__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_AvgDialog = readonly({
  AvgDialog_100303_Content_1 = {
    Text = "Huff... huff... No, that's not it... something still feels off..."
  },
  AvgDialog_100303_Content_10 = {
    Text = "Why is it that it's right in front of me, yet I still can't find it..."
  },
  AvgDialog_100303_Content_11 = {
    Text = "Don't worry, Pickman. Since the Muse has already told you, then the answer must be very close to you. Think carefully about what you might have missed."
  },
  AvgDialog_100303_Content_12 = {
    Text = "Before that, let's help you up first... Ouch..."
  },
  AvgDialog_100303_Content_13 = {
    Text = "You snatch your hand back. Inside his scalding body flows what feels like lava."
  },
  AvgDialog_100303_Content_14 = {
    Text = "As expected, it's Thais again causing trouble..."
  },
  AvgDialog_100303_Content_15 = {
    Text = "Thais... Ah! Right! How could I not think of that! How could I overlook it!!"
  },
  AvgDialog_100303_Content_16 = {
    Text = "He suddenly straightens up, his gaze, almost searing, fixing directly on you."
  },
  AvgDialog_100303_Content_17 = {
    Text = "The craziest desire... that's right! I see, I see..."
  },
  AvgDialog_100303_Content_18 = {
    Text = "He is so excited that he forgets to stand up, crawling toward you on all fours."
  },
  AvgDialog_100303_Content_19 = {
    Text = "Keeper, can you be my model once more? Please! This is the last time!"
  },
  AvgDialog_100303_Content_2 = {Text = "Pickman?"},
  AvgDialog_100303_Content_20 = {
    Text = "I know what you want to do, absolutely not..."
  },
  AvgDialog_100303_Content_21 = {
    Text = "Pickman's anxious and pleading red eyes flicker slightly in the dim light. You find your words of refusal can no longer be spoken."
  },
  AvgDialog_100303_Content_22 = {
    Text = "...Fine. If I'm just acting as your model. Should I still sit on that sofa?"
  },
  AvgDialog_100303_Content_23 = {
    Text = "No, no, Keeper! A painting like this can't be created in a studio!"
  },
  AvgDialog_100303_Content_24 = {Text = "..."},
  AvgDialog_100303_Content_25 = {
    Text = "Is this... the world in your painting?"
  },
  AvgDialog_100303_Content_26 = {
    Text = "That's right! It's the ghouls' carnival ritual!"
  },
  AvgDialog_100303_Content_27 = {
    Text = "I created it, but I never finished it. It lacks a pair of protagonists at its center. They represent the most primitive and wildest desires of this universe, the desires I have forgotten..."
  },
  AvgDialog_100303_Content_28 = {
    Text = "I haven't found a model sufficient to become the protagonist until now..."
  },
  AvgDialog_100303_Content_29 = {
    Text = "Pickman remains kneeling, dragging his knee closer to you."
  },
  AvgDialog_100303_Content_3 = {
    Text = "Pickman's dim studio is messier than before, with countless sheets of leather filled with colors and lines scattered randomly in every corner, as if experiencing a strange war."
  },
  AvgDialog_100303_Content_30 = {
    Text = "Please, Keeper... grant me the Muse!"
  },
  AvgDialog_100303_Content_31 = {
    Text = "You can make me do anything! PLEASE! Please help me complete this painting..."
  },
  AvgDialog_100303_Content_32 = {
    Text = "Without hesitating for long, you gently sigh and approach him."
  },
  AvgDialog_100303_Content_33 = {
    Text = "He raises his head and looks at you with wide eyes. Those eyes belong to a creature that is simultaneously greedy, yearning, obedient, and loyal—a beast or a devoted pet. He is pleading, begging for a command that will lead him to the Muse."
  },
  AvgDialog_100303_Content_34 = {
    Text = "Anything, huh... Then, I need to think carefully..."
  },
  AvgDialog_100303_Content_35 = {
    Text = "Your hand gently rests on Pickman's face. His hot breath lingers, but his body instantly becomes docile. You do not know if you are taming him or if he is melting you."
  },
  AvgDialog_100303_Content_36 = {
    Text = "The sounds of the ghouls begin to fade, replaced by the rough and primal voices of the protagonists, resonating throughout the world within the painting."
  },
  AvgDialog_100303_Content_37 = {
    Text = "That is the voice of the Muse."
  },
  AvgDialog_100303_Content_4 = {
    Text = "He, with disheveled clothes, kneels on both knees, frantically smearing on a blank sheet of paper, nearly tearing it apart. The splattered paint covers his body, resembling a devotee in the midst of a savage ritual."
  },
  AvgDialog_100303_Content_5 = {
    Text = "What is going on..."
  },
  AvgDialog_100303_Content_6 = {
    Text = "I heard it, Keeper! I heard the voice of the Muse calling! Right in my ear!"
  },
  AvgDialog_100303_Content_7 = {
    Text = "My eyes, my hands, my heart, every cell in my body trembles at the sound of it!"
  },
  AvgDialog_100303_Content_8 = {
    Text = "So close! I'm only one step away from the greatest art!"
  },
  AvgDialog_100303_Content_9 = {
    Text = "But I can't find it... slaughter, conquest, gluttony, greed, waste, void... I've depicted all the madness, but I still haven't found it..."
  },
  AvgDialog_100588_Content_1 = {
    Text = "A pitch-black figure gradually appears before you."
  },
  AvgDialog_100588_Content_2 = {
    Text = "[Attack]???"
  },
  AvgDialog_100588_Content_3 = {
    Text = "You dealt 677 damage! You feel you have dealt a total of 27,188 damage to Him.\nEveryone has dealt a total of 14,636,643,707 damage to Him, but He still hasn’t fallen."
  },
  AvgDialog_100588_Content_4 = {Text = "[Continue]"},
  AvgDialog_100588_Content_5 = {
    Text = [[
You felt that you had been here before...
Under the watchful gaze of the dark figure, your consciousness gradually blurred.]]
  },
  AvgDialog_100588_Content_6 = {Text = "[Sleep]"},
  AvgDialog_100629_Content_1 = {
    Text = "Not long after, this world was no longer plagued by erosion; humanity developed rapidly, and later the Masagog University intercepted a train in the starry sky..."
  },
  AvgDialog_10120_Content_1 = {
    Text = "Protect the command device in your hand and beware of Dissolution! It will be essential in the upcoming battle!"
  },
  AvgDialog_10120_Content_2 = {
    Text = "Hold down a <Yellow:Command Card>, drag it upwards, then release it to command me in combat."
  },
  AvgDialog_10121_Content_1 = {
    Text = "<Yellow:Silver>? Didn't expect to find any here..."
  },
  AvgDialog_10121_Content_2 = {
    Text = "Whether it's crafting Silver Keys, linking Awakeners, or providing spiritual energy... it all relies on <Yellow:Silver>."
  },
  AvgDialog_10121_Content_3 = {
    Text = "Even trace amounts of <Yellow:Silver> hold extraordinary value for Mythag's research. Gather as much as you can."
  },
  AvgDialog_10122_Content_1 = {
    Text = "We can't afford to stall for much longer. Let's end this in one fell swoop."
  },
  AvgDialog_10122_Content_2 = {
    Text = "This is <Yellow:\"Queen's Sword\">, a technique I've practiced since childhood. May it strike down our foe!"
  },
  AvgDialog_10123_Content_1 = {
    Text = "You slip through a hidden door beneath the Clock Tower, stepping into a concealed passage."
  },
  AvgDialog_10123_Content_10 = {Text = "..."},
  AvgDialog_10123_Content_11 = {
    Text = "The great gate slowly parts, offering your first glimpse into the forbidden sanctum."
  },
  AvgDialog_10123_Content_13 = {
    Text = "Their luminous upper body floats above the black mire, the inky darkness serving only to accentuate Their blinding purity."
  },
  AvgDialog_10123_Content_14 = {
    Text = "Mesmerized, you gaze upon the inhuman entity; Their outline briefly superimposing with that of the young woman you saw while in a trance back at the Keygrave."
  },
  AvgDialog_10123_Content_15 = {
    Text = "They have no face, yet Their stance radiates profound compassion."
  },
  AvgDialog_10123_Content_16 = {
    Text = "The Supreme. The Purest. The Noblest. The Fairest."
  },
  AvgDialog_10123_Content_17 = {
    Text = "<Shake:You... are here...>"
  },
  AvgDialog_10123_Content_18 = {
    Text = "The pale monster emits a hoarse cry; roar and wail entwined."
  },
  AvgDialog_10123_Content_19 = {
    Text = "It was most definitely not human speech, yet you comprehend Their meaning perfectly."
  },
  AvgDialog_10123_Content_2 = {
    Text = "Doll marches forward, her feet clanging against the metal walkway with each step."
  },
  AvgDialog_10123_Content_20 = {
    Text = "Your vision blurs and unexpectedly, your eyes sting. Warm rivulets trace paths down your cheeks."
  },
  AvgDialog_10123_Content_21 = {
    Text = "Are these tears? But why? What is this ache constricting your chest?"
  },
  AvgDialog_10123_Content_22 = {
    Text = "...<Yellow:Tawil>?"
  },
  AvgDialog_10123_Content_23 = {
    Text = "The name muttered by Doll causes Ramona's expression to shift."
  },
  AvgDialog_10123_Content_24 = {
    Text = "Tawil? The Awakener Tawil, one of the founders?"
  },
  AvgDialog_10123_Content_25 = {
    Text = "You remember it too. <Blue:The History of Mythag> lists this name alongside two others."
  },
  AvgDialog_10123_Content_26 = {
    Text = "In the year AF 90, <Blue:Ward Philips>, <Blue:Khlarcus>, and <Blue:Tawil> founded <Blue:Mythag College>."
  },
  AvgDialog_10123_Content_27 = {
    Text = "That was where you stood now. The predecessor to the current day <Blue:Mythag University>."
  },
  AvgDialog_10123_Content_28 = {Text = "Keeper."},
  AvgDialog_10123_Content_29 = {Text = "I'm here."},
  AvgDialog_10123_Content_3 = {
    Text = "A secret passage below the clock tower? I had never heard of it before..."
  },
  AvgDialog_10123_Content_30 = {
    Text = "The fact that Tawil has not expelled you yet... it can only mean that your fate is now linked to Mythag's."
  },
  AvgDialog_10123_Content_31 = {
    Text = "Therefore, you've earned the right to hear this."
  },
  AvgDialog_10123_Content_32 = {
    Text = "This is the deepest secret of Mythag University. Tawil, one of our three founders, is neither human nor Awakener."
  },
  AvgDialog_10123_Content_33 = {
    Text = "They're an extradimensional entity initially perceived as mere whispers by Phillips, the first Headmaster."
  },
  AvgDialog_10123_Content_34 = {
    Text = "Contrary to popular belief, Tawil isn't an Awakener. Silver refinement and <Yellow:postmortem Awakening of individuals resonant with the Higher Will> were developed under Their guidance."
  },
  AvgDialog_10123_Content_35 = {
    Text = "They foretold the impending Dissolution, shared the first \"Truth,\" then fell dormant after establishing Mythag College."
  },
  AvgDialog_10123_Content_36 = {
    Text = "Phillips' records suggest that Tawil opted for this \"Nonexistent\" state to evade observation."
  },
  AvgDialog_10123_Content_37 = {
    Text = "Only when the \"Variable\" emerges will They awaken—"
  },
  AvgDialog_10123_Content_38 = {Text = "Look!"},
  AvgDialog_10123_Content_39 = {
    Text = "As if heralding disaster, \"Tawil\" let out a eardrum-piercing shriek."
  },
  AvgDialog_10123_Content_4 = {
    Text = "If it was common knowledge, it would hardly qualify as a secret passage. This tunnel leads to the <Yellow:Black Pool>... the foundation of Mythag."
  },
  AvgDialog_10123_Content_40 = {
    Text = "With the trembling of a hatchling breaking out from its shell, six magnificent silver wings burst forth from Their body."
  },
  AvgDialog_10123_Content_41 = {
    Text = "Silver-like liquid drips steadily from each wingtip, creating a soft percussion as it hits the Black Pool below."
  },
  AvgDialog_10123_Content_42 = {
    Text = "As the glinting substance meets the pitch-black of the pool, it churns violently. From its depths, grotesque Dissolutes emerge."
  },
  AvgDialog_10123_Content_43 = {
    Text = "The incomprehensible abominations scatter; some charging at your group, while the rest spill toward the Clock Tower plaza."
  },
  AvgDialog_10123_Content_44 = {
    Text = "<Shake:I have... finally... found... you...>"
  },
  AvgDialog_10123_Content_45 = {
    Text = "We must stop Them! It's the only way to prevent more of those monsters from coming out!"
  },
  AvgDialog_10123_Content_5 = {
    Text = "Without the giant Silver artifact known as the <Yellow:Core> at the bottom of the Black Pool, our Awakener technology would regress decades. Human spirits alone are too fragile to sustain them."
  },
  AvgDialog_10123_Content_6 = {
    Text = "So the restriction on unlinked Awakeners... it's to protect us from succumbing to madness?"
  },
  AvgDialog_10123_Content_7 = {
    Text = "That's not entirely true. If all Awakeners were as manageable as you, Ogier, my job would be far simpler."
  },
  AvgDialog_10123_Content_8 = {
    Text = "Alright, we've arrived."
  },
  AvgDialog_10123_Content_9 = {
    Text = "As she speaks, Doll presses an inconspicuous button on the wall. A sharp ding rings out as the doorway slides open, revealing a cramped and dimly lit chamber beyond."
  },
  AvgDialog_10124_Content_1 = {
    Text = "Looks like you've found your rhythm. The command is yours, Keeper!"
  },
  AvgDialog_10125_Content_1 = {
    Text = "Phew. Sorry, there's no time for you to acclimate to all of this properly."
  },
  AvgDialog_10125_Content_10 = {
    Text = "Ramona looks terrified; you've never seen her this flustered."
  },
  AvgDialog_10125_Content_11 = {
    Text = "The girl, bombarded with questions, speaks in a trembling voice, her fatigue evident."
  },
  AvgDialog_10125_Content_12 = {
    Text = "You recognize her—Professor Doll, belonging to the <Blue:Awakening Research Institute> and infamously difficult to communicate with. In other words, a non-combatant."
  },
  AvgDialog_10125_Content_13 = {
    Text = "Obviously. Did you think I came here for a leisurely stroll?"
  },
  AvgDialog_10125_Content_14 = {
    Text = "She closes her eyes, quickly recomposing herself."
  },
  AvgDialog_10125_Content_15 = {
    Text = "The Keygrave is compromised as well? We're near the rear exit. You two should evacuate immediately."
  },
  AvgDialog_10125_Content_16 = {
    Text = "We can help! %player% can establish a link with us and take command—"
  },
  AvgDialog_10125_Content_17 = {
    Text = "Ramona. This is our duty. %player% is still a freshman, freshly graduated from prep school."
  },
  AvgDialog_10125_Content_18 = {
    Text = "%player% has already linked with me, and I know that {Male=he,Female=she}'s up to the task. I believe in {Male=him,Female=her}!"
  },
  AvgDialog_10125_Content_19 = {
    Text = "Doll scrutinizes you, then turns to Ramona with a stern expression."
  },
  AvgDialog_10125_Content_2 = {
    Text = "These Mutants reached the Keygrave before the alarm sounded. The <Blue:Mist Barrier> around Mythag must be down."
  },
  AvgDialog_10125_Content_20 = {
    Text = "If memory serves, the oath ceremony was interrupted. {Male=He,Female=She} hasn't received {Male=his,Female=her} Silver Key yet, correct?"
  },
  AvgDialog_10125_Content_21 = {
    Text = "We'll be delving into a <Bold:restricted> area. I'd expect someone raised at Mythag to understand what that means."
  },
  AvgDialog_10125_Content_22 = {
    Text = "It's an emergency! We have no choice, right? Besides, %player% isn't just any freshman. {Male=He's,Female=She's} our only Keeper."
  },
  AvgDialog_10125_Content_23 = {
    Text = "Don't you remember the <Yellow:Yakutsk Explosion> a year ago? If not for {Male=him,Female=her} single-handedly linking all the Awakeners back then, I wouldn't be here having this discussion with you right now."
  },
  AvgDialog_10125_Content_24 = {
    Text = "The pink-haired girl doesn't answer, and instead, she turns to you."
  },
  AvgDialog_10125_Content_25 = {
    Text = "I know you caught a glimpse of what lies beyond the <Yellow:Gate>; but reality, be it Mythag's foundation or the fate of the world, may not be as you idealize."
  },
  AvgDialog_10125_Content_26 = {
    Text = "We're combating a phenomenon that unmakes existence itself. Once contaminated by <Yellow:Dissolution>, everything that is <Bold:you> will vanish entirely from this world."
  },
  AvgDialog_10125_Content_27 = {
    Text = "Your tombstone inscription and your legacy will be reduced to a sludge of nothingness, forgotten by all."
  },
  AvgDialog_10125_Content_28 = {
    Text = "Answer me. Are you truly ready for this?"
  },
  AvgDialog_10125_Content_29 = {
    Text = "Doll's icy gaze meets yours, her voice flat."
  },
  AvgDialog_10125_Content_3 = {
    Text = "We informed <Blue:William> about today's ceremony, but no reinforcements came to our aid. The bell... we should regroup and <Yellow:eliminate the source of the anomaly>!"
  },
  AvgDialog_10125_Content_30 = {
    Text = "Her face betrays nothing, but deep within her frosty pupils, you glimpse a blazing fire."
  },
  AvgDialog_10125_Content_31 = {
    Text = "Your answer is—"
  },
  AvgDialog_10125_Content_32 = {
    Text = "My tombstone now stands as a part of the Keygrave."
  },
  AvgDialog_10125_Content_33 = {
    Text = "You're a member of Mythag. Perhaps you already were back in Yakutsk."
  },
  AvgDialog_10125_Content_34 = {
    Text = "There are things only I can accomplish."
  },
  AvgDialog_10125_Content_35 = {
    Text = "The decision may be hasty, but can one ever be truly prepared for everything in life?"
  },
  AvgDialog_10125_Content_36 = {Text = "Very well."},
  AvgDialog_10125_Content_37 = {
    Text = "By the authority of Mythag's 6th Headmaster, <Blue:Oliver Elsie>, I hereby confer Silver Key K-0617 upon you."
  },
  AvgDialog_10125_Content_39 = {
    Text = "Doll retrieves the Silver Key from an ornate case, placing it on your chest. It glows faintly, flooding you with a vague sense of familiarity."
  },
  AvgDialog_10125_Content_4 = {
    Text = "What is that?!"
  },
  AvgDialog_10125_Content_40 = {
    Text = "Henceforth, you stand as a Keeper among the myriad of Mythag's students and scholars."
  },
  AvgDialog_10125_Content_41 = {Text = "..."},
  AvgDialog_10125_Content_42 = {
    Text = "Now then, establish a link with me."
  },
  AvgDialog_10125_Content_43 = {
    Text = "You follow your training and cautiously activate the Silver Key. Silver light flickers as invisible threads tether your senses to Doll's."
  },
  AvgDialog_10125_Content_44 = {
    Text = "Countless images surge through the connection, electric and overwhelming. Your heart pounds violently as you struggle to stay upright."
  },
  AvgDialog_10125_Content_45 = {
    Text = "Doll, you..."
  },
  AvgDialog_10125_Content_46 = {
    Text = "Your timing is adequate, Keeper. Ogier and I... we were at our limit."
  },
  AvgDialog_10125_Content_47 = {
    Text = "Stay here and rest. Ramona and I will join the battle and support Ogier."
  },
  AvgDialog_10125_Content_48 = {
    Text = "Composure, please. You cannot compensate for Ramona's injuries with foolhardiness. She's currently not fit for combat."
  },
  AvgDialog_10125_Content_49 = {
    Text = "That kid, Ogier, can hold on a little longer. Follow me first."
  },
  AvgDialog_10125_Content_6 = {
    Text = "In the periphery of your vision, a blond youth raises a massive black shield, barely fending off the assault of a dual-wielding swordswoman."
  },
  AvgDialog_10125_Content_7 = {
    Text = "He guards a pink-haired girl behind him, each deflected attack pushing him back another step."
  },
  AvgDialog_10125_Content_8 = {
    Text = "Wait, the assailant... is that <Yellow:Awakener> Lotan?!"
  },
  AvgDialog_10125_Content_9 = {
    Text = "Doll? Is the <Blue:Clock Tower> compromised?!"
  },
  AvgDialog_10126_Content_1 = {
    Text = "When your HP drops to 0, your mind will struggle to continue investigating a <Yellow:Domain>. For your safety, you'll be evacuated."
  },
  AvgDialog_10126_Content_2 = {
    Text = "The situation is urgent! I've adjusted the device's power output to match your vitals, fully charging up our Aliemus!"
  },
  AvgDialog_10126_Content_3 = {
    Text = "As it is, we have but one recourse left... it might be dangerous, but we're out of options. Now, unleash my Exalt to end this battle!"
  },
  AvgDialog_10127_Content_1 = {
    Text = "How warm... the connection is perfect. Your spirit and life force have never shone brighter."
  },
  AvgDialog_10127_Content_2 = {
    Text = "As <Yellow:the one and only> Keeper in this world, you mustn't falter. We're counting on you to investigate and document all history lost to Dissolution."
  },
  AvgDialog_10127_Content_3 = {
    Text = "The worry in her eyes fades as Ramona offers a reassuring half-smile."
  },
  AvgDialog_10127_Content_4 = {
    Text = "The sound of pattering rain fills the world."
  },
  AvgDialog_10127_Content_5 = {
    Text = "Yet with the fall of a single raindrop, <Red:unease, pain, and suffocation> suddenly flood your chest."
  },
  AvgDialog_10127_Content_7 = {Text = "Ramona!"},
  AvgDialog_10127_Content_9 = {
    Text = "The bell tolls."
  },
  AvgDialog_10128_Content_1 = {
    Text = "Watch out, the enemy is going on the offensive!"
  },
  AvgDialog_10128_Content_2 = {
    Text = "What's all that fuss about? I'm here with you. Keeper, let me perform <Yellow:\"Outer Surgery\">."
  },
  AvgDialog_10129_Content_1 = {
    Text = "Activate the Silver Key, %player%."
  },
  AvgDialog_10129_Content_2 = {
    Text = "The Silver Key flickers. An illusory scene coalesces into existence, overlapping with reality before your very eyes."
  },
  AvgDialog_10129_Content_3 = {
    Text = "Feeling dazed, your thoughts slow to a crawl. A siren wails inside your skull. Doll's voice fades into the distance..."
  },
  AvgDialog_10129_Content_4 = {
    Text = "You fight to steady your thoughts, trying your hardest to focus on Doll's words despite the noise ringing in your mind."
  },
  AvgDialog_10129_Content_5 = {
    Text = "Can you perceive it? Before you is what we call a Domain. An amalgam of <Yellow:Dream> and <Yellow:Reality>."
  },
  AvgDialog_10129_Content_6 = {
    Text = "Mythag has projected <Blue:Junctions> to stabilize the Investigators' fraying minds and tend to the Awakeners' wounds."
  },
  AvgDialog_10129_Content_7 = {
    Text = "However, human influence falters within a Domain. We cannot be sure where those <Blue:Junctions> are located. It's adapt or perish."
  },
  AvgDialog_10129_Content_8 = {
    Text = "Now, head to the nearest <Blue:Junction> so that you may heal Ramona's wounds."
  },
  AvgDialog_10130_Content_10 = {
    Text = "As long as our tombstones stand, we're protected against @2's Dissolution."
  },
  AvgDialog_10130_Content_11 = {
    Text = "Her gentle voice, interwoven with distorted screeches, echoes in your mind."
  },
  AvgDialog_10130_Content_12 = {
    Text = "As your assistant, I'll be with you till the very end... <Yellow:May the Silver Key light your path.>"
  },
  AvgDialog_10130_Content_13 = {
    Text = "Are you all right, %player%? You're looking a bit pale. Should we drop by the infirmary?"
  },
  AvgDialog_10130_Content_14 = {
    Text = "Her crisp voice clears your mind, and the dizziness fades away."
  },
  AvgDialog_10130_Content_15 = {
    Text = "Don't worry, I was just a little dazed... but I'm feeling better already."
  },
  AvgDialog_10130_Content_16 = {
    Text = "Is that so? Just to be safe, why not establish a link with me? As your assistant and partner, it's my responsibility to monitor your condition."
  },
  AvgDialog_10130_Content_17 = {
    Text = "Right now? Out here?"
  },
  AvgDialog_10130_Content_18 = {
    Text = "It's maybe a little earlier than planned, but it shouldn't matter, right?"
  },
  AvgDialog_10130_Content_19 = {
    Text = "Besides, I've been looking forward to this day for over a year now."
  },
  AvgDialog_10130_Content_2 = {
    Text = "Welcome to Mythag University, %player%."
  },
  AvgDialog_10130_Content_21 = {
    Text = "Raindrops slip into your gloves, wetting your fingertips. A faint current seeps through the material, flowing secretly between your skin and hers."
  },
  AvgDialog_10130_Content_22 = {
    Text = "Inexplicable emotions surge through your nerves—joy, excitement, unease, and..."
  },
  AvgDialog_10130_Content_23 = {
    Text = "...<Yellow:hope>."
  },
  AvgDialog_10130_Content_3 = {
    Text = "Or rather, welcome back to the world beyond the veil."
  },
  AvgDialog_10130_Content_4 = {Text = "I'm home."},
  AvgDialog_10130_Content_5 = {
    Text = "Everyone's been waiting for you. In a couple of days, William will assign us our first <Yellow:Cataclysm Investigation Mission>."
  },
  AvgDialog_10130_Content_6 = {
    Text = "He won't go easy on you, even if you're our once-in-a-century Keeper."
  },
  AvgDialog_10130_Content_7 = {
    Text = "Just promise me your @1 field work won't rely too much on me as your <Blue:assistant>; or at least, not as much as you did for your Calculus course."
  },
  AvgDialog_10130_Content_8 = {
    Text = "Never expected to attend my own funeral."
  },
  AvgDialog_10130_Content_9 = {
    Text = "Embracing our mortality banishes the fear of death."
  },
  AvgDialog_10131_Content_1 = {
    Text = "Ogier and I are joining the battle."
  },
  AvgDialog_10131_Content_2 = {
    Text = "I can sense through the link that neither of you are in good condition."
  },
  AvgDialog_10131_Content_3 = {
    Text = "It's okay, Keeper. It's a knight's duty to protect others. I can still hold on!"
  },
  AvgDialog_10131_Content_4 = {
    Text = "Worry not. With your assistance, we won't lose control and can make the most of our Aliemus."
  },
  AvgDialog_10131_Content_5 = {
    Text = "Once I've accumulated enough Aliemus, I'll be able to fully recuperate my strength."
  },
  AvgDialog_10131_Content_6 = {
    Text = "Your hesitation is misplaced, Keeper. We are counting on you to break through the blockade."
  },
  AvgDialog_10131_Content_7 = {
    Text = "Let me witness for myself the worth of this prodigy Mythag stakes its future upon!"
  },
  AvgDialog_10132_Content_1 = {
    Text = "Hmph, you think you have what it takes to destroy this planet?"
  },
  AvgDialog_10132_Content_2 = {
    Text = "Far from enough! Bring it on! Fight me with everything you've got!"
  },
  AvgDialog_10133_Content_1 = {
    Text = "Is it... over...?"
  },
  AvgDialog_10133_Content_10 = {
    Text = "Her finger daintily taps your Silver Key."
  },
  AvgDialog_10133_Content_11 = {
    Text = "The Key faintly shines in response."
  },
  AvgDialog_10133_Content_12 = {
    Text = "You are the Variable, the answer to both the beginning and the end."
  },
  AvgDialog_10133_Content_13 = {
    Text = "Hopefully, you will become the turning point..."
  },
  AvgDialog_10133_Content_15 = {
    Text = "The pale six-winged monster. The mud creatures. The twisted Awakeners..."
  },
  AvgDialog_10133_Content_16 = {
    Text = "One by one, they melt into the Black Pool before vanishing completely. The woman with a vacant expression begins to float upward."
  },
  AvgDialog_10133_Content_17 = {
    Text = "Deaf to Ramona and Doll's calls, you clutch the Silver Key and stare up at \"Tawil,\" already being engulfed by the \"Gate\" above."
  },
  AvgDialog_10133_Content_18 = {
    Text = "You know that face. The indifference. The brows. The lips. They all mirror Ramona's appearance."
  },
  AvgDialog_10133_Content_19 = {
    Text = "They look exactly the same."
  },
  AvgDialog_10133_Content_2 = {
    Text = "\"Tawil\" remains standing in place, though no longer with the same composure."
  },
  AvgDialog_10133_Content_20 = {
    Text = [[
Two Days Later

Keygrave]]
  },
  AvgDialog_10133_Content_21 = {
    Text = "...We of Mythag University are pioneers in the battle against Dissolution. We stand as humanity's last line of defense."
  },
  AvgDialog_10133_Content_22 = {
    Text = "For three centuries we've been the bulwark secretly protecting our civilization's future. The cost... has been severe."
  },
  AvgDialog_10133_Content_23 = {
    Text = "These graves were dug in advance. We honor all Mythag personnel, professors and students alike, who chose martyrdom over retreat."
  },
  AvgDialog_10133_Content_24 = {
    Text = "The speech continues. Czort closes her eyes and sighs, her breath a white mist dissipating in the rain."
  },
  AvgDialog_10133_Content_25 = {
    Text = "...I believe you understand the gravity of these words better than any other initiate."
  },
  AvgDialog_10133_Content_26 = {
    Text = "Over the centuries, The Black Pool has birthed Silver Cores and Mutants many times before... but this latest incident dwarfs them all."
  },
  AvgDialog_10133_Content_27 = {
    Text = "Too many never came home."
  },
  AvgDialog_10133_Content_28 = {
    Text = "Ms. Czort is the Acting Dean of Mythag's Department of Biological Studies. Legend had it that she could see otherworldly beings. The former dean's star pupil."
  },
  AvgDialog_10133_Content_29 = {
    Text = "Dissolution brings only chaos, madness, and death. This is an inevitable burden we must bear together."
  },
  AvgDialog_10133_Content_3 = {
    Text = "Before anyone has a chance to react, They unfurl their wings, and lunge at Ramona."
  },
  AvgDialog_10133_Content_30 = {
    Text = "You understand the meaning behind Czort's words. There is no one buried in the grave before you."
  },
  AvgDialog_10133_Content_31 = {
    Text = "Black slime slowly oozes down the tombstone."
  },
  AvgDialog_10133_Content_32 = {Text = "..."},
  AvgDialog_10133_Content_33 = {
    Text = "After the ceremony, Lord Dexter invites you to his office."
  },
  AvgDialog_10133_Content_34 = {
    Text = "\"Dexter\" rings a familiar bell; it's Ramona's surname. He's your professor and her adoptive father."
  },
  AvgDialog_10133_Content_35 = {
    Text = "About this section in your report... I have a favor to ask of you."
  },
  AvgDialog_10133_Content_36 = {
    Text = "Regarding Tawil's appearance... could you keep that from Ramona for now?"
  },
  AvgDialog_10133_Content_37 = {Text = "Why?"},
  AvgDialog_10133_Content_38 = {
    Text = "How should I put it... the causality involved is quite complicated. Not something I can sum up quickly."
  },
  AvgDialog_10133_Content_39 = {
    Text = "But I will tell her eventually; just not yet."
  },
  AvgDialog_10133_Content_4 = {
    Text = "Time comes to a halt."
  },
  AvgDialog_10133_Content_40 = {
    Text = "This is unrelated to Mythag's confidentiality protocols, but rather a request from a father who wishes to protect his daughter."
  },
  AvgDialog_10133_Content_41 = {
    Text = "Please, give me some time, alright?"
  },
  AvgDialog_10133_Content_42 = {
    Text = "Although you wish to know the truth, you nod in agreement compliantly."
  },
  AvgDialog_10133_Content_43 = {
    Text = "Thank you for understanding. Speaking of which... I just got my hands on a couple of bottles of royal blend whiskey."
  },
  AvgDialog_10133_Content_44 = {
    Text = "Here, take one. Invite Ramona for a drink, and savor the taste of adulthood. Consider it your special initiation rite, eh?"
  },
  AvgDialog_10133_Content_45 = {
    Text = "Respectfully, Lord Dexter, rest is a luxury we can't afford. The Dissolution won't pause for our convenience."
  },
  AvgDialog_10133_Content_46 = {
    Text = "Alas, William has found his way here. Sorry kid, you're on your own now."
  },
  AvgDialog_10133_Content_47 = {
    Text = "Your dossier is prepared. The time has come, our new Keeper. Report for duty."
  },
  AvgDialog_10133_Content_48 = {
    Text = "May the Silver Key light your path."
  },
  AvgDialog_10133_Content_5 = {
    Text = "You unleashed every ounce of speed you possessed, barely managing to intercept Their path."
  },
  AvgDialog_10133_Content_6 = {
    Text = "The pale monster stares at you."
  },
  AvgDialog_10133_Content_7 = {
    Text = "Faceless. Silent."
  },
  AvgDialog_10133_Content_9 = {
    Text = "A woman's face comes into view, cold and expressionless."
  },
  AvgDialog_10134_Content_1 = {
    Text = "Hey you! Quit dawdling and use my <Yellow:\"Blade of Defiance\"> already."
  },
  AvgDialog_10134_Content_2 = {
    Text = "If I may interject, Keeper. First, utilize the \"Strike\" Command Cards to reduce the Arithmetica Cost of <Yellow:\"Blade of Defiance\">."
  },
  AvgDialog_10134_Content_3 = {
    Text = "The right command sequence can optimize our effectiveness in battle. Every choice matters. Think tactically."
  },
  AvgDialog_10135_Content_1 = {
    Text = "Stay back! Please... my shield is beginning to falter!"
  },
  AvgDialog_10135_Content_10 = {
    Text = "You know that I'm the only one who can do this."
  },
  AvgDialog_10135_Content_11 = {
    Text = "When praising me, you refer to me as a \"once-in-a-century prodigy\", but in times of crisis, I'm relegated to but a figurehead. That's hardly appropriate."
  },
  AvgDialog_10135_Content_12 = {
    Text = "Some risks can't be avoided."
  },
  AvgDialog_10135_Content_13 = {
    Text = "We have no choice. With so many losing control, either we fight the ones stricken with madness or get consumed by it."
  },
  AvgDialog_10135_Content_14 = {
    Text = "Besides, we can't possibly break through the blockade around the Clock Tower by ourselves. We'll need all the help we can get... we must find a way to command the Awakeners."
  },
  AvgDialog_10135_Content_15 = {
    Text = "Ramona, I need your support."
  },
  AvgDialog_10135_Content_16 = {
    Text = "Since you've made up your mind... as your partner, I won't try to stop you."
  },
  AvgDialog_10135_Content_17 = {
    Text = "Ramona, ready for battle!"
  },
  AvgDialog_10135_Content_2 = {
    Text = "With a clang, Lotan's twin swords shatter his shield of black sludge once again."
  },
  AvgDialog_10135_Content_3 = {
    Text = "Pathetic! Utterly pathetic! Battling this weakling won't satisfy me! Give me a real fight!"
  },
  AvgDialog_10135_Content_4 = {
    Text = "Awakener Lotan swings her twin blades, relentlessly assaulting Ogier. The sheer power behind each strike makes it clear—she has lost control."
  },
  AvgDialog_10135_Content_5 = {
    Text = "Given the situation, we must..."
  },
  AvgDialog_10135_Content_6 = {
    Text = "Ramona, help me subdue Lotan!"
  },
  AvgDialog_10135_Content_7 = {
    Text = "You can't possibly mean to..."
  },
  AvgDialog_10135_Content_8 = {
    Text = "I'll establish a link with her!"
  },
  AvgDialog_10135_Content_9 = {
    Text = "Don't be foolish! An Awakener's breakdown resonates through the link! Even you—"
  },
  AvgDialog_10136_Content_1 = {
    Text = "This is... Lotan's prided technique <Yellow:\"Blade of Defiance\">, capable of launching multiple attacks in an instant!"
  },
  AvgDialog_10136_Content_2 = {
    Text = "To counter her move... employ my <Yellow:\"Assault Thesis\"> . Better safe than sorry."
  },
  AvgDialog_10137_Content_1 = {
    Text = "You can't stop me! Shameless humans..."
  },
  AvgDialog_10137_Content_2 = {
    Text = "Your fingers brush the Silver Key. It thrums faintly, urging you to resonate with Lotan."
  },
  AvgDialog_10137_Content_4 = {
    Text = "<Shake:Had I known this would happen... I would have never made that pact...>"
  },
  AvgDialog_10137_Content_5 = {
    Text = "Ramona approaches Lotan, holding out her hand."
  },
  AvgDialog_10137_Content_6 = {
    Text = "I know that after your awakening, Mythag promised to fight alongside you. To fight together till the planet's end."
  },
  AvgDialog_10137_Content_7 = {
    Text = "We never intended to break our promise. Not for the past three hundred years, nor the three hundred to come."
  },
  AvgDialog_10137_Content_8 = {
    Text = "Lotan, the fierce battle you crave is within your grasp."
  },
  AvgDialog_10138_Content_1 = {
    Text = "Stay on your toes, the enemy's about to attack. That much damage could kill me!"
  },
  AvgDialog_10138_Content_2 = {
    Text = "I trust that you'll make the right decision. For this turn, I suggest playing the <Yellow:\"Defense\"> card."
  },
  AvgDialog_10139_Content_1 = {
    Text = "Thank you, Keeper. You've saved me once again. If not for the link we shared, I'd be in serious trouble right now."
  },
  AvgDialog_10139_Content_2 = {
    Text = "Save that for later. Now is not the time!"
  },
  AvgDialog_10139_Content_3 = {
    Text = "The pitch-black anomaly spreads around you. Your classmates' screams echo in your ears, as they dissolve into black sludge one by one."
  },
  AvgDialog_10139_Content_4 = {
    Text = "The Silver Key is communicating the enemy's <Yellow:intent> to us through our link. Watch out, it's about to attack!"
  },
  AvgDialog_10140_Content_1 = {
    Text = "Do you sense the Aliemus coursing through me, Keeper? Without your guidance, I'd be as mad as Lotan."
  },
  AvgDialog_10140_Content_2 = {
    Text = "However, we can now put it to good use."
  },
  AvgDialog_10140_Content_3 = {
    Text = "Focus on the Aliemus current... yes, it should be on the <Blue:top left corner> of the Command Device."
  },
  AvgDialog_10140_Content_4 = {
    Text = "Unleash my Exalt and enact my <Yellow:\"Mundus Decree\">! In the fight against Dissolution, <Yellow:we must stay sharp to effectively counter the enemy>."
  },
  AvgDialog_10141_Content_1 = {
    Text = "Damn it, Lotan is about to unleash her own <Yellow:Exalt>... these Command Cards won't suffice..."
  },
  AvgDialog_10141_Content_2 = {
    Text = "The Silver Key is bound to your spirit; as such, your memories and insight uniquely shape its power."
  },
  AvgDialog_10141_Content_3 = {
    Text = "Look toward the <Blue:bottom left corner> of the Command Device. The Silver Key is brimming with energy... you now have access to your <Yellow:Posse>!"
  },
  AvgDialog_10141_Content_4 = {
    Text = "Grip the Silver Key and chant the incantation... activate <Yellow:Posse>, and grant me more tactical space!"
  },
  AvgDialog_10142_Content_2 = {
    Text = "Stay focused, <Yellow:Keeper>. The ceremony isn't over yet. You're next in line for a Silver Key."
  },
  AvgDialog_10142_Content_3 = {
    Text = "Erect your tombstone, and devote your life to the fight against <Yellow:Dissolution>. This Mythag tradition marks your graduation from preparatory studies, and the beginning of your tenure as an Investigator."
  },
  AvgDialog_10142_Content_4 = {
    Text = "Ready? Then engrave your name. Make it official."
  },
  AvgDialog_116003_Content_1 = {
    Text = "As the drawing of your House-Tree-Person drawing shatters, everything around you melts away in distortion."
  },
  AvgDialog_116003_Content_10 = {
    Text = "But I don't want this to be just a dream."
  },
  AvgDialog_116003_Content_11 = {
    Text = "I want to return to Mythag and see them again."
  },
  AvgDialog_116003_Content_12 = {
    Text = "...An expected answer."
  },
  AvgDialog_116003_Content_13 = {
    Text = "But this time, after you showed your determination, I can finally rest assured."
  },
  AvgDialog_116003_Content_14 = {
    Text = "%player%, your will is more resilient and stronger than I imagined... strong enough to confront Him and the chaos and madness of this world."
  },
  AvgDialog_116003_Content_15 = {
    Text = "You shook your head, gazing at Clementine in the beautiful dream that was about to shatter completely."
  },
  AvgDialog_116003_Content_16 = {
    Text = "No, you're wrong. A person's will has its limits."
  },
  AvgDialog_116003_Content_17 = {
    Text = "The reason I have been able to hold on until now is that everyone in Mythag supports me."
  },
  AvgDialog_116003_Content_18 = {
    Text = "They from \"that world\" have jointly built this beautiful dream for you, and you are determined to turn this dream into reality in this world."
  },
  AvgDialog_116003_Content_19 = {
    Text = "Hearing your words and seeing your serious expression, Clementine smiled, revealing a relaxed smile."
  },
  AvgDialog_116003_Content_2 = {
    Text = "You shattered your own beautiful dream."
  },
  AvgDialog_116003_Content_20 = {
    Text = "Yes, you still have \"them,\" and Tawil... and me."
  },
  AvgDialog_116003_Content_21 = {
    Text = "That's right. I have never been alone."
  },
  AvgDialog_116003_Content_22 = {
    Text = "In the constantly dissolving scenery, a shriek echoed, which was Tawil's response to you.\n She has always been there."
  },
  AvgDialog_116003_Content_23 = {
    Text = "So now, %player%, your beautiful dream has truly come to an end."
  },
  AvgDialog_116003_Content_24 = {
    Text = "As a thank you for your cooperation in this healing session, I am giving you a small gift. I hope you like it."
  },
  AvgDialog_116003_Content_25 = {
    Text = "With Clementine's last words, the dream shattered completely—"
  },
  AvgDialog_116003_Content_26 = {
    Text = "The sky with the black sun hangs high before you, bringing gray mist and the cruelty of this world."
  },
  AvgDialog_116003_Content_27 = {
    Text = [[
And in your palm lies a photo.
A photo taken in the "false beautiful dream," one that should not exist in the cruel reality.]]
  },
  AvgDialog_116003_Content_28 = {
    Text = "By the seaside, volleyball, revelry, the only thing different from my memories is Ramona."
  },
  AvgDialog_116003_Content_29 = {
    Text = "The familiar visage smiles serenely, as if transcending time and space to gaze into yours.\n It feels as if it's right before you."
  },
  AvgDialog_116003_Content_3 = {
    Text = "Since I decided to use their strength to build this dream, I knew that this day would eventually come."
  },
  AvgDialog_116003_Content_30 = {
    Text = "<Small:Ramona...>"
  },
  AvgDialog_116003_Content_31 = {
    Text = "You place your hand on the photo, a mix of emotions and confusion flooding your heart."
  },
  AvgDialog_116003_Content_32 = {
    Text = "<Shake:Why is it Ramona...>"
  },
  AvgDialog_116003_Content_33 = {
    Text = [[
Your questions go unanswered.
In the world shrouded in gray mist, only the silent black sun remains unchanged.]]
  },
  AvgDialog_116003_Content_34 = {
    Text = "No matter what..."
  },
  AvgDialog_116003_Content_35 = {
    Text = "You place the photo on your chest, where your heart is, and close your eyes."
  },
  AvgDialog_116003_Content_36 = {
    Text = "No matter what, I am not alone."
  },
  AvgDialog_116003_Content_37 = {
    Text = "Then, you open your eyes and look at the high-hanging black sun, walking steadily towards it."
  },
  AvgDialog_116003_Content_38 = {
    Text = "This world is still crumbling, watched by indescribable horrors, on the brink of collapse, but..."
  },
  AvgDialog_116003_Content_39 = {
    Text = "<Big:You will eventually find a way to save it>"
  },
  AvgDialog_116003_Content_4 = {
    Text = "I just didn't expect it to come so soon, nor did I expect you to be so determined."
  },
  AvgDialog_116003_Content_5 = {
    Text = "Actually... I have hesitated and avoided. When I was by the seaside."
  },
  AvgDialog_116003_Content_6 = {
    Text = "So why not continue to sink into this? Is it not beautiful enough, not happy enough here?"
  },
  AvgDialog_116003_Content_7 = {
    Text = "You remain silent, recalling your House-Tree-Person drawing."
  },
  AvgDialog_116003_Content_8 = {
    Text = "Undeniably, this is indeed a beautiful dream. But..."
  },
  AvgDialog_116003_Content_9 = {
    Text = "Gradually, the scenes in your mind are no longer paintings, but the real Mythag, the real Doll, Ramona, Lotan, and Ogier."
  },
  AvgDialog_117499_Content_1 = {
    Text = "<Shake:There are too many of them...>"
  },
  AvgDialog_117499_Content_2 = {
    Text = "Under the dim sky, the frenzy of fish swirls like an unending storm. You spot a rusty metal ladder in the corner and quickly climb to the second platform."
  },
  AvgDialog_117499_Content_3 = {
    Text = "I should be safe hiding here for a while."
  },
  AvgDialog_117499_Content_4 = {
    Text = "An eerie odor, mixed with a teeth-grinding friction sound, captures your attention."
  },
  AvgDialog_117499_Content_5 = {
    Text = "Wait, that one over there is..."
  },
  AvgDialog_117500_Content_1 = {Text = "Shackles"},
  AvgDialog_117500_Content_10 = {Text = "..."},
  AvgDialog_117500_Content_100 = {
    Text = "Murphy shakes her head dejectedly, her vacant eyes hollowly searching for your position. She faces you, tightly pursing her cracked, bloodless lips to force a faint smile."
  },
  AvgDialog_117500_Content_101 = {
    Text = "You've come for me... I thought... it would be impossible to see you..."
  },
  AvgDialog_117500_Content_102 = {
    Text = "The hull suddenly tilts violently, and the salty, cold tide surges into the cabin."
  },
  AvgDialog_117500_Content_103 = {
    Text = "What is going on?!"
  },
  AvgDialog_117500_Content_104 = {
    Text = "Did the ship run aground?"
  },
  AvgDialog_117500_Content_105 = {
    Text = "Impossible. The ship's deep draft means a leak wouldn't flood the top level this quickly..."
  },
  AvgDialog_117500_Content_106 = {Text = "Unless..."},
  AvgDialog_117500_Content_107 = {
    Text = "William rushes to the porthole. The bizarre sight before him is like the most absurd delusion: The Paradise sinks at an incredible speed."
  },
  AvgDialog_117500_Content_108 = {
    Text = "Some enormous, irresistible force drags the ship rapidly downward toward the seabed with tremendous strength, as if pulled by a giant whale."
  },
  AvgDialog_117500_Content_109 = {Text = "AAHHH—"},
  AvgDialog_117500_Content_11 = {
    Text = "You open your eyes again. You feel the bedding beneath you, soft and warm. Everything feels strangely familiar."
  },
  AvgDialog_117500_Content_110 = {
    Text = "Under the violent tremors, the chain piercing through Murphy's palm suddenly snaps."
  },
  AvgDialog_117500_Content_111 = {
    Text = "Her sticky, damp palm explores the space, resting on the back of your hand. She endures the pain of the wound, gently gripping your hand and locking eyes with you."
  },
  AvgDialog_117500_Content_112 = {
    Text = "She mumbles, her words carrying the metallic smell of rust, whether from seawater or blood, you cannot tell."
  },
  AvgDialog_117500_Content_113 = {
    Text = "Help me... I know you can..."
  },
  AvgDialog_117500_Content_114 = {
    Text = "Her last words, along with the seawater flooding the cabin, are swallowed by the dark."
  },
  AvgDialog_117500_Content_12 = {
    Text = "<Small:Tsk, do we really have to wait here for {Male=him,Female=her} to wake up?>"
  },
  AvgDialog_117500_Content_13 = {
    Text = "<Small:Goliath, do not question the Divine Mother's decree.>"
  },
  AvgDialog_117500_Content_14 = {
    Text = "<Small:Let's keep our voice down, Lord Goliath. This morning, Divine Mother called our High Priestess over for quite a scolding...>"
  },
  AvgDialog_117500_Content_15 = {
    Text = "The muffled argument came from beyond the veil."
  },
  AvgDialog_117500_Content_16 = {
    Text = "Cough, cough..."
  },
  AvgDialog_117500_Content_17 = {
    Text = "Are you awake? We're all waiting for you."
  },
  AvgDialog_117500_Content_18 = {
    Text = "Faros lifts the bed canopy."
  },
  AvgDialog_117500_Content_19 = {
    Text = "Did I... get saved from the sea again?"
  },
  AvgDialog_117500_Content_2 = {
    Text = "...A spider?"
  },
  AvgDialog_117500_Content_20 = {
    Text = "You've lived, and that's luck enough. We have no obligation to answer all your questions."
  },
  AvgDialog_117500_Content_21 = {
    Text = "By the Divine Mother's command, the Seafarers have long awaited your wake."
  },
  AvgDialog_117500_Content_22 = {
    Text = "This is the lemon juice that Divine Mother bid me squeeze. Drink it gratefully, human."
  },
  AvgDialog_117500_Content_23 = {
    Text = "Since our guest is safe and sound, I will return to my post as navigator. The Divine Realm calls."
  },
  AvgDialog_117500_Content_24 = {Text = "..."},
  AvgDialog_117500_Content_25 = {Text = "..."},
  AvgDialog_117500_Content_26 = {
    Text = "Did that truly happen, or was it a nightmare I had while drowning..."
  },
  AvgDialog_117500_Content_27 = {
    Text = "(I must find a way to verify it.)"
  },
  AvgDialog_117500_Content_28 = {
    Text = "If I remember correctly, the last person I saw was..."
  },
  AvgDialog_117500_Content_29 = {
    Text = "You step onto the deck."
  },
  AvgDialog_117500_Content_3 = {
    Text = "...A spider?"
  },
  AvgDialog_117500_Content_30 = {
    Text = "<Shake:Hey! William—>"
  },
  AvgDialog_117500_Content_31 = {
    Text = "<Shake:Stop hiding—I know you're here!>"
  },
  AvgDialog_117500_Content_32 = {
    Text = "The only sound on the deck is the quiet tide. Your cries diffuse into the morning mist."
  },
  AvgDialog_117500_Content_33 = {
    Text = "(Forget it, it really was just my dream...)"
  },
  AvgDialog_117500_Content_34 = {Text = "WHOAAAH!"},
  AvgDialog_117500_Content_35 = {
    Text = "The deck beneath your feet suddenly opens a hatch, and with a thud, you plunge into the darkness."
  },
  AvgDialog_117500_Content_36 = {
    Text = "A bundle of straw cushions your fall."
  },
  AvgDialog_117500_Content_37 = {
    Text = "Long time no see, %player%."
  },
  AvgDialog_117500_Content_38 = {
    Text = "You know me. You are my Senior William, from our original world..."
  },
  AvgDialog_117500_Content_39 = {
    Text = "William ignores the surprise in your tone. His expression darkens."
  },
  AvgDialog_117500_Content_4 = {
    Text = "A woman gazes intently at you, her hands holding a spinning wheel. Layers of sheer fabric lie beneath her as she stands on the rusted deck."
  },
  AvgDialog_117500_Content_40 = {
    Text = "I don't recall teaching you to act so boldly in the enemy's stronghold."
  },
  AvgDialog_117500_Content_41 = {
    Text = "Even Dean Czort, the most headstrong one of us, probably wouldn't support your choice."
  },
  AvgDialog_117500_Content_42 = {
    Text = "The familiar scent of cedar. The familiar upright posture. The familiar stern tone."
  },
  AvgDialog_117500_Content_43 = {Text = "William..."},
  AvgDialog_117500_Content_44 = {
    Text = "I wasn't planning to show up before you yet. Not before addressing the key issue."
  },
  AvgDialog_117500_Content_45 = {
    Text = "However, your recklessness forced my hand."
  },
  AvgDialog_117500_Content_46 = {
    Text = "So you knew I've been looking for you?"
  },
  AvgDialog_117500_Content_47 = {
    Text = "William doesn't offer a word, only a sharp look that plainly asks, <Italic:Do you think I'm an idiot?>"
  },
  AvgDialog_117500_Content_48 = {
    Text = "We're already on the same ship. I might as well tell you everything to avoid unnecessary complications."
  },
  AvgDialog_117500_Content_49 = {
    Text = "But first, mind sharing the intel you have?"
  },
  AvgDialog_117500_Content_5 = {
    Text = "This time, she does not sigh or speak; she is simply silent."
  },
  AvgDialog_117500_Content_50 = {Text = "..."},
  AvgDialog_117500_Content_51 = {Text = "..."},
  AvgDialog_117500_Content_52 = {
    Text = "From being turned into a brain vat by Doll: Inferno, to being trapped in Clementine's sanatorium, then through the customs of Necrovia, and finally the \"nightmare\" you've lived through on Paradise the cruise ship."
  },
  AvgDialog_117500_Content_53 = {
    Text = "You recount the events you have witnessed, and William listens attentively with his head tilted, nodding occasionally to show engagement."
  },
  AvgDialog_117500_Content_54 = {
    Text = "When you begin to narrate the young William you had seen, you hesitate for a moment, but William simply raises his hand to signal you to continue."
  },
  AvgDialog_117500_Content_55 = {
    Text = "The information you provided is very useful."
  },
  AvgDialog_117500_Content_56 = {
    Text = "William, what exactly are you chasing right now?"
  },
  AvgDialog_117500_Content_57 = {
    Text = "William ponders for a moment."
  },
  AvgDialog_117500_Content_58 = {
    Text = "Let me think about where to start."
  },
  AvgDialog_117500_Content_59 = {
    Text = "Ever since I fell into this world, I've been exploring two questions: why I ended up here, and how to return to my original world."
  },
  AvgDialog_117500_Content_6 = {
    Text = "Why? I clearly remember being surrounded by countless Seafarers, and then..."
  },
  AvgDialog_117500_Content_60 = {
    Text = "William solemnly draws out a Silver Key he keeps close to his heart, and a hint of nostalgia shines in his gaze."
  },
  AvgDialog_117500_Content_61 = {
    Text = "This Silver Key was once shattered. I restored it myself. It belonged to Fingal, my former partner... People often call me the most legendary Investigator of Mythag, but to me, that's only because he passed away in his prime."
  },
  AvgDialog_117500_Content_62 = {
    Text = "It wasn't until I fell into this world that I understand he merely gained Insight into the world's essence earlier, and fought as a pioneer on the front lines against Dissolution."
  },
  AvgDialog_117500_Content_63 = {
    Text = "He traced the secret connecting two worlds and left behind a key clue—an ivory sculpture."
  },
  AvgDialog_117500_Content_64 = {
    Text = "As usual, he always gets ahead of me."
  },
  AvgDialog_117500_Content_65 = {
    Text = "William's expression grows wistful. He shakes his head and returns the Silver Key to his bosom."
  },
  AvgDialog_117500_Content_66 = {
    Text = "...Have you seen the ivory sculpture in Miryam or Murphy's possession?"
  },
  AvgDialog_117500_Content_67 = {Text = "You nod."},
  AvgDialog_117500_Content_68 = {
    Text = "If everything develops the same way as last time, Murphy is holding a ceremony with this sculpture on the deck above us right now."
  },
  AvgDialog_117500_Content_69 = {
    Text = "That ivory sculpture seems to be connected with the truth behind this world."
  },
  AvgDialog_117500_Content_7 = {
    Text = "You check your limbs. Although phantom pain still exists, there is not a trace of injury on your body; the battle you experienced before fainting seems never to have happened."
  },
  AvgDialog_117500_Content_70 = {
    Text = "So, if we want to go back, we need to obtain the ivory sculpture and analyze it."
  },
  AvgDialog_117500_Content_71 = {
    Text = "The ritual is over. The ivory sculpture should be in Murphy's room..."
  },
  AvgDialog_117500_Content_72 = {
    Text = "It's very quiet inside. There shouldn't be anyone in there..."
  },
  AvgDialog_117500_Content_73 = {
    Text = "Better safe than sorry. We must try to avoid unnecessary conflict."
  },
  AvgDialog_117500_Content_74 = {
    Text = "Alright, let's go take a look first."
  },
  AvgDialog_117500_Content_75 = {
    Text = "You carefully push the door open slightly."
  },
  AvgDialog_117500_Content_76 = {Text = "..."},
  AvgDialog_117500_Content_77 = {
    Text = "The air, mixed with an unpleasant odor, flows into your nostrils as you unconsciously take a deep breath."
  },
  AvgDialog_117500_Content_78 = {
    Text = "What's the matter?"
  },
  AvgDialog_117500_Content_79 = {Text = "Sound."},
  AvgDialog_117500_Content_8 = {
    Text = "Was that... a nightmare?"
  },
  AvgDialog_117500_Content_80 = {
    Text = "A sound finally emerges in the quiet room."
  },
  AvgDialog_117500_Content_81 = {
    Text = "The slow sound of liquid dripping."
  },
  AvgDialog_117500_Content_82 = {
    Text = "Drip, drop. The liquid converges into a small, newly formed puddle."
  },
  AvgDialog_117500_Content_83 = {
    Text = "Eight taut iron chains extend from Murphy's limbs, binding her tightly. A gaping, crimson cavity scars her chest."
  },
  AvgDialog_117500_Content_84 = {
    Text = "Blood flows from the shocking wound, dripping into the pool, which is the source of the persistent ticking sound."
  },
  AvgDialog_117500_Content_85 = {Text = "Murphy...!"},
  AvgDialog_117500_Content_86 = {
    Text = "You are too late."
  },
  AvgDialog_117500_Content_87 = {
    Text = "Your heart aches, gripped tightly by an invisible hand. The familiar, suffocating pain is sharply pierced by fragments of memory."
  },
  AvgDialog_117500_Content_88 = {
    Text = "The dazzling light stings your eyes, causing uncontrollable tears."
  },
  AvgDialog_117500_Content_89 = {
    Text = "As the murky liquid drains away, your eyes finally refocus on the girl."
  },
  AvgDialog_117500_Content_9 = {
    Text = "The woman silently nods, her figure dissipating into the hazy mist."
  },
  AvgDialog_117500_Content_90 = {
    Text = "With a blade sunken deep into her chest, the moonlit girl opens her eyes."
  },
  AvgDialog_117500_Content_91 = {
    Text = "The full moon, a symbol of death, looms close, yet not a trace of fear shows on her young face."
  },
  AvgDialog_117500_Content_92 = {
    Text = "I did it... I truly did it."
  },
  AvgDialog_117500_Content_93 = {
    Text = "I... pierced it... It won't be born..."
  },
  AvgDialog_117500_Content_94 = {
    Text = "Now, I can..."
  },
  AvgDialog_117500_Content_95 = {
    Text = "Her hand gripping the knife falls weakly, as thick, viscous, dark crimson liquid flows from the blade, dripping through her fingers into the sea."
  },
  AvgDialog_117500_Content_96 = {
    Text = "Cough, cough..."
  },
  AvgDialog_117500_Content_97 = {
    Text = "You are... the person in my dream..."
  },
  AvgDialog_117500_Content_98 = {
    Text = "Don't talk yet! Let me help you..."
  },
  AvgDialog_117500_Content_99 = {
    Text = "Your anxious attempts yield no results. The chains emit faint squeaks as Murphy trembles with pain."
  },
  AvgDialog_117501_Content_10 = {
    Text = "Why do you ask so, Divine Mother?"
  },
  AvgDialog_117501_Content_11 = {
    Text = "Last night, I had a dream."
  },
  AvgDialog_117501_Content_12 = {
    Text = "In the dream, with that ritual dagger..."
  },
  AvgDialog_117501_Content_13 = {
    Text = [[
Murphy raises her hand and points at the dagger that Miryam always carries.
The blade shimmers with vibrant colors, exuding an eerie, poisonous glimmer.]]
  },
  AvgDialog_117501_Content_14 = {
    Text = "I pierced my own chest."
  },
  AvgDialog_117501_Content_15 = {
    Text = "<ItalicRed:He won't be born...>"
  },
  AvgDialog_117501_Content_16 = {
    Text = "Murphy murmurs to herself, her fingertips gently tracing the blood-soaked scar on her chest."
  },
  AvgDialog_117501_Content_17 = {
    Text = "It was only a nightmare."
  },
  AvgDialog_117501_Content_18 = {
    Text = "Miryam steps forward, kneels before Murphy, and gently places her palm on the back of Murphy's hand to offer comfort."
  },
  AvgDialog_117501_Content_19 = {
    Text = "Rest assured, we Seafarers' long-held wish has been fulfilled. He exists. He has arrived in this world."
  },
  AvgDialog_117501_Content_2 = {Text = "Murmurs"},
  AvgDialog_117501_Content_20 = {
    Text = "And you and I will ultimately arrive at the Eternal Divine Realm, sharing the glory of the divine before His throne."
  },
  AvgDialog_117501_Content_21 = {
    Text = "Her words sound like prayers offered before an altar, filled with reverence and devotion."
  },
  AvgDialog_117501_Content_22 = {
    Text = "What if we can't reach the Divine Realm? I mean, if..."
  },
  AvgDialog_117501_Content_23 = {
    Text = "Miryam immediately interrupts Murphy's hesitant inquiry."
  },
  AvgDialog_117501_Content_24 = {
    Text = [[
Such matters were never conveyed in the prophecy of the God-King.
The next time the stars align is tomorrow, and His blood will surely guide us to the promised land.]]
  },
  AvgDialog_117501_Content_25 = {
    Text = "Murphy frowns."
  },
  AvgDialog_117501_Content_26 = {
    Text = "I'm going to rest now, Miryam. You should go back and rest too."
  },
  AvgDialog_117501_Content_27 = {
    Text = "I will pray for you until dawn, so you may have a peaceful sleep throughout the night."
  },
  AvgDialog_117501_Content_28 = {
    Text = "Murphy doesn't respond, her deep gaze following Miryam's silhouette until the door's creaking sound closes."
  },
  AvgDialog_117501_Content_29 = {
    Text = "She turns despondently to the altar in the shadow, closing her eyes to pray."
  },
  AvgDialog_117501_Content_3 = {
    Text = "Esteemed Divine Mother, you are here watching the lights again."
  },
  AvgDialog_117501_Content_30 = {
    Text = "Tomorrow, the day of stellar alignment..."
  },
  AvgDialog_117501_Content_31 = {
    Text = [[
The strange offerings on the altar give her no response, silent like fossils beneath the ice.
Murphy finally opens her eyes with determination.]]
  },
  AvgDialog_117501_Content_32 = {
    Text = "For the continuation of this dream..."
  },
  AvgDialog_117501_Content_33 = {
    Text = "She straightens her slender arms, heavily veiled in black gauze, raising the ceremonial dagger high—"
  },
  AvgDialog_117501_Content_34 = {
    Text = "The candlelight reflects the dagger's shadow, fiercely stabbing into the sleeping swaddling on the altar."
  },
  AvgDialog_117501_Content_35 = {
    Text = "A sickening squelch sounds as the blade pierces the thick flesh. A dark slime weeps from the wound, soaking the glaring Seafarer runes on the velvet swaddling."
  },
  AvgDialog_117501_Content_36 = {
    Text = "Another night is about to arrive..."
  },
  AvgDialog_117501_Content_37 = {
    Text = "She lets out a sigh of relief and closes her eyes, but what engulfs her is not an abyss of darkness, but yesterday's dream."
  },
  AvgDialog_117501_Content_38 = {Text = "..."},
  AvgDialog_117501_Content_39 = {
    Text = "(The moment the dagger pierced me. There was someone there...)"
  },
  AvgDialog_117501_Content_4 = {
    Text = "Get some rest early, for tomorrow is the Day of Stellar Alignment, and you still need to guide the Seafarers on their path with your holy blood."
  },
  AvgDialog_117501_Content_40 = {
    Text = "(Who was it? I never met them before, but I feel somewhat nostalgic...)"
  },
  AvgDialog_117501_Content_41 = {
    Text = "...A spider?"
  },
  AvgDialog_117501_Content_42 = {
    Text = "A tiny dark purple spider is staring at you from the mast. Seeing you awake, it raises its front leg and greets you."
  },
  AvgDialog_117501_Content_43 = {
    Text = "In the dream, I heard someone singing..."
  },
  AvgDialog_117501_Content_44 = {
    Text = "Ethereal, soft, like the singing of a siren, lingering endlessly in your ears."
  },
  AvgDialog_117501_Content_45 = {
    Text = "Tragic children, the fabric of fate has already been woven, and you will inevitably embark on your destined journey."
  },
  AvgDialog_117501_Content_46 = {
    Text = "And you, the guest from another world—"
  },
  AvgDialog_117501_Content_47 = {
    Text = "As the moment of the stars' alignment returns, please mark the end of the cycle of tragedy."
  },
  AvgDialog_117501_Content_48 = {
    Text = "With a long, mournful sigh, the woman's phantom vanishes."
  },
  AvgDialog_117501_Content_49 = {Text = "?!"},
  AvgDialog_117501_Content_5 = {
    Text = "Murphy stares intently at the flickering flame of the lantern. Her black veil sways with her movements, casting curtain-like phantoms on the cabin walls."
  },
  AvgDialog_117501_Content_50 = {
    Text = "Once the momentary feeling of fear dissipates, you finally calm down and observe your surroundings."
  },
  AvgDialog_117501_Content_51 = {
    Text = "Where am I...?"
  },
  AvgDialog_117501_Content_52 = {
    Text = "Soft mattress. A tranquil space covered in a black canopy. The faint scent of sage and incense floats in the air."
  },
  AvgDialog_117501_Content_53 = {
    Text = "Previously... I..."
  },
  AvgDialog_117501_Content_54 = {
    Text = "Doll! Can you hear me? Doll?"
  },
  AvgDialog_117501_Content_55 = {
    Text = "Keep your voice down. You're disturbing my voice waveform receiver."
  },
  AvgDialog_117501_Content_56 = {
    Text = "I've caught up with the ship that William boarded according to the fishermen! But that ship has sailed into the storm!"
  },
  AvgDialog_117501_Content_57 = {
    Text = "Let me guess. Your next sentence will be..."
  },
  AvgDialog_117501_Content_58 = {
    Text = "I'M GOING AFTER HIM!"
  },
  AvgDialog_117501_Content_59 = {
    Text = "You plan to charge into the Bermuda Islands' trench with this little boat? Aren't you afraid of capsizing in there?"
  },
  AvgDialog_117501_Content_6 = {
    Text = "Miryam, have you ever had a dream?"
  },
  AvgDialog_117501_Content_60 = {
    Text = "I can't afford to lose another clue; this is the only real and valid information we've encountered in months!"
  },
  AvgDialog_117501_Content_61 = {
    Text = "May the Silver Key light our way!"
  },
  AvgDialog_117501_Content_62 = {
    Text = "You didn't hear the expected phrase \"May the Silver Key guide us,\" but instead, you heard the crackling sound of a disrupted link."
  },
  AvgDialog_117501_Content_63 = {
    Text = "What came next was a towering roar of waves, followed closely by the engulfing endless darkness—"
  },
  AvgDialog_117501_Content_64 = {
    Text = "Three months ago, following the news of a mysterious blonde man setting sail from Innsmouth Harbor, you set off to track William's whereabouts."
  },
  AvgDialog_117501_Content_65 = {
    Text = "Recently, you finally saw the flags of the fishermen described on the sea surface, but a sudden storm swept you off course."
  },
  AvgDialog_117501_Content_66 = {
    Text = "When you opened your eyes again, you found yourself in this room."
  },
  AvgDialog_117501_Content_67 = {
    Text = "Are you awake? We're all waiting for you."
  },
  AvgDialog_117501_Content_68 = {
    Text = "The black bed canopy is gently lifted, accompanied by a familiar yet strange female voice."
  },
  AvgDialog_117501_Content_69 = {
    Text = "We...? Who are you...?"
  },
  AvgDialog_117501_Content_7 = {
    Text = "Of course, Divine Mother. In countless dreams, I see great Lemuria rising, reborn under the sunlight."
  },
  AvgDialog_117501_Content_70 = {
    Text = "Four familiar faces surround your bed, making you feel very uneasy."
  },
  AvgDialog_117501_Content_71 = {
    Text = "By the Divine Mother's command, the Seafarers have been awaiting your waking for a long time. Drink this medicine. Our Divine Mother prepared it personally."
  },
  AvgDialog_117501_Content_72 = {
    Text = "Caecus presents a finely crafted glass cup; the murky, bright yellow liquid inside is unsettling."
  },
  AvgDialog_117501_Content_73 = {
    Text = "What is this...?"
  },
  AvgDialog_117501_Content_74 = {
    Text = "You've lived, and that's luck enough. Stop with the questions."
  },
  AvgDialog_117501_Content_75 = {
    Text = "The Divine Mother bid me prepare it. Drink it, and be grateful, human."
  },
  AvgDialog_117501_Content_76 = {
    Text = "Under their watchful eyes, you hesitantly take a sip."
  },
  AvgDialog_117501_Content_77 = {
    Text = "BAH! That's sour! Is this just pure lemon juice?!"
  },
  AvgDialog_117501_Content_78 = {
    Text = "You bolt upright, your face twisted in a grimace of pain."
  },
  AvgDialog_117501_Content_79 = {
    Text = "Since He is safe and sound, I want to go to the deck and receive the call. The Divine Realm is calling me."
  },
  AvgDialog_117501_Content_8 = {
    Text = "The eternal radiance sweeps across the distant seas, guiding our course to a new age."
  },
  AvgDialog_117501_Content_80 = {
    Text = "(This world is insane, or I am... One of us has to be.)"
  },
  AvgDialog_117501_Content_81 = {
    Text = "Uh... where exactly am I?..."
  },
  AvgDialog_117501_Content_82 = {
    Text = "You are aboard the Paradise, the Seafarers' most cherished maritime haven."
  },
  AvgDialog_117501_Content_83 = {
    Text = "We are sailing towards Lemuria, the Eternal Divine Realm."
  },
  AvgDialog_117501_Content_9 = {
    Text = "Miryam instinctively gives the answer, but the question that follows reveals an unmistakable surprise."
  },
  AvgDialog_117502_Content_1 = {Text = "..."},
  AvgDialog_117502_Content_10 = {
    Text = "In the last glimmer of light before your vision falls into absolute darkness, a figure darts past."
  },
  AvgDialog_117502_Content_11 = {
    Text = "A head of brilliant golden hair, his mechanical arm glimmering with a metallic sheen."
  },
  AvgDialog_117502_Content_12 = {
    Text = "William...?"
  },
  AvgDialog_117502_Content_2 = {Text = "..."},
  AvgDialog_117502_Content_3 = {
    Text = "How long have you been fighting among the stinking piles of fish?"
  },
  AvgDialog_117502_Content_4 = {
    Text = "One hour? A day? Or an immeasurable amount of time?"
  },
  AvgDialog_117502_Content_5 = {
    Text = "(Rushing in when the Seafarers are collectively mobilizing for the ritual... This was truly an impulsive and terrible decision.)"
  },
  AvgDialog_117502_Content_6 = {
    Text = "The slippery sensation has become so familiar it's numb, and the stench of sticky mucus no longer troubles your congested nostrils."
  },
  AvgDialog_117502_Content_7 = {
    Text = "（If I could try just one more time... What a pity...）"
  },
  AvgDialog_117502_Content_8 = {
    Text = "You strain to raise the Silver Key. The core that once shone with brilliance begins to tremble. You are on the verge of collapse, spitting out a mouthful of blood."
  },
  AvgDialog_117502_Content_9 = {
    Text = "(So... This is it... Sorry... I couldn't get out...)"
  },
  AvgDialog_117503_Content_1 = {Text = "A Traveler"},
  AvgDialog_117503_Content_10 = {
    Text = "Your heart pounds with a sudden, frantic rhythm, and you open your mouth, already knowing the identity of the one behind the veil."
  },
  AvgDialog_117503_Content_100 = {
    Text = "A school of fish bursts free from the water, spasming and struggling in the thick air before crashing down beside you in a stinking, sticky downpour."
  },
  AvgDialog_117503_Content_101 = {
    Text = "Accompanied by a chilling sound, the half-rotten fish bounce uselessly on the deck, the decaying slime at the point of impact releasing a suffocating stench."
  },
  AvgDialog_117503_Content_102 = {
    Text = "Delicate, fragile tendrils tear through their pale abdomens, unnervingly crawling toward you—"
  },
  AvgDialog_117503_Content_11 = {
    Text = "<Shake:Murphy...>"
  },
  AvgDialog_117503_Content_12 = {
    Text = "Between the gauze, her pale and bluish skin is exposed, white as a drifting corpse on the verge of disintegration."
  },
  AvgDialog_117503_Content_13 = {
    Text = "How dare you utter the Divine Mother's name so casually!"
  },
  AvgDialog_117503_Content_14 = {
    Text = "It's fine, Caecus. {Male=He,Female=She} is a guest of the paradise and will join our great voyage."
  },
  AvgDialog_117503_Content_15 = {
    Text = "Five pairs of eyes fix on you intently, forcing the words you were about to say back down your throat."
  },
  AvgDialog_117503_Content_16 = {
    Text = "...Murphy, can I speak with you alone?"
  },
  AvgDialog_117503_Content_17 = {Text = "..."},
  AvgDialog_117503_Content_18 = {Text = "..."},
  AvgDialog_117503_Content_19 = {Text = "Murphy..."},
  AvgDialog_117503_Content_2 = {
    Text = "The speaker sits quietly at your bedside, her face obscured by a hazy black veil."
  },
  AvgDialog_117503_Content_20 = {
    Text = "If your questions aren't ready, I actually have one for you."
  },
  AvgDialog_117503_Content_21 = {
    Text = "Why did you come to the Paradise? To approach it, one must survive the storm."
  },
  AvgDialog_117503_Content_22 = {
    Text = "To take such a risk, you must have a request."
  },
  AvgDialog_117503_Content_23 = {
    Text = "So... have you seen a man half a head taller than me with golden hair?"
  },
  AvgDialog_117503_Content_24 = {
    Text = "Murphy casts you a sidelong glance and scoffs."
  },
  AvgDialog_117503_Content_25 = {
    Text = "Given your height, that description fits quite a few crew members."
  },
  AvgDialog_117503_Content_26 = {
    Text = "No, you'd recognize him instantly... He has a mechanical arm, he's very handsome, and he smells faintly of cedar."
  },
  AvgDialog_117503_Content_27 = {
    Text = "...Then I can confirm, I've never seen anyone like that. Those crew members always emit a foul and dirty fishy smell."
  },
  AvgDialog_117503_Content_28 = {
    Text = "So, Murphy, there's one more key thing."
  },
  AvgDialog_117503_Content_29 = {Text = "Hmm?"},
  AvgDialog_117503_Content_3 = {
    Text = "(A familiar voice... Who is this...)"
  },
  AvgDialog_117503_Content_30 = {
    Text = "Do you want to escape with me?"
  },
  AvgDialog_117503_Content_31 = {Text = "Hah?!"},
  AvgDialog_117503_Content_32 = {
    Text = "Murphy recoils, then rage colors her cheeks. She struggles to regain control, finally releasing a mocking snort."
  },
  AvgDialog_117503_Content_33 = {
    Text = "What do you mean, \"escape\"?"
  },
  AvgDialog_117503_Content_34 = {
    Text = "Literally. We need to find a way to leave this ship and break free from the Seafarers' control."
  },
  AvgDialog_117503_Content_35 = {
    Text = "Why would I run away with you?"
  },
  AvgDialog_117503_Content_36 = {
    Text = "Because you don't like your life here."
  },
  AvgDialog_117503_Content_37 = {
    Text = "You don't like Miryam's fabricated doctrines, the followers' hypocritical worship, or those hollow honors."
  },
  AvgDialog_117503_Content_38 = {
    Text = "Murphy slowly lowers her gaze."
  },
  AvgDialog_117503_Content_39 = {
    Text = "Seeing her silence, you quickly press your advantage."
  },
  AvgDialog_117503_Content_4 = {
    Text = "Your aching arms strain as you prop yourself up, trying to make sense of the situation."
  },
  AvgDialog_117503_Content_40 = {
    Text = "In another world, I met you, and I knew you instantly. We experienced the same dreadful circumstances, and you found a way to escape..."
  },
  AvgDialog_117503_Content_41 = {Text = "Hmph..."},
  AvgDialog_117503_Content_42 = {
    Text = "Wrong, wrong! You are completely mistaken!"
  },
  AvgDialog_117503_Content_43 = {Text = "Murphy...?"},
  AvgDialog_117503_Content_44 = {
    Text = "Murphy's reaction catches you totally off guard."
  },
  AvgDialog_117503_Content_45 = {
    Text = "She begins to chuckle, and the sound spirals into hysterical laughter that fills the room."
  },
  AvgDialog_117503_Content_46 = {
    Text = "After a time, she seems to have exhausted her mirth, and the laughter snaps off. She lifts her head and glares at you fiercely."
  },
  AvgDialog_117503_Content_47 = {
    Text = "The God's holy embryo nestles in my chest. I am the revered Divine Mother, cherished by all. Why would I heed your mortal pleas to \"escape\"?"
  },
  AvgDialog_117503_Content_48 = {
    Text = "But when the God is born, you will die..."
  },
  AvgDialog_117503_Content_49 = {
    Text = "No need to wait for that, foolish one."
  },
  AvgDialog_117503_Content_5 = {
    Text = "Stay still, fool."
  },
  AvgDialog_117503_Content_50 = {
    Text = "Murphy presents to you an eerie swaddling. What is supposed to be an infant's head is congealed with a familiar, purplish lump of gelatinous flesh."
  },
  AvgDialog_117503_Content_51 = {
    Text = "The Divine Fetus?!"
  },
  AvgDialog_117503_Content_52 = {
    Text = "You recognize it as the malformed false god the Seafarers tried to summon on Sona-Nyl."
  },
  AvgDialog_117503_Content_53 = {
    Text = "Has the Divine Fetus already been born in this world? But why is it... so small?!"
  },
  AvgDialog_117503_Content_54 = {
    Text = "Why is it so small... What a ridiculous question to ask."
  },
  AvgDialog_117503_Content_55 = {
    Text = "If it stayed this small, it wouldn't be a swollen hydrogen balloon, greedily siphoning energy from the mother, relentlessly filling, expanding, and compressing my chest..."
  },
  AvgDialog_117503_Content_56 = {
    Text = "Then, at the moment the mother dies, it would break down, shatter, and turn to ash..."
  },
  AvgDialog_117503_Content_57 = {
    Text = "You have seen it. This is the Divine Fetus I have borne."
  },
  AvgDialog_117503_Content_58 = {
    Text = "You call this... a god?"
  },
  AvgDialog_117503_Content_59 = {
    Text = "So what? Has anyone ever witnessed the Seafarers' god when He was born?"
  },
  AvgDialog_117503_Content_6 = {
    Text = "The maiden anxiously rises, the veiling black gauze swaying uneasily."
  },
  AvgDialog_117503_Content_60 = {
    Text = "Who can assert that this stinking mass of flesh in our hands is not a real \"God\"?"
  },
  AvgDialog_117503_Content_61 = {
    Text = "The challenging voice booms like thunder, echoing in your mind."
  },
  AvgDialog_117503_Content_62 = {
    Text = "I am not the Murphy you know; I am the Divine Mother of the Seafarers, the only one who shares His bloodline."
  },
  AvgDialog_117503_Content_63 = {
    Text = "Do not make me regret bringing you into this Paradise. Now, take your ridiculous thoughts and roll out of this room. Leave me alone."
  },
  AvgDialog_117503_Content_64 = {
    Text = "You wander on the Paradise cruise ship, following past memories, while the short fish-people sailors bustle around, ignoring you."
  },
  AvgDialog_117503_Content_65 = {
    Text = "Until you see two familiar figures beside the engine room."
  },
  AvgDialog_117503_Content_66 = {
    Text = "Kid, come at me! Give it your all!"
  },
  AvgDialog_117503_Content_67 = {Text = "Yes, sir!"},
  AvgDialog_117503_Content_68 = {Text = "CLANG!"},
  AvgDialog_117503_Content_69 = {
    Text = "Still blocked, huh... Curse it, will I ever be strong enough to see our plan through..."
  },
  AvgDialog_117503_Content_7 = {
    Text = "This ship hosts many sensitive to the deep sea. Before you adapt to the \"Paradise,\" stay still, or your spirit will get further disturbed."
  },
  AvgDialog_117503_Content_70 = {
    Text = "Quiet down, kid. Eavesdroppers are everywhere. If we're caught, neither of us walks away."
  },
  AvgDialog_117503_Content_71 = {
    Text = "Lord Goliath, but you said our bloodline comes from the strong, and we should fear nothing..."
  },
  AvgDialog_117503_Content_72 = {
    Text = "Stupid boy. Even the strong must yield sometimes. On this ship, we pretend to obey those mad women."
  },
  AvgDialog_117503_Content_73 = {Text = "But..."},
  AvgDialog_117503_Content_74 = {
    Text = "Shut it, someone's coming."
  },
  AvgDialog_117503_Content_75 = {
    Text = "The giant emerges from the shadow of the engine room, the grinding sound of his heavy blade dragging across the floor nearly deafening you over the cabin's roar."
  },
  AvgDialog_117503_Content_76 = {
    Text = "Hello again, little one."
  },
  AvgDialog_117503_Content_77 = {
    Text = "Goliath... How did I end up on this ship?"
  },
  AvgDialog_117503_Content_78 = {
    Text = "Ask yourself that. Ordinary travelers are not welcome in Miryam's territory, let alone a small boat that crashed right into us."
  },
  AvgDialog_117503_Content_79 = {
    Text = "I don't know what luck you possess, but that girl suddenly changed her mind a few days ago. We are strictly forbidden from touching you."
  },
  AvgDialog_117503_Content_8 = {
    Text = "You come face-to-face with a pair of familiar red eyes."
  },
  AvgDialog_117503_Content_80 = {
    Text = "Otherwise, that woman would have already extracted the Silver from your body. After all, in a world where most humans are dead, Silver is a resource that diminishes with every use."
  },
  AvgDialog_117503_Content_81 = {
    Text = "So what is your stance? The Goliath I know is not a weakling who can be easily manipulated."
  },
  AvgDialog_117503_Content_82 = {
    Text = "Little one, you just boarded this ship. There is much you still don't know."
  },
  AvgDialog_117503_Content_83 = {
    Text = "You only need to remember one thing: everything on this vessel is decided by that girl, the Divine Mother. Do not cross her—or at least, don't let her find out if you do."
  },
  AvgDialog_117503_Content_84 = {
    Text = "The madwoman who is supposed to be in charge is completely obedient to her."
  },
  AvgDialog_117503_Content_85 = {
    Text = "As for the rest, I'll tell you when we meet again somewhere else, if fate permits."
  },
  AvgDialog_117503_Content_86 = {
    Text = "I need to clear my head... I'll go to the deck for some sea breeze."
  },
  AvgDialog_117503_Content_87 = {
    Text = "You stand alone at the bow, gazing into the distance."
  },
  AvgDialog_117503_Content_88 = {
    Text = "The sea is veiled in a light, pure white mist. The cruise ship navigates smoothly, slicing through the ocean's clamor and the sounds of machinery."
  },
  AvgDialog_117503_Content_89 = {
    Text = "You take a deep breath of the salty air, trying to untangle your chaotic thoughts."
  },
  AvgDialog_117503_Content_9 = {
    Text = "Thump. Thump."
  },
  AvgDialog_117503_Content_90 = {
    Text = "I chased William's ship into the storm, had an accident, and was rescued by the Seafarers' ship..."
  },
  AvgDialog_117503_Content_91 = {
    Text = "The Divine Fetus has been born, Murphy has become the Divine Mother, Miryam is collecting Silver, and Goliath is secretly planning something..."
  },
  AvgDialog_117503_Content_92 = {
    Text = "<Shake:Click—>"
  },
  AvgDialog_117503_Content_93 = {
    Text = "Huh, what was that sound?"
  },
  AvgDialog_117503_Content_94 = {
    Text = "You turn to trace the noise, but the deck is eerily quiet, with no one in sight."
  },
  AvgDialog_117503_Content_95 = {
    Text = "(Was that just my imagination?)"
  },
  AvgDialog_117503_Content_96 = {
    Text = "<Shake:Plop, plop, plop...>"
  },
  AvgDialog_117503_Content_97 = {Text = "Huh?!"},
  AvgDialog_117503_Content_98 = {
    Text = "Deep beneath the surface, countless tiny bodies spread densely, their murky, floating halos resembling a festering rash on the water."
  },
  AvgDialog_117503_Content_99 = {
    Text = "These are... fish?"
  },
  AvgDialog_117504_Content_1 = {
    Text = "Rite of Navigation"
  },
  AvgDialog_117504_Content_10 = {
    Text = "We prepare for the Ritual of Navigation. Spiritual beings naturally flock to the sacred energy, becoming the very nourishment for our ritual."
  },
  AvgDialog_117504_Content_100 = {
    Text = "That voice calls for you—"
  },
  AvgDialog_117504_Content_101 = {
    Text = "<Italic:<Red:Help me.>>"
  },
  AvgDialog_117504_Content_102 = {
    Text = "Unable to contain the impulse, you leap down from the mast."
  },
  AvgDialog_117504_Content_103 = {
    Text = "You must go help her. Release her from this bloody ritual."
  },
  AvgDialog_117504_Content_104 = {
    Text = "Murphy, stop the ritual! You'll die! We are getting out of here!"
  },
  AvgDialog_117504_Content_105 = {
    Text = "Are you mad?! How dare you desecrate the Divine Mother!"
  },
  AvgDialog_117504_Content_106 = {
    Text = "I am not the Murphy you know, I have already made my choice!"
  },
  AvgDialog_117504_Content_107 = {
    Text = "I know you're not my Murphy, but I've met many Genesis Awakeners before—Ramona: Timeworn, Helot: Catena, Doll: Inferno..."
  },
  AvgDialog_117504_Content_108 = {
    Text = "They descend into madness because of the misfortune they endure. Their terrible experiences do not change the fundamental nature of their hearts."
  },
  AvgDialog_117504_Content_109 = {
    Text = "Stop clinging to this wrong path. Let's escape together!"
  },
  AvgDialog_117504_Content_11 = {
    Text = "Ritual of Navigation?"
  },
  AvgDialog_117504_Content_110 = {
    Text = "Escape...? Where are we going, then?"
  },
  AvgDialog_117504_Content_111 = {
    Text = "This is the perfect world. Any attempt to escape only plunges us into a deeper, more despairing cycle."
  },
  AvgDialog_117504_Content_112 = {
    Text = "Look back at the towering waves behind you."
  },
  AvgDialog_117504_Content_113 = {
    Text = "Accompanied by the sea's violent churn, thousands of Seafarers and serpents rise around the pale ivory sculpture, radiating an endless sense of menace."
  },
  AvgDialog_117504_Content_114 = {
    Text = "Divine Mother... forgive me, but I can no longer follow your instructions, nor can I tolerate this foolishness that desecrates our Lord."
  },
  AvgDialog_117504_Content_115 = {
    Text = "Miryam kneels at the bow, offering a reverent rite toward the direction where the horizon is divided."
  },
  AvgDialog_117504_Content_116 = {
    Text = "O Lord, please bless us faithful ones. The desecrators attempting to obstruct the ritual have already appeared."
  },
  AvgDialog_117504_Content_117 = {
    Text = "Please punish the impudent rogue who dares to offend the Divine Mother."
  },
  AvgDialog_117504_Content_118 = {
    Text = "They step onto the cruise ship's deck with slippery, eerie strides, mounting invisible stairs woven from the surging waves."
  },
  AvgDialog_117504_Content_119 = {
    Text = "<Big:<Shake:Go ahead! Crush them! Tear them apart!>>"
  },
  AvgDialog_117504_Content_12 = {
    Text = "The Divine Mother will guide us to the ascendant Lemuria."
  },
  AvgDialog_117504_Content_13 = {
    Text = "Seeing your confusion, Miryam becomes surprisingly gentle."
  },
  AvgDialog_117504_Content_14 = {
    Text = "You harbor many questions. Worry not; by the Divine Mother's decree, I will graciously answer them all."
  },
  AvgDialog_117504_Content_15 = {
    Text = "...Honestly, I'm already shocked at your change in attitude."
  },
  AvgDialog_117504_Content_16 = {
    Text = "In retrospect, your previous conflict with the Seafarers is revealed as utterly unnecessary."
  },
  AvgDialog_117504_Content_17 = {
    Text = "No way. I witnessed firsthand how you Seafarers conducted a sinister ritual..."
  },
  AvgDialog_117504_Content_18 = {
    Text = "It was a misunderstanding. We held those rituals only to harness the energy needed to keep this vessel sailing."
  },
  AvgDialog_117504_Content_19 = {
    Text = "Now that most humans are reduced to ash, such intensive rituals are unnecessary. The Silver accumulated from various places suffices for our needs."
  },
  AvgDialog_117504_Content_2 = {
    Text = "Amidst the overwhelming fish stench, the woman in the purple robe frowns and turns to Faros beside her."
  },
  AvgDialog_117504_Content_20 = {
    Text = "Therefore, the Seafarers headed to Necrovia to gather Silver from the deceased. Unfortunately, our plan happened to conflict with the appetites of Doresain, the King of Necrovia."
  },
  AvgDialog_117504_Content_21 = {
    Text = "Based on our understanding of Mythag University, you, too, utilize refined Silver as an energy source, do you not?"
  },
  AvgDialog_117504_Content_22 = {
    Text = "That Silver Key at your chest is a testament to that."
  },
  AvgDialog_117504_Content_23 = {
    Text = "You instinctively disagree, but you can't think of a refute. Eventually, you change the subject."
  },
  AvgDialog_117504_Content_24 = {
    Text = "Miryam... what is your goal?"
  },
  AvgDialog_117504_Content_25 = {
    Text = "To rebuild the Divine Realm and resurrect Lemuria, of course."
  },
  AvgDialog_117504_Content_26 = {
    Text = "Now that our Lord has descended, nothing is more urgent than returning to the Divine Realm and seeing the glorious Lemuria revived."
  },
  AvgDialog_117504_Content_27 = {
    Text = "Your Lord has descended... You mean, Tulu?"
  },
  AvgDialog_117504_Content_28 = {
    Text = "Yes. His consciousness remains in a state between dreaming and waking, but He will surely fulfill His promise and lead us back to the Divine Realm."
  },
  AvgDialog_117504_Content_29 = {
    Text = "Lemuria... where is it located?"
  },
  AvgDialog_117504_Content_3 = {
    Text = "Gather the spiritual energy here."
  },
  AvgDialog_117504_Content_30 = {
    Text = "Above the heavens, beneath the sea. The oracle reveals no more."
  },
  AvgDialog_117504_Content_31 = {
    Text = "Miryam falls silent after that."
  },
  AvgDialog_117504_Content_32 = {
    Text = "After collecting all the Silver pieces, Faros stands beside Miryam, holding a wooden box filled with silver beads."
  },
  AvgDialog_117504_Content_33 = {
    Text = "Faros, why did you join the Seafarers?"
  },
  AvgDialog_117504_Content_34 = {
    Text = "Is there any need to ask? Because Lemuria is right there. My homeland is calling me."
  },
  AvgDialog_117504_Content_35 = {
    Text = "No matter where I go, I hear His call, like the relentless surge of the tide day after day."
  },
  AvgDialog_117504_Content_36 = {
    Text = "She stares into the distance, her words sounding like a distant echo."
  },
  AvgDialog_117504_Content_37 = {
    Text = "It looks like a lovely day today. Look, the sun is about to emerge."
  },
  AvgDialog_117504_Content_38 = {Text = "The sun..."},
  AvgDialog_117504_Content_39 = {
    Text = "You follow her gaze—"
  },
  AvgDialog_117504_Content_4 = {
    Text = "Yes, Your Holiness."
  },
  AvgDialog_117504_Content_40 = {
    Text = "Thump. Thump. Your heartbeat is almost deafening."
  },
  AvgDialog_117504_Content_41 = {
    Text = "<Shake:Wait, what about the... sun in the sky?>"
  },
  AvgDialog_117504_Content_42 = {
    Text = "The sun? Is the sun not right there?"
  },
  AvgDialog_117504_Content_43 = {
    Text = "No, no, that is not the sun I'm talking about!"
  },
  AvgDialog_117504_Content_44 = {
    Text = "What rises above the sea level is a ball of gentle, warm light—a sun you should have yearned for."
  },
  AvgDialog_117504_Content_45 = {
    Text = "Not this sun? Which other sun is there?"
  },
  AvgDialog_117504_Content_46 = {
    Text = "The unusual heat from the warm light leaves you senseless and thirsty, and the words that escape your lips are hesitant and unclear."
  },
  AvgDialog_117504_Content_47 = {
    Text = "It should be a pitch-black, lightless sun!"
  },
  AvgDialog_117504_Content_48 = {
    Text = "I have never heard of or seen a black sun..."
  },
  AvgDialog_117504_Content_49 = {
    Text = "Faros, what year is it this year?"
  },
  AvgDialog_117504_Content_5 = {
    Text = "Faros kneels, carefully collecting the bloody remains piece by piece."
  },
  AvgDialog_117504_Content_50 = {
    Text = "1920 AD. Is something amiss?"
  },
  AvgDialog_117504_Content_51 = {
    Text = "AD... not \"After Flood\"... I truly am in the new world..."
  },
  AvgDialog_117504_Content_52 = {
    Text = "Do not be distracted. The Divine Mother is here."
  },
  AvgDialog_117504_Content_53 = {
    Text = "As a guest sanctioned by Her, I grant you permission to observe the most sacred pilotage ceremony here."
  },
  AvgDialog_117504_Content_54 = {
    Text = "But do not leave this place without my permission. Blasphemers shall be beheaded with their heads displayed to the public."
  },
  AvgDialog_117504_Content_55 = {
    Text = "A small team in black and purple emerges from the stern, their steps bizarrely synchronized as they crawl toward the deck beneath your feet."
  },
  AvgDialog_117504_Content_56 = {
    Text = "The girl at the forefront wears a pale white gown, cradling a bulky, swollen bundle. Her expression is indistinct and dazed beneath the black gauze."
  },
  AvgDialog_117504_Content_57 = {Text = "..."},
  AvgDialog_117504_Content_58 = {
    Text = "The line quickly holds firm at the bow of the ship, each black-clad figure already familiar with their landing point."
  },
  AvgDialog_117504_Content_59 = {
    Text = "A pair of bare feet steps into the narrow path left for her in the formation. Behind her, countless tiny silver fragments tumble down."
  },
  AvgDialog_117504_Content_6 = {
    Text = "A soft glow emanates from her forehead. Seconds later, only some silver-colored remnants remain."
  },
  AvgDialog_117504_Content_60 = {
    Text = "Divine Mother, receive our gratitude for the sacred blood! We swallow the flames of the spirit and drink the crimson prayer! Let a thousand devout souls now rise as the beacon light!"
  },
  AvgDialog_117504_Content_61 = {
    Text = "Monsters crawl on the ground, competing to pick up the silver beads on the floor."
  },
  AvgDialog_117504_Content_62 = {
    Text = "…Miryam…"
  },
  AvgDialog_117504_Content_63 = {
    Text = "Miryam humbly kneels, holding up a silver platter covered in black gauze, upon which lies a shimmering dagger."
  },
  AvgDialog_117504_Content_64 = {
    Text = "Esteemed Divine Mother, please guide the bloodline of the Godking to lead us lost Seafarers, and reveal the sacred path to Lemuria."
  },
  AvgDialog_117504_Content_65 = {
    Text = "The girl takes the dagger."
  },
  AvgDialog_117504_Content_66 = {
    Text = "O esteemed Godking..."
  },
  AvgDialog_117504_Content_67 = {
    Text = "The dagger pierces the swaddling. A drop of thick plasma gathers in mid-air, possessing a horrific will of its own."
  },
  AvgDialog_117504_Content_68 = {
    Text = "<Change>I follow Your Divine Blood."
  },
  AvgDialog_117504_Content_69 = {
    Text = "All believers kneel, their hands raised to the sky, using thin knives to cut open their scaled left wrists."
  },
  AvgDialog_117504_Content_7 = {
    Text = "Miryam... did you and Faros summon these flying fish?"
  },
  AvgDialog_117504_Content_70 = {
    Text = "Countless silver threads twine around the blood droplet, spreading outward from the wrists of over a hundred believers, extending along an elusive trail."
  },
  AvgDialog_117504_Content_71 = {
    Text = "<Change>Offer the spirits of the multitude as sacrifice."
  },
  AvgDialog_117504_Content_72 = {
    Text = "The ink-colored blood droplet spins, condenses, and leaps onto a milky-white ivory sculpture, seeping into a dense network of fine blood threads."
  },
  AvgDialog_117504_Content_73 = {
    Text = "Infused with life, the ivory sculpture soars over the steel behemoth and plunges straight into the silent ocean."
  },
  AvgDialog_117504_Content_74 = {
    Text = "<Change>Please rend the false Abyss and guide us directly to Your Kingdom."
  },
  AvgDialog_117504_Content_75 = {
    Text = "Instantly, the sea and sky tremble. The vast ocean surges with raging waves, emitting a wail like that of a giant beast in labor."
  },
  AvgDialog_117504_Content_76 = {
    Text = "The wind and waves dance wildly, weeping, forming a terrifying, trembling wall of water."
  },
  AvgDialog_117504_Content_77 = {
    Text = "Divine Mother, the amount of spiritual energy in this batch might be insufficient..."
  },
  AvgDialog_117504_Content_78 = {
    Text = "It is of no matter."
  },
  AvgDialog_117504_Content_79 = {
    Text = "The maiden lifts her veil, turning to face the kneeling beings."
  },
  AvgDialog_117504_Content_8 = {
    Text = "Miryam seems to only notice your presence now. She tilts her head slightly in your direction."
  },
  AvgDialog_117504_Content_80 = {
    Text = "Divine Mother, bestow us your blood!"
  },
  AvgDialog_117504_Content_81 = {
    Text = "<Big:<Shake:Divine Mother, bestow us your blood!>>"
  },
  AvgDialog_117504_Content_82 = {
    Text = "The sound waves rise higher. Amidst the shouts, the maiden's fingertips reach toward her chest."
  },
  AvgDialog_117504_Content_83 = {
    Text = "Her nails, sharp as blades, tear open her chest along the purple scar, revealing the single, remaining heart."
  },
  AvgDialog_117504_Content_84 = {
    Text = "<Shake:Hunt! Feast! I offer you the flesh and blood of the Divine Mother, and you shall forge for me the reverse staircase to the Divine Realm!>"
  },
  AvgDialog_117504_Content_85 = {
    Text = "The congregation surges forward. Their flippers and strange pincers eagerly reach out toward the Divine Mother's frail body."
  },
  AvgDialog_117504_Content_86 = {
    Text = "They drain her blood and feast on her flesh. Crimson threads then violently proliferate, rushing into the deep sea."
  },
  AvgDialog_117504_Content_87 = {
    Text = "Crimson waves of blood spread wildly from the ivory sculpture, solidifying into millions of blood corals amidst the turmoil."
  },
  AvgDialog_117504_Content_88 = {
    Text = "The ritual is complete! Step back, all of you!"
  },
  AvgDialog_117504_Content_89 = {
    Text = "She steps forward, treading on the bodies of the Seafarers clustered in front of Murphy, wrapping the maiden's body in a heavy black robe. Beneath the robe, streams of blood continue to flow steadily."
  },
  AvgDialog_117504_Content_9 = {
    Text = "Should you not be in the Divine Mother's chamber? Why..."
  },
  AvgDialog_117504_Content_90 = {
    Text = "Lemuria! Lemuria! Her Holiness Divine Mother's blood has revealed the path to Lemuria!"
  },
  AvgDialog_117504_Content_91 = {
    Text = "Among the thousands of bloodlines, you catch a glimpse of an unusual silver thread. That thread emerges from your own chest, extending upward... extending..."
  },
  AvgDialog_117504_Content_92 = {
    Text = "...until it vanishes somewhere beyond the heavens."
  },
  AvgDialog_117504_Content_93 = {
    Text = "The maiden seems to realize that silver thread's existence. She looks up, her pupils suddenly trembling, and her horrified gaze pierces directly to your hiding place."
  },
  AvgDialog_117504_Content_94 = {Text = "..."},
  AvgDialog_117504_Content_95 = {
    Text = "In the moment your gazes meet, an invisible, immense force pulls at you, disregarding your full resistance, plunging you straight into a terrifying, nightmarish illusion."
  },
  AvgDialog_117504_Content_96 = {
    Text = "...You see the unclean black sun again."
  },
  AvgDialog_117504_Content_97 = {
    Text = "A hand drum?"
  },
  AvgDialog_117504_Content_98 = {
    Text = "No. That is the sound of a heartbeat."
  },
  AvgDialog_117504_Content_99 = {
    Text = "Long, suffocating, near-death; long gone before the ancient times, yet revived after the Long Dream..."
  },
  AvgDialog_118123_Content_1 = {
    Text = "Windmill Knight"
  },
  AvgDialog_118123_Content_10 = {
    Text = "It is precisely with such hopes that I pardoned {Male=him,Female=her} for {Male=his,Female=her} rudeness."
  },
  AvgDialog_118123_Content_11 = {
    Text = "(In the end... nothing changed...)"
  },
  AvgDialog_118123_Content_12 = {
    Text = "I knew it... You need my help."
  },
  AvgDialog_118123_Content_13 = {
    Text = "Running around like a headless chicken! Where on earth are you going!"
  },
  AvgDialog_118123_Content_14 = {
    Text = "What William said earlier. We're gonna go take the lifeboat in the hold!"
  },
  AvgDialog_118123_Content_15 = {
    Text = "The deck's vision is wide open! You are trying to feed yourself to the fish-people!"
  },
  AvgDialog_118123_Content_16 = {
    Text = "In the last cycle, you were the one who got fed to them!"
  },
  AvgDialog_118123_Content_17 = {
    Text = "Don't you dare talk back to the Divine Mother! Run to the bridge! There's a structure that leads to the escape pod!"
  },
  AvgDialog_118123_Content_18 = {
    Text = "And let me down! My hair is already a mess!"
  },
  AvgDialog_118123_Content_19 = {
    Text = "You are my important hostage; this is not the time to worry about appearances! Please, dear Divine Mother, endure just a little longer!"
  },
  AvgDialog_118123_Content_2 = {
    Text = "You leap down, feeling the sharp wind slicing against your cheeks, and then the rope around your waist suddenly tightens, halting your fall."
  },
  AvgDialog_118123_Content_20 = {
    Text = "<Shake:Careful, Miryam's minions are catching up!>"
  },
  AvgDialog_118123_Content_3 = {
    Text = "Hey! What are you doing!"
  },
  AvgDialog_118123_Content_4 = {
    Text = "You cut the rope with a small knife, and then leap to the ground."
  },
  AvgDialog_118123_Content_5 = {
    Text = "Are you just going to run away with me on your back? They'll be catching up to us soon!"
  },
  AvgDialog_118123_Content_6 = {
    Text = "Ahhh, you're so stupid, it's killing me!"
  },
  AvgDialog_118123_Content_7 = {
    Text = "What was I thinking, to have had even a glimmer of hope for this fool."
  },
  AvgDialog_118123_Content_8 = {
    Text = "This escape is more reckless than any I tried in the past."
  },
  AvgDialog_118123_Content_9 = {
    Text = "<Italic:If <Yellow:%player%> exists in this world, will the direction of the story be different?>"
  },
  AvgDialog_118124_Content_1 = {
    Text = "You tear down the veil to bind Murphy with it, ignoring her struggle."
  },
  AvgDialog_118124_Content_10 = {
    Text = "If you observe the three of us closely, you'll realize the real princess among us isn't me."
  },
  AvgDialog_118124_Content_11 = {
    Text = "William tightly ties the rope around you and Murphy."
  },
  AvgDialog_118124_Content_12 = {
    Text = "Take good care of our princess; don't lose her! There are lifeboats in the lower deck. I'll see you there!"
  },
  AvgDialog_118124_Content_13 = {
    Text = "Three, two, one, jump!"
  },
  AvgDialog_118124_Content_2 = {
    Text = "All set! Stop moving. Don't hurt yourself!"
  },
  AvgDialog_118124_Content_3 = {
    Text = "Ugh! I'm going to bite you!"
  },
  AvgDialog_118124_Content_4 = {
    Text = "It's more like you to be this way without putting on airs, Murphy."
  },
  AvgDialog_118124_Content_5 = {
    Text = "Stop wasting time! Your punishment for insulting the Divine Mother will be executed once I regain my freedom!"
  },
  AvgDialog_118124_Content_6 = {
    Text = "The footsteps outside... Are they getting more frequent?"
  },
  AvgDialog_118124_Content_7 = {
    Text = "The sound of pattering footsteps converges into a sea, as short and stout bodies continuously slam against the living room door, producing dull thuds."
  },
  AvgDialog_118124_Content_8 = {
    Text = "Let's go, we'll break the window and get out! Grab this, then jump onto the deck!"
  },
  AvgDialog_118124_Content_9 = {
    Text = "Tying knots with bed sheets...? William, you sound like a runaway princess from a fairy tale."
  },
  AvgDialog_118125_Content_1 = {
    Text = "Tower Princess"
  },
  AvgDialog_118125_Content_10 = {
    Text = "You observe closely: there are two broken strands of thread, and four loops of thread are still wound on the spinning wheel."
  },
  AvgDialog_118125_Content_11 = {
    Text = "I have... four chances left?"
  },
  AvgDialog_118125_Content_12 = {
    Text = "She nods, and then she shakes her head."
  },
  AvgDialog_118125_Content_13 = {
    Text = "I've heard your singing. You're not mute... You are just not allowed to say anything...?"
  },
  AvgDialog_118125_Content_14 = {
    Text = "She opens her mouth, but all that comes out is an eternal silence."
  },
  AvgDialog_118125_Content_15 = {
    Text = "She gazes back at the distant sky. You follow her gaze into the distance."
  },
  AvgDialog_118125_Content_16 = {
    Text = "There is only a black sun submerged in the water."
  },
  AvgDialog_118125_Content_17 = {
    Text = "Cough, cough...!"
  },
  AvgDialog_118125_Content_18 = {
    Text = "You suddenly wake up in bed, gasping loudly due to the pain of drowning."
  },
  AvgDialog_118125_Content_19 = {
    Text = "I'm back... once again..."
  },
  AvgDialog_118125_Content_2 = {
    Text = "The sea breeze is salty and fishy, bringing an indelible bitter taste when it blows into your mouth."
  },
  AvgDialog_118125_Content_20 = {
    Text = "The four people around you—whether surprised, indifferent, genuinely caring, or feigning concern—you cannot bring yourself to care. The only thing lingering in your mind is Murphy's face before the last cycle ended."
  },
  AvgDialog_118125_Content_21 = {
    Text = "Help me... I know you can..."
  },
  AvgDialog_118125_Content_22 = {
    Text = "Then darkness engulfs everything, turning into an indelible doubt in your mind."
  },
  AvgDialog_118125_Content_23 = {
    Text = "In any case, you need to meet up with William first."
  },
  AvgDialog_118125_Content_24 = {
    Text = "Goliath and Miryam walk down an empty corridor, their footsteps echoing in front and behind."
  },
  AvgDialog_118125_Content_25 = {
    Text = "They pass the Baroque-style Divine Mother mural, the small lanterns replacing the brass wall sconces, and the quiet, empty dormitory."
  },
  AvgDialog_118125_Content_26 = {
    Text = "They make no contact or speak; a tense atmosphere hangs between the two."
  },
  AvgDialog_118125_Content_27 = {
    Text = "Miryam stops at the door of the captain's room and turns to push the door open."
  },
  AvgDialog_118125_Content_28 = {
    Text = "Goliath catches up a few steps and stands behind her."
  },
  AvgDialog_118125_Content_29 = {
    Text = "Hey, Miryam. That little girl is lying to you."
  },
  AvgDialog_118125_Content_3 = {Text = "..."},
  AvgDialog_118125_Content_30 = {
    Text = "What do you wish to talk about? You should be guarding the bridge, should you not?"
  },
  AvgDialog_118125_Content_31 = {
    Text = "If anything happens to that woman sustaining the engine room, you know the consequence."
  },
  AvgDialog_118125_Content_32 = {
    Text = "Stop talking nonsense. We have Caecus there. Those brainless crew members can't stir up any trouble."
  },
  AvgDialog_118125_Content_33 = {
    Text = "The only crux is this: the little girl is lying to you."
  },
  AvgDialog_118125_Content_34 = {
    Text = "Philistine. Slandering the Divine Mother is not your usual behavior."
  },
  AvgDialog_118125_Content_35 = {
    Text = "You know this ship will never reach that Lemuria, right?"
  },
  AvgDialog_118125_Content_36 = {
    Text = "...Goliath."
  },
  AvgDialog_118125_Content_37 = {
    Text = "You are merely my reared hound. Unless I command you to swing your blade at a specific enemy, you are not permitted to speak."
  },
  AvgDialog_118125_Content_38 = {
    Text = "Before we reach the shore, your only order is to manage those sailors for me and ensure they do not disturb the Divine Mother's slumber."
  },
  AvgDialog_118125_Content_39 = {
    Text = "If there is something you must know..."
  },
  AvgDialog_118125_Content_4 = {
    Text = "The woman holding a spinning wheel gazes at you with a sorrowful expression."
  },
  AvgDialog_118125_Content_40 = {
    Text = "<Shake:If this ship has even the slightest chance of reaching Lemuria, it is solely thanks to the blessing of our Divine Mother.>"
  },
  AvgDialog_118125_Content_41 = {
    Text = "Tsk, you stubborn, vile woman..."
  },
  AvgDialog_118125_Content_42 = {
    Text = "I've already said what needs to be said."
  },
  AvgDialog_118125_Content_43 = {
    Text = "Don't blame me for whatever happens next."
  },
  AvgDialog_118125_Content_44 = {
    Text = "Caecus, execute the plan."
  },
  AvgDialog_118125_Content_45 = {
    Text = "Yes, Lord Goliath!"
  },
  AvgDialog_118125_Content_46 = {
    Text = "Take control of the ship before the ritual is complete."
  },
  AvgDialog_118125_Content_47 = {
    Text = "You wander the deck, struggling to search for clues that might lead to William's hiding place."
  },
  AvgDialog_118125_Content_48 = {
    Text = "If I remember correctly, it's right here..."
  },
  AvgDialog_118125_Content_49 = {
    Text = "You pry open the hatch along the gap on the deck, grit your teeth, and leap down."
  },
  AvgDialog_118125_Content_5 = {
    Text = "Is there something you want to tell me?"
  },
  AvgDialog_118125_Content_50 = {
    Text = "<Shake:Cough, bleh...>"
  },
  AvgDialog_118125_Content_51 = {
    Text = "You cough out the bulrush in your mouth, regretting your choice of a head-first landing."
  },
  AvgDialog_118125_Content_52 = {
    Text = "William, stop hiding! I know you're here!"
  },
  AvgDialog_118125_Content_53 = {
    Text = "After a while, a few rustling sounds come from behind the thatch pile."
  },
  AvgDialog_118125_Content_54 = {
    Text = "This doesn't make sense."
  },
  AvgDialog_118125_Content_55 = {
    Text = "...If you had such precise ability to locate me, you would have already caught up with me on the streets of London."
  },
  AvgDialog_118125_Content_56 = {
    Text = "Let's talk about it... What have you experienced since boarding this ship?"
  },
  AvgDialog_118125_Content_57 = {Text = "..."},
  AvgDialog_118125_Content_58 = {
    Text = "You briefly summarized what you experienced in the time loop."
  },
  AvgDialog_118125_Content_59 = {
    Text = "Sorry, there won't be enough time once the ceremony starts. William, we must lift the ambush in the other Murphy's living room."
  },
  AvgDialog_118125_Content_6 = {
    Text = "The woman nods."
  },
  AvgDialog_118125_Content_60 = {
    Text = "Go. Follow me, I know how to avoid the guards."
  },
  AvgDialog_118125_Content_61 = {
    Text = "You mean Goliath is plotting a rebellion, and I have to go hide with you..."
  },
  AvgDialog_118125_Content_62 = {
    Text = "And you know all of that in advance because you experienced a time loop?"
  },
  AvgDialog_118125_Content_63 = {
    Text = "So absurd, so ridiculous... unless I'm not in my right mind... <Shake:Mmpff!>"
  },
  AvgDialog_118125_Content_64 = {
    Text = "Sorry, we're running out of time. You're coming with us."
  },
  AvgDialog_118125_Content_65 = {Text = "William!"},
  AvgDialog_118125_Content_66 = {
    Text = "Don't worry, I anticipated this. I've already blocked the sounds from outside the living room."
  },
  AvgDialog_118125_Content_67 = {
    Text = "Take her away first!"
  },
  AvgDialog_118125_Content_7 = {
    Text = "Is it related to the time loop?"
  },
  AvgDialog_118125_Content_8 = {
    Text = "The woman shakes her head. Her fingertips brush over the yarn of the spinning wheel, making a clockwise rotation before stopping at the starting point."
  },
  AvgDialog_118125_Content_9 = {
    Text = "As the spinning wheel turns, the original thread disintegrates and breaks."
  },
  AvgDialog_118699_Content_1 = {Text = "Our Wish"},
  AvgDialog_118699_Content_10 = {
    Text = "More intense spiritual energy, huh... I understand. I'll notify all Awakeners."
  },
  AvgDialog_118699_Content_11 = {
    Text = "On the playground at dusk, Ogier finishes his daily training as usual, not skipping a single rep."
  },
  AvgDialog_118699_Content_12 = {
    Text = "I broke a previous record again today..."
  },
  AvgDialog_118699_Content_13 = {
    Text = "Wiping away the flowing sweat, he supports himself with the heavy spear. Ogier turns around, but the person who would have smiled and offered encouragement is no longer there. Only his own lonely shadow stretches long across the ground."
  },
  AvgDialog_118699_Content_14 = {
    Text = "Lotan's rapier parries and flicks away the weapons of two Investigators, ending yet another battle that lasts only a minute."
  },
  AvgDialog_118699_Content_15 = {
    Text = "What's going on with the freshmen these days? Come on! They're too weak!"
  },
  AvgDialog_118699_Content_16 = {
    Text = "Before she can raise her sword to continue bullying, the two panting freshmen before her are already clasping their hands in pleading surrender."
  },
  AvgDialog_118699_Content_17 = {
    Text = "Tsk, boring..."
  },
  AvgDialog_118699_Content_18 = {
    Text = "Lotan sighs at the setting sun and turns away listlessly, remembering the exhilarating battles she once had with a certain someone."
  },
  AvgDialog_118699_Content_19 = {
    Text = "Aigis cuts the final strand of yarn, carefully unfolds the newly knitted sweater, smooths it, and then tiptoes to hang it in the wardrobe filled with knitwear."
  },
  AvgDialog_118699_Content_2 = {
    Text = [[
World#Kadath
Now]]
  },
  AvgDialog_118699_Content_20 = {
    Text = "I've learned a lot more patterns now. I can do cable-knit, waffle stitch, ripple stitch, shell stitch, and fair isle patterns."
  },
  AvgDialog_118699_Content_21 = {
    Text = "I wonder what kind you would like, %player%..."
  },
  AvgDialog_118699_Content_22 = {
    Text = "The clever gray mouse scurries through the door gap, faithfully placing a shiny ring into its partner's hand."
  },
  AvgDialog_118699_Content_23 = {
    Text = "Well done, Brown."
  },
  AvgDialog_118699_Content_24 = {
    Text = "Jenkin yawns in boredom, casually tosses the ring into an open wooden box nearby, which overflows with a jumbled mess of \"treasures.\""
  },
  AvgDialog_118699_Content_25 = {Text = "Squeak..."},
  AvgDialog_118699_Content_26 = {
    Text = "That person used to demand Jenkin return all the stolen treasures one by one, but {Male=he,Female=she} hasn't showed up in a long time. So why is she still feeling down? Brown wonders."
  },
  AvgDialog_118699_Content_27 = {
    Text = "Lily sits neatly at the desk and opens another storybook."
  },
  AvgDialog_118699_Content_28 = {
    Text = "A tall stack of finished children's books has piled up on the corner of the desk, and the girl jots down story ideas in the notebook beside her."
  },
  AvgDialog_118699_Content_29 = {
    Text = "When excited by an idea, a faint smile appears on the girl's tranquil face, and her feet begin to gently sway under the desk."
  },
  AvgDialog_118699_Content_3 = {
    Text = "The blurry, half-formed tunnel collapses as a sudden, terrifying corrosion strikes. Ramona lets out a muffled groan as her consciousness is forcibly recalled by the emergency system."
  },
  AvgDialog_118699_Content_30 = {
    Text = "Yes, they will all like this story..."
  },
  AvgDialog_118699_Content_31 = {
    Text = "The pencil dances as it records innocent fantasies. But soon, Lily stops writing, staring blankly out the window."
  },
  AvgDialog_118699_Content_32 = {
    Text = "But when will you come back... and make another movie with me?"
  },
  AvgDialog_118699_Content_33 = {Text = "..."},
  AvgDialog_118699_Content_34 = {
    Text = "Helot tips the wineskin, pouring the content onto the ground in front of the tombstone."
  },
  AvgDialog_118699_Content_35 = {
    Text = "After downing the remaining half-flask of wine in one gulp, the warrior departs in silence, leaving only a laurel wreath hanging quietly on the gravestone."
  },
  AvgDialog_118699_Content_36 = {
    Text = "Upon the luxurious velvet tablecloth, Murphy's afternoon tea is as sumptuous as ever."
  },
  AvgDialog_118699_Content_37 = {
    Text = "Cutlery clinks against the plate as she sends the rich cream cake into her mouth."
  },
  AvgDialog_118699_Content_38 = {
    Text = "She eats her cake in an unnatural silence while staring blankly at the empty chair across from her, where that person's dedicated tableware is placed."
  },
  AvgDialog_118699_Content_39 = {
    Text = "Leaving a lady like me all alone here... what an incompetent servant you are."
  },
  AvgDialog_118699_Content_4 = {
    Text = "Ramona! Pollux! Are you both alright?"
  },
  AvgDialog_118699_Content_40 = {
    Text = "In a specially reserved, empty dorm room, the neat and brand-new furnishings seem uninhabited, with only a freshly sprouted sapling placed by the window."
  },
  AvgDialog_118699_Content_41 = {
    Text = "On rare occasions, someone might see a honey-skinned woman behind that window, leaning on the windowsill, gently cradling the potted sapling."
  },
  AvgDialog_118699_Content_42 = {
    Text = "Even though the club activities have gradually revived and become lively now, this music classroom belonging to the master performer still has no one daring to disturb it easily."
  },
  AvgDialog_118699_Content_43 = {Text = "..."},
  AvgDialog_118699_Content_44 = {
    Text = "The curtain is gently lifted by the night breeze as Hameln stands before the piano, gazing toward the clock tower."
  },
  AvgDialog_118699_Content_45 = {
    Text = "The piano they once shared stands unused. Only the sound of Hameln's flute, repeated day after day, quietly drifts under the moonlight, unheard by anyone."
  },
  AvgDialog_118699_Content_46 = {
    Text = "In the depths of the Black Pool, the eternally lonely prisoner behind the gate now has a slumbering companion."
  },
  AvgDialog_118699_Content_47 = {
    Text = "Tawil's compassionate eyes open silently, gazing at the shell whose soul drifts far away."
  },
  AvgDialog_118699_Content_48 = {
    Text = "In the Research Department laboratory, Ramona soaks her training suit with sweat, tirelessly conducting mental training day and night."
  },
  AvgDialog_118699_Content_49 = {
    Text = "Doll stares at her while sipping another cup of strong coffee, flips to a new page of the experiment report, and continues to debug the instrument's data."
  },
  AvgDialog_118699_Content_5 = {
    Text = "Cough... I'm fine. The cut-off was timely."
  },
  AvgDialog_118699_Content_50 = {
    Text = "<Small:Ah, Winkle's coffee is indeed a bit too strong...>"
  },
  AvgDialog_118699_Content_51 = {
    Text = "A notification sent to all Awakeners flashes on the communicator she had just set down."
  },
  AvgDialog_118699_Content_52 = {
    Text = "Every Awakener on campus simultaneously glances at their suddenly ringing communicators, their eyes locking onto the name they have waited for in the screen."
  },
  AvgDialog_118699_Content_53 = {
    Text = [[
To all Mythag Awakeners,

Not long ago, we stood united against the all-consuming black disaster. To this day, the gravestones in the Keygrave bear witness to countless sacrifices, including the loss of the Keeper, who secured our ultimate peace.
{Male=He,Female=She} was a comrade, a confidant, a student who mastered the art of skipping class, a very dear friend to many, our singular guide, and the hero who saved us all.]]
  },
  AvgDialog_118699_Content_54 = {
    Text = [[
Mythag sustained a profound loss with {Male=his,Female=her} disappearance. While sharing this collective sorrow, the Research Department has maintained a focused effort to locate traces of the Keeper's consciousness.
Originally, I intended to withhold this information until success was secured, unwilling to subject our community to the added burden of prolonged, uncertain hope. However, we have now verified a viable methodology for locating <Yellow:%player%> and will initiate the final retrieval attempt shortly.]]
  },
  AvgDialog_118699_Content_55 = {
    Text = [[
This operation requires the participation of every Awakener. We must transform the concentrated dedication of us all for <Yellow:%player%> into the spiritual energy necessary to act as the navigational beacon that guides {Male=him,Female=her} home.
On behalf of Mythag, I formally request your presence before the Black Pool. I invite us all to stand together, as we did during the final battle, and fight side by side once more for <Yellow:%player%>.

Your comrade,
Doll]]
  },
  AvgDialog_118699_Content_56 = {
    Text = [[
World#Kadath
The Day of Reunion]]
  },
  AvgDialog_118699_Content_57 = {
    Text = "Beneath the clock tower's restricted area, a quiet crowd stands before the silent Black Pool."
  },
  AvgDialog_118699_Content_58 = {
    Text = "After Doll explains the principles of dimensional travel, the Awakeners who had been clamoring to go now stand silently by the Spirit Resonance Device."
  },
  AvgDialog_118699_Content_59 = {
    Text = "Due to the spiritual characteristics of the dimensional space, the more spirits appear together, the more attention will be drawn from higher beings. The Keeper on the other side will find {Male=his,Female=her} defense even more arduous."
  },
  AvgDialog_118699_Content_6 = {
    Text = "Why... I clearly heard {Male=his,Female=her} voice just now. Why can't I find {Male=him,Female=her}?"
  },
  AvgDialog_118699_Content_60 = {
    Text = "In front of the crowd, Ramona holds a bouquet of withered roses, quietly gazing at the Black Pool. In her other hand, she clutches the Silver Key numbered 0617 tightly."
  },
  AvgDialog_118699_Content_61 = {
    Text = "The instrument is ready to start. Everyone, focus your minds."
  },
  AvgDialog_118699_Content_62 = {
    Text = "Doll presses the button, and a wave of spiritual energy ripples out, weaving everyone's spirits into threads, forming a giant, connecting net."
  },
  AvgDialog_118699_Content_63 = {
    Text = "Ramona solemnly opens her palm, and the Silver Key slowly rises in a strange gravitational pull, floating in the center of the invisible net, flickering with a breath-like glow."
  },
  AvgDialog_118699_Content_64 = {
    Text = "Everyone stares at the key, offering silent prayers."
  },
  AvgDialog_118699_Content_65 = {
    Text = "This school, the people here, all need you. Whether it's one year, two years, ten years... as long as the research remains meaningful, we will bring you back."
  },
  AvgDialog_118699_Content_66 = {
    Text = "My lord, I can now hold on for 40 seconds without a link. I can protect you better now, and I really want to show you the results of my training..."
  },
  AvgDialog_118699_Content_67 = {
    Text = "There will never be another student of Mythag as tough as you. When will you let me experience a battle under your command again?"
  },
  AvgDialog_118699_Content_68 = {
    Text = "I've been a good girl. I eat my vegetables on time. I've knitted a lot of scarves, hats, gloves, and all sorts of sweaters, just for you! Will you... like them?"
  },
  AvgDialog_118699_Content_69 = {
    Text = "West-Whelp, you haven't finished learning the survival secrets of the East District that I promised to teach you. I've already taken the tuition, so hurry back and don't let this master thief's business reputation suffer..."
  },
  AvgDialog_118699_Content_7 = {
    Text = "Same here. My \"Sacred Heart\" can only sense {Male=his,Female=her} general direction, but I don't have a detailed coordinate."
  },
  AvgDialog_118699_Content_70 = {
    Text = "{Male=Mr,Female=Miss} Keeper, I believe that kind people are always blessed with good fortune. Someone like you is sure to have a happy ending."
  },
  AvgDialog_118699_Content_71 = {
    Text = "%player%, Lily can read many storybooks now. When you come back, can we make a movie again?"
  },
  AvgDialog_118699_Content_72 = {
    Text = "A victorious warrior should return to {Male=his,Female=her} homeland."
  },
  AvgDialog_118699_Content_73 = {
    Text = "Hurry back, you silly servant! You owe me so many afternoon teas, and you'd better make up for all of them properly!"
  },
  AvgDialog_118699_Content_74 = {
    Text = "You once asked me what my wish was... Now I finally have my own wish: I hope you can come back safely."
  },
  AvgDialog_118699_Content_75 = {
    Text = "My untrustworthy sapling... You promised me a renewed world, and you delivered; but you can't leave me alone here..."
  },
  AvgDialog_118699_Content_76 = {
    Text = "Our tribe will not leave any member behind."
  },
  AvgDialog_118699_Content_77 = {
    Text = "My flute shall forever keep watch for you."
  },
  AvgDialog_118699_Content_78 = {
    Text = "All the Awakeners silently recite that familiar name. Streams of spiritual energy, flowing like fireflies, converge into the suspended Silver Key. The center of the key gradually begins to shine like a star."
  },
  AvgDialog_118699_Content_79 = {
    Text = "Pollux and Castor exchange a glance, nodding at each other. In an instant, Castor's body transforms into a streak of light and merges into Pollux's chest."
  },
  AvgDialog_118699_Content_8 = {
    Text = "However, Miss Ramona's intense wish in that last moment has made my perception of {Male=his,Female=her} location much clearer."
  },
  AvgDialog_118699_Content_80 = {
    Text = "An emerald glow swirls within the <Blue:Sacred Heart>. Behind Pollux, a pair of magnificent <Blue:Onyx Plumes> unfurls. He points his finger, and the artificial heart flashes in response to the Silver Key's brilliance."
  },
  AvgDialog_118699_Content_81 = {
    Text = "Miss Ramona."
  },
  AvgDialog_118699_Content_82 = {
    Text = "Meeting Pollux's solemn gaze, Ramona tightly grasps the glowing rose in her hand—the signal she had agreed upon with the Keeper."
  },
  AvgDialog_118699_Content_83 = {
    Text = "The spiritual strength, honed through countless rehearsals, gradually coalesces following the familiar guidance. She lifts her head and gazes at the Silver Key, pouring her wishes into its center along with everyone else's."
  },
  AvgDialog_118699_Content_84 = {
    Text = "(<Yellow:%player%>, please wait for me. I'm coming to bring you home.)"
  },
  AvgDialog_118699_Content_9 = {
    Text = "If we gather more intense spiritual energy directed at <Yellow:%player%>, perhaps I can pinpoint %player%'s location more precisely."
  },
  AvgDialog_118700_Content_1 = {
    Text = "Momentary Embrace"
  },
  AvgDialog_118700_Content_10 = {
    Text = "The surrounding noise fades away. Deep within her mind, Ramona gazes at that distant self."
  },
  AvgDialog_118700_Content_11 = {
    Text = "Your power is greater than mine... Perhaps this task should be undertaken by you, to ensure its success..."
  },
  AvgDialog_118700_Content_12 = {
    Text = "Sensing Ramona's inner thoughts, Ramona: Timeworn shakes her head, raising her veiled eyes to quietly observe the abyss."
  },
  AvgDialog_118700_Content_13 = {
    Text = "I'm only here to see you off. On such a distant journey through dimensions, there's really no difference between you and me. Moreover..."
  },
  AvgDialog_118700_Content_14 = {
    Text = "You are {Male=his,Female=her} partner. This is your shared destiny, not mine."
  },
  AvgDialog_118700_Content_15 = {
    Text = "Go. Go bring {Male=him,Female=her} back, \"Ramona\"."
  },
  AvgDialog_118700_Content_16 = {
    Text = "Ramona's hand tightens around the rose. After a long moment, she nods solemnly, and under the gaze of her other self, seats herself within the Spirit Separation Device."
  },
  AvgDialog_118700_Content_17 = {
    Text = "Her physical eyes close tightly, while another pair of eyes slowly opens. A solidified soul detaches from her body, coated in a hazy, veil-like white light by the radiance of Pollux's \"Sacred Heart.\""
  },
  AvgDialog_118700_Content_18 = {
    Text = "Under the gaze of dozens of eyes, Ramona turns, meeting the gazes of her comrades one by one, shouldering the weight of those heavy hopes."
  },
  AvgDialog_118700_Content_19 = {
    Text = "Guided by those yearnings, she turns and leaps into the massive vortex. The entrance, resembling a gate to Hell, engulfs the solitary soul in an instant."
  },
  AvgDialog_118700_Content_2 = {
    Text = "Pollux hovers high above like an angel brimming with holy light, waiting to guide the lost soul to the side of god."
  },
  AvgDialog_118700_Content_3 = {
    Text = "After exchanging a glance, Doll and Ramona activate the massive device that covers nearly half of the Black Pool. In the violent turbulence of the pool water, the enormous vortex collapses with a roar, creating an abyss that seems ready to devour everything."
  },
  AvgDialog_118700_Content_4 = {Text = "That is..."},
  AvgDialog_118700_Content_5 = {
    Text = "The majestic pool of water flows down into another world, and within the bottomless vortex, the existence of the world begins to blur."
  },
  AvgDialog_118700_Content_6 = {
    Text = "The edge of this world, the entrance to the dimensional space."
  },
  AvgDialog_118700_Content_7 = {
    Text = "Beyond the abyss, {Male=he,Female=she} is waiting for you."
  },
  AvgDialog_118700_Content_8 = {
    Text = "Ramona nods. Just before stepping into the abyss, she suddenly pauses and looks back at the crowd."
  },
  AvgDialog_118700_Content_9 = {
    Text = "A faint figure stands silently behind the praying crowd. A presence hidden deep within her consciousness, visible only to her."
  },
  AvgDialog_118701_Content_1 = {Text = "Waiting"},
  AvgDialog_118701_Content_10 = {
    Text = "The mist gathers and dissipates, and a Mythag regular appears at the entrance of the Black Pool, quietly standing next to Doll, gazing together at the figure sitting motionless in front of the \"Gate.\""
  },
  AvgDialog_118701_Content_11 = {
    Text = "Long-term exposure to pool water isn't good for her health. Aren't you going to stop her?"
  },
  AvgDialog_118701_Content_12 = {
    Text = "I gave her basic protective gear. Physical damage is something I can still treat, but psychological damage isn't so easy to cure."
  },
  AvgDialog_118701_Content_13 = {
    Text = "The rational professor sighs and turns her head inquisitively."
  },
  AvgDialog_118701_Content_14 = {
    Text = "You rarely come here willingly. What have you brought this time?"
  },
  AvgDialog_118701_Content_15 = {
    Text = "Ah, a piece of good news that might just heal her soul."
  },
  AvgDialog_118701_Content_16 = {
    Text = "Partner, thanks to your great feat, there have been significantly fewer D-Rifts worldwide recently."
  },
  AvgDialog_118701_Content_17 = {
    Text = "The investigators at the school have become more relaxed. Everyone just attends classes and takes exams every day. Mythag is becoming more and more like an ordinary university."
  },
  AvgDialog_118701_Content_18 = {
    Text = "Someone suggested building a statue for you, right next to Headmaster Ward's. The school is still considering it."
  },
  AvgDialog_118701_Content_19 = {
    Text = "I submitted an unsupported suggestion. You are still right here—why should you be made into a statue like the headmaster?"
  },
  AvgDialog_118701_Content_2 = {
    Text = [[
World#Kadath
Before the Keeper's funeral]]
  },
  AvgDialog_118701_Content_20 = {
    Text = "Besides, when you come back and see your huge self standing next to the principal, you'd be so awkward and speechless."
  },
  AvgDialog_118701_Content_21 = {
    Text = "Your expression is so peaceful, I don't believe... You must have gotten lost in another world and forgotten how to return..."
  },
  AvgDialog_118701_Content_22 = {
    Text = "You are right, {Male=he,Female=she} has indeed entered another dimension, a very distant dimension."
  },
  AvgDialog_118701_Content_23 = {
    Text = "Hearing Daffodil's sudden voice behind her, Ramona stands up, nearly losing her composure, barely restraining herself from grabbing the shopkeeper's arm."
  },
  AvgDialog_118701_Content_24 = {
    Text = "What did you say? Did you find {Male=him,Female=her}? Dimension... I remember you can travel between dimensions!"
  },
  AvgDialog_118701_Content_25 = {
    Text = "How can I bring {Male=him,Female=her} back? I would pay any price!"
  },
  AvgDialog_118701_Content_26 = {
    Text = "After this impassioned plea, Ramona finally notices Doll's unsmiling expression beside her."
  },
  AvgDialog_118701_Content_27 = {Text = "...What?"},
  AvgDialog_118701_Content_28 = {
    Text = "Your determination is touching, but unfortunately, that dimension is not connected to this world. Moreover, I have no way to take the Keeper across unknown dimensional space."
  },
  AvgDialog_118701_Content_29 = {
    Text = "Without finding a definite route, recklessly traversing the dimensional turbulence will only lead to one outcome: getting lost forever."
  },
  AvgDialog_118701_Content_3 = {
    Text = "With a low hum signaling the completion of the test, the instruments once again display a null result. Doll silently waves her hand, and the researchers exchange glances, tacitly beginning to dismantle the equipment."
  },
  AvgDialog_118701_Content_30 = {
    Text = "With Mythag's current technology, it is impossible to achieve this."
  },
  AvgDialog_118701_Content_31 = {
    Text = "What does it mean... We've tried for so long, and finally have news about {Male=him,Female=her}—are we really going to leave {Male=him,Female=her} stranded out there alone?!"
  },
  AvgDialog_118701_Content_32 = {
    Text = "I might still be able to discuss the technique of dimensional travel with Professor Doll, just consider it a gift for a loyal customer."
  },
  AvgDialog_118701_Content_33 = {
    Text = "But when it comes to retrieving <Yellow:%player%>, the most difficult part is finding the path to that specific world. Even my collection doesn't contain such a treasure that transcends the universe."
  },
  AvgDialog_118701_Content_34 = {
    Text = "I will arrange for the Research Department to fully commit to dimensional research starting today."
  },
  AvgDialog_118701_Content_35 = {
    Text = "Between dimensions, sometimes there is no intersection, and it cannot be found through exhaustive search."
  },
  AvgDialog_118701_Content_36 = {
    Text = "What you may face is a long attempt that seems hopeless."
  },
  AvgDialog_118701_Content_37 = {
    Text = "We will not give up."
  },
  AvgDialog_118701_Content_38 = {Text = "..."},
  AvgDialog_118701_Content_39 = {
    Text = "I understand. No matter how long it takes, I will wait for {Male=him,Female=her}."
  },
  AvgDialog_118701_Content_4 = {
    Text = "Why are you putting away the instruments? Try again, there must be testing methods we haven't thought of yet..."
  },
  AvgDialog_118701_Content_40 = {
    Text = [[
World#Kadath
10 months after the Keeper's funeral
Black Pool]]
  },
  AvgDialog_118701_Content_41 = {
    Text = "Hollow footsteps echoed through the layers of locked gates, splashing into the viscous water. The silent Black Pool welcomes its second visitor of the day."
  },
  AvgDialog_118701_Content_42 = {
    Text = "I knew I'd find you here. Again."
  },
  AvgDialog_118701_Content_43 = {
    Text = "The person she is talking to does not respond. The motionless silhouette, like a statue watching afar, remains facing the floating figure in front of the \"Gate\"."
  },
  AvgDialog_118701_Content_44 = {
    Text = "I got another complaint letter today. This is your seventh time refusing to be assigned a task partner, insisting on conducting the two-person investigation alone."
  },
  AvgDialog_118701_Content_45 = {Text = "..."},
  AvgDialog_118701_Content_46 = {
    Text = "It's okay. I'm not here to criticize or command you, nor am I here to advise you—even though Sylvia mentioned there is a slight issue with your psychological assessment."
  },
  AvgDialog_118701_Content_47 = {
    Text = "But how many people here are perfectly fine, anyway?"
  },
  AvgDialog_118701_Content_48 = {
    Text = "She stands beside Ramona, gazing together at the figure that remains in eternal slumber."
  },
  AvgDialog_118701_Content_49 = {
    Text = "Is there any special task you need me to perform?"
  },
  AvgDialog_118701_Content_5 = {
    Text = "The number and frequency spectrum of tests have been more than sufficient. You got full marks in your Silver Core Instrument Usage course, Ramona. Stop deceiving yourself."
  },
  AvgDialog_118701_Content_50 = {
    Text = "Ramona, who has been silent as a statue until now, finally speaks, her tone as flat as a machine."
  },
  AvgDialog_118701_Content_51 = {Text = "Yes."},
  AvgDialog_118701_Content_52 = {
    Text = "Task requirements?"
  },
  AvgDialog_118701_Content_53 = {
    Text = "You need to go to a very dangerous place to pick up your partner."
  },
  AvgDialog_118701_Content_54 = {
    Text = "I don't need a new—"
  },
  AvgDialog_118701_Content_55 = {
    Text = "I mean, your ORIGINAL partner."
  },
  AvgDialog_118701_Content_56 = {
    Text = "Ramona jerks her head around to stare at Doll's calm eyes."
  },
  AvgDialog_118701_Content_57 = {
    Text = "This task is a gamble, unprecedented in its danger rating. I'm afraid no external support within the school can accompany you..."
  },
  AvgDialog_118701_Content_58 = {
    Text = "Did the Research Department have results? When?"
  },
  AvgDialog_118701_Content_59 = {
    Text = "Doll smiles, handing over the freshly printed research report."
  },
  AvgDialog_118701_Content_6 = {
    Text = "This is merely an empty shell, with no signs of life. The Keeper's consciousness... may have already dissipated."
  },
  AvgDialog_118701_Content_60 = {
    Text = "Since Daffodil informed us about the Keeper, the Research Department has tried all current technological methods. Surprisingly, the breakthrough came from the Awakener."
  },
  AvgDialog_118701_Content_61 = {
    Text = "We discovered that Pollux's \"Sacred Heart\" can attract that existence. The Church of the Lightbearers originally created the \"Sacred Heart\" to produce pure souls and spread the \"divine blood\"."
  },
  AvgDialog_118701_Content_62 = {
    Text = "Eventually, they planned to sacrifice their Twin Divi to summon the so-called Pure Land."
  },
  AvgDialog_118701_Content_63 = {
    Text = "The ritual was supposed to attract Tohuwabohu's attention and spread Dissolution. After targeted modification, the \"Sacred Heart\" is very likely to specifically guide us to the Keeper's location."
  },
  AvgDialog_118701_Content_64 = {
    Text = "Mythag plans to send an exceptionally powerful Awakener to the dimensional space, following the guidance of the \"Sacred Heart\" to traverse dimensions and establish a tunnel connecting the two worlds."
  },
  AvgDialog_118701_Content_65 = {
    Text = "If everything goes smoothly with the test data, we can start trying in less than a month."
  },
  AvgDialog_118701_Content_66 = {
    Text = "Your training regimen will now include exercises for mental strength. I hope you... don't overexert yourself, lest you damage your brain."
  },
  AvgDialog_118701_Content_67 = {
    Text = [[
World#Kadath
One year after the Keeper's funeral
Black Pool]]
  },
  AvgDialog_118701_Content_68 = {
    Text = "The rapidly operating spirit separation device emits an overloaded red alarm. The nearby observer immediately presses the stop button."
  },
  AvgDialog_118701_Content_69 = {
    Text = "The hatch of the user's cabin instantly pops open. Ramona, already exhausted, manages to twitch a finger before researchers quickly support her out."
  },
  AvgDialog_118701_Content_7 = {
    Text = "The cruel verdict finally falls from Doll's lips. Seeing the tears streaming from Ramona's stunned eyes, the professor, accustomed to sacrifice, closes her eyes in pity."
  },
  AvgDialog_118701_Content_70 = {
    Text = "Quickly, get her into the Neural Coolant!"
  },
  AvgDialog_118701_Content_71 = {
    Text = "The light green pool water submerges her chest. The feverish heat radiating from Ramona's body finally subsides. Her eyes, once rational and now bordering on obsessive, slowly open."
  },
  AvgDialog_118701_Content_72 = {
    Text = "Even with the first official attempt scheduled the day after tomorrow, you still can't risk your body like this."
  },
  AvgDialog_118701_Content_73 = {
    Text = "It's okay, I can handle it..."
  },
  AvgDialog_118701_Content_74 = {
    Text = "Pollux, who has stepped out from the nearby instrument, quietly approaches the two and interrupts Doll's further admonitions."
  },
  AvgDialog_118701_Content_75 = {
    Text = "The pain of losing someone you can't live without... the self-hatred for being powerless to save them... I've stood where you are, Miss Ramona."
  },
  AvgDialog_118701_Content_76 = {
    Text = "I can already sense the call of that bright light. Castor and I will do our best to help you bring back our benefactor."
  },
  AvgDialog_118701_Content_8 = {
    Text = "<Yellow:%player%>'s funeral is scheduled tomorrow. You can read %player%'s last will for {Male=him,Female=her}."
  },
  AvgDialog_118701_Content_9 = {
    Text = [[
World#Kadath
3 months after the Keeper's funeral]]
  },
  AvgDialog_118702_Content_1 = {
    Text = "Message from Afar"
  },
  AvgDialog_118702_Content_10 = {
    Text = "Seeing nothing, you wave your hands and take desperate steps, like a traveler wading upstream, struggling forward and searching in the viscous darkness."
  },
  AvgDialog_118702_Content_100 = {
    Text = "No scorching heat here. Only endless, viscous darkness. Gradually, forward and backward recede into abstraction, and existence itself dissolves into nothingness."
  },
  AvgDialog_118702_Content_101 = {
    Text = "Keep going. Don't look back."
  },
  AvgDialog_118702_Content_102 = {
    Text = "Trusting that voice, you empty your mind and push forward, until a swirl of psychedelic colors plunges you into violent dizziness."
  },
  AvgDialog_118702_Content_103 = {
    Text = "...Is that...!"
  },
  AvgDialog_118702_Content_104 = {
    Text = "Except for being Daffodil's Sea of Primordial Essence, this is the first time you stand outside the universe, looking at the world."
  },
  AvgDialog_118702_Content_105 = {
    Text = "It feels like entering a microscopic world under a microscope: a gelatinous spatial substance, countless writhing lines, bizarre-shaped spirits, and distant galaxies flickering at the far edge of vision..."
  },
  AvgDialog_118702_Content_106 = {
    Text = "...and the boundless frontier of worlds."
  },
  AvgDialog_118702_Content_107 = {
    Text = "Without a firm spiritual anchor, one would easily get lost in such a chaotic and boundless space. Yet you feel no fear."
  },
  AvgDialog_118702_Content_108 = {
    Text = "Are you ready? Once you start the link, I will make as much noise as possible to attract It. The rest will be your battle."
  },
  AvgDialog_118702_Content_109 = {
    Text = "Clutching the Silver Key at your chest, you solemnly, almost tenderly, extend your spirit tendrils toward the blooming rose in your hand."
  },
  AvgDialog_118702_Content_11 = {
    Text = "Finally... I found you! We @3... through the @2 tunnel..."
  },
  AvgDialog_118702_Content_110 = {Text = "Start."},
  AvgDialog_118702_Content_111 = {
    Text = "A grand wave of spiritual energy erupts in the dimensional space, and at the farthest reach of your spirit tendril, a sudden rift appears, tearing through the fabric of space."
  },
  AvgDialog_118702_Content_112 = {
    Text = "Behind the crevice, a gigantic pupil emerges, like the eye of a giant opening abruptly."
  },
  AvgDialog_118702_Content_12 = {
    Text = "You cannot see her, only hear her fragmented voice. Your partner is equally excited, expressing the joy of a long-awaited reunion."
  },
  AvgDialog_118702_Content_13 = {
    Text = "It feels like a real rope tethers you and Ramona together, and following that rope will lead you back home."
  },
  AvgDialog_118702_Content_14 = {
    Text = "As you advance along the guidance of that rope, a shattering sound suddenly erupts. The entire space shakes violently from a massive tremor."
  },
  AvgDialog_118702_Content_15 = {
    Text = "Something is attacking the @2! The Sacred Heart can't hold on!"
  },
  AvgDialog_118702_Content_16 = {
    Text = "Ramona, disconnect the link!"
  },
  AvgDialog_118702_Content_17 = {Text = "But...!"},
  AvgDialog_118702_Content_18 = {
    Text = "Keeper, go find Daffodil! We won't give up—"
  },
  AvgDialog_118702_Content_19 = {
    Text = "All light vanishes. In the distant expanse, a colossal, unknown entity changes course and gradually fades into the chaotic void."
  },
  AvgDialog_118702_Content_2 = {
    Text = "Keep@2... Keeper..."
  },
  AvgDialog_118702_Content_20 = {Text = "!!!"},
  AvgDialog_118702_Content_21 = {
    Text = "You jolt upright in bed. Dark red brick walls... the faint smell of disinfectant... You realize you are still in Doll: Inferno's base."
  },
  AvgDialog_118702_Content_22 = {
    Text = "What's going on? Since when did my research field expand to dream analysis? Shouldn't you be talking to Clementine for that?"
  },
  AvgDialog_118702_Content_23 = {
    Text = "But you're right. Given the uniqueness of your spirit, I'm inclined to believe this is neither a hallucination nor a simple dream."
  },
  AvgDialog_118702_Content_24 = {
    Text = "As for the truth, another \"me\" in your dream has already told you, I believe?"
  },
  AvgDialog_118702_Content_25 = {
    Text = "She takes a Silver Core you once stole and tosses it into the Awakening device. A wisp of hazy purple smoke rises amidst the mechanical humming."
  },
  AvgDialog_118702_Content_26 = {
    Text = "Oh, we meet again, my old customers."
  },
  AvgDialog_118702_Content_27 = {
    Text = "Daffodil! I..."
  },
  AvgDialog_118702_Content_28 = {
    Text = "Shh, no need to speak. A qualified merchant always understands the customer's desires."
  },
  AvgDialog_118702_Content_29 = {
    Text = "I have indeed met your friends."
  },
  AvgDialog_118702_Content_3 = {
    Text = "You feel smothered and shrouded, as if layers of thick velvet fabric press down upon you. You cannot see or move."
  },
  AvgDialog_118702_Content_30 = {Text = "?!"},
  AvgDialog_118702_Content_31 = {
    Text = "Seeing your shocked expression, Doll: Inferno rolls her eyes."
  },
  AvgDialog_118702_Content_32 = {
    Text = "I shouldn't have assumed you were smart enough to figure out the key to her strength."
  },
  AvgDialog_118702_Content_33 = {
    Text = "The key to her strength... ?"
  },
  AvgDialog_118702_Content_34 = {
    Text = "You remember that gray sea filled with skulls."
  },
  AvgDialog_118702_Content_35 = {
    Text = "You mean... Dimensional space? Daffodil can travel between different worlds... So the two Daffodils I met are actually the same person?"
  },
  AvgDialog_118702_Content_36 = {
    Text = "Very close, clever child. The two Daffodils are indeed the same \"existence,\" but you forgot: we are not human."
  },
  AvgDialog_118702_Content_37 = {
    Text = "Daffodil's eyes curve appreciatively as she flips her wrist, giving the smoking rod a slight shake."
  },
  AvgDialog_118702_Content_38 = {
    Text = "We are merely faces that emerge on the surface of the sea; that Gray Mist Sea flowing between the crevices of all dimensions is our true essence."
  },
  AvgDialog_118702_Content_39 = {
    Text = "Thus, our consciousnesses are connected, yet we are not the same \"person.\""
  },
  AvgDialog_118702_Content_4 = {
    Text = "In this dream of darkness and void, a faint voice ripples through like water, then quickly dissipates."
  },
  AvgDialog_118702_Content_40 = {
    Text = "So, you can travel between different worlds through the Sea of Primordial Essence? In the dream just now, Doll asked me to find you... Does that mean you have a way to take me back to that world now?"
  },
  AvgDialog_118702_Content_41 = {
    Text = "Don't be anxious. As I've said, even I can't easily perform dimensional travel."
  },
  AvgDialog_118702_Content_42 = {
    Text = "If I truly had such a flawless method, why would I hoard it until now?"
  },
  AvgDialog_118702_Content_43 = {
    Text = "You are stunned, slowly lowering your head."
  },
  AvgDialog_118702_Content_44 = {
    Text = "However, this time, your brave friends have found a new way."
  },
  AvgDialog_118702_Content_45 = {
    Text = "Your head jerks up, eyes reigniting, earning a gentle chuckle from Daffodil and a scoff from Doll: Inferno."
  },
  AvgDialog_118702_Content_46 = {
    Text = "Since the last time we met in this world, I have told them about you."
  },
  AvgDialog_118702_Content_47 = {
    Text = "Upon learning of this dimension's unique nature, Doll and the Mythag researchers have been working day and night, trying to pinpoint this world. Recently, they found a way to link the two dimensions."
  },
  AvgDialog_118702_Content_48 = {
    Text = "What you just felt was the result of their successful link."
  },
  AvgDialog_118702_Content_49 = {
    Text = "So that wasn't a dream? That spiritual link is real?!"
  },
  AvgDialog_118702_Content_5 = {
    Text = "Who? Who's calling me? That voice sounds so familiar..."
  },
  AvgDialog_118702_Content_50 = {
    Text = "Yes, but the collapse of that link was just as real. You should have noticed that sudden arrival."
  },
  AvgDialog_118702_Content_51 = {
    Text = "Dimensional travel is extremely dangerous. Even if I can help you escape the Hellhounds, there are far too many higher beings within the dimensional spaces."
  },
  AvgDialog_118702_Content_52 = {
    Text = "They each claim their own domain, ruling like monarchs over their territories."
  },
  AvgDialog_118702_Content_53 = {
    Text = "You might have avoided them in various ways, but unfortunately, this time, the one targeting the tunnel is your most familiar rival."
  },
  AvgDialog_118702_Content_54 = {
    Text = "Most familiar... The sense of being watched... Tohuwabohu? Has It awoken again?!"
  },
  AvgDialog_118702_Content_55 = {
    Text = "No need for such tension. The results you achieved through your sacrifice won't vanish so easily. It remains deep in slumber."
  },
  AvgDialog_118702_Content_56 = {
    Text = "But Tohuwabohu is powerful. You and Pollux's \"Sacred Heart\" are both too eye-catching. Even in its slumber, Its subconscious has taken notice of you."
  },
  AvgDialog_118702_Content_57 = {
    Text = "Daffodil's expression grows uncharacteristically grave. You fall silent, recalling the battle that cost everything."
  },
  AvgDialog_118702_Content_58 = {
    Text = "Fortunately, the disturbance from this dimensional travel is much smaller than the commotion Juliette caused last time. The gaze projected by Its subconscious isn't enough to destroy the entire world."
  },
  AvgDialog_118702_Content_59 = {
    Text = "Even so, that power is more than the Awakener sent to retrieve you could endure. To forge a complete and stable dimensional link, relying solely on the other side won't succeed."
  },
  AvgDialog_118702_Content_6 = {
    Text = "Keeper... %player%!"
  },
  AvgDialog_118702_Content_60 = {
    Text = "<Yellow:%player%>, we need you to draw Its attention here, and repel It, thus shielding your friends in the other world as they tunnel through."
  },
  AvgDialog_118702_Content_61 = {
    Text = "Tohuwabohu's gaze... I'll have to face it... again..."
  },
  AvgDialog_118702_Content_62 = {
    Text = "The battle feels so distant, like a story from a past life."
  },
  AvgDialog_118702_Content_63 = {
    Text = "Yet, it also feels so near—close enough for you to recall every detail with ease."
  },
  AvgDialog_118702_Content_64 = {
    Text = "You remember every grievous wound, every hard-won victory, every shudder of fear, every desperate cry on the brink of death..."
  },
  AvgDialog_118702_Content_65 = {
    Text = "Gazing upon the Supreme Will once cost you all your courage and life. Recalling those gazes that transcend all rules, your voice begins to tremble uncontrollably."
  },
  AvgDialog_118702_Content_66 = {
    Text = "Even a mere gaze projected by Its subconscious, its power may still be beyond my capacity to withstand."
  },
  AvgDialog_118702_Content_67 = {
    Text = "Now I cannot fully utilize the power of the three Aeons, nor do I have the aid of my companions from other dimensions. How should I stop It again..."
  },
  AvgDialog_118702_Content_68 = {
    Text = "What, are you afraid, our brave Keeper?"
  },
  AvgDialog_118702_Content_69 = {
    Text = "You clench your fists, shake your head, and look earnestly at Daffodil."
  },
  AvgDialog_118702_Content_7 = {Text = "Ramona?!"},
  AvgDialog_118702_Content_70 = {
    Text = "As long as I can go back, no fear can stop me. I'm just worried my current ability is insufficient."
  },
  AvgDialog_118702_Content_71 = {
    Text = "If I fail, It might be reawakened... a catastrophe beyond anyone's capacity to endure."
  },
  AvgDialog_118702_Content_72 = {
    Text = "Good. It seems our Keeper has not yet lost the courage to stand against the god."
  },
  AvgDialog_118702_Content_73 = {
    Text = "Don't worry, <Yellow:%player%>. This time, I'll help you clear the barriers between dimensions, dispersing Its power into other worlds."
  },
  AvgDialog_118702_Content_74 = {
    Text = "Last time, Keepers from other dimensions fought alongside you. This time, they'll still be fighting the same battle with you—even if you cannot see them."
  },
  AvgDialog_118702_Content_75 = {
    Text = "Really?! Then I... no, we will surely be able to hold It back once more!"
  },
  AvgDialog_118702_Content_76 = {
    Text = "Even so, a battle of this magnitude would devastate the entire world here. No one here possesses the capability to confront It, aside from <Yellow:%player%>."
  },
  AvgDialog_118702_Content_77 = {
    Text = "Precisely. So this battle must take place in the dimensional space. As for how to keep <Yellow:%player%> there for an extended period... we'll require a genius's assistance."
  },
  AvgDialog_118702_Content_78 = {
    Text = "Please! Doll: Inferno!"
  },
  AvgDialog_118702_Content_79 = {
    Text = "Hmph... How conveniently you've arranged everything."
  },
  AvgDialog_118702_Content_8 = {
    Text = "As you utter the name, an invisible barrier instantly shatters. A warm, intimate link crosses countless timelines, transforming into a shimmering white thread that brushes your chest."
  },
  AvgDialog_118702_Content_80 = {
    Text = "But fine—I promised to get you home. I'll keep my promise, my little puppy."
  },
  AvgDialog_118702_Content_81 = {Text = "Thank you!"},
  AvgDialog_118702_Content_82 = {
    Text = "Save your gratitude. Let me be clear: I can only anchor your consciousness in dimensional space, and I'll try my best to pull you back here anytime you need me."
  },
  AvgDialog_118702_Content_83 = {
    Text = "Remember. You may still fail, or even die from fighting It."
  },
  AvgDialog_118702_Content_84 = {
    Text = "I'm not optimistic about this impulsive plan. Even so, are you willing to take such a risk on an unknown outcome?"
  },
  AvgDialog_118702_Content_85 = {
    Text = "I am willing. They took the same risks for me, and I have every reason to answer in kind. Even if we are worlds apart, we are still fighting side by side, as we did in the past."
  },
  AvgDialog_118702_Content_86 = {
    Text = "Doll: Inferno gives an unsurprised nod, and Daffodil looks at you, smiling, as if she never considered the possibility that you would flinch."
  },
  AvgDialog_118702_Content_87 = {
    Text = "Got it. Such a cheesy oath is better left for your comrades. I need some time to prepare, and I assume you already have a method to coordinate your starting time of the operation?"
  },
  AvgDialog_118702_Content_88 = {
    Text = "In response to Doll: Inferno's inquiry, Daffodil turns her gaze toward you."
  },
  AvgDialog_118702_Content_89 = {
    Text = "Of course, your partner asked me to deliver a gift."
  },
  AvgDialog_118702_Content_9 = {
    Text = "Is this... a spiritual link?! Ramona, is that you? Where are you?"
  },
  AvgDialog_118702_Content_90 = {
    Text = "Amidst swirling mist, a rose, seemingly produced from nowhere, is handed to you."
  },
  AvgDialog_118702_Content_91 = {
    Text = "This is... the one Ramona gave me...?!"
  },
  AvgDialog_118702_Content_92 = {
    Text = "I regret to say that I do not yet possess the power to transmit physical objects across dimensions."
  },
  AvgDialog_118702_Content_93 = {
    Text = "Yet in these two realities, everything has its counterpart."
  },
  AvgDialog_118702_Content_94 = {
    Text = "This rose corresponds to the one Ramona gave you in that world."
  },
  AvgDialog_118702_Content_95 = {
    Text = "I have made a little adjustment to this flower. When you are ready, just link your spirit to it. Our allies over there will receive the signal."
  },
  AvgDialog_118702_Content_96 = {
    Text = "Ramona said she will pin this rose to your chest herself when you meet again."
  },
  AvgDialog_118702_Content_97 = {Text = "..."},
  AvgDialog_118702_Content_98 = {
    Text = "For the first time, you realize that the passage used by Doll: Inferno to leave the world is the vanished sun hanging overhead."
  },
  AvgDialog_118702_Content_99 = {
    Text = "The sun's pitch-black void resembles an unhealable wound of the world. As your consciousness drifts into it, you feel as though you are crawling into the hollow chest of a giant."
  },
  AvgDialog_118703_Content_1 = {
    Text = "Curled Fingertips"
  },
  AvgDialog_118703_Content_10 = {
    Text = "A piercing shriek, belonging to no creature or dimension, rings directly from the depths of your consciousness, nearly tearing your mind apart."
  },
  AvgDialog_118703_Content_100 = {
    Text = "Ugh! My head... hurts so much..."
  },
  AvgDialog_118703_Content_101 = {
    Text = "The connecting instruments are almost completely damaged. It's practically a miracle that you returned alive."
  },
  AvgDialog_118703_Content_102 = {
    Text = "But this place has already witnessed too many miracles. Perhaps for the Black Pool, probability theory itself is a fallacy."
  },
  AvgDialog_118703_Content_103 = {
    Text = "You did well, Ramona. But don't do that again."
  },
  AvgDialog_118703_Content_104 = {
    Text = "Please rest assured, Professor Doll... I know what I am doing."
  },
  AvgDialog_118703_Content_105 = {
    Text = "For %player%, being able to see you again is perhaps more important than many other things."
  },
  AvgDialog_118703_Content_106 = {
    Text = "Unfortunately, you didn't hear {Male=his,Female=her} parting words."
  },
  AvgDialog_118703_Content_107 = {
    Text = "No, Lady Daffodil. I already heard what {Male=he,Female=she} said..."
  },
  AvgDialog_118703_Content_108 = {
    Text = "Ramona weakly stands up and, with a smile, walks to the fading void of the Black Pool."
  },
  AvgDialog_118703_Content_109 = {
    Text = "The abyss collapses in her eyes—from a massive entity devouring everything, to a gate separating dimensions, then to a void-like crevice, until it disappears completely."
  },
  AvgDialog_118703_Content_11 = {
    Text = "You collapse to your knees, clutching your ears tightly, feeling blood uncontrollably seep from your eyes..."
  },
  AvgDialog_118703_Content_110 = {
    Text = "Ramona's hand gently brushes over the place where the abyss once existed, over that battered body."
  },
  AvgDialog_118703_Content_111 = {
    Text = "She smiles, as if she sees the owner of the body standing before her in the near future, just like any ordinary day back in Mythag."
  },
  AvgDialog_118703_Content_112 = {
    Text = "I heard you, Keeper... We will make it happen. <Blue:We Will Meet Again.>"
  },
  AvgDialog_118703_Content_113 = {
    Text = "I'm waiting for you, %player%."
  },
  AvgDialog_118703_Content_12 = {
    Text = "<Shake:Huff... huff...>"
  },
  AvgDialog_118703_Content_13 = {
    Text = "Is it... over?"
  },
  AvgDialog_118703_Content_14 = {
    Text = "The agonizing shriek has vanished without you noticing when. You lift your head. In the fragile illusory dimension, that terrifying, chilling presence is long gone."
  },
  AvgDialog_118703_Content_15 = {
    Text = "You've won. Its subconscious is severed from this place; the last giant eye has dissipated within the dimension."
  },
  AvgDialog_118703_Content_16 = {
    Text = "Struggling to steady your utterly exhausted mind, you almost instinctively turn back."
  },
  AvgDialog_118703_Content_17 = {Text = "Crack—"},
  AvgDialog_118703_Content_18 = {
    Text = "A faint, crystalline shattering reaches your ears. You see the dimensional tunnel cracking like a spider web, and Ramona's spiritual form begins to flicker like an old television."
  },
  AvgDialog_118703_Content_19 = {
    Text = "<BigShake:Ramona!!!>>"
  },
  AvgDialog_118703_Content_2 = {
    Text = "Just... a little more...!"
  },
  AvgDialog_118703_Content_20 = {
    Text = "Your long-exhausted body seems to heal in an instant. No longer caring about anything else, you fly to her side, trembling as you grasp her hands."
  },
  AvgDialog_118703_Content_21 = {
    Text = "I... I'm fine..."
  },
  AvgDialog_118703_Content_22 = {
    Text = "Your partner smiles as usual. She squeezes your hand back tighter, continuing with the original plan as if nothing had happened."
  },
  AvgDialog_118703_Content_23 = {
    Text = "You've defeated It. Come, follow me. I'll take you back."
  },
  AvgDialog_118703_Content_24 = {
    Text = [[
She leads you, just as she always does during missions.
However, a more rational voice cuts in, almost coldly.]]
  },
  AvgDialog_118703_Content_25 = {
    Text = "Ramona, the dimensional tunnel is shattered. Your spiritual form cannot maintain the tunnel any longer. If this continues, you risk brain death."
  },
  AvgDialog_118703_Content_26 = {
    Text = "This rescue... has failed. You must return immediately. I will activate the recall mode of the separation device to bring your spirit back to your body."
  },
  AvgDialog_118703_Content_27 = {
    Text = "<Big:I'm not leaving!>"
  },
  AvgDialog_118703_Content_28 = {
    Text = "It's the first time you've seen this always-calm person cry out so desperately. She takes a deep breath, then shows you a more natural smile."
  },
  AvgDialog_118703_Content_29 = {
    Text = "I can still do it, <Yellow:%player%>. I've done so much training lately; my spiritual power has grown. Doll doesn't know my true limits."
  },
  AvgDialog_118703_Content_3 = {
    Text = "When your spirit is on the brink of exhaustion, the gaze of the Supreme also begins to waver from weakness."
  },
  AvgDialog_118703_Content_30 = {
    Text = "Don't give up, let's try again, just a little attempt, okay?"
  },
  AvgDialog_118703_Content_31 = {
    Text = "She's pleading with you."
  },
  AvgDialog_118703_Content_32 = {Text = "..."},
  AvgDialog_118703_Content_33 = {
    Text = "You can't speak."
  },
  AvgDialog_118703_Content_34 = {
    Text = "Why bother struggling? How about I capture her spirit and place it in one of my meticulously crafted bodies? That way, she can stay by <Yellow:%player%>'s side again."
  },
  AvgDialog_118703_Content_35 = {
    Text = "Doll: Inferno, who had been enjoying the show immensely, also joins the communication channel, letting out a cynical laugh."
  },
  AvgDialog_118703_Content_36 = {
    Text = "Nonsense. We both know not everyone can sustain spirit separation for long periods like <Yellow:%player%>. Otherwise, we wouldn't be hauling vats of pink brains every day."
  },
  AvgDialog_118703_Content_37 = {
    Text = "It's okay, Ramona. Next time, when you're rested, I'll wait for you to come and get me."
  },
  AvgDialog_118703_Content_38 = {
    Text = "You gaze at the transparent figure that seems to be fading away, smiling gently and hiding all your longing for home."
  },
  AvgDialog_118703_Content_39 = {
    Text = "It's not that simple. This \"route\" has already been discovered by It. If used again, it will only attract more intense scrutiny."
  },
  AvgDialog_118703_Content_4 = {
    Text = "This is a battlefield of wills. Like a dying beast, you summon every last ounce of your strength, squeezing out the final dregs of power from your parched mental world."
  },
  AvgDialog_118703_Content_40 = {
    Text = "Doll: Inferno ruthlessly shatters your illusion, while Doll on the other end remains silent."
  },
  AvgDialog_118703_Content_41 = {
    Text = "<Shake:We've come this far. This time, right now, I want to take you back.>"
  },
  AvgDialog_118703_Content_42 = {
    Text = "Ramona's hands begin to tremble as well. You slowly take a breath and pat her hand, pretending to be relaxed."
  },
  AvgDialog_118703_Content_43 = {
    Text = "Ramona, do you remember the first time we met?"
  },
  AvgDialog_118703_Content_44 = {
    Text = "Ramona nods, then shakes her head, looking at you with an almost pleading gaze. You simply close your eyes and continue speaking with deliberate cruelty."
  },
  AvgDialog_118703_Content_45 = {
    Text = "That was truly a horrific disaster. After the explosion, I can only vaguely remember everything around me turning to ruins with a deafening blast. When I opened my eyes, I thought I had arrived in heaven."
  },
  AvgDialog_118703_Content_46 = {
    Text = "The glaring sunlight streamed through the excavated stones, and then there was your hand, reaching out to me."
  },
  AvgDialog_118703_Content_47 = {
    Text = "At that time, I was wondering, is the angel's outfit this strange? It's such an old-fashioned uniform. I didn't expect that soon, I'd be wearing the same uniform myself."
  },
  AvgDialog_118703_Content_48 = {
    Text = "Ramona wants to say something more, but you interrupt her. You start to ramble on like an elder lost in memories."
  },
  AvgDialog_118703_Content_49 = {
    Text = "After you dug me out, I always regarded you as the kindest person, but after coming to Mythag, I realized I'd been massively scammed."
  },
  AvgDialog_118703_Content_5 = {
    Text = "With trembling hands, you raise the Silver Key high."
  },
  AvgDialog_118703_Content_50 = {
    Text = "When I first started the preparatory class, you said you were my partner and would help me with all my life and study problems. I believed you."
  },
  AvgDialog_118703_Content_51 = {
    Text = "In fact, you did solve my problems—by solving the source of the problem: <Shake:me>."
  },
  AvgDialog_118703_Content_52 = {
    Text = "Turns out, my so-called partner was actually my biggest taskmaster. In that prep class year, you were the one who was the strictest with me."
  },
  AvgDialog_118703_Content_53 = {
    Text = "Not only did you monitor me during class as my desk mate, but you also watched me when I did homework after class. Sometimes, after physical training, you wouldn't even let me have a plate of fish and chips. It was truly despicable."
  },
  AvgDialog_118703_Content_54 = {
    Text = "Ramona's silent and sorrowful expression breaks for a moment, and the corner of her mouth involuntarily curves up."
  },
  AvgDialog_118703_Content_55 = {
    Text = "But, my dear partner, you were also the one who took care of me the most."
  },
  AvgDialog_118703_Content_56 = {
    Text = "Leonian I couldn't speak, the pressure of exams driving me crazy, homework I couldn't complete... whenever I was sad, I could always turn to my all-omnipotent partner."
  },
  AvgDialog_118703_Content_57 = {
    Text = "Do you remember the first time I saw a student sacrifice themselves during a mission? I couldn't sleep that night, tossing and turning, and sneaked over to knock on your door."
  },
  AvgDialog_118703_Content_58 = {
    Text = "Then, you pulled me up to the top of the clock tower. I struggled to climb up to the roof with you, and we just sat side by side watching the stars."
  },
  AvgDialog_118703_Content_59 = {
    Text = "You and I talked for a very long time, about a lot of things. That was the first time I realized that you also didn't know what your mother and childhood were like."
  },
  AvgDialog_118703_Content_6 = {
    Text = "This will be... the end!"
  },
  AvgDialog_118703_Content_60 = {
    Text = "My heart, which had always felt a bit lonely and lost, suddenly settled then."
  },
  AvgDialog_118703_Content_61 = {
    Text = "I thought that even though I had no family, this might be the only person in the world right now who treated me so well and was so much like me, someone who felt like family."
  },
  AvgDialog_118703_Content_62 = {
    Text = "I swore to you with a pinky promise that I would definitely take my homework seriously, attend classes seriously, and carry out missions seriously from now on."
  },
  AvgDialog_118703_Content_63 = {
    Text = "Since then, I came to see Mythag as my real home. And so, mission after mission, I met so many Awakeners and met one new family member after another."
  },
  AvgDialog_118703_Content_64 = {
    Text = "<Yellow:%player%>..."
  },
  AvgDialog_118703_Content_65 = {
    Text = "So, thank you, thank you for coming to pick me up, my family."
  },
  AvgDialog_118703_Content_66 = {
    Text = "I know you must have tried for a very long time and put in a lot of effort."
  },
  AvgDialog_118703_Content_67 = {
    Text = "Then come with me, I definitely can take you back."
  },
  AvgDialog_118703_Content_68 = {
    Text = "You still smile as you look at the tears streaming down Ramona's cheeks, but some scalding liquid also flows uncontrollably across your face."
  },
  AvgDialog_118703_Content_69 = {
    Text = "Watching her becoming translucent and flickering as her spirit reaches its limit, you gently shake your head."
  },
  AvgDialog_118703_Content_7 = {
    Text = "A dazzling silver light blooms in your hand, its silvery radiance illuminating the entire illusory dimension."
  },
  AvgDialog_118703_Content_70 = {
    Text = "It's time, Ramona."
  },
  AvgDialog_118703_Content_71 = {Text = "No, no..."},
  AvgDialog_118703_Content_72 = {
    Text = "Ramona had known this moment would come. She shakes her head desperately, her fading hands gripping your spiritual form tightly."
  },
  AvgDialog_118703_Content_73 = {
    Text = "I'll come back to you. That's a promise."
  },
  AvgDialog_118703_Content_74 = {
    Text = "We will meet again... no matter what."
  },
  AvgDialog_118703_Content_75 = {
    Text = "You gently withdraw your hand from that familiar grasp and let go."
  },
  AvgDialog_118703_Content_76 = {
    Text = "Doll on the other end of the comm receives the signal. A familiar sensation washes over Ramona's spirit—the instrument is pulling her away. She knows she has to leave."
  },
  AvgDialog_118703_Content_77 = {
    Text = "\"A promise,\" huh... Just like the first time, when you walked into the Gate... You don't believe it yourself, do you?"
  },
  AvgDialog_118703_Content_78 = {
    Text = "You really are a heartless person..."
  },
  AvgDialog_118703_Content_79 = {
    Text = "Ramona, I..."
  },
  AvgDialog_118703_Content_8 = {
    Text = "<Shake:@2@4@3!!—>"
  },
  AvgDialog_118703_Content_80 = {
    Text = "Investigator's Code... promises made must be kept."
  },
  AvgDialog_118703_Content_81 = {
    Text = "I believe you. Even if you lie to me countless times, even if you don't even believe yourself, I'll always believe you."
  },
  AvgDialog_118703_Content_82 = {
    Text = "On that face where tears and smile intertwine, Ramona's pupils lock onto yours, struggling to etch your face into her memory."
  },
  AvgDialog_118703_Content_83 = {
    Text = "At the last moment when her spirit is recalled to her body, she stretches out her hand to you with all her strength once again."
  },
  AvgDialog_118703_Content_84 = {
    Text = "Just like that moment long ago under the starry night sky, she reached out her pinky finger and gently hooked it onto your fingertip."
  },
  AvgDialog_118703_Content_85 = {
    Text = "You will keep your promise, right?"
  },
  AvgDialog_118703_Content_86 = {
    Text = "She does not wait for your answer. The next instant, her illusory figure dissipates along with the dimensional tunnel, turning into scattered remnants that slowly fade away, leaving no trace."
  },
  AvgDialog_118703_Content_87 = {Text = "..."},
  AvgDialog_118703_Content_88 = {Text = "..."},
  AvgDialog_118703_Content_89 = {
    Text = "Breathing normal. Heart rate normal. Mental strength below alert level... recovering."
  },
  AvgDialog_118703_Content_9 = {
    Text = "AAAHHHHH—"
  },
  AvgDialog_118703_Content_90 = {
    Text = "To survive after draining mental strength like that... you really are a tough little pup."
  },
  AvgDialog_118703_Content_91 = {
    Text = "What a good show. Pity I didn't get to see the god you summoned destroy this world. The ending wasn't spectacular enough."
  },
  AvgDialog_118703_Content_92 = {
    Text = "Don't worry... I told you I'd hold It back in another dimension. I will never make an unfulfilled promise again."
  },
  AvgDialog_118703_Content_93 = {
    Text = "Save those words to tell her in person when you get back."
  },
  AvgDialog_118703_Content_94 = {
    Text = "Since I've chosen this path with you all, I want to see just how far you can go."
  },
  AvgDialog_118703_Content_95 = {
    Text = "Rest well, and then continue on your way, little pup."
  },
  AvgDialog_118703_Content_96 = {
    Text = "Feeling the lingering warmth on your fingertip, you slowly clench the pinky finger that was just linked with hers, pressing it firmly against your chest."
  },
  AvgDialog_118703_Content_97 = {
    Text = "Toward that vast, solitary dimensional space, toward that vanished figure, you whisper the promise you are determined to keep."
  },
  AvgDialog_118703_Content_98 = {
    Text = "Even though you can't hear me now... I will keep my promise. Wait for me, Ramona!"
  },
  AvgDialog_118703_Content_99 = {Text = "..."},
  AvgDialog_118944_Content_1 = {
    Text = "After defeating the last deformed Seafarer, you cautiously approach the girl in the corner while fighting your way back."
  },
  AvgDialog_118944_Content_10 = {
    Text = "William attempts to unveil the hatch leading to the lower cabin, but no matter how hard he exerts himself, the hatch won't budge."
  },
  AvgDialog_118944_Content_11 = {
    Text = "No, it's been sealed shut from below!"
  },
  AvgDialog_118944_Content_12 = {
    Text = "The hull lets out a chilling groan as it struggles and resolutely begins to turn, charging towards the darker waters, where the storms are denser, amidst the towering waves."
  },
  AvgDialog_118944_Content_13 = {
    Text = "Miryam opens her arms, embracing this destructive course. A smile of near maternal tenderness appears on her face."
  },
  AvgDialog_118944_Content_14 = {
    Text = "The ritual is about to end."
  },
  AvgDialog_118944_Content_15 = {
    Text = "Do you have a conclusion?"
  },
  AvgDialog_118944_Content_16 = {
    Text = "In the midst of the storm and chaos, no one can discern everyone's position..."
  },
  AvgDialog_118944_Content_17 = {
    Text = "As long as there is one more small boat..."
  },
  AvgDialog_118944_Content_18 = {
    Text = "Countless clues lit up within your mind..."
  },
  AvgDialog_118944_Content_19 = {
    Text = "The guards in the living quarters."
  },
  AvgDialog_118944_Content_2 = {
    Text = "Murphy, come with me!"
  },
  AvgDialog_118944_Content_20 = {
    Text = "The navigation ritual on the deck."
  },
  AvgDialog_118944_Content_21 = {
    Text = "The explosion in the engine room."
  },
  AvgDialog_118944_Content_22 = {
    Text = "The lifeboat in the lower cabin."
  },
  AvgDialog_118944_Content_23 = {
    Text = "The points of light linked together, interwoven, and extended... finally converging into a definitive escape route."
  },
  AvgDialog_118944_Content_24 = {
    Text = "William nods."
  },
  AvgDialog_118944_Content_25 = {
    Text = "Since you've found the answer, the goal of this cycle is achieved. There's no need for regret."
  },
  AvgDialog_118944_Content_26 = {
    Text = "According to the pattern you've described, the ship is about to start sinking."
  },
  AvgDialog_118944_Content_27 = {
    Text = "Are you ready?"
  },
  AvgDialog_118944_Content_28 = {
    Text = "The tide has already swallowed your chests. You gently grasp the Silver Key at your chest, whispering farewell words."
  },
  AvgDialog_118944_Content_29 = {
    Text = "See you in the next cycle, William."
  },
  AvgDialog_118944_Content_3 = {
    Text = "She jolts. Her gaze, unfocused, struggles to fixate on your face."
  },
  AvgDialog_118944_Content_30 = {
    Text = "May the Silver Key light your path."
  },
  AvgDialog_118944_Content_4 = {
    Text = "No, it's meaningless, it's all an illusion... Whether advancing or retreating, it's all..."
  },
  AvgDialog_118944_Content_5 = {
    Text = "As long as it's not the last moment, don't give up trying! Even if I fail this time, I will take your hand once again!"
  },
  AvgDialog_118944_Content_6 = {Text = "..."},
  AvgDialog_118944_Content_7 = {
    Text = "Murphy stares blankly at you."
  },
  AvgDialog_118944_Content_8 = {
    Text = "You grasp her wrist with a firm yet gentle grip, pulling her out of that desperate corner."
  },
  AvgDialog_118944_Content_9 = {
    Text = "Is there an escape route, Senior William?"
  },
  AvgDialog_118945_Content_1 = {
    Text = "Little one, you held back during the battle."
  },
  AvgDialog_118945_Content_10 = {
    Text = "Some commit atrocities to survive when all other paths are closed."
  },
  AvgDialog_118945_Content_11 = {
    Text = "Some filter others according to their own conviction to construct the new world they imagine."
  },
  AvgDialog_118945_Content_12 = {
    Text = "And some, purely for their cruel amusement, are willing to turn the world upside down and create endless turmoil."
  },
  AvgDialog_118945_Content_13 = {
    Text = "You wait and look forward to her answer, recalling the distant dream of the path she took."
  },
  AvgDialog_118945_Content_14 = {
    Text = "The now-maniacal Miryam was once a girl who, during the cataclysm, devoted herself to the priest's charge to protect her only family."
  },
  AvgDialog_118945_Content_15 = {
    Text = "Miryam does not directly answer your question. Instead, she brings her hands together and prays toward the distant horizon."
  },
  AvgDialog_118945_Content_16 = {
    Text = "\"The lost, He guides...\""
  },
  AvgDialog_118945_Content_17 = {
    Text = "\"The yearning, He answers.\""
  },
  AvgDialog_118945_Content_18 = {
    Text = "As if receiving the sea's approval, she half-opens her vacant purple-black eyes."
  },
  AvgDialog_118945_Content_19 = {
    Text = "I have come to revive the Divine Realm, to bring the glory of God back to the world."
  },
  AvgDialog_118945_Content_2 = {
    Text = "To me, this conversation with Miryam is far more important than winning against you."
  },
  AvgDialog_118945_Content_20 = {
    Text = "So, when Lemuria is reenacted in the world, what kind of world do you expect to see?"
  },
  AvgDialog_118945_Content_21 = {
    Text = "\"In His Long Dream, we share eternal peace and happiness.\""
  },
  AvgDialog_118945_Content_22 = {
    Text = "The glory of Lemuria has returned, just as you were instilled with during your lifetime."
  },
  AvgDialog_118945_Content_23 = {
    Text = "You have never witnessed a day of such prosperity. Do you truly know how to create it?"
  },
  AvgDialog_118945_Content_24 = {
    Text = "\"His Divine Will will guide the faithful on the path to Lemuria.\""
  },
  AvgDialog_118945_Content_25 = {
    Text = "The you in this world is indeed no different from what I perceived."
  },
  AvgDialog_118945_Content_26 = {
    Text = "So, in this moment when your god has already been born, why do you still hold onto Murphy?"
  },
  AvgDialog_118945_Content_3 = {
    Text = "If you could expose a momentary vulnerability in Miryam, the Domain may crack and reveal its hidden \"core\"..."
  },
  AvgDialog_118945_Content_4 = {
    Text = "You will have the chance to completely end this entrenched artificial dream."
  },
  AvgDialog_118945_Content_5 = {
    Text = "Very well. You've proved your resolve. Now state your purpose."
  },
  AvgDialog_118945_Content_6 = {
    Text = "I have a question."
  },
  AvgDialog_118945_Content_7 = {
    Text = "Miryam, why do you want to revive the Divine Realm?"
  },
  AvgDialog_118945_Content_8 = {
    Text = "You've raised a very interesting question."
  },
  AvgDialog_118945_Content_9 = {
    Text = "During my journey to confront Dissolution, I met many people."
  },
  AvgDialog_118946_Content_1 = {Text = "The Escape"},
  AvgDialog_118946_Content_10 = {
    Text = "She raises her pale fingertips and turns the spinning wheel again."
  },
  AvgDialog_118946_Content_100 = {
    Text = "Until darkness finally engulfs your world."
  },
  AvgDialog_118946_Content_11 = {
    Text = "Although I still don't know your name, please bless me, stranger."
  },
  AvgDialog_118946_Content_12 = {
    Text = [[
A flock of birds swoops by, stirring up waves of white feathers.

After the waves receded, the woman also vanished.]]
  },
  AvgDialog_118946_Content_13 = {
    Text = "You quickly outline the overall plan to William."
  },
  AvgDialog_118946_Content_14 = {
    Text = "Sounds like a plan to win amidst the chaos."
  },
  AvgDialog_118946_Content_15 = {
    Text = "When the ritual ends and the rebellion erupts, the Seafarers cult will be at its weakest."
  },
  AvgDialog_118946_Content_16 = {
    Text = "According to the clues provided by Faros, perhaps all we need to do is acquire the ivory sculpture to escape the Domain."
  },
  AvgDialog_118946_Content_17 = {
    Text = "Would taking Murphy with us further complicate the situation?"
  },
  AvgDialog_118946_Content_18 = {
    Text = "Senior William, you were the one who told me that the events in the Domain might affect the real world outside."
  },
  AvgDialog_118946_Content_19 = {
    Text = "I can't just sit and watch what's happening to Murphy..."
  },
  AvgDialog_118946_Content_2 = {
    Text = "Another cycle."
  },
  AvgDialog_118946_Content_20 = {
    Text = "Goliath intends to seize the ship; he won't care about Murphy's escape. Miryam is exhausted from dealing with Goliath and will be too preoccupied to pursue us."
  },
  AvgDialog_118946_Content_21 = {
    Text = "It's an excellent opportunity."
  },
  AvgDialog_118946_Content_22 = {
    Text = "William closes his eyes, adjusts his glasses, and lets out a resigned sigh."
  },
  AvgDialog_118946_Content_23 = {
    Text = "Fine. Your call."
  },
  AvgDialog_118946_Content_24 = {
    Text = "You and William hide on the platform of the mast."
  },
  AvgDialog_118946_Content_25 = {
    Text = "Goliath is busy orchestrating his rebel. You leap down and grab Murphy's wrist."
  },
  AvgDialog_118946_Content_26 = {
    Text = "Hurry! You're leaving with us!"
  },
  AvgDialog_118946_Content_27 = {
    Text = "Are you out of your mind? Why are you coming back? We can't escape. Isn't it better to just let everything continue smoothly?"
  },
  AvgDialog_118946_Content_28 = {
    Text = "Murphy tries to break free from you, but your insistence is impossible to refuse. A ring of light red appears on her wrist."
  },
  AvgDialog_118946_Content_29 = {
    Text = "Murphy, the stability you wanted has long since ceased to exist."
  },
  AvgDialog_118946_Content_3 = {
    Text = "Sea birds circle above the mysterious woman, their mournful calls resembling a song."
  },
  AvgDialog_118946_Content_30 = {
    Text = "Goliath and Caecus are plotting to seize the ship, Faros is scheming for the power of the ivory sculpture, and the entire Seafarer group is already in disarray."
  },
  AvgDialog_118946_Content_31 = {
    Text = "Trust me, trust me one more time. I will definitely get you out."
  },
  AvgDialog_118946_Content_32 = {
    Text = "We'll get out of here, and then what?"
  },
  AvgDialog_118946_Content_33 = {
    Text = "Then we will find a way to return to Mythag, and you will become a part of Mythag alongside everyone."
  },
  AvgDialog_118946_Content_34 = {
    Text = "They often say my dreams are prophetic dreams; in distant dreams, I have seen that happen..."
  },
  AvgDialog_118946_Content_35 = {
    Text = "You feel that the strength to resist has weakened somewhat."
  },
  AvgDialog_118946_Content_36 = {
    Text = "Come on, follow me. To the right side of the ship... Three, two, one, jump!"
  },
  AvgDialog_118946_Content_37 = {Text = "Splash!"},
  AvgDialog_118946_Content_38 = {
    Text = "You leap into the ocean together, your hands tightly clasped together."
  },
  AvgDialog_118946_Content_39 = {
    Text = "Sunlight pierces through the surface of the sea, illuminating her floating hair and veil in the crystalline water. Her rose-colored pupils stare into yours, like a silent dream."
  },
  AvgDialog_118946_Content_4 = {
    Text = "Don't worry, this time our preparations are foolproof."
  },
  AvgDialog_118946_Content_40 = {
    Text = "You are free now."
  },
  AvgDialog_118946_Content_41 = {Text = "Splash—"},
  AvgDialog_118946_Content_42 = {
    Text = "A paddle pierces the crystalline seawater before you."
  },
  AvgDialog_118946_Content_43 = {
    Text = "You nod at Murphy, and the two of you cling to the oars together."
  },
  AvgDialog_118946_Content_44 = {
    Text = "Got a good grip?"
  },
  AvgDialog_118946_Content_45 = {
    Text = "He pulls you out of the water, and you climb up, holding onto the edge of the small boat."
  },
  AvgDialog_118946_Content_46 = {
    Text = "Hey, give me a hand!"
  },
  AvgDialog_118946_Content_47 = {
    Text = "What's wrong? Can't you get up by yourself?"
  },
  AvgDialog_118946_Content_48 = {
    Text = "Stop wasting words; I haven't even finished punishing you for letting the Divine Mother fall into the water!"
  },
  AvgDialog_118946_Content_49 = {
    Text = "You gently grasp Murphy's shoulder as she floats, pulling her away from the water's surface with just the right amount of force."
  },
  AvgDialog_118946_Content_5 = {
    Text = "We know that the ship will capsize after the Ritual of Navigation is over; we know that the ivory sculpture can manipulate dreams."
  },
  AvgDialog_118946_Content_50 = {Text = "Huff—"},
  AvgDialog_118946_Content_51 = {
    Text = "Alright, now we can have a proper talk. Where are we going?"
  },
  AvgDialog_118946_Content_52 = {
    Text = "While Goliath and Miryam are busy fighting, the three of us will pilot this ship together and sail out of the Domain's borders."
  },
  AvgDialog_118946_Content_53 = {
    Text = "We will find the way back to my original world. You'll meet the other Murphy there, and the two of you will be living a safe life, bickering over trivialities in the cafeteria..."
  },
  AvgDialog_118946_Content_54 = {
    Text = "Pfft. Sounds like it will be a long journey."
  },
  AvgDialog_118946_Content_55 = {
    Text = "Then... tell me all about that place you call Mythag."
  },
  AvgDialog_118946_Content_56 = {Text = "..."},
  AvgDialog_118946_Content_57 = {Text = "..."},
  AvgDialog_118946_Content_58 = {
    Text = "And then? What happened next?"
  },
  AvgDialog_118946_Content_59 = {
    Text = "Then Ramona discovered the wine that Lord Dexter had hidden in the corner of her bookcase. To conceal the bottles, he had even carved holes into some of her books."
  },
  AvgDialog_118946_Content_6 = {
    Text = "We also know there is only one lifeboat in the lower deck. Once we leave this cruise ship, we will no longer be under Miryam's control."
  },
  AvgDialog_118946_Content_60 = {
    Text = "You catch a glimpse of William with his head down, frowning and rubbing his temples."
  },
  AvgDialog_118946_Content_61 = {
    Text = "Burning with anger, she stormed into Lady Sorel's salon with her sword drawn!"
  },
  AvgDialog_118946_Content_62 = {
    Text = "And then what?"
  },
  AvgDialog_118946_Content_63 = {
    Text = "Murphy nervously clutches your sleeve, her appetite piqued by the intriguing story."
  },
  AvgDialog_118946_Content_64 = {
    Text = "The laughter and chatter in the salon suddenly froze, and everyone stared wide-eyed at the uninvited guest!"
  },
  AvgDialog_118946_Content_65 = {
    Text = "That's right, just like the look on William's face right now!"
  },
  AvgDialog_118946_Content_66 = {
    Text = "%player%..."
  },
  AvgDialog_118946_Content_67 = {
    Text = "Assassin! It's an assassin! People started shouting all around!"
  },
  AvgDialog_118946_Content_68 = {
    Text = "Suddenly, your smile freezes on your face."
  },
  AvgDialog_118946_Content_69 = {
    Text = "Behind Murphy, at the edge of the small boat, a towering monster made up of countless fused corpses suddenly rises from the sea."
  },
  AvgDialog_118946_Content_7 = {
    Text = "Our plan is for me to crash the Ritual of Navigation and take advantage of Murphy's weakness to jump into the sea with her."
  },
  AvgDialog_118946_Content_70 = {Text = "<Big:...>"},
  AvgDialog_118946_Content_71 = {
    Text = "It silently opens its gigantic maw, formed by writhing bones and a skull—"
  },
  AvgDialog_118946_Content_72 = {
    Text = "<Red:And swallows Murphy whole.>"
  },
  AvgDialog_118946_Content_73 = {
    Text = "<Shake:No... the Puppet of Putrescence... Didn't we defeat it in Necrovia...>"
  },
  AvgDialog_118946_Content_74 = {
    Text = "At this point in this Domain... Goliath is still controlling the Puppet of Putrescence."
  },
  AvgDialog_118946_Content_75 = {
    Text = "His main forces are engaged in combat with Miryam, so he dispatched this external lineup to pursue us..."
  },
  AvgDialog_118946_Content_76 = {
    Text = "We... miscalculated."
  },
  AvgDialog_118946_Content_77 = {
    Text = "<BigShake:...!!!>"
  },
  AvgDialog_118946_Content_78 = {
    Text = "The giant creature that devoured Murphy raises its strange head high, emitting a satisfied gurgling sound from its throat."
  },
  AvgDialog_118946_Content_79 = {
    Text = "The fouled, filthy mist diffuses over the sea. The Paradise is long out of sight in the distance; only the towering mountain of skeletons looms over, blocking out the light."
  },
  AvgDialog_118946_Content_8 = {
    Text = "William will drive the lifeboat to pick up Murphy and me. After boarding, I will quickly unravel the mystery of the ivory sculpture and escape from the Domain."
  },
  AvgDialog_118946_Content_80 = {Text = "Watch out!"},
  AvgDialog_118946_Content_81 = {
    Text = "William holds you tightly and rolls toward the side of the ship, narrowly dodging the bone claw's initial strike."
  },
  AvgDialog_118946_Content_82 = {
    Text = "William, your back..."
  },
  AvgDialog_118946_Content_83 = {
    Text = "All you can see is his blood. Blood, trickling down his spine."
  },
  AvgDialog_118946_Content_84 = {
    Text = "Don't worry about me. Get up there! Sever its spine!"
  },
  AvgDialog_118946_Content_85 = {Text = "..."},
  AvgDialog_118946_Content_86 = {Text = "<Big:...>"},
  AvgDialog_118946_Content_87 = {
    Text = "The Puppet of Putrescence collapses like a tall tower, falling into the infinite ocean."
  },
  AvgDialog_118946_Content_88 = {
    Text = "As you said... Goliath's strength was greatly weakened in the Domain."
  },
  AvgDialog_118946_Content_89 = {
    Text = "That's why we were able to survive its attack..."
  },
  AvgDialog_118946_Content_9 = {
    Text = "The woman lowers her head, her fine bangs obscuring her expression."
  },
  AvgDialog_118946_Content_90 = {
    Text = "Perhaps because the injury is too severe, you can no longer hear William's words."
  },
  AvgDialog_118946_Content_91 = {
    Text = "Amidst the collapsed tide of corpses and bones, the maiden's figure is also nowhere to be seen."
  },
  AvgDialog_118946_Content_92 = {
    Text = "Murphy... Murphy!"
  },
  AvgDialog_118946_Content_93 = {
    Text = "You rush toward the floating pile of skeletons, digging through the piled skulls, one piece after another, at the location of the creature's belly."
  },
  AvgDialog_118946_Content_95 = {
    Text = "Murphy is nowhere to be found."
  },
  AvgDialog_118946_Content_96 = {
    Text = "In the midst of the haphazard bones, there is only a piece of thin, light black gauze."
  },
  AvgDialog_118946_Content_97 = {
    Text = "You gently lift the piece of black gauze, and a wave of sorrow rises in your heart."
  },
  AvgDialog_118946_Content_98 = {
    Text = "I thought, this time, I could surely take her out of here..."
  },
  AvgDialog_118946_Content_99 = {
    Text = "You let out a low, muffled sob, which gradually rises to a louder weeping."
  },
  AvgDialog_118947_Content_1 = {
    Text = "The Paradise Cruise"
  },
  AvgDialog_118947_Content_10 = {
    Text = "You pull the baking tray out, and Murphy immediately reaches out eagerly to grab a steaming cupcake."
  },
  AvgDialog_118947_Content_11 = {
    Text = "Don't rush, it's too hot!"
  },
  AvgDialog_118947_Content_12 = {
    Text = "Murphy seems completely unwilling to let go, switching the cake back and forth between her left and right hands a few times until it finally cools down to a suitable temperature."
  },
  AvgDialog_118947_Content_13 = {
    Text = "Take a bite... It seems I don't need to say anything."
  },
  AvgDialog_118947_Content_14 = {
    Text = "Before you can finish your sentence, Murphy has already taken a bite."
  },
  AvgDialog_118947_Content_15 = {
    Text = "How do you like it?"
  },
  AvgDialog_118947_Content_16 = {
    Text = "The recipe relies entirely on your memory. To take care of the young lady who cries for food in the middle of the night, you have borrowed the back kitchen of Mythag multiple times."
  },
  AvgDialog_118947_Content_17 = {
    Text = "Hmph. Such simple ingredients. A pale shadow of what Miryam provides me."
  },
  AvgDialog_118947_Content_18 = {
    Text = "Murphy carefully swallows the remnants in her mouth and says seriously."
  },
  AvgDialog_118947_Content_19 = {
    Text = "No matter... it merely proves my talent is great enough to appreciate the miraculous simplicity."
  },
  AvgDialog_118947_Content_2 = {Text = "..."},
  AvgDialog_118947_Content_20 = {
    Text = "Warm and soft... this is the most delicious food I've ever had."
  },
  AvgDialog_118947_Content_21 = {
    Text = "I'll try a piece too."
  },
  AvgDialog_118947_Content_22 = {
    Text = "William carefully picks up a piece with a silver scapel and brings it to his mouth."
  },
  AvgDialog_118947_Content_23 = {
    Text = "William... If I'm not mistaken, you dissected Nubia cubs with the same scapel before?"
  },
  AvgDialog_118947_Content_24 = {
    Text = "It has been thoroughly disinfected. The crude knives and forks used by those sailors are really hard to eat with."
  },
  AvgDialog_118947_Content_25 = {
    Text = "I should have asked Doresain for two sets of cutlery before leaving Necrovia... Never mind, what Doresain's cutlery has cut through is even more concerning..."
  },
  AvgDialog_118947_Content_26 = {
    Text = "You feast heartily, laughing as you smear cream on each other's faces."
  },
  AvgDialog_118947_Content_27 = {
    Text = "(If this is going to be the last thing she remembers, then at least make it a happy one...)"
  },
  AvgDialog_118947_Content_28 = {Text = "BANG!"},
  AvgDialog_118947_Content_29 = {
    Text = "A loud bang shatters the rare tranquility, and the kitchen you are in suddenly begins to shake violently and uncontrollably."
  },
  AvgDialog_118947_Content_3 = {
    Text = "Dozens of minutes later."
  },
  AvgDialog_118947_Content_30 = {
    Text = "What's going on?!"
  },
  AvgDialog_118947_Content_31 = {
    Text = "Goliath plunders the engine room, Miryam fiercely resists, and an explosion occurs in the engine room."
  },
  AvgDialog_118947_Content_32 = {
    Text = "You reply calmly."
  },
  AvgDialog_118947_Content_33 = {
    Text = "In other words, the ship is going to sink."
  },
  AvgDialog_118947_Content_34 = {
    Text = "The ship is sinking, aren't you going to react at all?"
  },
  AvgDialog_118947_Content_35 = {
    Text = [[
Murphy, I have something to tell you.
This ship is bound to sink.]]
  },
  AvgDialog_118947_Content_36 = {
    Text = "I have gone through five cycles, and in each cycle, Goliath always sets up for a heist."
  },
  AvgDialog_118947_Content_37 = {
    Text = "This process triggers an explosion in the engine room, and then the ship is sucked to the bottom of the sea by a vortex."
  },
  AvgDialog_118947_Content_38 = {Text = "So...?"},
  AvgDialog_118947_Content_39 = {
    Text = "I have been trying to prevent the destruction of this ship, and that led to a flaw in my thinking."
  },
  AvgDialog_118947_Content_4 = {
    Text = "You stare at the oven as the kneaded dough slowly puffs up, and your heart, filled with anticipation, swells lightly with the fluffy curve."
  },
  AvgDialog_118947_Content_40 = {
    Text = "This ship must sink... Only by sinking can it clear a path to freedom for you."
  },
  AvgDialog_118947_Content_41 = {Text = "BOOM!"},
  AvgDialog_118947_Content_42 = {
    Text = "The hull convulses and trembles as if struck by lightning, like a giant beast losing control and twitching in the agony of an explosion."
  },
  AvgDialog_118947_Content_43 = {
    Text = "Alright, no need to explain so much now. Hurry and follow me."
  },
  AvgDialog_118947_Content_44 = {
    Text = "Any later, and we'll be too late for everything."
  },
  AvgDialog_118947_Content_45 = {
    Text = "You pull Murphy along the path pointed out by William."
  },
  AvgDialog_118947_Content_46 = {
    Text = "Hey, do I really have to climb this ladder? It's humiliating to be scrambling on all fours in front of an audience!"
  },
  AvgDialog_118947_Content_47 = {
    Text = "Then you go down and wait for me there. I promise to not look at you."
  },
  AvgDialog_118947_Content_48 = {
    Text = "Your eyes adapt to the darkness. In the corner of the cargo hold, a small boat is parked alone."
  },
  AvgDialog_118947_Content_49 = {
    Text = "This is the escape route Goliath prepared for himself, and we've found it."
  },
  AvgDialog_118947_Content_5 = {
    Text = "The aroma of custard wafts everywhere, and your salivary glands detect it before your brain does, making your stomach growl with hunger."
  },
  AvgDialog_118947_Content_50 = {
    Text = "That cunning man destroyed all the lifeboats before starting the rebellion, ensuring that only he could escape."
  },
  AvgDialog_118947_Content_51 = {
    Text = "Here you go; this is the spare key that Senior William replicated. Now, board the ship."
  },
  AvgDialog_118947_Content_52 = {
    Text = "Wait, what are you talking about? I never agreed to escape with you—"
  },
  AvgDialog_118947_Content_53 = {
    Text = "I never said I would board the ship with you. There is, and only one lifeboat here. You get on it alone, then go ashore."
  },
  AvgDialog_118947_Content_54 = {Text = "!"},
  AvgDialog_118947_Content_55 = {
    Text = "If we leave like this, Miryam won't let it go. One day, the shadows from the Seafarers will catch up to you."
  },
  AvgDialog_118947_Content_56 = {
    Text = "I must stay here to ensure that the Seafarers and the Divine Fetus are forever sunk in the sea."
  },
  AvgDialog_118947_Content_57 = {
    Text = "This is also what they are pleased to see: returning to their eternal homeland and Divine Realm, isn't it?"
  },
  AvgDialog_118947_Content_58 = {Text = "Pfft—"},
  AvgDialog_118947_Content_59 = {
    Text = "Murphy laughs through her tears."
  },
  AvgDialog_118947_Content_6 = {
    Text = "The Seafarer's distorted, moist, and anxious footsteps occasionally echo along the wooden floor, while the thin gateway separates two worlds. This little space is filled with an overly simple happiness and warmth, reminiscent of a phantasm."
  },
  AvgDialog_118947_Content_60 = {
    Text = "I planned it before setting off."
  },
  AvgDialog_118947_Content_61 = {
    Text = "If I can help you escape, then this is already the best ending."
  },
  AvgDialog_118947_Content_62 = {
    Text = "If I can't... at least I've tried to recreate a day that the Murphy I know would love."
  },
  AvgDialog_118947_Content_63 = {
    Text = "We haven't known each other for long, and my understanding of you isn't very deep. I hope you like it too."
  },
  AvgDialog_118947_Content_64 = {
    Text = "Murphy tiptoes and gives you a gentle hug."
  },
  AvgDialog_118947_Content_65 = {
    Text = "I remember you said that you would go through the cycle over and over again."
  },
  AvgDialog_118947_Content_66 = {
    Text = "This time it won't be the end."
  },
  AvgDialog_118947_Content_67 = {
    Text = "Next time, take me with you to escape, okay?"
  },
  AvgDialog_118947_Content_68 = {
    Text = [[
<Red:There won't be a next time.>
A sour sensation rushes to your nose.]]
  },
  AvgDialog_118947_Content_69 = {
    Text = "I promise you. We'll get out of here together."
  },
  AvgDialog_118947_Content_7 = {
    Text = "Look, the skin has changed color, it's ready to be served!"
  },
  AvgDialog_118947_Content_70 = {
    Text = "With dense clouds overhead, under the ship's figurehead, Miryam and Goliath confront each other from afar."
  },
  AvgDialog_118947_Content_71 = {
    Text = "Hand over that little girl and the ivory statue. Then I might grant you a dignified death, like how you once threatened me."
  },
  AvgDialog_118947_Content_72 = {
    Text = "Stop babbling nonsense. Wasn't it you who abducted the Divine Mother and caused this revolt?"
  },
  AvgDialog_118947_Content_73 = {
    Text = [[
No need to argue. Murphy isn't on this ship anymore.
She has escaped your clutches and distanced herself from this mess.]]
  },
  AvgDialog_118947_Content_74 = {
    Text = "An inexplicable surge of sweet vindication floods your heart."
  },
  AvgDialog_118947_Content_75 = {
    Text = "So <Italic:you> sent her out? You've got some guts."
  },
  AvgDialog_118947_Content_76 = {
    Text = "If you're planning to fight her here, I wouldn't mind taking advantage of the chaos."
  },
  AvgDialog_118947_Content_77 = {
    Text = "It's actually you, an insignificant outsider..."
  },
  AvgDialog_118947_Content_78 = {
    Text = "Do you think you can do as you please with the Divine Mother's protection?"
  },
  AvgDialog_118947_Content_79 = {
    Text = "Miryam, I want to talk to you."
  },
  AvgDialog_118947_Content_8 = {Text = "Nice!"},
  AvgDialog_118947_Content_80 = {
    Text = "So you want a conversation before declaring war on us?"
  },
  AvgDialog_118947_Content_81 = {
    Text = "Fine. I am also curious about what kind of reckless person you are, to be summoned by Divine Mother and still act so thoughtlessly and fearlessly."
  },
  AvgDialog_118947_Content_82 = {
    Text = "If you sincerely seek answers from the Apostle of God, I might as well bestow upon you His divine will."
  },
  AvgDialog_118947_Content_83 = {
    Text = "<Red:<Shake:But first, you must bear the wrath of the Seafarers!>>"
  },
  AvgDialog_118947_Content_9 = {
    Text = "The aroma of egg and milk bursts forth."
  },
  AvgDialog_118948_Content_1 = {Text = "Vortex"},
  AvgDialog_118948_Content_10 = {
    Text = "The silver thread instantly breaks with a snap."
  },
  AvgDialog_118948_Content_11 = {
    Text = "Caecus is completely unaware of what just happened. He merely scans you with suspicion."
  },
  AvgDialog_118948_Content_12 = {
    Text = "Friends? You and I? What are you talking about?"
  },
  AvgDialog_118948_Content_13 = {
    Text = "It must be a trick to confuse you! Don't listen to {Male=him,Female=her}, Lord Caecus!"
  },
  AvgDialog_118948_Content_14 = {
    Text = "Yes... I should focus on the order I received..."
  },
  AvgDialog_118948_Content_15 = {
    Text = "Caecus takes a deep breath, as if courage is being infused back into his body, and suddenly lifts his head."
  },
  AvgDialog_118948_Content_16 = {
    Text = "All I know is that the Seafarers have temporarily placed you here, but that doesn't mean you can come and go freely in critical areas."
  },
  AvgDialog_118948_Content_17 = {
    Text = "As per Lord Goliath's orders, unauthorized personnel are not allowed to enter the engine room!"
  },
  AvgDialog_118948_Content_2 = {
    Text = "Look, someone is guarding the engine room."
  },
  AvgDialog_118948_Content_3 = {
    Text = "Several hunched figures wander about. Among them, a young man with an upright posture tightly grips a membranous spear, cautiously alert to the rustles of the surroundings."
  },
  AvgDialog_118948_Content_4 = {
    Text = "Keep your eyes open! This is an important task from Lord Goliath..."
  },
  AvgDialog_118948_Content_5 = {Text = "Caecus!"},
  AvgDialog_118948_Content_6 = {
    Text = "Hmm? You're that..."
  },
  AvgDialog_118948_Content_7 = {
    Text = "You try to activate the Silver Key, connecting with his consciousness to awaken your shared past memories."
  },
  AvgDialog_118948_Content_8 = {
    Text = "Silver phantasmal tendrils extend and crawl along the surface of his body, covered in scales, delving deep into his spinal cord..."
  },
  AvgDialog_118948_Content_9 = {
    Text = "Caecus, we're friends. Can you let me into that room..."
  },
  AvgDialog_118949_Content_1 = {
    Text = "Sorry, Lord Goliath..."
  },
  AvgDialog_118949_Content_10 = {
    Text = "But my plan is at a critical juncture. You're an uncertainty I can't afford."
  },
  AvgDialog_118949_Content_11 = {
    Text = "I'll shut you up forever now, kid."
  },
  AvgDialog_118949_Content_12 = {
    Text = "Lord Goliath, I will fight alongside you!"
  },
  AvgDialog_118949_Content_13 = {
    Text = "No need for that, you weak little thing. This place is too cramped for us both."
  },
  AvgDialog_118949_Content_14 = {
    Text = "<Small:But I...>"
  },
  AvgDialog_118949_Content_15 = {
    Text = "Caecus mutters softly, but the recent defeat in battle makes him realize he has no grounds to continue complaining, so he falls silent and takes a step back."
  },
  AvgDialog_118949_Content_16 = {Text = "Caecus."},
  AvgDialog_118949_Content_17 = {Text = "Hmm?"},
  AvgDialog_118949_Content_18 = {
    Text = "Goliath does not turn back."
  },
  AvgDialog_118949_Content_19 = {
    Text = "Don't be discouraged. You are the one I've chosen. Once this is settled, I will do five hundred more training sessions with you."
  },
  AvgDialog_118949_Content_2 = {
    Text = "Shush it, Caecus."
  },
  AvgDialog_118949_Content_20 = {
    Text = "Ah... Yes, sir!"
  },
  AvgDialog_118949_Content_21 = {
    Text = "Faros, are you ready?"
  },
  AvgDialog_118949_Content_22 = {
    Text = "To build the ladder to Divine Realm... Faros will always be at your service."
  },
  AvgDialog_118949_Content_3 = {
    Text = "Goliath steps out slowly, holding the blade upside down, the serrated edge dragging on the ground and making a grating screeching sound."
  },
  AvgDialog_118949_Content_4 = {
    Text = "Can't even handle this little commotion, huh? And you want to call yourself a Philistine? Try again."
  },
  AvgDialog_118949_Content_5 = {
    Text = "Sorry, I..."
  },
  AvgDialog_118949_Content_6 = {
    Text = "Gurgle, Lord Goliath, please don't blame Lord Caecus! That {Male=man,Female=woman} can summon invisible monsters!"
  },
  AvgDialog_118949_Content_7 = {
    Text = "Speaking of that... You. I'm talking to you."
  },
  AvgDialog_118949_Content_8 = {
    Text = "Necrovia is one thing. But this ship is no place for you to mess around."
  },
  AvgDialog_118949_Content_9 = {
    Text = "Under different circumstances, I'd take the time to figure you out. Maybe even have a chat."
  },
  AvgDialog_118950_Content_1 = {
    Text = "The sky is burning."
  },
  AvgDialog_118950_Content_10 = {
    Text = "A crimson slick of blood trails behind him, soaking into the deck."
  },
  AvgDialog_118950_Content_11 = {
    Text = "<Red:Die! You bastard heretic!>"
  },
  AvgDialog_118950_Content_12 = {
    Text = "With bulging eyes, a Seafarer priest raises Caecus's spear and mercilessly drives its sharp tip through his back, pinning him to the deck."
  },
  AvgDialog_118950_Content_13 = {
    Text = "Caecus twitches and finally stops moving, his body just one step away from Goliath."
  },
  AvgDialog_118950_Content_14 = {
    Text = "Haha! HAHAHAHA!"
  },
  AvgDialog_118950_Content_15 = {
    Text = "Oh Lord, our Lord, do you see? This is the Sacrament that I and the Divine Mother present to you!"
  },
  AvgDialog_118950_Content_16 = {
    Text = "Miryam, her face drenched in blood, stares at this hellish scene, laughing maniacally at the sky, her torn robe fluttering in the flames."
  },
  AvgDialog_118950_Content_17 = {
    Text = "<Shake:May Your Divine Realm rise again from the Abyss! May Your will be enacted upon the Earth!>"
  },
  AvgDialog_118950_Content_18 = {
    Text = "The Priestess's triumphant gaze sweeps across her territory, sliding past Faros's body, which lies cleaved in two, past the two gravely injured Investigators, and coming to rest upon the young maiden, drenched in blood and venom."
  },
  AvgDialog_118950_Content_19 = {
    Text = "Divine Mother, come to my side. I have sanctioned all the heretics who have forsaken the light and the fallen ones who have desecrated the divine!"
  },
  AvgDialog_118950_Content_2 = {
    Text = "The sea is burning."
  },
  AvgDialog_118950_Content_20 = {
    Text = "The damaged hull of the ship loses its balance due to water infiltration. Half of the ship's body has already sunk beneath the surface, yet she remains completely oblivious."
  },
  AvgDialog_118950_Content_21 = {
    Text = "<Red:<Shake:Next, the two of us shall inherit the immortality of the Divine Realm. On the next eve of stellar alignment, His holy name shall be proclaimed throughout the universe!>>"
  },
  AvgDialog_118950_Content_22 = {
    Text = "The ship's slanted bow hangs like a guillotine. Miryam stands at the tip of it, stretching out her bloodied hand from above."
  },
  AvgDialog_118950_Content_23 = {
    Text = "<Shake:No, no... It shouldn't be...>"
  },
  AvgDialog_118950_Content_24 = {
    Text = "Murphy's legs go weak, and she kneels on the ground. Her petite body has completely lost its former elegance, trembling in the light of flames."
  },
  AvgDialog_118950_Content_25 = {
    Text = "<Shake:Sorry, I shouldn't... I shouldn't have wanted to run...>"
  },
  AvgDialog_118950_Content_26 = {
    Text = "Tears roll down, leaving mottled water stains on the deck, only to be licked dry by the heat of the flames."
  },
  AvgDialog_118950_Content_27 = {
    Text = "<Red:<Shake:I should have known. This is a fate I cannot avoid. I cannot escape...>>"
  },
  AvgDialog_118950_Content_28 = {
    Text = "Murphy... No, Murphy, there's still a chance..."
  },
  AvgDialog_118950_Content_29 = {
    Text = "You are anxious to step forward and comfort her, but your body betrays your will."
  },
  AvgDialog_118950_Content_3 = {
    Text = "Not literally, perhaps—but everything you see is burning.\nDeath and despair shroud this lawless place, a scar upon the vast sea."
  },
  AvgDialog_118950_Content_30 = {
    Text = "The excruciating pain in your ankle. The wounds you suffered in the recent battle pin you firmly in place, making it impossible to move a step."
  },
  AvgDialog_118950_Content_31 = {Text = "Sorry."},
  AvgDialog_118950_Content_32 = {
    Text = "Calmly, the girl rises to her feet, paying no mind to the blood flowing from her chest wound."
  },
  AvgDialog_118950_Content_33 = {
    Text = "The pain can no longer hold her back. In her eyes, there is no hesitation, no delusion, and nothing left to regret."
  },
  AvgDialog_118950_Content_34 = {
    Text = [[
Crossing over mountains of corpses and seas of fire.
She walked solemnly, step by step, towards the Priestess.]]
  },
  AvgDialog_118950_Content_35 = {
    Text = "No... it can't end here..."
  },
  AvgDialog_118950_Content_36 = {
    Text = "William... William! Can you still move?"
  },
  AvgDialog_118950_Content_37 = {
    Text = "What... do you want..."
  },
  AvgDialog_118950_Content_38 = {
    Text = "William lies in a pool of blood, fighting for breath."
  },
  AvgDialog_118950_Content_39 = {
    Text = "<BigRed:...Kill me. Restart the cycle.>"
  },
  AvgDialog_118950_Content_4 = {
    Text = "A chain of explosions tears open the engine room; the burning deck twists and rises."
  },
  AvgDialog_118950_Content_40 = {
    Text = "No... Why..."
  },
  AvgDialog_118950_Content_41 = {
    Text = "I can't let it end here... I can't accept such an outcome..."
  },
  AvgDialog_118950_Content_42 = {
    Text = "Hurry! I can't move anymore..."
  },
  AvgDialog_118950_Content_43 = {
    Text = "William's mechanical arm lay severed from his body. He barely extends his remaining arm, grasping the dagger that Miryam had thrown aside."
  },
  AvgDialog_118950_Content_44 = {
    Text = "Sorry, I can't bear to let you see my face right now..."
  },
  AvgDialog_118950_Content_45 = {
    Text = "As he moves, a piercing pain radiates from your left lower back."
  },
  AvgDialog_118950_Content_46 = {
    Text = "DON'T YOU DARE!"
  },
  AvgDialog_118950_Content_47 = {
    Text = "Priest! Capture {Male=him,Female=her} alive! Don't let {Male=him,Female=her} die!"
  },
  AvgDialog_118950_Content_48 = {
    Text = "At Miryam's command, another trident pierces William's chest. Stunned, you look back only to see his golden hair softly slump."
  },
  AvgDialog_118950_Content_49 = {
    Text = "The Seafarer priest spins in an eerie circle, bursting into laughter."
  },
  AvgDialog_118950_Content_5 = {
    Text = "Comrades and enemies lie indistinguishable now, united in a final, scalding crimson embrace."
  },
  AvgDialog_118950_Content_50 = {
    Text = "GURGLE! Hehe, whatever you wanted to do, you can't do it now!"
  },
  AvgDialog_118950_Content_51 = {
    Text = "Grief tears at your heart, overriding the physical pain. Your bloodless limbs are icy and aching."
  },
  AvgDialog_118950_Content_52 = {
    Text = "<Red:You must die.> You must move on to the next cycle."
  },
  AvgDialog_118950_Content_53 = {
    Text = "<Red:<Shake:I... I can do this...>>"
  },
  AvgDialog_118950_Content_54 = {
    Text = "Press the dagger against the deck."
  },
  AvgDialog_118950_Content_55 = {
    Text = "The dagger slowly sinks into your body, followed by a pain that pierces deep into your bones."
  },
  AvgDialog_118950_Content_56 = {
    Text = "Fall back onto the dagger."
  },
  AvgDialog_118950_Content_57 = {
    Text = "The sharp blade pierces through your chest, and the void of fleeting consciousness envelops your vision."
  },
  AvgDialog_118950_Content_58 = {
    Text = "<Shake:Murphy... William... Please, wait for me in the next cycle.>"
  },
  AvgDialog_118950_Content_59 = {
    Text = "<Yellow:I will... get us out of here.>"
  },
  AvgDialog_118950_Content_6 = {
    Text = "<Shake:Sorry, Lord Goliath... If only I were a little stronger...>"
  },
  AvgDialog_118950_Content_7 = {
    Text = "Severely wounded, Caecus drags his body across the floor, raking the ground with bleeding fingers toward Goliath's lifeless form."
  },
  AvgDialog_118950_Content_8 = {
    Text = "<Shake:Lord... Goliath...>"
  },
  AvgDialog_118950_Content_9 = {
    Text = "No matter how he calls out, the man wouldn't respond."
  },
  AvgDialog_118951_Content_1 = {
    Text = "So, what exactly did you trick me into coming here for?"
  },
  AvgDialog_118951_Content_10 = {
    Text = "Let's do something that has nothing to do with the doctrines and rituals."
  },
  AvgDialog_118951_Content_11 = {
    Text = "I know you don't really like any of that, despite talking about them all the time."
  },
  AvgDialog_118951_Content_12 = {
    Text = "Enough talking. Take this, Murphy!"
  },
  AvgDialog_118951_Content_13 = {
    Text = "Th-This is?"
  },
  AvgDialog_118951_Content_14 = {
    Text = "Now stir! Stir quickly, in one direction!"
  },
  AvgDialog_118951_Content_15 = {Text = "..."},
  AvgDialog_118951_Content_16 = {
    Text = "Then, add flour! Baking powder! A little bit of salt!"
  },
  AvgDialog_118951_Content_17 = {
    Text = "William, don't just stand there! Go help melt the butter!"
  },
  AvgDialog_118951_Content_18 = {Text = "...Sure."},
  AvgDialog_118951_Content_19 = {
    Text = "William walks away, patiently playing the role of the flustered yet responsible chef assistant in the chaotic kitchen."
  },
  AvgDialog_118951_Content_2 = {
    Text = "Come closer. Senior William has a magic trick for you!"
  },
  AvgDialog_118951_Content_20 = {
    Text = "Finally, you put the mixed dough into the oven."
  },
  AvgDialog_118951_Content_21 = {
    Text = "Murphy gazes blankly at the oven."
  },
  AvgDialog_118951_Content_22 = {
    Text = "I remembered something... from a long time ago..."
  },
  AvgDialog_118951_Content_23 = {Text = "Hmm?"},
  AvgDialog_118951_Content_24 = {
    Text = "That was back when we were at the Antarctic base. I discovered an altar in a mountain pass, adorned with many delicate stone carvings."
  },
  AvgDialog_118951_Content_25 = {
    Text = "I asked mommy... I asked Miryam to get me a small knife and some wooden blocks; I wanted to make some wood carvings."
  },
  AvgDialog_118951_Content_26 = {
    Text = "After a long time, she only gave me a dull knife, saying she was worried that \"the sacred body of Divine Mother might be harmed.\""
  },
  AvgDialog_118951_Content_27 = {
    Text = "I felt like my body didn't belong to myself. It didn't belong to her, either. It seemed we were both merely bricks from that so-called Divine Realm, stuck in our own places, unable to move at all."
  },
  AvgDialog_118951_Content_28 = {
    Text = "I saw some wooden carvings at the head of your bed."
  },
  AvgDialog_118951_Content_29 = {
    Text = "Yes. I secretly asked Goliath to help me find a piece of whetstone."
  },
  AvgDialog_118951_Content_3 = {
    Text = "I've brought everything back according to your list, %player%. Check them out."
  },
  AvgDialog_118951_Content_30 = {
    Text = "I put in a lot of effort just to barely sharpen the blade enough to cut through wood."
  },
  AvgDialog_118951_Content_31 = {
    Text = "I carved for many days, striving to recreate every detail I imagined."
  },
  AvgDialog_118951_Content_32 = {
    Text = "When I finally felt satisfied, I gave it to Miryam..."
  },
  AvgDialog_118951_Content_33 = {
    Text = "Do you know what she said?"
  },
  AvgDialog_118951_Content_34 = {
    Text = "Miryam... she said your carving was bad and desecrated her god?"
  },
  AvgDialog_118951_Content_35 = {
    Text = "You carefully ponder Miryam's mindset and cautiously offer a guess."
  },
  AvgDialog_118951_Content_36 = {Text = "No."},
  AvgDialog_118951_Content_37 = {
    Text = "She didn't even look at it. She just said that if I desired a sculpture of that type, she could arrange for the finest craftsmen to produce one for me every single day."
  },
  AvgDialog_118951_Content_38 = {
    Text = "Murphy laughs maniacally. An indescribable pain and taunt spill out with her rigid smile, tightening around your heart."
  },
  AvgDialog_118951_Content_39 = {
    Text = "Called me the Daughter of the God and His womb vessel. Said whatever I wanted, I could have it with a wave of my hand."
  },
  AvgDialog_118951_Content_4 = {
    Text = "William opens the various pockets on his chest, back, and arms, one after another."
  },
  AvgDialog_118951_Content_40 = {
    Text = "Trivial. That's what it was. Just a trivial little thing."
  },
  AvgDialog_118951_Content_41 = {
    Text = "She laughs and laughs, choking on her tears. Tears quickly slide down her distorted cheeks from the maniacal laughter."
  },
  AvgDialog_118951_Content_42 = {
    Text = "I've seen the work you placed by the head of the bed, your craftsmanship is quite good."
  },
  AvgDialog_118951_Content_43 = {
    Text = "Am I good at it? So what, it doesn't matter anymore..."
  },
  AvgDialog_118951_Content_44 = {
    Text = "Murphy, from now on, you will carve however you want."
  },
  AvgDialog_118951_Content_45 = {
    Text = "Then we can make some cupcakes together and study floral arrangements."
  },
  AvgDialog_118951_Content_46 = {
    Text = "I will find a way to return to my world, and when I do, I will introduce you to the Murphy I know. The two of you can freely do everything you want to do together."
  },
  AvgDialog_118951_Content_47 = {
    Text = "Murphy covers her face to wipe away her tears, then lifts her head and gives you a radiant smile that you have never seen before."
  },
  AvgDialog_118951_Content_48 = {
    Text = "Sure. Remember your promise."
  },
  AvgDialog_118951_Content_49 = {
    Text = "Do not bail on me, okay?"
  },
  AvgDialog_118951_Content_5 = {
    Text = "Let's thank the great god of magic, William, for the raw materials he stole from the kitchen for us."
  },
  AvgDialog_118951_Content_50 = {
    Text = "Your story had nothing to do with the Divine Mother."
  },
  AvgDialog_118951_Content_51 = {
    Text = "But it seems she has never been happier."
  },
  AvgDialog_118951_Content_6 = {
    Text = "Flour, eggs, lemon, honey, sugar, baking powder, and butter..."
  },
  AvgDialog_118951_Content_7 = {
    Text = "We've got it all! Luckily, the sailor's uniform comes with a lot of pockets."
  },
  AvgDialog_118951_Content_8 = {
    Text = "I still don't understand... why?"
  },
  AvgDialog_118951_Content_9 = {
    Text = "Don't you want to try baking the cakes you usually eat by yourself?"
  },
  AvgDialog_118952_Content_1 = {Text = "Seven Days"},
  AvgDialog_118952_Content_10 = {
    Text = "I begged an answer from the god."
  },
  AvgDialog_118952_Content_11 = {
    Text = "I asked about the future of the Divine Realm, about the connection between Him and me, everything I wanted to know, and everything Miryam sought to probe."
  },
  AvgDialog_118952_Content_12 = {
    Text = "The god remained silent."
  },
  AvgDialog_118952_Content_13 = {
    Text = "<color=#E6E6E6>Day five after His birth.</color>"
  },
  AvgDialog_118952_Content_14 = {
    Text = "Miryam asked me the outcome of my audience with the god."
  },
  AvgDialog_118952_Content_15 = {
    Text = "In a moment of desperation, I made up a reply, \"The Divine Realm is about to rise.\""
  },
  AvgDialog_118952_Content_16 = {
    Text = "She kept asking about the exact time, and I could only respond, \"When the stars are right.\""
  },
  AvgDialog_118952_Content_17 = {
    Text = "Miryam was ecstatic. It was a frenzied joy I had never seen before—not when I gifted her the wooden carving, not even when I conceived the Divine Fetus."
  },
  AvgDialog_118952_Content_18 = {
    Text = "<color=#E1E1E1>Day six after His birth.</color>"
  },
  AvgDialog_118952_Content_19 = {
    Text = "Miryam asked about the location of Lemuria, and I could only respond vaguely; her expression was one of skepticism."
  },
  AvgDialog_118952_Content_2 = {
    Text = "Day one after His birth."
  },
  AvgDialog_118952_Content_20 = {
    Text = "She had seen the god when He was alive. My lies may not work on her."
  },
  AvgDialog_118952_Content_21 = {
    Text = "<Shake:God, save me, please, just one word, answer my prayer.>"
  },
  AvgDialog_118952_Content_22 = {
    Text = "<Red:Day seven after His birth.>"
  },
  AvgDialog_118952_Content_23 = {
    Text = "The god was dead. The god was never born."
  },
  AvgDialog_118952_Content_24 = {
    Text = "Lying upon my chest was only a false effigy, a mass of dead flesh mistakenly called a <Yellow:\"god.\">"
  },
  AvgDialog_118952_Content_25 = {
    Text = "Miryam never loved anyone. She never cared about anyone."
  },
  AvgDialog_118952_Content_26 = {
    Text = "After mastering the Authority of the Divine Mother, I have read all the records of the Seafarers."
  },
  AvgDialog_118952_Content_27 = {
    Text = "Every six decades, the stars align—a phenomenon that has recurred for thousands of years."
  },
  AvgDialog_118952_Content_28 = {
    Text = "I am not the first vessel you sacrificed, and I will not be the last."
  },
  AvgDialog_118952_Content_29 = {
    Text = "To stay alive... To stay with you..."
  },
  AvgDialog_118952_Content_3 = {
    Text = "The Divine Fetus was born within an ashen shell."
  },
  AvgDialog_118952_Content_30 = {
    Text = "I must kill my past self..."
  },
  AvgDialog_118952_Content_31 = {
    Text = "I must kill my naivety..."
  },
  AvgDialog_118952_Content_4 = {
    Text = "I was exhausted, spiritually drained, yet everyone's face was alight with fanatical joy."
  },
  AvgDialog_118952_Content_5 = {
    Text = "<color=#F7F7F7>Day two after His birth.</color>"
  },
  AvgDialog_118952_Content_6 = {
    Text = "I performed baptism for the fetus. He slept soundly in his cradle."
  },
  AvgDialog_118952_Content_7 = {
    Text = "<color=#F2F2F2>Day three after His birth.</color>"
  },
  AvgDialog_118952_Content_8 = {
    Text = "The Divine Fetus still had not opened His eyes. Why? I could even feel His heartbeats like my own."
  },
  AvgDialog_118952_Content_9 = {
    Text = "<color=#F0F0F0>Day four after His birth.</color>"
  },
  AvgDialog_118953_Content_1 = {
    Text = "The curtain in the sky sways and churns, resembling a raging storm."
  },
  AvgDialog_118953_Content_10 = {
    Text = "The wind stirs, and the gloomy, overcast sky begins to change."
  },
  AvgDialog_118953_Content_11 = {
    Text = "The... sun in the sky..."
  },
  AvgDialog_118953_Content_12 = {
    Text = "The false radiance fades away, and beneath the distant sky, the black veil that blots out the sun gently sways with each breath."
  },
  AvgDialog_118953_Content_13 = {
    Text = "It is a pitch-black sun."
  },
  AvgDialog_118953_Content_2 = {
    Text = "A wisp of passing breeze lifts the black veil that obscures Murphy's face, beneath which are a pair of tear-stained eyes that have long since dried up."
  },
  AvgDialog_118953_Content_3 = {
    Text = "NOW! Right there!"
  },
  AvgDialog_118953_Content_4 = {Text = "HAAHHH!"},
  AvgDialog_118953_Content_6 = {
    Text = "In the fleeting moment of the trembling sky, the jagged giant blade decisively slashes towards the wavering rift."
  },
  AvgDialog_118953_Content_7 = {
    Text = "The ivory sculpture bursts forth with a fierce white light, resembling a desperate resistance to death."
  },
  AvgDialog_118953_Content_8 = {
    Text = "Seconds later, the white light suddenly extinguishes, and the ivory sculpture shatters, creating a rain of white fragments within a diameter of twenty centimeters."
  },
  AvgDialog_118953_Content_9 = {
    Text = "It's all over..."
  },
  AvgDialog_118954_Content_1 = {Text = "Time Loop"},
  AvgDialog_118954_Content_10 = {Text = "Keeper..."},
  AvgDialog_118954_Content_11 = {Text = "Ramona!"},
  AvgDialog_118954_Content_12 = {
    Text = "Calm down and listen to me."
  },
  AvgDialog_118954_Content_13 = {
    Text = "I have experienced countless time jumps and regressed through many loops."
  },
  AvgDialog_118954_Content_14 = {
    Text = "I am quite sure that what happened to you is not a \"time loop.\""
  },
  AvgDialog_118954_Content_15 = {
    Text = "The time you have experienced is still naturally elapsed."
  },
  AvgDialog_118954_Content_16 = {
    Text = "There is no \"time loop\"..."
  },
  AvgDialog_118954_Content_17 = {
    Text = "Then the strange sights I encounter every time I awaken, the cruise ship sinking and setting sail again, and the dead Murphy resurrecting without a scratch..."
  },
  AvgDialog_118954_Content_18 = {
    Text = "Why is that?"
  },
  AvgDialog_118954_Content_19 = {
    Text = "I don't have an answer."
  },
  AvgDialog_118954_Content_2 = {
    Text = "You sense that you are dreaming."
  },
  AvgDialog_118954_Content_20 = {
    Text = "And that sun in the sky..."
  },
  AvgDialog_118954_Content_21 = {
    Text = "Ramona falls silent. She doesn't have an answer to your question."
  },
  AvgDialog_118954_Content_22 = {
    Text = "The water's surface gradually becomes turbulent, her shadow begins to sway from the edge, ultimately transforming into elusive shards of memory, scattering into the shimmering light of the waves."
  },
  AvgDialog_118954_Content_23 = {
    Text = "Scorching pain. The flames lick every inch of your skin."
  },
  AvgDialog_118954_Content_24 = {
    Text = "Your nerve endings curl from the stabbing pain, charred from dehydration, and you become light, so light that you turn into blackened, withered bones."
  },
  AvgDialog_118954_Content_25 = {
    Text = "You cough violently."
  },
  AvgDialog_118954_Content_26 = {
    Text = "Are you awake?"
  },
  AvgDialog_118954_Content_27 = {
    Text = "<Shake:...One more time... back from the start?>"
  },
  AvgDialog_118954_Content_28 = {
    Text = "If you've recovered, I'll go prepare for the ceremony."
  },
  AvgDialog_118954_Content_29 = {
    Text = "Wait, don't go, Murphy..."
  },
  AvgDialog_118954_Content_3 = {
    Text = "Dreams are the embodiment of inner desires and fears, while the dream realm consists of islands floating in the void."
  },
  AvgDialog_118954_Content_30 = {
    Text = "They... where is everyone?"
  },
  AvgDialog_118954_Content_31 = {
    Text = "Murphy takes a deep breath and exhales slowly."
  },
  AvgDialog_118954_Content_32 = {
    Text = "Everyone has their own things to attend to. You should rest well here."
  },
  AvgDialog_118954_Content_33 = {
    Text = "When the next moment of alignment arrives, this ship will reach Lemuria, and everything will be alright."
  },
  AvgDialog_118954_Content_34 = {
    Text = [[
With a creak, the door closes.
You are left alone in the living room.]]
  },
  AvgDialog_118954_Content_35 = {
    Text = "You can't just sit back and watch. You decide to take action."
  },
  AvgDialog_118954_Content_36 = {
    Text = "Any conclusion so far? After going through three full cycles?"
  },
  AvgDialog_118954_Content_37 = {
    Text = "Since the number of cycles is certain, gathering information is far more important than attempting to escape."
  },
  AvgDialog_118954_Content_38 = {
    Text = "In the first cycle, I gained a preliminary understanding of the Seafarers. The third cycle ended in a brutal failure, but I grasped the basic goals of the other people on this ship."
  },
  AvgDialog_118954_Content_39 = {
    Text = "On the contrary, the time I spent during the second cycle was wasted for nothing."
  },
  AvgDialog_118954_Content_4 = {
    Text = "In a chaotic dream filled with scattered fragments, countless colorful blades pierce your chest, refracting each other's shadows like bubbles."
  },
  AvgDialog_118954_Content_40 = {
    Text = "Now, our immediate priority is to gather more information about the Paradise and the Seafarers."
  },
  AvgDialog_118954_Content_41 = {
    Text = "Although that mysterious person hinted that there are a total of six cycles..."
  },
  AvgDialog_118954_Content_42 = {
    Text = "But have you considered that if this is the last cycle, you might be wasting a final chance?"
  },
  AvgDialog_118954_Content_43 = {
    Text = "If this is the last cycle..."
  },
  AvgDialog_118954_Content_44 = {
    Text = "You shake your head, brushing away all the ominous guesses."
  },
  AvgDialog_118954_Content_45 = {
    Text = "In the dream at the beginning of this cycle, the other Ramona provided me with a piece of information: <Yellow:time was still flowing sequentially within me.>"
  },
  AvgDialog_118954_Content_46 = {
    Text = "And you said you encountered the same events repeating in a loop..."
  },
  AvgDialog_118954_Content_47 = {Text = "!"},
  AvgDialog_118954_Content_48 = {
    Text = "So you have figured it out too, William."
  },
  AvgDialog_118954_Content_49 = {
    Text = "This is not a \"time loop.\" Rather, \"the same events have been happening in repeat\"..."
  },
  AvgDialog_118954_Content_5 = {
    Text = "You need a way to end the dream."
  },
  AvgDialog_118954_Content_50 = {
    Text = "In Mythag, I often found myself forced into similar predicaments."
  },
  AvgDialog_118954_Content_51 = {
    Text = "The \"Artificial Domain\"..."
  },
  AvgDialog_118954_Content_52 = {
    Text = "Yes. This is most likely an Artificial Domain."
  },
  AvgDialog_118954_Content_53 = {
    Text = "The Artificial Domain is merely a carrier of information; in the real world, we may be caught in a whirlwind of storms, swirling in mid-air."
  },
  AvgDialog_118954_Content_54 = {
    Text = "How was this Artificial Domain created? Why does the Domain keep restarting? What is the catalyst for its end?"
  },
  AvgDialog_118954_Content_55 = {
    Text = "Without understanding all of this, our attempts in the Domain would just be a futile exercise."
  },
  AvgDialog_118954_Content_56 = {
    Text = "We need Reason. For the past three hundred years, Reason has been helping Mythag combat the madness known as Dissolution."
  },
  AvgDialog_118954_Content_57 = {
    Text = "I believe you have also noticed. The sun we've been staring at these days is not the black sun obscured by black mist, but the pure sun of the normal world."
  },
  AvgDialog_118954_Content_58 = {
    Text = "This Domain was created before the black mist enveloped the world."
  },
  AvgDialog_118954_Content_59 = {Text = "..."},
  AvgDialog_118954_Content_6 = {
    Text = "As the Weaver of Fate, I must remain silent and cannot speak the truth."
  },
  AvgDialog_118954_Content_60 = {
    Text = "Did I say something wrong? Why are you staring at me like that?"
  },
  AvgDialog_118954_Content_61 = {
    Text = "...No. I just remembered our days back in Mythag. During the field assignments, you and Ramona were always by my side. With your help, I didn't have to think much at all."
  },
  AvgDialog_118954_Content_62 = {
    Text = "Thinking is an essential part of the investigation."
  },
  AvgDialog_118954_Content_63 = {
    Text = "So, William, who do you think is the master of this Domain?"
  },
  AvgDialog_118954_Content_64 = {
    Text = "Based on the principles of Domain formation and known information, my current hypothesis is that the Domain belongs to either Miryam or Faros."
  },
  AvgDialog_118954_Content_65 = {
    Text = "The <Yellow:\"core\"> of the Domain is the \"Ritual of Navigation,\" and tracking the whereabouts of Lemuria should be the obsession of the Domain's master."
  },
  AvgDialog_118954_Content_66 = {
    Text = "According to Mythag's records of the Sona-Nyl investigation, Goliath's goal is to seize more power. Caecus is obsessed with proving his noble bloodline. Only Miryam and Faros yearn for the glory of the Divine Realm."
  },
  AvgDialog_118954_Content_67 = {
    Text = "So we'll keep close attention to the potential Domain Masters. And then what?"
  },
  AvgDialog_118954_Content_68 = {
    Text = "As the Domain Master's desire for their goal—the obsession sustaining this reality—falters, cracks will appear, and the Cataclysm will manifest through them."
  },
  AvgDialog_118954_Content_69 = {
    Text = "However, since it's an Artificial Domain, the safety of our physical bodies can be ensured."
  },
  AvgDialog_118954_Content_7 = {
    Text = "Therefore, I have extradited the one who can provide you with revelation."
  },
  AvgDialog_118954_Content_70 = {
    Text = "Don't let your guard down. Not to mention that the Artificial Domain is still just a hypothesis for us..."
  },
  AvgDialog_118954_Content_71 = {
    Text = "AF 306, Investigator Jude Bright broke his right leg after stepping into a hunter's trap while deep in a Domain. Upon returning to reality, his right leg gradually began to necrose."
  },
  AvgDialog_118954_Content_72 = {
    Text = "The way the Domain influences reality is currently unknown, but caution is always wise."
  },
  AvgDialog_118954_Content_73 = {
    Text = "Understood."
  },
  AvgDialog_118954_Content_74 = {
    Text = "After the ritual, I will deal with Miryam, and Faros will be left to you."
  },
  AvgDialog_118954_Content_75 = {
    Text = "May the Silver Key light your path."
  },
  AvgDialog_118954_Content_76 = {
    Text = "The familiar tone momentarily leaves you in a daze, but you quickly reveal a genuine smile."
  },
  AvgDialog_118954_Content_77 = {
    Text = "May the Silver Key guide us."
  },
  AvgDialog_118954_Content_78 = {
    Text = "The solemn woman occupies a corner of the captain's cabin alone. The light above her flickers imperceptibly with her breath."
  },
  AvgDialog_118954_Content_79 = {Text = "Faros..."},
  AvgDialog_118954_Content_8 = {
    Text = "In the reflection of the rippling dream, a solemn figure emerges."
  },
  AvgDialog_118954_Content_80 = {
    Text = "The moment you open your mouth, you suddenly pause. You struggle to recall the information related to Faros, only to realize that Mythag has very few records about her."
  },
  AvgDialog_118954_Content_81 = {
    Text = "She longs to return to the Divine Realm. She leads ships at sea astray with her light."
  },
  AvgDialog_118954_Content_82 = {
    Text = "Aside from that, the other case files are all blank."
  },
  AvgDialog_118954_Content_83 = {
    Text = "What's wrong? You look bewildered, are you feeling lost?"
  },
  AvgDialog_118954_Content_84 = {
    Text = "Perhaps... I can offer you a bit of guidance?"
  },
  AvgDialog_118954_Content_85 = {
    Text = "I'm afraid..."
  },
  AvgDialog_118954_Content_86 = {
    Text = "I know who the master of this Domain is."
  },
  AvgDialog_118954_Content_9 = {
    Text = "The shadow ripples, fragmenting and reassembling, gradually stabilizing into the familiar calm visage from your memory."
  },
  AvgDialog_118955_Content_1 = {Text = "Outsider"},
  AvgDialog_118955_Content_10 = {Text = "William..."},
  AvgDialog_118955_Content_11 = {
    Text = "But you can't stay here. You must find the master of this dream to finally free him from this endless cycle of days."
  },
  AvgDialog_118955_Content_12 = {
    Text = "At the end of the ship, you find the maiden."
  },
  AvgDialog_118955_Content_13 = {
    Text = "Countless black-robed Seafarers lie sprawled around her, while she quietly leans against the Altar, holding a mass of crimson, foul-smelling rotten flesh in her hands."
  },
  AvgDialog_118955_Content_14 = {Text = "Murphy..."},
  AvgDialog_118955_Content_15 = {
    Text = "Just as you promised, you came."
  },
  AvgDialog_118955_Content_16 = {
    Text = "The master of this Dream Domain is you."
  },
  AvgDialog_118955_Content_17 = {
    Text = "Yeah, everything on this ship is a dream. Everything you see right now is just \"reality in a dream.\""
  },
  AvgDialog_118955_Content_18 = {Text = "Why?"},
  AvgDialog_118955_Content_19 = {
    Text = "Why did I create such a dream? Or why did I become who I am now?"
  },
  AvgDialog_118955_Content_2 = {
    Text = "Cough, cough!"
  },
  AvgDialog_118955_Content_20 = {
    Text = "That was a long time ago."
  },
  AvgDialog_118955_Content_21 = {
    Text = "A small figure trudged through the snow."
  },
  AvgDialog_118955_Content_22 = {
    Text = "Huff... Huff..."
  },
  AvgDialog_118955_Content_23 = {
    Text = "Since coming to Antarctica, Murphy had experienced a kind of absurd freedom."
  },
  AvgDialog_118955_Content_24 = {
    Text = "She could go anywhere alone. But no matter where she went, all she saw was a pale, endless expanse of snowfield."
  },
  AvgDialog_118955_Content_25 = {
    Text = "There wasn't even a trace of human activity, let alone another person."
  },
  AvgDialog_118955_Content_26 = {
    Text = "Am I... lost?"
  },
  AvgDialog_118955_Content_27 = {
    Text = "The girl looked back at the footprints she left behind. In the vast snowfield, a nearly straight path led to an unknowable destination."
  },
  AvgDialog_118955_Content_28 = {
    Text = "Whatever, as long as I keep moving forward, I will eventually get somewhere."
  },
  AvgDialog_118955_Content_29 = {
    Text = "She counted the rations she carried, confirming the farthest distance she could reach by being frugal."
  },
  AvgDialog_118955_Content_3 = {
    Text = "You cough forcefully, trying to expel the seawater that fills your lungs."
  },
  AvgDialog_118955_Content_30 = {
    Text = "Come on, Murphy. This is a journey towards freedom, and being a bit hungry is no big deal."
  },
  AvgDialog_118955_Content_31 = {Text = "..."},
  AvgDialog_118955_Content_32 = {Text = "..."},
  AvgDialog_118955_Content_33 = {
    Text = "No, it's impossible to tell the direction in such a snowstorm."
  },
  AvgDialog_118955_Content_34 = {
    Text = "Ration and snow water... It tastes awful."
  },
  AvgDialog_118955_Content_35 = {
    Text = "She resided in snow caves and could hear a beast howling outside. She had never seen it, only knew it was a kind of white wolf."
  },
  AvgDialog_118955_Content_36 = {Text = "Help!"},
  AvgDialog_118955_Content_37 = {
    Text = "Murphy fled in a panic, escaping the cave. Those bright green eyes remained in the cave, and did not follow her footsteps."
  },
  AvgDialog_118955_Content_38 = {
    Text = "In such a dire situation, I saw a line of footprints."
  },
  AvgDialog_118955_Content_39 = {
    Text = "These are... human footprints!"
  },
  AvgDialog_118955_Content_4 = {
    Text = "But nothing comes out when you cough; all that's left in your lungs are twitching nerves and the phantom pain of drowning."
  },
  AvgDialog_118955_Content_40 = {
    Text = "As long as there are people, there is hope. I followed without hesitation."
  },
  AvgDialog_118955_Content_41 = {Text = "..."},
  AvgDialog_118955_Content_42 = {
    Text = "Soon after, the footprints turned into two lines."
  },
  AvgDialog_118955_Content_43 = {
    Text = "Then three."
  },
  AvgDialog_118955_Content_44 = {
    Text = "The footprints were increasing, but the owner of the footprints remained elusive."
  },
  AvgDialog_118955_Content_45 = {
    Text = "Exhausted, I finally fainted."
  },
  AvgDialog_118955_Content_46 = {
    Text = "Later I learned that due to the difference in length between the left and right feet, everyone tends to slightly drift in a certain direction when walking without being able to determine their orientation."
  },
  AvgDialog_118955_Content_47 = {
    Text = "In other words... at that time, I was walking in circles."
  },
  AvgDialog_118955_Content_48 = {
    Text = "The footprints I thought were my hope came from my past self, leading to an endless cycle."
  },
  AvgDialog_118955_Content_49 = {
    Text = "Because of a slight, almost insignificant deviation... my life has been bound by a strange loop."
  },
  AvgDialog_118955_Content_5 = {
    Text = "Why... isn't this supposed to be the last cycle?"
  },
  AvgDialog_118955_Content_50 = {
    Text = "The center of that loop is called Fate."
  },
  AvgDialog_118955_Content_51 = {
    Text = "This is the loop I have built that traps myself."
  },
  AvgDialog_118955_Content_52 = {
    Text = "So, you mean..."
  },
  AvgDialog_118955_Content_53 = {
    Text = "Time has stood still since Goliath first prepared to rebel."
  },
  AvgDialog_118955_Content_54 = {
    Text = [[
Everyone has sunk into a dream, beginning a repetitive cycle.
The cycle starts with the birth of the Divine Fetus and ends with the sinking of the cruise ship.]]
  },
  AvgDialog_118955_Content_55 = {
    Text = "If Goliath hadn't started a rebellion, everything could've remained peaceful as before."
  },
  AvgDialog_118955_Content_56 = {
    Text = "But I once saw Goliath in Necrovia..."
  },
  AvgDialog_118955_Content_57 = {
    Text = "To maintain the Dream Domain, I send a group of people out periodically to collect energy for the ivory sculpture."
  },
  AvgDialog_118955_Content_58 = {
    Text = "Once they return, they will forget everything and fall into my dream again."
  },
  AvgDialog_118955_Content_59 = {
    Text = "Unfortunately, ever since you interfered with our energy absorption from Necrovia, the Dream Domain has become increasingly unstable."
  },
  AvgDialog_118955_Content_6 = {
    Text = "You look around; the open deck is empty, with no purple spiders and no Seafarers surrounding you."
  },
  AvgDialog_118955_Content_60 = {
    Text = "Why do you want me to see you?"
  },
  AvgDialog_118955_Content_61 = {
    Text = "I originally summoned you here, hoping to kill you..."
  },
  AvgDialog_118955_Content_62 = {
    Text = "But before I could do that, my Silver Core seemed to resonate with your Silver Key, connecting me to your dream, your memory."
  },
  AvgDialog_118955_Content_63 = {
    Text = "I saw another possibility in that dream... another version of myself."
  },
  AvgDialog_118955_Content_64 = {
    Text = "I saw her competing with her classmates in sculpture class;"
  },
  AvgDialog_118955_Content_65 = {
    Text = "I saw her fighting a stray cat under the fountain."
  },
  AvgDialog_118955_Content_66 = {
    Text = "I saw her being coaxed by her friends to wear a little devil costume, carrying a pumpkin lantern and going door to door handing out candy..."
  },
  AvgDialog_118955_Content_67 = {
    Text = "In a world where the Divine Fetus was never born, she seemed truly... happy."
  },
  AvgDialog_118955_Content_68 = {
    Text = "How enviable. How beautiful."
  },
  AvgDialog_118955_Content_69 = {
    Text = "A life I wish I had."
  },
  AvgDialog_118955_Content_7 = {
    Text = "You run around, searching."
  },
  AvgDialog_118955_Content_70 = {
    Text = "<Yellow:%player%>, it wasn't until I met you that I realized there is such a simple and joyful way of living in this world..."
  },
  AvgDialog_118955_Content_71 = {
    Text = "No need for Divine Mother's vain crown, no need for the honor of being revered by the masses, no need to face the annoying faces of the followers day after day..."
  },
  AvgDialog_118955_Content_72 = {
    Text = "Responsibility? Legacy? Why do so many people have to sacrifice their lives for a pile of rotten flesh?"
  },
  AvgDialog_118955_Content_73 = {
    Text = "You remain silent; you can only stay silent."
  },
  AvgDialog_118955_Content_74 = {
    Text = "Murphy is denying her past self."
  },
  AvgDialog_118955_Content_75 = {
    Text = "I have one final question to ask you."
  },
  AvgDialog_118955_Content_76 = {
    Text = "In your world, did you also make cupcakes with her like that?"
  },
  AvgDialog_118955_Content_77 = {
    Text = [[
Murphy... You'll find many people willing to help you there. It won't be just me. 
They'll join you in any reckless or whimsical thing you desire to do.]]
  },
  AvgDialog_118955_Content_78 = {
    Text = "Because you love the world and everyone in it."
  },
  AvgDialog_118955_Content_79 = {
    Text = "You tore your own heart open, and all the world bore witness..."
  },
  AvgDialog_118955_Content_8 = {
    Text = "Asleep, asleep, everyone is asleep."
  },
  AvgDialog_118955_Content_80 = {
    Text = "....to the love that pulsed within."
  },
  AvgDialog_118955_Content_81 = {
    Text = "Murphy smiles, her smile as radiant as you remembered."
  },
  AvgDialog_118955_Content_82 = {
    Text = "You know, this ship is merely a dream."
  },
  AvgDialog_118955_Content_83 = {
    Text = [[
I once thought it was a beautiful dream... 
I am the Divine Mother, and that writhing mass of flesh is the so-called god I gave birth to.]]
  },
  AvgDialog_118955_Content_84 = {
    Text = "Day and night, I live in fear, constantly anxious and tormented."
  },
  AvgDialog_118955_Content_85 = {
    Text = "Turns out it is not a sweet dream, but a nightmare of panic that I wasn't even aware of."
  },
  AvgDialog_118955_Content_86 = {
    Text = "So now, it's time to tear down the curtain of lies and let the dream end."
  },
  AvgDialog_118955_Content_9 = {
    Text = "William lies on the deck, his uniform a tattered mess, as if it had been battered repeatedly by storms and scorching sun, with grease and salt crusted into a mottled map."
  },
  AvgDialog_118956_Content_1 = {
    Text = "You retreat while fighting him, from the engine room to the corridor, and finally onto the deck, until only the ship's railing separates you from the infinite ocean behind you."
  },
  AvgDialog_118956_Content_10 = {
    Text = "The giant, driven back by your impact, slides quickly toward the cabin wall."
  },
  AvgDialog_118956_Content_11 = {
    Text = "In the blink of an eye, he plunges his massive blade straight into the deck, barely stabilizing his stance."
  },
  AvgDialog_118956_Content_12 = {
    Text = "You've improved quite a bit since the last time we met, kid."
  },
  AvgDialog_118956_Content_13 = {
    Text = "No, that's not how it is."
  },
  AvgDialog_118956_Content_14 = {
    Text = "It is not that you have grown stronger; rather, Goliath has become weaker."
  },
  AvgDialog_118956_Content_15 = {
    Text = "Even with Faros assisting him, Goliath's strength is far inferior to what it was during your last encounter."
  },
  AvgDialog_118956_Content_16 = {
    Text = "Each slash is light and airy, completely unlike the work of a giant with brute strength."
  },
  AvgDialog_118956_Content_17 = {
    Text = "Goliath, the inhuman strength within you... is fading. I noticed right after the fight started."
  },
  AvgDialog_118956_Content_18 = {
    Text = "Ha. Even if I were ten times weaker, you little rascal wouldn't be able to match me."
  },
  AvgDialog_118956_Content_19 = {
    Text = "Is this related to Faros being here?"
  },
  AvgDialog_118956_Content_2 = {
    Text = "Wow, such perseverance... You actually fought me all the way here."
  },
  AvgDialog_118956_Content_20 = {
    Text = "Furthermore, is it related to the visions on this ship?"
  },
  AvgDialog_118956_Content_21 = {
    Text = "Are you eager to carry out these so-called arrangements because your own power is weakening?"
  },
  AvgDialog_118956_Content_22 = {
    Text = "There are things you shouldn't know. Don't expect to get a word out of me no matter how you ask."
  },
  AvgDialog_118956_Content_23 = {
    Text = "If our goals are aligned, you may not actually need to remove me."
  },
  AvgDialog_118956_Content_24 = {
    Text = "Let's each take a step back. I won't interfere with your intention of betrayal, and you shouldn't make things difficult for me either."
  },
  AvgDialog_118956_Content_25 = {
    Text = "Goliath has yet to respond when two shadowy serpents dart toward you like lightning!"
  },
  AvgDialog_118956_Content_27 = {
    Text = "You suddenly withdraw, and the shadowy impact instantly blasts two terrifying, smoke-emitting holes into the deck."
  },
  AvgDialog_118956_Content_28 = {
    Text = "Two ungrateful traitors. This is no place for you to collude."
  },
  AvgDialog_118956_Content_29 = {
    Text = "As for you, {Male=Mr.,Female=Miss} outsider... when you fled, it seems you forgot something crucial."
  },
  AvgDialog_118956_Content_3 = {
    Text = "However, you have no way out now."
  },
  AvgDialog_118956_Content_30 = {
    Text = [[
The ivory sculpture hovers in Miryam's hand. 
She prays devoutly, blasphemous words seeping from her mouth like maggots.]]
  },
  AvgDialog_118956_Content_31 = {
    Text = "<Change>Your bodies and souls should have long belonged to the darkness of the abyss."
  },
  AvgDialog_118956_Content_32 = {
    Text = "Wait, Miryam, don't—"
  },
  AvgDialog_118956_Content_33 = {
    Text = "I am sorry, Divine Mother, but I must punish those who desecrate in your stead."
  },
  AvgDialog_118956_Content_34 = {
    Text = "The ivory sculpture emits a silent screech, countless strands of silver threads spreading out, parasitically entwining the hearts of Lemuria's followers like eerie living beings."
  },
  AvgDialog_118956_Content_35 = {
    Text = "What... crazy bitch, what are you doing?!"
  },
  AvgDialog_118956_Content_36 = {
    Text = "What am I doing? Naturally, I am bestowing upon you the Lord's mercy, His compassion, and His supreme power."
  },
  AvgDialog_118956_Content_37 = {
    Text = "The entangled threads tighten violently—"
  },
  AvgDialog_118956_Content_38 = {
    Text = "Lord Goliath... I can't breathe..."
  },
  AvgDialog_118956_Content_39 = {
    Text = "<Shake:Ah... it's there... I feel His pulse... I have touched... His Soul...>"
  },
  AvgDialog_118956_Content_4 = {
    Text = "Taking a deep breath, you steady your mind and face Goliath as he swings his massive blade again."
  },
  AvgDialog_118956_Content_40 = {Text = "SPLURGE."},
  AvgDialog_118956_Content_41 = {
    Text = "Hearts burst in quick succession. Blood erupts, blooming in crimson waves across the deck."
  },
  AvgDialog_118956_Content_42 = {
    Text = "No amount of time can change the folly of you unbelievers."
  },
  AvgDialog_118956_Content_43 = {
    Text = "<Shake:Your blood and spirit shall forge the staircase to the Divine Realm!>"
  },
  AvgDialog_118956_Content_44 = {
    Text = "<Shake:Stop her... <Big:Help me stop her!>>"
  },
  AvgDialog_118956_Content_6 = {
    Text = "The dead end you see was already the battlefield I chose for you."
  },
  AvgDialog_118956_Content_7 = {
    Text = "You have been wasting your strength all this time, and now, it is time for my counterattack."
  },
  AvgDialog_118956_Content_8 = {
    Text = "Silver light bursts forth suddenly, crashing down towards Goliath with overwhelming force. Goliath immediately raises his blade, but it is too late."
  },
  AvgDialog_118957_Content_1 = {Text = "Epilogue"},
  AvgDialog_118957_Content_10 = {
    Text = "What a long, long dream it was."
  },
  AvgDialog_118957_Content_11 = {
    Text = "Death, betrayal, sinking; the more I want to hold on to something, the more it inevitably slips through my fingers."
  },
  AvgDialog_118957_Content_12 = {
    Text = "Perhaps this is fate. No need to hold on to something you can't keep."
  },
  AvgDialog_118957_Content_13 = {
    Text = "Let go sooner, and you might encounter more like-minded companions."
  },
  AvgDialog_118957_Content_14 = {
    Text = "For example... Mythag?"
  },
  AvgDialog_118957_Content_15 = {
    Text = "The people of Mythag seem to be very good at being inclusive... or smoothing out everyone's quirks."
  },
  AvgDialog_118957_Content_16 = {
    Text = "I remember one year, the Murphy in our world insisted on trying every flavor of candy, and as a result, she ended up with a toothache."
  },
  AvgDialog_118957_Content_17 = {
    Text = "In the end, Sylvia had Jenkin steal all of her stock of sweets."
  },
  AvgDialog_118957_Content_18 = {
    Text = "Pfft. And then what?"
  },
  AvgDialog_118957_Content_19 = {
    Text = "Then she began to make a big fuss about catching thieves, completely forgetting about the candy."
  },
  AvgDialog_118957_Content_2 = {
    Text = "The Paradise has docked, and next..."
  },
  AvgDialog_118957_Content_20 = {
    Text = "And another time, she..."
  },
  AvgDialog_118957_Content_21 = {
    Text = "Alright, how much more do you want me to envy her life?"
  },
  AvgDialog_118957_Content_22 = {
    Text = "When we return to Mythag, it will be your life, too."
  },
  AvgDialog_118957_Content_23 = {
    Text = "Then hopefully we will meet there one day."
  },
  AvgDialog_118957_Content_24 = {
    Text = "Murphy stretches out her hands towards the distant sky, as if trying to touch the sun high above."
  },
  AvgDialog_118957_Content_25 = {
    Text = "The black hole in the sky rests between her fingers, pulsating."
  },
  AvgDialog_118957_Content_26 = {
    Text = "And there's one more thing I must tell you."
  },
  AvgDialog_118957_Content_27 = {
    Text = "Murphy stares at you intently."
  },
  AvgDialog_118957_Content_28 = {
    Text = "This world is already beyond salvation, shrouded in a despair deeper than the cycles I have experienced."
  },
  AvgDialog_118957_Content_29 = {
    Text = "If possible, I might be able to send you back."
  },
  AvgDialog_118957_Content_3 = {
    Text = "They already know everything about the gods of this world and will soon make their own choice."
  },
  AvgDialog_118957_Content_30 = {
    Text = "Send me... back?"
  },
  AvgDialog_118957_Content_31 = {
    Text = "Do you know the way to traverse between two worlds?"
  },
  AvgDialog_118957_Content_32 = {
    Text = "Not exactly, but once you grasp this world's essence, you naturally understand the dimensional nexus."
  },
  AvgDialog_118957_Content_33 = {
    Text = "This ship is a dream, but when the curtain of lies is lifted..."
  },
  AvgDialog_118957_Content_34 = {
    Text = "You will realize this whole world is also Someone's dream, only that dream is bigger, more illusory, and more distant..."
  },
  AvgDialog_118957_Content_35 = {
    Text = "Even the sun, moon, and stars originate from His illusion; only the beings entangled with His spirit can @3..."
  },
  AvgDialog_118957_Content_36 = {
    Text = "The sun, moon, and stars..."
  },
  AvgDialog_118957_Content_37 = {
    Text = "The black veil trembles, extending into a winding path of fabric leading to the sky."
  },
  AvgDialog_118957_Content_38 = {
    Text = "Go, go back, return to the world that belongs to you! There's no need to cling to this world that is already dead."
  },
  AvgDialog_118957_Content_39 = {
    Text = "What about you, Murphy?"
  },
  AvgDialog_118957_Content_4 = {
    Text = "In my opinion, Miryam and Faros should set sail again to search for the whereabouts of Lemuria."
  },
  AvgDialog_118957_Content_40 = {
    Text = "You resist the urge to immediately jump on the silk path, turning back to question the silent Murphy."
  },
  AvgDialog_118957_Content_41 = {
    Text = "Who knows? This is a world that has already been destroyed."
  },
  AvgDialog_118957_Content_42 = {
    Text = "Take it. Perhaps one day, you may sense my Silver Core in that world."
  },
  AvgDialog_118957_Content_43 = {
    Text = "A gem formed from a droplet of blood falls into your palm, originating from the grotesque wound that pierces her chest."
  },
  AvgDialog_118957_Content_44 = {
    Text = "The \"me\" you summon could be from any point in my life."
  },
  AvgDialog_118957_Content_45 = {
    Text = "But when you call for me, remember how I look now..."
  },
  AvgDialog_118957_Content_46 = {
    Text = "\"His\" birth was an illusion from the start. All dreams are faux... A false genesis."
  },
  AvgDialog_118957_Content_47 = {
    Text = "You will call me... <Yellow:Murphy the Fauxborn>!"
  },
  AvgDialog_118957_Content_48 = {
    Text = "You stroll along the path of dark fabric, and countless thoughts rush through your mind."
  },
  AvgDialog_118957_Content_49 = {
    Text = "The journey to confront Dissolution, two worlds entwined by a black nightmare, many similar or identical faces overlapping each other..."
  },
  AvgDialog_118957_Content_5 = {
    Text = "Goliath and Caecus will most likely depart; even in a world so desolate, they should have a quest of their own to embark on."
  },
  AvgDialog_118957_Content_50 = {
    Text = "Two Doll..."
  },
  AvgDialog_118957_Content_51 = {
    Text = "Two Clementine..."
  },
  AvgDialog_118957_Content_52 = {
    Text = "Two Murphy..."
  },
  AvgDialog_118957_Content_53 = {
    Text = "And at last, you remember Ramona's smiling face."
  },
  AvgDialog_118957_Content_54 = {
    Text = "Can I... go back now?"
  },
  AvgDialog_118957_Content_55 = {
    Text = "In a dreamlike state, you stand just an arm's length away from the black sun, yet you feel no warmth at all."
  },
  AvgDialog_118957_Content_56 = {
    Text = "That infinite deep black devours all light, eagerly waiting to swallow you completely."
  },
  AvgDialog_118957_Content_57 = {
    Text = "Ramona... are you there? Are you waiting for me behind this?"
  },
  AvgDialog_118957_Content_58 = {
    Text = "You close your eyes and gently touch the black passage."
  },
  AvgDialog_118957_Content_59 = {
    Text = "If you can, please... hold my hand."
  },
  AvgDialog_118957_Content_6 = {
    Text = "As for \"this\" Murphy..."
  },
  AvgDialog_118957_Content_60 = {
    Text = "From under your feet, from countless deep dreams."
  },
  AvgDialog_118957_Content_61 = {
    Text = "Starting from the black sun, the black veils gradually disintegrate layer by layer."
  },
  AvgDialog_118957_Content_62 = {
    Text = "You fall from the sky...."
  },
  AvgDialog_118957_Content_63 = {
    Text = "Falling into the vortex called \"Fate.\""
  },
  AvgDialog_118957_Content_64 = {
    Text = "I glimpsed that girl's experience in a deep dream."
  },
  AvgDialog_118957_Content_65 = {
    Text = "How unfortunate. I sent her away from Lemuria, entrusting the ivory sculpture to her in a dream, not for such an ending."
  },
  AvgDialog_118957_Content_66 = {
    Text = "Shouldn't you thank me for my involvement in this?"
  },
  AvgDialog_118957_Content_67 = {
    Text = "The Light of Hope in this world has long been annihilated; you know that, right?"
  },
  AvgDialog_118957_Content_68 = {
    Text = "The woman with her hand on the spinning wheel remains silent, simply allowing the thread in her hand to extend beneath the heavens, among all things."
  },
  AvgDialog_118957_Content_69 = {
    Text = "As long as there is still one seed."
  },
  AvgDialog_118957_Content_7 = {
    Text = "I think she has something to say to you."
  },
  AvgDialog_118957_Content_70 = {
    Text = "No matter how long the silence lasts, no matter which soil it is in, one day it will sprout."
  },
  AvgDialog_118957_Content_71 = {
    Text = "As for me..."
  },
  AvgDialog_118957_Content_72 = {
    Text = "The woman lowers her gaze."
  },
  AvgDialog_118957_Content_73 = {
    Text = "I am not a sower, not a caregiver, and not a reaper."
  },
  AvgDialog_118957_Content_74 = {
    Text = "I am merely pulling the threads, following the preordained order as the Weaver of Fate."
  },
  AvgDialog_118957_Content_75 = {
    Text = "I pull the thread of the spindle to draw out the most suitable soil for it."
  },
  AvgDialog_118957_Content_76 = {
    Text = "I shall wait... quietly."
  },
  AvgDialog_118957_Content_8 = {
    Text = "You're here?"
  },
  AvgDialog_118957_Content_9 = {Text = "Yes."},
  AvgDialog_118958_Content_1 = {Text = "Dream Core"},
  AvgDialog_118958_Content_10 = {
    Text = "I once allied with Goliath, but a barbarian who only understands war and violence clearly does not know how to uphold a contract, let alone lead the way to Lemuria."
  },
  AvgDialog_118958_Content_11 = {
    Text = "How about it? Work with me, and I will reveal the identity of the Domain Master to you."
  },
  AvgDialog_118958_Content_12 = {
    Text = "Her heart is in her throat."
  },
  AvgDialog_118958_Content_13 = {
    Text = "Allow me to refuse."
  },
  AvgDialog_118958_Content_14 = {
    Text = "I can't hastily agree to take someone's life without knowing who they are."
  },
  AvgDialog_118958_Content_15 = {
    Text = "Moreover, since you have made such a request, it is clear that the Domain Master is not among you, Goliath, and Caecus."
  },
  AvgDialog_118958_Content_16 = {
    Text = "And you have already revealed that the power of dream manipulation is related to that ivory sculpture."
  },
  AvgDialog_118958_Content_17 = {
    Text = "Then the only remaining suspect... would be her."
  },
  AvgDialog_118958_Content_18 = {
    Text = "Your taste in choosing a viewing spot is indeed commendable."
  },
  AvgDialog_118958_Content_19 = {
    Text = "You tighten the rope, letting the sails on the mast shield you and William from view."
  },
  AvgDialog_118958_Content_2 = {
    Text = "Tap-tap-tap, tap-tap-tap."
  },
  AvgDialog_118958_Content_20 = {
    Text = "I noticed during the last ceremony that, compared to the Sona-Nyl, the Paradise retains a relatively ancient mast structure."
  },
  AvgDialog_118958_Content_21 = {
    Text = "It's equivalent to a lookout tower that offers a view of the situation at the pilotage ceremony site."
  },
  AvgDialog_118958_Content_22 = {
    Text = "When the Ritual of Navigation begins, Miryam will hand the ivory sculpture to Murphy, which is also the only occasion when we can access it."
  },
  AvgDialog_118958_Content_23 = {
    Text = "Take the sculpture and parse it; perhaps we can grasp the method to undo the Domain."
  },
  AvgDialog_118958_Content_24 = {
    Text = "Shh, they're coming."
  },
  AvgDialog_118958_Content_25 = {
    Text = "William taps your shoulder, signaling you to turn around."
  },
  AvgDialog_118958_Content_26 = {
    Text = "Keep a close eye on the position of the ivory sculpture... it is our lifeline."
  },
  AvgDialog_118958_Content_27 = {
    Text = "The Ritual of Navigation continues, exactly as you remembered."
  },
  AvgDialog_118958_Content_28 = {
    Text = "Esteemed Divine Mother, please guide the bloodline of the divine king, lead the lost seafarers, and show us the course to Lemuria."
  },
  AvgDialog_118958_Content_29 = {
    Text = "Murphy bites her lip and takes the glowing dagger from Miryam's hand."
  },
  AvgDialog_118958_Content_3 = {
    Text = "A maiden is running in the corridor."
  },
  AvgDialog_118958_Content_30 = {
    Text = "She raises the knife high—then doesn't stab down for a long time."
  },
  AvgDialog_118958_Content_31 = {
    Text = "Divine Mother, haven't you already made your decision? Lemuria is still at the bottom of the Abyss, awaiting your arrival."
  },
  AvgDialog_118958_Content_32 = {
    Text = "... I'll do that right away..."
  },
  AvgDialog_118958_Content_33 = {
    Text = "The latter half of the sentence is swallowed."
  },
  AvgDialog_118958_Content_34 = {
    Text = "She lifts the blood-soaked ivory sculpture, allowing the deformed monster to drain her essence."
  },
  AvgDialog_118958_Content_35 = {
    Text = "The river of blood spreads along the ship's railing, flowing to the left."
  },
  AvgDialog_118958_Content_36 = {
    Text = "Turn! Helmsman of the Seafarers, heed the divine oracle, hard left!"
  },
  AvgDialog_118958_Content_37 = {
    Text = "A blade slices through the air, as if responding to her words."
  },
  AvgDialog_118958_Content_38 = {
    Text = "I don't think it's necessary."
  },
  AvgDialog_118958_Content_39 = {
    Text = "A sharp harpoon shoots out from the pitch-black night like the fangs of a giant shark, piercing precisely through the helmsman's throat."
  },
  AvgDialog_118958_Content_4 = {
    Text = "As she passes by the captain's cabin, a calm voice flows into her ears."
  },
  AvgDialog_118958_Content_40 = {
    Text = "A heavy giant blade scrapes sparks across the deck as the giant emerges from the depths of the night, crushing the helmsman's skull and revealing a cruel smile to the witch before him."
  },
  AvgDialog_118958_Content_41 = {
    Text = "Behind him, a barbarian clad in a blue-gray oilskin raincoat holds a blade, eagerly waiting for the command to kill."
  },
  AvgDialog_118958_Content_42 = {
    Text = "Goliath... you still refuse to give up, I see."
  },
  AvgDialog_118958_Content_43 = {
    Text = "You rallied these sailors, orchestrated this chaos... thinking you could shatter the peace of our Paradise..."
  },
  AvgDialog_118958_Content_44 = {
    Text = "Unfortunately, I won't be a part of your peace anymore. This time, next time, and every time after... Philistines are done with kneeling."
  },
  AvgDialog_118958_Content_45 = {
    Text = "Hear me, Philistines!"
  },
  AvgDialog_118958_Content_46 = {
    Text = "Answering his sinister call, the barbarian figures clad in oilskin raincoats emerge densely from the darkness behind Goliath, wielding sharp blades."
  },
  AvgDialog_118958_Content_47 = {
    Text = "Their deep growls tremble with elation. They thirstily await the moment to reenact their glory, waiting for the command to slaughter everything."
  },
  AvgDialog_118958_Content_48 = {
    Text = "Kill them all! Leave none alive!"
  },
  AvgDialog_118958_Content_49 = {
    Text = "Coarse war songs tear through the night sky over the sea, as the savage tribes swing their ropes, smashing into the crowd on the deck with blinding speed."
  },
  AvgDialog_118958_Content_5 = {
    Text = "I know who the Domain Master is, and I can lead you to break through the boundaries of the Domain and return to the real world."
  },
  AvgDialog_118958_Content_50 = {
    Text = "The Philistines, who have long survived by coastal raiding, swarm towards their prey like sharks sensing blood, thirstily and ferociously biting into the enemies' bodies with their curved blades like sharp teeth."
  },
  AvgDialog_118958_Content_51 = {
    Text = "My Lord, please hear the calls of Your believers... Bestow grace upon Your people..."
  },
  AvgDialog_118958_Content_52 = {
    Text = "Miryam opens her arms, and the dark light gradually spreads."
  },
  AvgDialog_118958_Content_53 = {
    Text = "The Seafarers in strange black robes make no sound, like a group of devout black phantoms, silently basking in the profound divine grace, silently driving their daggers into the enemies' chests."
  },
  AvgDialog_118958_Content_54 = {
    Text = "Bluish gray and dark violet. Two distinctly different factions are engaged in a deadly struggle in this moving hell."
  },
  AvgDialog_118958_Content_55 = {
    Text = "Slaughter, my kin... Reenact the glory of the Philistines!"
  },
  AvgDialog_118958_Content_56 = {
    Text = "His massive blade effortlessly severs the head of a Seafarer blocking his path. The gushing, salty blood stains much of Goliath's face crimson."
  },
  AvgDialog_118958_Content_57 = {
    Text = "He licks the blood from his face, wielding the giant blade in his hand under the illumination of lightning, slaying every Seafarer in his way."
  },
  AvgDialog_118958_Content_58 = {
    Text = "The warm blood gushing out is instantly diluted by the downpour, mingling with the seawater, forming slick crimson rills on the violently shaking deck."
  },
  AvgDialog_118958_Content_59 = {
    Text = "<Shake:My Lord, I have heard your decree. Your believers shall return to the Divine Realm with you...>"
  },
  AvgDialog_118958_Content_6 = {
    Text = "She pretends to be calm and moves quietly closer."
  },
  AvgDialog_118958_Content_60 = {
    Text = "Ritual, storm, slaughter..."
  },
  AvgDialog_118958_Content_61 = {
    Text = "In the heart of this chaos, beneath the ominous ivory sculpture at the bow of the ship, Miryam stands, devoutly whispering in the storm."
  },
  AvgDialog_118958_Content_62 = {
    Text = "She ignores the slaughter around her. A dagger whizzes past her ear, and the huge waves drench her completely, yet she is utterly unaware."
  },
  AvgDialog_118958_Content_63 = {
    Text = "May your oracle guide us, may your body envelop us."
  },
  AvgDialog_118958_Content_64 = {
    Text = "Miryam... Give up! We can't reach Lemuria!"
  },
  AvgDialog_118958_Content_65 = {
    Text = "No... He promised me, and you have heard His Divine Oracle, haven't you?"
  },
  AvgDialog_118958_Content_66 = {
    Text = "Miryam gazes devoutly at the horizon."
  },
  AvgDialog_118958_Content_67 = {
    Text = "The storm is Your breath, the thunder is Your battle drum!"
  },
  AvgDialog_118958_Content_68 = {
    Text = "Please guide this lost lamb toward the course to Your Kingdom!"
  },
  AvgDialog_118958_Content_69 = {
    Text = "A pale bolt of lightning rends the heavens, instantly illuminating her fervent and devout eyes."
  },
  AvgDialog_118958_Content_7 = {
    Text = "But my assistance comes with conditions."
  },
  AvgDialog_118958_Content_70 = {
    Text = "The girl in black gauze huddles silently in a corner of the bow, her hollow gaze hopelessly fixed on the battlefield of slaughter, like a rag doll discarded in a heap of trash."
  },
  AvgDialog_118958_Content_71 = {
    Text = "Let's go down!"
  },
  AvgDialog_118958_Content_72 = {
    Text = "I'll take the ivory statue!"
  },
  AvgDialog_118958_Content_73 = {
    Text = "I'm getting Murphy!"
  },
  AvgDialog_118958_Content_8 = {
    Text = "What's your condition...?"
  },
  AvgDialog_118958_Content_9 = {
    Text = "Kill the Domain Master, seize the ivory sculpture, and transfer the ownership of this Domain to me."
  },
  AvgDialog_118959_Content_1 = {
    Text = "I killed myself and picked up the crown. I got everything I desired, except for freedom."
  },
  AvgDialog_118959_Content_10 = {
    Text = "I will not abandon you, because you are different."
  },
  AvgDialog_118959_Content_11 = {
    Text = "What is so different between me and them? We are merely sacrifices in your eyes, just food for this rotten meat."
  },
  AvgDialog_118959_Content_12 = {
    Text = "Murphy holds up the dirty clump in her hands, blood dripping down in a steady stream."
  },
  AvgDialog_118959_Content_13 = {
    Text = "No, you ARE different."
  },
  AvgDialog_118959_Content_14 = {Text = "Because..."},
  AvgDialog_118959_Content_15 = {
    Text = "Because we have come together all the way."
  },
  AvgDialog_118959_Content_16 = {
    Text = "I remember the day we implanted the Divine Fetus in your chest; you said you wanted some churros."
  },
  AvgDialog_118959_Content_17 = {
    Text = "Then you suddenly decided that it was too delicious to enjoy alone, so you shared half with me reluctantly."
  },
  AvgDialog_118959_Content_18 = {
    Text = "Later, the Divine Fetus began to grow, and you had a high fever that wouldn't subside. We tried every possible way to bring down the temperature, but in the end, we had no choice but to transport you to the ice cellar in Antarctica."
  },
  AvgDialog_118959_Content_19 = {
    Text = "Caused us a lot of trouble."
  },
  AvgDialog_118959_Content_2 = {
    Text = "But I, who gave birth to the Divine Fetus, was unable to receive His blessing. I failed to guide the path to Lemuria..."
  },
  AvgDialog_118959_Content_20 = {
    Text = "Even in such a perilous environment, you still upheld your duties as the Divine Mother."
  },
  AvgDialog_118959_Content_21 = {
    Text = "Most of the priests endured the bitter cold, accompanying, waiting, and praying at the altar in Antarctica."
  },
  AvgDialog_118959_Content_22 = {
    Text = "And you have lived up to everyone's expectations, becoming the first vessel to give birth to the Divine Fetus."
  },
  AvgDialog_118959_Content_23 = {
    Text = "We have arrived at that moment together."
  },
  AvgDialog_118959_Content_24 = {
    Text = "And we will sail together toward the Eternal Divine Realm."
  },
  AvgDialog_118959_Content_25 = {
    Text = "Slowly and resolutely, Miryam walks in front of Murphy, bending down."
  },
  AvgDialog_118959_Content_26 = {
    Text = "You are the esteemed Divine Mother, and I am willing to kneel at your feet for eternity, offering you my lifelong devotion."
  },
  AvgDialog_118959_Content_27 = {
    Text = "I am willing to forever look up to you with the reverence reserved for my Lord."
  },
  AvgDialog_118959_Content_28 = {
    Text = "Murphy stares blankly down at Miryam."
  },
  AvgDialog_118959_Content_29 = {
    Text = "Miryam kneels, taking Murphy's hand and pressing a devout kiss to it."
  },
  AvgDialog_118959_Content_3 = {
    Text = "So you created this never-ending dream..."
  },
  AvgDialog_118959_Content_30 = {
    Text = "Come back to my side, will you? Our Divine Mother?"
  },
  AvgDialog_118959_Content_31 = {
    Text = "Murphy lowers her head. The winds come to a halt, and silence reigns the small cosmic crevice."
  },
  AvgDialog_118959_Content_32 = {
    Text = [[
Your stories were never about me. They were about the Divine Fetus. 
Your words were never for me. They were for the Divine Mother.]]
  },
  AvgDialog_118959_Content_33 = {
    Text = "You still don't understand... and you never will..."
  },
  AvgDialog_118959_Content_34 = {
    Text = "A few murmurs slip through her trembling lips."
  },
  AvgDialog_118959_Content_35 = {
    Text = "You who only know about prayers, rituals, the Divine Realm, Lemuria, and the rebirth of your god..."
  },
  AvgDialog_118959_Content_36 = {
    Text = "You will never, ever understand."
  },
  AvgDialog_118959_Content_37 = {
    Text = "Everything I have built—this final destination I fought so hard to reach, this illusion I struggled so hard to maintain... I did it all for one reason."
  },
  AvgDialog_118959_Content_38 = {
    Text = "So you would finally acknowledge me truly. So I could... finally call you..."
  },
  AvgDialog_118959_Content_39 = {Text = "Mother..."},
  AvgDialog_118959_Content_4 = {
    Text = "If I didn't do this, she would definitely rip out my heart..."
  },
  AvgDialog_118959_Content_40 = {
    Text = "The raging winds drown out her already indistinct whispers."
  },
  AvgDialog_118959_Content_41 = {
    Text = "Ha... What a shame."
  },
  AvgDialog_118959_Content_42 = {
    Text = "Murphy bites away her tears."
  },
  AvgDialog_118959_Content_43 = {
    Text = "My expectations were pointless. The balance I created is a lie, an eternal illusion."
  },
  AvgDialog_118959_Content_44 = {
    Text = "You will never be my mother."
  },
  AvgDialog_118959_Content_45 = {
    Text = "The Murphy you knew is dead. She died the day your god was born."
  },
  AvgDialog_118959_Content_46 = {
    Text = "What stands before you now is an Awakener, forged from her ashes and a spirit of Silver."
  },
  AvgDialog_118959_Content_47 = {
    Text = "And the person who awakened me from my own corpse... No, can that even be called a person?"
  },
  AvgDialog_118959_Content_48 = {
    Text = "My <Blue:Linker> is here, right in front of you."
  },
  AvgDialog_118959_Content_49 = {
    Text = "She gently lifts the swaddling cloth. On her face, you catch an expression of unusual tenderness—so profound it's almost terrifying."
  },
  AvgDialog_118959_Content_5 = {
    Text = "...and sacrifice me to her revered king."
  },
  AvgDialog_118959_Content_50 = {
    Text = "I brought it into this world... and it brought me back again..."
  },
  AvgDialog_118959_Content_51 = {
    Text = "A fate of deviation, eternally entangled. A distorted cycle that never ends."
  },
  AvgDialog_118959_Content_52 = {
    Text = "The Father births a Daughter. The Daughter then conceives Her Father. And the Father awakens His Daughter once more..."
  },
  AvgDialog_118959_Content_53 = {
    Text = "There is no one to sever this twisted bond. Nothing can break the eternal ouroboros of our bloodline."
  },
  AvgDialog_118959_Content_54 = {
    Text = "Do you think you are the first person to get caught in this time loop?"
  },
  AvgDialog_118959_Content_55 = {
    Text = "I have lived through its horrors more times than I can count. Each loop ended in an unspeakable nightmare."
  },
  AvgDialog_118959_Content_56 = {
    Text = "Once, Miryam stabbed me through the chest because I rejected Lemuria's call."
  },
  AvgDialog_118959_Content_57 = {
    Text = "Once, I was imprisoned by Goliath, and the ivory sculpture was taken away, leading to the sinking of the entire ship."
  },
  AvgDialog_118959_Content_58 = {
    Text = "Once, in a certain dream, a frail but determined person opened a path for my escape."
  },
  AvgDialog_118959_Content_59 = {
    Text = [[
But I have always believed those were not the true endings. 
I was waiting for the one that belongs solely to <Italic:this version of me>.]]
  },
  AvgDialog_118959_Content_6 = {
    Text = "So when Goliath said she has been waiting for me... I didn't understand."
  },
  AvgDialog_118959_Content_60 = {
    Text = "The wait is over. This is the true ending I choose."
  },
  AvgDialog_118959_Content_61 = {
    Text = "Let this ship capsize."
  },
  AvgDialog_118959_Content_62 = {
    Text = "A black curtain, like silk spilled from the heavens, descends from the lightless black sun, shrouding the ship and isolating it from the outside world."
  },
  AvgDialog_118959_Content_63 = {
    Text = "Seawater surges, burying the entire cruise ship into the dark abyss."
  },
  AvgDialog_118959_Content_64 = {
    Text = "You are, once again, trapped in the boundless darkness."
  },
  AvgDialog_118959_Content_7 = {
    Text = "<Shake:Why? Miryam, why?>"
  },
  AvgDialog_118959_Content_8 = {
    Text = "If I'm not a qualified Divine Mother, why not just discard me like you did the others?"
  },
  AvgDialog_118959_Content_9 = {
    Text = "<Red:Discard me... grant me freedom...>"
  },
  AvgDialog_118960_Content_1 = {
    Text = "Eternal Veil"
  },
  AvgDialog_118960_Content_10 = {
    Text = "No, I have always been able to manipulate everything in the dream. I can decide when the cycles end and begin, I..."
  },
  AvgDialog_118960_Content_11 = {
    Text = "Our Lord lent you the power to dream, yet you are trapped in your own obsession, squandering His goodwill."
  },
  AvgDialog_118960_Content_12 = {Text = "Lent...?"},
  AvgDialog_118960_Content_13 = {
    Text = "Do you remember where that sculpture came from?"
  },
  AvgDialog_118960_Content_14 = {
    Text = "The sculpture... His idol..."
  },
  AvgDialog_118960_Content_15 = {
    Text = "When giving birth to... the Divine Fetus..."
  },
  AvgDialog_118960_Content_16 = {
    Text = "No, I never saw this sculpture during the first week after the Divine Fetus was born."
  },
  AvgDialog_118960_Content_17 = {
    Text = "His idol... is..."
  },
  AvgDialog_118960_Content_18 = {
    Text = "No wonder I always felt like there was a missing piece to the puzzle."
  },
  AvgDialog_118960_Content_19 = {
    Text = [[
%player%, do you remember our deduction last time?
This Domain should have formed before Dissolution consumed this world, before the sun turned black.]]
  },
  AvgDialog_118960_Content_2 = {
    Text = "<Red:It should not end here.>"
  },
  AvgDialog_118960_Content_20 = {
    Text = "But the Divine Fetus's Birth, and Murphy's Sacrifice and Rebirth, clearly took place after that."
  },
  AvgDialog_118960_Content_21 = {
    Text = "In other words, Murphy at that time was just a spiritually vibrant human. She was not strong enough to construct this Dream."
  },
  AvgDialog_118960_Content_22 = {
    Text = "The one who wielded the Authority before that... It must have been..."
  },
  AvgDialog_118960_Content_23 = {
    Text = "The Godking of this world has long been born... No, rather, He has never died."
  },
  AvgDialog_118960_Content_24 = {
    Text = "You failed to awaken His consciousness because He is still in the deep slumber of a dream."
  },
  AvgDialog_118960_Content_25 = {
    Text = "He didn't want you to perish from the sacrifice, so He specially divided a thread of His strength to create a dream within a dream for you."
  },
  AvgDialog_118960_Content_26 = {
    Text = "But you desired too much. Thus, the dream continually collapses and restarts; this is the essence of the Paradise."
  },
  AvgDialog_118960_Content_27 = {
    Text = "It was born from your wish, but It is not your slave..."
  },
  AvgDialog_118960_Content_28 = {
    Text = "<Yellow:So now, It is going to carry out the mission bestowed upon It by the Creator.>"
  },
  AvgDialog_118960_Content_29 = {
    Text = "The sky begins to roll; black gauze shrouds the vision, and a massive body rises like a mountain."
  },
  AvgDialog_118960_Content_3 = {Text = "?!"},
  AvgDialog_118960_Content_30 = {
    Text = "It does not rise from the Abyss below, but rather, the sheer Will of a higher being tears through the boundary of dimensions."
  },
  AvgDialog_118960_Content_31 = {
    Text = "Beneath the suffocating dome, Its limbs silently appear: pale, slender, with joints twisted, like the tortured, deformed bones of a martyr."
  },
  AvgDialog_118960_Content_32 = {
    Text = "<Big:<Shake:...!!!>>"
  },
  AvgDialog_118960_Content_33 = {Text = "Murphy..."},
  AvgDialog_118960_Content_34 = {
    Text = "The face of that massive monster clearly resembles the maiden you know so well."
  },
  AvgDialog_118960_Content_35 = {
    Text = "<Red:<Italic:Dream... must... continue...>>"
  },
  AvgDialog_118960_Content_4 = {
    Text = "<Red:It cannot end here.>"
  },
  AvgDialog_118960_Content_5 = {
    Text = "The sky begins to stitch itself together, with black gauze obscuring the sun and gathering into a false sky."
  },
  AvgDialog_118960_Content_6 = {
    Text = "Click. Click. You hear the sound of the spinning wheel turning again."
  },
  AvgDialog_118960_Content_7 = {
    Text = "Why? Why? I've already decided to end this dream..."
  },
  AvgDialog_118960_Content_8 = {
    Text = "Because... esteemed Divine Mother, you are not the master of this dream."
  },
  AvgDialog_118960_Content_9 = {Text = "??!!"},
  AvgDialog_118961_Content_1 = {Text = "Fauxborn"},
  AvgDialog_118961_Content_10 = {
    Text = "Surprised? The only escape path from this ship has always been under my control."
  },
  AvgDialog_118961_Content_11 = {
    Text = [[
Goliath grabs Murphy over, pressing his giant blade against her throat. 
Blood rolls down her neck and pools into the eternally unhealed scar on her chest.]]
  },
  AvgDialog_118961_Content_12 = {Text = "Murphy!"},
  AvgDialog_118961_Content_13 = {
    Text = "Divine Mother!"
  },
  AvgDialog_118961_Content_14 = {
    Text = "Sorry... I couldn't stop worrying about you, so I came back..."
  },
  AvgDialog_118961_Content_15 = {
    Text = "Miryam isn't unwilling to let this girl go. It's her holding Miryam in place."
  },
  AvgDialog_118961_Content_16 = {
    Text = "She either refuses to let Miryam discover the truth, cannot bring herself to allow it, or is simply too afraid of what might happen."
  },
  AvgDialog_118961_Content_17 = {
    Text = "What is the truth you are talking about?"
  },
  AvgDialog_118961_Content_18 = {
    Text = "She doesn't even know where that Lemuria is; she has never seen the true form of God."
  },
  AvgDialog_118961_Content_19 = {
    Text = "Because she doesn't know, this ship can only drift on the sea, just drifting like this all the time."
  },
  AvgDialog_118961_Content_2 = {
    Text = "So, in this moment when your god has already been born, why do you still hold onto Murphy?"
  },
  AvgDialog_118961_Content_20 = {
    Text = "I don't know what kind of words this little girl used to charm the two of you..."
  },
  AvgDialog_118961_Content_21 = {
    Text = "High Priestess of the Seafarers. A mysterious person showing up out of nowhere. You're both being toyed with by a little girl."
  },
  AvgDialog_118961_Content_22 = {
    Text = "Remember what happened when she tried to run? Don't tell me you forgot."
  },
  AvgDialog_118961_Content_23 = {Text = "Running."},
  AvgDialog_118961_Content_24 = {
    Text = "Murphy was running."
  },
  AvgDialog_118961_Content_25 = {
    Text = "She did not know the journey's destination, nor if she could escape her Godmother's vigilance."
  },
  AvgDialog_118961_Content_26 = {
    Text = "<Shake:Huff, huff...>"
  },
  AvgDialog_118961_Content_27 = {
    Text = "No one was there to meet her ahead. Behind her, the eerie, yet somewhat comical, sound of flippers slapping the ground grew dense and insistent."
  },
  AvgDialog_118961_Content_28 = {
    Text = "The news of the Divine Maiden's disappearance had spread; the Seafarers were assembling."
  },
  AvgDialog_118961_Content_29 = {
    Text = "Curse it, these annoying bastards."
  },
  AvgDialog_118961_Content_3 = {
    Text = "You question her resolutely."
  },
  AvgDialog_118961_Content_30 = {
    Text = "Behind the flash of light, the purple-robed figure, a symbol of her failure, appeared with unnerving composure..."
  },
  AvgDialog_118961_Content_31 = {Text = "..."},
  AvgDialog_118961_Content_32 = {
    Text = "The Murphy in this world did not make it out."
  },
  AvgDialog_118961_Content_33 = {
    Text = "Because the person who had sent her to the Seafarers, and then repented and helped her flee..."
  },
  AvgDialog_118961_Content_34 = {
    Text = "Had already vanished forever in the Dissolution disaster."
  },
  AvgDialog_118961_Content_35 = {
    Text = "She did not willingly become the Divine Mother. Just as I did not willingly become your slave."
  },
  AvgDialog_118961_Content_36 = {
    Text = "We are all in pursuit of... the things we want for ourselves."
  },
  AvgDialog_118961_Content_37 = {
    Text = "<Shake:No, I don't want anything.> I... don't want anything at all."
  },
  AvgDialog_118961_Content_38 = {
    Text = "You don't want anything? No, you want TOO MANY."
  },
  AvgDialog_118961_Content_39 = {
    Text = "You want the privileged life of the Divine Mother, but you don't want to bear the responsibilities of being a guide."
  },
  AvgDialog_118961_Content_4 = {
    Text = "I'm holding onto Murphy... What do you mean?"
  },
  AvgDialog_118961_Content_40 = {
    Text = "You're afraid of being abandoned, so you treat others as puppets in your life, like toys for your tea party playhouse."
  },
  AvgDialog_118961_Content_41 = {
    Text = "Every once in a while, you erase everyone's memory on the ship and start a new cycle."
  },
  AvgDialog_118961_Content_42 = {
    Text = "Little girl, let me tell you: don't be too clever, everything in this world comes at a cost."
  },
  AvgDialog_118961_Content_43 = {
    Text = "Did you think no one would ever discover your little tricks? Did you think that with that ivory sculpture, you could do anything?"
  },
  AvgDialog_118961_Content_44 = {
    Text = "Murphy clutches the ivory sculpture in her hand."
  },
  AvgDialog_118961_Content_45 = {
    Text = "Stop being silly, you foolish child."
  },
  AvgDialog_118961_Content_46 = {
    Text = "You think I knew nothing about your actions? I was simply not ready to confront you then."
  },
  AvgDialog_118961_Content_47 = {
    Text = "In every cycle, I tried to change the method of the heist. Threatening you, threatening Miryam, blowing up the engine room..."
  },
  AvgDialog_118961_Content_48 = {
    Text = "Later, I discovered that as long as that damn ivory sculpture is around, I had no chance of fighting against you."
  },
  AvgDialog_118961_Content_49 = {
    Text = "Goliath's snicker echoes across the deck."
  },
  AvgDialog_118961_Content_5 = {
    Text = "You are the one who constructed this dream and trapped Murphy in a loop, aren't you?"
  },
  AvgDialog_118961_Content_50 = {
    Text = "Until a few months ago. Our operation in Necrovia was ruined, all because of this little {Male=guy,Female=girl} in front of us."
  },
  AvgDialog_118961_Content_51 = {
    Text = "We failed to capture enough Silver. The power of that ivory sculpture weakened, and the Awakeners on this ship started to remember everything."
  },
  AvgDialog_118961_Content_52 = {
    Text = "You remember everything... Does that mean all of you do?"
  },
  AvgDialog_118961_Content_53 = {
    Text = "So William doesn't remember solely because he comes from another world..."
  },
  AvgDialog_118961_Content_54 = {
    Text = "other Awakeners are no different from me... They are aware of what has been happening, of the same events running in a loop..."
  },
  AvgDialog_118961_Content_55 = {
    Text = "<Small:<Shake:Does the \"everyone\" you mentioned... include... her?>>"
  },
  AvgDialog_118961_Content_56 = {
    Text = "Murphy lowers her head, her voice so faint it is almost inaudible. Her gaze flickers uncertainly, often drifting towards the woman beside her, but it retracts before it can meet her eyes."
  },
  AvgDialog_118961_Content_57 = {
    Text = "You foolish little girl, I said all Awakeners."
  },
  AvgDialog_118961_Content_58 = {
    Text = "Including that stupid woman Miryam, of course."
  },
  AvgDialog_118961_Content_59 = {
    Text = "So you mean..."
  },
  AvgDialog_118961_Content_6 = {
    Text = "Miryam ponders your words. Before she can speak, a deep scoff echoes from behind you."
  },
  AvgDialog_118961_Content_60 = {
    Text = "Miryam remembers every cycle. Everything that has ever happened. And in every one, she waits... for you to change your mind."
  },
  AvgDialog_118961_Content_61 = {
    Text = "I've been having dreams of the other world since our little guest showed up. I've seen how it ends. And I bet Miryam has seen it, too."
  },
  AvgDialog_118961_Content_62 = {
    Text = "<Blue:She knows everything you do.> But in every cycle, she never intervenes. She just... waits. And waits."
  },
  AvgDialog_118961_Content_63 = {
    Text = "Goliath tips his head toward the silent Miryam beside him."
  },
  AvgDialog_118961_Content_64 = {
    Text = "You thought you trapped her in your prison? <Blue:She remains there by choice.>"
  },
  AvgDialog_118961_Content_65 = {
    Text = "Miryam responds to Goliath's speculation with silence."
  },
  AvgDialog_118961_Content_66 = {
    Text = "<Shake:Why? I don't understand why?>"
  },
  AvgDialog_118961_Content_67 = {
    Text = "Aren't I supposed to be a failed product, a single-use tool for you?"
  },
  AvgDialog_118961_Content_68 = {
    Text = "Aren't you supposed to abandon me like you abandoned them?"
  },
  AvgDialog_118961_Content_7 = {
    Text = "Let me tell you."
  },
  AvgDialog_118961_Content_8 = {
    Text = "<Shake:Because this little girl named Murphy is a liar.>"
  },
  AvgDialog_118961_Content_9 = {
    Text = "Led by the Philistines, the crowd cracks open a small gap through which a sailor pushes the embattled Murphy out."
  },
  AvgDialog_118962_Content_1 = {
    Text = "You close the cockpit door, secure the latch, and listen to the footsteps of the pursuers turn in another direction before turning around to observe your little hostage."
  },
  AvgDialog_118962_Content_10 = {
    Text = "If they are not on their duties... where would they be?"
  },
  AvgDialog_118962_Content_11 = {
    Text = "Given Goliath's personality, they're probably not slacking off at the underground casino."
  },
  AvgDialog_118962_Content_12 = {
    Text = "He must be plotting something in secret..."
  },
  AvgDialog_118962_Content_13 = {
    Text = "Meanwhile, William prepares for the confrontation in Murphy's bedroom."
  },
  AvgDialog_118962_Content_14 = {
    Text = "Even if it's just me, I can at least hold them off for twenty minutes... that is enough..."
  },
  AvgDialog_118962_Content_15 = {
    Text = "The footsteps suddenly become sparse."
  },
  AvgDialog_118962_Content_16 = {
    Text = "We greet you, Your Holiness the High Priestess!"
  },
  AvgDialog_118962_Content_17 = {
    Text = "We have cornered the intruders in the Divine Mother's chamber! Just give the word..."
  },
  AvgDialog_118962_Content_18 = {
    Text = "No need. Divine Mother is no longer here."
  },
  AvgDialog_118962_Content_19 = {
    Text = "(They found me?!)"
  },
  AvgDialog_118962_Content_2 = {Text = "Hmph..."},
  AvgDialog_118962_Content_20 = {
    Text = "Now, mister hiding in this room... why don't we have a talk?"
  },
  AvgDialog_118962_Content_21 = {
    Text = "What do you want to talk about?"
  },
  AvgDialog_118962_Content_22 = {
    Text = "Whether it is you or your friends, since boarding the ship, all the Seafarers have treated you with sacred respect."
  },
  AvgDialog_118962_Content_23 = {
    Text = "Yet you repay kindness with enmity, kidnapping the Divine Mother, causing the crucial navigation ritual to be unable to take place on schedule."
  },
  AvgDialog_118962_Content_24 = {
    Text = "If we miss this Stellar Alignment, our grand ambition will have to wait for another sixty stellar cycles."
  },
  AvgDialog_118962_Content_25 = {
    Text = "There must be a reason for this impudence, and I would like to hear both of your explanations."
  },
  AvgDialog_118962_Content_26 = {
    Text = "Because of the time loop the Keeper experienced? Because that girl was once a part of Mythag?"
  },
  AvgDialog_118962_Content_27 = {
    Text = "William has not yet sorted out a response when a nauseating, slippery, slithering sound suddenly comes from behind him."
  },
  AvgDialog_118962_Content_28 = {
    Text = "He turns around—his pupils constrict in an instant. Several fish-people burst through the entire window like a flood of filth."
  },
  AvgDialog_118962_Content_29 = {
    Text = "Twisted limbs jostle one another, forcing their way into the room; a waterfall of foul, viscous bodily fluid pours down, instantly soaking the carpet into a slick swamp."
  },
  AvgDialog_118962_Content_3 = {
    Text = "She pulls out a small mirror from somewhere and meticulously tidies the stray hairs at her forehead."
  },
  AvgDialog_118962_Content_30 = {
    Text = "He is firmly pinned at the point of death where two raging tides are about to converge."
  },
  AvgDialog_118962_Content_31 = {
    Text = "How did you..."
  },
  AvgDialog_118962_Content_32 = {
    Text = "The porthole is over ten meters high from the deck, and %player% quickly cut the long rope after escaping."
  },
  AvgDialog_118962_Content_33 = {
    Text = "How did they silently slip through the smooth walls and into the window?"
  },
  AvgDialog_118962_Content_34 = {
    Text = "The Divine Realm grants us the strength to withstand the cataclysm, and such insignificant obstacles cannot possibly hinder the Seafarers."
  },
  AvgDialog_118962_Content_35 = {
    Text = "Marine life... They have suckers on their limbs?"
  },
  AvgDialog_118962_Content_36 = {
    Text = "Apart from the Seafarers stationed on the cruise ship, marine creatures surrounding this vessel are all drawn by the spiritual call of our Lord, obeying our command."
  },
  AvgDialog_118962_Content_37 = {
    Text = "Even without this, you should know that you cannot defend against the entire Seafarer church from this small room..."
  },
  AvgDialog_118962_Content_38 = {
    Text = "An Investigator from Mythag should not be so reckless... Tell me, what else do you know?"
  },
  AvgDialog_118962_Content_39 = {
    Text = "<Big:<Shake:BOOM—>>"
  },
  AvgDialog_118962_Content_4 = {
    Text = "Where is that structure you mentioned...?"
  },
  AvgDialog_118962_Content_40 = {
    Text = "A deafening metallic ripping sound pierces the sky, accompanied by a violent tremor, as if an invisible giant hand suddenly grips the ship and twists it mercilessly!"
  },
  AvgDialog_118962_Content_41 = {
    Text = "What is going on?!"
  },
  AvgDialog_118962_Content_42 = {
    Text = "Someone is changing the course by force!"
  },
  AvgDialog_118962_Content_43 = {
    Text = "The giant ship twists and rolls like an enraged, uncontrollable beast in the monstrous waves of the night sea, each violent tremor seeming to rend the hull apart!"
  },
  AvgDialog_118962_Content_44 = {
    Text = "Engine room... It is the engine room!"
  },
  AvgDialog_118962_Content_45 = {
    Text = "Goliath has taken hostages and occupied that place!"
  },
  AvgDialog_118962_Content_46 = {
    Text = "It's happening again..."
  },
  AvgDialog_118962_Content_47 = {
    Text = "Intense tremors come in waves."
  },
  AvgDialog_118962_Content_48 = {Text = "Murphy..."},
  AvgDialog_118962_Content_49 = {
    Text = "I know. You're worried about your Senior William, right?"
  },
  AvgDialog_118962_Content_5 = {
    Text = "Right under the captain's seat, here."
  },
  AvgDialog_118962_Content_50 = {
    Text = "Of course you want to go help him. Everyone tells me I'm the most important person... right up until the moment they have to choose."
  },
  AvgDialog_118962_Content_51 = {Text = "I..."},
  AvgDialog_118962_Content_52 = {
    Text = "Forget about it. It was just pointless rambling. We barely know each other anyway, do we?"
  },
  AvgDialog_118962_Content_53 = {
    Text = "Besides, if that engine room blows, it'll take the lower deck with it."
  },
  AvgDialog_118962_Content_54 = {
    Text = "We're out of choice now. Let's go."
  },
  AvgDialog_118962_Content_6 = {
    Text = "She steps on the iron plate beneath her feet."
  },
  AvgDialog_118962_Content_7 = {
    Text = "However, this place feels a bit strange..."
  },
  AvgDialog_118962_Content_8 = {
    Text = "At this time, Goliath and Caecus should be guarding the cockpit."
  },
  AvgDialog_118962_Content_9 = {
    Text = "Before the ritual, the sea creatures become restless; we must prevent the fish from disturbing the ship's course..."
  },
  AvgDialog_118963_Content_1 = {
    Text = "Deipara's Day Off"
  },
  AvgDialog_118963_Content_10 = {
    Text = "You mean..."
  },
  AvgDialog_118963_Content_11 = {
    Text = "Yes, you can still be the Divine Mother. But the Divine Mother can use a day off."
  },
  AvgDialog_118963_Content_12 = {
    Text = "You lie with a straight face."
  },
  AvgDialog_118963_Content_13 = {Text = "A day off?"},
  AvgDialog_118963_Content_14 = {
    Text = "Yes. I've been told to take you around the ship and relax for a day."
  },
  AvgDialog_118963_Content_15 = {
    Text = "You haven't experienced the life of an ordinary crewmate, have you?"
  },
  AvgDialog_118963_Content_16 = {
    Text = "You firmly \"invited\" Murphy out of the bedroom, leaving no room for refusal."
  },
  AvgDialog_118963_Content_17 = {
    Text = "Do we really have to climb up to a place like this?"
  },
  AvgDialog_118963_Content_18 = {
    Text = "Hurry up! The vision is good up here. We can observe the patrolling Seafarers."
  },
  AvgDialog_118963_Content_19 = {
    Text = "If you keep being so slow, you'll get caught!"
  },
  AvgDialog_118963_Content_2 = {
    Text = "You open your eyes. The glaring sun makes them hurt."
  },
  AvgDialog_118963_Content_20 = {
    Text = "What are you on about... making a mess out of everything!"
  },
  AvgDialog_118963_Content_21 = {
    Text = "Despite her complaint, she obediently takes your hand. With a gentle pull, you effortlessly bring her up onto the platform."
  },
  AvgDialog_118963_Content_22 = {Text = "Pfft—"},
  AvgDialog_118963_Content_23 = {
    Text = "Murphy suddenly laughs out loud."
  },
  AvgDialog_118963_Content_24 = {
    Text = "What are you laughing at?"
  },
  AvgDialog_118963_Content_25 = {
    Text = "You climbing the rigging looks just like a monkey!"
  },
  AvgDialog_118963_Content_26 = {
    Text = "You, if it weren't for the need to keep the volume down right now, I would definitely knock a big bump on your forehead..."
  },
  AvgDialog_118963_Content_27 = {
    Text = "Stop laughing! Come hide here!"
  },
  AvgDialog_118963_Content_28 = {
    Text = "You grab Murphy's hand and pull her close to you."
  },
  AvgDialog_118963_Content_29 = {
    Text = "Hey, how dare you!"
  },
  AvgDialog_118963_Content_3 = {
    Text = "But you do not avert your gaze."
  },
  AvgDialog_118963_Content_30 = {Text = "Shh!"},
  AvgDialog_118963_Content_31 = {
    Text = "You both hold your breath. A group of Seafarers wobbles across the deck, clad in tattered and filthy straw raincoats."
  },
  AvgDialog_118963_Content_32 = {
    Text = "Hurry and find the Divine Mother! She must be on this ship!"
  },
  AvgDialog_118963_Content_33 = {
    Text = "We're right above them, and they can't see us at all?"
  },
  AvgDialog_118963_Content_34 = {
    Text = "Somehow patrollers never look up. It's almost like a trope or something."
  },
  AvgDialog_118963_Content_35 = {
    Text = "Relax, as long as we hide here, no one will ever find us."
  },
  AvgDialog_118963_Content_36 = {
    Text = "Gurgle! Look up there, there are people!"
  },
  AvgDialog_118963_Content_37 = {
    Text = "Your jinx just had to be this accurate, didn't it!"
  },
  AvgDialog_118963_Content_38 = {
    Text = "Keep it low. After we clear them out, let's sneak over to the crew quarters!"
  },
  AvgDialog_118963_Content_4 = {
    Text = "Rustling, rustling, it is the sound of a spider crawling. It feels like a mother's gentle urging."
  },
  AvgDialog_118963_Content_5 = {
    Text = "No need to remind me. I know this is the last cycle."
  },
  AvgDialog_118963_Content_6 = {
    Text = "You wipe away the tears that had welled up in the corners of your eyes and turn towards the direction from which the call is coming, no longer bothering to look back to confirm the source of the song."
  },
  AvgDialog_118963_Content_7 = {
    Text = "You know that the woman with the loom is surely gazing at you with compassion in her eyes."
  },
  AvgDialog_118963_Content_8 = {
    Text = "What are you doing here? Their memories are completely erased by me. The ship's voyage resumes, and there is no room for you here anymore."
  },
  AvgDialog_118963_Content_9 = {
    Text = "It doesn't matter. You are the Seafarers' Divine Mother, the captain of the Paradise, and the master of this Domain. This has nothing to do with the break I want to give you."
  },
  AvgDialog_119922_Content_1 = {
    Text = "Welcome back, partner."
  },
  AvgDialog_119922_Content_10 = {
    Text = "It’s alright, my lord, no matter how long you run, Ogier will be with you. I just hope..."
  },
  AvgDialog_119922_Content_11 = {
    Text = "The young knight gazes at you seriously, his eyes filled with sincerity and a plea hidden beneath that sincerity."
  },
  AvgDialog_119922_Content_12 = {
    Text = "I just hope... next time if my lord intends to \"clear your mind\" and leave for so long, please be sure to take me along. Ogier will vow to protect you to the death."
  },
  AvgDialog_119922_Content_13 = {
    Text = "Or maybe I could too."
  },
  AvgDialog_119922_Content_14 = {
    Text = "Lotan also looked at you, her usually flamboyant eyes filled with solemnity. At this moment, there were indeed no thoughts of winning or losing, no battles, only care for you."
  },
  AvgDialog_119922_Content_15 = {
    Text = "……I knew it would turn out this way. You two, don’t forget the goal of this tea party. We are celebrating %player%'s \"return\"."
  },
  AvgDialog_119922_Content_16 = {
    Text = "I hope that after your \"return\" this time, you won't leave again."
  },
  AvgDialog_119922_Content_17 = {
    Text = "It’s just a little relaxation, don’t make it sound so serious... And I’m back, right?"
  },
  AvgDialog_119922_Content_18 = {
    Text = "Hearing your words, Doll looked at you. She seemed to want to say something, but in the end, she merely sighed softly."
  },
  AvgDialog_119922_Content_19 = {
    Text = "Yes, you are back. Those who searched for your figure in the campus could only feel disappointed, and those who stood silently at your door but dared not knock have also passed."
  },
  AvgDialog_119922_Content_2 = {
    Text = "Unknowingly, Misag Square was arranged for a small tea party, and Ramona was standing by a little table full of muffins, jams, and tea, smiling and reaching out to you."
  },
  AvgDialog_119922_Content_20 = {
    Text = "%player%, I have said countless times before, and I will continue to do so in the future, your existence is incredibly important."
  },
  AvgDialog_119922_Content_21 = {
    Text = "Whether it's for this world or for us. So..."
  },
  AvgDialog_119922_Content_22 = {
    Text = "You waited for Doll to continue, but Doll only closed her eyes and said nothing more."
  },
  AvgDialog_119922_Content_23 = {
    Text = "At this moment, a pair of hands gently yet firmly covered your hand, it was Ramona."
  },
  AvgDialog_119922_Content_24 = {
    Text = "Partner, I know that as a keeper, you bear a lot of pressure, we all understand, and we won’t ask for too much."
  },
  AvgDialog_119922_Content_25 = {
    Text = "I just want you to know that no matter how many times you leave, no matter how long you are gone, we will be here when you return."
  },
  AvgDialog_119922_Content_26 = {
    Text = "As she said this, the girl's voice paused for a moment, slowly revealing a smile to you."
  },
  AvgDialog_119922_Content_27 = {
    Text = "Welcome back once again, partner. Now, enjoy this tea party prepared for you."
  },
  AvgDialog_119922_Content_28 = {
    Text = "That’s right. There’s no assessment today, no extra assignments. Your only task is to make yourself happy."
  },
  AvgDialog_119922_Content_29 = {
    Text = "If you don't care about cavities and excessive sugar intake, you can eat all these desserts. After all, they are prepared for you."
  },
  AvgDialog_119922_Content_3 = {
    Text = "I wonder if I have the honor to invite you to the return tea party we prepared for you?"
  },
  AvgDialog_119922_Content_30 = {
    Text = "There's really no need for that..."
  },
  AvgDialog_119922_Content_31 = {
    Text = "Although saying this, you still took a bite of the frosted butter roll. The taste was just as sweet as you imagined, overly sweet, yet not unpleasant."
  },
  AvgDialog_119922_Content_32 = {
    Text = "Because, in the caring gazes of others, your heart has found satisfaction. Perhaps, life is about tasting such a touching sweetness in the bitter intervals of reality."
  },
  AvgDialog_119922_Content_4 = {
    Text = "You nod, and the girl gently takes your hand, leading you to the triangular table filled with dishes, and to the awakeners who have been waiting by the table for a long time."
  },
  AvgDialog_119922_Content_5 = {
    Text = "If you ask me, isn't a fight more \"exciting\" than a tea party? But indeed... this time is a bit different."
  },
  AvgDialog_119922_Content_6 = {
    Text = "This time, it has nothing to do with win or lose, nothing to do with battle. It’s only about you."
  },
  AvgDialog_119922_Content_7 = {
    Text = "%player%, you are the absolute main character of this tea party."
  },
  AvgDialog_119922_Content_8 = {
    Text = [[
Lotan said, pushing a plate of frosted butter rolls in front of you.
Just one glance, and you knew it was horrifyingly high in calories.]]
  },
  AvgDialog_119922_Content_9 = {
    Text = "I wonder why it feels like... just taking a bite will require a whole semester to digest..."
  },
  AvgDialog_119923_Content_1 = {
    Text = "In the pitch-black spiritual mire, there comes a piercing pain that reaches the soul, accompanied by a cold voice."
  },
  AvgDialog_119923_Content_10 = {
    Text = "Recalling the feeling of having your skull opened, your brain tingles, and to shake off this sensation, you actively change the topic."
  },
  AvgDialog_119923_Content_11 = {
    Text = "What is the state of this world... now?"
  },
  AvgDialog_119923_Content_12 = {
    Text = "Still the same. Every moment you come closer to breakdown and destruction. But at least there’s good news for you."
  },
  AvgDialog_119923_Content_13 = {
    Text = "As she spoke, Meltdown Doll opened the communicator, and soon, a familiar figure appeared before you. It was a previously recorded message communication."
  },
  AvgDialog_119923_Content_14 = {
    Text = "Doll: Inferno, if %player% successfully returns, or if there is any news, remember to tell me. Also, I think your previous suggestion about planting psychological hints is very reasonable."
  },
  AvgDialog_119923_Content_15 = {
    Text = "As a professional psychologist, while asking %player% to stay, I cannot overly cater to the desires of the patient..."
  },
  AvgDialog_119923_Content_16 = {
    Text = "Communication abruptly ends here, closed by doll: inferno. She gently tapped the table, signaling you to focus on her."
  },
  AvgDialog_119923_Content_17 = {
    Text = "The useless small talk can stop here. I put this forward just to show you what went wrong during your \"absence\"."
  },
  AvgDialog_119923_Content_18 = {
    Text = "Most importantly, my experiment is not yet over..."
  },
  AvgDialog_119923_Content_19 = {
    Text = "Doll: Inferno approaches you with a scalpel. Her expression is calm, yet harbors a touch of madness."
  },
  AvgDialog_119923_Content_2 = {
    Text = "How much longer are you going to pretend to be asleep? My lovely puppy."
  },
  AvgDialog_119923_Content_20 = {
    Text = "What, what are you going to do?"
  },
  AvgDialog_119923_Content_21 = {
    Text = "I plan to permanently fix your spirit in this mind, this body. That way, you won't be able to \"leave\" anymore."
  },
  AvgDialog_119923_Content_22 = {
    Text = "You took a step back in fright, but soon regained your composure as you remembered there was still something you had yet to finish—"
  },
  AvgDialog_119923_Content_23 = {
    Text = "Doll: Inferno, it doesn't have to be like this. As long as this world hasn't returned to normal, I won't truly leave."
  },
  AvgDialog_119923_Content_24 = {
    Text = "The figure holding the scalpel stops, quietly looking at you, seemingly judging the truth of your words."
  },
  AvgDialog_119923_Content_25 = {
    Text = "I am serious. As a keeper, I will never give up on saving this world, so no matter how long I \"leave,\" I will always return."
  },
  AvgDialog_119923_Content_26 = {
    Text = [[
Doll: Inferno puts down the scalpel. Seizing this opportunity, you reach for your chest.
When your fingertips touch the familiar silver key, your heart truly settles down.]]
  },
  AvgDialog_119923_Content_27 = {
    Text = "Now, I have returned. The interrupted investigation can continue."
  },
  AvgDialog_119923_Content_28 = {
    Text = "As you said this, you walked towards the door. Meltdown Doll glanced at you and followed along."
  },
  AvgDialog_119923_Content_29 = {
    Text = "It seems you really understand the importance of your existence to this world."
  },
  AvgDialog_119923_Content_3 = {
    Text = "Doll: Inferno?"
  },
  AvgDialog_119923_Content_30 = {
    Text = "Of course, because as Tawil once said, I am the variable of this world, the future of this world."
  },
  AvgDialog_119923_Content_31 = {
    Text = "As your words were spoken, the door to the laboratory slowly opened. The outside air and sunlight gradually fell on you, like a silent greeting or a response."
  },
  AvgDialog_119923_Content_32 = {
    Text = "This world is waiting for you, waiting for the changes you are about to bring, the future you are about to create."
  },
  AvgDialog_119923_Content_4 = {
    Text = "You recognized the owner of that voice and slowly opened your eyes. Soon, the darkness faded away, and light emerged——"
  },
  AvgDialog_119923_Content_5 = {
    Text = "What does it feel like to \"leave\" this world?"
  },
  AvgDialog_119923_Content_6 = {
    Text = "Perhaps next time I should also confine your \"Spirit,\" so that it doesn’t need to be retrieved."
  },
  AvgDialog_119923_Content_7 = {
    Text = "Doll: Inferno squints her eyes, revealing a half-smile expression as she slowly plays with the scalpel sparkling with cold light in her hand."
  },
  AvgDialog_119923_Content_8 = {
    Text = "……Why am I here?"
  },
  AvgDialog_119923_Content_9 = {
    Text = "Of course, it’s because when your \"Spirit\" leaves, the vessel loses its function, which is why I had to perform the surgery again to retrieve your \"Spirit.\""
  },
  AvgDialog_120290_Content_1 = {
    Text = "Gilded Flesh-Pot"
  },
  AvgDialog_120290_Content_10 = {
    Text = "You fall into her embrace. She lifts you onto the bed, tucking the corners of the quilt tight. She leans down, pressing her forehead to yours, then pulls you against her chest."
  },
  AvgDialog_120290_Content_11 = {
    Text = "Mūmā...? Mūmā!"
  },
  AvgDialog_120290_Content_12 = {
    Text = "Mūmā, Papa hasn't looked in on me for so long. There's no one in the house to help me... no water... My head hurts. Everything hurts."
  },
  AvgDialog_120290_Content_13 = {
    Text = "...Don't cry, <Italic:Nānnān>."
  },
  AvgDialog_120290_Content_14 = {
    Text = "Rest easy. Everything will be better soon."
  },
  AvgDialog_120290_Content_15 = {
    Text = "You sink into the warmth of the blankets. In your delirium, you notice the fragrance growing heavier. It is no longer the light jasmine your mother always wore. It smells like..."
  },
  AvgDialog_120290_Content_16 = {
    Text = "What does it smell like? Like the deepest, winding alleys of Shencheng, where great magnolia blossoms fall and ferment in the stifling heat—a strange, cloying, sickly sweetness."
  },
  AvgDialog_120290_Content_17 = {
    Text = "Mūmā, are you wearing a new fragrance? It's so strong... and... so strange."
  },
  AvgDialog_120290_Content_18 = {
    Text = "The gentle voice offers no answer. As she rhythmically pats your shoulder, the scent thickens until it feels almost solid, a physical weight."
  },
  AvgDialog_120290_Content_19 = {
    Text = "You strain to see her face, but an endless haze swirls before your eyes, finally swallowing you whole."
  },
  AvgDialog_120290_Content_2 = {
    Text = "A thin mist, carrying the scent of jasmine, coils around your limbs, entangling you in a damp, invisible embrace."
  },
  AvgDialog_120290_Content_20 = {
    Text = "Sleep now, precious child. Sleep. Your Mūmā will be back by your side before long."
  },
  AvgDialog_120290_Content_21 = {
    Text = "...I have already given her my word."
  },
  AvgDialog_120290_Content_22 = {
    Text = "In the darkness, thirst still claws at your throat like a cat. Suddenly, a warm, viscous liquid begins to flow into your mouth—trickling in from your nose, or perhaps the corners of your lips."
  },
  AvgDialog_120290_Content_23 = {
    Text = "Your eyelids grow heavy. Amidst the heavy perfume and the low murmurs, you drift into total unconsciousness."
  },
  AvgDialog_120290_Content_24 = {
    Text = "The sound of footsteps rustles and gathers outside the door, rousing you from your throbbing, drowsy haze with voices in conversation."
  },
  AvgDialog_120290_Content_25 = {
    Text = "Aiyo! This Young Mistress... the moment she opens her eyes she wants her tea. It's enough to vex a saint! Does she really think she's still the pampered little pet from when the Madam was alive?"
  },
  AvgDialog_120290_Content_26 = {
    Text = "Keep your voice down! ...The Master doesn't spare a thought for his own daughter anyway. Look at how many pretty concubines are stuffed into this courtyard now. And look at him today—off to the Fourth Avenue brothels again."
  },
  AvgDialog_120290_Content_27 = {
    Text = "Just you wait. Mark my words, it won't be long before all those concubines start popping out more \"Little Masters\" and \"Little Misses\"..."
  },
  AvgDialog_120290_Content_28 = {
    Text = "...The Master?"
  },
  AvgDialog_120290_Content_29 = {
    Text = "In a tarnished copper basin atop a wooden stand, you see the blurred reflection of a delicate, youthful face. You blink in a daze; the little girl in the reflection blinks back."
  },
  AvgDialog_120290_Content_3 = {
    Text = "The stupor of a high fever draws you toward the vapor..."
  },
  AvgDialog_120290_Content_30 = {
    Text = "Your consciousness gradually clears, and you struggle to recall your identity."
  },
  AvgDialog_120290_Content_31 = {
    Text = "...The Master, <Italic:Ho Fong>... Father... I'm at the Ho family mansion, I am the daughter of Ho Fong, my name is..."
  },
  AvgDialog_120290_Content_32 = {
    Text = "Aiyah! What are you doing on the floor? The Master will have my head if he sees you like that!"
  },
  AvgDialog_120290_Content_33 = {
    Text = "The door flies open. A woman rushes in and hauls you up with an impatient, sharp tug."
  },
  AvgDialog_120290_Content_34 = {
    Text = "Why was I on the floor... where is Mūmā?"
  },
  AvgDialog_120290_Content_35 = {
    Text = "Your Mūmā? Young Miss, get your head straight. The Madam has been \"gone\" over a month now."
  },
  AvgDialog_120290_Content_36 = {
    Text = "She stops short. Seeing you standing there, small and vacant, a flash of pity crosses her face."
  },
  AvgDialog_120290_Content_37 = {
    Text = "<Small:<Italic:Just a mite, isn't she? Poor thing likely doesn't even know what \"gone\" means.>>"
  },
  AvgDialog_120290_Content_38 = {
    Text = "<LightGray:<Italic:(That's right. A month ago, Mūmā already...)>>"
  },
  AvgDialog_120290_Content_39 = {
    Text = "Did you dream again? Sigh. Here, I brought you some water."
  },
  AvgDialog_120290_Content_4 = {
    Text = "...and you tumble, sprawling onto the floorboards."
  },
  AvgDialog_120290_Content_40 = {
    Text = "Water... you're no longer thirsty; the liquid that flowed in earlier, accompanied by its fragrance."
  },
  AvgDialog_120290_Content_41 = {
    Text = [[
The smell of magnolias. It still haunts your palate and your breath.
Sweet to the point of rot.
It's the fragrance <Italic:in that dream>! You bolt upright, realization hitting you like a physical blow. You sprint for the door.]]
  },
  AvgDialog_120290_Content_42 = {
    Text = "Hey! Hey! Where do you think you're going! Miss!"
  },
  AvgDialog_120290_Content_43 = {
    Text = "The festival has begun. The first lights of evening are flickering on—red lanterns competing with the harsh glow of modern neon. But the crowds, who should be heading home for the holiday, are all surging in one direction."
  },
  AvgDialog_120290_Content_44 = {
    Text = "The air is a thick soup of face powder, kerosene, greasy cooking smoke, and that growing scent of..."
  },
  AvgDialog_120290_Content_45 = {
    Text = "My Mūmā. It's her scent. It wasn't a dream! It wasn't!"
  },
  AvgDialog_120290_Content_46 = {
    Text = "You follow the source of that strange, potent, familiar, tender, and cloyingly sweet aroma."
  },
  AvgDialog_120290_Content_47 = {
    Text = "The sign for the Gilded Boudoir hangs high upon an ornate gate."
  },
  AvgDialog_120290_Content_48 = {Text = "Lady Xu!"},
  AvgDialog_120290_Content_49 = {
    Text = "Out of my way, you're blocking me! Lady Xu! Look this way!"
  },
  AvgDialog_120290_Content_5 = {
    Text = "Ow... <Italic:Mūmā>... water..."
  },
  AvgDialog_120290_Content_50 = {Text = "Tsk."},
  AvgDialog_120290_Content_51 = {
    Text = "High upon a platform, a figure idly toys with a black fan, her features half-hidden behind the silk."
  },
  AvgDialog_120290_Content_52 = {
    Text = "The throng of bodies threatens to drown you. A feverish, frantic hunger creeps into the eyes of the men around you, but she remains untouched by the chaos."
  },
  AvgDialog_120290_Content_53 = {
    Text = "You find the source of the perfume—or rather, a primal, incomprehensible longing seizes you. You strain your neck, staring upward."
  },
  AvgDialog_120290_Content_54 = {Text = "...Ah."},
  AvgDialog_120290_Content_55 = {
    Text = "As if sensing your gaze, she looks down. You only see a pair of very, very beautiful eyes."
  },
  AvgDialog_120290_Content_56 = {
    Text = "The black fan moves aside with a heart-stopping, predatory elegance."
  },
  AvgDialog_120290_Content_57 = {
    Text = "<color=#C6C4C6>MistMISTMiST</color>\n<color=#817D81>MISTmIsT</color><color=#B9B7B9>She... IT? IT...She... Mother...</color>MOTHErHeR EYES\n<color=#C6C4C6>MISTmIsT</color><color=#B9B7B9>MIST</color><color=#817D81>mIsTMISTmIsTMISTmIsTMIST</color><color=#C6C4C6>MIST</color> <color=#757175>MIST</color>       <color=#817D81>SHESHESHESHESHE</color>                         <color=#757175>mIsTMISTmIsT</color><color=#C6C4C6>MISTMISTMOTHERmIsTMIST</color> <color=#C6C4C6>mIsTMISTmIsT</color>      <color=#B9B7B9>SHESHESHESHESHE</color>         <color=#817D81> mIsTMISTmIsT</color><color=#D7D7D7>MISTmIsTMISTmIsTMISTmIsTMISTmIsT</color> <color=#D7D7D7>MISTmIsTMISTmIsT</color><color=#B9B7B9>MIsTMIST</color><color=#757175>mIsTMISTmIsT</color><color=#ACAAAC>MISTmIsTMISTmIsTMISTmIsTMISTmIsTMIST</color> <color=#B9B7B9>sEYESmIsTMISTmIsT</color><color=#817D81>BEAUTIFULEYES</color><color=#B9B7B9>mIsTMISTmIsTMISTmIsT</color><color=#757175>BEAUTIFULEYES</color><color=#D7D7D7>MISTmIsT MISTmIsTMISTmIsTMISTmIsTMISTMISTmIsTMISTmIsT</color> <color=#5F5D5F>MOTHERSTHERMOmIsT</color><color=#817D81>MISTmIsTMISTMOMmO</color><color=#757175>EYEMOMEYESEYEmIsTMISTmIsT</color><color=#B9B7B9>SHESHESHESHEmIsTMIST</color> <color=#757175>mIsTMISTmIsTEYESBEAUMIST</color><color=#B9B7B9>mIsTMISTmIsTMISTmIsTMISTMOTHERSmIsTMISTmIsT</color> <color=#C6C4C6>MOTHERSMoTHERMOTHERS</color><color=#D7D7D7>MOMOTHERSMOTHERSTHER</color><color=#ACAAAC>MOTHERSTHERBEAUTIFUL</color>"
  },
  AvgDialog_120290_Content_58 = {
    Text = "Screams and howls explode in your ears. The sea of bodies collapses inward!"
  },
  AvgDialog_120290_Content_59 = {
    Text = "I saw! I saw! She looked at me!"
  },
  AvgDialog_120290_Content_6 = {
    Text = "As you speak, a searing thirst takes hold. Memory has not yet returned; your limbs are like lead, useless and soft. Instinctively, you cry out the most familiar word you know."
  },
  AvgDialog_120290_Content_60 = {
    Text = "SHE'S LOOKING AT ME!"
  },
  AvgDialog_120290_Content_61 = {
    Text = "<Change>Such beauty... how can a face be so perfect... so... divine... so terrifying.."
  },
  AvgDialog_120290_Content_62 = {
    Text = "Lady Xu! Lady Xu... Please, please!!"
  },
  AvgDialog_120290_Content_63 = {
    Text = "LOOK AT ME!"
  },
  AvgDialog_120290_Content_64 = {
    Text = "<Shake:<Red:AAAHHHHHHH!!!!>>"
  },
  AvgDialog_120290_Content_65 = {
    Text = "The dandy suddenly shrieks and lunges at the man in the suit, who stares fixedly at the platform even as his eyes are torn from his head."
  },
  AvgDialog_120290_Content_66 = {
    Text = "The blinded man wails and laughs simultaneously, the wet spheres dangling from his now empty eye sockets. He wipes the gore from his face and reaches toward the platform with every ounce of his strength, veins bulging in his arms."
  },
  AvgDialog_120290_Content_67 = {
    Text = "As if a signal has been given, the crowd turns into a maddened tide. Amidst the laughter and the screams, they surge forward, desperate to touch the high stage."
  },
  AvgDialog_120290_Content_68 = {
    Text = "<Change>Xu!! Xu!!!"
  },
  AvgDialog_120290_Content_69 = {
    Text = "<Change>XU——!!!!"
  },
  AvgDialog_120290_Content_7 = {
    Text = "A gentle, fragmented humming drifts closer. A woman's silhouette passes across the door—achingly familiar, radiating warmth. Your legs feel hollow, but you struggle to prop yourself up..."
  },
  AvgDialog_120290_Content_70 = {
    Text = "The cacophony threatens to shatter your eardrums. The crowd heaves; the fragile bones of your young body groan under the pressure. That face beneath the fan seems to become clearer, yet more impossible to grasp."
  },
  AvgDialog_120290_Content_71 = {
    Text = "In the end, it coalesces into a abyss-like mist that swallows all light."
  },
  AvgDialog_120290_Content_72 = {
    Text = "And then, a sound cuts through the mist—a light, melodic, joyful laugh."
  },
  AvgDialog_120290_Content_73 = {
    Text = "There you are, my Little Jasmine."
  },
  AvgDialog_120290_Content_74 = {
    Text = "A moment before the darkness and suffocation take you, you catch a glimpse of a certain person. He is caught in the same mindless fervor, his dignity discarded, shoving his way forward..."
  },
  AvgDialog_120290_Content_75 = {
    Text = "A man whose eyes never once fell upon you... Your father."
  },
  AvgDialog_120290_Content_8 = {
    Text = "<Shake:Creeeeak—>"
  },
  AvgDialog_120290_Content_9 = {
    Text = "Oh, you poor thing. Why are you sprawled out on the floor like this?"
  },
  AvgDialog_120291_Content_1 = {
    Text = "Sudden Apparition"
  },
  AvgDialog_120291_Content_10 = {
    Text = "A piece of dry pastry is shoved into your mouth. The moment the cake begins to dissolve, saliva floods your mouth."
  },
  AvgDialog_120291_Content_11 = {
    Text = "You follow behind her, chewing nonstop. Just as your stomach begins to relax, a far heavier pressure seizes your heart."
  },
  AvgDialog_120291_Content_12 = {
    Text = "Don't just stand there, Miss. Get inside. Lady Xu has been waiting an age."
  },
  AvgDialog_120291_Content_13 = {
    Text = "Your father, Ho Fong, is surrounded as always by concubines whose faces you don't remember. In this manor, the \"aunties\" come and go—some slender as swallows, some plump and graceful."
  },
  AvgDialog_120291_Content_14 = {
    Text = "But now, his gaze is fixed with a delirious intensity on only one person."
  },
  AvgDialog_120291_Content_15 = {
    Text = "The owner of those maddeningly beautiful eyes is currently playing a role with an air of detached, professional courtesy. She is visibly bored. That is, until her gaze falls tenderly upon you."
  },
  AvgDialog_120291_Content_16 = {
    Text = "I knew you would descend after the ritual, but I never imagined you would be this... enchanting."
  },
  AvgDialog_120291_Content_17 = {
    Text = "I shouldn't have sent you to the Gilded Boudoir. Yes... I should keep you by my side. Nothing else matters anymore. Nothing matters without you!"
  },
  AvgDialog_120291_Content_18 = {
    Text = "Master Ho, do not lose your composure. We shall reminisce later. I have come today to offer my apologies."
  },
  AvgDialog_120291_Content_19 = {
    Text = "What does a silly little girl know? I shall begin preparing bridewealth for the Gilded Boudoir. If you like her, take her; keep her by your side and raise her yourself."
  },
  AvgDialog_120291_Content_2 = {Text = "..."},
  AvgDialog_120291_Content_20 = {
    Text = "Master Ho, you are a man of such grand character. Should fate allow us to tie the knot, I would be delighted."
  },
  AvgDialog_120291_Content_21 = {
    Text = "However, I felt a kinship with this child the moment we met, despite our... \"accident\" earlier. If you and I are to grow closer, it would be best if her heart were at peace first."
  },
  AvgDialog_120291_Content_22 = {
    Text = "The woman they call Lady Xu glides toward you. She leans over to look you in the eye."
  },
  AvgDialog_120291_Content_23 = {
    Text = "I have not yet introduced myself. My name is Xu. So, what do you say, Little Miss of the Ho Family?"
  },
  AvgDialog_120291_Content_24 = {
    Text = "Instinctively, you clutch the hand of the servant who brought you, trying to hide behind her robe."
  },
  AvgDialog_120291_Content_25 = {
    Text = [[
Her fingertips, as smooth as jade, tilt your chin upward.
You see those eyes again.
They are beautiful enough to trigger a primal terror, yet they are identical to your mother's.]]
  },
  AvgDialog_120291_Content_26 = {Text = "I... I..."},
  AvgDialog_120291_Content_27 = {
    Text = "<Shake:Everyone who saw you on the street went mad. The Uncle in a suit had his eyes torn out! I-I'm scared!>"
  },
  AvgDialog_120291_Content_28 = {
    Text = "Your childish outburst causes Lady Xu to blink in surprise. Then, she laughs with such abandon she nearly loses her poise."
  },
  AvgDialog_120291_Content_29 = {
    Text = "What a coincidence! Master Du, if you would be so kind as to settle my embarrassment. Little Jasmine, look closer—is this the Uncle you saw?"
  },
  AvgDialog_120291_Content_3 = {
    Text = "The shock of being at the epicenter of such unknown frenzy should have shattered your mind, or at least your will."
  },
  AvgDialog_120291_Content_30 = {
    Text = "You follow her finger as it moves from your chin. There, standing behind the huddle of jealous concubines, is the man in the suit earlier."
  },
  AvgDialog_120291_Content_31 = {
    Text = "It's him. Eh? How are his eyes back?"
  },
  AvgDialog_120291_Content_32 = {
    Text = "His face is no longer a mask of gore; his eyes are exactly where they should be. You recognize him now."
  },
  AvgDialog_120291_Content_33 = {
    Text = "When your mother was still alive, your father would try to corner this man at banquets to talk business, only to be brushed off every time. Your father would come home in a rage."
  },
  AvgDialog_120291_Content_34 = {
    Text = "This is the girl who was so frightened? She's hardly worth the effort of sending me all that way just to buy her sweets."
  },
  AvgDialog_120291_Content_35 = {
    Text = "If the Ho family can't even manage a hysterical daughter, they have no business meddling in the city's import trade. Laughable."
  },
  AvgDialog_120291_Content_36 = {
    Text = "My daughter has been... unwell since the passing of my wife. My apologies, Master Du, I shall..."
  },
  AvgDialog_120291_Content_37 = {
    Text = "Seeing your father's face darken, you stiffen in terror. But then, the scent of magnolias envelops you. Lady Xu pulls you into her arms, kneading and stroking your shoulder with careless affection."
  },
  AvgDialog_120291_Content_38 = {
    Text = "Master Du... I told you, I am fond of this little girl. When you speak of her so harshly, I find myself quite displeased. And when I am displeased... what are you prepared to do?"
  },
  AvgDialog_120291_Content_39 = {
    Text = "The man's eyes, which had been scanning you with utter contempt, suddenly lose their focus. Then, he swings his arm back and begins to slap his own face, <Italic:over and over.>"
  },
  AvgDialog_120291_Content_4 = {
    Text = "But you are far too young. Your brain is as simple as a mayfly. No—simpler. An amoeba, a single-celled speck. You only know hunger, cold, and the primal urge to seek comfort."
  },
  AvgDialog_120291_Content_40 = {
    Text = "His cheeks swell and redden instantly, yet he seems to feel no pain. He grins mechanically, baring his teeth in a smile like a wooden mannequin at a foreign carnival."
  },
  AvgDialog_120291_Content_41 = {
    Text = "Sorry! I spoke out of turn!"
  },
  AvgDialog_120291_Content_42 = {
    Text = "I spoke out of turn! I spoke out of turn!"
  },
  AvgDialog_120291_Content_43 = {
    Text = "To the rhythmic slapping sounds, Lady Xu giggles. She plucks a bag of candy from the man's unresisting hand and tucks a piece into your mouth."
  },
  AvgDialog_120291_Content_44 = {
    Text = "Now this is a fun sight. Do you like it, Little Miss?"
  },
  AvgDialog_120291_Content_45 = {
    Text = "A sweet, thick liquid melts in your mouth. You stare blankly before finally lifting your head to look at Xu."
  },
  AvgDialog_120291_Content_46 = {
    Text = "...Pear syrup candy from the City God Temple. Mūmā used to buy this for me."
  },
  AvgDialog_120291_Content_47 = {
    Text = "Lady Xu... are you my Mūmā?"
  },
  AvgDialog_120291_Content_48 = {
    Text = "Lady Xu does not answer. She only smiles. Your father and his concubines stand like statues, entranced and silent."
  },
  AvgDialog_120291_Content_49 = {
    Text = "Oh, look at you, Master Du. I was only being temperamental. To strike yourself so hard... it breaks my heart."
  },
  AvgDialog_120291_Content_5 = {
    Text = "And so, the cage of mist simply catches you again. You open your eyes, physically unscathed."
  },
  AvgDialog_120291_Content_50 = {
    Text = "The moment the man stops, the concubines seem to snap awake. They stare at Master Du's bruised and battered face in shock."
  },
  AvgDialog_120291_Content_51 = {
    Text = "I remembered Master Ho's desire for a word with Master Du. I took the liberty of escorting him here—consider it a small courtesy of my own."
  },
  AvgDialog_120291_Content_52 = {
    Text = "Little Miss, while they talk, would you care to take a walk with me?"
  },
  AvgDialog_120291_Content_53 = {
    Text = "Before stepping out, you cannot help but look back at your father. He does not wear the vacant, eerie expression of the others, yet he allows it all to happen in absolute silence."
  },
  AvgDialog_120291_Content_54 = {
    Text = "Lady Xu, you..."
  },
  AvgDialog_120291_Content_55 = {
    Text = "You have many questions, don't you?"
  },
  AvgDialog_120291_Content_56 = {
    Text = "No rush, my dear."
  },
  AvgDialog_120291_Content_57 = {
    Text = "My Little Jasmine... Come, take a look at me."
  },
  AvgDialog_120291_Content_58 = {
    Text = "The night presses down, heavy and suffocating. In the warm glow of the lanterns, Lady Xu moves her fan aside. A hazy mist lunges at you, wrapping around you, swallowing you whole."
  },
  AvgDialog_120291_Content_59 = {
    Text = "Blurred by the vapor, your mother stands in the light. She is smiling, leaning down with her arms open wide."
  },
  AvgDialog_120291_Content_6 = {
    Text = "Night has fallen completely. Candlelight flickers from the windows of distant rooms, and those light, hurried footsteps approach once more."
  },
  AvgDialog_120291_Content_60 = {
    Text = "It's as if a string inside you finally snaps. Your nose stings, tears blurring your vision, and you throw yourself into her embrace."
  },
  AvgDialog_120291_Content_61 = {
    Text = "Mūmā, don't leave me again, please..."
  },
  AvgDialog_120291_Content_62 = {
    Text = "Sob... waaahhhh... My head is so messy. I'm so scared. I missed you so much! Mūmā..."
  },
  AvgDialog_120291_Content_63 = {
    Text = "She circles her arms around you, gently stroking your back."
  },
  AvgDialog_120291_Content_64 = {
    Text = "My precious child. My good, sweet girl."
  },
  AvgDialog_120291_Content_65 = {
    Text = "My little <Italic:bǎobèi>. My obedient darling..."
  },
  AvgDialog_120291_Content_66 = {
    Text = "What would you give... to stay with your mother forever?"
  },
  AvgDialog_120291_Content_67 = {
    Text = "The mist coils tighter. You hear your own voice, a distant murmur."
  },
  AvgDialog_120291_Content_68 = {
    Text = "Anything... I'll give you everything."
  },
  AvgDialog_120291_Content_69 = {
    Text = "Even this entire mansion?"
  },
  AvgDialog_120291_Content_7 = {
    Text = "Aiyo, Little Miss, you nearly scared us to death! Wandering into the main road in a trance like that—you'll be the end of us servants, you will!"
  },
  AvgDialog_120291_Content_70 = {
    Text = "I don't want the house. I only want Mūmā."
  },
  AvgDialog_120291_Content_71 = {
    Text = "This mansion, the whole of Shencheng, and even your father... can I have them all?"
  },
  AvgDialog_120291_Content_72 = {
    Text = "Father... Papa..."
  },
  AvgDialog_120291_Content_73 = {
    Text = "You drift for a moment, lost in thought. You remember the long nights of waiting with your mother—and the heavy, warm hand your father would rest upon your head when he finally returned."
  },
  AvgDialog_120291_Content_74 = {
    Text = "Take your time. We have plenty of it, my Little Jasmine."
  },
  AvgDialog_120291_Content_75 = {
    Text = "You feel yourself being lifted, tucked into soft, plush bedding. Something warmer, something more moist and supple, embraces you intimately."
  },
  AvgDialog_120291_Content_76 = {
    Text = "The night is deep. Sleep now. I will be by your side again very, very soon."
  },
  AvgDialog_120291_Content_77 = {
    Text = "For the first time since your mother's death, you feel an absolute, crushing sense of peace. You fall into the depths of a sweet, dark dream."
  },
  AvgDialog_120291_Content_8 = {
    Text = "<Shake:Gurgle—>"
  },
  AvgDialog_120291_Content_9 = {
    Text = "...Sigh. I truly pity you, I do. Here, eat. The Master is already waiting in the hall. Don't go making more trouble for us, you hear?"
  },
  AvgDialog_120296_Content_1 = {
    Text = "Oh, My Dearest"
  },
  AvgDialog_120296_Content_10 = {
    Text = "Enough with your little schemes. I'm not just trying to scare you, but any woman the Master loves too much... they all vanish in the end."
  },
  AvgDialog_120296_Content_11 = {
    Text = "Even his first wife, his childhood sweetheart—they say she died of illness, but who knows if she—"
  },
  AvgDialog_120296_Content_12 = {
    Text = "Ow! Why are you shoving me!"
  },
  AvgDialog_120296_Content_13 = {
    Text = "Madam, please... please forgive us. My sister speaks without thinking. Do not listen to her nonsense; we have absolutely no intention of competing with you. I beg of you, do not tell the Master."
  },
  AvgDialog_120296_Content_14 = {
    Text = "Her sister's violent tug brings her back to her senses. The meticulously dressed concubine suddenly turns deathly pale. She clamps her hand over her mouth, falling into a terrified silence."
  },
  AvgDialog_120296_Content_15 = {
    Text = "Since this place is not safe, why haven't you thought of seeking a life elsewhere?"
  },
  AvgDialog_120296_Content_16 = {
    Text = "...And go where? If only we were like you—cherished like pearls by the big people—then we truly could go anywhere we pleased."
  },
  AvgDialog_120296_Content_17 = {
    Text = "Hee-hee. Cherished like pearls?"
  },
  AvgDialog_120296_Content_18 = {
    Text = "Xu laughs suddenly, and for a fleeting second, every woman in the gallery hears a more spectral, wandering tittering."
  },
  AvgDialog_120296_Content_19 = {
    Text = "Their eyes begin to glaze over. With vacant expressions, they turn toward the woman drifting further into the shadows of the corridor."
  },
  AvgDialog_120296_Content_2 = {
    Text = "That new little vixen... she certainly knows a trick or two, doesn't she?"
  },
  AvgDialog_120296_Content_20 = {
    Text = "My Little Jasmine is sleeping; let us not wake her. Follow me."
  },
  AvgDialog_120296_Content_21 = {
    Text = "I shall show you how those \"big people,\" like all treasures, are only fun when they're pinched between one's fingertips."
  },
  AvgDialog_120296_Content_22 = {
    Text = "Daft, idiotic smiles spread across the concubines' faces. Then, the mist rises to veil their lips, and the fans move to mask their faces."
  },
  AvgDialog_120296_Content_23 = {
    Text = "A thick, cloyingly sweet scent of magnolia begins to bleed through the Ho Mansion."
  },
  AvgDialog_120296_Content_24 = {Text = "..."},
  AvgDialog_120296_Content_25 = {
    Text = "Ever since Lady Xu was brought into the Ho Mansion as the Second Wife, you haven't gone hungry for a single day. Everyone treats you with a burning, sudden kindness, as if you were still the precious Young Miss you were when your mother was alive."
  },
  AvgDialog_120296_Content_26 = {
    Text = "But your father has not stepped out of his room once. Lady Xu never enters it either; instead, the concubines, as if pulled by invisible silken threads, frequent her private quarters."
  },
  AvgDialog_120296_Content_27 = {
    Text = "Aiyah, Miss, give me a break, won't you? The Master gave strict orders that no one is to go near his room."
  },
  AvgDialog_120296_Content_28 = {
    Text = "I haven't seen Papa in so long. I... I'll just look from a distance. I promise not to disturb him."
  },
  AvgDialog_120296_Content_29 = {
    Text = "Yet, before you even draw close, you hear a frantic, abnormally feverish growl coming from inside."
  },
  AvgDialog_120296_Content_3 = {
    Text = "Oh, you and your wicked tongue. That fan she gave you—you haven't let it out of your sight for a second, have you?"
  },
  AvgDialog_120296_Content_30 = {
    Text = "Xu... my darling, my savior, my heart... I cannot let them take you away again. You are mine. You can only be mine."
  },
  AvgDialog_120296_Content_31 = {
    Text = "Those women, their blood, their bones... they mean nothing... No matter the cost! AHH! So long as I have you... so long as I have you, it is all worth it!"
  },
  AvgDialog_120296_Content_32 = {
    Text = "I understand now! I see it! Haha, HAHAHAHA!!!"
  },
  AvgDialog_120296_Content_33 = {
    Text = "You hear something wet slithering across the floor. Finally, Ho Fong's breathing turns into a short, choked rattling, like a broken bellows, as if he is being squeezed by something that won't let him draw breath."
  },
  AvgDialog_120296_Content_34 = {Text = "Papa!"},
  AvgDialog_120296_Content_35 = {
    Text = "Terrified by his death-like gasping, you lunge forward and throw the door open."
  },
  AvgDialog_120296_Content_36 = {
    Text = "There is only Ho Fong. He is slumped frantically against the edge of the bed, sprawling over dark bedding. The entire room is so damp it feels as though it's been submerged in water."
  },
  AvgDialog_120296_Content_37 = {
    Text = "Shattered ornaments and torn scraps of fabric are strewn across the floor in a mess. He snaps toward you, his face flushed with an unnatural, sickly crimson. He snatches up a wooden pillow and hurls it at your head."
  },
  AvgDialog_120296_Content_38 = {
    Text = "Who let you in!"
  },
  AvgDialog_120296_Content_39 = {
    Text = "No one is allowed to disturb our time together! Out! GET OUT!"
  },
  AvgDialog_120296_Content_4 = {
    Text = "Well, she has looks, taste, and her gifts have style. Don't act so superior; you've been fluttering yours from dawn to dusk, as if you've grown the thing onto your hand."
  },
  AvgDialog_120296_Content_40 = {
    Text = "The servant rushes up behind you, slamming the door shut against Ho Fong's roaring."
  },
  AvgDialog_120296_Content_41 = {
    Text = "Told you not to bother the Master. He'll get mad at us. Please stop running about, Young Miss!"
  },
  AvgDialog_120296_Content_42 = {
    Text = "Papa... What's wrong with him? Why does he keep calling Lady Xu's name?"
  },
  AvgDialog_120296_Content_43 = {
    Text = "<Shake:She went out this morning... Who is he talking to? His face... it was so scary...>"
  },
  AvgDialog_120296_Content_44 = {
    Text = "Sigh. Sorry, Young Miss, but the Master's business isn't for us servants to meddle in."
  },
  AvgDialog_120296_Content_45 = {
    Text = "Stumbling, you run toward the place you're most familiar with, looking for help."
  },
  AvgDialog_120296_Content_46 = {
    Text = "The Madam's quarters—now Lady Xu's quarters. The very room your mother once lived in."
  },
  AvgDialog_120296_Content_47 = {
    Text = "That door, which had grown faded and dull after your mother's passing, is now freshly gilded. It feels like an entrance to another world; every time it opens, a heavy, intoxicating fragrance spills out."
  },
  AvgDialog_120296_Content_48 = {
    Text = "Haha, hehehe... Sob, wahhhh... I was wrong all along. I was so, SO WRONG!"
  },
  AvgDialog_120296_Content_49 = {
    Text = "Hack them up! Shred them! Pry them open! Pry it all open while it's still steaming! Offer it to HER, and SHE will listen... Then we won't have to suffer anymore!"
  },
  AvgDialog_120296_Content_5 = {
    Text = "Are we speaking of me?"
  },
  AvgDialog_120296_Content_50 = {
    Text = "<Change>Xu... our Savior... our @3!"
  },
  AvgDialog_120296_Content_51 = {
    Text = "An invisible mist fills the room. The concubines are piously holding the fans Lady Xu gifted them on her arrival. They laugh, they weep, until their cries escalate into a bizarre, rhythmic wailing."
  },
  AvgDialog_120296_Content_52 = {
    Text = "You cannot understand a word they are saying. Your ears are filled with a dull humming and the frantic thudding of your own heart. You stumble backward, accidentally knocking against the railing with a sharp clack."
  },
  AvgDialog_120296_Content_53 = {
    Text = "...My. There's a sound."
  },
  AvgDialog_120296_Content_54 = {
    Text = "<Shake:<Red:More sweetmeat for the offering?>>"
  },
  AvgDialog_120296_Content_55 = {
    Text = "Their voices trail off into playful giggles. The wailing vanishes instantly. An inexplicable, bone-chilling cold sweeps over you!"
  },
  AvgDialog_120296_Content_56 = {Text = "RUN!!!"},
  AvgDialog_120296_Content_57 = {
    Text = "It is the terror of staring into the eyes of a predator. It is the primal fear buried in the blood of every living thing since the dawn of time!"
  },
  AvgDialog_120296_Content_58 = {
    Text = "Oh? A mere box of butterfly crackers, and my Little Jasmine comes rushing into my arms with such joy?"
  },
  AvgDialog_120296_Content_59 = {
    Text = "Arms as smooth as white jade catch you before you fall. If you were to look through the gaps in the estate's fence, you would see the famous Inspector Huang of Shencheng personally closing her carriage door."
  },
  AvgDialog_120296_Content_6 = {
    Text = "Ah! My apologies, Madam!"
  },
  AvgDialog_120296_Content_60 = {
    Text = "She presents you a box of pastries. The eye-like patterns layered on the wrapping paper terrify you. You take a sharp breath, summon your courage, and slap it out of her hands."
  },
  AvgDialog_120296_Content_61 = {
    Text = "Who are you?! Why are you in my home! What is happening... Papa, the Aunties, those Uncles... ever since you came, everyone has turned strange!"
  },
  AvgDialog_120296_Content_62 = {
    Text = "Oh dear... such a small thing, and look, my Little Jasmine's already going to cry."
  },
  AvgDialog_120296_Content_63 = {
    Text = "She doesn't seem angry that you ruined the pastries. Instead, she leans down intimately, using her fan to dab the tears of fright from the corners of your eyes."
  },
  AvgDialog_120296_Content_64 = {
    Text = "Little Jasmine... before I arrived, was this place—where they wouldn't even give you water to drink—truly your home?"
  },
  AvgDialog_120296_Content_65 = {
    Text = "Miss! I look away for one second and you... Madam, I am so sorry, it's my fault for not watching her."
  },
  AvgDialog_120296_Content_66 = {
    Text = "Lady Xu ignores the servant. She wraps her arms around you, stroking your back like one might pet a small animal. Her voice is soft, airy."
  },
  AvgDialog_120296_Content_67 = {
    Text = "Little Jasmine, think carefully. Why does this matter? Why does that matter? What does any of it have to do with you?"
  },
  AvgDialog_120296_Content_68 = {
    Text = "So long as you are good and do exactly as I say..."
  },
  AvgDialog_120296_Content_69 = {
    Text = "Everything can be yours. Every person can be your toy."
  },
  AvgDialog_120296_Content_7 = {
    Text = "Tsk. \"Madam\" this, \"Madam\" that... she's just a cortesan fresh out of the sing-song houses. Why be so afraid of her? It's not as if she's going to eat you whole."
  },
  AvgDialog_120296_Content_70 = {
    Text = "She strokes from your spine up to your hair, finally finishing her play with your tresses before letting go. She radiates a sense of pure joy."
  },
  AvgDialog_120296_Content_71 = {
    Text = "There now. Take my Little Jasmine to bed... she needs her rest."
  },
  AvgDialog_120296_Content_72 = {
    Text = "You walk for a long time through the fog. Within the grey miasma, you see a vast expanse of dark water."
  },
  AvgDialog_120296_Content_73 = {
    Text = "Countless slimy, writhing limbs covered in suckers nestle at the border where the water meets the fog. A gentle shadow sits by the water's edge, her back to you."
  },
  AvgDialog_120296_Content_74 = {
    Text = "Mūmā? Is that you?"
  },
  AvgDialog_120296_Content_75 = {
    Text = "<Shake:...Wrong... everything... run...>"
  },
  AvgDialog_120296_Content_76 = {
    Text = "Mūmā, what are you saying? I can't hear you."
  },
  AvgDialog_120296_Content_77 = {
    Text = "You draw closer, only to realize with a jolt that she isn't \"sitting\" by the water. Her lower body has dissolved into a mass of tentacles, merging into the grey depths."
  },
  AvgDialog_120296_Content_78 = {
    Text = "<Shake:Wrong. All of it.>"
  },
  AvgDialog_120296_Content_79 = {
    Text = "<Shake:She isn't... IT isn't...>"
  },
  AvgDialog_120296_Content_8 = {
    Text = "Look at you all, hissing and spitting like ruffled kittens. How truly darling."
  },
  AvgDialog_120296_Content_80 = {
    Text = "The woman turns. Her familiar face is etched with grey lines of tears. She screams at you, her voice a jagged shriek."
  },
  AvgDialog_120296_Content_81 = {
    Text = "<Red:She wears your mother's face.>"
  },
  AvgDialog_120296_Content_82 = {
    Text = "<Change>It isn't IT ISN'T IT ISN'T!!!"
  },
  AvgDialog_120296_Content_83 = {
    Text = "<Red:<Shake:Wrong! It's all wrong!! Nānnān!!! Run!! FAST!! RUN!!!>>"
  },
  AvgDialog_120296_Content_9 = {
    Text = "Don't fret. I am merely a newcomer here. I saw you all chatting so animatedly and simply wished to join in and share a few secrets."
  },
  AvgDialog_120297_Content_1 = {
    Text = "Blood of the Sire"
  },
  AvgDialog_120297_Content_10 = {
    Text = "Sometimes it is the men themselves; sometimes it is their wives. When the wives come, the smile on Lady Xu's face grows noticeably wider. By the time they return for a second visit, a black fan—identical to those held by the concubines—is gripped firmly in their hands."
  },
  AvgDialog_120297_Content_100 = {
    Text = "Yet, the murderous Ho Fong actually begins to calm down."
  },
  AvgDialog_120297_Content_101 = {
    Text = "Do you... truly think so?"
  },
  AvgDialog_120297_Content_102 = {
    Text = "You know well that while I possess divine power, I am tethered to the one who awakened me. I can only do what you bid me to do. How could I possibly deceive you?"
  },
  AvgDialog_120297_Content_103 = {
    Text = "Just as it was in the alleyway, you find yourself unable to speak or move. It is as if this grotesque Goddess is determined to force you to witness this farce."
  },
  AvgDialog_120297_Content_104 = {
    Text = "Ho Fong leaves, his face glowing with delight. Like that day at the Gilded Boudoir, he leaves without casting a single glance back at you."
  },
  AvgDialog_120297_Content_105 = {
    Text = "The moment you can move, you whirl around and lunge at Lady Xu, letting out a animalistic wail. Feet, fists, teeth—you use every pathetic method of attack you know, despite knowing it is futile."
  },
  AvgDialog_120297_Content_106 = {
    Text = "Give them back! Give me back my Mūmā! Give me back my Papa!"
  },
  AvgDialog_120297_Content_107 = {
    Text = "Lady Xu stands perfectly still, fan in hand, allowing you to vent your rage. The amusement in her eyes makes you forget your fear; there is only fury and desperation left."
  },
  AvgDialog_120297_Content_108 = {
    Text = "Everything happened because of you! You aren't a Goddess—you're a monster!"
  },
  AvgDialog_120297_Content_109 = {
    Text = "The woman before you... nods."
  },
  AvgDialog_120297_Content_11 = {
    Text = "Quick. Dawdle longer, and we'll lose her."
  },
  AvgDialog_120297_Content_110 = {
    Text = "That is correct, my Little Jasmine. I am a monster."
  },
  AvgDialog_120297_Content_111 = {
    Text = "But your mother's death had nothing to do with me. Ho Fong murdered countless women, including her, to summon me in exchange for wealth and power."
  },
  AvgDialog_120297_Content_112 = {
    Text = "Just now, he wanted to kill you. You didn't want to die, and so I answered you. Had I abandoned you, you would be dead now."
  },
  AvgDialog_120297_Content_113 = {Text = "..."},
  AvgDialog_120297_Content_114 = {
    Text = "You don't know what to say. Her voice is full of dark interest; her beautiful eyes shimmer with amusement."
  },
  AvgDialog_120297_Content_115 = {
    Text = "So, my Little Jasmine, how will you choose?"
  },
  AvgDialog_120297_Content_116 = {
    Text = "You open your mouth to speak, but the words fail you; you can only stare at her in a dull stupor. A sharp, piercing tinnitus jangles your nerves, drowning out the world. With a lingering brush of her hand against your back, she turns and begins her walk into the courtyard."
  },
  AvgDialog_120297_Content_117 = {
    Text = "Hehe... Soon. Very, very soon... the time will come for you to make the final choice."
  },
  AvgDialog_120297_Content_118 = {Text = "..."},
  AvgDialog_120297_Content_119 = {
    Text = "The events of the day replay in your dreams. You wake up screaming the middle of the night, but the mansion is as silent as a tomb. No one answers. That shrill, familiar voice no longer exists."
  },
  AvgDialog_120297_Content_12 = {
    Text = "The rickshaw ride is jarring and bumpy. Though you manage to stay hidden through the winding streets, you lose the car just as it turns into a small grove of trees."
  },
  AvgDialog_120297_Content_120 = {
    Text = "Hunger gnaws at your insides. You curl into a ball for a long time before finally standing up. Guided by memory, you find the box of shattered butterfly crackers. Standing alone in the moonlight, you wolf down every last crumb in silence."
  },
  AvgDialog_120297_Content_121 = {
    Text = "When sleep takes you again, you return to the grey water's edge. Your mother reaches out with tentacle-shaped arms, beckoning you. Behind her, a massive, shifting tangle of limbs looms in the mist."
  },
  AvgDialog_120297_Content_122 = {
    Text = "Is Mūmā... still here?"
  },
  AvgDialog_120297_Content_123 = {
    Text = "Mūmā will be with you forever."
  },
  AvgDialog_120297_Content_124 = {
    Text = "I will stay by my Little Jasmine's side... always, and forever."
  },
  AvgDialog_120297_Content_125 = {
    Text = [[
Two voices ring out in your ears at once. You don't ask any more questions.
You are just too tired, and so, so afraid.]]
  },
  AvgDialog_120297_Content_126 = {
    Text = "Without hesitation, you throw yourself forward, plunging into that terrifying, viscous, and unimaginably soft embrace."
  },
  AvgDialog_120297_Content_13 = {
    Text = "You are led deeper into the woods. For some reason, your heart begins to pound intensely. You only find a little comfort by clutching the woman's hand tight."
  },
  AvgDialog_120297_Content_14 = {
    Text = "The sky slowly bruises into a deep twilight, and the moon creeps above the treeline unnoticed. Suddenly, the woman gestures for silence, her finger pressed firmly to her lips."
  },
  AvgDialog_120297_Content_15 = {Text = "Shhh—"},
  AvgDialog_120297_Content_16 = {
    Text = "In the distance, Xu appears. The white motorcar speeds away, leaving Master Du standing silently by her side. In the corner, several long shadows are cast upon the dirt."
  },
  AvgDialog_120297_Content_17 = {
    Text = "Master Du, Inspector Huang, the head of the Northern Shipping Syndicate, and those mafia bosses... Oh-ho, Lady Xu truly is something else, isn't she..."
  },
  AvgDialog_120297_Content_18 = {
    Text = "In the distance, the men's faces are flushed with that same unnatural crimson you saw on your father. At first, they mutter in low voices, but the sound quickly escalates into a rapid, frantic chant."
  },
  AvgDialog_120297_Content_19 = {
    Text = "<Shake:She... stay... cannot...>"
  },
  AvgDialog_120297_Content_2 = {
    Text = "Every concubine is becoming more and more like Lady Xu. And your father has not left his room since that day."
  },
  AvgDialog_120297_Content_20 = {
    Text = "<Shake:Kill... only then...>"
  },
  AvgDialog_120297_Content_21 = {
    Text = "<Shake:Kill... Kill... KILL!! SLAY HER—HACK HER TO PIECES!!!>"
  },
  AvgDialog_120297_Content_22 = {
    Text = "<Change>Mine, mine, mine mineMINE! SHE'S MINE!!"
  },
  AvgDialog_120297_Content_23 = {
    Text = "A pale, sickening light stings your eyes. Only then do you realize that every man has a sickle hidden behind his back—and now, they raise them high in a synchronized arc."
  },
  AvgDialog_120297_Content_24 = {
    Text = "Ha—ahahaha! AHAHAHAHAHA!"
  },
  AvgDialog_120297_Content_25 = {
    Text = "As the men close in, Xu erupts into a violent fit of laughter, as if she has just witnessed the funniest joke in the world. She points a finger at their faces, one by one."
  },
  AvgDialog_120297_Content_26 = {
    Text = "The next second, the sharpened sickles swing down from every direction! The dull thud of splitting meat. The wet snap of severed bone and tendon. A severed arm, white as jade, is tossed high into the air."
  },
  AvgDialog_120297_Content_27 = {
    Text = "SQUELCH. CRACK!"
  },
  AvgDialog_120297_Content_28 = {
    Text = "Mmmph! Mmmph-mmmph!!"
  },
  AvgDialog_120297_Content_29 = {
    Text = "You are pulled into a suffocating embrace. The woman's hand clamps over your mouth, forcing your panicked scream back down your throat."
  },
  AvgDialog_120297_Content_3 = {
    Text = "Mother no longer visits your dreams. Instead, you dream of endless black fans, and beneath every one of them is Lady Xu's face. You dream of Father being devoured by monsters, only to wake in a cold, drenching sweat."
  },
  AvgDialog_120297_Content_30 = {
    Text = "<Change>Skull. Neck. Chest. Arms. Belly..."
  },
  AvgDialog_120297_Content_31 = {
    Text = "<Shake:From the skull, from the neck, from the chest, from the arms, from the belly...> Something craws out."
  },
  AvgDialog_120297_Content_32 = {
    Text = "<Change>Out of the skull. Out of the neck. Out of the chest cavity, out, out, bursting forth..."
  },
  AvgDialog_120297_Content_33 = {
    Text = "My dear lords..."
  },
  AvgDialog_120297_Content_34 = {
    Text = "Her voice is tender. Coquettish. Sweet as honey."
  },
  AvgDialog_120297_Content_35 = {
    Text = "Though she is far away, the voice coils like mist around your ears, slithering into your mind."
  },
  AvgDialog_120297_Content_36 = {
    Text = "The mist, crimson as blood, darkens in color. One by one, many \"Lady Xus\" begin to crawl out from the piles of butchered meat. Their jade-white arms are slick with a flowing, black sludge as they reach upward."
  },
  AvgDialog_120297_Content_37 = {
    Text = "Oh, it hurts so, so much... won't you give me a kiss?"
  },
  AvgDialog_120297_Content_38 = {
    Text = "<Change>It hurts so much... Give me a kiss..."
  },
  AvgDialog_120297_Content_39 = {
    Text = "<Change>It hurts @3. Give me a @4!"
  },
  AvgDialog_120297_Content_4 = {
    Text = "Miss, stop this tantrum. Lady Xu is so good to you; every day she brings you new treats and toys."
  },
  AvgDialog_120297_Content_40 = {
    Text = "<Change>IT HURTS SO MUCH. GIVE ME A KISS!"
  },
  AvgDialog_120297_Content_41 = {
    Text = "The Xus... monsters in her image. Their lower bodies are fused into the mangled heaps of meat, their faces smeared with a dark, viscous sludge that leaves only the faint outline of their lips visible."
  },
  AvgDialog_120297_Content_42 = {
    Text = "Upon each \"Lady Xu's\" face, a dozen lush, beautiful, petal-like mouths bloom, latching onto the men who stand there, giggling in mindless ecstasy."
  },
  AvgDialog_120297_Content_43 = {
    Text = "<Change>Crack... Snap... CRUNCH—"
  },
  AvgDialog_120297_Content_44 = {
    Text = "The sound of skulls being compressed. The sound of skulls shattering."
  },
  AvgDialog_120297_Content_45 = {
    Text = "<Change>Schlurp... Squelch... Gulp—"
  },
  AvgDialog_120297_Content_46 = {
    Text = "The sound of suction. The sound of feeding."
  },
  AvgDialog_120297_Content_47 = {
    Text = "You watch as their heads burst, only to be knit back together, pristine and whole. The \"Xus\" let out sighs of deep satisfaction, then begin to merge back into a single form amidst sated grunts."
  },
  AvgDialog_120297_Content_48 = {
    Text = "Master Du, Inspector Huang, the shipping tycoon..."
  },
  AvgDialog_120297_Content_49 = {
    Text = "They rise in eerie silence. As if nothing had ever happened, they disperse with hollow, vacant expressions. Lady Xu is already gone, vanished into the air."
  },
  AvgDialog_120297_Content_5 = {
    Text = "The woman sighs, using her handkerchief to dab the cold sweat from your brow."
  },
  AvgDialog_120297_Content_50 = {
    Text = "The hand that held you finally lets go. In the suffocating silence that follows, your tears fall uncontrollably. You spin around, and your pupils contract in a violent tremor."
  },
  AvgDialog_120297_Content_51 = {Text = "Oh dear..."},
  AvgDialog_120297_Content_52 = {
    Text = "I have been wondering just how to be... <Italic:perfectly honest> with you, my Little Jasmine."
  },
  AvgDialog_120297_Content_53 = {
    Text = "Your world shrinks until there is nothing but the woman before you. A white-hot spark of pain flares within your overtaxed brain."
  },
  AvgDialog_120297_Content_54 = {
    Text = "What did she look like? That woman with the shrill voice?"
  },
  AvgDialog_120297_Content_55 = {
    Text = "All the servants in your room had been dismissed when your mother died."
  },
  AvgDialog_120297_Content_56 = {
    Text = "No one cared if you lived or died. You never once saw her face—so why did everyone, including you, find her presence so natural?"
  },
  AvgDialog_120297_Content_57 = {
    Text = "I grew fond of that skin... I loved the scent of jasmine she carried. From the very beginning, I wondered... what would her \"Little Jasmine\"—my Little Jasmine—look like?"
  },
  AvgDialog_120297_Content_58 = {
    Text = "Aww, I simply couldn't help myself. I came to see you very, very early on."
  },
  AvgDialog_120297_Content_59 = {
    Text = "You run away. She doesn't move to stop you. She merely watches from behind her fan with a playful smile, as if she's watching a terrified kitten scramble to escape."
  },
  AvgDialog_120297_Content_6 = {
    Text = "Miss, if you're truly this frightened, I have an idea."
  },
  AvgDialog_120297_Content_60 = {
    Text = "Papa! Xu is a monster, she—"
  },
  AvgDialog_120297_Content_61 = {
    Text = "You don't remember how long you ran, or how many wrong turns you took. Ignoring the stunned looks of the doormen, you burst into your father's quarters, slamming the door and clutching at his sleeve."
  },
  AvgDialog_120297_Content_62 = {
    Text = "But the moment Xu's name leaves your lips, a heavy, stinging blow sends you reeling."
  },
  AvgDialog_120297_Content_63 = {
    Text = "I told you. You will call her <Red:\"Mother.\">"
  },
  AvgDialog_120297_Content_64 = {
    Text = "Your father's face is terrifyingly sober and dark. The madness of the past weeks has vanished. He grabs you by the collar and rips you away from his side."
  },
  AvgDialog_120297_Content_65 = {
    Text = "No, Papa, she's changed into everyone around me! She's with all those men, and she—"
  },
  AvgDialog_120297_Content_66 = {Text = "Enough!"},
  AvgDialog_120297_Content_67 = {
    Text = "I only kept you in this house because she took a liking to you. But you're just like your short-lived mother, utterly ungrateful."
  },
  AvgDialog_120297_Content_68 = {
    Text = "You're a mess, you're babbling nonsense, and you dare speak ill of your Mother! Go to the hall and kneel. You aren't to move until the hour of the Rooster!"
  },
  AvgDialog_120297_Content_69 = {
    Text = "She isn't my mother! She's a man-eating monster!"
  },
  AvgDialog_120297_Content_7 = {
    Text = "If you fear Lady Xu so much, why not follow her? See what she does all day. If she really is a monster, we'll tell the Master together and make her leave this house. How about that?"
  },
  AvgDialog_120297_Content_70 = {
    Text = "You scream with every ounce of your strength. The room falls into a heavy silence. Then, you hear it..."
  },
  AvgDialog_120297_Content_71 = {
    Text = "<Red:Your father's low, cold chuckling.>"
  },
  AvgDialog_120297_Content_72 = {
    Text = "<Shake:A monster?>"
  },
  AvgDialog_120297_Content_73 = {
    Text = "Xu is a <Red:Goddess> I summoned through countless sacrifices! I hand-picked all those women and sliced them open! I poured every drop of my soul into bringing her here!"
  },
  AvgDialog_120297_Content_74 = {
    Text = "I tried so many times, but those common women weren't worthy of her grace. Do you think my heart didn't ache? It pained me to part with your mother."
  },
  AvgDialog_120297_Content_75 = {
    Text = "The realization hits you like a thunderbolt. Your mind is drowned out by a piercing ring in your head; you cannot even begin to process his words."
  },
  AvgDialog_120297_Content_76 = {
    Text = "<Shake:You should feel honored. Her flesh became the vessel for the Goddess to walk among us.>"
  },
  AvgDialog_120297_Content_77 = {
    Text = "His voice is bone-chilling. You realize with horror that he has moved, his shadow blocking the door, looming over you as he draws closer."
  },
  AvgDialog_120297_Content_78 = {
    Text = "Since you know everything now, there is no place for you in this house. I won't have you running out there with your loose tongue."
  },
  AvgDialog_120297_Content_79 = {
    Text = "Before you can scream, your father's hands clamp around your throat. Your vision begins to swim in a sea of blood-red."
  },
  AvgDialog_120297_Content_8 = {
    Text = "Make Lady Xu leave?"
  },
  AvgDialog_120297_Content_80 = {
    Text = "The <Red:Goddess> has descended. From now on, she will <Red:forever> belong to me. Fame, fortune... they mean nothing now. As long as the <Red:Goddess> is with me, every sacrifice was worth it!"
  },
  AvgDialog_120297_Content_81 = {
    Text = "<Shake:Mūmā, help...>"
  },
  AvgDialog_120297_Content_82 = {
    Text = "I... I don't wanna die. I want to live. Mūmā..."
  },
  AvgDialog_120297_Content_83 = {
    Text = "<Change><Shake:I don't wanna die it hurts it hurts IT HURTS Mūmā save me SAVE ME SAVE ME HELP @4!!>"
  },
  AvgDialog_120297_Content_84 = {
    Text = "Anyone... please, save me..."
  },
  AvgDialog_120297_Content_85 = {
    Text = "No one answers your frantic, voiceless prayer."
  },
  AvgDialog_120297_Content_86 = {
    Text = "Confusion. Suffocation. Agony. Stillness. And then... that familiar, metallic, sickly-sweet scent of magnolia."
  },
  AvgDialog_120297_Content_87 = {
    Text = "<Red:<Shake:Creeeeak—>>"
  },
  AvgDialog_120297_Content_88 = {
    Text = "Through the haze of your fading consciousness, a black tentacle erupts through the door. With a monstrous force, it slams Ho Fong straight into the bedframe."
  },
  AvgDialog_120297_Content_89 = {
    Text = "Oh, my dear... how can you be so cruel to a mere child?"
  },
  AvgDialog_120297_Content_9 = {
    Text = "The honk of a motorcar horn sounds from the front gate. Every day, a different face waits before the Ho Mansion—distinguished men, the very elites your father tried to flatter."
  },
  AvgDialog_120297_Content_90 = {
    Text = "A pair of tender arms catches you. Air finally floods back into your collapsing lungs. Lady Xu tilts the edge of her fan slightly, and an unseen force hoists Ho Fong back to his feet."
  },
  AvgDialog_120297_Content_91 = {
    Text = "She simply saw a few things she shouldn't have. If I do not wish for her to remember, then naturally, she will forget."
  },
  AvgDialog_120297_Content_92 = {
    Text = "Her tone is as playful and effortless as ever; even the hand resting on your head feels light, almost affectionate."
  },
  AvgDialog_120297_Content_93 = {
    Text = "From outside the door, a servant's voice calls out."
  },
  AvgDialog_120297_Content_94 = {
    Text = "Master, several gentlemen are waiting for you in the front hall."
  },
  AvgDialog_120297_Content_95 = {
    Text = "Ho Fong's expression twists violently—even more hideous than when he was trying to strangle you."
  },
  AvgDialog_120297_Content_96 = {
    Text = "My darling, why must you start this again? I told you, worldly things mean nothing to me now! Only you—you are the only thing that must be mine, and mine alone!"
  },
  AvgDialog_120297_Content_97 = {
    Text = "Since I was awakened by you, my beloved, others are meaningless to me. However, I still remember the great ambitions you harbor, and I wish to lend you what little strength I have."
  },
  AvgDialog_120297_Content_98 = {
    Text = "I only do these things so that we might have more to lean upon... while we dwell together in this mortal realm."
  },
  AvgDialog_120297_Content_99 = {
    Text = "There isn't a shred of sincerity in her eyes. Even a child like you can see it; especially since she just finished slamming this \"beloved\" of hers against the furniture."
  },
  AvgDialog_120298_Content_1 = {
    Text = "The Dreamless One"
  },
  AvgDialog_120298_Content_10 = {
    Text = "Whenever I speak to them, your scent crawls into my nostrils. The mere thought of you being intimate with other men... it makes me want to go MAD!"
  },
  AvgDialog_120298_Content_11 = {
    Text = "I told you, I only need you to stay by my side! Why won't you belong to me alone? Why are you still seducing others!"
  },
  AvgDialog_120298_Content_12 = {
    Text = "Never before have you seen such a look of utter helplessness on Lady Xu's face. She seems to be searching frantically for an escape, her eyes darting about until they land, in shock, upon you—hiding behind the window, unnoticed by Ho Fong."
  },
  AvgDialog_120298_Content_13 = {
    Text = "Instinctively, you duck below the sill. Ho Fong notices her gaze and glances back briefly, but his focus returns to her almost instantly."
  },
  AvgDialog_120298_Content_14 = {
    Text = "Still thinking of running? Give it up. I am your <Red:Linker>. Your power is tethered to mine; your divinity is useless against me."
  },
  AvgDialog_120298_Content_15 = {
    Text = "<Red:<Shake:I understand it all now. Only by killing you... only by slaying you... can we truly be together forever.>>"
  },
  AvgDialog_120298_Content_16 = {
    Text = "With hitched breath, you rush through the manor, cabin after cabin, trying to find someone to stop him."
  },
  AvgDialog_120298_Content_17 = {
    Text = "No. No. No one is here. The vast Ho Mansion is empty. Even the doormen have vanished."
  },
  AvgDialog_120298_Content_18 = {
    Text = "A heavy lock has been dropped onto the main gate, and outside, a grey, bottomless mist swallows the world."
  },
  AvgDialog_120298_Content_19 = {
    Text = "If this keeps up, Lady Xu is going to end up just like Mūmā..."
  },
  AvgDialog_120298_Content_2 = {
    Text = "The following dawn has not yet broken when a hysterical roar erupts from the courtyard."
  },
  AvgDialog_120298_Content_20 = {
    Text = "<Shake:You should hide. You should stay hidden until it's all over.>"
  },
  AvgDialog_120298_Content_21 = {
    Text = "But there is nowhere left to go. You find the object you are looking for, hide it behind your back, and walk once more toward the room that once belonged to your mother."
  },
  AvgDialog_120298_Content_22 = {
    Text = "<Red:<Shake:My wife... my darling... you can only be mine.>>"
  },
  AvgDialog_120298_Content_23 = {
    Text = "The moment he raise the gleaming sickle, your eyes meet Lady Xu's. Her eyes light up for a fraction of a second, flashing with a look of desperate pleading."
  },
  AvgDialog_120298_Content_24 = {
    Text = "But then, she gives a tiny shake of her head—"
  },
  AvgDialog_120298_Content_25 = {Text = "<Red:Run.>"},
  AvgDialog_120298_Content_26 = {
    Text = "Those beautiful eyes close. Their mistress offers her neck to the blade."
  },
  AvgDialog_120298_Content_27 = {Text = "..."},
  AvgDialog_120298_Content_28 = {Text = "ARGH!!"},
  AvgDialog_120298_Content_29 = {
    Text = "You little brat! How dare you—"
  },
  AvgDialog_120298_Content_3 = {
    Text = "It is a sound of twisted, venomous malice. Before you can even think, a massive wave of dread sends you bolting toward the source of the noise."
  },
  AvgDialog_120298_Content_30 = {
    Text = "The sickle hits the floor with a clang. Ho Fong clutches his lower back in agony, where the small knife you found is buried deep in his flesh."
  },
  AvgDialog_120298_Content_31 = {
    Text = "In a fit of fury, Ho Fong turns to seize you, but then—suddenly—You hear giggling. Not just one voice, but hundreds, swarming toward the room in a dense, suffocating wave."
  },
  AvgDialog_120298_Content_32 = {
    Text = "The giggles erupt into a roar of uncontrollable laughter. Behind Ho Fong, Lady Xu is doubled over, laughing so hard that tears stream down her face."
  },
  AvgDialog_120298_Content_33 = {
    Text = "AHAHA! AHAHAHAHAHAHA! Little Jasmine... my dearest, most beloved Little Jasmine. You truly didn't disappoint me—you are every bit as interesting as I imagined!"
  },
  AvgDialog_120298_Content_34 = {
    Text = "Women dressed in yellow and black qipaos file into the room, their folding fans masking their noses and lips. Every single one of them—every last one—possesses a pair of very, very beautiful eyes."
  },
  AvgDialog_120298_Content_35 = {
    Text = "Ho Fong is paralyzed with terror. Before he can scream, a cold, soft embrace envelops you."
  },
  AvgDialog_120298_Content_36 = {
    Text = "<Red:Disgusting thing. You will not foul my Little Jasmine's eyes.>"
  },
  AvgDialog_120298_Content_37 = {
    Text = "<Shake:Master...>"
  },
  AvgDialog_120298_Content_38 = {
    Text = "<Shake:Darling...>"
  },
  AvgDialog_120298_Content_39 = {
    Text = "What are you doing? Have you gone mad? Get out! All of you, GET OUT!"
  },
  AvgDialog_120298_Content_4 = {
    Text = "In the bedroom, Lady Xu is cornered by Ho Fong. His eyes bloodshot and his hair a tangled mess; he looks as though he hasn't slept for a single second."
  },
  AvgDialog_120298_Content_40 = {
    Text = "The concubines slowly lower their fans. Beneath every single fan is the exact same face."
  },
  AvgDialog_120298_Content_41 = {
    Text = "Darling, why did you turn us into sacrifices?"
  },
  AvgDialog_120298_Content_42 = {
    Text = "Darling, why did you hack off our limbs?"
  },
  AvgDialog_120298_Content_43 = {
    Text = "Countless \"Lady Xus\" ignore Ho Fong's trembling rage. They giggle, surrounding him in a tightening knot of black fans and sickles."
  },
  AvgDialog_120298_Content_44 = {
    Text = "<Change>Are we beautiful enough now?"
  },
  AvgDialog_120298_Content_45 = {
    Text = "<Change>Can we stay with you... <RedItalic:forever?>"
  },
  AvgDialog_120298_Content_46 = {
    Text = "A gargantuan shadow erupts from behind Xu, soaring toward the ceiling. One, two, three... countless lips lined with dragon-like teeth burst from bloated, swelling skin, dripping with saliva, hungry to consume."
  },
  AvgDialog_120298_Content_47 = {
    Text = "Feather-like tentacles expand to fill the entire Ho Mansion. All light is snuffed out; all noise is suppressed."
  },
  AvgDialog_120298_Content_48 = {
    Text = "The mist clouds your vision. You only feel the strange fragrance of Lady Xu, and hear the eerie, slow, satisfied sounds of a feast."
  },
  AvgDialog_120298_Content_49 = {Text = "..."},
  AvgDialog_120298_Content_5 = {
    Text = "There is one thing my stupid daughter was right about... <Shake:I smell it.>"
  },
  AvgDialog_120298_Content_50 = {
    Text = "When the rhythmic sucking finally stops, a silent Ho Fong stands up. He walks out of the house and joins a group of men who are waiting with equal silence."
  },
  AvgDialog_120298_Content_51 = {
    Text = "The Inspector, the President, the Chairman... their wives stand beside them. The rising sun is dazzling. You see the same mysterious, identical smile on every woman's face."
  },
  AvgDialog_120298_Content_52 = {Text = "..."},
  AvgDialog_120298_Content_53 = {
    Text = "Ho Fong said your power was tied to his. Now that he's... like this, will you disappear?"
  },
  AvgDialog_120298_Content_54 = {
    Text = "That is the first thing my Little Jasmine asks? Truly... I am so moved."
  },
  AvgDialog_120298_Content_55 = {
    Text = "Her fingers trace the space between your brows, coming to rest at the tip of your nose."
  },
  AvgDialog_120298_Content_56 = {
    Text = "Perhaps I will... or perhaps I won't. But tell me... would you like to be my new Master instead?"
  },
  AvgDialog_120298_Content_57 = {
    Text = "Lady Xu makes a delicate plucking motion in the air, pulling out a silk handkerchief as thin as a cicada's wing. A brush appears, dipped in ink, and rests before you."
  },
  AvgDialog_120298_Content_58 = {
    Text = "I shall give you everything Ho Fong failed to obtain. I shall give you the very best of this world."
  },
  AvgDialog_120298_Content_59 = {
    Text = "In a city caught between old traditions and the \"New Culture Movement,\" your mother had made sure you were taught to read and write—a rare privilege for a daughter of your station."
  },
  AvgDialog_120298_Content_6 = {
    Text = "<Shake:<Red:Those men...>>"
  },
  AvgDialog_120298_Content_60 = {
    Text = "Lady Xu takes your hand, waiting for you to begin. Name... what is your name again?"
  },
  AvgDialog_120298_Content_61 = {
    Text = "A bronze mirror, splattered with fresh crimson droplets, reflects the delicate, young features of a girl—looking like a cluster of pale, fragile jasmine."
  },
  AvgDialog_120298_Content_62 = {
    Text = "You blink blankly. The little girl in the reflection blinks back. You remember now. Across the silk handkerchief, your childish, unpracticed handwriting appears. Your name is—"
  },
  AvgDialog_120298_Content_63 = {
    Text = "Also Ho Fong, but written with a different, floral character."
  },
  AvgDialog_120298_Content_64 = {Text = "..."},
  AvgDialog_120298_Content_65 = {
    Text = "So... the leader of that underground cult that appeared in Shencheng later on... was a little girl no older than Jenkin?!"
  },
  AvgDialog_120298_Content_66 = {
    Text = "Your head is throbbing with the aftereffects of the dream, and the sudden, silent appearance of the woman upon your waking gives you a violent start."
  },
  AvgDialog_120298_Content_67 = {
    Text = "The Mythag dorms really need better security, you think, as you begin to wonder if anything could possibly protect you from this woman—a woman who doesn't even spare children."
  },
  AvgDialog_120298_Content_68 = {
    Text = "...According to the records, there is a legend in the Far East of a primal deity. They call Her the <Red:\"The Obsidian Matriarch of Thousand Fans.\"> She delights in toying with the humans and feeds upon the brain-matter of those who harbor lust for Her."
  },
  AvgDialog_120298_Content_69 = {
    Text = "Even though you can only see her eyes, it is painfully obvious that the woman before you is enjoying herself. She leans lazily on her hand; you suspect she could look at a doormat with that same smoldering gaze."
  },
  AvgDialog_120298_Content_7 = {
    Text = "You thought you could hide it from me? Don't forget, I am the one who summoned you with my own wife's <Red:corpse>. How could I ever mistake that scent?"
  },
  AvgDialog_120298_Content_70 = {
    Text = "Oh, you know me so well... truly, I am overjoyed."
  },
  AvgDialog_120298_Content_71 = {
    Text = "That foolish man... he found an ancient scroll and sought to summon me to perform his petty deceptions. He murdered countless people. In the end, he didn't even spare the devoted wife who loved him with all her heart."
  },
  AvgDialog_120298_Content_72 = {
    Text = "Originally, it was merely the wife's resentment that I found amusing. I thought to taste her murderer's brain for her."
  },
  AvgDialog_120298_Content_73 = {
    Text = "But Shencheng in those days... it was filled with a towering stench of rot and malice. It truly made me... loath to leave."
  },
  AvgDialog_120298_Content_74 = {
    Text = "...You don't actually need a Linker, do you?"
  },
  AvgDialog_120298_Content_75 = {
    Text = "I've read the Silver Core storage records. You are perfectly capable of completing an Awakening Ritual on your own. Staying sane and alert without a Linker is a trivial matter for you."
  },
  AvgDialog_120298_Content_76 = {
    Text = "So why did you want to link with the little Ho Fong back in Shencheng? What was your goal?"
  },
  AvgDialog_120298_Content_77 = {
    Text = "Xu remains silent. A wisp of mist coils around you, drawing away the throbbing ache in your head. From behind her fan, she winks at you."
  },
  AvgDialog_120298_Content_78 = {
    Text = "I thought that in this world, adults were all the same, while every child was unique in their own way."
  },
  AvgDialog_120298_Content_79 = {
    Text = "I nourished her with my mist. I watered her with power and desire. I loved her. Why do you treat me as if I have committed a crime?"
  },
  AvgDialog_120298_Content_8 = {
    Text = "If you hadn't slept with them, why would they be reeking of <Red:your fragrance?>"
  },
  AvgDialog_120298_Content_80 = {
    Text = "That is not love."
  },
  AvgDialog_120298_Content_81 = {Text = "..."},
  AvgDialog_120298_Content_82 = {
    Text = "Hehe. True, I do not understand what humans call \"love.\" Food, toys, the power to turn lies into truth... I offer the finest gifts this world has to offer."
  },
  AvgDialog_120298_Content_83 = {
    Text = "And of course... I shall receive the payment I desire in return. And on the day you find yourself in need, my Little Jasmine... how will <Italic:you> choose?"
  },
  AvgDialog_120298_Content_84 = {
    Text = "My Dreamless Land is waiting for you. Always, always waiting."
  },
  AvgDialog_120298_Content_85 = {
    Text = "Amidst a soft, coquettish giggle, the mist spreads—and a second later, nothing remains in the dorm room but the lingering scent of white magnolias."
  },
  AvgDialog_120298_Content_9 = {
    Text = "He laughs suddenly, a neurotic, high-pitched sound. He lunges forward, seizing Xu's wrist—the one holding her fan."
  },
  AvgDialog_120313_Content_1 = {
    Text = [[
Meanwhile
Beyond the Black Sun]]
  },
  AvgDialog_120313_Content_10 = {
    Text = "Beyond the billions of worlds shimmering like stars, that familiar figure struggles to break through the tumultuous currents, running toward you step by step."
  },
  AvgDialog_120313_Content_11 = {Text = "Ramona!!!"},
  AvgDialog_120313_Content_12 = {
    Text = "You can see her silhouette, her face, and her eyes shining with joy, no longer a false illusion, no longer just a vague voice."
  },
  AvgDialog_120313_Content_13 = {
    Text = "The energy waves of the tunnel connection roar past, stirring your hair. Finally, your fingertips touch, and then you embrace tightly."
  },
  AvgDialog_120313_Content_14 = {
    Text = "The longing from another world transforms into a white halo, swirling and flowing through your soul."
  },
  AvgDialog_120313_Content_15 = {
    Text = "<Shake:<color=#DEDEDE>Finally... I've found you.</color>>"
  },
  AvgDialog_120313_Content_16 = {
    Text = "Your foreheads touch, her hands lovingly wrap around your back, her voice trembling with joy as she cries."
  },
  AvgDialog_120313_Content_17 = {
    Text = "All the fatigue, loneliness, and pain dissipate at this moment. You know your soul has returned to its true home."
  },
  AvgDialog_120313_Content_18 = {
    Text = "It's dangerous to travel between dimensions, right? Did you get hurt?"
  },
  AvgDialog_120313_Content_19 = {
    Text = "You repeatedly check the soul before you that has trekked so far, noting only her somewhat thinner frame. Ramona shakes her head, gently stroking your face."
  },
  AvgDialog_120313_Content_2 = {
    Text = "Descent. Destruction. Rebirth... Confrontation. Combat. Perseverance..."
  },
  AvgDialog_120313_Content_20 = {
    Text = "What about you? You've been alone in a strange world for so long; it must have been really tough for you."
  },
  AvgDialog_120313_Content_21 = {
    Text = "A pang of emotion hits your nose, and you shake your head as well. In the gaze exchanged between you, amidst the tears welling up in your eyes, you both smile at the same time."
  },
  AvgDialog_120313_Content_22 = {
    Text = "Pfft... What are you smiling at? You look stupid."
  },
  AvgDialog_120313_Content_23 = {
    Text = "Aren't you smiling too..."
  },
  AvgDialog_120313_Content_24 = {
    Text = "In immense happiness, you instinctively take her hand, eager to go home."
  },
  AvgDialog_120313_Content_25 = {Text = "!!!"},
  AvgDialog_120313_Content_26 = {
    Text = "Suddenly, you see her pupils dilate sharply, and in an instant, she lunges at you, shoving you aside with immense force."
  },
  AvgDialog_120313_Content_27 = {
    Text = "As you're thrown backward, you see a new dimensional rift has opened where you once stood. Another colossal eye turns and looks at Ramona, who is left behind."
  },
  AvgDialog_120313_Content_28 = {
    Text = "In an instant, the pitch-black slime engulfs her."
  },
  AvgDialog_120313_Content_29 = {
    Text = "<Shake:<Big:NO!!!>>"
  },
  AvgDialog_120313_Content_3 = {
    Text = "Under the immense pressure of that Supreme Will, everything feels so familiar."
  },
  AvgDialog_120313_Content_4 = {
    Text = "One by one, the giant, pale eyes in the alien dimension dissipate with a roar. Your spirit gradually nears exhaustion. The only thing sustaining you now is the vibrant red rose in your hand."
  },
  AvgDialog_120313_Content_5 = {
    Text = "Huff... I can't fall. They are still waiting for me..."
  },
  AvgDialog_120313_Content_6 = {
    Text = "In a daze, your heart suddenly starts to race, and you turn, following this instinct."
  },
  AvgDialog_120313_Content_7 = {
    Text = "Like a meteor streaking past, or ice crystals condensing, a beam-like tunnel extends toward you, accompanied by a strange, ethereal sound."
  },
  AvgDialog_120313_Content_8 = {
    Text = "A voice that has echoed in your memory a thousand times crosses the distant dimensional space behind you, resonating in your mind through the link of your spiritual tendrils."
  },
  AvgDialog_120313_Content_9 = {
    Text = "<Yellow:%player%>!!!"
  },
  AvgDialog_121232_Content_1 = {
    Text = "The glory of my homeland is shimmering before my eyes, Lord Goliath, I'll leave the rest up to you..."
  },
  AvgDialog_121232_Content_2 = {
    Text = "The rushing divine power you wield... reminds me of that mad woman."
  },
  AvgDialog_121232_Content_3 = {
    Text = "Alright, little one. Get ready to witness the power of the Philistine. It surpasses any divine blessing!"
  },
  AvgDialog_121369_Content_1 = {
    Text = "In the hollow hall, only the echoes of your and Murphy's footsteps remained."
  },
  AvgDialog_121369_Content_10 = {
    Text = "Before you could process the command, icy tentacles snapped around your calves. The crushing pressure forced you immediately down onto the cold stone floor."
  },
  AvgDialog_121369_Content_11 = {
    Text = "You tried to resist, but a paralysis toxin seeped into your nerves, rendering you powerless."
  },
  AvgDialog_121369_Content_12 = {
    Text = "Murphy, what are you doing?!"
  },
  AvgDialog_121369_Content_13 = {
    Text = "I don't know why, I just feel really angry."
  },
  AvgDialog_121369_Content_14 = {
    Text = "A fire burns in my heart, and seeing you just makes it burn hotter."
  },
  AvgDialog_121369_Content_15 = {
    Text = "<Italic:(Calm down, I must calm down... Do not do anything that would undermine my dignity as the Divine Mother...)>"
  },
  AvgDialog_121369_Content_16 = {
    Text = "So... what exactly do you want me to kneel for?"
  },
  AvgDialog_121369_Content_17 = {
    Text = "Just kneel down, don't ask!"
  },
  AvgDialog_121369_Content_18 = {
    Text = "Murphy's tone was furious. The octopus tentacles tapped anxiously against your leg. It seemed that even she was struggling for control."
  },
  AvgDialog_121369_Content_19 = {
    Text = "You resisted the grip of the paralysis toxin and lifted your head, reaching out to gently touch her flushed cheek."
  },
  AvgDialog_121369_Content_2 = {
    Text = "Since you entered, you had refused to say a word."
  },
  AvgDialog_121369_Content_20 = {
    Text = "Murphy, are you... being affected by the power of the Holy River?"
  },
  AvgDialog_121369_Content_21 = {
    Text = "Nonsense! As the mother of a god, how could I be affected by such stupid—"
  },
  AvgDialog_121369_Content_22 = {
    Text = "The blue-ringed tentacles crawled up your spine, leaving a tingling sensation along the way."
  },
  AvgDialog_121369_Content_23 = {
    Text = "Before dawn, you must stay here properly."
  },
  AvgDialog_121369_Content_24 = {
    Text = "Don't move!"
  },
  AvgDialog_121369_Content_25 = {
    Text = "Yet, you felt the bonds of the tentacles relax slightly, as if a cloud was supporting you. When you tried to break free, however, the restraint held firm, not allowing you to move an inch."
  },
  AvgDialog_121369_Content_26 = {
    Text = "Be thankful. You will gain the honor of welcoming the dawn with me."
  },
  AvgDialog_121369_Content_27 = {
    Text = "As a return..."
  },
  AvgDialog_121369_Content_28 = {
    Text = "Her breathing lingered in your ear. Then, a gentle, soft kiss landed on your forehead."
  },
  AvgDialog_121369_Content_29 = {
    Text = "You will also receive the blessings of the Divine Mother."
  },
  AvgDialog_121369_Content_3 = {
    Text = "What happened, Murphy?"
  },
  AvgDialog_121369_Content_4 = {
    Text = "Murphy did not respond, walking straight towards the top of the steps where the throne stood."
  },
  AvgDialog_121369_Content_5 = {
    Text = "You tread carefully until she finally turned, settling onto the Throne. Her slightly angry gaze pierced you."
  },
  AvgDialog_121369_Content_6 = {
    Text = "Who allowed you to stand next to me? Stand lower. Do not look down on me."
  },
  AvgDialog_121369_Content_7 = {
    Text = "You felt confusion, but still stepped back two paces, aligning your gaze with the young woman on the throne."
  },
  AvgDialog_121369_Content_8 = {Text = "Kneel."},
  AvgDialog_121369_Content_9 = {Text = "Huh?"},
  AvgDialog_121741_Content_1 = {
    Text = "Vast, decaying, empty... This illusion above the \"Veil\" I've been trying to maintain with absurd fantasies..."
  },
  AvgDialog_121741_Content_2 = {
    Text = "How foolish and ridiculous I was... to have indulged in this <Italic:Paradise>..."
  },
  AvgDialog_121741_Content_3 = {
    Text = "%player%, help me end this dream once and for all."
  },
  AvgDialog_121741_Content_4 = {
    Text = "Help me reclaim... my fate."
  },
  AvgDialog_121742_Content_1 = {
    Text = "Heavy chains tremble. The monster behind the veil looks around the entire ship, letting out a desperate wail."
  },
  AvgDialog_121742_Content_10 = {
    Text = "Farewell, my fragile and helpless <Italic:Yesterday>...!"
  },
  AvgDialog_121742_Content_2 = {
    Text = "I understand... I fully understand... your attachment, what you can't bear to give up..."
  },
  AvgDialog_121742_Content_3 = {
    Text = "But I have made up my mind."
  },
  AvgDialog_121742_Content_4 = {
    Text = "Murphy stares back at It, and for a moment, utterly resolute, she shows you a gentle smile."
  },
  AvgDialog_121742_Content_5 = {
    Text = "Please take a look... at the heart inside my chest..."
  },
  AvgDialog_121742_Content_6 = {
    Text = "Even today, it still throbs with life."
  },
  AvgDialog_121742_Content_7 = {
    Text = "Like during the Ritual of Navigation, Murphy slices her chest open again."
  },
  AvgDialog_121742_Content_8 = {
    Text = "This is to leave here. To meet you again in Mythag."
  },
  AvgDialog_121742_Content_9 = {
    Text = "The spiritual blood flows down from Murphy's chest, with faint silver threads entangled, persistently trying to tear open the veil above the firmament."
  },
  AvgDialog_121743_Content_1 = {
    Text = "You don't know how long you've been fighting. Your brain is spinning, and your arms are heavy, while the pale, slender giant relentlessly swings its arms at you, infinitely regenerating as they are broken."
  },
  AvgDialog_121743_Content_10 = {
    Text = [[
William's promise feels like an invisible shield rising before you. 
The trust forged over the years allows your failing strength to surge from deep within your being.]]
  },
  AvgDialog_121743_Content_11 = {
    Text = "It's a promise, then. We will go back together."
  },
  AvgDialog_121743_Content_12 = {
    Text = "May the Silver Key light our path."
  },
  AvgDialog_121743_Content_13 = {
    Text = "May the Silver Key guide us."
  },
  AvgDialog_121743_Content_2 = {
    Text = "Sweat slides down your forehead, blurring your vision. You can't even lift your hand to wipe it away."
  },
  AvgDialog_121743_Content_3 = {Text = "Shit..."},
  AvgDialog_121743_Content_4 = {
    Text = "%player%. I've got you."
  },
  AvgDialog_121743_Content_5 = {
    Text = [[
A black-and-red cloak flutters before your eyes. 
A precise mechanical arm shields you from the relentless assault of pale bones.]]
  },
  AvgDialog_121743_Content_6 = {
    Text = "The slender limbs furiously strike again, but are blocked once more. Debris hits beside you, raising billowing smoke."
  },
  AvgDialog_121743_Content_7 = {Text = "William?"},
  AvgDialog_121743_Content_8 = {
    Text = [[
Focus. Keep your eyes on that thing.
Leave your back to me.]]
  },
  AvgDialog_121743_Content_9 = {
    Text = [[
In this new world... I will temporarily assume the role of your partner.
Until the day we return to Mythag, side by side.]]
  },
  AvgDialog_121744_Content_1 = {
    Text = "The monster roars. It cries. The concealed curtain cracks, and Its body floats up from the depth of the sea."
  },
  AvgDialog_121744_Content_10 = {
    Text = "Not knowing how to use strength wisely and entrusting fate to others is not the Philistine way."
  },
  AvgDialog_121744_Content_11 = {
    Text = "The giant waves his weapon, pointing its tip at the huge mass of flesh."
  },
  AvgDialog_121744_Content_12 = {
    Text = "Enough talk. Prepare for battle!"
  },
  AvgDialog_121744_Content_13 = {
    Text = "Only the winner is qualified to survive."
  },
  AvgDialog_121744_Content_2 = {
    Text = "No... It's still expanding!"
  },
  AvgDialog_121744_Content_3 = {
    Text = "A bolt of lightning split the pitch-black night sky. Meanwhile, a giant blade fiercely slices at the monster's pale and fragile limbs, accompanied by swift purple-black flashes of lightning."
  },
  AvgDialog_121744_Content_4 = {
    Text = "...Miryam? Goliath? Why are you here?"
  },
  AvgDialog_121744_Content_5 = {
    Text = "Divine Mother, since you have made up your mind... We shall sever this heavy \"veil\" according to your will."
  },
  AvgDialog_121744_Content_6 = {Text = "Miryam..."},
  AvgDialog_121744_Content_7 = {
    Text = "Rest assured, Divine Mother. No matter what you plan to do in the future, the Seafarers will always be the most steadfast support behind you."
  },
  AvgDialog_121744_Content_8 = {
    Text = "Cut the nonsense. Do you really think we're going to just watch while you two little things try to fight that monster?"
  },
  AvgDialog_121744_Content_9 = {
    Text = "A familiar voice sounds, interrupting Murphy's words. Goliath shows up with Caecus."
  },
  AvgDialog_121745_Content_1 = {
    Text = "The towering monster raises its head high, <Italic:gazing> at all of you from behind the dim veil."
  },
  AvgDialog_121745_Content_10 = {
    Text = "Please... be forever buried in the boundless deep sea, like the old me!"
  },
  AvgDialog_121745_Content_2 = {Text = "...!!!"},
  AvgDialog_121745_Content_3 = {
    Text = "An invisible link connects Murphy and the monster, unavoidable, allowing her to see Its trauma, Its sobbing, even Its confusion..."
  },
  AvgDialog_121745_Content_4 = {
    Text = "Like a wounded child, It is questioning the mother's \"Betrayal.\""
  },
  AvgDialog_121745_Content_5 = {
    Text = "Don't look at me, don't judge me, please... I've already made up my mind. This will be my last <Italic:Betrayal>."
  },
  AvgDialog_121745_Content_6 = {
    Text = "Once, I made a wish to the <Italic:Paradise.> I prayed for a <Italic:Dream> I've longed for since my youth."
  },
  AvgDialog_121745_Content_7 = {
    Text = "I thought the <Italic:Authority> could help me gain happiness, but it was ultimately just a vain fantasy..."
  },
  AvgDialog_121745_Content_8 = {
    Text = "Murphy smiles as she wipes away the tears that fall from the corners of her eyes. She slowly and meticulously wipes, until the last trace of tears vanishes. She lifts her head, gazing at the giant version of <Italic:\"herself\".>"
  },
  AvgDialog_121745_Content_9 = {
    Text = "I don't need a Paradise. I don't need a self-deceiving dream. Not anymore."
  },
  AvgDialog_121858_Content_1 = {
    Text = [[
Countless monsters pour forth from beneath It. You will slay them all.

With countless corpses underfoot, you've reached the base of the massive outline of the entity.]]
  },
  AvgDialog_121858_Content_10 = {
    Text = "This time, I will not allow anyone's life to be traded for victory."
  },
  AvgDialog_121858_Content_11 = {
    Text = "Prepare for battle. The \"Veil\" will eventually fade away!"
  },
  AvgDialog_121858_Content_2 = {
    Text = "This is my will. The will of \"Paradise\"..."
  },
  AvgDialog_121858_Content_3 = {
    Text = "\"Children\" never inherently belong to the \"Mother\" who birthed them. Upon birth, your child develops its own \"will.\""
  },
  AvgDialog_121858_Content_4 = {
    Text = "<Red:Dream... must... continue...>"
  },
  AvgDialog_121858_Content_5 = {
    Text = "You once said that if we killed the Domain Master and transferred the Authority to you..."
  },
  AvgDialog_121858_Content_6 = {
    Text = "Yes. My promise still stands. Have you made your resolve?"
  },
  AvgDialog_121858_Content_7 = {
    Text = "No. She won't have to make such a sacrifice again."
  },
  AvgDialog_121858_Content_8 = {
    Text = "...%player%!"
  },
  AvgDialog_121858_Content_9 = {
    Text = "The \"Core\" of this Domain... the \"Cataclysm\" we're facing... I've fought things like this so many times I lost count."
  },
  AvgDialog_121859_Content_1 = {
    Text = "The power It exerts within the veil... is changing..."
  },
  AvgDialog_121859_Content_2 = {
    Text = "Abandoned, forsaken... It laments in unwillingness, in anger, in sorrow..."
  },
  AvgDialog_121859_Content_3 = {
    Text = "Its resentment will descend upon you...!"
  },
  AvgDialog_121864_Content_1 = {
    Text = "Surprised? The oracle calls to me, from beyond the veil..."
  },
  AvgDialog_121865_Content_1 = {
    Text = "My blood is pulsing... and the abyss is chanting an invitation to me!"
  },
  AvgDialog_121866_Content_1 = {
    Text = "Oh distant Lord, Your devoted servant offers what little strength she can..."
  },
  AvgDialog_121867_Content_1 = {
    Text = "Consider yourself lucky. You shall witness the true strength of the Philistines!"
  },
  AvgDialog_122640_Content_1 = {
    Text = "<Shake:Boom!—>"
  },
  AvgDialog_122640_Content_2 = {
    Text = "The dimension begins to tremble under the gaze of madness; The link between you and Ramona is shrouded by Dissolution, vanishing from sight."
  },
  AvgDialog_122640_Content_3 = {
    Text = "You draw a sharp breath, forcing down the storm of agitation that madness stirs within."
  },
  AvgDialog_122640_Content_4 = {
    Text = "Keep this madness to yourself... <Big:I won't let your madness harm anyone else!>"
  },
  AvgDialog_122641_Content_1 = {
    Text = "...@3!! ..."
  },
  AvgDialog_122641_Content_2 = {
    Text = "The familiar ominousness. The familiar gaze. The familiar pain that threatens to split your brain."
  },
  AvgDialog_122641_Content_3 = {
    Text = "Heh... We meet again, Tohuwabohu, the Supreme Will... Guess I should thank you, though you can't hear anything..."
  },
  AvgDialog_122641_Content_4 = {
    Text = "You killed me once, and it helped me learn one thing..."
  },
  AvgDialog_122641_Content_5 = {
    Text = "You clutch the Silver Key tightly, staring into the gaze cast by Its will—and only later will you realize you were <Italic:smiling.>"
  },
  AvgDialog_122641_Content_6 = {
    Text = "In this grand dream of yours, nothing is immutable, and nothing is invincible."
  },
  AvgDialog_122641_Content_7 = {
    Text = "We have waited so long for this reunion... Not even you can get in our way!"
  },
  AvgDialog_122642_Content_1 = {
    Text = "...@2... @2... @1@3...!!"
  },
  AvgDialog_122642_Content_2 = {
    Text = "A violent impact shatters the dimension. You open your bloodshot eyes, fixing them on that pupil growing increasingly substantial."
  },
  AvgDialog_122642_Content_3 = {
    Text = "Your consciousness has reached its limit, Tohuwabohu... Now, return to your slumber!"
  },
  AvgDialog_122642_Content_4 = {
    Text = "You rally your almost exhausted spirit, infusing the last spiritual power into your Silver Key."
  },
  AvgDialog_122642_Content_5 = {
    Text = "Grasping the silver light like a blade, you stab it toward the god before you—"
  },
  AvgDialog_122643_Content_1 = {
    Text = "<Big:<Shake:Ramona!!!>>"
  },
  AvgDialog_122643_Content_2 = {
    Text = "The familiar figure is swallowed by Dissolution of Its gaze; ancient and sinister runes faintly appear in this gaze."
  },
  AvgDialog_122643_Content_3 = {
    Text = "These chantings shall end here...!"
  },
  AvgDialog_122644_Content_1 = {
    Text = "The world collapses and rebuilds before you; loved ones die and revive before you. That chaotic gaze pours all the chaos of the universe into your spirit."
  },
  AvgDialog_122644_Content_2 = {
    Text = "Chaos, confusion, madness... These are what your power ever brings."
  },
  AvgDialog_122644_Content_3 = {
    Text = "But your never managed to confuse me, Tohuwabohu. Never before, and certainly not now."
  },
  AvgDialog_122644_Content_4 = {
    Text = "The silver light flashes. Amidst those endless illusions, you find the path to confront It—"
  },
  AvgDialog_122645_Content_1 = {
    Text = "In the distant dimension, a speck of light flickers faintly."
  },
  AvgDialog_122645_Content_2 = {
    Text = "Is that... Pollux's \"Sacred Heart\"?"
  },
  AvgDialog_122645_Content_3 = {
    Text = "They're looking for me... They must be in danger, too."
  },
  AvgDialog_122645_Content_4 = {
    Text = "I still remember how scared I was last time, Tohuwabohu. But this time, I won't keep them waiting for long!"
  },
  AvgDialog_122646_Content_1 = {
    Text = "A sharp, piercing agony assaults every bone, every inch of your flesh. You endure this excruciating pain and manage a strained smile."
  },
  AvgDialog_122646_Content_2 = {
    Text = "Blind Idiot God, you'll never understand this: within your dream, some sufferings far surpass merely physical pain..."
  },
  AvgDialog_122646_Content_3 = {
    Text = "I will not let those sufferings happen again!"
  },
  AvgDialog_122693_Content_1 = {
    Text = "In the hollow hall, only the echoes of your and Murphy's footsteps remain."
  },
  AvgDialog_122694_Content_1 = {
    Text = "In the hollow hall, only the echoes of your and Murphy's footsteps remain."
  },
  AvgDialog_122696_Content_1 = {
    Text = "In the hollow hall, only the echoes of your and Murphy's footsteps remain."
  },
  AvgDialog_122697_Content_1 = {
    Text = "The sky is darkening much faster than usual today; heavy and leaden, a storm is clearly brewing."
  },
  AvgDialog_122697_Content_10 = {
    Text = "She looks up, her face flushed with an unnatural fever. A smile spreads across her lips—a haunting mix of confusion and pure mania."
  },
  AvgDialog_122697_Content_11 = {
    Text = "Fight me. Right here, right now!"
  },
  AvgDialog_122697_Content_13 = {
    Text = "Before you can utter a word, her axe swings. It grazes your cheek with terrifying precision, leaving behind nothing but a whistle of freezing air."
  },
  AvgDialog_122697_Content_14 = {
    Text = "The draft invades your collar and chills your chest, sending an instinctive shiver racing down your spine."
  },
  AvgDialog_122697_Content_15 = {
    Text = "Where is this coming from?! Why are we fighting?"
  },
  AvgDialog_122697_Content_16 = {
    Text = "Your protests fall on deaf ears; both the weapon and its master are beyond words."
  },
  AvgDialog_122697_Content_17 = {
    Text = "<Shake:Mouchette!?>"
  },
  AvgDialog_122697_Content_18 = {
    Text = "Mouchette! Look at me!"
  },
  AvgDialog_122697_Content_19 = {
    Text = "Under the weight of your persistent shouting, the axe finally halts. It thuds into the wall, inches from your shoulder, embedding itself deep into the stone."
  },
  AvgDialog_122697_Content_2 = {
    Text = "To avoid getting drenched, you hurry toward the dorms, only for a silhouette to block your path."
  },
  AvgDialog_122697_Content_20 = {
    Text = "The girl stands right in front of you. Her face is burning hot as she bunches her fists, violently seizing you by the collar."
  },
  AvgDialog_122697_Content_21 = {
    Text = "<Shake:Shut up... It hurts... I'm suffering... Only a fight will make it stop...>"
  },
  AvgDialog_122697_Content_22 = {
    Text = "Her grip tightens until her fingers turn bloodless and pale—a silent testament to her stubborn refusal to give in."
  },
  AvgDialog_122697_Content_23 = {
    Text = "I hate it... I hate people forcing their will on me..."
  },
  AvgDialog_122697_Content_24 = {
    Text = "You think a little thing like the Holy River can break me? <Shake:You're... severely underestimating me.>"
  },
  AvgDialog_122697_Content_25 = {
    Text = "She exhales sharply, trying to vent the River's corruption. But you can feel it—the heat radiating from her, the surging impulses, and the desperate internal war she's losing."
  },
  AvgDialog_122697_Content_26 = {
    Text = "Sensing her desperation, you sigh softly. You take her hand in yours and gently guide her fingers back onto the handle of her axe."
  },
  AvgDialog_122697_Content_27 = {
    Text = "<Shake:What are you doing?>"
  },
  AvgDialog_122697_Content_28 = {
    Text = "You want a fight? Then you've got one."
  },
  AvgDialog_122697_Content_29 = {
    Text = "However you want to do this, and for as long as it takes—I'm not going anywhere."
  },
  AvgDialog_122697_Content_3 = {
    Text = "Mouchette? Is something wrong?"
  },
  AvgDialog_122697_Content_30 = {Text = "..."},
  AvgDialog_122697_Content_31 = {
    Text = "Her eyes widen in shock, searching yours for a hint of a joke, but finding none."
  },
  AvgDialog_122697_Content_32 = {
    Text = "At that moment, the sky finally breaks. A stray droplet lands on Mouchette's cheek, slides down her chin, and vanishes into your collar, trailing a cold line down your skin."
  },
  AvgDialog_122697_Content_33 = {
    Text = "Then comes the deluge. Rain hammers the earth with a wild rhythm, stinging your faces and washing away the tension with a cold, damp itch."
  },
  AvgDialog_122697_Content_34 = {
    Text = "<Shake:Hahaha! Now THAT is the answer I wanted.>"
  },
  AvgDialog_122697_Content_35 = {
    Text = "Things are finally starting to get interesting, aren't they?"
  },
  AvgDialog_122697_Content_36 = {
    Text = "She wrenches the axe from the wall. But instead of swinging it, she simply stands there, locking her eyes onto yours."
  },
  AvgDialog_122697_Content_37 = {
    Text = "I don't usually do \"hand-to-hand,\" but I suppose it's good to try new things once in a while, right?"
  },
  AvgDialog_122697_Content_38 = {
    Text = "Life is long, after all... and the best \"pleasures\" should be savored slowly, in the flesh."
  },
  AvgDialog_122697_Content_39 = {
    Text = "She steps toward you, leaving the axe behind. The weapon leans quietly against the wall, surrendering to the cold baptism of the pouring rain."
  },
  AvgDialog_122697_Content_4 = {
    Text = "She keeps her head low, silent. You can only sense her inner turmoil by the way her knuckles have turned white, gripping her axe with trembling force."
  },
  AvgDialog_122697_Content_5 = {
    Text = "<Shake:Mouchette!?>"
  },
  AvgDialog_122697_Content_6 = {
    Text = "Finally, she speaks, her voice laced with an uncharacteristic flicker of hesitation."
  },
  AvgDialog_122697_Content_7 = {
    Text = "%player%, I... I need your help..."
  },
  AvgDialog_122697_Content_8 = {
    Text = "Help? Of course. What do you need?"
  },
  AvgDialog_122697_Content_9 = {
    Text = "<Shake:I need you to...>"
  },
  AvgDialog_122699_Content_1 = {
    Text = "In the hollow hall, only the echoes of your and Murphy's footsteps remain."
  },
  AvgDialog_122700_Content_1 = {
    Text = "In the hollow hall, only the echoes of your and Murphy's footsteps remain."
  },
  AvgDialog_122780_Content_1 = {
    Text = "Message from afar"
  },
  AvgDialog_122780_Content_2 = {
    Text = "This is a test document"
  },
  AvgDialog_122780_Content_3 = {
    Text = "This is a test document"
  },
  AvgDialog_122780_Content_4 = {
    Text = "This is a test document"
  },
  AvgDialog_122780_Content_5 = {
    Text = "This is a test document"
  },
  AvgDialog_122780_Content_6 = {
    Text = "This is a test document"
  },
  AvgDialog_122780_Content_7 = {
    Text = "End statement"
  },
  AvgDialog_123116_Content_1 = {
    Text = "The Lost Lamb"
  },
  AvgDialog_123116_Content_10 = {
    Text = "But every priest who arrived in Howick—John, James, Anderson—simply vanished without a trace shortly after arrival."
  },
  AvgDialog_123116_Content_11 = {
    Text = "They are kind, devout souls... since the Cataclysm, they have followed the All-Father's teachings, volunteering to travel to the outer parishes to spread His Gospel."
  },
  AvgDialog_123116_Content_12 = {
    Text = "Even in a city as large as London, ordinary people can barely look after themselves after the disaster. The situation in Howick must be even worse. Why would they—"
  },
  AvgDialog_123116_Content_13 = {
    Text = "For the same reason you do what you do for this world, and for the world you hail from, Pale Messenger."
  },
  AvgDialog_123116_Content_14 = {
    Text = "Salvador clasps his hands, his expression pious and brimming with compassion."
  },
  AvgDialog_123116_Content_15 = {
    Text = "Because our brothers and sisters are suffering."
  },
  AvgDialog_123116_Content_16 = {
    Text = "To eradicate such misery from this earth is the duty of the All-Father's emissaries. They cannot abandon those in despair simply because the journey is long."
  },
  AvgDialog_123116_Content_17 = {Text = "...I see."},
  AvgDialog_123116_Content_18 = {
    Text = "Father Salvador, I will help you find them. Whether they are dead or alive."
  },
  AvgDialog_123116_Content_19 = {Text = "Now"},
  AvgDialog_123116_Content_2 = {
    Text = "Howick, a remote town on the outskirts of London"
  },
  AvgDialog_123116_Content_20 = {
    Text = "Salvador, I think I see a light up ahead..."
  },
  AvgDialog_123116_Content_21 = {
    Text = "Your voice cuts off abruptly at the unexpected sight—a crude, makeshift cage sits jarringly in the middle of the empty cavern."
  },
  AvgDialog_123116_Content_22 = {
    Text = "At least a dozen people are crammed inside. They look haggard; several are covered in bruises and open wounds."
  },
  AvgDialog_123116_Content_23 = {
    Text = "<Shake:Henry... is he dead? They shot him. They shot Henry dead...!>"
  },
  AvgDialog_123116_Content_24 = {
    Text = "The woman clutches her head and mumbles to herself, her frantic gaze and violent trembling betraying her broken psyche."
  },
  AvgDialog_123116_Content_25 = {
    Text = "Suddenly, she looks up and notices your approach."
  },
  AvgDialog_123116_Content_26 = {
    Text = "<Shake:No, they're coming! Please, get us out of here!>"
  },
  AvgDialog_123116_Content_27 = {
    Text = "Her outburst draws the attention of the others. A man lunges toward the bars and seizes your arm with desperate strength."
  },
  AvgDialog_123116_Content_28 = {
    Text = "Save me! I don't want to be human cattle! I don't want to be sacrificed!"
  },
  AvgDialog_123116_Content_29 = {
    Text = "Aaaaah—GET US OUT OF HERE!"
  },
  AvgDialog_123116_Content_3 = {
    Text = "If the information \"Doll\" provided is correct, they should be right here."
  },
  AvgDialog_123116_Content_30 = {
    Text = "Shut the @4 up!"
  },
  AvgDialog_123116_Content_31 = {
    Text = "A thunderous roar silences the victims. The prisoners appear utterly petrified by the owner of the voice, cowering in terror."
  },
  AvgDialog_123116_Content_32 = {
    Text = "The ritual hasn't even started yet! You swines, are you so eager to die?!"
  },
  AvgDialog_123116_Content_33 = {
    Text = "The sound of hurried footsteps follows."
  },
  AvgDialog_123116_Content_34 = {
    Text = "Those must be the cultists holding these people. %player%, we should..."
  },
  AvgDialog_123116_Content_35 = {
    Text = "Stay hidden for now. We'll find a way to rescue them later. They're armed with guns; if things get chaotic, we won't be able to guarantee the prisoners' safety."
  },
  AvgDialog_123116_Content_36 = {
    Text = "However, the man still refuses to let go, gripping your arm with enough force to nearly snap the bone."
  },
  AvgDialog_123116_Content_37 = {
    Text = "Save us! Save us now! If you won't save us, then die with us!!"
  },
  AvgDialog_123116_Content_38 = {
    Text = "The footsteps draw nearer. The man is clearly too far gone to listen to reason."
  },
  AvgDialog_123116_Content_39 = {
    Text = "You grit your teeth and knock him unconscious with a swift blow."
  },
  AvgDialog_123116_Content_4 = {
    Text = "I trust your judgment, %player%."
  },
  AvgDialog_123116_Content_40 = {Text = "Heh..."},
  AvgDialog_123116_Content_41 = {
    Text = "A soft chuckle drifts from the corner of the cage."
  },
  AvgDialog_123116_Content_42 = {
    Text = "You instinctively turn your head. A strangely dressed girl is watching you, her faint smile appearing hauntingly detached from the surrounding madness."
  },
  AvgDialog_123116_Content_43 = {
    Text = "How fascinating. One second you say you're here to save them, and the next, you're knocking them out cold..."
  },
  AvgDialog_123116_Content_44 = {
    Text = "Her complete lack of concern leaves you momentarily stunned."
  },
  AvgDialog_123116_Content_45 = {
    Text = "Oh, don't mind me. Please, carry on."
  },
  AvgDialog_123116_Content_46 = {
    Text = "But you might want to hurry; the cultists are almost here."
  },
  AvgDialog_123116_Content_47 = {Text = "...?"},
  AvgDialog_123116_Content_48 = {
    Text = "Time is running out. With no leisure for idle chatter, you leave the girl behind and slip into the shadows with Salvador."
  },
  AvgDialog_123116_Content_49 = {
    Text = "Moments later, two cultists armed with shotguns appear. They flank the cage, leveling their weapons at the captives inside."
  },
  AvgDialog_123116_Content_5 = {
    Text = "May the All-Father bless our brothers and sisters and shield them from shadows. May they continue to dwell in peace."
  },
  AvgDialog_123116_Content_50 = {
    Text = "Who was making all that noise? Step forward!"
  },
  AvgDialog_123116_Content_51 = {
    Text = "No one answers. The prisoners either huddle in the corners trembling or stare blankly in a state of catatonic numbness. Everyone—except that strange girl."
  },
  AvgDialog_123116_Content_52 = {
    Text = "She maintains her casual, offhand smile, leisurely observing the armed men."
  },
  AvgDialog_123116_Content_53 = {
    Text = "Is she crazy? She looks far too relaxed for someone about to meet her end."
  },
  AvgDialog_123116_Content_54 = {
    Text = "Is there anyone left in this godforsaken world who isn't crazy? Ha! If <Italic:we> were crazy, maybe things would be easier."
  },
  AvgDialog_123116_Content_55 = {
    Text = "I just hope this ritual works. I'm sick to death of this strange mist..."
  },
  AvgDialog_123116_Content_56 = {
    Text = "So, when exactly does your ritual begin?"
  },
  AvgDialog_123116_Content_57 = {
    Text = "The cultists freeze in visible confusion."
  },
  AvgDialog_123116_Content_58 = {
    Text = "Who are you talking to? Us?"
  },
  AvgDialog_123116_Content_59 = {
    Text = "Well, duh? Stop wasting time and answer my question."
  },
  AvgDialog_123116_Content_6 = {
    Text = "Salvador devoutly lowers his eyes to whisper a prayer before leading the way deeper into the cave."
  },
  AvgDialog_123116_Content_60 = {
    Text = "Infuriated by her tone, the cultist sneers and aims his gun at her leg."
  },
  AvgDialog_123116_Content_61 = {
    Text = "You crazy bitch. All you have to do is sit there and wait to be sacrificed. You clearly have no idea what's happening here."
  },
  AvgDialog_123116_Content_62 = {Text = "BANG!"},
  AvgDialog_123116_Content_63 = {
    Text = "An invisible force diverts the shot, sending the bullet into the cavern ceiling where it strikes with a faint spark."
  },
  AvgDialog_123116_Content_64 = {
    Text = "You and Salvador emerge from the darkness, launching a sudden ambush."
  },
  AvgDialog_123116_Content_66 = {
    Text = "Nice timing. I suppose you two aren't as stupid as you look."
  },
  AvgDialog_123116_Content_67 = {
    Text = "Thank you for distracting them for us, kind lady."
  },
  AvgDialog_123116_Content_68 = {
    Text = "May the All-Father bless you."
  },
  AvgDialog_123116_Content_69 = {
    Text = [[
Salvador traces the All-Father's Holy Sign in the air. 
Meanwhile, you confiscate the cultists' weapons and force them to their knees before the cage to begin the interrogation.]]
  },
  AvgDialog_123116_Content_7 = {
    Text = "Three Days Ago"
  },
  AvgDialog_123116_Content_70 = {
    Text = "Talk. When is the ritual? Where is it being held? And did you have anything to do with the disappearance of the Chantry of Life's priests?!"
  },
  AvgDialog_123116_Content_71 = {
    Text = "Chantry of Life... priests...?"
  },
  AvgDialog_123116_Content_72 = {
    Text = "You heard {Male=him,Female=her} right. John, James, Anderson. Where are they?"
  },
  AvgDialog_123116_Content_73 = {
    Text = "The cultist pauses for a moment, then bursts into a fit of wild, manic laughter."
  },
  AvgDialog_123116_Content_74 = {
    Text = "<Shake:We shall redeem ourselves according to the All-Father's will! Yes, the Serene Realm Free from Dissolution is at hand!>"
  },
  AvgDialog_123116_Content_75 = {
    Text = "<Shake:<Big:It has descended! You unblessed wretches will rot here while the world falls to ruin!>>"
  },
  AvgDialog_123116_Content_76 = {
    Text = "So, the ritual is about to start? <Small:Seems I'll have to hurry.>"
  },
  AvgDialog_123116_Content_77 = {
    Text = "Hurry... What do you mean? What do you know?"
  },
  AvgDialog_123116_Content_78 = {
    Text = "The girl doesn't answer. She glances at you and Salvador with an innocent, sweet smile, yet you sense a sharp edge of cunning beneath it."
  },
  AvgDialog_123116_Content_79 = {
    Text = "Ah, right. My name is Mouchette. As for yours—don't bother, I'm not interested."
  },
  AvgDialog_123116_Content_8 = {
    Text = "All the priests sent to Howick by the Chantry of Life have gone missing?"
  },
  AvgDialog_123116_Content_80 = {
    Text = "I know where the ritual site is, and I can take you there. But..."
  },
  AvgDialog_123116_Content_81 = {
    Text = "I'm going to need a small favor first."
  },
  AvgDialog_123116_Content_82 = {
    Text = "What kind of favor? Please be clear."
  },
  AvgDialog_123116_Content_83 = {
    Text = "Again, she offers no answer. Humming a sporadic, broken melody, she begins to walk away."
  },
  AvgDialog_123116_Content_84 = {
    Text = "Hehe☆! I have some business to attend to first. Meet me outside in ten minutes~"
  },
  AvgDialog_123116_Content_85 = {Text = "..."},
  AvgDialog_123116_Content_86 = {
    Text = "This is just as well. We can use the time to contact the Chantry and arrange for reinforcements to secure these poor souls."
  },
  AvgDialog_123116_Content_87 = {
    Text = "I suppose we have no other choice."
  },
  AvgDialog_123116_Content_88 = {
    Text = "As you watch the girl walk away, a growing sense of unease crawls up your spine."
  },
  AvgDialog_123116_Content_89 = {
    Text = "The source is the jarring disconnection beneath her youthful exterior—a personality that seems almost human, yet feels glaringly, undeniably... false."
  },
  AvgDialog_123116_Content_9 = {
    Text = "Yes. After we lost contact with Father White, who was in charge of the Howick parish, the Chantry decided to send reinforcements."
  },
  AvgDialog_123117_Content_1 = {
    Text = "In Silver and Blood"
  },
  AvgDialog_123117_Content_10 = {
    Text = "...I really shouldn't have humored you."
  },
  AvgDialog_123117_Content_100 = {
    Text = "Mouchette... if you can hear me... please. I'm begging you."
  },
  AvgDialog_123117_Content_101 = {
    Text = "Still, the void remains empty. The girl named Mouchette is gone."
  },
  AvgDialog_123117_Content_102 = {Text = "..."},
  AvgDialog_123117_Content_103 = {
    Text = "You close your eyes, exhaling a ragged sigh. Time is up. Salvador is dying outside, and the Gate is widening. You have to move."
  },
  AvgDialog_123117_Content_104 = {
    Text = "I'm sorry I dragged you into this nightmare. I'm sorry I couldn't get you home."
  },
  AvgDialog_123117_Content_105 = {
    Text = "You sever the connection to her Spirit Realm."
  },
  AvgDialog_123117_Content_106 = {
    Text = "Dizziness washes over you as your spirit snaps back into your body. You are back at the start."
  },
  AvgDialog_123117_Content_107 = {
    Text = "The invisible Gateway is keening in its death throes, and Mouchette's axe is heavy in your hands."
  },
  AvgDialog_123117_Content_108 = {
    Text = "<Shake:Mouchette... I...>"
  },
  AvgDialog_123117_Content_109 = {
    Text = "You grip the handle, looking at the silent girl. She stands there in the ruins of her sanity, waiting for the killing blow."
  },
  AvgDialog_123117_Content_11 = {
    Text = "You let out a heavy sigh, shoulders slumped. Salvador watches the exchange, a faint, warm chuckle escaping him."
  },
  AvgDialog_123117_Content_110 = {
    Text = "You look into her eyes, searching for the girl who smiled, the girl who joked. You can't believe she's gone."
  },
  AvgDialog_123117_Content_111 = {
    Text = "<Shake:How long... are you going to... just stare at me...?>"
  },
  AvgDialog_123117_Content_112 = {
    Text = "Mouchette! You're back?!"
  },
  AvgDialog_123117_Content_113 = {
    Text = "<Shake:Not really... but I... heard you...>"
  },
  AvgDialog_123117_Content_114 = {
    Text = "You're right... I can't just... quit without a fight."
  },
  AvgDialog_123117_Content_115 = {
    Text = "She lunges forward with her final spark of life, her hand closing over the Silver Key at your chest."
  },
  AvgDialog_123117_Content_116 = {
    Text = "Whatever happens... the Gate dies with me."
  },
  AvgDialog_123117_Content_117 = {
    Text = "I won't let this place... become another world of mist."
  },
  AvgDialog_123117_Content_118 = {
    Text = "Not after seeing how hard you fought to save it."
  },
  AvgDialog_123117_Content_119 = {
    Text = "The Silver Key erupts, a supernova of white light that bleaches your vision and swallows the world."
  },
  AvgDialog_123117_Content_12 = {
    Text = "Mouchette is... a unique child. Very special, but a good soul nonetheless."
  },
  AvgDialog_123117_Content_120 = {
    Text = "A chorus of screams fills the air—the wail of the Gate, the distortion of the flute, the sound of a world shattering."
  },
  AvgDialog_123117_Content_121 = {
    Text = "Or perhaps it is all a hallucination. In that sea of white, time and sense have no meaning."
  },
  AvgDialog_123117_Content_122 = {
    Text = "When the ringing finally stops and your senses return, the world is quiet."
  },
  AvgDialog_123117_Content_123 = {
    Text = "The fog has vanished. The Gate is gone. Only the blood-stained altar remains, and Salvador, watching you with hollow, worried eyes."
  },
  AvgDialog_123117_Content_124 = {
    Text = "Pale Messenger... did we... did we fail?"
  },
  AvgDialog_123117_Content_125 = {Text = "..."},
  AvgDialog_123117_Content_126 = {
    Text = "A soft, familiar chuckle echoes from behind you."
  },
  AvgDialog_123117_Content_127 = {
    Text = "%player%, Salvador. Why the long faces? The mission is over."
  },
  AvgDialog_123117_Content_128 = {
    Text = "<Big:MOUCHETTE—!!>"
  },
  AvgDialog_123117_Content_129 = {
    Text = "You scream her name in pure shock, and then, despite the blood and the ruins, you start to laugh."
  },
  AvgDialog_123117_Content_13 = {
    Text = "A good soul? Please, don't use those—Wait. Do you hear that?"
  },
  AvgDialog_123117_Content_130 = {
    Text = "I'm right here, no need to shout. The exciting part is over. Now back to the boring stuff."
  },
  AvgDialog_123117_Content_131 = {
    Text = "I'm really craving a cup of Hazelnut Kava Tea now. Oh, right... you don't have it here. Cupcakes it is then."
  },
  AvgDialog_123117_Content_132 = {
    Text = "You're going to tell me everything. Who Murphy is, who Liz is, who Doll is... and all those adventures you had."
  },
  AvgDialog_123117_Content_133 = {
    Text = "Since I'm stuck here, I might as well get to know the neighborhood."
  },
  AvgDialog_123117_Content_134 = {
    Text = "I don't think %player% will have any objections to that."
  },
  AvgDialog_123117_Content_135 = {
    Text = "Salvador smiles at you, and you find yourself smiling back at her. The moonlight breaks through the clouds, bathing the three of you in a soft, silver glow."
  },
  AvgDialog_123117_Content_136 = {
    Text = "You have a thousand questions, but you let them rest for now."
  },
  AvgDialog_123117_Content_137 = {
    Text = "Perhaps it's the moonlight, or perhaps it's the sheer, dizzying relief of a narrow escape. It feels like a rebirth."
  },
  AvgDialog_123117_Content_138 = {
    Text = "...The reports can wait. We don't get many chances to welcome a traveler to a brand new life."
  },
  AvgDialog_123117_Content_139 = {
    Text = "Congratulations, Mouchette. You're an Awakener now. This isn't just our world anymore—it's yours too."
  },
  AvgDialog_123117_Content_14 = {
    Text = "Someone is crying... and the sound is getting louder."
  },
  AvgDialog_123117_Content_140 = {
    Text = [[
Awakener Mouchette,
Welcome to this world.]]
  },
  AvgDialog_123117_Content_15 = {
    Text = "You strain to listen, but only the wind answers. Salvador offers a gentle shake of his head; he hears nothing but silence."
  },
  AvgDialog_123117_Content_16 = {
    Text = "Suddenly, Mouchette shrieks. She doubles over, her hands clamping over her ears as if trying to block out a scream from within."
  },
  AvgDialog_123117_Content_17 = {
    Text = "<Shake:Wait... someone, no, hundreds of them... they're screaming in my head... howling...>"
  },
  AvgDialog_123117_Content_18 = {
    Text = "Panic flares as you rush to her side. Her body is wracked with violent tremors, and her pupils are dilating into empty, unfocused voids."
  },
  AvgDialog_123117_Content_19 = {
    Text = "Loss of control? Is it the Liquefied Silver...?"
  },
  AvgDialog_123117_Content_2 = {
    Text = "Beneath a sky choked with silver and blood, the endless mist seethes. The invisible Gateway pulses with light, yet its aura of invincibility has finally begun to fracture."
  },
  AvgDialog_123117_Content_20 = {
    Text = "Liquefied Silver!?"
  },
  AvgDialog_123117_Content_21 = {
    Text = "You scan the gore clinging to her. Amidst the dark red, the silver is pulsing, moving like a parasite as it seeps through her skin and into her veins."
  },
  AvgDialog_123117_Content_22 = {
    Text = "She came here through their sacrifice. The ritual has claimed her—the silver is treating her as part of the offering itself!"
  },
  AvgDialog_123117_Content_23 = {
    Text = "We have to act! The contamination is too deep. If we don't purge it now, her mind will shatter!"
  },
  AvgDialog_123117_Content_24 = {
    Text = "You and Salvador move to scrub the Silver off her, but the transformation has already taken root."
  },
  AvgDialog_123117_Content_25 = {
    Text = "<Red:<Shake:AAAAHHH—!>>"
  },
  AvgDialog_123117_Content_26 = {
    Text = "A final scream tears from her throat as her pupils shatter into jagged fragments. Her body twists, flesh rupturing and bone snapping as she mutates into a grotesque, nameless horror."
  },
  AvgDialog_123117_Content_27 = {
    Text = "Pieces of her flesh spray across you and Salvador, striking the shapeless gate and sending violent ripples across its dark surface."
  },
  AvgDialog_123117_Content_28 = {
    Text = "Something is wrong. The Gateway... it's changing..."
  },
  AvgDialog_123117_Content_29 = {
    Text = "Before you can react, a psychic backlash slams through the link between the Gate and your Silver Key, hitting your mind with the force of a hammer."
  },
  AvgDialog_123117_Content_3 = {
    Text = "Resolute light flares from the Silver Key in your hand, its brilliance stitching the Time Rift shut and purging the unnatural distortions born of the ritual."
  },
  AvgDialog_123117_Content_30 = {
    Text = "Agony blinds you. Blood pours from your nose as your strength evaporates, leaving you collapsed on one knee, gasping for air."
  },
  AvgDialog_123117_Content_31 = {
    Text = "<Red:<Shake:Kill! Kill them all! Wipe them out!>>"
  },
  AvgDialog_123117_Content_32 = {
    Text = "<Red:<Shake:Hahaha! Watch this world burn!>>"
  },
  AvgDialog_123117_Content_33 = {
    Text = "The axe that once cleared your path is raised high, its edge aimed at your skull. Drained by the spiritual link, you can only watch, paralyzed."
  },
  AvgDialog_123117_Content_34 = {
    Text = "<Shake:Mouchette...>"
  },
  AvgDialog_123117_Content_35 = {
    Text = "You try to call her name, but your voice is a broken rasp, powerless to reach the mind buried beneath the monstrosity."
  },
  AvgDialog_123117_Content_37 = {
    Text = "The axe swings down, hungry for bone. At the final heartbeat, Salvador throws himself in front of you, absorbing the impact."
  },
  AvgDialog_123117_Content_38 = {
    Text = "Blood carves a path down Salvador's shoulder, yet his face remains a mask of profound mercy and boundless compassion."
  },
  AvgDialog_123117_Content_39 = {
    Text = "Child, I know this isn't your heart. You are simply lost in the dark."
  },
  AvgDialog_123117_Content_4 = {
    Text = "After a long silence, the levitating silver and blood begin to rain down, staining the earth and your shoulders. The heavy mist visibly recedes, shrinking back into the void. Things are turning."
  },
  AvgDialog_123117_Content_40 = {
    Text = "<Red:<Shake:KILL! DESTROY EVERYTHING!>>"
  },
  AvgDialog_123117_Content_41 = {
    Text = "The madness is absolute. Mouchette is gone, replaced by a feral impulse to slaughter and erase."
  },
  AvgDialog_123117_Content_42 = {
    Text = "<Shake:Salvador, stop... she's gone...>"
  },
  AvgDialog_123117_Content_43 = {
    Text = "You look at the creature that was once your friend, your voice trembling. Just moments ago, she was full of life and wit."
  },
  AvgDialog_123117_Content_44 = {
    Text = "No, Pale Messenger. She is merely lost."
  },
  AvgDialog_123117_Content_45 = {
    Text = "Salvador stands, stepping directly into the shadow of the raised axe."
  },
  AvgDialog_123117_Content_46 = {
    Text = "Blood from the blade spatters his face, but his eyes do not flicker with fear."
  },
  AvgDialog_123117_Content_47 = {
    Text = "I was not there when the Sect summoned you through blood. For that, I am truly sorry."
  },
  AvgDialog_123117_Content_48 = {
    Text = "A single drop of Mouchette's blood slides down his cheek like a solitary, crimson tear."
  },
  AvgDialog_123117_Content_49 = {
    Text = "He does not wipe it away. Instead, he grips the biting edge of the axe with one hand and raises the other to her brow."
  },
  AvgDialog_123117_Content_5 = {
    Text = "The dimensional anomalies are bottoming out, Mouchette. This is it—your best chance to cross back."
  },
  AvgDialog_123117_Content_50 = {
    Text = "But I am here now. And I will redeem you."
  },
  AvgDialog_123117_Content_51 = {
    Text = "His bloodied palm touches her forehead. Instantly, a blinding, resolute light erupts from the point of contact."
  },
  AvgDialog_123117_Content_52 = {
    Text = "It is a Benediction—a Priest of this world shielding a lost Lamb of another."
  },
  AvgDialog_123117_Content_53 = {
    Text = "As the light swells, the screaming pain in your mind vanishes. It feels as though a great weight has been lifted from your soul and placed onto his."
  },
  AvgDialog_123117_Content_54 = {
    Text = "Salvador, stop! That link spans an entire dimension! No human can survive that!"
  },
  AvgDialog_123117_Content_55 = {Text = "I know."},
  AvgDialog_123117_Content_56 = {
    Text = "His voice is a fractured whisper. Even for him, this psychic connection is a torment that defies description."
  },
  AvgDialog_123117_Content_57 = {
    Text = "Within seconds, the strain breaks him. Tears of blood begin to track down his face."
  },
  AvgDialog_123117_Content_58 = {
    Text = "But as the All-Father's Emissary, I will give everything I am."
  },
  AvgDialog_123117_Content_59 = {
    Text = "Blood weeps from beneath his eye-wrap, but the golden light of the Benediction catches it, turning the red to molten gold."
  },
  AvgDialog_123117_Content_6 = {
    Text = "I'm pushing the Silver Key to its limit. It will hold the path steady until you're safe on the other side."
  },
  AvgDialog_123117_Content_60 = {
    Text = "This gold drips onto Mouchette's hand, the light fading to reveal the raw crimson beneath as it merges with the sacrificial blood on her skin."
  },
  AvgDialog_123117_Content_61 = {
    Text = "In His name, Mouchette, I will not let you fall."
  },
  AvgDialog_123117_Content_62 = {
    Text = "At his command, the light at her forehead flares with the heat of a dying star, drowning out the blood, the shadows, and the Gateway itself."
  },
  AvgDialog_123117_Content_63 = {
    Text = "It is the radiance of a man pouring his very life-force into a single moment of salvation."
  },
  AvgDialog_123117_Content_64 = {
    Text = "<Shake:Ugh...>"
  },
  AvgDialog_123117_Content_65 = {
    Text = "In that sun-bright glare, Mouchette's split pupils flicker with a spark of clarity. Her dying sanity clings to the sight of her own hand."
  },
  AvgDialog_123117_Content_66 = {
    Text = "Salvador's blood is no longer separate from hers; they have become one."
  },
  AvgDialog_123117_Content_67 = {
    Text = "The blood of the victim and the slayer, the sinner and the saint, flows together into a single, unified tide."
  },
  AvgDialog_123117_Content_68 = {
    Text = "I... I said..."
  },
  AvgDialog_123117_Content_69 = {
    Text = "<Shake:I hate it... being saved by... the sacrifice of others...>"
  },
  AvgDialog_123117_Content_7 = {
    Text = "I wish I could take a shower first. If I go back looking like a butcher's shop, I'll give the Investigator a heart attack."
  },
  AvgDialog_123117_Content_70 = {
    Text = "Pushing Salvador back with the last of her strength, she turns to you, her face a mask of tears and agony. She raises the axe one final time."
  },
  AvgDialog_123117_Content_71 = {
    Text = "Don't let him... do this again. People like him... they're the ones who deserve to live."
  },
  AvgDialog_123117_Content_72 = {
    Text = "The ritual... the Gate has woven me into itself. I'm part of it now."
  },
  AvgDialog_123117_Content_73 = {
    Text = "<Shake:Kill me. If I die, it vanishes. They'll all... be free.>"
  },
  AvgDialog_123117_Content_74 = {
    Text = "And... this isn't running away. It's... taking the enemy down with me."
  },
  AvgDialog_123117_Content_75 = {
    Text = "With a final, shaking effort, she thrusts the handle of the axe into your hands. You stand there, frozen by the weight of it."
  },
  AvgDialog_123117_Content_76 = {
    Text = "Honestly... why did I choose this? I don't even... understand myself."
  },
  AvgDialog_123117_Content_77 = {
    Text = "Destroying the world... was supposed to be my style..."
  },
  AvgDialog_123117_Content_78 = {
    Text = "A sob breaks her voice. A single tear rolls down the blade and shatters against your palm."
  },
  AvgDialog_123117_Content_79 = {
    Text = "The clarity begins to fade. Her eyes grow cloudy as the madness claws its way back to the surface. She is slipping away again."
  },
  AvgDialog_123117_Content_8 = {
    Text = "Should we set a table for you? Maybe some cupcakes for a proper afternoon tea?"
  },
  AvgDialog_123117_Content_80 = {
    Text = "Pale Messenger, please... I can still save her..."
  },
  AvgDialog_123117_Content_81 = {
    Text = "Salvador struggles to rise, his voice a desperate plea. You look down at the axe, your mind a storm of grief and conflict."
  },
  AvgDialog_123117_Content_82 = {
    Text = "This isn't just a weapon. It is her trust. It is her goodbye."
  },
  AvgDialog_123117_Content_83 = {
    Text = "<Shake:Just give me a moment... there has to be another way... there has to be...>"
  },
  AvgDialog_123117_Content_84 = {
    Text = "Suddenly, a desperate solution flashes in your mind."
  },
  AvgDialog_123117_Content_85 = {
    Text = "You don't stop to think. You seize the Silver Key and grab Mouchette's hand, diving headlong into the murky depths of her consciousness."
  },
  AvgDialog_123117_Content_86 = {
    Text = "You will use the Silver in her veins to force a transformation—turning her from a human into an Awakener. It is a desperate, suicidal gamble."
  },
  AvgDialog_123117_Content_87 = {
    Text = "As you plunge into her mind, you are blinded by writhing, screaming specks of light. They wail in agony, but none of them are her."
  },
  AvgDialog_123117_Content_88 = {
    Text = "Her inner world is a void. There is no Mouchette here."
  },
  AvgDialog_123117_Content_89 = {
    Text = "Mouchette! Mouchette, where are you?!"
  },
  AvgDialog_123117_Content_9 = {
    Text = "Perfect. Honestly, after seeing how messy this boring world is, those cakes are going to taste like a miracle."
  },
  AvgDialog_123117_Content_90 = {
    Text = "Silence. As a human, that final plea for death was the absolute limit of her will. She has nothing left to give."
  },
  AvgDialog_123117_Content_91 = {
    Text = "Have you given up? You're the one who joked about having days you wanted to die every week... always talked about ending it all..."
  },
  AvgDialog_123117_Content_92 = {
    Text = "But not like this. Salvador, me, even that Investigator you talk about—none of us want this for you!"
  },
  AvgDialog_123117_Content_93 = {
    Text = "So please, Mouchette... come out!"
  },
  AvgDialog_123117_Content_94 = {
    Text = "No matter how loud you scream, only the echoes of the mad answer you."
  },
  AvgDialog_123117_Content_95 = {
    Text = "She has vanished into the dark."
  },
  AvgDialog_123117_Content_96 = {
    Text = "...I have a plan."
  },
  AvgDialog_123117_Content_97 = {
    Text = "I'm going to use the silver inside you to refine you... to make you an Awakener. It might kill you. But it's all I have."
  },
  AvgDialog_123117_Content_98 = {
    Text = "<Small:I thought the hardest part would be the Awakening itself. I didn't think I'd fail because I couldn't even find your soul...>"
  },
  AvgDialog_123117_Content_99 = {
    Text = "Silence falls, heavy and suffocating. As a Keeper, you know exactly what happens to a human heart when it is over-saturated with Silver."
  },
  AvgDialog_123118_Content_1 = {
    Text = "In the boundless fog, the chilling wails of agony echo continuously."
  },
  AvgDialog_123118_Content_10 = {
    Text = "The All-Father's mercy cannot save everyone, but we will do everything in our power to lend a hand to every victim we can reach."
  },
  AvgDialog_123118_Content_11 = {
    Text = "<Shake:Don't... please, stop screaming...>"
  },
  AvgDialog_123118_Content_12 = {
    Text = "Under the weight of the psychic trauma, blood begins to stream uncontrollably from her nose."
  },
  AvgDialog_123118_Content_13 = {
    Text = "<Shake:I said, <Big:STOP SCREAMING!>>"
  },
  AvgDialog_123118_Content_15 = {
    Text = "Mouchette cries out in rage. In her agitation, she swings her axe furiously at the humanoid mists, only to see them split apart and instantly reform."
  },
  AvgDialog_123118_Content_16 = {
    Text = "It's useless. As long as the mist remains, these monsters will never vanish."
  },
  AvgDialog_123118_Content_17 = {
    Text = "That's why you wanted us to \"help\" by distracting them earlier, wasn't it?"
  },
  AvgDialog_123118_Content_18 = {
    Text = "Are you trying to settle scores now? Get in line—you're way in the back..."
  },
  AvgDialog_123118_Content_19 = {
    Text = "Mouchette wipes the blood from her nose and resumes swinging her axe. The thrill of battle fires her up; she can't stop, and she won't."
  },
  AvgDialog_123118_Content_2 = {
    Text = "@2 I... save @2..."
  },
  AvgDialog_123118_Content_20 = {
    Text = "There's no way to retreat now anyway. We might as well hold them off here!"
  },
  AvgDialog_123118_Content_21 = {
    Text = "Mouchette, calm down! If you keep this up, you'll..."
  },
  AvgDialog_123118_Content_22 = {
    Text = "I'll die? Is that it?"
  },
  AvgDialog_123118_Content_23 = {
    Text = "I have days every week where I wanna end it all anyway. Ha, I may as well..."
  },
  AvgDialog_123118_Content_24 = {
    Text = "Mouchette cuts herself off. A sudden light flares before her, followed by a wave of warmth that showers over her, flowing into her very marrow."
  },
  AvgDialog_123118_Content_25 = {
    Text = "Salvador has bestowed the Blessing upon her."
  },
  AvgDialog_123118_Content_26 = {
    Text = "<Shake:What are you doing?!>"
  },
  AvgDialog_123118_Content_27 = {
    Text = "Mouchette instinctively recoils. The sensation of warmth is too alien. It feels wrong. It shouldn't belong to someone like her."
  },
  AvgDialog_123118_Content_28 = {
    Text = "We... we are enemies. Why..."
  },
  AvgDialog_123118_Content_29 = {
    Text = "I told you. We are not enemies."
  },
  AvgDialog_123118_Content_3 = {
    Text = "Save @2... @2 me..."
  },
  AvgDialog_123118_Content_30 = {
    Text = "Not being enemies doesn't make us allies!"
  },
  AvgDialog_123118_Content_31 = {
    Text = "I'm not naive enough to consider people I've only just met as companions..."
  },
  AvgDialog_123118_Content_32 = {
    Text = "But we've already fought those cultists together, haven't we? Those who stand together in battle are partners."
  },
  AvgDialog_123118_Content_33 = {
    Text = "And for the record, I'm not going to repeat some boring lectures about \"love and compassion.\" I prefer to look at it differently..."
  },
  AvgDialog_123118_Content_34 = {
    Text = "I see it as a form of survival wisdom."
  },
  AvgDialog_123118_Content_35 = {
    Text = "The radiance of the All-Father reaches across the entire earth. Even in the lands of annihilation, brothers and sisters must support one another."
  },
  AvgDialog_123118_Content_36 = {
    Text = "Mouchette presses her lips together in silence. Her eyes remain wary and suspicious, but slowly, that hostility softens into confusion... and a faint trace of nostalgia."
  },
  AvgDialog_123118_Content_37 = {
    Text = "Her lips move as if she is whispering something. Though her voice is too low, you catch the word \"Investigator\" again."
  },
  AvgDialog_123118_Content_38 = {
    Text = "I'll reconsider the whole \"dying\" thing another time. I still have someone I need to see back home."
  },
  AvgDialog_123118_Content_39 = {
    Text = "You mean... that Investigator you mentioned?"
  },
  AvgDialog_123118_Content_4 = {
    Text = "<Shake:Make it stop! This Mist... why won't it stop screaming?!>"
  },
  AvgDialog_123118_Content_40 = {
    Text = "Before Mouchette can answer, an invisible shockwave washes over the area. The hair on your neck stands on end as the monsters in the mist grow even more frenzied."
  },
  AvgDialog_123118_Content_41 = {
    Text = "This feeling... <Shake:<Big:The ritual has begun!>>"
  },
  AvgDialog_123118_Content_42 = {
    Text = "The ritual? But we saved the sacrifices!"
  },
  AvgDialog_123118_Content_43 = {
    Text = "And Pale Messenger... the missing priests weren't among the prisoners we found."
  },
  AvgDialog_123118_Content_44 = {
    Text = "Were the people we rescued just backups? Or is the ritual time fixed, forced to proceed even if the sacrifices are insufficient?"
  },
  AvgDialog_123118_Content_45 = {
    Text = "I don't have time to play detective."
  },
  AvgDialog_123118_Content_46 = {
    Text = "Are you two going to stay here and chatter, or are you coming with me? Decide. Fast."
  },
  AvgDialog_123118_Content_47 = {
    Text = "Mouchette shoots you an impatient look, then turns her back and steps into the thick of the mist."
  },
  AvgDialog_123118_Content_48 = {Text = "Mouchette!"},
  AvgDialog_123118_Content_49 = {
    Text = "I know what you're worried about. I won't play any tricks this time."
  },
  AvgDialog_123118_Content_5 = {
    Text = "Because this isn't the \"Mist Disaster\" from your world. And these monsters... they aren't the \"Ancient Monsters\" you mentioned."
  },
  AvgDialog_123118_Content_50 = {
    Text = "Mouchette responds while swinging her axe to disperse a humanoid mist attempting to ambush her."
  },
  AvgDialog_123118_Content_51 = {
    Text = "Your optimism is stupid, and some of those ideas are so unrealistically idealistic they make my head hurt, but..."
  },
  AvgDialog_123118_Content_52 = {
    Text = "But there are always some people who insist on trying to save this boring world. <Small:Like you. Like my Investigator...>"
  },
  AvgDialog_123118_Content_53 = {
    Text = "Maybe you two would actually get along?"
  },
  AvgDialog_123118_Content_54 = {
    Text = "Aren't we getting a bit off-topic...? Those people are still waiting for us..."
  },
  AvgDialog_123118_Content_55 = {
    Text = "Then get moving. I want this to be over as soon as possible. I'm going home."
  },
  AvgDialog_123118_Content_56 = {
    Text = "Come on, keep up! Don't fall behind. I'm the fastest vanguard in the A.U.G.E!"
  },
  AvgDialog_123118_Content_57 = {
    Text = "Mouchette's silhouette sprints forward into the heart of the fog. You and Salvador exchange a glance, then follow her."
  },
  AvgDialog_123118_Content_6 = {
    Text = "<Shake:Then... what are they?>"
  },
  AvgDialog_123118_Content_7 = {
    Text = "Mouchette instinctively covers her ears, but it is futile."
  },
  AvgDialog_123118_Content_8 = {
    Text = "The pain and despair seep through the fog into the listener's flesh and bone, striking directly at the soul."
  },
  AvgDialog_123118_Content_9 = {
    Text = "I can sense them. Their souls... they are the people who were sacrificed in the last ritual."
  },
  AvgDialog_123119_Content_1 = {
    Text = "Between Dimensions"
  },
  AvgDialog_123119_Content_10 = {
    Text = "Mouchette shrugs, pointing her thumb at the Dimensional Gate that is constantly spewing dense mist and eroding the world."
  },
  AvgDialog_123119_Content_100 = {
    Text = "No, %player%, wait..."
  },
  AvgDialog_123119_Content_101 = {
    Text = "She reaches out to stop the rescue, her mind a frantic tangle of unanswered questions."
  },
  AvgDialog_123119_Content_102 = {
    Text = "But time has run out. A violent tug at her very essence drags her back from this realm filled with mesmerizing light."
  },
  AvgDialog_123119_Content_103 = {
    Text = "The shimmering light remains behind—steady, distant, and radiating a quiet, final warmth."
  },
  AvgDialog_123119_Content_104 = {
    Text = "Show the @4 information to @3 \"me,\" and you will be able to @2 go home @1."
  },
  AvgDialog_123119_Content_105 = {
    Text = "@2, farewell, Mouchette, @2... my <Italic:other self.>"
  },
  AvgDialog_123119_Content_106 = {
    Text = "The psychic hum twists and dissolves into nothingness, taking her senses along with it."
  },
  AvgDialog_123119_Content_107 = {
    Text = "When the world snaps back into focus, she is staring at the same person—the one she can no longer comprehend."
  },
  AvgDialog_123119_Content_108 = {
    Text = "Mouchette, leave this place. Salvador and I will handle the rest."
  },
  AvgDialog_123119_Content_109 = {
    Text = "The corrosion of the Gateway is deepening. %player%, we need to prepare for the worst..."
  },
  AvgDialog_123119_Content_11 = {
    Text = "So, I must go. Only I can go."
  },
  AvgDialog_123119_Content_110 = {Text = "..."},
  AvgDialog_123119_Content_111 = {
    Text = "Mouchette? What are you dawdling for? You must leave. Quick."
  },
  AvgDialog_123119_Content_112 = {
    Text = "She stares at you, a storm of fury and newfound pity churning in her chest, choking the words in her throat."
  },
  AvgDialog_123119_Content_113 = {
    Text = "Finally, she exhales a sharp, jagged breath and clenches her fists in reluctant surrender."
  },
  AvgDialog_123119_Content_114 = {
    Text = "I should have known from the start. You're exactly the kind of meddlesome \"Protagonist\" I'll never understand."
  },
  AvgDialog_123119_Content_115 = {
    Text = "Even in a hundred years, I wouldn't get how your brain works. So, I give up."
  },
  AvgDialog_123119_Content_116 = {
    Text = "What do you mean?"
  },
  AvgDialog_123119_Content_117 = {
    Text = "I know the frequency you need. It's the other @4@3..."
  },
  AvgDialog_123119_Content_118 = {
    Text = "A sharp pain twists her words into static. After several failed attempts to speak the truth she saw, Mouchette gives up on words."
  },
  AvgDialog_123119_Content_119 = {
    Text = "She takes your hand, her eyes filled with a resolve that is now absolute."
  },
  AvgDialog_123119_Content_12 = {
    Text = "In your words, it's... oh, \"survival wisdom in a cruel world.\""
  },
  AvgDialog_123119_Content_120 = {
    Text = "I'm staying. I'll help you solve this mess."
  },
  AvgDialog_123119_Content_121 = {
    Text = "I, Mouchette, the star vanguard of A.U.G.E., am not ending this battle as a \"deserter.\""
  },
  AvgDialog_123119_Content_13 = {
    Text = "Listening to her, you and Salvador fall into a brief silence, then speak simultaneously—"
  },
  AvgDialog_123119_Content_14 = {
    Text = "I disagree, child. The one who should make the sacrifice is me."
  },
  AvgDialog_123119_Content_15 = {
    Text = "I agree. I promise to bring you back, or send you home, no matter the cost."
  },
  AvgDialog_123119_Content_16 = {
    Text = "Having voiced completely opposite opinions at the same moment, you and Salvador stare at each other."
  },
  AvgDialog_123119_Content_17 = {
    Text = "%player%, why...?"
  },
  AvgDialog_123119_Content_18 = {
    Text = "Then it's settled. I'm counting on you to get me home, %player%."
  },
  AvgDialog_123119_Content_19 = {
    Text = "Mouchette interrupts before you or Salvador can react, walking straight toward the unknown and ominous Gateway."
  },
  AvgDialog_123119_Content_2 = {
    Text = "Mouchette, are you saying you want to enter that unknown \"Gateway\"...?"
  },
  AvgDialog_123119_Content_20 = {
    Text = "You grip the Silver Key in one hand and clutch Salvador's sleeve with the other, fixing your eyes on Mouchette—too focused to even blink."
  },
  AvgDialog_123119_Content_21 = {
    Text = "Salvador, listen. Perhaps... Mouchette is different."
  },
  AvgDialog_123119_Content_22 = {
    Text = "This is the gate to another dimension, and she's from that very dimension. She was even summoned here by this same ritual."
  },
  AvgDialog_123119_Content_23 = {
    Text = "But... what if..."
  },
  AvgDialog_123119_Content_24 = {
    Text = "If anything goes wrong, I will activate the Silver Key and transfer the link to myself."
  },
  AvgDialog_123119_Content_25 = {
    Text = "Salvador looks into your eyes—seeing a forced calm backed by trembling resolve—and then at the Silver Key in your hand. He finally lets out a long sigh."
  },
  AvgDialog_123119_Content_26 = {
    Text = "If that moment comes, please let me share the burden."
  },
  AvgDialog_123119_Content_27 = {
    Text = "Pale Messenger, I won't let you fall before me."
  },
  AvgDialog_123119_Content_28 = {
    Text = "You respond with a smile of silent understanding."
  },
  AvgDialog_123119_Content_29 = {
    Text = "Meanwhile, Mouchette raises her hand to touch the intangible Gate."
  },
  AvgDialog_123119_Content_3 = {
    Text = "Not just you, but even Salvador is stunned into silence."
  },
  AvgDialog_123119_Content_30 = {
    Text = "<Shake:This is...>"
  },
  AvgDialog_123119_Content_31 = {
    Text = "The moment Mouchette's fingers brush the Gateway, it erupts in a blinding, sudden light."
  },
  AvgDialog_123119_Content_32 = {
    Text = "At the same time, you activate the Silver Key."
  },
  AvgDialog_123119_Content_33 = {
    Text = "The brilliance of the Key resonates with the Gateway's glow. Above, the silver and blood obscuring the sky begin to boil and surge as if guided by an invisible force."
  },
  AvgDialog_123119_Content_34 = {
    Text = "The two energies combine into a soul-eroding hum. It's a resonance that merges with the endless mist, assailing everything around and plunging everyone present into a dizzying state of spiritual dissociation..."
  },
  AvgDialog_123119_Content_35 = {
    Text = "The world@2 fades into the void, like @2@1, like a thick mist, @3, something @2 gestates in this void @3."
  },
  AvgDialog_123119_Content_36 = {
    Text = "@1 is just an @2 accident of the Great @4's Dream, yet this tiny @2 writhes, evolves, and transforms into @4 race."
  },
  AvgDialog_123119_Content_37 = {
    Text = "From the darkness, a chaotic and distorted flute melody echoes, tormenting Mouchette's will. Even though it is music, she glimpses a horrifying truth within the notes."
  },
  AvgDialog_123119_Content_38 = {
    Text = "Humans, this is what @3 calls themselves. Compared to the endless @1 universe, @2 is @4 tiny and fleeting."
  },
  AvgDialog_123119_Content_39 = {
    Text = "@3 did not leave @3 behind; the blood and silver of @1 flow through generations, @4@2's traces @1 evidence."
  },
  AvgDialog_123119_Content_4 = {
    Text = "That's right. I'll go in and help you investigate that \"frequency\" thing."
  },
  AvgDialog_123119_Content_40 = {
    Text = "The screeching flute grows sharper, like psychic torture. Mouchette can't endure it any longer; she snaps her eyes open."
  },
  AvgDialog_123119_Content_41 = {
    Text = "There is no flute. No musician. Only a surreal expanse of shimmering light specks swirling around her, keeping a respectful distance. Then, a voice—one she knows—speaks."
  },
  AvgDialog_123119_Content_42 = {
    Text = "Nice to meet you, Mouchette, \"my\" friend."
  },
  AvgDialog_123119_Content_43 = {
    Text = "The light speck vibrates with a low hum. Strangely, she understands it perfectly. Or perhaps... she herself is now one of those specks."
  },
  AvgDialog_123119_Content_44 = {
    Text = "Am I dead? So this is what it feels like to be dead..."
  },
  AvgDialog_123119_Content_45 = {
    Text = "No, you're still alive. I simply brought you here. You carry \"my\" scent."
  },
  AvgDialog_123119_Content_46 = {
    Text = "If I hadn't intervened, the failed dimensional crossing would have @4 you—because you've already been @3"
  },
  AvgDialog_123119_Content_47 = {
    Text = "Mouchette misses the final words; the moment the chaotic syllables sound, her head throbs violently, nearly splitting."
  },
  AvgDialog_123119_Content_48 = {
    Text = "<Shake:STOP! STOP! Say something I can understand... my head is going to explode!>"
  },
  AvgDialog_123119_Content_49 = {
    Text = "She thinks she hears a sigh from the light—or perhaps it's just her imagination. Suddenly, a flood of information pours into her consciousness, seizing her entire attention."
  },
  AvgDialog_123119_Content_5 = {
    Text = "Child, you don't understand the dangers involved. The trauma from the Spirit Realm can affect the real world. You will—"
  },
  AvgDialog_123119_Content_50 = {
    Text = "What is this?"
  },
  AvgDialog_123119_Content_51 = {
    Text = "What you need right now. Show it to the \"me\" in this world, %player% will understand."
  },
  AvgDialog_123119_Content_52 = {
    Text = "I don't get all this \"me\" and \"you\" talk—"
  },
  AvgDialog_123119_Content_53 = {
    Text = "Wait, are you... %player%?"
  },
  AvgDialog_123119_Content_54 = {
    Text = "That's impossible! I just saw you a moment ago—healthy, lively, looking like you'd live another hundred years!"
  },
  AvgDialog_123119_Content_55 = {
    Text = "The light speck hums with a faint chuckle. Mouchette isn't sure if it's a \"laugh,\" as it carries no joy. It carries no emotion at all."
  },
  AvgDialog_123119_Content_56 = {
    Text = "You can understand that as \"me\" in another dimension. And I, the real me—"
  },
  AvgDialog_123119_Content_57 = {
    Text = "As the light speaks, a tidal wave of information surges into Mouchette's mind. The fragments fracture and coalesce, weaving unstable, flickering images."
  },
  AvgDialog_123119_Content_58 = {
    Text = "At first, the visions are abstract and jagged, a blur of static and shadow..."
  },
  AvgDialog_123119_Content_59 = {
    Text = "But soon, the chaos sharpens into a single, familiar silhouette."
  },
  AvgDialog_123119_Content_6 = {
    Text = "I'm the only one suitable for the job. I may not be the sharpest tool in the shed, but I'm not stupid."
  },
  AvgDialog_123119_Content_60 = {
    Text = "She watches {Male=him,Female=her} wake in the heart of a crater, eyes wide and unseeing amidst the settling dust."
  },
  AvgDialog_123119_Content_61 = {
    Text = "Years later, people would call it the \"Yakutsk Explosion.\""
  },
  AvgDialog_123119_Content_62 = {
    Text = "She follows as %player% steps into the halls of Mythag, fingers closing around the Silver Key. She sees %player% become a \"Keeper,\" leading a band of \"Awakeners\" into the throat of a nightmare world."
  },
  AvgDialog_123119_Content_63 = {
    Text = "It is a mirror of her own life—the Investigator, the A.U.G.E. team, and the mission that never ends."
  },
  AvgDialog_123119_Content_64 = {Text = "..."},
  AvgDialog_123119_Content_65 = {
    Text = "Memories of her own world pull a nostalgic sigh from Mouchette's lips, but the vision of %player%'s life marches on."
  },
  AvgDialog_123119_Content_66 = {
    Text = "She treks alongside %player% through the biting frost of a dead town. She stands in a sanitarium choked with secrets, facing the Dimensional Hounds, witnessing the stubborn immortality of family bonds."
  },
  AvgDialog_123119_Content_67 = {
    Text = "She drifts through the poetry and petals of Cité, listening to the sighs buried in a flame, and the wilting of a rose."
  },
  AvgDialog_123119_Content_68 = {
    Text = "Then comes the salt and rot of Sona-Nyl, the ghost ship. Madness masquerading as faith, hungry gods, and the metallic tang of sacrifice. Through %player%'s eyes, she tastes the pure, concentrated distortion of a world gone mad."
  },
  AvgDialog_123119_Content_69 = {
    Text = "No matter how deep the darkness, %player% and the Awakeners never gave up."
  },
  AvgDialog_123119_Content_7 = {
    Text = "Mouchette cuts Salvador off, looking at you both with uncharacteristic gravity."
  },
  AvgDialog_123119_Content_70 = {
    Text = "Just as the Mist, the Griske, and the Artifacts could never truly extinguish the fire in A.U.G.E."
  },
  AvgDialog_123119_Content_71 = {
    Text = "Now that's more like it!"
  },
  AvgDialog_123119_Content_72 = {
    Text = "I wonder how those little guys in the Mist are doing?"
  },
  AvgDialog_123119_Content_73 = {
    Text = "Sigh... I'd really love a hot cup of Hazelnut Kava Tea right now."
  },
  AvgDialog_123119_Content_74 = {
    Text = "Mouchette smiles. She watches %player% and the Awakeners, certain they will fight until the end of time."
  },
  AvgDialog_123119_Content_75 = {
    Text = "It's the only ending that makes sense; she had never planned on leaving A.U.G.E., so why would these people ever leave their Keeper?"
  },
  AvgDialog_123119_Content_76 = {
    Text = "They would struggle and bleed until the world was fixed, or until they became part of the scenery. Just like the heroes in the storybooks."
  },
  AvgDialog_123119_Content_77 = {
    Text = "But this reality is far more jagged and cold than she imagined."
  },
  AvgDialog_123119_Content_78 = {
    Text = "<Shake:How could this happen!!>"
  },
  AvgDialog_123119_Content_79 = {
    Text = "So you're actually...!?"
  },
  AvgDialog_123119_Content_8 = {
    Text = "Salvador, your power is the only thing keeping us safe in this mist. And %player%... clearly, both you and your Silver Key are crucial to this."
  },
  AvgDialog_123119_Content_80 = {
    Text = "You jerk, I shouldn't have expected you to give up on being a boring savior!"
  },
  AvgDialog_123119_Content_81 = {
    Text = "Sacrificing yourself like that... that's..."
  },
  AvgDialog_123119_Content_82 = {
    Text = "The words die in her throat. Rage and frustration are empty weights now."
  },
  AvgDialog_123119_Content_83 = {
    Text = "%player% is her friend, but Mouchette is only a traveler passing through this timeline."
  },
  AvgDialog_123119_Content_84 = {
    Text = "The distance between them is no longer just a \"dimension\". It is the weight of two entirely different worlds."
  },
  AvgDialog_123119_Content_85 = {
    Text = "In fact, my dream is to sit by a cozy fire with the people I love, wasting our worthless lives away."
  },
  AvgDialog_123119_Content_86 = {
    Text = [[
Snow will drift outside the window, year after year, until we pass peacefully.

My headstone would read: %player% was a long-lived, happy fool.]]
  },
  AvgDialog_123119_Content_87 = {
    Text = "And even now... that dream hasn't changed."
  },
  AvgDialog_123119_Content_88 = {
    Text = "Then go live it! Who cares if the world ends? What does it matter if this boring world collapses!?"
  },
  AvgDialog_123119_Content_89 = {
    Text = "It's still better than being trapped here forever—alone, with regrets that never fade!"
  },
  AvgDialog_123119_Content_9 = {
    Text = "If something happens to you, no one else can fix this mess."
  },
  AvgDialog_123119_Content_90 = {
    Text = "The figure made up of light specks chuckles again. This time, the sound is filtered through the bitterness rising in Mouchette's heart."
  },
  AvgDialog_123119_Content_91 = {
    Text = "I want to realize that dream too, I really do."
  },
  AvgDialog_123119_Content_92 = {
    Text = "But... in this cruel world, we always make \"choices,\" choices we might not even understand ourselves."
  },
  AvgDialog_123119_Content_93 = {
    Text = "Perhaps it's not so hard to understand. I've never had Hazelnut Kava Tea, but I have things I love too."
  },
  AvgDialog_123119_Content_94 = {
    Text = "Murphy's cakes, Liz's dances... even the extra homework Doll assigned feels interesting now..."
  },
  AvgDialog_123119_Content_95 = {
    Text = "That's enough. Stop talking. You're just a hopeless..."
  },
  AvgDialog_123119_Content_96 = {
    Text = "Mouchette! Mouchette!"
  },
  AvgDialog_123119_Content_97 = {
    Text = "Suddenly, a voice pierces the silence of her mind. She recognizes it instantly."
  },
  AvgDialog_123119_Content_98 = {
    Text = "Having witnessed the weight of \"%player%'s\" struggle, she knows this voice is now etched into her soul."
  },
  AvgDialog_123119_Content_99 = {
    Text = "Hold on! Salvador and I will get you out! I promised!"
  },
  AvgDialog_123120_Content_1 = {
    Text = "Self-Oblation"
  },
  AvgDialog_123120_Content_10 = {
    Text = "Father Salvador...?"
  },
  AvgDialog_123120_Content_100 = {
    Text = "I don't know how far this thing will spread. If it's really like my world..."
  },
  AvgDialog_123120_Content_101 = {
    Text = "Mouchette doesn't finish the sentence, but you understand her implication."
  },
  AvgDialog_123120_Content_102 = {
    Text = "The Mist Disaster is apparently a catastrophe capable of consuming an entire world."
  },
  AvgDialog_123120_Content_103 = {
    Text = "We must end this ritual at all costs... <Shake:Salvador!>"
  },
  AvgDialog_123120_Content_104 = {
    Text = "I am here. I will ensure your safety... and I will bring these lost souls true salvation..."
  },
  AvgDialog_123120_Content_105 = {
    Text = "A warm, gentle light radiates from Salvador, spreading to you and Mouchette, shielding you from the corruption of the mist."
  },
  AvgDialog_123120_Content_106 = {
    Text = "Mouchette, to close this spatial rift, I need to measure and determine the vibrational frequency of the spiritual dimension. I'm counting on you to handle the fighting."
  },
  AvgDialog_123120_Content_107 = {
    Text = "Fighting? No problem. With me here, you won't lose a single hair!"
  },
  AvgDialog_123120_Content_108 = {
    Text = "I've been holding back for so long, it's time to cut loose—"
  },
  AvgDialog_123120_Content_109 = {
    Text = "Here's everyone's favorite! <Big:SHINING☆TORNADO—!!>"
  },
  AvgDialog_123120_Content_11 = {
    Text = "Salvador takes a deep breath in silence, then exhales heavily."
  },
  AvgDialog_123120_Content_111 = {
    Text = "The axe flies out, shattering a line of humanoid mists and carving a brief, safe path for you to approach the mysterious gate spewing the fog."
  },
  AvgDialog_123120_Content_112 = {
    Text = "You work the measuring instruments frantically, trying to capture the frequencies of the different dimensions."
  },
  AvgDialog_123120_Content_113 = {
    Text = [[
One minute passes.

Two minutes pass.]]
  },
  AvgDialog_123120_Content_114 = {
    Text = "Then three minutes, five, ten..."
  },
  AvgDialog_123120_Content_115 = {
    Text = "Sweat drips from your brow. You have never felt time move so slowly."
  },
  AvgDialog_123120_Content_116 = {
    Text = "How much longer? These monsters feel like they're getting stronger. It takes several hits just to break one apart now..."
  },
  AvgDialog_123120_Content_117 = {
    Text = "That is a sign that the other dimension is attempting to invade and devour our world, isn't it, Pale Messenger?"
  },
  AvgDialog_123120_Content_118 = {
    Text = "Another bead of sweat falls. In your extreme mental strain, you even forget to nod."
  },
  AvgDialog_123120_Content_119 = {
    Text = "The frequency... it keeps shifting..."
  },
  AvgDialog_123120_Content_12 = {
    Text = "There is no need to look for him. Father White... is already here."
  },
  AvgDialog_123120_Content_120 = {
    Text = "It could be the mist itself, or interference from the souls trapped inside... I need more time to filter it out."
  },
  AvgDialog_123120_Content_121 = {
    Text = "You glance at the sky. There are no \"stars\" left to see."
  },
  AvgDialog_123120_Content_122 = {
    Text = "The entire world seems to consist only of the thick mist and the dimensional gate that endlessly spews it forth."
  },
  AvgDialog_123120_Content_123 = {
    Text = "But we don't have time."
  },
  AvgDialog_123120_Content_124 = {
    Text = "You put away the instruments and grip the Silver Key."
  },
  AvgDialog_123120_Content_125 = {
    Text = "It seems we'll have to take a gamble..."
  },
  AvgDialog_123120_Content_126 = {
    Text = "Pale Messenger, are you planning to connect...?"
  },
  AvgDialog_123120_Content_127 = {
    Text = "Salvador frowns, looking at you with disapproval. You remain silent."
  },
  AvgDialog_123120_Content_128 = {
    Text = "Hey, there's an \"Otherworlder\" here, remember? Speak in a language I can actually understand!"
  },
  AvgDialog_123120_Content_129 = {
    Text = "%player% intends to... link directly to that unknown \"Gateway\" to lock onto the dimensional frequency."
  },
  AvgDialog_123120_Content_13 = {
    Text = "The one standing on that altar... is White."
  },
  AvgDialog_123120_Content_130 = {
    Text = "What? That thing is super suspicious! Who knows what it'll do to you? Don't be stupid."
  },
  AvgDialog_123120_Content_131 = {
    Text = "You grip the Silver Key tight and walk toward the shapeless gate, your expression solemn. In this moment, action speaks louder than words."
  },
  AvgDialog_123120_Content_132 = {
    Text = "I really don't get you people... thinking this boring world is still worth saving..."
  },
  AvgDialog_123120_Content_133 = {
    Text = "Unexpectedly, Mouchette reaches out to stop you. She looks at you with a complex expression—as if she is seeing you, and yet seeing someone else through you."
  },
  AvgDialog_123120_Content_134 = {
    Text = "Finally, the internal struggle fades into a smile. She tries to keep her voice light."
  },
  AvgDialog_123120_Content_135 = {
    Text = "Forget it. Since I'm the star vanguard of A.U.G.E., it's only natural for me to be the one at the front—"
  },
  AvgDialog_123120_Content_136 = {
    Text = "So, let me go."
  },
  AvgDialog_123120_Content_137 = {
    Text = "Mouchette looks at you, her expression serious and unwavering."
  },
  AvgDialog_123120_Content_138 = {
    Text = "For the first time since you met her in that cage, she looks truly, deeply sincere."
  },
  AvgDialog_123120_Content_14 = {Text = "What?!"},
  AvgDialog_123120_Content_15 = {
    Text = "In your shock, you turn to stare at White. The man who was once a priest of the Chantry of Life—now a cult leader—continues his impassioned address."
  },
  AvgDialog_123120_Content_16 = {
    Text = "At this moment, we make our choice at the cost of silver and blood, and we shall never regret it."
  },
  AvgDialog_123120_Content_17 = {
    Text = "For the sake of reaching the Serene Realm Free from Dissolution. For the sake of redeeming ourselves in this burning world—"
  },
  AvgDialog_123120_Content_18 = {
    Text = "For the sake of reaching the Serene Realm Free from Dissolution. For the sake of redeeming ourselves in this burning world—"
  },
  AvgDialog_123120_Content_19 = {
    Text = "A dozen cultists swear the oath in unison."
  },
  AvgDialog_123120_Content_2 = {
    Text = "<Shake:This world is burning. This world is collapsing. This world is doomed to destruction.>"
  },
  AvgDialog_123120_Content_20 = {
    Text = "They simultaneously raise their silver-plated daggers—"
  },
  AvgDialog_123120_Content_21 = {Text = "Stop!"},
  AvgDialog_123120_Content_22 = {
    Text = "Even as you shout, the silver blades plunge into the hearts of the sacrifices, sinking deep and twisting with a cruel force."
  },
  AvgDialog_123120_Content_23 = {
    Text = "Blinding crimson sprays from their chests, staining the altar red."
  },
  AvgDialog_123120_Content_24 = {
    Text = "Amidst the blood, you emerge from the shadows to face White—the source of this entire tragedy."
  },
  AvgDialog_123120_Content_25 = {
    Text = "More ignorant fools come to interfere with the All-Father's ritual?"
  },
  AvgDialog_123120_Content_26 = {
    Text = "Ha! You remained indifferent when the Cataclysm struck, yet now that I am leading my brothers and sisters to salvation, you come to stop me—"
  },
  AvgDialog_123120_Content_27 = {
    Text = "The leader of the Sect of Astral Dawn sneers as he looks toward you, but then his pupils suddenly dilate, and he freezes in place."
  },
  AvgDialog_123120_Content_28 = {
    Text = "<Shake:B-Bishop Salvador?!>"
  },
  AvgDialog_123120_Content_29 = {
    Text = "Salvador's face is shrouded in gloom. You notice that beneath his heavy robes, his tall, slender frame is trembling slightly."
  },
  AvgDialog_123120_Content_3 = {
    Text = "<Shake:The only path to salvation is to reach the <Yellow:Serene Realm Free from Dissolution>. It lies above us, amidst the stars of the cosmos.>"
  },
  AvgDialog_123120_Content_30 = {
    Text = "White... my misguided child..."
  },
  AvgDialog_123120_Content_31 = {
    Text = "Oh, I see. This \"lost child\" you are trying to save is actually a cult leader! Haha!"
  },
  AvgDialog_123120_Content_32 = {Text = "Mouchette!"},
  AvgDialog_123120_Content_33 = {
    Text = "Fine, fine, I'll shut up. But even if I don't say it, the facts won't change, right?"
  },
  AvgDialog_123120_Content_34 = {
    Text = "The scene falls into silence. The only sound is the slow trickle of blood across the altar, soaking into the stone floor."
  },
  AvgDialog_123120_Content_35 = {
    Text = "John, James, Anderson... they were all your colleagues."
  },
  AvgDialog_123120_Content_36 = {
    Text = "As a former priest of the Chantry of Life, you should understand why they came to Howick."
  },
  AvgDialog_123120_Content_37 = {
    Text = "...Of course I understand."
  },
  AvgDialog_123120_Content_38 = {
    Text = "Because once, I was just like them! I came here filled with noble ideals!"
  },
  AvgDialog_123120_Content_39 = {
    Text = "White's voice suddenly becomes frantic. He looks at Salvador with a desperate fervor, like a child seeking approval."
  },
  AvgDialog_123120_Content_4 = {
    Text = "<Shake:<Big:Find it! Convert to it! Throw yourselves into it! Only then will our lives welcome the eternal dawn—>>"
  },
  AvgDialog_123120_Content_40 = {
    Text = "And I have fulfilled my promise! I have found the only path to save our brothers and sisters!"
  },
  AvgDialog_123120_Content_41 = {Text = "..."},
  AvgDialog_123120_Content_42 = {
    Text = "Death is not the teaching of the All-Father, White. You have strayed from the path."
  },
  AvgDialog_123120_Content_43 = {
    Text = "<Shake:No! I am still following the All-Father's guidance!>"
  },
  AvgDialog_123120_Content_44 = {
    Text = "The All-Father says, <Italic:We are all His children, sharing in His mercy.> He says, <Italic:Love one another, just as you love yourselves.>"
  },
  AvgDialog_123120_Content_45 = {
    Text = "The All-Father commands, <Italic:The noble among you shall be my emissaries; act in my stead, so that suffering may be eradicated from this earth.>"
  },
  AvgDialog_123120_Content_46 = {
    Text = "...That is correct. Those are indeed the All-Father's words."
  },
  AvgDialog_123120_Content_47 = {
    Text = "And I have done it! I will save my brothers and sisters and eliminate the suffering inflicted upon them!"
  },
  AvgDialog_123120_Content_48 = {
    Text = "I will lead them away from this land of misery! I will guide them to the dawn that shines among the stars, toward the—"
  },
  AvgDialog_123120_Content_49 = {
    Text = "<Yellow:<Big:Serene Realm Free from Dissolution>>."
  },
  AvgDialog_123120_Content_5 = {
    Text = "Inside the cave filled with blasphemous symbols, the leader of the Sect of Astral Dawn delivers a fervent speech. As his voice falls silent, the captives are dragged to the center of the altar."
  },
  AvgDialog_123120_Content_50 = {
    Text = "For the sake of reaching the Serene Realm Free from Dissolution. For the sake of redeeming ourselves in this burning world—"
  },
  AvgDialog_123120_Content_51 = {
    Text = "For the sake of reaching the Serene Realm Free from Dissolution. For the sake of redeeming ourselves in this burning world—"
  },
  AvgDialog_123120_Content_52 = {
    Text = "Just then, a cold sneer cuts through the pious chanting like a needle."
  },
  AvgDialog_123120_Content_53 = {
    Text = "The Serene Realm Free from Dissolution? Are you talking about the world behind that portal?"
  },
  AvgDialog_123120_Content_54 = {
    Text = "What a joke. My world isn't nearly that beautiful."
  },
  AvgDialog_123120_Content_55 = {
    Text = "Mist Disasters, Ancient Monsters, the Griske Legion, and all sorts of mutated horrors. Meeting any one of them is enough to ruin your life."
  },
  AvgDialog_123120_Content_56 = {
    Text = "So quit spouting this \"salvation\" nonsense. You aren't saving anyone—you're just sacrificing others to save your own skins."
  },
  AvgDialog_123120_Content_57 = {
    Text = "<Shake:That's not true! Because—>"
  },
  AvgDialog_123120_Content_58 = {
    Text = "White steps forward toward Mouchette, his hand trembling with emotion as he raises the silver dagger."
  },
  AvgDialog_123120_Content_59 = {
    Text = "You instinctively move to shield Mouchette, but the strike you expected never comes."
  },
  AvgDialog_123120_Content_6 = {
    Text = "You hide in the shadows nearby, carefully confirming the number of sacrifices."
  },
  AvgDialog_123120_Content_60 = {
    Text = "White was going to stab himself from the very beginning."
  },
  AvgDialog_123120_Content_61 = {
    Text = "Blood sprays from White's heart, flowing and merging with the blood of the sacrifices on the crimson altar."
  },
  AvgDialog_123120_Content_62 = {
    Text = "<Shake:Now... we have sufficient silver and blood...>"
  },
  AvgDialog_123120_Content_63 = {
    Text = "As White whispers these words, an invisible shockwave erupts from the altar."
  },
  AvgDialog_123120_Content_64 = {
    Text = "The blood pooling on the stone surface begins to writhe and lift into the air. The bodies of the sacrifices begin to float alongside it."
  },
  AvgDialog_123120_Content_65 = {
    Text = "<Shake:AAAAHHH—Bishop Salvador...>"
  },
  AvgDialog_123120_Content_66 = {
    Text = "<Shake:Do you see...? I have not betrayed... my promise... to the All-Father...>"
  },
  AvgDialog_123120_Content_67 = {
    Text = "White screams in agony, his dying body convulsing. The Silver and blood within him are extracted by an invisible force, painting grotesque patterns across the air."
  },
  AvgDialog_123120_Content_68 = {
    Text = "<Shake:Bishop, I know I have sinned... I will bear the guilt... for myself and for them.>"
  },
  AvgDialog_123120_Content_69 = {
    Text = "<Shake:But I will never regret it... because I have saved my brothers and sisters... from this land of suffering...>"
  },
  AvgDialog_123120_Content_7 = {
    Text = "John, James, Anderson... they are all here."
  },
  AvgDialog_123120_Content_70 = {
    Text = "White's gaze remains fixed on Salvador. And Salvador—the Bishop who once poured his heart into mentoring him—slowly traces the Holy Sign of the All-Father in the air."
  },
  AvgDialog_123120_Content_71 = {
    Text = "Salvador's hand trembles as he suppresses the urge to bestow a \"Blessing.\" His lost child has made his final choice."
  },
  AvgDialog_123120_Content_72 = {
    Text = "I still do not agree with your methods, White, but you have indeed practiced the teachings of the All-Father in your own way. So..."
  },
  AvgDialog_123120_Content_73 = {
    Text = "May the All-Father forgive you. May you... return to His embrace. Escape from the misery, and find your redemption..."
  },
  AvgDialog_123120_Content_74 = {
    Text = "Salvador sighs, offering a final prayer."
  },
  AvgDialog_123120_Content_75 = {
    Text = "But White can no longer hear him. His expression is frozen between a blissful smile and extreme agony as his heart stops beating."
  },
  AvgDialog_123120_Content_76 = {
    Text = "Then, the silver and blood floating in the air surge violently, like countless boiling \"stars\" illuminating the darkness."
  },
  AvgDialog_123120_Content_77 = {
    Text = "Within this blinding, grand light, countless unknown flecks of radiance coalesce, forming an shapeless gate leading to an unknown destination."
  },
  AvgDialog_123120_Content_78 = {
    Text = "Is this the \"Gateway\" they were talking about?"
  },
  AvgDialog_123120_Content_79 = {
    Text = "If I go through it, can I go back to my world?"
  },
  AvgDialog_123120_Content_8 = {
    Text = "Which means we're only missing Father White...?"
  },
  AvgDialog_123120_Content_80 = {
    Text = "It's hard to say. In theory, we can link to the same dimension by simulating the same vibrational frequency, but in practice, accidents happen easily."
  },
  AvgDialog_123120_Content_81 = {
    Text = "Especially with a sacrificial ritual like this. There are too many variables; things can go wrong in an instant—"
  },
  AvgDialog_123120_Content_82 = {
    Text = "Wait, don't go near it!"
  },
  AvgDialog_123120_Content_83 = {
    Text = "You call out to stop the cultists who are marching in unison toward the shapeless gate. They seem deaf to your warning, continuing forward with an eerie, steady pace."
  },
  AvgDialog_123120_Content_84 = {
    Text = "For the sake of reaching the Serene Realm Free from Dissolution. For the sake of redeeming ourselves in this burning world—"
  },
  AvgDialog_123120_Content_85 = {
    Text = "For the sake of reaching the Serene Realm Free from Dissolution. For the sake of redeeming ourselves in this burning world—"
  },
  AvgDialog_123120_Content_86 = {
    Text = "Finally, the first believer reaches out and touches the shapeless gate, stepping into the new world he craves."
  },
  AvgDialog_123120_Content_87 = {
    Text = "<Shake:AAAAHHH—!>"
  },
  AvgDialog_123120_Content_88 = {
    Text = "In a scream of pure despair, the believer's hands begin to twist and melt, dissolving into the sudden burst of intense light."
  },
  AvgDialog_123120_Content_89 = {
    Text = "Endless thick mist gushes from the portal, devouring the flesh and souls of the followers, transforming those who yearned for the stars into part of the \"Stars\" themselves."
  },
  AvgDialog_123120_Content_9 = {Text = "..."},
  AvgDialog_123120_Content_90 = {
    Text = "Your specialized communicator crackles again with static, replaying those familiar death-murmurs:"
  },
  AvgDialog_123120_Content_91 = {
    Text = "@2 I... save @2..."
  },
  AvgDialog_123120_Content_92 = {
    Text = "Save @2... @2 me..."
  },
  AvgDialog_123120_Content_93 = {
    Text = "This is... <Shake:The ritual has gone wrong!>"
  },
  AvgDialog_123120_Content_94 = {
    Text = "Salvador, watch out for the monsters in the mist!"
  },
  AvgDialog_123120_Content_95 = {
    Text = "As you speak, countless humanoid shapes coalesce from the fog, roaring as they charge toward you."
  },
  AvgDialog_123120_Content_96 = {
    Text = "Well, things are finally getting fun."
  },
  AvgDialog_123120_Content_97 = {
    Text = "Mouchette—"
  },
  AvgDialog_123120_Content_98 = {
    Text = "Alright, I'll stop talking. But I have to warn you, the Mist Disaster is spreading fast."
  },
  AvgDialog_123120_Content_99 = {
    Text = "...Pale Messenger, just a moment ago I could still see our surroundings. Now, everything is gone."
  },
  AvgDialog_123121_Content_1 = {
    Text = "Extinguished Stars"
  },
  AvgDialog_123121_Content_10 = {
    Text = "With your strength, you never should have been imprisoned by a few pathetic cultists."
  },
  AvgDialog_123121_Content_11 = {
    Text = "Indeed. And I believe we both noticed how many times you inquired about the timing of the ritual. Your expression... it was quite clear you were anticipating something."
  },
  AvgDialog_123121_Content_12 = {
    Text = "Ah, so that's where I slipped up. Careless of me."
  },
  AvgDialog_123121_Content_13 = {
    Text = "So, who are you really? What is this ritual, and what do you know about it?"
  },
  AvgDialog_123121_Content_14 = {
    Text = "Mouchette flashes a casual smile and answers with a question instead:"
  },
  AvgDialog_123121_Content_15 = {
    Text = "What about you two? Why did you come to a place like this, where the secular order has completely collapsed and nothing remains but tedious beliefs?"
  },
  AvgDialog_123121_Content_16 = {
    Text = "Salvador does not take offense at her remark. Instead, he looks at her with genuine compassion."
  },
  AvgDialog_123121_Content_17 = {
    Text = "I come for the sake of salvation."
  },
  AvgDialog_123121_Content_18 = {
    Text = "Salvation? For whom? For those \"cattle\" in the cage? With all due respect, sometimes a swift death is far kinder than a miserable life."
  },
  AvgDialog_123121_Content_19 = {
    Text = "Especially in a world as... hmm, thrilling and amusing as this one."
  },
  AvgDialog_123121_Content_2 = {
    Text = "After sending a signal to the Chantry, you and Salvador wait outside the cave for the strange girl who calls herself Mouchette."
  },
  AvgDialog_123121_Content_20 = {
    Text = "The All-Father's blessing is shed upon every corner that yearns for redemption."
  },
  AvgDialog_123121_Content_21 = {
    Text = "Those prisoners cried out to me and the Chantry for aid in their suffering, and we shall answer their pleas."
  },
  AvgDialog_123121_Content_22 = {
    Text = "As an emissary of the All-Father, I will do everything in my power to eradicate such misery from this earth."
  },
  AvgDialog_123121_Content_23 = {
    Text = [[
Salvador lowers his head and clasps his hands in devout prayer.
In response, Mouchette lets out a soft, mocking chuckle.]]
  },
  AvgDialog_123121_Content_24 = {
    Text = "I take it you're both \"good people\" in the boring, mundane sense, believing in all that nonsense like \"love thy neighbor\" and \"everyone loves me,\" right?"
  },
  AvgDialog_123121_Content_25 = {
    Text = "That's why you trusted me so easily and followed me out here..."
  },
  AvgDialog_123121_Content_26 = {
    Text = "Honestly, your naivety is enough to give me a headache."
  },
  AvgDialog_123121_Content_27 = {
    Text = "You cannot tell if her expression is one of mockery or melancholy, as a wisp of mist drifting from nowhere suddenly obscures her face."
  },
  AvgDialog_123121_Content_28 = {
    Text = "You're wrong. We simply choose not to assume the worst of a stranger."
  },
  AvgDialog_123121_Content_29 = {
    Text = "Aye, whatever. It doesn't matter anyway. You couldn't possibly understand..."
  },
  AvgDialog_123121_Content_3 = {
    Text = "To your surprise, when she finally emerges from the shadows, she is carrying a sleek, stylishly designed axe."
  },
  AvgDialog_123121_Content_30 = {
    Text = "A sudden, sharp mechanical clicking sound interrupts her words."
  },
  AvgDialog_123121_Content_31 = {
    Text = "The communicator is picking up spiritual fluctuations... the source is... the mist?!"
  },
  AvgDialog_123121_Content_32 = {
    Text = "Without warning, the wisp of mist begins to expand rapidly. It swallows Mouchette's figure and begins to shroud the surrounding landscape in a thick, white veil."
  },
  AvgDialog_123121_Content_33 = {
    Text = "Spiritual fluctuations? So that's how you explain the Mist Disaster here..."
  },
  AvgDialog_123121_Content_34 = {
    Text = "The Mist Disaster?"
  },
  AvgDialog_123121_Content_35 = {
    Text = "Of course. This dying world wouldn't have something this interesting on its own. It comes from—"
  },
  AvgDialog_123121_Content_36 = {
    Text = "From <Yellow:my world>."
  },
  AvgDialog_123121_Content_37 = {
    Text = "Your world...?"
  },
  AvgDialog_123121_Content_38 = {
    Text = "Those fools in the Sect of Astral Dawn opened a forbidden portal that never should have been touched."
  },
  AvgDialog_123121_Content_39 = {
    Text = "Then the ritual went <Italic:SNAP!> and failed, leaving only me, the unlucky one, and these persistent things—"
  },
  AvgDialog_123121_Content_4 = {
    Text = "How is it? Isn't it cool?"
  },
  AvgDialog_123121_Content_40 = {
    Text = "Just a friendly reminder: you might want to start thinking about when to start running."
  },
  AvgDialog_123121_Content_41 = {
    Text = "Running from what?"
  },
  AvgDialog_123121_Content_42 = {
    Text = "Hehe☆... the little ones in the mist are coming soon~"
  },
  AvgDialog_123121_Content_43 = {
    Text = "Have fun, you guys."
  },
  AvgDialog_123121_Content_44 = {
    Text = "With that, Mouchette steps back and vanishes into the heavy fog, her voice drifting away into the gloom."
  },
  AvgDialog_123121_Content_45 = {
    Text = "Also, thanks for the help earlier. One good turn deserves another, right? This time, you two can buy some time for me~"
  },
  AvgDialog_123121_Content_46 = {
    Text = "...Mouchette, wait!?"
  },
  AvgDialog_123121_Content_47 = {
    Text = "You move to stop her, but the fog is so dense you have no idea where to even begin the pursuit."
  },
  AvgDialog_123121_Content_48 = {
    Text = "You grasp your Silver Key, preparing to activate Spirit Tracing, when the communicator shrieks again."
  },
  AvgDialog_123121_Content_49 = {
    Text = "It is a harsh, distorted sound of electrical interference that grows louder and more agonizing as the mist surges."
  },
  AvgDialog_123121_Content_50 = {
    Text = "@2 I... save @2..."
  },
  AvgDialog_123121_Content_51 = {Text = "...?!"},
  AvgDialog_123121_Content_52 = {
    Text = "Salvador, did you hear that?"
  },
  AvgDialog_123121_Content_53 = {
    Text = "It sounded like... a human voice?"
  },
  AvgDialog_123121_Content_54 = {
    Text = "You raise the communicator, waiting for the sound to repeat. The device responds with a piercing scream of utter despair."
  },
  AvgDialog_123121_Content_55 = {
    Text = "It feels like a jagged blade stabbing into your brain, leaving you dizzy and disoriented."
  },
  AvgDialog_123121_Content_56 = {
    Text = "Simultaneously, countless humanoid shapes churn out of the fog, roaring as they lunge toward you and Salvador."
  },
  AvgDialog_123121_Content_57 = {Text = "Watch out!"},
  AvgDialog_123121_Content_58 = {
    Text = "Salvador's stone tablets dart through the gloom, shattering the mist-monsters, but the agonizing screams persist, assaulting your very soul."
  },
  AvgDialog_123121_Content_59 = {
    Text = "Blood begins to drip from your nose, splattering onto the ground, but your vision is too blurred by the vertigo to see it clearly."
  },
  AvgDialog_123121_Content_6 = {
    Text = "Mouchette swings the axe several times with clean, effortless precision, as if the massive weapon is a natural extension of her own body."
  },
  AvgDialog_123121_Content_60 = {
    Text = "Your spirit feels as though it is detaching from your flesh, expanding into a chaotic, formless state that senses the entire village at once."
  },
  AvgDialog_123121_Content_61 = {
    Text = "You feel it—the mist is everywhere, wantonly devouring the land, the buildings, and every trace of life."
  },
  AvgDialog_123121_Content_62 = {
    Text = "And within this boundless white void, you sense countless stars burning with a cold, silent fire, long dead and full of grief."
  },
  AvgDialog_123121_Content_63 = {Text = "%player%!"},
  AvgDialog_123121_Content_64 = {
    Text = "Salvador's voice echoes in your mind, but the despair welling up from the depths of your soul paralyzes you."
  },
  AvgDialog_123121_Content_65 = {
    Text = "@2 I... save @2..."
  },
  AvgDialog_123121_Content_66 = {
    Text = "Save @2... @2 me..."
  },
  AvgDialog_123121_Content_67 = {
    Text = "Those dead stars encircle you, heavy with infinite agony. They stubbornly attempt to melt your consciousness and corrode your will, dragging you down into an eternal, frozen slumber."
  },
  AvgDialog_123121_Content_68 = {
    Text = "...I can't fall asleep... Sal..."
  },
  AvgDialog_123121_Content_69 = {
    Text = "Sal... vador... help me..."
  },
  AvgDialog_123121_Content_7 = {
    Text = "Having noticed the weapon, you decide to press her."
  },
  AvgDialog_123121_Content_70 = {
    Text = "Just then, a gentle light blazes through your world. Like a warm sun, it wraps you in a steady embrace, driving away the cold and the stench of death."
  },
  AvgDialog_123121_Content_71 = {
    Text = "It is Salvador's radiance."
  },
  AvgDialog_123121_Content_72 = {
    Text = "He has heard your plea."
  },
  AvgDialog_123121_Content_73 = {
    Text = "He has answered."
  },
  AvgDialog_123121_Content_74 = {
    Text = "<Shake:Cough, cough...>"
  },
  AvgDialog_123121_Content_75 = {
    Text = "With Salvador's help, you finally snap out of the dizzying haze. You gasp for air, feeling your sanity slowly return."
  },
  AvgDialog_123121_Content_76 = {
    Text = "Father Salvador, you can stop the Blessing now. I'm... I'm much better."
  },
  AvgDialog_123121_Content_77 = {
    Text = "Salvador nods, but his focus remains on the unseen threats lurking in the fog."
  },
  AvgDialog_123121_Content_78 = {
    Text = "These monsters in the mist do not die. Even when shattered, they reform almost instantly."
  },
  AvgDialog_123121_Content_79 = {
    Text = "I fear that as long as this mist remains, these creatures will never truly perish."
  },
  AvgDialog_123121_Content_8 = {
    Text = "Mouchette, you let the cultists capture you on purpose."
  },
  AvgDialog_123121_Content_80 = {
    Text = "Father Salvador, do you believe... that what Mouchette said is true?"
  },
  AvgDialog_123121_Content_81 = {
    Text = "From the moment we met, Miss Mouchette's soul-fire has remained constant. In my sight, she has shown neither the demeanor nor the motive of a liar."
  },
  AvgDialog_123121_Content_82 = {
    Text = "Then I have a few theories of my own. But first, we have to find her."
  },
  AvgDialog_123121_Content_83 = {
    Text = "I respect your decision, Pale Messenger."
  },
  AvgDialog_123121_Content_84 = {
    Text = "Do not fear the monsters in the mist; I will ensure your safety."
  },
  AvgDialog_123121_Content_85 = {
    Text = "You look at Salvador with gratitude before reaching for the Silver Key."
  },
  AvgDialog_123121_Content_86 = {
    Text = "Blood drips down your cheek again, but you ignore it. The terrifying realization you glimpsed during your vertigo now occupies your entire mind."
  },
  AvgDialog_123121_Content_87 = {
    Text = "@2 I... save @2..."
  },
  AvgDialog_123121_Content_88 = {
    Text = "Save @2... @2 me..."
  },
  AvgDialog_123121_Content_89 = {
    Text = "Finally, as the communicator shrieks once more, you reach through the cold, dead stars and make contact with Mouchette's spirit."
  },
  AvgDialog_123121_Content_9 = {
    Text = "Hmm? Are you joking? Normal people don't volunteer to be a cultist's prisoner, locked in a cage without food or water."
  },
  AvgDialog_123122_Content_1 = {
    Text = "Through Thy Gaze"
  },
  AvgDialog_123122_Content_10 = {
    Text = "I'm busy right now. I don't have time for boring games of house, and I have zero interest in playing the role of the \"rebellious daughter\" being lectured."
  },
  AvgDialog_123122_Content_11 = {
    Text = "You don't understand this world, nor do you know the true danger of those cultists' ritual."
  },
  AvgDialog_123122_Content_12 = {
    Text = "The prisoners you were locked up with are all essential sacrifices for the next rite."
  },
  AvgDialog_123122_Content_13 = {
    Text = "Moreover, even if the ritual is held again, you have no way of knowing if the portal between worlds will actually reopen—or if you could even survive the passage back to your own world."
  },
  AvgDialog_123122_Content_14 = {
    Text = "Mouchette freezes. She bites her lip hard."
  },
  AvgDialog_123122_Content_15 = {Text = "..."},
  AvgDialog_123122_Content_16 = {
    Text = "Child, I know you did not come to this cruel world by choice, and I understand your longing to return home."
  },
  AvgDialog_123122_Content_17 = {
    Text = "We only wish to help you... so you won't stray onto a darker path."
  },
  AvgDialog_123122_Content_18 = {
    Text = "Are you saying that my plan to use their ritual to go home... is the wrong, \"darker\" path?"
  },
  AvgDialog_123122_Content_19 = {
    Text = "Mouchette's temporary hesitation vanishes as her attitude hardens again. Her seemingly cheerful tone is now laced with sharp sarcasm."
  },
  AvgDialog_123122_Content_2 = {
    Text = "How did you all find me?!"
  },
  AvgDialog_123122_Content_20 = {
    Text = "The surrounding fog begins to churn and surge."
  },
  AvgDialog_123122_Content_21 = {
    Text = "Then what is the \"right\" path? Who gets to define it? You? Or your God?"
  },
  AvgDialog_123122_Content_22 = {
    Text = "The mask has finally slipped. Mouchette no longer hides her disdain and contempt for Salvador."
  },
  AvgDialog_123122_Content_23 = {
    Text = "So what if you've judged what is right and wrong? From what I can see, this world is even more barren and pathetic than Temurahn."
  },
  AvgDialog_123122_Content_24 = {
    Text = "When those \"cattle\" were suffering, where was this \"All-Father\" of yours?"
  },
  AvgDialog_123122_Content_25 = {
    Text = "The mist surges violently, obscuring Mouchette's face and hiding Salvador's expression."
  },
  AvgDialog_123122_Content_26 = {
    Text = "The only thing you can hear in the gloom is Salvador's heavy sigh and the eerie, rhythmic scraping that signals the approach of danger."
  },
  AvgDialog_123122_Content_27 = {Text = "I..."},
  AvgDialog_123122_Content_28 = {
    Text = "Speak your mind, Father. It's not like we have anything else to do while we wait."
  },
  AvgDialog_123122_Content_29 = {
    Text = "No sooner has Mouchette finished speaking than countless humanoid shapes burst from the surrounding mist, charging toward you."
  },
  AvgDialog_123122_Content_3 = {
    Text = "Did something go wrong with the Mist? Or do you also have the ability to see through the Mist, just like the <Italic:Investigator>?"
  },
  AvgDialog_123122_Content_30 = {
    Text = "But Mouchette moves faster. Seeing her about to slip away again, you shout out."
  },
  AvgDialog_123122_Content_31 = {
    Text = "Salvador, stop her!"
  },
  AvgDialog_123122_Content_4 = {
    Text = "Mouchette's astonishment does not last long; in an instant, her expression becomes calm."
  },
  AvgDialog_123122_Content_5 = {
    Text = "You certainly have your ways of escaping the Ancient Monsters in the Mist. But—"
  },
  AvgDialog_123122_Content_6 = {
    Text = "<Big:<Shake:Don't you dare get in my way!>>"
  },
  AvgDialog_123122_Content_7 = {
    Text = "Mouchette grips her axe tightly, her gaze filled with vigilance and hostility."
  },
  AvgDialog_123122_Content_8 = {
    Text = "Mouchette, you don't have to do this. We are not your enemies. At least, not right now."
  },
  AvgDialog_123122_Content_9 = {
    Text = "But before you make your decision, there is something I must tell you."
  },
  AvgDialog_125040_Content_1 = {
    Text = "The flooding of the Holy River has brought unprecedented trouble to Mythag. Unexpectedly, Xu's room has become one of the few places where you can take refuge."
  },
  AvgDialog_125040_Content_10 = {
    Text = "I can be a lie, a fleeting desire, but when I am only myself... it becomes utterly dull."
  },
  AvgDialog_125040_Content_11 = {Text = "Uh... Xu?"},
  AvgDialog_125040_Content_12 = {Text = "Mist."},
  AvgDialog_125040_Content_13 = {
    Text = "Delicate as silk, fine as thread, the mist coils around you in layers."
  },
  AvgDialog_125040_Content_14 = {
    Text = "<Gray:Wait, weren't you unaffected? Weren't we just chatting and playing Weiqi?! Why do you Awakeners always say one thing and do another?!>"
  },
  AvgDialog_125040_Content_15 = {
    Text = "A shimmering, gilded wisp flashes at the edge of your vision. Something smooth as satin coils around your arms and back, gently guiding you to lift the curtain woven from mist."
  },
  AvgDialog_125040_Content_16 = {
    Text = "Oh dear, it's just that I am truly, truly curious."
  },
  AvgDialog_125040_Content_17 = {
    Text = "When they touch me, they touch only an illusion. When they look at me, they are gazing at someone else they \"believe\" they love."
  },
  AvgDialog_125040_Content_18 = {
    Text = "But you are different. Are you projecting someone else's shadow onto me? If you delve deeper, whose face will you see beneath my fan...?"
  },
  AvgDialog_125040_Content_19 = {
    Text = "The mist parts. Beneath the fan, something warm gently brushes the tip of your nose. The feathered tassels on her shoulder cascade down, softly caressing your trembling skin."
  },
  AvgDialog_125040_Content_2 = {
    Text = "The Holy River hasn't affected you at all?"
  },
  AvgDialog_125040_Content_20 = {
    Text = "<Gray:Great. Scorching hot—another one affected by the Holy River.>"
  },
  AvgDialog_125040_Content_21 = {
    Text = "Xu, if I recall correctly, you just said you had \"no stray thoughts.\""
  },
  AvgDialog_125040_Content_22 = {
    Text = "Well... In the far east, when a monarch has important matters to discuss, they'd invite their guest into their command tent—thus the term <Italic:\"guest admitted into the curtain.\">"
  },
  AvgDialog_125040_Content_23 = {
    Text = "Though, of course, when spoken of a woman, the phrase takes on another meaning entirely."
  },
  AvgDialog_125040_Content_24 = {Text = "Tap."},
  AvgDialog_125040_Content_25 = {
    Text = "A drop of molten candle wax falls onto the table; the go stones scatter in disarray."
  },
  AvgDialog_125040_Content_26 = {
    Text = "The light goes out."
  },
  AvgDialog_125040_Content_27 = {
    Text = "I've always remained beyond the fray. Yet you might be the one who finally sees me."
  },
  AvgDialog_125040_Content_28 = {
    Text = "Only for you would I willingly sit within these curtains, for you are the guest who may matter most in my life. How could I possibly have any \"stray thoughts\" then?"
  },
  AvgDialog_125040_Content_29 = {
    Text = "The restraints vanish. This ancient and mysterious deity has clearly left you a path of retreat."
  },
  AvgDialog_125040_Content_3 = {
    Text = "Perhaps it's because my power also stems from the three great Aeons, or perhaps because I am simply too skilled in the art of pleasure—I seem to have no stray thoughts."
  },
  AvgDialog_125040_Content_30 = {
    Text = "And with it, a barely audible, ambiguously playful invitation, brimming with delight."
  },
  AvgDialog_125040_Content_31 = {
    Text = "Remember that novel? <Italic:\"I have fallen into the abyss, seeking a shore I cannot reach...\">"
  },
  AvgDialog_125040_Content_4 = {
    Text = "Her beautiful eyes brim with smiles. Several white Weiqi stones click lightly against the board. Xu seems quite fond of this ancient game from the far east."
  },
  AvgDialog_125040_Content_5 = {
    Text = "Humans are such strange creatures. They lose all composure for a fleeting moment of bliss, only to grow instantly bored once they've claimed it."
  },
  AvgDialog_125040_Content_6 = {
    Text = "The more they see of one another, the less they wish to see. Only by weaving illusions for them, luring them to sacrifice their lives, to rip out their own hearts for love, can I leave a lasting impression."
  },
  AvgDialog_125040_Content_7 = {
    Text = "The flickering candlelight traces her faint, shadowy silhouette as she sits gracefully on the bed."
  },
  AvgDialog_125040_Content_8 = {
    Text = "The sky has dimmed before you could noticed She lets out a soft laugh."
  },
  AvgDialog_125040_Content_9 = {
    Text = "They all love ruining the virgins, and \"saving\" the wh@1res—oh, I am most adept at this little drama. I give them the perfect story—half truth, half lie, then with a flick of my fan... I give them a glimpse: It will make them ache with guilt, or burn with unrequited love."
  },
  AvgDialog_126907_Content_1 = {
    Text = "Yesteryear's Sparkles"
  },
  AvgDialog_126907_Content_10 = {
    Text = "Then, by all means."
  },
  AvgDialog_126907_Content_11 = {
    Text = "Elsa's eyes light up. She grabs your hand and, before you can even take your stance, launches into the dance with startling speed."
  },
  AvgDialog_126907_Content_12 = {
    Text = "Her strength is so overwhelming that she nearly flings you across the room. In a panic, she yanks you back with raw force."
  },
  AvgDialog_126907_Content_13 = {
    Text = "<Shake:I-I'm so sorry,> Lord Dexter! I'll do better next time, I promise..."
  },
  AvgDialog_126907_Content_14 = {
    Text = "You feel like a spinning top being whipped round and round in dizzying circles. Your already clumsy footwork becomes a total disaster."
  },
  AvgDialog_126907_Content_15 = {Text = "Pfft."},
  AvgDialog_126907_Content_16 = {
    Text = "Witnessing your plight, Ramona can't help but let out a soft chuckle."
  },
  AvgDialog_126907_Content_17 = {
    Text = "You meet her eyes, feeling the mirth in her gaze whisper to you—"
  },
  AvgDialog_126907_Content_18 = {
    Text = "Lord Dexter, you've finally met your match."
  },
  AvgDialog_126907_Content_19 = {Text = "..."},
  AvgDialog_126907_Content_2 = {
    Text = "In the ballroom, boys and girls in school uniforms whirl gracefully across the dance floor. The music flows like water, caressing their clasped palms, fluttering skirts, and exchanged glances."
  },
  AvgDialog_126907_Content_20 = {
    Text = "The song ends. You hastily kiss your partner's hand in farewell and head straight toward Ramona."
  },
  AvgDialog_126907_Content_21 = {
    Text = "I recall you being known as the most elegant ballroom dancer in all of Mythag, Lord Dexter."
  },
  AvgDialog_126907_Content_22 = {
    Text = "You rack your brain, trying to mimic Lord Dexter's smooth, glib reply."
  },
  AvgDialog_126907_Content_23 = {
    Text = "Well, if there were a \"Dance with Elsa\" contest, I'd still come out on top."
  },
  AvgDialog_126907_Content_24 = {
    Text = "Ramona looks away, gently swirling the glass in her hand."
  },
  AvgDialog_126907_Content_25 = {
    Text = "Elsa really admires you. Even if the dance wasn't perfect, it probably fulfilled her Spring Festival wish."
  },
  AvgDialog_126907_Content_26 = {
    Text = "Pity the one who danced with her wasn't the real Lord Dexter."
  },
  AvgDialog_126907_Content_27 = {
    Text = "Worse still, the man she knows has never been the real Lord Dexter, with or without you \"possessing\" his body today."
  },
  AvgDialog_126907_Content_28 = {
    Text = "But that's not the topic you want to broach."
  },
  AvgDialog_126907_Content_29 = {
    Text = "Ramona, what's your Spring Festival wish?"
  },
  AvgDialog_126907_Content_3 = {
    Text = "You notice Ramona standing alone by a small table at the edge of the dance floor, sipping an unknown drink."
  },
  AvgDialog_126907_Content_30 = {
    Text = "Changing the subject already? Skipping hellos to this lady or that, now you care for your adopted daughter?"
  },
  AvgDialog_126907_Content_31 = {
    Text = "I noticed you haven't danced yet. No one catches your eye?"
  },
  AvgDialog_126907_Content_32 = {
    Text = "No need to trouble yourself."
  },
  AvgDialog_126907_Content_33 = {
    Text = "Care to grace your lonely old man with a dance?"
  },
  AvgDialog_126907_Content_34 = {
    Text = "Ramona goes quiet. You can practically see her searching her mind for an excuse to refuse."
  },
  AvgDialog_126907_Content_35 = {
    Text = "The person you're waiting for... would want you to say yes to this dance."
  },
  AvgDialog_126907_Content_36 = {
    Text = "How do you know?"
  },
  AvgDialog_126907_Content_37 = {Text = "I just do."},
  AvgDialog_126907_Content_38 = {
    Text = "An even longer silence."
  },
  AvgDialog_126907_Content_39 = {
    Text = "Fine. I'll take your word for it. Just this once."
  },
  AvgDialog_126907_Content_4 = {
    Text = "You're pondering how to start a conversation when a timid voice pipes up beside you."
  },
  AvgDialog_126907_Content_40 = {
    Text = "She steps gracefully onto the dance floor, her slender fingers resting in your palm."
  },
  AvgDialog_126907_Content_41 = {
    Text = "Come on. I've never danced with you before."
  },
  AvgDialog_126907_Content_42 = {Text = "..."},
  AvgDialog_126907_Content_43 = {
    Text = "Ramona's steps are just like her—rational, restrained, precise, and meticulous."
  },
  AvgDialog_126907_Content_44 = {
    Text = "Loosen up a little. You're treating the dance floor like a battlefield."
  },
  AvgDialog_126907_Content_45 = {
    Text = "And you could focus a bit more, my lord. You've nearly stepped on my toes three times already."
  },
  AvgDialog_126907_Content_46 = {
    Text = "That hardly seems like Lord Dexter, the social butterfly of decades."
  },
  AvgDialog_126907_Content_47 = {
    Text = "Maybe sometimes... I feel like playing a different role?"
  },
  AvgDialog_126907_Content_48 = {
    Text = "Is that so?"
  },
  AvgDialog_126907_Content_49 = {
    Text = "You know, you've been unusually quiet today."
  },
  AvgDialog_126907_Content_5 = {
    Text = "<Shake:<Small:Lord Dexter... May I have this dance with you?>>"
  },
  AvgDialog_126907_Content_50 = {
    Text = "<LightGray:(I thought I was staying well in character...)>"
  },
  AvgDialog_126907_Content_51 = {
    Text = "Really? Must be the cold weather. It kills the urge to chat."
  },
  AvgDialog_126907_Content_52 = {
    Text = "The real Lord Dexter should say: \"Flirting with one's adopted daughter is quite the taboo, you know.\""
  },
  AvgDialog_126907_Content_53 = {
    Text = "<Yellow:Who are you, really?>"
  },
  AvgDialog_126907_Content_54 = {
    Text = "Ramona, our time together is so short. I don't want to..."
  },
  AvgDialog_126907_Content_55 = {
    Text = "A soft cough from Xu cuts you off."
  },
  AvgDialog_126907_Content_56 = {
    Text = "Never mind that—look!"
  },
  AvgDialog_126907_Content_59 = {
    Text = "In an instant, fireworks whistle into the night sky."
  },
  AvgDialog_126907_Content_6 = {
    Text = "Hmm? Why is that?"
  },
  AvgDialog_126907_Content_62 = {
    Text = "Blossoms of fire and gold bloom overhead in an unbroken chain."
  },
  AvgDialog_126907_Content_64 = {
    Text = "Just like that day at the Keybestowal Ceremony, you take Ramona's hand."
  },
  AvgDialog_126907_Content_66 = {
    Text = "Ignoring her startled expression, you close your eyes."
  },
  AvgDialog_126907_Content_68 = {
    Text = "In the darkness, a chorus of joyful, hopeful voices rises:"
  },
  AvgDialog_126907_Content_69 = {
    Text = "<Big:<Shake:\"Happy Spring Festival!\">>"
  },
  AvgDialog_126907_Content_7 = {
    Text = "No one else wants to dance with me... They say it's too dangerous."
  },
  AvgDialog_126907_Content_70 = {
    Text = "Happy Spring Festival, Ramona."
  },
  AvgDialog_126907_Content_71 = {
    Text = "Midnight has come, the wind howls, and all the stories that were meant to belong to you are drifting away from you."
  },
  AvgDialog_126907_Content_72 = {
    Text = "But you know, the day of reunion is no longer far away."
  },
  AvgDialog_126907_Content_8 = {
    Text = "But don't worry! I'll do my best to control my strength!"
  },
  AvgDialog_126907_Content_9 = {
    Text = "Your eyes sweep over the nervous little girl before you."
  },
  AvgDialog_126908_Content_1 = {
    Text = "Lightless Cabin"
  },
  AvgDialog_126908_Content_10 = {
    Text = "Her smile and form flicker and dissolve, scattering like ash into the wind."
  },
  AvgDialog_126908_Content_11 = {
    Text = "Go on. Claim your prize."
  },
  AvgDialog_126908_Content_12 = {
    Text = "Beyond the mist and ash, a door emerges—the door to the driver's cab."
  },
  AvgDialog_126908_Content_13 = {
    Text = "No tricks, no hidden mechanisms, nothing superfluous."
  },
  AvgDialog_126908_Content_14 = {
    Text = "It is simply an ordinary door, like any other of its kind, serving the function of \"entry and exit,\" waiting for you at the end of the puzzle."
  },
  AvgDialog_126908_Content_15 = {
    Text = "You take a deep breath, clutch the Silver Key, and push the door open."
  },
  AvgDialog_126908_Content_16 = {Text = "..."},
  AvgDialog_126908_Content_17 = {
    Text = "<LightGray:(No more corpses, no dismantled crew members—I'm almost unnerved by the quiet.)>"
  },
  AvgDialog_126908_Content_18 = {Text = "Hmm?"},
  AvgDialog_126908_Content_19 = {
    Text = "A wisp of mist cascades from the console, gently spreading into a silken handkerchief shimmering with soft luster. Written upon it, in Londinium script that feels entirely out of place with its elegant style, is a message:"
  },
  AvgDialog_126908_Content_2 = {Text = "Car 1"},
  AvgDialog_126908_Content_20 = {
    Text = "My dearest Keeper,\n\nSince you have made it this far, you must have uncovered this train's secret—it is an Artificial Domain crafted by N. By now, the \"me\" on this train is dead.\n\nI watched as each of you spoke of your homelands. Winkle and Tinct... their homes have long since been reduced to nothing. I had once considered Miryam, but upon closer examination, the Lemuria she described is a past beyond recovery."
  },
  AvgDialog_126908_Content_21 = {
    Text = "And where do I wish to return? I suppose... it is the true Dreamless Land. All of them, all of us... have long since had no home to return to. \n\nBut you, only you, %player%—the Mythag University you long for still exists, and there are still people there waiting for your return. \n\nTherefore, you must become the final winner of this game.\n\nSo, I offer this victory to you, with my own death as its footnote. \nSimply pull the lever beside you, and it will carry you to the place where those people await."
  },
  AvgDialog_126908_Content_22 = {
    Text = "May both you and I attain what we desire.\n\n\n—Xu"
  },
  AvgDialog_126908_Content_23 = {
    Text = "Feels like some twisted prank fitting N's malicious nature..."
  },
  AvgDialog_126908_Content_24 = {
    Text = "You mutter under your breath, trying to shake the impulse out of your head."
  },
  AvgDialog_126908_Content_25 = {
    Text = "But the temptation is simply too great—familiar faces flash through your thoughts, until one figure stands out clearly..."
  },
  AvgDialog_126908_Content_26 = {Text = "Ramona..."},
  AvgDialog_126908_Content_27 = {
    Text = "Your thundering heartbeat overwhelms your senses. Before reason can catch up, your body has already moved. You thrust the lever forward."
  },
  AvgDialog_126908_Content_28 = {
    Text = "The train lurches violently, accelerating as it hurtles toward the black void ahead."
  },
  AvgDialog_126908_Content_29 = {
    Text = "Seconds later, at the end of the tunnel a hundred meters away, a sheer cliff face looms into view."
  },
  AvgDialog_126908_Content_3 = {
    Text = "At the far end of Car 1, a slender figure awaits in silence, her face veiled by a fan."
  },
  AvgDialog_126908_Content_30 = {
    Text = "You've got to be kidding me..."
  },
  AvgDialog_126908_Content_31 = {
    Text = "In a panic, you yank the lever backward with all your strength, but it sticks fast, refusing to budge. The cliff rushes toward you at over a hundred kilometers per hour."
  },
  AvgDialog_126908_Content_32 = {
    Text = "<Red:I'm going to crash...>"
  },
  AvgDialog_126908_Content_33 = {
    Text = "You close your eyes helplessly, waiting for the impact."
  },
  AvgDialog_126908_Content_34 = {
    Text = "<Shake:So damn cheap... Why was I stupid enough to trust any avatar of N...?>"
  },
  AvgDialog_126908_Content_35 = {Text = "BOOM—!!!"},
  AvgDialog_126908_Content_36 = {
    Text = "The moment the train strikes, weightlessness seizes you and drags you downward."
  },
  AvgDialog_126908_Content_37 = {Text = "!!! Ugh!!"},
  AvgDialog_126908_Content_38 = {
    Text = "Time passes. You don't know how long."
  },
  AvgDialog_126908_Content_39 = {Text = "..."},
  AvgDialog_126908_Content_4 = {
    Text = "Allow me to introduce myself. I am Thais of this train, or you may call me N's mole."
  },
  AvgDialog_126908_Content_40 = {
    Text = "This is... <Shake:Mythag?!>"
  },
  AvgDialog_126908_Content_41 = {
    Text = "The architecture outside the window is unmistakably familiar. Overwhelming joy blinds you to the subtle oddities of the scene—you nearly leap from the expensive armchair."
  },
  AvgDialog_126908_Content_42 = {
    Text = "Until your eyes fall upon a mirror placed at an extremely deliberate and calculated angle."
  },
  AvgDialog_126908_Content_43 = {
    Text = "Reflected within is the face of Lord Dexter."
  },
  AvgDialog_126908_Content_44 = {Text = "???"},
  AvgDialog_126908_Content_45 = {
    Text = "You touch your face in disbelief—the reflection's fingertips trace his chiseled jaws in perfect synchrony."
  },
  AvgDialog_126908_Content_46 = {
    Text = "My, my! The reward for making it out alive was a \"return to Mythag,\" but I never promised how you'd return, did I?"
  },
  AvgDialog_126908_Content_47 = {
    Text = "The best I could manage was letting you borrow one of my avatars for a while."
  },
  AvgDialog_126908_Content_48 = {
    Text = "Even so, this defies the laws of the universe. You must exercise restraint—don't let anyone discover you aren't the real Lord Dexter, okay~?"
  },
  AvgDialog_126908_Content_49 = {
    Text = "I guess you're about to say, \"Or else...\""
  },
  AvgDialog_126908_Content_5 = {
    Text = "Over the long millennia of my life, I have grown most accustomed to the name \"Xu.\" It is ordinary enough, common enough, familiar enough to be seen as anyone."
  },
  AvgDialog_126908_Content_50 = {
    Text = "Or else—ta-da! The midnight bell will toll early, and the pumpkin carriage and glass slippers will revert to their original forms."
  },
  AvgDialog_126908_Content_51 = {
    Text = "So cherish the moments before the clock strikes twelve. After all, you paid for this time with the lives of your companions."
  },
  AvgDialog_126908_Content_6 = {
    Text = "I have so much more I wish to say to you, but not here."
  },
  AvgDialog_126908_Content_7 = {
    Text = "If fate permits, perhaps we shall cross paths again in another time and place."
  },
  AvgDialog_126908_Content_8 = {
    Text = "She raises her hand and crushes the Silver Core."
  },
  AvgDialog_126908_Content_9 = {
    Text = "You are the final victor, Keeper."
  },
  AvgDialog_126909_Content_1 = {
    Text = "Homebound Train"
  },
  AvgDialog_126909_Content_10 = {
    Text = "<Shake:Clang—clang—clang—>"
  },
  AvgDialog_126909_Content_11 = {
    Text = "<Shake:Hmm... so sleepy...> No matter how long I sleep on this train, it's never enough."
  },
  AvgDialog_126909_Content_12 = {
    Text = "<LightGray:(Feels like my brain is a tangled mess... Did I forget something important?)>"
  },
  AvgDialog_126909_Content_13 = {
    Text = "<LightGray:<Shake:(Whatever. The Spring Festival holiday is a perfect excuse—and I'm going straight back to the dorm to play dead. Even if Doll pushes me for homework or Ramona nags about reports, I'll resist to the bitter end...)>>"
  },
  AvgDialog_126909_Content_14 = {
    Text = "Oh dear, what a sleepy little sapling~ You can lean on my shoulder until the train reaches the terminus, you know?"
  },
  AvgDialog_126909_Content_15 = {Text = "Whoa?!"},
  AvgDialog_126909_Content_16 = {
    Text = "You look around and count the passengers."
  },
  AvgDialog_126909_Content_17 = {
    Text = "Wanda swirls half a glass of red wine, admiring her sharp, manicured nails."
  },
  AvgDialog_126909_Content_18 = {
    Text = "Tinct quietly holds a music score, lips moving as she practices silently."
  },
  AvgDialog_126909_Content_19 = {
    Text = "Winkle huddles near a dim lamp, eyes glued to the flickering wick as if afraid the light might escape."
  },
  AvgDialog_126909_Content_2 = {
    Text = "Ta-daah! Ladies and gentlemen in the audience, happy Spring Festival! Finally, finally—it's Little N's time to shine!"
  },
  AvgDialog_126909_Content_20 = {
    Text = "Miryam has her head tilted back, eyes closed, seemingly oblivious to her surroundings."
  },
  AvgDialog_126909_Content_21 = {
    Text = "<LightGray:(Everyone is minding their own business... such a peaceful atmosphere...)>"
  },
  AvgDialog_126909_Content_22 = {Text = "..."},
  AvgDialog_126909_Content_23 = {Text = "......"},
  AvgDialog_126909_Content_24 = {
    Text = "<LightGray:(But... hasn't this train ride been going on way too long?)>"
  },
  AvgDialog_126909_Content_25 = {
    Text = "The Mythag Express is a short-line train designed to pass through the Mist Barrier. But since you woke up, at least an hour has passed."
  },
  AvgDialog_126909_Content_26 = {
    Text = "After thinking for a moment, you walk over to the only faculty member on board."
  },
  AvgDialog_126909_Content_27 = {
    Text = "Winkle... why is the Mythag Express so slow today?"
  },
  AvgDialog_126909_Content_28 = {
    Text = "Winkle jumps up like a startled hare."
  },
  AvgDialog_126909_Content_29 = {
    Text = "Wh-what Mythag Express? Isn't this train headed to the @1 home planet?"
  },
  AvgDialog_126909_Content_3 = {
    Text = "Even though you're my avatar, I must say that your idea of entertainment this time is embarrassingly lowbrow. Frankly, it borders on the absurd."
  },
  AvgDialog_126909_Content_30 = {
    Text = "All eyes turn toward Winkle like spotlights."
  },
  AvgDialog_126909_Content_31 = {
    Text = "Don't be silly, little girl. Isn't this the train to Aram?"
  },
  AvgDialog_126909_Content_32 = {
    Text = "Huh? Huh? But Aram is deep in the desert—no tracks could possibly reach it..."
  },
  AvgDialog_126909_Content_33 = {
    Text = "As far as I know, the destination of this train should be Isarawu."
  },
  AvgDialog_126909_Content_34 = {
    Text = "That's even more ridiculous. Hasn't Isarawu been a ruin for ages?"
  },
  AvgDialog_126909_Content_35 = {
    Text = "Talk is cheap. I have proof."
  },
  AvgDialog_126909_Content_36 = {
    Text = "Wanda pulls out a metal ticket and shows it to everyone."
  },
  AvgDialog_126909_Content_37 = {
    Text = "The destination clearly reads \"Isarawu.\""
  },
  AvgDialog_126909_Content_38 = {
    Text = "Miryam, Tinct, what about you two...?"
  },
  AvgDialog_126909_Content_39 = {
    Text = "There is no need for words. His will shall guide me back to Lemuria."
  },
  AvgDialog_126909_Content_4 = {
    Text = "But it's the Spring Festival! Gotta present our dear audience something fresh and festive, don't you think?"
  },
  AvgDialog_126909_Content_40 = {
    Text = "I... I want to spend the holiday with my sister... back on the Desolate, our home..."
  },
  AvgDialog_126909_Content_41 = {
    Text = "<LightGray:(The Desolate... It took Tinct countless eons of wandering to reach Kadath. That distance is unimaginable for a mere train...)>"
  },
  AvgDialog_126909_Content_42 = {
    Text = "Lemuria sank beneath the ocean thousands of years ago."
  },
  AvgDialog_126909_Content_43 = {
    Text = "And Isarawu... has long been destroyed."
  },
  AvgDialog_126909_Content_44 = {
    Text = "Little one, you've been playing the expert on everyone else's business. What about you? What is the name of this \"home planet,\" and where is it?"
  },
  AvgDialog_126909_Content_45 = {
    Text = "Winkle pales."
  },
  AvgDialog_126909_Content_46 = {
    Text = "<Shake:Home planet... is just the home planet! Its name is... <Small:@1...>>"
  },
  AvgDialog_126909_Content_47 = {
    Text = "Hmm? Did I hear that right? You can't even remember the name of your own home?"
  },
  AvgDialog_126909_Content_48 = {
    Text = "Everyone, calm down and listen to me."
  },
  AvgDialog_126909_Content_49 = {
    Text = "Your destinations all sound... unrealistic. Yet each of you holds a ticket to your respective homeland."
  },
  AvgDialog_126909_Content_5 = {
    Text = "Even so, isn't it a bit far-fetched to have only one scene from start to finish?"
  },
  AvgDialog_126909_Content_50 = {
    Text = "Instead of arguing, we need to find the conductor and get some real information."
  },
  AvgDialog_126909_Content_51 = {Text = "Ahem."},
  AvgDialog_126909_Content_52 = {
    Text = "A comical, strange voice pipes up from the shadows."
  },
  AvgDialog_126909_Content_53 = {
    Text = "Already done bickering? I was hoping for a longer show~"
  },
  AvgDialog_126909_Content_54 = {Text = "Little N?!"},
  AvgDialog_126909_Content_55 = {
    Text = "What's with that look? Am I not welcome? After I went through all the trouble of preparing such a wonderful Spring Festival gift for you all!"
  },
  AvgDialog_126909_Content_56 = {
    Text = "The mastermind behind the scenes steps gleefully into the spotlight. His malicious intentions are obvious—he must be plotting something even bigger."
  },
  AvgDialog_126909_Content_57 = {
    Text = "What are you doing here?"
  },
  AvgDialog_126909_Content_58 = {
    Text = "Isn't it obvious? In the spirit of the festival, your considerate, selfless, and charitable Little N has launched this \"Homebound Express,\" so every homesick soul can enjoy the warmth of reunion!"
  },
  AvgDialog_126909_Content_59 = {
    Text = "You're not that generous. Out with it—what are you hiding?"
  },
  AvgDialog_126909_Content_6 = {
    Text = "<Shake:Sob... Times have changed since you ran the theater and faced off against that Lady... The project budget for this festival is a pittance! This bare-bones stage set is all we can afford...>"
  },
  AvgDialog_126909_Content_60 = {
    Text = "Ah-ah! Patience! Let me finish one bit at a time."
  },
  AvgDialog_126909_Content_61 = {
    Text = "Many wish to return home, but there's only one train. So naturally... only one person can return to their beloved homeland~"
  },
  AvgDialog_126909_Content_62 = {
    Text = "Sigh, as the considerate, selfless, and charitable N, of course I must use the fairest method to decide who gets that privilege, right?"
  },
  AvgDialog_126909_Content_63 = {
    Text = "Which is...?"
  },
  AvgDialog_126909_Content_64 = {
    Text = "<BigShake:So—<Red:Start killing each other!>>"
  },
  AvgDialog_126909_Content_65 = {
    Text = "Kill everyone else! The last one standing gets to decide the train's destination and wins a one-day homecoming tour!"
  },
  AvgDialog_126909_Content_66 = {
    Text = "Impossible! No one would... would actually take a life for something like this!"
  },
  AvgDialog_126909_Content_67 = {
    Text = "Exactly... Though I miss Faint dearly, I could never join such a cruel game..."
  },
  AvgDialog_126909_Content_68 = {
    Text = "Hmph. Staying here with fine wine and servants isn't a bad alternative. Isarawu is just a faded memory to me anyway."
  },
  AvgDialog_126909_Content_69 = {
    Text = "Although I'd love to return... my little sapling is here with me, and the people of Aram no longer need my guidance. I have no motive to participate in a bloodbath, either."
  },
  AvgDialog_126909_Content_7 = {
    Text = "Then it seems I've got no choice but to... wait and see."
  },
  AvgDialog_126909_Content_70 = {
    Text = "All eyes now turn to the last person."
  },
  AvgDialog_126909_Content_71 = {Text = "..."},
  AvgDialog_126909_Content_72 = {
    Text = "The stares don't bother her. Miryam remains silent."
  },
  AvgDialog_126909_Content_73 = {
    Text = "You know her obsession; you know what \"Lemuria\" means to her."
  },
  AvgDialog_126909_Content_74 = {
    Text = "Sigh... I knew it wouldn't be that easy..."
  },
  AvgDialog_126909_Content_75 = {
    Text = "To avoid this awkward stalemate, I've refined the rules: you must present me with five corpses to exchange for the final ticket."
  },
  AvgDialog_126909_Content_76 = {
    Text = "You need seven tickets in total to start the train!"
  },
  AvgDialog_126909_Content_77 = {
    Text = "In other words, no one leaves until only one person remains alive."
  },
  AvgDialog_126909_Content_78 = {
    Text = "Oh, and one more thing! There's an impostor among you—a double of me, the ever-changing Little N!"
  },
  AvgDialog_126909_Content_79 = {
    Text = "If you do nothing, it will pick you off one by one by one! And then? No one goes home!"
  },
  AvgDialog_126909_Content_8 = {
    Text = "Ahem! Without further ado, Little N presents the latest, hottest Spring Festival Exclusive Drama!"
  },
  AvgDialog_126909_Content_81 = {
    Text = "Before Little N can finish, a vine suddenly pierces through the black mist."
  },
  AvgDialog_126909_Content_82 = {
    Text = "Alright, everyone. Stop listening to his nonsense."
  },
  AvgDialog_126909_Content_83 = {
    Text = "There are six of us, including Mythag's finest Keeper. You really think we can't escape this tiny carriage?"
  },
  AvgDialog_126909_Content_9 = {
    Text = "Come on, audience! Make some noise—it's showtime!"
  },
  AvgDialog_126910_Content_1 = {
    Text = "Second Victim"
  },
  AvgDialog_126910_Content_10 = {
    Text = "Shouldn't the priority be finding the killer among us?"
  },
  AvgDialog_126910_Content_11 = {
    Text = "I disagree. There are so few of us left; turning on each other will only play into the killer's hands."
  },
  AvgDialog_126910_Content_12 = {
    Text = "What matters most is keeping the rest of us safe. How about we all stay in Car 2?"
  },
  AvgDialog_126910_Content_13 = {
    Text = "You glance at Winkle's haggard face and nod."
  },
  AvgDialog_126910_Content_14 = {
    Text = "Since little sapling has made up {Male=his,Female=her} mind, I won't object."
  },
  AvgDialog_126910_Content_15 = {
    Text = "...According to our Lord's teaching, I must seek a quiet corner for solitary prayer at regular intervals."
  },
  AvgDialog_126910_Content_16 = {
    Text = "No way! Who knows what you might do while \"praying\"?"
  },
  AvgDialog_126910_Content_17 = {
    Text = "Besides, you were the only one who stayed silent when we agreed to a truce. How do we know you're not one of N's underlings?"
  },
  AvgDialog_126910_Content_18 = {
    Text = "The only Lord I serve is the deity of Lemuria."
  },
  AvgDialog_126910_Content_19 = {
    Text = "However, should you utter another word of blasphemy, I would not mind delivering divine retribution on His behalf."
  },
  AvgDialog_126910_Content_2 = {
    Text = "<Italic:Three hours later, inside the train car>"
  },
  AvgDialog_126910_Content_20 = {
    Text = "Seeing Miryam already drawing her dagger, you hurriedly step in to mediate."
  },
  AvgDialog_126910_Content_21 = {
    Text = "We have no evidence against anyone yet. When Tinct... died, everyone was asleep."
  },
  AvgDialog_126910_Content_22 = {
    Text = "Besides, this \"mole\" business might just be another of N's ploys to goad us into slaughtering each other."
  },
  AvgDialog_126910_Content_23 = {
    Text = "How cruel! Sob... I was being so sincere with my warning—"
  },
  AvgDialog_126910_Content_24 = {
    Text = "<LightGray:<Italic:(Death glare)...>>"
  },
  AvgDialog_126910_Content_25 = {
    Text = "Fine, fine! I'll disappear! Waaah..."
  },
  AvgDialog_126910_Content_26 = {
    Text = "POOF!—Little N vanishes into thin air."
  },
  AvgDialog_126910_Content_27 = {
    Text = "In that case... Miryam, would you mind leaving to pray alone in Car 1? Please stay there unless it is an absolute emergency."
  },
  AvgDialog_126910_Content_28 = {
    Text = "We'll lock the connecting door to Car 1. With the rest of us in one room, we can ensure everyone's safety."
  },
  AvgDialog_126910_Content_29 = {
    Text = "Isn't that a bit... extreme for Miryam?"
  },
  AvgDialog_126910_Content_3 = {
    Text = "<Shake:<Italic: Gulp, gulp, gulp—>>"
  },
  AvgDialog_126910_Content_30 = {
    Text = "I have no objection."
  },
  AvgDialog_126910_Content_31 = {
    Text = "Ignoring your protest, Miryam stands up and leaves Car 2 without hesitation, carefully locking the connecting door behind her."
  },
  AvgDialog_126910_Content_32 = {
    Text = "The rest of us should be able to breath easy now, huh."
  },
  AvgDialog_126910_Content_33 = {
    Text = "I have a feeling it won't be that simple..."
  },
  AvgDialog_126910_Content_34 = {
    Text = "One hour later, inside Car 2"
  },
  AvgDialog_126910_Content_35 = {Text = "Urgh..."},
  AvgDialog_126910_Content_36 = {
    Text = "I... need a moment..."
  },
  AvgDialog_126910_Content_37 = {
    Text = "Winkle wobbles towards the intersection between two cars."
  },
  AvgDialog_126910_Content_38 = {
    Text = "<LightGray:(Too much caffeine, I guess...)>"
  },
  AvgDialog_126910_Content_39 = {
    Text = "One hour later, inside Car 2"
  },
  AvgDialog_126910_Content_4 = {
    Text = "Stop drinking already."
  },
  AvgDialog_126910_Content_40 = {
    Text = "<LightGray:(Strange... Winkle is taking an awfully long time...)>"
  },
  AvgDialog_126910_Content_41 = {
    Text = "Worried? Shall I accompany you to check on her?"
  },
  AvgDialog_126910_Content_42 = {Text = "Let's go."},
  AvgDialog_126910_Content_43 = {
    Text = "Unease creeps into your heart. Hollow footsteps echo alongside the shadows, filling the entire train car."
  },
  AvgDialog_126910_Content_44 = {
    Text = "You recognize the name of this dread—"
  },
  AvgDialog_126910_Content_45 = {Text = "Death."},
  AvgDialog_126910_Content_46 = {
    Text = "You pound on the door, shouting Winkle's name. Silence."
  },
  AvgDialog_126910_Content_47 = {
    Text = "You start trying to force the door open."
  },
  AvgDialog_126910_Content_48 = {
    Text = "Bang, bang, bang!"
  },
  AvgDialog_126910_Content_49 = {
    Text = "What's the matter?"
  },
  AvgDialog_126910_Content_5 = {
    Text = "<Shake:<Italic: Gulp, gulp, gulp—>>"
  },
  AvgDialog_126910_Content_50 = {
    Text = "Wanda is also drawn over by the noise."
  },
  AvgDialog_126910_Content_51 = {
    Text = "Winkle has been in there for an hour. We've been knocking, but there's no answer."
  },
  AvgDialog_126910_Content_52 = {
    Text = "The door won't budge. It's absurd! We've got a bunch of Awakeners here... people who can summon storms and fight mythical creatures... yet we're bested by a simple door?!"
  },
  AvgDialog_126910_Content_53 = {
    Text = "Ever heard of <Italic:\"Shin Honkaku,\">— the New Orthodoxy of murder mystery?"
  },
  AvgDialog_126910_Content_54 = {
    Text = "To talk Shin Honkaku, one must first pay respects to the Orthodoxy."
  },
  AvgDialog_126910_Content_56 = {
    Text = [[
In the world of deduction, Honkaku refers to a work with a clearly defined puzzle and rigorous logic...
Shin Honkaku takes that foundation and builds a unique worldview on top of it.]]
  },
  AvgDialog_126910_Content_57 = {
    Text = "Even so, the New Orthodoxy must respect the reader and abide by the rules of \"Fair Play.\" The mystery must be solvable within the information already given—no adding supernatural elements on a whim."
  },
  AvgDialog_126910_Content_58 = {
    Text = "In short, if you don't have lockpicking skills, you can't just magically open a door locked from the inside."
  },
  AvgDialog_126910_Content_59 = {
    Text = "Little N bounces between the luggage racks and hides behind seats, dodging thorns and vines as he finishes his lecture."
  },
  AvgDialog_126910_Content_6 = {Text = "Winkle..."},
  AvgDialog_126910_Content_60 = {
    Text = "So... you're saying this is a classic \"locked-room murder\"? And the crime scene is right inside?"
  },
  AvgDialog_126910_Content_61 = {
    Text = "Who knows! Perhaps Winkle fled in a fit of guilt, leaping from the lavatory window mid-transit!"
  },
  AvgDialog_126910_Content_62 = {
    Text = "But didn't you say we can't leave the train?"
  },
  AvgDialog_126910_Content_63 = {
    Text = "Aha! A lapse in logic!"
  },
  AvgDialog_126910_Content_64 = {
    Text = "Before the Great Detective makes {Male=his,Female=her} grand entrance, there must always be the \"clueless sidekick\" who offers the wrong theory."
  },
  AvgDialog_126910_Content_65 = {
    Text = "Since none of you are willing to play the buffoon, I, the ever-magnanimous Little N, shall graciously take the stage!"
  },
  AvgDialog_126910_Content_66 = {
    Text = "Stop wasting your breath on him."
  },
  AvgDialog_126910_Content_67 = {
    Text = "It's a bit crude, I know... but there's a louvered vent on the restroom door. The structure is quite flimsy."
  },
  AvgDialog_126910_Content_68 = {
    Text = "Wanda raises her thorns."
  },
  AvgDialog_126910_Content_69 = {
    Text = "Crunch, crack... the slats are pried loose."
  },
  AvgDialog_126910_Content_7 = {
    Text = "Even if you drown yourself in coffee, it won't bring Tinct back, will it?"
  },
  AvgDialog_126910_Content_70 = {
    Text = "Leave the rest to me."
  },
  AvgDialog_126910_Content_71 = {
    Text = "Vines snake through the opening and unlatch the lock. You push the door open."
  },
  AvgDialog_126910_Content_72 = {
    Text = "We're too late."
  },
  AvgDialog_126910_Content_73 = {
    Text = "Winkle is lying curled up, silent, in a corner of the restroom."
  },
  AvgDialog_126910_Content_74 = {Text = "Winkle!"},
  AvgDialog_126910_Content_75 = {
    Text = "You rush toward her, but dark crimson blood has already trickled from the corner of her lips. She has no breath left."
  },
  AvgDialog_126910_Content_76 = {
    Text = "To be blunt: when Winkle died, you, Wanda, and I never left Car 2."
  },
  AvgDialog_126910_Content_77 = {
    Text = "The only possible killer... has to be Miryam."
  },
  AvgDialog_126910_Content_78 = {
    Text = "My Lord did not guide me to such an act. But if you insist, I am willing to deliver judgment on His behalf."
  },
  AvgDialog_126910_Content_79 = {
    Text = "Oh dear, quite the standoff!"
  },
  AvgDialog_126910_Content_8 = {
    Text = "<Shake:You—!>"
  },
  AvgDialog_126910_Content_80 = {
    Text = "Since we're talking divine judgment, I'd like to offer you an easy way to win!"
  },
  AvgDialog_126910_Content_81 = {
    Text = "Let's hold a vote right now! Whoever gets the most votes will be expelled from the train by me and lose their chance to return home!"
  },
  AvgDialog_126910_Content_82 = {
    Text = "Without a doubt, my vote goes to Miryam."
  },
  AvgDialog_126910_Content_83 = {Text = "Thais."},
  AvgDialog_126910_Content_84 = {
    Text = "Little one, what about you? Given the circumstantial evidence, I'm also inclined to vote for Miryam."
  },
  AvgDialog_126910_Content_85 = {
    Text = "Miryam: 2 votes! Thais: 1 vote!"
  },
  AvgDialog_126910_Content_86 = {
    Text = "N, what happens in the event of a tie?"
  },
  AvgDialog_126910_Content_87 = {
    Text = "If it's a tie, nobody gets eliminated~"
  },
  AvgDialog_126910_Content_88 = {
    Text = "But think carefully! There are only four of you left. If you pass this up and the mole strikes again, your odds of survival will plummet!"
  },
  AvgDialog_126910_Content_89 = {
    Text = "I don't want to wrong an innocent person. I'm voting for Thais."
  },
  AvgDialog_126910_Content_9 = {
    Text = "She has a point. Finding a way off this train is our top priority now."
  },
  AvgDialog_126910_Content_90 = {
    Text = "Really? Won't you reconsider? This is your one and only chance to vote!"
  },
  AvgDialog_126910_Content_91 = {
    Text = "No. The more you push, the more certain I am that I've made the right choice."
  },
  AvgDialog_126910_Content_92 = {
    Text = "Very well! Final tally: a tie. No one is out!"
  },
  AvgDialog_126910_Content_93 = {
    Text = "Sigh... What a disappointment. Even Little N needs some alone time to recover now. See ya!"
  },
  AvgDialog_126911_Content_1 = {Text = "Game On"},
  AvgDialog_126911_Content_10 = {
    Text = "Keep talking, and I won't mind giving you another taste of a pierced heart."
  },
  AvgDialog_126911_Content_11 = {
    Text = "Wanda idly toys with the sharp spikes on her fingers."
  },
  AvgDialog_126911_Content_12 = {
    Text = "Ohhh, that's harsh! Truly heartbreaking!"
  },
  AvgDialog_126911_Content_13 = {
    Text = "Is the Spring Festival program I painstakingly prepared really that unpopular? <Italic:Sniff...>"
  },
  AvgDialog_126911_Content_14 = {
    Text = "The fake sobs lasted less than a second before a radiant smile blooms across his face again."
  },
  AvgDialog_126911_Content_15 = {
    Text = "Anyway—happy hunting! Little N is looking forward to your performances!"
  },
  AvgDialog_126911_Content_16 = {
    Text = "Whoosh! In a blink, Little N vanishes again. \nSilence returns to the train—tense and suffocating."
  },
  AvgDialog_126911_Content_17 = {
    Text = "A long pause follows. The darkness on the tracks ahead seems endless."
  },
  AvgDialog_126911_Content_18 = {
    Text = "How much longer will this train run? Where is it heading?"
  },
  AvgDialog_126911_Content_19 = {
    Text = "Some have no answer; others hold one they dare not speak aloud."
  },
  AvgDialog_126911_Content_2 = {
    Text = "...There's no way out."
  },
  AvgDialog_126911_Content_20 = {
    Text = "Um... everyone...?"
  },
  AvgDialog_126911_Content_21 = {
    Text = "A clear, pleasant voice breaks the stillness."
  },
  AvgDialog_126911_Content_22 = {
    Text = "It's a bit dull just sitting here... If you don't mind, may I sing a song for you?"
  },
  AvgDialog_126911_Content_23 = {
    Text = "Ooh?! I love a good show! Can I request a song?"
  },
  AvgDialog_126911_Content_24 = {
    Text = "Shoo, shoo! No one asked you!"
  },
  AvgDialog_126911_Content_25 = {
    Text = "Since it's the Spring Festival of the Panlong Empire... I recall an Eastern folk tune. I once heard the Shadow Choir perform it."
  },
  AvgDialog_126911_Content_26 = {
    Text = "I'm not sure whether I know enough Eastern pieces..."
  },
  AvgDialog_126911_Content_27 = {
    Text = "The song is called \"Mo Li Hua\", <Italic:the Jasmine Flower>."
  },
  AvgDialog_126911_Content_28 = {
    Text = "Oh? That one?"
  },
  AvgDialog_126911_Content_29 = {
    Text = "What a coincidence. I was in the audience for that Shadow Choir performance, too."
  },
  AvgDialog_126911_Content_3 = {
    Text = "Winkle mutters the conclusion in despair."
  },
  AvgDialog_126911_Content_30 = {
    Text = "If I remember correctly, I even spotted..."
  },
  AvgDialog_126911_Content_31 = {
    Text = "Wanda's eyes locks onto Miryam, who simply nods silently."
  },
  AvgDialog_126911_Content_32 = {
    Text = "Well... if no one objects... I'll begin."
  },
  AvgDialog_126911_Content_33 = {
    Text = "Tinct clears her throat softly."
  },
  AvgDialog_126911_Content_34 = {
    Text = "<Shake:What a lovely jasmine flower~ What a lovely jasmine flower♪~ No bloom in the garden can compare to her♪~>"
  },
  AvgDialog_126911_Content_35 = {
    Text = "<Shake:La la la~ La la la~ La la la♪~>"
  },
  AvgDialog_126911_Content_36 = {
    Text = "Her ethereal voice echoes through the empty carriage."
  },
  AvgDialog_126911_Content_37 = {
    Text = "Under the soothing song, the tension in your mind begins to ease. You feel a wave of drowsiness wash over you."
  },
  AvgDialog_126911_Content_38 = {
    Text = "Everyone is exhausted, aren't they? I'm used to going without sleep—I'll keep watch."
  },
  AvgDialog_126911_Content_39 = {
    Text = "You nod, then sink deep into the long-delayed embrace of sleep."
  },
  AvgDialog_126911_Content_4 = {
    Text = "Aside from the driver's cab, this train has three carriages in total. We're in Car 2, the middle one."
  },
  AvgDialog_126911_Content_40 = {Text = "..."},
  AvgDialog_126911_Content_41 = {
    Text = "After a long while, Tinct finishes her song."
  },
  AvgDialog_126911_Content_42 = {
    Text = "Everyone's asleep now. Why don't you get some rest too?"
  },
  AvgDialog_126911_Content_43 = {
    Text = "Are you sure it's okay?"
  },
  AvgDialog_126911_Content_44 = {
    Text = "What, are you worried I might be the mole?"
  },
  AvgDialog_126911_Content_45 = {
    Text = "Not at all. It's just... back then, I would always wait for Faint to fall asleep before I rest..."
  },
  AvgDialog_126911_Content_46 = {
    Text = "Then today, it's your turn to get some proper sleep! Go on."
  },
  AvgDialog_126911_Content_47 = {
    Text = "At Winkle's insistence, Tinct takes a blanket, leans against the seatback, and closes her eyes."
  },
  AvgDialog_126911_Content_48 = {
    Text = "No wonder everyone fell asleep so fast... It's such a peaceful atmosphere..."
  },
  AvgDialog_126911_Content_49 = {Text = "..."},
  AvgDialog_126911_Content_5 = {
    Text = "Cars 1 and 3 are empty. Every window and door is sealed shut—neither brute force nor Silver Technology can break them."
  },
  AvgDialog_126911_Content_50 = {Text = "......"},
  AvgDialog_126911_Content_51 = {Text = "Hmm...?"},
  AvgDialog_126911_Content_52 = {
    Text = "The first thing you see is Winkle's peaceful, sleeping face."
  },
  AvgDialog_126911_Content_53 = {
    Text = "At some point, the lights were cut. Darkness fills the carriage, save for a soft glow leaking in from the gangway."
  },
  AvgDialog_126911_Content_54 = {
    Text = "Winkle... why are you asleep?"
  },
  AvgDialog_126911_Content_55 = {
    Text = "Winkle lets out a soft breath."
  },
  AvgDialog_126911_Content_56 = {
    Text = "Huh...? I... fell asleep?"
  },
  AvgDialog_126911_Content_57 = {
    Text = "EHHH?!?! I FELL ASLEEP?!?!"
  },
  AvgDialog_126911_Content_58 = {
    Text = "Her panicked cry tears through the night like a storm, jolting the others awake."
  },
  AvgDialog_126911_Content_59 = {
    Text = "The lights snap back on, flooding the entire carriage with harsh brightness."
  },
  AvgDialog_126911_Content_6 = {
    Text = "Told ya! No point wasting your energy! Nobody gets off until there's only one winner left!"
  },
  AvgDialog_126911_Content_60 = {
    Text = "Dear passengers, did you rest well on the Homebound Express?"
  },
  AvgDialog_126911_Content_61 = {
    Text = "Once I detected that all passengers were asleep, I kindly arranged a quiet, dark environment for you!"
  },
  AvgDialog_126911_Content_62 = {
    Text = "I'm so sorry... I usually rely on massive amounts of coffee to stay awake..."
  },
  AvgDialog_126911_Content_63 = {
    Text = "Wait. Is someone missing?"
  },
  AvgDialog_126911_Content_64 = {Text = "…"},
  AvgDialog_126911_Content_65 = {
    Text = "Hmm? Are you looking for me, little sapling? I'm right here."
  },
  AvgDialog_126911_Content_66 = {
    Text = "Then the missing person is..."
  },
  AvgDialog_126911_Content_67 = {
    Text = "Everyone turns toward the rear of the carriage—"
  },
  AvgDialog_126911_Content_68 = {
    Text = "Tinct's throat has been pierced through by something sharp. Blood streams down her graceful neck, soaking her dress crimson."
  },
  AvgDialog_126911_Content_69 = {
    Text = "The bloodstained nightingale would never sing again."
  },
  AvgDialog_126911_Content_7 = {
    Text = "How did you...? Didn't Thais just...?"
  },
  AvgDialog_126911_Content_70 = {
    Text = "<Shake:AAAAAAH—!!!>"
  },
  AvgDialog_126911_Content_71 = {
    Text = "Winkle shrieks—a sound that could shatter glass—then slides down the wall into a corner, arms wrapped tightly around herself, trembling uncontrollably."
  },
  AvgDialog_126911_Content_72 = {
    Text = "<Shake:I'm sorry... I shouldn't have been so confident... I shouldn't have kept watch alone... I shouldn't have thought I could stay awake without coffee...>"
  },
  AvgDialog_126911_Content_73 = {
    Text = "She bites her nails frantically; tears pour out, dripping onto the carpet."
  },
  AvgDialog_126911_Content_74 = {
    Text = "Ta-da! What did the considerate Little N hear? <Shake:A passenger's need!>"
  },
  AvgDialog_126911_Content_75 = {
    Text = "Heartfelt service, coming right up—an <Yellow:unlimited coffee machine!>"
  },
  AvgDialog_126911_Content_76 = {
    Text = "Just press this red button, and endless streams of hot, dark-roast Americano will gush forth!"
  },
  AvgDialog_126911_Content_77 = {
    Text = "You silently step forward and raise your hand—"
  },
  AvgDialog_126911_Content_78 = {
    Text = "Then you smash the annoying Little N flat."
  },
  AvgDialog_126911_Content_79 = {
    Text = "<Shake:I'm sorry... I'm so, so sorry...>"
  },
  AvgDialog_126911_Content_8 = {
    Text = "Hehe! If I were that easy to kill, I wouldn't be Little N, would I?"
  },
  AvgDialog_126911_Content_80 = {
    Text = "Winkle's broken sobs echo through the carriage."
  },
  AvgDialog_126911_Content_81 = {
    Text = "No matter how you resist, with Tinct's death as the opening act—"
  },
  AvgDialog_126911_Content_82 = {
    Text = "The killing game... has begun."
  },
  AvgDialog_126911_Content_9 = {
    Text = "So? Has everyone picked their target for the night?"
  },
  AvgDialog_126912_Content_1 = {
    Text = "The Silent Kill"
  },
  AvgDialog_126912_Content_10 = {
    Text = "For some reason, you feel something hidden beneath that smile—an emotion you haven't yet grasped."
  },
  AvgDialog_126912_Content_11 = {
    Text = "Let's go, Miryam. To Car 1."
  },
  AvgDialog_126912_Content_12 = {
    Text = "Just as the connecting door begins to close, Wanda pauses and glances back over her shoulder."
  },
  AvgDialog_126912_Content_13 = {
    Text = "Happy Spring Festival, %player%."
  },
  AvgDialog_126912_Content_14 = {Text = "..."},
  AvgDialog_126912_Content_15 = {Text = "Car 2"},
  AvgDialog_126912_Content_16 = {
    Text = "With Wanda and Miryam gone, only you and Thais remain in the carriage."
  },
  AvgDialog_126912_Content_17 = {
    Text = "Well then, since we finally have some precious time alone, what shall we do, my little sapling?"
  },
  AvgDialog_126912_Content_18 = {
    Text = "Thais suddenly leans in with a mischievous glint. Startled, you flinch back, maintaining a safe distance."
  },
  AvgDialog_126912_Content_19 = {
    Text = "I could... work on my report..."
  },
  AvgDialog_126912_Content_2 = {Text = "Car 2"},
  AvgDialog_126912_Content_20 = {
    Text = "It's Spring Festival already! Relax a little—stop obsessing over those reports."
  },
  AvgDialog_126912_Content_21 = {
    Text = "Her honey-toned arm drapes gently over your shoulder. Her breath, warm and intimate, curls around you like a <Italic:Night Haze.>"
  },
  AvgDialog_126912_Content_22 = {Text = "I... uh..."},
  AvgDialog_126912_Content_23 = {
    Text = "In that instant, visions flash before your eyes: Doll's stern face, Ramona's sighs, and Czort's pointer."
  },
  AvgDialog_126912_Content_24 = {
    Text = "I'd better not..."
  },
  AvgDialog_126912_Content_25 = {
    Text = "You give an awkward smile and subtly slip out of her reach."
  },
  AvgDialog_126912_Content_26 = {
    Text = "Fine. Then let's just sit quietly and chat for a while, shall we?"
  },
  AvgDialog_126912_Content_27 = {
    Text = "Tell me, Keeper... in that moment when your eyes darted away—who were you thinking of?"
  },
  AvgDialog_126912_Content_28 = {Text = "..."},
  AvgDialog_126912_Content_29 = {Text = "......"},
  AvgDialog_126912_Content_3 = {
    Text = "Amidst the rumble of the train, Wanda is the first to break the silence."
  },
  AvgDialog_126912_Content_30 = {
    Text = "You don't remember how long you've been talking—only that every memory comes rushing back with vivid clarity."
  },
  AvgDialog_126912_Content_31 = {
    Text = "And the cafeteria at Mythag? Way more packed than any lab."
  },
  AvgDialog_126912_Content_32 = {
    Text = "Especially when those little cakes are stocked... the kids forget all about grace or manners..."
  },
  AvgDialog_126912_Content_33 = {
    Text = "Some cheeky ones even cheat—they'd have their animal companions hold their spot at the counter with a meal voucher, then give the cakes they grab to their shy friends."
  },
  AvgDialog_126912_Content_34 = {
    Text = "<Shake:And... huh?>"
  },
  AvgDialog_126912_Content_35 = {
    Text = "You realize your voice is choking up. Tears begin to roll down your cheeks uncontrollably."
  },
  AvgDialog_126912_Content_36 = {Text = "And..."},
  AvgDialog_126912_Content_37 = {
    Text = "The tears well up, blurring your vision."
  },
  AvgDialog_126912_Content_38 = {
    Text = "<Shake:I miss Mythag so much. I want to go back... back to their side...>"
  },
  AvgDialog_126912_Content_39 = {
    Text = "It's strange... I only left <Yellow:three days ago> for fieldwork. I shouldn't feel this way..."
  },
  AvgDialog_126912_Content_4 = {
    Text = "I have a proposal."
  },
  AvgDialog_126912_Content_40 = {
    Text = "But the ache of longing makes your nose sting, and a tension inside you feels ready to snap."
  },
  AvgDialog_126912_Content_41 = {
    Text = "Shh... It's okay, Keeper. It's okay."
  },
  AvgDialog_126912_Content_42 = {
    Text = "You sink into a soft embrace. A mother's embrace."
  },
  AvgDialog_126912_Content_43 = {
    Text = "@1 promise you, you'll return to the place you miss so dearly."
  },
  AvgDialog_126912_Content_44 = {
    Text = "Thais's features begin to blur."
  },
  AvgDialog_126912_Content_45 = {
    Text = "A gentle haze envelops you both, and you curl up quietly in her arms, feeling small—so very small."
  },
  AvgDialog_126912_Content_46 = {
    Text = "You catch a scent. The fragrance of <Yellow:magnolias.>"
  },
  AvgDialog_126912_Content_47 = {
    Text = "<Red:Large, blooming magnolias.>"
  },
  AvgDialog_126912_Content_48 = {
    Text = "Wrapped in that rich fragrance, you drift into a deep, untroubled sleep. It is an infant-like sleep that washes away all worry and fear."
  },
  AvgDialog_126912_Content_49 = {
    Text = "Before your consciousness fades, the last thing you remember is <Yellow:a pair of golden eyes>—the enchanting, loving eyes of a mother."
  },
  AvgDialog_126912_Content_5 = {
    Text = "We can split into pairs and stay in Cars 1 and 2 separately. That way we can keep an eye on each other."
  },
  AvgDialog_126912_Content_50 = {Text = "..."},
  AvgDialog_126912_Content_51 = {Text = "Until—"},
  AvgDialog_126912_Content_52 = {
    Text = "A loud CRASH erupts from Car 1."
  },
  AvgDialog_126912_Content_53 = {
    Text = "In that instant, you know: the killing game isn't over. It's time to wake up."
  },
  AvgDialog_126912_Content_54 = {Text = "Car 1"},
  AvgDialog_126912_Content_55 = {
    Text = "Inside Car 1, Wanda and Miryam lie tangled together, gravely wounded. A dagger is buried deep into Wanda's chest; Miryam is impaled by countless thorns."
  },
  AvgDialog_126912_Content_56 = {
    Text = "Wanda's eyes flutter half-open, her voice ragged and fading."
  },
  AvgDialog_126912_Content_57 = {
    Text = "I knew... Miryam would strike first... so I prepared... my \"counter\"..."
  },
  AvgDialog_126912_Content_58 = {
    Text = "Now... N can never achieve his victory..."
  },
  AvgDialog_126912_Content_59 = {
    Text = "You two... must..."
  },
  AvgDialog_126912_Content_6 = {
    Text = "But wouldn't the person left alone with the killer be in grave danger?"
  },
  AvgDialog_126912_Content_60 = {
    Text = "Her voice trails off. Her final blessing dissolves into silence."
  },
  AvgDialog_126912_Content_61 = {
    Text = "After a long, heavy pause, Thais finally speaks, her voice trembling."
  },
  AvgDialog_126912_Content_62 = {
    Text = "So... Miryam really was the killer. She knew that under the rule of mutual watch, she had to eliminate Wanda first—or her following actions would unite everyone else against her. So she made her move."
  },
  AvgDialog_126912_Content_63 = {
    Text = "Wanda... she knew she was good at \"counter,\" so she volunteered to stay with the mole, Miryam, alone."
  },
  AvgDialog_126912_Content_64 = {
    Text = "She sacrificed herself... to secure victory for the \"innocents.\""
  },
  AvgDialog_126912_Content_65 = {
    Text = "Her tone is heavy with a trace of respect. If only the respect were genuine..."
  },
  AvgDialog_126912_Content_66 = {
    Text = "<Italic:But it's not.>"
  },
  AvgDialog_126912_Content_67 = {
    Text = "No... Miryam wasn't the mole N planted among us."
  },
  AvgDialog_126912_Content_68 = {
    Text = "<Shake:Not her? Then why would she...?>"
  },
  AvgDialog_126912_Content_69 = {
    Text = "The Miryam I know wouldn't hesitate to get her hands dirty for victory... for returning to \"Lemuria,\" as N promised."
  },
  AvgDialog_126912_Content_7 = {
    Text = "Perhaps, but it's the only way to ensure N doesn't claim ultimate victory."
  },
  AvgDialog_126912_Content_70 = {
    Text = "Then... why do you..."
  },
  AvgDialog_126912_Content_71 = {
    Text = "But the real mole... is you. \"Thais\"—or rather, <Yellow:whoever is impersonating her.>"
  },
  AvgDialog_126912_Content_72 = {
    Text = "Perhaps your buildup has been enough; Thais shows little surprise. She simply stares into your eyes with a calm, knowing smile."
  },
  AvgDialog_126912_Content_73 = {
    Text = "Oh? And when did you figure it out, <ItalicYellow:my Little Jasmine>? I'd love to hear your deduction."
  },
  AvgDialog_126912_Content_74 = {
    Text = "After Winkle left... before Wanda suggested we go stay in different cars."
  },
  AvgDialog_126912_Content_75 = {
    Text = "That early? I thought my Modus Operandi was discreet enough to leave no traces."
  },
  AvgDialog_126912_Content_76 = {
    Text = "Tinct's piercing wounds could've come from your vines, Wanda's thorns, or Miryam's dagger."
  },
  AvgDialog_126912_Content_77 = {
    Text = "As for Winkle's death... any of you three—Thais, Wanda, or Miryam—is capable of using poison."
  },
  AvgDialog_126912_Content_78 = {
    Text = "Given how much coffee she drank, poisoning the coffee machine would guarantee her death eventually."
  },
  AvgDialog_126912_Content_79 = {
    Text = "So, yes. In terms of execution, your disguise was perfect."
  },
  AvgDialog_126912_Content_8 = {
    Text = "I'll watch Miryam. Don't worry—I've got a trump card she'd never see coming."
  },
  AvgDialog_126912_Content_80 = {
    Text = "Then what gave me away?"
  },
  AvgDialog_126912_Content_81 = {
    Text = "Have you ever played a party game called \"Werewolf\"? Every blood moon, the werewolves open their eyes to hunt, then hide among the villagers by dawn."
  },
  AvgDialog_126912_Content_82 = {
    Text = "To identify the werewolf, you must figure out everyone's true motives during the discussion phase. Werewolves know who the innocents are, so their accusations tend to be more certain."
  },
  AvgDialog_126912_Content_83 = {
    Text = "But the real Thais, the queen who could stay undercover in Aram for a millennia, would never point the finger of suspicion at others so easily. She is cautious, deliberate."
  },
  AvgDialog_126912_Content_84 = {
    Text = "So that's why you voted for me... instead of following the others against Miryam."
  },
  AvgDialog_126912_Content_85 = {
    Text = "I chose to stay alone with the killer."
  },
  AvgDialog_126912_Content_86 = {
    Text = "I had planned to catch you red-handed when you made your move, but Miryam acted faster than you did."
  },
  AvgDialog_126912_Content_87 = {
    Text = "She struck Wanda before you could finish hypnotizing me."
  },
  AvgDialog_126912_Content_88 = {
    Text = "Bravo. Truly brilliant deduction. You've impressed me."
  },
  AvgDialog_126912_Content_89 = {
    Text = "No... It's not enough. I never intended to play the \"detective\" in N's little story."
  },
  AvgDialog_126912_Content_9 = {
    Text = "Wanda narrows her eyes, offering a reassuring smile."
  },
  AvgDialog_126912_Content_90 = {
    Text = "I wanted to stop your schemes before any murder happened. But it's too late now."
  },
  AvgDialog_126912_Content_91 = {
    Text = "Now, all I ask is this: who are you, really?"
  },
  AvgDialog_126912_Content_92 = {
    Text = "Silver light erupts from the Silver Key at your chest, as if to pierce through every illusion and disguise."
  },
  AvgDialog_126912_Content_93 = {
    Text = "Hehe... hehehe~"
  },
  AvgDialog_126912_Content_94 = {
    Text = "Your attack seems to strike only air."
  },
  AvgDialog_126912_Content_95 = {
    Text = "She dissolves into a wisp of smoke, a veil of mist, an intangible, nameless presence."
  },
  AvgDialog_126912_Content_96 = {
    Text = "Follow me, <Italic:my Little Jasmine...>"
  },
  AvgDialog_126912_Content_97 = {
    Text = "The mist giggles, its voice dripping with enigmatic allure."
  },
  AvgDialog_126912_Content_98 = {
    Text = "Come with me, and see the truth behind this story."
  },
  AvgDialog_128696_Content_1 = {
    Text = "BANG! BANG! BANG!"
  },
  AvgDialog_128696_Content_10 = {Text = "Nautila!"},
  AvgDialog_128696_Content_11 = {
    Text = "Vortice rushes over in a panic, pressing her ear to Nautila's chest—only to find that Nautila has simply passed out cold from sheer exhaustion.."
  },
  AvgDialog_128696_Content_12 = {
    Text = "Vortice exhales in relief, then bursts into laughter."
  },
  AvgDialog_128696_Content_13 = {
    Text = "Pfft—hahahahaha!"
  },
  AvgDialog_128696_Content_14 = {
    Text = "She carries Nautila to the bed, then grabs you and, ignoring your protests entirely, rolls gleefully across the floor with you several times."
  },
  AvgDialog_128696_Content_15 = {
    Text = "Escape, we, not apart!"
  },
  AvgDialog_128696_Content_16 = {
    Text = "This is the first time Vortice has been this relaxed since that day. Her eyes are sparkling with hope, her nose nuzzling happily into the soft fur on your chest."
  },
  AvgDialog_128696_Content_17 = {
    Text = "Sleep... a little.... tomorrow morning... tomorrow morning..."
  },
  AvgDialog_128696_Content_18 = {
    Text = "Having stayed up for days, Vortice holds you tightly, leaning against the corner of Nautila's bed, and drifts into a deep sleep."
  },
  AvgDialog_128696_Content_19 = {Text = "..."},
  AvgDialog_128696_Content_2 = {
    Text = "ROAR—ROARROAR—ROAR!"
  },
  AvgDialog_128696_Content_20 = {
    Text = "@2, Vortice, @4..."
  },
  AvgDialog_128696_Content_21 = {
    Text = "@4... is here..."
  },
  AvgDialog_128696_Content_22 = {Text = "..."},
  AvgDialog_128696_Content_23 = {
    Text = "The ship has been sailing for only half a day when, without any warning, a massive storm strikes."
  },
  AvgDialog_128696_Content_24 = {
    Text = "Their course is completely lost. Rain lashes down from all sides, giving no chance of retreat for these overconfident challengers."
  },
  AvgDialog_128696_Content_25 = {
    Text = "The rudder remains eerily locked, stubbornly veering toward the vortex. No matter what Nautila and Vortice try, even coming close to breaking it, it refuses to turn."
  },
  AvgDialog_128696_Content_26 = {
    Text = "This can't be right... something's wrong! No warning signs, barometric pressure completely normal... everything was fine until we got near this water."
  },
  AvgDialog_128696_Content_27 = {
    Text = "It's just... It's like this whirlpool conjured the whirlwind specifically to set a trap for us."
  },
  AvgDialog_128696_Content_28 = {Text = "Trap?"},
  AvgDialog_128696_Content_29 = {
    Text = "And it has to happen right when we are closest to the vortex. If we were just five more—no, even three more nautical miles out, we'd be beyond its pull entirely."
  },
  AvgDialog_128696_Content_3 = {
    Text = "The dormant iron behemoth let out a hoarse roar. The steam whistle blares, and amid the fluttering of seagulls, the entire ship seems to slowly come alive."
  },
  AvgDialog_128696_Content_30 = {
    Text = "Your brain is a mess, and you're desperately trying to cry out—but what is it you're trying to say...?"
  },
  AvgDialog_128696_Content_31 = {
    Text = "SQUEAK, SQUEEEAKKK!"
  },
  AvgDialog_128696_Content_32 = {
    Text = "You can only let out a helpless shriek. You don't understand—can't they feel it?"
  },
  AvgDialog_128696_Content_33 = {
    Text = "(Don't get close to the whirlpool, Big One, don't go near it!)"
  },
  AvgDialog_128696_Content_34 = {
    Text = "That massive, horrifying presence—It has seen Vortice."
  },
  AvgDialog_128696_Content_35 = {
    Text = "<Red:It has no intention of letting anyone leave.>"
  },
  AvgDialog_128696_Content_36 = {Text = "..."},
  AvgDialog_128696_Content_37 = {
    Text = "It's okay, Coalsie, Vortice, is here."
  },
  AvgDialog_128696_Content_38 = {
    Text = "Yeah, trust me, Coalsie, Vortice. There's still a way out, I'll think of something!"
  },
  AvgDialog_128696_Content_39 = {Text = "Nautila..."},
  AvgDialog_128696_Content_4 = {
    Text = "The engine. Last step..."
  },
  AvgDialog_128696_Content_40 = {
    Text = "I'm the one who insisted we set sail. I'm the one who brought you here. I will think of something. I will get you both out safely!"
  },
  AvgDialog_128696_Content_41 = {
    Text = "<Change>Break the hull here and let water in for ballast..."
  },
  AvgDialog_128696_Content_42 = {
    Text = "<Change>No...@2 Engine, right... If I overload one of the engines, we might break free from @1's pull..."
  },
  AvgDialog_128696_Content_43 = {
    Text = "The girl drags you and Vortice through the compartments, trying everything as the whites of her eyes begin to bleed a frantic red."
  },
  AvgDialog_128696_Content_44 = {
    Text = "Clang—Bang!"
  },
  AvgDialog_128696_Content_45 = {Text = "Nauti..."},
  AvgDialog_128696_Content_46 = {
    Text = "The wrench slips from her exhausted grip, strikes the wall, then crashes down hard onto Nautila's foot. Yet, as if feeling no pain, she reaches down in a daze to pick it back up."
  },
  AvgDialog_128696_Content_47 = {
    Text = "<Change>It's too late, the whirlpool is getting closer... Why, why, why, WHY!! I have to save you both, I must... I must...!"
  },
  AvgDialog_128696_Content_48 = {
    Text = "Crack—Boom—!"
  },
  AvgDialog_128696_Content_49 = {
    Text = "The storm and the constant battering finally push the cabin past its limits. With a sharp crack, a rotted plank plummets from above, heading straight for Nautila—"
  },
  AvgDialog_128696_Content_5 = {
    Text = "Great! Vortice, Coalsie, we did it!"
  },
  AvgDialog_128696_Content_50 = {
    Text = "<Big:Nautila! Stop!>"
  },
  AvgDialog_128696_Content_51 = {
    Text = "When Nautila opens her eyes—eyes she has squeezed shut in terror—she sees something she has never expected."
  },
  AvgDialog_128696_Content_52 = {
    Text = "Vortice has braced herself against the wall with one arm, shielding Nautila beneath her, while her other hand holds the entire ceiling up."
  },
  AvgDialog_128696_Content_53 = {Text = "Ngh..."},
  AvgDialog_128696_Content_54 = {Text = "Hah!"},
  AvgDialog_128696_Content_55 = {
    Text = "With one great shove, Vortice hurls the ceiling away, then grabs the near-delirious Nautila and cups her face in both hands, forcing their eyes to meet."
  },
  AvgDialog_128696_Content_56 = {
    Text = "It's fine, go back, next time."
  },
  AvgDialog_128696_Content_57 = {
    Text = "Go back... But..."
  },
  AvgDialog_128696_Content_58 = {
    Text = "Nautila looks around blankly, letting the torrential rain pour down on her."
  },
  AvgDialog_128696_Content_59 = {
    Text = "The storm rages with thunder and lightning, striking every nerve like relentless music at a demon's feast."
  },
  AvgDialog_128696_Content_6 = {
    Text = "Nautila has worked herself to the bone, barely sleeping to patch the hull. With three days left before the predicted storm, all key parts were back in place."
  },
  AvgDialog_128696_Content_60 = {
    Text = "The whirlpool's pull is too strong... we can't turn back anymore..."
  },
  AvgDialog_128696_Content_61 = {
    Text = "Without a word in response, Vortice drags the diving suit out of the cabin and, with no idea how it works, tries to force it on Nautila anyway."
  },
  AvgDialog_128696_Content_62 = {
    Text = "The wetsuit? No way—if I put it on, what about you?"
  },
  AvgDialog_128696_Content_63 = {
    Text = "By now, the ship is tilting fully and uncontrollably toward the whirlpool."
  },
  AvgDialog_128696_Content_64 = {
    Text = "<Shake:Creak—Squeak—>"
  },
  AvgDialog_128696_Content_7 = {
    Text = "Just need to... secure the anchor... huff... so sleepy..."
  },
  AvgDialog_128696_Content_8 = {Text = "Thump."},
  AvgDialog_128696_Content_9 = {
    Text = "Chirp?! Chirp—? (Human?! Human?!!!)"
  },
  AvgDialog_128697_Content_1 = {
    Text = "Good. Better. Bestest!"
  },
  AvgDialog_128697_Content_10 = {Text = "..."},
  AvgDialog_128697_Content_11 = {
    Text = "<Italic: Cheering>"
  },
  AvgDialog_128697_Content_12 = {
    Text = "Although, yes, she is perhaps a little destructive."
  },
  AvgDialog_128697_Content_13 = {
    Text = "Keeper! Vortice! Defeat evil homework! Strong!"
  },
  AvgDialog_128697_Content_14 = {
    Text = "Huh... Keeper... Coalsie?"
  },
  AvgDialog_128697_Content_15 = {
    Text = "Vortice's beast-like instinct catches the difference instantly. She springs like a catapult and lunges in, wrapping you in a crushing hug."
  },
  AvgDialog_128697_Content_16 = {
    Text = "Ow! Vortice, that hurts!"
  },
  AvgDialog_128697_Content_17 = {
    Text = "At the same time, the muzzle she's wearing delivers a solid blow to your poor nose."
  },
  AvgDialog_128697_Content_18 = {
    Text = "Muzzle, restraints, Vorticesteel, good! Heh heh, Vortice, safe."
  },
  AvgDialog_128697_Content_19 = {
    Text = "The device Mythag specially developed for her effectively contains her power overflow. Now, Vortice's maximum destructive power is only equivalent to that of a slightly stronger-than-average human."
  },
  AvgDialog_128697_Content_2 = {
    Text = "Hello, Keeper. Regarding Awakener No. O-1841: Given her recent Awakening, occasional bouts of ferocity, and incomplete control over her abilities, we advise exercising caution in all interactions with her."
  },
  AvgDialog_128697_Content_20 = {
    Text = "Friends, after that, perfect adventure? Yes? No?"
  },
  AvgDialog_128697_Content_21 = {
    Text = "It takes considerable effort to peel the exuberant, puppy-like girl off yourself. Finally willing to sit still, she perches opposite your desk, fixing you with those bright, gleaming eyes."
  },
  AvgDialog_128697_Content_22 = {Text = "Hmm..."},
  AvgDialog_128697_Content_23 = {
    Text = "Actually..."
  },
  AvgDialog_128697_Content_24 = {
    Text = "Beneath Moskstraumen lies a massive D-Rift. Although Nautila and I managed to escape the influence of the whirlpool, we both showed signs of memory loss."
  },
  AvgDialog_128697_Content_25 = {
    Text = "You only paused for a brief moment before choosing to use \"I\"—adopting the consciousness from that dream as your own."
  },
  AvgDialog_128697_Content_26 = {
    Text = "Nautila has been looking for you ever since. She founded an adventuring party, but encountered another disaster during their return voyage..."
  },
  AvgDialog_128697_Content_27 = {
    Text = "She probably doesn’t remember anymore, but... she made the same choice as you."
  },
  AvgDialog_128697_Content_28 = {Text = "I see..."},
  AvgDialog_128697_Content_29 = {
    Text = "But, that's great."
  },
  AvgDialog_128697_Content_3 = {
    Text = "Thank you, Erica. But it's fine, I think I know my... friend well enough."
  },
  AvgDialog_128697_Content_30 = {Text = "Of course"},
  AvgDialog_128697_Content_31 = {
    Text = "Of course we did! Later, Nautila and I..."
  },
  AvgDialog_128697_Content_32 = {
    Text = "In short, until Nautila and I became too old to move, we went through all kinds of adventures."
  },
  AvgDialog_128697_Content_33 = {
    Text = "You rack your brain and weave every adventure story you've ever heard in your brief, conscious year of life into the tale you spin for Vortice."
  },
  AvgDialog_128697_Content_34 = {
    Text = "After all, heavens, there is simply no way you could say anything cruel to those innocent eyes."
  },
  AvgDialog_128697_Content_35 = {
    Text = "Story of Robin@2, Vortice, has heard."
  },
  AvgDialog_128697_Content_36 = {
    Text = "<Gray:Oh no, I forgot that was general studies reading...>"
  },
  AvgDialog_128697_Content_37 = {Text = "It's okay."},
  AvgDialog_128697_Content_38 = {Text = "Huh?"},
  AvgDialog_128697_Content_39 = {
    Text = "Vortice lowers her head and presses her face against your palm, just as she did when you were still little Coalsie."
  },
  AvgDialog_128697_Content_4 = {
    Text = "Unlike what the Academy had anticipated, your first Link with this volatile Awakener went surprisingly smoothly."
  },
  AvgDialog_128697_Content_40 = {
    Text = "Friend, Coalsie, meet again."
  },
  AvgDialog_128697_Content_41 = {
    Text = "Coalsie, go through the dark, remember Vortice, good."
  },
  AvgDialog_128697_Content_42 = {
    Text = "She breaks into a smile—wide, bright, and so entirely happy."
  },
  AvgDialog_128697_Content_43 = {
    Text = "But, bracelet, gone."
  },
  AvgDialog_128697_Content_44 = {
    Text = "But, we here, better, better than better!"
  },
  AvgDialog_128697_Content_45 = {Text = "Vortice..."},
  AvgDialog_128697_Content_46 = {Text = "Chirp?"},
  AvgDialog_128697_Content_47 = {
    Text = "??Why is there a sea otter wearing a Mythag hat here?"
  },
  AvgDialog_128697_Content_48 = {
    Text = "My apologies, Keeper, it seems many students have grown rather fond of this stray sea otter and have adorned it with some unnecessary decorations."
  },
  AvgDialog_128697_Content_49 = {
    Text = "Erica will initiate the expulsion procedure as soon as possible. One, two—"
  },
  AvgDialog_128697_Content_5 = {
    Text = "After this unexpected dream, you think you've found the answer."
  },
  AvgDialog_128697_Content_50 = {
    Text = "Ah, sea otter! Cute! Play with Vortice!"
  },
  AvgDialog_128697_Content_51 = {
    Text = "Bang. Thud. Clatter—"
  },
  AvgDialog_128697_Content_52 = {Text = "BANG!"},
  AvgDialog_128697_Content_53 = {
    Text = "Ouch, Vortice!"
  },
  AvgDialog_128697_Content_54 = {
    Text = "Nautila has just walked into the classroom when she sees her new best friend barreling wildly around the room chasing a sea otter in a Mythag hat, leaving a trail of demolished equipment in her wake."
  },
  AvgDialog_128697_Content_55 = {
    Text = "Keeper, please tell Professor Erica that I'll fix everything in the classroom!"
  },
  AvgDialog_128697_Content_56 = {
    Text = "Vortice, stop!"
  },
  AvgDialog_128697_Content_57 = {
    Text = "Eek— squeak—!"
  },
  AvgDialog_128697_Content_58 = {Text = "SQUEAK!"},
  AvgDialog_128697_Content_59 = {
    Text = "<Italic:*happy noises*>"
  },
  AvgDialog_128697_Content_6 = {
    Text = "She loves roasted meat and the sea. She's timid, and she hates the cold, darkness, and loneliness... When she's scared, she sniffs quietly so no one notices."
  },
  AvgDialog_128697_Content_60 = {
    Text = "If I'm not mistaken, that sea otter is saying \"play with me,\" right? ...How exactly does it communicate with Vortice?"
  },
  AvgDialog_128697_Content_61 = {
    Text = "Eh?! Why can I understand the sea otter too?!"
  },
  AvgDialog_128697_Content_62 = {
    Text = "Hold on, if that's the case..."
  },
  AvgDialog_128697_Content_63 = {
    Text = "Ahem. O nameless Mythag sea otter, hereby I bestow upon you the title of \"Coalsie.\""
  },
  AvgDialog_128697_Content_64 = {
    Text = "You shall inherit the name of Coalsie and become the great, glorious Coalsie the Second!"
  },
  AvgDialog_128697_Content_65 = {Text = "!"},
  AvgDialog_128697_Content_66 = {
    Text = "Coalsie the Second! Coalsie the Second!"
  },
  AvgDialog_128697_Content_67 = {
    Text = "Chirp— (OTTER IMPACT!)"
  },
  AvgDialog_128697_Content_68 = {
    Text = "NAUTILA—!!"
  },
  AvgDialog_128697_Content_69 = {
    Text = "Perfect, it's a total mess now."
  },
  AvgDialog_128697_Content_7 = {
    Text = "It's a golden afternoon in Mythag. Sunlight filters through the stained glass windows and falls across the face of the girl wrestling with her Leonian language textbook."
  },
  AvgDialog_128697_Content_70 = {
    Text = "And so, as my rightful heir, <Small:it is your solemn duty to handle what displeases me, Coalsie the First...>"
  },
  AvgDialog_128697_Content_71 = {
    Text = "You whistle casually, then quietly, ever so quietly..."
  },
  AvgDialog_128697_Content_72 = {
    Text = "...toss your calculus homework toward the sea otter's paws amidst the commotion."
  },
  AvgDialog_128697_Content_73 = {
    Text = "In the blink of an eye, the homework turns into crumpled scraps, lying peacefully in a pile of waste paper."
  },
  AvgDialog_128697_Content_74 = {
    Text = "What a beautiful day, isn't it, Nautila, Vortice?"
  },
  AvgDialog_128697_Content_75 = {Text = "SQUEAK—!"},
  AvgDialog_128697_Content_76 = {
    Text = "Mythag, today too, is as friendly and peaceful as ever."
  },
  AvgDialog_128697_Content_77 = {
    Text = "How wonderful. How truly, perfectly wonderful."
  },
  AvgDialog_128697_Content_8 = {
    Text = "But she's also incredibly brave—always ready to shield her friends from everything she hates."
  },
  AvgDialog_128697_Content_9 = {
    Text = "Riiip—the textbook splits clean in two, right in the middle of what was shaping up to be quite a touching moment."
  },
  AvgDialog_128698_Content_1 = {
    Text = "Splish~Splash~"
  },
  AvgDialog_128698_Content_10 = {
    Text = "Power and fuel aren't the problem, but the hull is just too fragile. Vortice, is there any way to steer clear of that giant whirlpool? That's where our fleet ran into trouble."
  },
  AvgDialog_128698_Content_11 = {
    Text = "...Can't get out."
  },
  AvgDialog_128698_Content_12 = {
    Text = "Vortice shakes her head, picks you up again, then the two of you gesture wildly together—flailing all four hands and four feet in unison."
  },
  AvgDialog_128698_Content_13 = {
    Text = "Bad people, catch Mama and Papa. Vortice, bite, taken away. Coalsie, on ship, meet."
  },
  AvgDialog_128698_Content_14 = {
    Text = "Ocean, whoosh— then here. Vortice, try, but not work."
  },
  AvgDialog_128698_Content_15 = {
    Text = "You were taken by bad people and separated from your parents... and you haven't been able to get out since?"
  },
  AvgDialog_128698_Content_16 = {
    Text = "Mama, Papa, not here."
  },
  AvgDialog_128698_Content_17 = {
    Text = "I'm sorry..."
  },
  AvgDialog_128698_Content_18 = {
    Text = "Oh! Mama, Papa, like... come!"
  },
  AvgDialog_128698_Content_19 = {
    Text = "Vortice! Where are you dragging me?!"
  },
  AvgDialog_128698_Content_2 = {
    Text = "Once we get the bearings in this section fully repaired, the rudder should—"
  },
  AvgDialog_128698_Content_20 = {Text = "..."},
  AvgDialog_128698_Content_21 = {
    Text = "Huff... huff... What are you, a monster?! How can you swim this fast while carrying me?!"
  },
  AvgDialog_128698_Content_22 = {
    Text = "Wait—where are we?"
  },
  AvgDialog_128698_Content_23 = {
    Text = "SQUEAKKK—!"
  },
  AvgDialog_128698_Content_24 = {
    Text = "You gleefully jump into the water first, startling all the fish around."
  },
  AvgDialog_128698_Content_25 = {
    Text = "As you and Vortice splash in one after another with joyful shouts, ripples rise from the depths below, as if responding to your calls."
  },
  AvgDialog_128698_Content_26 = {
    Text = "Mama, Papa, like them! Nautila, Vortice, same!"
  },
  AvgDialog_128698_Content_27 = {
    Text = "Several beautiful white dolphins glide up from the depths, gathering around you, nuzzling you and Vortice affectionately with their snouts and fins."
  },
  AvgDialog_128698_Content_28 = {
    Text = "They circle around you gracefully, some even leaping out of the water and splashing Nautila with little jets of spray, as if inviting her to join in."
  },
  AvgDialog_128698_Content_29 = {
    Text = "They're... dolphins? Vortice, are you saying your parents are dolphins too?"
  },
  AvgDialog_128698_Content_3 = {
    Text = "The rutter?"
  },
  AvgDialog_128698_Content_30 = {
    Text = "Yes. Little Vortice, lost. Dolphins, feed little Vortice. Vortice, grow up!"
  },
  AvgDialog_128698_Content_31 = {
    Text = "Vortice, feed Coalsie. Coalsie, grow up!"
  },
  AvgDialog_128698_Content_32 = {
    Text = "Vortice bursts into giggles, dodging the water you splash at her in annoyance—and then, together, you both reach out toward Nautila."
  },
  AvgDialog_128698_Content_33 = {
    Text = "Trust me. Friend."
  },
  AvgDialog_128698_Content_34 = {Text = "...Okay!"},
  AvgDialog_128698_Content_35 = {
    Text = "Nautila grips your hands tight. One in front, one behind, you and Vortice lead her toward a hidden cave."
  },
  AvgDialog_128698_Content_36 = {
    Text = "After a moment of darkness, one patch, two patches... countless patches of dreamlike, hazy light stir to life. Jellyfish surge toward the surface, pushed away by gentle currents, until even brighter light spills down from the dome above."
  },
  AvgDialog_128698_Content_37 = {
    Text = "...Am I dreaming right now?"
  },
  AvgDialog_128698_Content_38 = {
    Text = "Sunlight pierces through layers of rock, painting the seafloor in shifting shades of blue. Colorful coral and countless sea creatures cut through the blue, creating a sight so breathtaking that it leaves one speechless."
  },
  AvgDialog_128698_Content_39 = {
    Text = "Sea anemones trail their venomous tendrils in a slow, hypnotic dance. Shellfish cling close, living in quiet harmony with them. Predators lurk in the dark of the abyss, biding their time. This place is dangerous and beautiful, dark and dazzling—a world unto itself, a miniature of the ocean."
  },
  AvgDialog_128698_Content_4 = {
    Text = "The rudder. It's like a steering wheel—it controls which direction you go. Do you know what a steering wheel is?"
  },
  AvgDialog_128698_Content_40 = {Text = "Nautila?"},
  AvgDialog_128698_Content_41 = {
    Text = "This. Pretty. For you."
  },
  AvgDialog_128698_Content_42 = {
    Text = "Vortice takes out a glistening, lustrous pearl. With an expression of utmost sincerity, she places it carefully in Nautila's palm."
  },
  AvgDialog_128698_Content_43 = {
    Text = "Vortice, here, like. Vortice, treasure, like. Nautila, friend, for you."
  },
  AvgDialog_128698_Content_44 = {
    Text = "(I asked you for that thing so many times and you never gave it to me! You big meanie!)"
  },
  AvgDialog_128698_Content_45 = {
    Text = "You grumble to yourself, but thinking of all the delicious grilled fish and seafood stew you’ve eaten lately, you generously push the pearl further into Nautila's hand along with Vortice."
  },
  AvgDialog_128698_Content_46 = {
    Text = "Oh—thank you! Well then, I have a gift for Vortice, too."
  },
  AvgDialog_128698_Content_47 = {Text = "A give?"},
  AvgDialog_128698_Content_48 = {
    Text = "Nautila unties the small bracelet from her wrist—the one she always wears, adorned with a tiny nautilus charm."
  },
  AvgDialog_128698_Content_49 = {
    Text = "Something a friend gives to a friend is called a \"gift.\" The pearl is your gift to me. And this... this is my gift to you."
  },
  AvgDialog_128698_Content_5 = {Text = "Umm...?"},
  AvgDialog_128698_Content_50 = {
    Text = "My mother gave me a necklace and this bracelet, and I promised her I’d become a great adventurer."
  },
  AvgDialog_128698_Content_51 = {
    Text = "Vortice, I'll fix the ship soon. We'll leave together and go find your parents."
  },
  AvgDialog_128698_Content_52 = {
    Text = "And after that... would you be willing to wear this bracelet, bring Coalsie along, and come on an adventure with me?"
  },
  AvgDialog_128698_Content_53 = {Text = "..."},
  AvgDialog_128698_Content_54 = {
    Text = "Nautila, Vortice, Coalsie, adventure!"
  },
  AvgDialog_128698_Content_55 = {Text = "Wahoooo!"},
  AvgDialog_128698_Content_56 = {
    Text = "After a brief silence that almost feels like an illusion, Vortice breaks into her usual bright smile and hugs you tight as she cheers."
  },
  AvgDialog_128698_Content_57 = {
    Text = "Chirp! (Adventure!)"
  },
  AvgDialog_128698_Content_58 = {
    Text = "What could you possibly tell? You're just a sea otter. Even if you caught a hint of something, your small brain couldn't quite grasp it. And so you let it go, diving headfirst into the joyful atmosphere."
  },
  AvgDialog_128698_Content_59 = {
    Text = "Great, Coalsie, I've got a gift for you too!"
  },
  AvgDialog_128698_Content_6 = {
    Text = "A steering wheel is what controls where these big machines go—you turn the wheel, and the ship or car follows the path you set."
  },
  AvgDialog_128698_Content_60 = {Text = "..."},
  AvgDialog_128698_Content_61 = {Text = "!"},
  AvgDialog_128698_Content_62 = {
    Text = "The once-dilapidated ship cabin has been completely transformed—between two identical, simple but clean and sturdy beds sits a wooden chest stuffed full of plush cushions."
  },
  AvgDialog_128698_Content_63 = {
    Text = "Heh heh, now everyone gets their own bed."
  },
  AvgDialog_128698_Content_64 = {
    Text = "Before Nautila's voice even fades, you tumbled headfirst into your perfect little den—Nautila even left you a special spot for your precious little shells!"
  },
  AvgDialog_128698_Content_65 = {
    Text = "The warmth of the seafood soup from dinner still lingers in your belly, and to the rhythm of the girls' steady breathing, you drift off to sleep before long."
  },
  AvgDialog_128698_Content_66 = {
    Text = "But when night truly falls, that ominous feeling begins to spread, thick and viscous like the sea mist."
  },
  AvgDialog_128698_Content_67 = {
    Text = "<Shake:Vortice, @3...>"
  },
  AvgDialog_128698_Content_68 = {
    Text = "<Shake:Return to me, submit to me, @4...@4!>"
  },
  AvgDialog_128698_Content_69 = {
    Text = "In the darkness, the ocean becomes filled with horror and mystery. Sunlight no longer touches the surface, and deep in the abyss, something stirs with a low, guttural rumble."
  },
  AvgDialog_128698_Content_7 = {
    Text = "Ohhhh! A steering wheel! That's so cool!"
  },
  AvgDialog_128698_Content_70 = {
    Text = "You drift in the boundless, icy void, desperately trying to reach the distant figure weeping softly in the dark."
  },
  AvgDialog_128698_Content_71 = {
    Text = "Chirp— (Big One—)"
  },
  AvgDialog_128698_Content_72 = {
    Text = "SQUEAAKKK! (Big One!)"
  },
  AvgDialog_128698_Content_73 = {
    Text = "You jolt awake. There's no gentle breathing from the sleeping girls, everything is dead silent. You crawl out of your nest and follow Vortice's scent to the deck."
  },
  AvgDialog_128698_Content_74 = {
    Text = "She is staring at the whirlpool in the distance."
  },
  AvgDialog_128698_Content_75 = {
    Text = "(That dream again... how many times has it been, since those awful humans died and we made our home here?)"
  },
  AvgDialog_128698_Content_76 = {
    Text = "Call, Vortice, there."
  },
  AvgDialog_128698_Content_77 = {
    Text = "Scary... no..."
  },
  AvgDialog_128698_Content_78 = {
    Text = "Hey, Coalsie, Vortice, what are you two doing outside?"
  },
  AvgDialog_128698_Content_79 = {
    Text = "Nautila's voice cuts through Vortice's dream-like murmurs. The next moment, Nautila excitedly pushes a set of metal equipment toward you both."
  },
  AvgDialog_128698_Content_8 = {Text = "..."},
  AvgDialog_128698_Content_80 = {
    Text = "Vortice, you said diving too deep makes you uncomfortable, but you still want to see what's down there, right?"
  },
  AvgDialog_128698_Content_81 = {
    Text = "I fixed up the diving suit I found on the ship. With this, you can dive longer, and you won't feel sick anymore."
  },
  AvgDialog_128698_Content_82 = {
    Text = "Too bad I need to fix the ship before the next storm hits. After the storm, I'll make myself a set too."
  },
  AvgDialog_128698_Content_83 = {
    Text = "Someday, we'll be able to explore the sea together!"
  },
  AvgDialog_128698_Content_84 = {
    Text = "Vortice is unusually quiet. After a moment, she gives a firm nod, scoops you up, and pulls Nautila into a big bear hug."
  },
  AvgDialog_128698_Content_85 = {Text = "Escape."},
  AvgDialog_128698_Content_86 = {
    Text = "Vortice, Nautila, Coalsie, Escape! Together!"
  },
  AvgDialog_128698_Content_9 = {
    Text = "The instrument data shows that we've got a week at most before a storm hits—one that'll last at least half a month. This ship is already in rough shape... I don't know if it'll even hold together after the storm."
  },
  AvgDialog_128699_Content_1 = {
    Text = "Pitter, patter."
  },
  AvgDialog_128699_Content_10 = {
    Text = "Vortice, listen to me—I'm the one who suggested we set sail, and I'm the one who misjudged the weather, so it's my responsibility to get you and Coalsie out of here."
  },
  AvgDialog_128699_Content_11 = {
    Text = "I'll take off the diving suit and give it to you. The boat can still move, so I'll try to steer it toward the edge of the whirlpool, and then you..."
  },
  AvgDialog_128699_Content_12 = {Text = "You..."},
  AvgDialog_128699_Content_13 = {
    Text = "Nautila stands frozen in place. For the first time, she sees that carefree, lively, naive girl wearing a complex, worried expression."
  },
  AvgDialog_128699_Content_14 = {
    Text = "Nautila, I'm sorry."
  },
  AvgDialog_128699_Content_15 = {
    Text = "Vortice reaches out her hand. Though she doesn't understand how the device works, driven by beast-like instinct, she forcibly finishes dressing Nautila in the diving suit."
  },
  AvgDialog_128699_Content_16 = {
    Text = "Vortice, danger, feeling."
  },
  AvgDialog_128699_Content_17 = {
    Text = "But, hope, won't happen."
  },
  AvgDialog_128699_Content_18 = {
    Text = "Rain pours in through a hole in the roof, splashing on both of them."
  },
  AvgDialog_128699_Content_19 = {
    Text = "Silence fills the cabin. It is Vortice who finally breaks it."
  },
  AvgDialog_128699_Content_2 = {
    Text = "<Shake:Creak—Squeak—>"
  },
  AvgDialog_128699_Content_20 = {
    Text = "Vortice, come here, dream."
  },
  AvgDialog_128699_Content_21 = {
    Text = "Vortice dream... something, call Vortice..."
  },
  AvgDialog_128699_Content_22 = {
    Text = "But, don't want to go. Cold, no one around, lonely..."
  },
  AvgDialog_128699_Content_23 = {
    Text = "Nautila suddenly realizes why the torrential rain fell early, why the tornado appeared without warning. She begins to tremble uncontrollably."
  },
  AvgDialog_128699_Content_24 = {
    Text = "That thing... right there..."
  },
  AvgDialog_128699_Content_25 = {
    Text = "Following Vortice's finger, Nautila feels a sense of fear crawling up from her subconscious."
  },
  AvgDialog_128699_Content_26 = {
    Text = "Fear from the bottom of the Moskstraumen. Fear of something beyond mortal comprehension."
  },
  AvgDialog_128699_Content_27 = {Text = "......"},
  AvgDialog_128699_Content_28 = {
    Text = "No, no, no—I know what you're going to do, no way!"
  },
  AvgDialog_128699_Content_29 = {
    Text = "Trust me, there has to be another way!"
  },
  AvgDialog_128699_Content_3 = {
    Text = "The raging current grips the hull like two enormous hands wringing out a wet cloth."
  },
  AvgDialog_128699_Content_30 = {
    Text = "Nautila clutches at Vortice desperately. Though Vortice, with her beast-like strength, could shake Nautila off easily at any moment, she doesn't."
  },
  AvgDialog_128699_Content_31 = {
    Text = "She just picks you up and nuzzles you affectionately."
  },
  AvgDialog_128699_Content_32 = {
    Text = "Friend, strong, but, no. Only, Vortice, can."
  },
  AvgDialog_128699_Content_33 = {
    Text = "Only, Vortice, can."
  },
  AvgDialog_128699_Content_34 = {
    Text = "...Why, why does it have to be like this?"
  },
  AvgDialog_128699_Content_35 = {
    Text = "Friend, not cry, smile, Vortice, like!"
  },
  AvgDialog_128699_Content_36 = {
    Text = "Uh, sorry—I noticed you both eat your fish raw, so I did a little... cooking. No seasoning though. Wanna try?"
  },
  AvgDialog_128699_Content_37 = {
    Text = "<Italic:Om nom!>"
  },
  AvgDialog_128699_Content_38 = {
    Text = "<Italic:Om nom!>"
  },
  AvgDialog_128699_Content_39 = {Text = "Yummy!"},
  AvgDialog_128699_Content_4 = {
    Text = "The ship lets out a groan under the immense strain. Vortice is shouting over the storm, desperately stuffing Nautila into the diving suit while pulling you tighter against her with her other arm."
  },
  AvgDialog_128699_Content_40 = {
    Text = "Adventure, expect!"
  },
  AvgDialog_128699_Content_41 = {
    Text = "Vortice, I'll fix the ship soon. We'll leave together and go find your parents."
  },
  AvgDialog_128699_Content_42 = {
    Text = "And after that... would you be willing to wear this bracelet, bring Coalsie along, and come on an adventure with me?"
  },
  AvgDialog_128699_Content_43 = {
    Text = "Nautila, Vortice, Coalsie, adventure!"
  },
  AvgDialog_128699_Content_44 = {
    Text = "Friend, like!"
  },
  AvgDialog_128699_Content_45 = {
    Text = "Friend, give Vortice, so much, so much!"
  },
  AvgDialog_128699_Content_46 = {
    Text = "So, now, Vortice give friend, so much, so much!"
  },
  AvgDialog_128699_Content_47 = {
    Text = "She plants herself like a wall against the raging storm, holding you and Nautila firmly in her arms. Then she takes a deep breath, breaks into a wide, reassuring grin that is so entirely hers."
  },
  AvgDialog_128699_Content_48 = {
    Text = "Vortice, come back, for sure!"
  },
  AvgDialog_128699_Content_49 = {
    Text = "...Alright, I believe you, Vortice. When you get back, I'll have the finest ship in the world ready, and then I'll take you and Coalsie on the greatest adventure ever."
  },
  AvgDialog_128699_Content_5 = {
    Text = "Danger! Grab!"
  },
  AvgDialog_128699_Content_50 = {
    Text = "Nautila wipes away her tears, pulls herself together, and manages a somewhat ugly smile."
  },
  AvgDialog_128699_Content_51 = {
    Text = "Seeing Nautila finally let her go, Vortice quietly, ever so quietly, takes your paw in hers and presses her face against your paw pads."
  },
  AvgDialog_128699_Content_52 = {
    Text = "Coalsie, do not, afraid."
  },
  AvgDialog_128699_Content_53 = {
    Text = "Eeek... SQUEAK! (You're leaving me behind...)"
  },
  AvgDialog_128699_Content_54 = {
    Text = "SQUEAK! SQUEAKKK!— (You're leaving me behind!!)"
  },
  AvgDialog_128699_Content_55 = {
    Text = "Your wailing cries fill the air as you are placed into Nautila's arms. The next moment, as the ship tilts again, Vortice turns without hesitation and runs toward the whirlpool."
  },
  AvgDialog_128699_Content_56 = {Text = "...Plop."},
  AvgDialog_128699_Content_57 = {
    Text = "Like a fish returning to her sea."
  },
  AvgDialog_128699_Content_58 = {Text = "VORTICE!"},
  AvgDialog_128699_Content_59 = {
    Text = "The storm drowns out all the screams. A mountainous wave crashes over the deck and sweeps you both into the sea as well."
  },
  AvgDialog_128699_Content_6 = {
    Text = "BOOM————"
  },
  AvgDialog_128699_Content_60 = {
    Text = "Beneath the dark blue waters, countless thread-like tendrils of black ooze unfurl toward Vortice. Her hands dissolve into massive churning currents, her expression serene and tranquil, the depths of her eyes calm and still, as if the eye of the whirlpool itself."
  },
  AvgDialog_128699_Content_61 = {
    Text = "Vortice, whirlpool. Vortice, steering wheel."
  },
  AvgDialog_128699_Content_62 = {
    Text = "Coalsie, Nautila, here, always."
  },
  AvgDialog_128699_Content_63 = {
    Text = "Vortice finally can't help but burst into tears, pressing her hand against her own chest."
  },
  AvgDialog_128699_Content_64 = {
    Text = "Then she raises her hand. A vortex carrying destructive force, yet abnormally gentle, pushes you both far, far away from the whirlpool."
  },
  AvgDialog_128699_Content_65 = {
    Text = "Strand by strand, the dark slime clings to Vortice's body, spreading across her entire body in an instant."
  },
  AvgDialog_128699_Content_66 = {
    Text = "The whirlpool begins to converge inward toward its center, carrying with it the fulfillment of Its desire. The girl, as if entwined and pulled by countless dark seaweeds, slowly sinks into the sunless deep."
  },
  AvgDialog_128699_Content_67 = {Text = "..."},
  AvgDialog_128699_Content_68 = {
    Text = "Everything has settled down. The sky is a clear, washed blue. On the tranquil sea, the ship drifts quietly."
  },
  AvgDialog_128699_Content_69 = {
    Text = "Huh, where am I, and why am I in the water? Ugh... so stuffy!"
  },
  AvgDialog_128699_Content_7 = {
    Text = "The violent jolt sends Nautila flying, slamming her into a wooden barrel that has rolled across the ground."
  },
  AvgDialog_128699_Content_70 = {
    Text = "You stare curiously at the human bobbing on the surface in that weird outfit."
  },
  AvgDialog_128699_Content_71 = {
    Text = "(How did I end up here, and who's that?)"
  },
  AvgDialog_128699_Content_72 = {Text = "Plap-plap."},
  AvgDialog_128699_Content_73 = {Text = "Plap-plap."},
  AvgDialog_128699_Content_74 = {
    Text = "(Oh right, I'm a sea otter! And sea otters look for shells. Shells, shells, shells!)"
  },
  AvgDialog_128699_Content_75 = {
    Text = "You dive joyfully into the warm water, swimming in the opposite direction from the human struggling toward the ship."
  },
  AvgDialog_128699_Content_76 = {
    Text = "You don't notice your tears merging into the sea."
  },
  AvgDialog_128699_Content_8 = {Text = "Hmm..."},
  AvgDialog_128699_Content_9 = {
    Text = "Nautila, enduring the pain, stumbles to her feet and rushes to Vortice's side."
  },
  AvgDialog_128700_Content_1 = {
    Text = "Gurgle... Gurgle..."
  },
  AvgDialog_128700_Content_10 = {
    Text = "You're a year-and-a-half-old sea otter, out foraging with your favorite Big One."
  },
  AvgDialog_128700_Content_100 = {
    Text = "Saliva floods your mouth. Tempted by the cooked food, you and Vortice lunge forward almost simultaneously, both biting into the grilled fish."
  },
  AvgDialog_128700_Content_101 = {Text = "Yummy—!!"},
  AvgDialog_128700_Content_102 = {
    Text = "Oh—ah... Nautila, your arm?"
  },
  AvgDialog_128700_Content_103 = {
    Text = "Just a dislocation—I already popped it back in. I'm an adventurer, so it's no big deal. And thank you for the medicine!"
  },
  AvgDialog_128700_Content_104 = {
    Text = "<Small: (Though it's super bitter and has a strong kick, it works really well.)>"
  },
  AvgDialog_128700_Content_105 = {
    Text = "Woohoo!! Happy, hug—"
  },
  AvgDialog_128700_Content_106 = {
    Text = "Hehe. Vortice. Careful."
  },
  AvgDialog_128700_Content_107 = {
    Text = "Eh? Eh! Don't worry, Vortice. Next time, I'll just yell out loud so you know to let go, okay?"
  },
  AvgDialog_128700_Content_108 = {Text = "Chirp!"},
  AvgDialog_128700_Content_11 = {
    Text = "(What do we have here? Kelp, seaweed, little stones...)"
  },
  AvgDialog_128700_Content_12 = {
    Text = "(And Stone, Stone's aunt, Stone's grandfather...?)"
  },
  AvgDialog_128700_Content_13 = {
    Text = "(STONE! Tell your family to stop swimming around here!!)"
  },
  AvgDialog_128700_Content_14 = {
    Text = "<Shake:ROAARRR—>"
  },
  AvgDialog_128700_Content_15 = {Text = "(Uh oh...)"},
  AvgDialog_128700_Content_16 = {
    Text = "The sea surges into a massive whirlpool. A familiar figure comes barreling toward you, hauling something large on her back!"
  },
  AvgDialog_128700_Content_17 = {
    Text = "Coalsie! Meat! Vortice find!"
  },
  AvgDialog_128700_Content_18 = {
    Text = "Happy! Go home! Together!"
  },
  AvgDialog_128700_Content_19 = {
    Text = "Before you can protest, the girl scoops you up onto her back as well and shoots toward the surface like a fish."
  },
  AvgDialog_128700_Content_2 = {
    Text = "<Shake:Gurgle... Grumble...>"
  },
  AvgDialog_128700_Content_20 = {Text = "..."},
  AvgDialog_128700_Content_21 = {
    Text = "BOOM—! Lightning flashes, thunder rolls, and the swollen rainclouds finally burst, dumping their water into the sea."
  },
  AvgDialog_128700_Content_22 = {
    Text = "You and Vortice retreat to the safe cabin, staring at each other."
  },
  AvgDialog_128700_Content_23 = {
    Text = "Eek? S-Squeakk?! (Is THAT the meat? Big One, it looks just like you!)"
  },
  AvgDialog_128700_Content_24 = {
    Text = "Just like me?"
  },
  AvgDialog_128700_Content_25 = {
    Text = "Vortice tilts her head with her classic puzzled face, then finally takes a good look at the \"meat\" she dropped on the floor."
  },
  AvgDialog_128700_Content_26 = {
    Text = "Pfft—urgh."
  },
  AvgDialog_128700_Content_27 = {
    Text = "What just happened... my head feels like it's been underwater the whole time... where is this... am I dead?"
  },
  AvgDialog_128700_Content_28 = {
    Text = "The stranger coughs hard and spits out a mouthful of seawater."
  },
  AvgDialog_128700_Content_29 = {
    Text = "Friend? Friend!! Same as Vortice!"
  },
  AvgDialog_128700_Content_3 = {
    Text = "<Shake:Grumble... Grumble... Grumble...>"
  },
  AvgDialog_128700_Content_30 = {Text = "Eh... huh?"},
  AvgDialog_128700_Content_31 = {
    Text = "<LightGray:Is she from some nearby indigenous tribe? Strange... And where exactly is this?>"
  },
  AvgDialog_128700_Content_32 = {
    Text = "You sense she's wary, but not hostile. Quietly, you inch closer to get a better look at this newcomer."
  },
  AvgDialog_128700_Content_33 = {
    Text = "This should be a ship's cabin. Worn, but structurally sound for the most part..."
  },
  AvgDialog_128700_Content_34 = {
    Text = "Wait—are those Northdrey Corporation rivets?! Water level gauges, annular slide valves—"
  },
  AvgDialog_128700_Content_35 = {
    Text = "Let's see, in that case..."
  },
  AvgDialog_128700_Content_36 = {
    Text = "The stranger excitedly rummages through the jam-packed cabin. Meanwhile, Vortice stands nearby, blinking with cheerful curiosity."
  },
  AvgDialog_128700_Content_37 = {
    Text = "Shiny, pretty. Vortice, bring. Friend, you like?"
  },
  AvgDialog_128700_Content_38 = {
    Text = "Vortice, with these parts, I can get this ship running again. Could you give them to me?"
  },
  AvgDialog_128700_Content_39 = {
    Text = "Once we reach Aglo, I promise I'll bring you even more, even prettier shiny things."
  },
  AvgDialog_128700_Content_4 = {
    Text = "You lie on your back in the warm sea, comfortably stretching your short limbs, and make a perfect turn."
  },
  AvgDialog_128700_Content_40 = {
    Text = "SQUEAK—!! (No way! My pretty little ball is still in there!!)"
  },
  AvgDialog_128700_Content_41 = {
    Text = "You let out an angry squeal and lunge to snatch your ball back—but your attention is instantly pulled away by Vortice."
  },
  AvgDialog_128700_Content_42 = {
    Text = "Shh. Vortice, give you. Shells."
  },
  AvgDialog_128700_Content_43 = {
    Text = "Vortice quietly tucks two shells you'd been eyeing into your paws, then nudges those parts toward the stranger, signaling she can have them."
  },
  AvgDialog_128700_Content_44 = {
    Text = "Friend, like, Vortice give!"
  },
  AvgDialog_128700_Content_45 = {
    Text = "You have no idea why those bits make the stranger so excited, but you've already stopped caring. You blissfully bury your little snout deep into those beautiful shells Vortice never once let you near."
  },
  AvgDialog_128700_Content_46 = {
    Text = "Wonderful! Thank you... friend."
  },
  AvgDialog_128700_Content_47 = {
    Text = "Warmed by Vortice's open, earnest kindness, the stranger finally relaxes a bit and smiles at you both."
  },
  AvgDialog_128700_Content_48 = {
    Text = "By the way, my name is Nautila."
  },
  AvgDialog_128700_Content_49 = {
    Text = "Yay!! Nautila, Vortice, friends, happy!"
  },
  AvgDialog_128700_Content_5 = {
    Text = "(Wait, stubby little limbs?)"
  },
  AvgDialog_128700_Content_50 = {
    Text = "Vortice cheers and flings her arms wide open, ready to give her brand-new friend a huge bear hug."
  },
  AvgDialog_128700_Content_51 = {
    Text = "AH! (Oh no... Big One...)"
  },
  AvgDialog_128700_Content_52 = {
    Text = "Friend! Hug!!"
  },
  AvgDialog_128700_Content_53 = {
    Text = "Wait, Vortice—mmph! OW—!"
  },
  AvgDialog_128700_Content_54 = {
    Text = "The air currents in the cabin suddenly converge; amid the intensified wind pressure, you hear a crisp <Italic:crack>."
  },
  AvgDialog_128700_Content_55 = {Text = "Ouch!!"},
  AvgDialog_128700_Content_56 = {
    Text = "Vortice snaps out of it and hurriedly lets go. But Nautila is already grimacing in pain, her arm bent at an unnatural angle."
  },
  AvgDialog_128700_Content_57 = {
    Text = "S-sorry... I... I—"
  },
  AvgDialog_128700_Content_58 = {
    Text = "Seeing Vortice frozen in panic, you clamp your teeth onto her pant leg and tug her toward something."
  },
  AvgDialog_128700_Content_59 = {
    Text = "Squeak, squeak! (This way, Big One! Over here!)"
  },
  AvgDialog_128700_Content_6 = {
    Text = "<Shake:Plap plap~>"
  },
  AvgDialog_128700_Content_60 = {
    Text = "Oh right, this! Nautila—drink!"
  },
  AvgDialog_128700_Content_61 = {
    Text = "Don't touch me!!"
  },
  AvgDialog_128700_Content_62 = {
    Text = "Nautila instinctively slaps Vortice's hand away, leaning backward."
  },
  AvgDialog_128700_Content_63 = {
    Text = "[@Compound Tonic]"
  },
  AvgDialog_128700_Content_64 = {
    Text = "Gulp, gulp—The medicine bottle hits the floor and rolls to a stop at Vortice's feet."
  },
  AvgDialog_128700_Content_65 = {
    Text = "The girl, who had been so gleeful and carefree just moments ago, keenly catches the stranger's fear. Slowly, she lowers her hand."
  },
  AvgDialog_128700_Content_66 = {Text = "..."},
  AvgDialog_128700_Content_67 = {
    Text = "I'm sorry, but... is there somewhere else on the ship I could go? I think I need to rest alone for a bit."
  },
  AvgDialog_128700_Content_68 = {
    Text = "Vortice is quiet for a moment. Then she drags over the biggest, softest blanket on the ship and spreads it out on the floor—a little distance away."
  },
  AvgDialog_128700_Content_69 = {
    Text = "Vortice... clumsy. Too strong... hurt people."
  },
  AvgDialog_128700_Content_7 = {Text = "Plap plap~"},
  AvgDialog_128700_Content_70 = {
    Text = "Vortice, bad. Sorry. Home, warm, Nautila."
  },
  AvgDialog_128700_Content_71 = {
    Text = "You're suddenly lifted into the air. Vortice carefully, almost timidly, holds you out toward Nautila, as if offering a precious gift."
  },
  AvgDialog_128700_Content_72 = {
    Text = "Vortice, out. Coalsie, warm, Nautila, stay."
  },
  AvgDialog_128700_Content_73 = {
    Text = "She tilts her chin toward the door, then points to the blanket, stubbornly standing between Nautila and the door."
  },
  AvgDialog_128700_Content_74 = {
    Text = "...Alright. Thank you."
  },
  AvgDialog_128700_Content_75 = {
    Text = "Eeek. Squeak?? (H-hey, Big One—??)"
  },
  AvgDialog_128700_Content_76 = {Text = "..."},
  AvgDialog_128700_Content_77 = {
    Text = "The rain doesn't let up all night. Midnight, Nautila walks to the cabin doorway and looks at the girl asleep on the deck."
  },
  AvgDialog_128700_Content_78 = {
    Text = "Curled up tightly in the corner of the ship, she shelters herself from the wind and rain."
  },
  AvgDialog_128700_Content_79 = {
    Text = "...Sleeping so soundly in a place like this. You really are like a little animal..."
  },
  AvgDialog_128700_Content_8 = {
    Text = "(Oh, right! I'm a sea otter!)"
  },
  AvgDialog_128700_Content_80 = {
    Text = "Sorry, Vortice. I shouldn't have snapped at you."
  },
  AvgDialog_128700_Content_81 = {
    Text = "Vortice is covered with an extra blanket. She smacks her lips in her sleep and sinks into an even deeper, sweeter dream."
  },
  AvgDialog_128700_Content_82 = {Text = "Chirp!"},
  AvgDialog_128700_Content_83 = {
    Text = "After a night of rain, it's the perfect time to fish in the early morning. You proudly bite the biggest fish of the day and toss it at Vortice. But—"
  },
  AvgDialog_128700_Content_84 = {
    Text = "<Italic:SMACK!>"
  },
  AvgDialog_128700_Content_85 = {Text = "..."},
  AvgDialog_128700_Content_86 = {
    Text = "Vortice takes the fish square in the face, cracking her morning-long daze. She looks at you, the corners of her mouth curving down. And then—fat, heavy teardrops start rolling down."
  },
  AvgDialog_128700_Content_87 = {
    Text = "Waah... waaaaaaah—"
  },
  AvgDialog_128700_Content_88 = {
    Text = "Next thing you know, she buries her face entirely into your belly and bursts into loud sobs."
  },
  AvgDialog_128700_Content_89 = {
    Text = "Vortice, bad!"
  },
  AvgDialog_128700_Content_9 = {
    Text = "Your tiny little head cheerfully recalls the current situation."
  },
  AvgDialog_128700_Content_90 = {
    Text = "Eek!! Squeak! SQUEAK!! (Big One!! YOUR SNOT!! Watch out for your snot!!)"
  },
  AvgDialog_128700_Content_91 = {
    Text = "<Italic:Sniff>— can talk, same, friend, never...waaah waaah..."
  },
  AvgDialog_128700_Content_92 = {
    Text = "Vortice is crying so hard she can barely breathe. You struggle desperately to rescue your belly from under her face, but eventually give up with a sigh and let her smear the snot all over you."
  },
  AvgDialog_128700_Content_93 = {
    Text = "(She probably wanted to say she finally found a friend who can talk like her, but she messed it up? But does Big One actually count as being able to \"talk\"?)"
  },
  AvgDialog_128700_Content_94 = {
    Text = "(Hm, wait—what's that amazing smell?!)"
  },
  AvgDialog_128700_Content_95 = {Text = "..."},
  AvgDialog_128700_Content_96 = {
    Text = "In the cabin, Nautila has threaded several fish onto thin wires. The flames have crisped their skin, and fat drips onto the floor below in a sizzle, releasing an aroma that instantly triggers animal instincts."
  },
  AvgDialog_128700_Content_97 = {
    Text = "Uh, sorry—I noticed you both eat your fish raw, so I did a little... cooking. No seasoning though. Wanna try?"
  },
  AvgDialog_128700_Content_98 = {
    Text = "<Italic:Om nom!>"
  },
  AvgDialog_128700_Content_99 = {
    Text = "<Italic:Om nom!>"
  },
  AvgDialog_130451_Content_1 = {
    Text = "In the hollow hall, only the echoes of your and Murphy's footsteps remain."
  },
  AvgDialog_130452_Content_1 = {
    Text = "In the hollow hall, only the echoes of your and Murphy's footsteps remain."
  },
  AvgDialog_130453_Content_1 = {
    Text = "In the hollow hall, only the echoes of your and Murphy's footsteps remain."
  },
  AvgDialog_130454_Content_1 = {
    Text = "In the hollow hall, only the echoes of your and Murphy's footsteps remain."
  },
  AvgDialog_13049_Content_1 = {
    Text = "Ogier clutches his weapon tightly, alert to every rustle around him. In his eyes, every sound could be an enemy ambush."
  },
  AvgDialog_13049_Content_10 = {
    Text = "The sound of water? Must be the water clock over there."
  },
  AvgDialog_13049_Content_11 = {
    Text = "Sounds like it's coming from outside! I'll go check!"
  },
  AvgDialog_13049_Content_12 = {
    Text = "Don't rush! Let's go together!"
  },
  AvgDialog_13049_Content_13 = {
    Text = "Before you can stop him, Ogier grabs his weapon and charges to the palace entrance."
  },
  AvgDialog_13049_Content_14 = {
    Text = "This is—?!"
  },
  AvgDialog_13049_Content_15 = {
    Text = "Enemy attack!"
  },
  AvgDialog_13049_Content_2 = {
    Text = "You can't find words to comfort him. The lines from the Awakener file you once carefully read flash before you—"
  },
  AvgDialog_13049_Content_3 = {
    Text = [[
Awakener's account: Ogier Dansk, Knight of the @2 Duchy
Fell on the Night of National Defense...]]
  },
  AvgDialog_13049_Content_4 = {
    Text = "Please take refuge in the suburbs, {Male=Sir,Female=Miss}. We can handle things here..."
  },
  AvgDialog_13049_Content_5 = {
    Text = "You two knights can't even tell aconite from orchids; what if you brew poison instead of medicine?"
  },
  AvgDialog_13049_Content_6 = {
    Text = "The blunt refusal eases the tension. Ogier flushes crimson, the Guardian Knight suppresses a laugh, and even from behind the door comes a muffled chuckle."
  },
  AvgDialog_13049_Content_7 = {
    Text = "You cannot leave—not while trapped in the mystery centered on Ogier. Leaving rashly could lead to unknown consequences."
  },
  AvgDialog_13049_Content_8 = {
    Text = "Drip, drip—"
  },
  AvgDialog_13049_Content_9 = {
    Text = "Did you hear something?"
  },
  AvgDialog_13050_Content_1 = {
    Text = "Finally, the battle ends. You and Ogier stay on the steps below to clean the palace hall, while the Guardian Knight has already returned to keep vigil outside the princess's room."
  },
  AvgDialog_13050_Content_10 = {
    Text = "...<Italic: Rustle>..."
  },
  AvgDialog_13050_Content_11 = {
    Text = "However... the plague turns into monsters that ordinary people cannot see?"
  },
  AvgDialog_13050_Content_12 = {
    Text = "Sounds truly absurd. Even if the court poets were to sing of it, few would likely believe it."
  },
  AvgDialog_13050_Content_13 = {
    Text = "At first, my father and I thought it was a curse cast by wizards from the neighboring kingdom, but soon... their lands were ravaged by plague too."
  },
  AvgDialog_13050_Content_14 = {
    Text = "Even I... cough, cough..."
  },
  AvgDialog_13050_Content_15 = {
    Text = "As she speaks, a heart-wrenching cough erupts behind the door."
  },
  AvgDialog_13050_Content_16 = {
    Text = "Princess, please stop talking for now. Please return to bed."
  },
  AvgDialog_13050_Content_17 = {
    Text = "...<Italic: Rustle>..."
  },
  AvgDialog_13050_Content_18 = {
    Text = "Attendant! Come back and help! The princess—"
  },
  AvgDialog_13050_Content_19 = {Text = "Ugh!"},
  AvgDialog_13050_Content_2 = {
    Text = "It's our first time fighting invisible enemies. When all this is over, we should find a bard to turn the story into a song—how about that?"
  },
  AvgDialog_13050_Content_20 = {
    Text = "The crisp sound of bones snapping rings out. Something forces its way through tightly coupled muscle tissue, and crimson liquid splatters."
  },
  AvgDialog_13050_Content_21 = {Text = "What...?"},
  AvgDialog_13050_Content_22 = {
    Text = "Sir Fernando!!!"
  },
  AvgDialog_13050_Content_23 = {
    Text = "The Guardian Knight coughs, blood mixed with tissue fragments gushing from his throat. His eyes widened in disbelief, filled with confusion and fear."
  },
  AvgDialog_13050_Content_3 = {
    Text = "I've even got a title: <Italic:Dansk's Eyes, Fernando's Sword>!"
  },
  AvgDialog_13050_Content_4 = {
    Text = "Hearing his name, Ogier looks up, hands smeared with a lot of D-Slime. He hesitates, unsure how to clean them, looking quite flustered."
  },
  AvgDialog_13050_Content_5 = {
    Text = "To have my name in the song as well? What have I done to deserve this..."
  },
  AvgDialog_13050_Content_6 = {
    Text = "Heh heh... Can't the Attendant and I get a mention?"
  },
  AvgDialog_13050_Content_7 = {
    Text = "Of course! Your name will be in the very first line of this song!"
  },
  AvgDialog_13050_Content_8 = {
    Text = "...<Italic: Rustle>..."
  },
  AvgDialog_13050_Content_9 = {
    Text = "Princess @1 Suite... How's that? Do I have a knack for poetry?"
  },
  AvgDialog_13051_Content_1 = {
    Text = "What... what happened?"
  },
  AvgDialog_13051_Content_10 = {
    Text = "Sir Fernando... I remember he was the only son in his family."
  },
  AvgDialog_13051_Content_11 = {
    Text = "If only I were more alert..."
  },
  AvgDialog_13051_Content_12 = {
    Text = "Don't blame yourself for this. Those @1 monsters strike without warning. We did all we could."
  },
  AvgDialog_13051_Content_13 = {
    Text = "Ogier shakes his head; your pale comfort clearly failed to soothe him. Just then, a faint knock comes from behind."
  },
  AvgDialog_13051_Content_14 = {
    Text = "Attendant, take Ogier and leave."
  },
  AvgDialog_13051_Content_15 = {Text = "Why!"},
  AvgDialog_13051_Content_16 = {
    Text = "You... you don't need me anymore? I know I failed to save Sir Fernando, but..."
  },
  AvgDialog_13051_Content_17 = {
    Text = "The plague has brought disease, war, and pain... Your staying here merely prepares another feast for it."
  },
  AvgDialog_13051_Content_18 = {
    Text = "Her voice trembles, yet she speaks in a playful tone. Confronted with the looming threat of death, she shows no trace of fear."
  },
  AvgDialog_13051_Content_19 = {
    Text = "I suppose... Sir Fernando wouldn't want to reunite with you so soon, would he?"
  },
  AvgDialog_13051_Content_2 = {
    Text = "Faint, unsteady footsteps came from inside, followed by the sliding of the door latch—"
  },
  AvgDialog_13051_Content_20 = {
    Text = "But... this... is my duty..."
  },
  AvgDialog_13051_Content_21 = {
    Text = "Now... it's just me... I'll carry on Sir Fernando's will... I must..."
  },
  AvgDialog_13051_Content_22 = {
    Text = "A long, resigned sigh comes from behind the door. After a while, the princess speaks to you."
  },
  AvgDialog_13051_Content_23 = {
    Text = "Attendant, promise me... when my voice completely disappears, you must take Ogier away, even if it means you have to knock him out, okay?"
  },
  AvgDialog_13051_Content_24 = {
    Text = "...As you wish."
  },
  AvgDialog_13051_Content_25 = {
    Text = "Ogier clutches his weapon tightly, his knuckles white from the force. It is as if the spear in his arms is his family whose fate is unknown, the dying princess, or the forever-gone Fernando."
  },
  AvgDialog_13051_Content_26 = {
    Text = "He stares fixedly at the palace entrance, his mind drifting far away. Not even the loud crash of the gate being struck could bring him back to reality."
  },
  AvgDialog_13051_Content_27 = {
    Text = "Ogier? Ogier?"
  },
  AvgDialog_13051_Content_28 = {
    Text = "Someone's coming."
  },
  AvgDialog_13051_Content_29 = {
    Text = "Someone... is coming? The knights are back!?"
  },
  AvgDialog_13051_Content_3 = {
    Text = "Don't come out!"
  },
  AvgDialog_13051_Content_30 = {
    Text = "The gate is slammed open, but the banner fluttering in the wind isn't the color you hoped for."
  },
  AvgDialog_13051_Content_4 = {
    Text = "Your Highness... please stay inside..."
  },
  AvgDialog_13051_Content_5 = {
    Text = "Ogier struggles to push Sir Fernando's body away from the doorway, then pulls down a curtain to cover the spreading pool of blood before it can seep inside."
  },
  AvgDialog_13051_Content_6 = {
    Text = "The Mutant's spikes pierced through the chest armor and flesh, leaving the chest a bloody mess as if it had exploded from within. Sir Fernando has already died in agony."
  },
  AvgDialog_13051_Content_7 = {
    Text = "...Alright."
  },
  AvgDialog_13051_Content_8 = {
    Text = "Please, do what you can to lay him to rest."
  },
  AvgDialog_13051_Content_9 = {
    Text = "You and Ogier exchange a glance, silently wrap the knight's body in a carpet, then sit on the ground before the bedroom door. Grief and anxiety fill the air."
  },
  AvgDialog_13052_Content_1 = {
    Text = "What enemy? Where?!"
  },
  AvgDialog_13052_Content_10 = {
    Text = "Can you see them too, {Male=Sir,Female=Miss}?"
  },
  AvgDialog_13052_Content_11 = {
    Text = "You give him a reassuring look and press on."
  },
  AvgDialog_13052_Content_12 = {
    Text = "Ogier has never been a child prone to unreasonable fuss, and you know this best from training with him, don't you?"
  },
  AvgDialog_13052_Content_13 = {
    Text = "Even if you say so, I truly see nothing..."
  },
  AvgDialog_13052_Content_14 = {
    Text = "...Wait, Sir Fernando."
  },
  AvgDialog_13052_Content_15 = {
    Text = "A knock comes from the direction of the chamber. The princess's frail voice gathers everyone back to the door."
  },
  AvgDialog_13052_Content_16 = {
    Text = "They are right... Those are the invisible enemies that spread the plague."
  },
  AvgDialog_13052_Content_17 = {
    Text = "Since the princess says so..."
  },
  AvgDialog_13052_Content_18 = {
    Text = "Gritting his teeth, the Guardian Knight raises his weapon and stands by your side."
  },
  AvgDialog_13052_Content_19 = {
    Text = "Tell me the enemy's location, and I will do my best to assist in the battle!"
  },
  AvgDialog_13052_Content_2 = {
    Text = "The Guardian Knight also rushes down the stairs to your side, completely baffled."
  },
  AvgDialog_13052_Content_3 = {
    Text = "This is no time for jokes. Don't let your guard down."
  },
  AvgDialog_13052_Content_4 = {
    Text = "I'm not joking! Can't you—can't you see them?!"
  },
  AvgDialog_13052_Content_5 = {
    Text = "Ogier anxiously explains, but the Guardian Knight remains skeptical."
  },
  AvgDialog_13052_Content_6 = {
    Text = "You cannot blame him. After all, the enemies you and Ogier have just defeated are Mutants derived entirely from Dissolution."
  },
  AvgDialog_13052_Content_7 = {
    Text = "Those who can visually observe the Dissolution Phenomenon are extremely rare. Ogier is one of the unfortunate yet fortunate few."
  },
  AvgDialog_13052_Content_8 = {
    Text = "Please believe us."
  },
  AvgDialog_13052_Content_9 = {
    Text = "Please believe us. Believe in Ogier's integrity."
  },
  AvgDialog_13053_Content_1 = {
    Text = "Final Curtain"
  },
  AvgDialog_13053_Content_10 = {Text = "..."},
  AvgDialog_13053_Content_11 = {
    Text = "Let Ogier stay to guard the palace. He is, after all, a legitimate Guardian Knight appointed by the Grand Duke, isn't he?"
  },
  AvgDialog_13053_Content_12 = {
    Text = "The knight couldn't find any other reason to refuse. He nods in agreement, and together you return to the palace."
  },
  AvgDialog_13053_Content_13 = {
    Text = "The palace is empty; even that boisterous maid has left. Apart from the three of you, only the princess remains."
  },
  AvgDialog_13053_Content_14 = {
    Text = "You knock on the gilded bedroom door. The sound echoes through the silent halls, hollow and heavy as a tomb's sigh."
  },
  AvgDialog_13053_Content_15 = {
    Text = "Princess? Are you alright?"
  },
  AvgDialog_13053_Content_16 = {
    Text = "There is no response. You wait a moment before knocking again."
  },
  AvgDialog_13053_Content_17 = {
    Text = "Princess, we are here—myself, the Guardian Knight, and Ogier."
  },
  AvgDialog_13053_Content_18 = {
    Text = "Through the heavy wooden door comes the sound of rustling fabric. Someone is struggling to sit up in bed."
  },
  AvgDialog_13053_Content_19 = {
    Text = "...Nonsense."
  },
  AvgDialog_13053_Content_2 = {Text = "\"Dream\""},
  AvgDialog_13053_Content_20 = {
    Text = "Leave... all of you. Go with the rest. There's no need to guard a corpse."
  },
  AvgDialog_13053_Content_21 = {
    Text = "The girl's breathing is faint, her voice as thin as a mosquito's hum. It seems that simply responding to you has drained all her strength."
  },
  AvgDialog_13053_Content_22 = {
    Text = "The plague spread unchecked through the Duchy, sparing not even the nobility. The princess fell ill before the war began, and by now, she lacks even the strength to leave her bed."
  },
  AvgDialog_13053_Content_23 = {
    Text = "The court physician has declared her too frail to be moved from the palace—even the slightest jolt could take her life."
  },
  AvgDialog_13053_Content_24 = {
    Text = "Princess..."
  },
  AvgDialog_13053_Content_25 = {
    Text = "No matter what you say, I won't leave. Please allow me to protect you... to fulfill my knightly oath."
  },
  AvgDialog_13053_Content_26 = {Text = "..."},
  AvgDialog_13053_Content_27 = {
    Text = "...Then don't get too close to my room. The plague is irreversible, at least... don't let it infect you as well."
  },
  AvgDialog_13053_Content_28 = {
    Text = "Every time the water clock empties, come speak to me, alright? When I no longer respond... you should leave."
  },
  AvgDialog_13053_Content_3 = {
    Text = "Conspiracies stir in the dark, igniting the fuse laid by the plague. War erupts overnight."
  },
  AvgDialog_13053_Content_4 = {
    Text = "The incurable <Yellow:plague> has already spread throughout the Duchy. The city guards, plagued by sickness and pain, are powerless against the invading cavalry."
  },
  AvgDialog_13053_Content_5 = {
    Text = "Even the royal knights have gone beyond the moat by the Grand Duke's orders, joining the last line of defense for the capital."
  },
  AvgDialog_13053_Content_6 = {
    Text = "Ogier, why are you still here?"
  },
  AvgDialog_13053_Content_7 = {
    Text = "I... I want to stand guard with you."
  },
  AvgDialog_13053_Content_8 = {
    Text = "You're too young; the war... is not your burden yet. Go, seek your family, and flee to a safe place."
  },
  AvgDialog_13053_Content_9 = {
    Text = "Ogier's home, the Dansk Estate... should be outside the defensive line, right?"
  },
  AvgDialog_13054_Content_1 = {
    Text = "Dream, or Ideal"
  },
  AvgDialog_13054_Content_10 = {
    Text = "Attendant, run an errand for me, please?"
  },
  AvgDialog_13054_Content_100 = {
    Text = "About what we just talked about... You really won't tell the princess?"
  },
  AvgDialog_13054_Content_101 = {
    Text = "What? You don't trust me?"
  },
  AvgDialog_13054_Content_102 = {
    Text = "I do! Of course I do! I'd never doubt you!"
  },
  AvgDialog_13054_Content_103 = {
    Text = "Then I'll have to blackmail you with this little secret."
  },
  AvgDialog_13054_Content_104 = {Text = "Blackmail?"},
  AvgDialog_13054_Content_105 = {
    Text = "You drop to one knee, bringing your eyes level with the flustered little puppy, then extend your hand."
  },
  AvgDialog_13054_Content_106 = {
    Text = "I can promise you to not tell anyone. But in return for my silence, you must promise me one thing in return."
  },
  AvgDialog_13054_Content_107 = {
    Text = "This era knows no tradition of pinky promises, but Ogier still somewhat confusedly hooks his little finger around yours."
  },
  AvgDialog_13054_Content_108 = {
    Text = "As long as it's something I can do..."
  },
  AvgDialog_13054_Content_109 = {
    Text = "Very well, I will reserve the right to one wish. One day in the future, I may come to collect it. Don't forget then, \"Sir Ogier.\""
  },
  AvgDialog_13054_Content_11 = {
    Text = "If it's the latter, then waking its dreamer might be a way out?"
  },
  AvgDialog_13054_Content_12 = {
    Text = "Hey! Attendant? Snap out of it!"
  },
  AvgDialog_13054_Content_13 = {
    Text = "Your thoughts drift further along the faint clues, and just as your \"Wake the Dreamer\" plan begins to take shape, nails dig sharply into your arm. The pain jolts you back to reality."
  },
  AvgDialog_13054_Content_14 = {
    Text = "Gah—! That hurts!"
  },
  AvgDialog_13054_Content_15 = {
    Text = "So you can feel pain! We've been calling you for ages, and you just stood there like a statue. Is there something wrong with your ears?"
  },
  AvgDialog_13054_Content_16 = {
    Text = "You've been spacing out lately. Are you too tired? Would you like to return to your family estate to rest for a while? It's been a long time since you last had a vacation."
  },
  AvgDialog_13054_Content_17 = {
    Text = "No—my apologies. It's just... I've got some things on my mind..."
  },
  AvgDialog_13054_Content_18 = {
    Text = "The key to escaping the \"Dream\" must lie with Ogier. Though you are curious about what the world beyond the dream center is like, you couldn't stray too far right now."
  },
  AvgDialog_13054_Content_19 = {
    Text = "Things on your mind? What is it? Is it because you've fallen for someone and are troubled by it?"
  },
  AvgDialog_13054_Content_2 = {
    Text = [[
In the "Dream"
Princess's Palace]]
  },
  AvgDialog_13054_Content_20 = {
    Text = "Are you worried the other person doesn't like you back? Princess, why don't you do a little divination for our dear attendant? Or better yet, just give {Male=him,Female=her} a love potion—"
  },
  AvgDialog_13054_Content_21 = {
    Text = "Don't be silly. How can we use magic or potions to maintain a relationship?"
  },
  AvgDialog_13054_Content_22 = {
    Text = "The princess smiles gently, brushing aside the maid's teasing. She waves you over."
  },
  AvgDialog_13054_Content_23 = {
    Text = "Ogier is training with the knights. Please check on him for me, and make sure the boy doesn't get hurt."
  },
  AvgDialog_13054_Content_24 = {
    Text = "As you wish!"
  },
  AvgDialog_13054_Content_25 = {
    Text = "Perfect timing—the princess hands you a reason made in heaven to approach Ogier."
  },
  AvgDialog_13054_Content_26 = {
    Text = "But if you do need a potion, you can still come to me for it."
  },
  AvgDialog_13054_Content_27 = {
    Text = [[
In the "Dream"
Knights' Order Training Ground]]
  },
  AvgDialog_13054_Content_28 = {
    Text = "Guided by other attendants, you navigate the maze-like castle and gardens until you reach the training grounds."
  },
  AvgDialog_13054_Content_29 = {
    Text = "The crisp clang of blades mixed with cheers and jeers rolls across the field like thunder—someone is sparring under the scorching sun."
  },
  AvgDialog_13054_Content_3 = {
    Text = "After your third attempt to wake up but see no changes in the scene before you, you finally accept the truth: you are trapped in Ogier's memories."
  },
  AvgDialog_13054_Content_30 = {
    Text = "You do not expect, however, that one of the sparring partners is Ogier."
  },
  AvgDialog_13054_Content_32 = {Text = "Ugh...!"},
  AvgDialog_13054_Content_33 = {
    Text = "In the face of absolute disparity in strength, persistence and determination mean little. The adult knight hasn't even used his full strength, yet the shock of clashing weapons has already caused Ogier to lose grip in his hands."
  },
  AvgDialog_13054_Content_34 = {
    Text = "The spear is knocked away. Sweat-soaked and breathless, the boy collapses onto the coarse, gravelly ground."
  },
  AvgDialog_13054_Content_35 = {
    Text = "Kid, go back for now. If you keep practicing like this, you'll break your hand."
  },
  AvgDialog_13054_Content_36 = {
    Text = "Yeah, you're still too young. Come back for training in a couple of years. You can barely lift a weapon right now."
  },
  AvgDialog_13054_Content_37 = {Text = "No..."},
  AvgDialog_13054_Content_38 = {
    Text = "Ogier trembles all over as he bends down to pick up the fallen spear. With great effort, he adjusts his stance, pointing the spear tip at the sparring knight."
  },
  AvgDialog_13054_Content_39 = {
    Text = "I can still... hold on!"
  },
  AvgDialog_13054_Content_4 = {
    Text = "You stand in a corner of the princess's chamber, striking the perfect pose of a dutiful listener, meekly playing the role of an attendant."
  },
  AvgDialog_13054_Content_40 = {
    Text = "This brat is as stubborn as a mule..."
  },
  AvgDialog_13054_Content_41 = {
    Text = "The boy's face flushes red from exhaustion and lack of oxygen. Seeing his tenacious will, the Commander who intended to make Ogier give up through training finally speaks."
  },
  AvgDialog_13054_Content_42 = {
    Text = "Not bad at all. With enemies eyeing our Duchy covetously, we need more kids with guts like Young Master Dansk."
  },
  AvgDialog_13054_Content_43 = {
    Text = "Then I'll get serious?"
  },
  AvgDialog_13054_Content_44 = {
    Text = "Don't be so reckless! If you train this child to collapse,  how will you explain it to the Grand Duke and the Princess?"
  },
  AvgDialog_13054_Content_45 = {
    Text = "Start with basic physical training. Keep an eye on him; don't let the weapons bite him."
  },
  AvgDialog_13054_Content_46 = {
    Text = "The Commander's words ignite Ogier. The boy's eyes light up instantly, brimming with excitement."
  },
  AvgDialog_13054_Content_47 = {
    Text = "Do you agree to let me join the Knights' Order?!"
  },
  AvgDialog_13054_Content_48 = {
    Text = "Even without the Grand Duke's jest, with willpower like this, you're qualified to be an apprentice knight."
  },
  AvgDialog_13054_Content_49 = {
    Text = "The Commander pauses, his gaze softening as he takes in Ogier's scraped, bloodied limbs."
  },
  AvgDialog_13054_Content_5 = {
    Text = "Princess, princess! I heard the young Master Dansk has reported to the Knights' Order again—it's the third day in a row!"
  },
  AvgDialog_13054_Content_50 = {
    Text = "Go back for today. Tomorrow, I'll give you a customized training regimen—And the rest of you! Stop gawking! Everyone gets two extra rounds of weighted drills!"
  },
  AvgDialog_13054_Content_51 = {
    Text = "Mercy, Commander—"
  },
  AvgDialog_13054_Content_52 = {
    Text = "Before the Commander's words even fade, a cheeky protest bubbles up from the crowd—the young knights blowing off steam in this light-hearted atmosphere."
  },
  AvgDialog_13054_Content_53 = {
    Text = "Three rounds!"
  },
  AvgDialog_13054_Content_54 = {
    Text = "Amid the collective wails, Ogier finally relaxes and collapses to the ground with a thud."
  },
  AvgDialog_13054_Content_55 = {
    Text = "Great... finally..."
  },
  AvgDialog_13054_Content_56 = {
    Text = "Ogier, can we talk?"
  },
  AvgDialog_13054_Content_57 = {
    Text = "You are... Lord Attendant! Please pardon my disgraceful appearance, I..."
  },
  AvgDialog_13054_Content_58 = {
    Text = "Ogier snaps upright instantly. The scrape on his knee drags against the sand, twisting his expression with pain and tension."
  },
  AvgDialog_13054_Content_59 = {
    Text = "You wave him off and pull out a small vial that the princess somehow slipped into your pocket earlier."
  },
  AvgDialog_13054_Content_6 = {
    Text = "He actually took father's words seriously... He's just a kid, how can he possibly endure their training?"
  },
  AvgDialog_13054_Content_60 = {
    Text = "Huh... It doesn't hurt? Isn't it supposed to be medicine?"
  },
  AvgDialog_13054_Content_61 = {
    Text = "It's a special formulation from the princess herself. It must have been specially treated."
  },
  AvgDialog_13054_Content_62 = {
    Text = "The princess \"you\" serve is a mysterious girl: reclusive, yet gifted with uncanny knowledge of herbal remedies. In your own era, she would be a renowned pharmacist."
  },
  AvgDialog_13054_Content_63 = {
    Text = "But here, in this forgotten age centuries past, her talents are misunderstood. You've heard other attendants secretly call her a \"witch\" more than once."
  },
  AvgDialog_13054_Content_64 = {
    Text = "Princess's potion?! This is too precious, how can I use it—Ouch!"
  },
  AvgDialog_13054_Content_65 = {
    Text = "Hold still. You want to waste her kindness? Sit down, let me treat your wounds."
  },
  AvgDialog_13054_Content_66 = {
    Text = "Afraid of squandering such a rare remedy, Ogier finally sits down quietly. The other knights gradually leave the field, and you realize this is your chance."
  },
  AvgDialog_13054_Content_67 = {
    Text = "Ogier, can you feel that you're dreaming?"
  },
  AvgDialog_13054_Content_68 = {
    Text = "Well... yeah. It feels like a dream..."
  },
  AvgDialog_13054_Content_69 = {
    Text = "The boy misinterprets your words in a way that best fits the current situation. He sighs with his eyes closed, his voice filled with satisfaction and longing."
  },
  AvgDialog_13054_Content_7 = {
    Text = "No... that's not right... perhaps there are other possibilities."
  },
  AvgDialog_13054_Content_70 = {
    Text = "Being summoned, chosen, earning the knights' respect... It truly feels like a dream."
  },
  AvgDialog_13054_Content_71 = {
    Text = "<LightGray:(Should I tell him directly that this is a dream? But I haven't figured out what this place really is. A memory? Or a dream...?)>"
  },
  AvgDialog_13054_Content_72 = {
    Text = "Your hesitation catches Ogier's attention. He suddenly grows uneasy, nervously rubbing the hem of his clothes."
  },
  AvgDialog_13054_Content_73 = {
    Text = "{Male=Sir,Female=Miss}, is... is the princess dissatisfied with me?"
  },
  AvgDialog_13054_Content_74 = {Text = "..."},
  AvgDialog_13054_Content_75 = {
    Text = "Ogier, you were born into a noble house. You could have spent your life in comfort and safety... so why choose this? Why do you want to become a knight?"
  },
  AvgDialog_13054_Content_76 = {
    Text = "Because... because..."
  },
  AvgDialog_13054_Content_77 = {
    Text = "Ogier's voice grows quieter with embarrassment, his head sinking lower. Whatever the reason, it clearly shames him."
  },
  AvgDialog_13054_Content_78 = {
    Text = "I swear, no third soul will ever know about our conversation."
  },
  AvgDialog_13054_Content_79 = {
    Text = "Because... my father is also ill, just like Aunt Merinte in the kitchens and Brother Pedro in the gardens..."
  },
  AvgDialog_13054_Content_8 = {
    Text = "Based on the maid's account, Ogier is currently undergoing training at the Knights' Order. Since Ogier did not participate in this conversation, the hypothesis that this is \"Ogier's memory\" couldn't hold."
  },
  AvgDialog_13054_Content_80 = {
    Text = "And many, many others. Everyone has the same sickness."
  },
  AvgDialog_13054_Content_81 = {
    Text = "My father can't even leave his bed anymore, but I haven't grown up yet...  As his only heir, I..."
  },
  AvgDialog_13054_Content_82 = {
    Text = "If my father were to pass away, everyone in the manor would be dismissed. But they're still sick... with nowhere else to go."
  },
  AvgDialog_13054_Content_83 = {
    Text = "I must... I must take responsibility for everyone... Only by becoming a knight and gaining the Grand Duke's favor..."
  },
  AvgDialog_13054_Content_84 = {
    Text = "Speaking of this, Ogier's face turns pale. He looks at you anxiously, as if afraid you'd accuse him of \"impure motives\" or punish him on the princess's behalf."
  },
  AvgDialog_13054_Content_85 = {
    Text = "The same youthful innocence, the same resilient will. He is undoubtedly the Ogier you know."
  },
  AvgDialog_13054_Content_86 = {
    Text = "Sorry, {Male=Sir,Female=Miss}... If, if you wish to have the princess replace me... I won't complain at all..."
  },
  AvgDialog_13054_Content_87 = {
    Text = "The night you were chosen by the Grand Duke, you swore upon your family's honor before all the guests, didn't you?"
  },
  AvgDialog_13054_Content_88 = {
    Text = "You swore to fulfill the duties of a knight with your life... Were you sincere when you recited the oath along with others?"
  },
  AvgDialog_13054_Content_89 = {
    Text = "<Big:Of course! I meant every word!>"
  },
  AvgDialog_13054_Content_9 = {
    Text = "This isn't just a \"memory.\" Perhaps you've entered a real, historical event, or maybe it's a dream based on someone's subconscious?"
  },
  AvgDialog_13054_Content_90 = {
    Text = "\"I shall be forever loyal, forever devoted\"... My father would want me to do this too."
  },
  AvgDialog_13054_Content_91 = {
    Text = "Alright, alright, I won't tell the princess anything. Don't be so worried; your tears are about to fall."
  },
  AvgDialog_13054_Content_92 = {
    Text = "T-Tears?! My apologies!"
  },
  AvgDialog_13054_Content_93 = {
    Text = "Ugh... My eyes... they hurt..."
  },
  AvgDialog_13054_Content_94 = {
    Text = "Ogier fumbles for his handkerchief, but it is already caked in dust from training. This wipe only makes Olgier's mess even worse."
  },
  AvgDialog_13054_Content_95 = {
    Text = "Letting you see me like this... I'm hopeless..."
  },
  AvgDialog_13054_Content_96 = {
    Text = "It's fine. I've seen you in far worse shape. Let's get you back to the palace first to clean you up. We can't let you go home looking like this."
  },
  AvgDialog_13054_Content_97 = {Text = "..."},
  AvgDialog_13054_Content_98 = {
    Text = "{Male=Sir,Female=Miss}, may I ask a favor of you?"
  },
  AvgDialog_13054_Content_99 = {
    Text = "Go ahead, I'm listening."
  },
  AvgDialog_13055_Content_1 = {
    Text = "Threads of the Past"
  },
  AvgDialog_13055_Content_10 = {Text = "Re-link"},
  AvgDialog_13055_Content_11 = {
    Text = "Seeing Ogier teetering closer to losing control, you decide to wait no longer. You firmly grasp his hands, now covered in black sludge."
  },
  AvgDialog_13055_Content_12 = {
    Text = "The Silver Key flickers. You steer your mental tendrils through the Gnosis Tempest, crossing layers of darkness to link with Ogier once more."
  },
  AvgDialog_13055_Content_13 = {
    Text = "Accompanied by a faint, electric-like sting, images flash before your eyes and vanish in an instant."
  },
  AvgDialog_13055_Content_14 = {
    Text = "The signs of frenzy recede like an ebbing tide. Ogier's condition stabilizes, though his youthful face shows a hint of exhaustion."
  },
  AvgDialog_13055_Content_15 = {
    Text = "My lord, how long did I last this time?"
  },
  AvgDialog_13055_Content_16 = {
    Text = "The timer barely covered half its circle. Without the link, Ogier couldn't hold out any longer than in the previous training session."
  },
  AvgDialog_13055_Content_17 = {
    Text = "Hmm... 30 seconds, plus 200 milliseconds."
  },
  AvgDialog_13055_Content_18 = {
    Text = "How... how could this be...!"
  },
  AvgDialog_13055_Content_19 = {
    Text = "His tone is anxious; after all, this <Yellow:Link-Severance Training> was his own idea."
  },
  AvgDialog_13055_Content_2 = {
    Text = [[
Mythag University Training Grounds
At Dusk]]
  },
  AvgDialog_13055_Content_20 = {
    Text = "He's been brooding over the anomaly from the day of the Keybestowal Ceremony, fearing that one day he might lose control and turn his spear against you all. To that end, he wants to enhance his ability to maintain sanity without the link."
  },
  AvgDialog_13055_Content_21 = {
    Text = "My lord, let's try again!"
  },
  AvgDialog_13055_Content_22 = {
    Text = "We've trained long enough. Fatigue training will backfire."
  },
  AvgDialog_13055_Content_23 = {
    Text = "Ogier's eyes flicker with resolve—then dim. His voice tinged with self-reproach:"
  },
  AvgDialog_13055_Content_24 = {
    Text = "I didn't think this through..."
  },
  AvgDialog_13055_Content_25 = {Text = "..."},
  AvgDialog_13055_Content_26 = {
    Text = "I have no missions tomorrow either. See you after lunch, same place."
  },
  AvgDialog_13055_Content_27 = {Text = "My lord!"},
  AvgDialog_13055_Content_28 = {
    Text = "Under his puppy-like, exuberant gaze, you drag your equally exhausted body back to the dormitory."
  },
  AvgDialog_13055_Content_29 = {
    Text = "You perform a quick wash and collapse onto the soft bed. With a silent thanks to Mythag's taste in bedding, your consciousness gradually drifts away..."
  },
  AvgDialog_13055_Content_3 = {
    Text = "The Silver Key glints. You guide the invisible, delicate silver thread in your mind, withdrawing it from the shining light dot."
  },
  AvgDialog_13055_Content_30 = {Text = "..."},
  AvgDialog_13055_Content_31 = {
    Text = "A strange, melodious tune rings out in the darkness, accompanied by the clinking of silver goblets. The dream overflows with a bustling yet elegant atmosphere."
  },
  AvgDialog_13055_Content_32 = {
    Text = "So noisy... Who is it... Throwing a banquet in the dorms at midnight...?"
  },
  AvgDialog_13055_Content_33 = {
    Text = "You roll over and reach for the blanket you kicked off the bed."
  },
  AvgDialog_13055_Content_34 = {
    Text = "Your hand plunges into the mist, grasping what feels like a rain cloud—its touch both real and illusory."
  },
  AvgDialog_13055_Content_35 = {
    Text = "Oh, there you are. I was just looking for you."
  },
  AvgDialog_13055_Content_36 = {Text = "What...?"},
  AvgDialog_13055_Content_37 = {
    Text = "My legs feel weak again. Could you please go to my father and bring my knight here?"
  },
  AvgDialog_13055_Content_38 = {Text = "Knight...?"},
  AvgDialog_13055_Content_39 = {
    Text = "What are you waiting for? Didn't you hear the princess?"
  },
  AvgDialog_13055_Content_4 = {Text = "Ugh...!"},
  AvgDialog_13055_Content_40 = {
    Text = "A woman slaps your shoulder hard. The darkness fades, and an unfamiliar scene comes into your view."
  },
  AvgDialog_13055_Content_41 = {
    Text = "A grand hall, an orchestra playing ancient suites in the distance, exquisite and tempting desserts, and noble ladies all gazing at you."
  },
  AvgDialog_13055_Content_42 = {
    Text = "And there, surrounded by them, is a young girl reclining on a plush chaise."
  },
  AvgDialog_13055_Content_43 = {
    Text = "It's no matter, don't be too harsh on {Male=him,Female=her}. My attendant has been busy all night without rest to present a perfect banquet for everyone."
  },
  AvgDialog_13055_Content_44 = {
    Text = "The girl, addressed by others as the princess, gently comes to your defense."
  },
  AvgDialog_13055_Content_45 = {
    Text = "Could you bring the \"knight\" my father appointed for me? Then you can rest for the day, alright?"
  },
  AvgDialog_13055_Content_46 = {
    Text = "Fragments of memory flood your mind. They are disjointed and incomplete, but sufficient for you to play the role of this shell—the princess's chief attendant."
  },
  AvgDialog_13055_Content_47 = {
    Text = "...Thank you for your grace, Your Highness."
  },
  AvgDialog_13055_Content_48 = {
    Text = "Your body bows instinctively. Amidst envious or disdainful gazes, you weave through the cluster of noblewomen toward the more crowded part of the hall."
  },
  AvgDialog_13055_Content_49 = {
    Text = "You look down at \"your\" hands. The skin tone is a few shades darker than your own, which is usually hidden under gloves. Fine, faint scar marks them everywhere—clearly not the hands of someone raised in luxury."
  },
  AvgDialog_13055_Content_5 = {
    Text = "Don't push yourself too hard. If you can't hold on, link with the Black Pool!"
  },
  AvgDialog_13055_Content_50 = {
    Text = "An ornate gilded vase on the way further confirms your suspicion—"
  },
  AvgDialog_13055_Content_51 = {
    Text = "the reflection it casts is not your face."
  },
  AvgDialog_13055_Content_52 = {
    Text = "Sir! You've come on behalf of the princess?"
  },
  AvgDialog_13055_Content_53 = {
    Text = "A maid darts out from the crowd, her eyes clearly sharper than yours; she spots the familiar \"you\" instantly amidst the bustling throng."
  },
  AvgDialog_13055_Content_54 = {
    Text = "<Small:The Grand Duke has knighted a little boy! Do they really want such a small child to join the knight's training? I doubt he can even lift a weapon.>"
  },
  AvgDialog_13055_Content_55 = {
    Text = "<BigItalic:Excuse me, please make way. We are here by the order of Princess @1 for an audience—>"
  },
  AvgDialog_13055_Content_56 = {
    Text = "<Small:You didn't see it earlier; his face was beet red when the Grand Duke presented him to everyone.>"
  },
  AvgDialog_13055_Content_57 = {
    Text = "<BigItalic:Pardon us! The princess's chief attendant requests an audience!!>"
  },
  AvgDialog_13055_Content_58 = {
    Text = "<Small:How long will it take for a kid like this to become a real knight... The Grand Duke must be joking, right?>"
  },
  AvgDialog_13055_Content_59 = {
    Text = "The maid skillfully parts the crowd with her words while whispering playful remarks to you, leading you right up to the throne."
  },
  AvgDialog_13055_Content_6 = {
    Text = "I can... still... hold on..."
  },
  AvgDialog_13055_Content_60 = {
    Text = "G-Greetings. Are you the chief attendant, {Male=Sir,Female=Miss}?"
  },
  AvgDialog_13055_Content_61 = {
    Text = "You are...!"
  },
  AvgDialog_13055_Content_62 = {
    Text = "I am the eldest son of the House of Dansk. I am deeply grateful for the Grand Duke's favor, and it's my g-great honor to serve as Princess @1's knight."
  },
  AvgDialog_13055_Content_7 = {
    Text = "Ogier sinks to one knee. With the link severed, he braces himself with his spear to keep from collapsing entirely."
  },
  AvgDialog_13055_Content_8 = {
    Text = "My... lord..."
  },
  AvgDialog_13055_Content_9 = {
    Text = "Thick, black liquid seeps from the corners of his eyes, his lips, and his ears. His organs are already shattered by amorphous black slime—it's easy to imagine the agony the boy is enduring."
  },
  AvgDialog_13056_Content_1 = {
    Text = "A New Ballad"
  },
  AvgDialog_13056_Content_10 = {
    Text = "Don't come any closer! I won't show mercy!"
  },
  AvgDialog_13056_Content_100 = {
    Text = "Come on, it's a rest day. The East District Market will be bustling. We can also stop by the workhouse to see the kids..."
  },
  AvgDialog_13056_Content_101 = {
    Text = "You mutter your itinerary like it's nothing, striding off without a backward glance. You feel no worry at all."
  },
  AvgDialog_13056_Content_102 = {
    Text = "My lord! My lord! Please tell me how you knew—"
  },
  AvgDialog_13056_Content_103 = {
    Text = "Because you know he'll follow."
  },
  AvgDialog_13056_Content_11 = {
    Text = "Ogier raises his spear, blocking the staircase."
  },
  AvgDialog_13056_Content_12 = {
    Text = "This is your final warning. Please leave the palace!"
  },
  AvgDialog_13056_Content_13 = {
    Text = "Hey, did you hear that? What did he just say? \"Please\" leave the palace?"
  },
  AvgDialog_13056_Content_14 = {
    Text = "Hahahaha, that's hilarious! No wonder the Duchy is so weak—they're playing knightly house with a child."
  },
  AvgDialog_13056_Content_15 = {
    Text = "Keep it down; your racket's hurting my ears."
  },
  AvgDialog_13056_Content_16 = {
    Text = "The sergeant ignores Ogier's warning, walking up to the chamber door, looking down at Ogier."
  },
  AvgDialog_13056_Content_17 = {
    Text = "Move aside."
  },
  AvgDialog_13056_Content_18 = {
    Text = "Ogier strains to hold the spear horizontally, trying to block the sergeant's advance."
  },
  AvgDialog_13056_Content_19 = {
    Text = "Please leave!"
  },
  AvgDialog_13056_Content_2 = {
    Text = "The armored boots, carrying sparks and dust, step onto the palace carpet."
  },
  AvgDialog_13056_Content_20 = {
    Text = "You know, a knight's weapon doesn't suit you."
  },
  AvgDialog_13056_Content_22 = {
    Text = "Resistance is a pale thing in the face of absolute power. The sergeant effortlessly parries Ogier's spear, and with a casual flick of his wrist, drives a dagger deep into the boy's chest."
  },
  AvgDialog_13056_Content_23 = {Text = "Cough—!"},
  AvgDialog_13056_Content_24 = {
    Text = "See? This is the kind of skill you should learn. After your nation falls, you'll only fit in the sunless back alleys."
  },
  AvgDialog_13056_Content_25 = {
    Text = "Theft, hunger, and mutual hatred... this is your fate. And this spear, the symbol of chivalric honor? Useless to you then."
  },
  AvgDialog_13056_Content_26 = {
    Text = "Blood surges into his windpipe, causing a dull, suffocating agony, like drowning on land. Each breath chokes on the scent of blood."
  },
  AvgDialog_13056_Content_27 = {
    Text = "You want to rush out from under the low table, to shove the sergeant down the stairs, to protect Ogier kneeling by the door. But your body betrays you. Trembling, rigid, it refuses to obey."
  },
  AvgDialog_13056_Content_28 = {
    Text = "No... cough..."
  },
  AvgDialog_13056_Content_29 = {
    Text = "Ah, I was wrong about one thing—you won't even live to see that future. You'll end up like this one, fuel to burn this palace down."
  },
  AvgDialog_13056_Content_3 = {
    Text = "This is your favorite carpet in this \"Dream.\" You and the chatty maid spent an entire afternoon selecting it from the Grand Duke's warehouse, and another half-day laying it flat."
  },
  AvgDialog_13056_Content_30 = {
    Text = "The armored boot stomps heavily on Fernando's corpse, accompanied by the clanging of metal and the crisp snap of breaking bones."
  },
  AvgDialog_13056_Content_31 = {
    Text = "...Fernan..."
  },
  AvgDialog_13056_Content_33 = {
    Text = "Ogier's body thrums with adrenaline, and he snatches up his spear and charges toward the enemy!"
  },
  AvgDialog_13056_Content_34 = {
    Text = "<Big:DON'T TOUCH HIM!>"
  },
  AvgDialog_13056_Content_36 = {Text = "Ugh—!"},
  AvgDialog_13056_Content_37 = {
    Text = "Resistance is futile. His attack not only fails to budge the sergeant but also exposes his back to the scout."
  },
  AvgDialog_13056_Content_38 = {
    Text = "Stubborn kid. If he'd run from the start, we wouldn't have bothered chasing him, right?"
  },
  AvgDialog_13056_Content_39 = {
    Text = "Look at you, little one, so determined... are you protecting someone? Is the princess behind this door?"
  },
  AvgDialog_13056_Content_4 = {
    Text = "The princess leaves her room—a rare occurence. She leans against the railing of the second-floor corridor, leisurely watching you bustle about in the hall below. Ogier, who has come for an audience, is so nervous he doesn't know where to place his feet."
  },
  AvgDialog_13056_Content_40 = {
    Text = "Blood pours from his ears. Ogier can't make out every word, but he still catches the most crucial one."
  },
  AvgDialog_13056_Content_41 = {
    Text = "No... go away..."
  },
  AvgDialog_13056_Content_42 = {
    Text = "His vision begins to whiten from the edges. Some force is pulling his consciousness out of his youthful body."
  },
  AvgDialog_13056_Content_43 = {
    Text = "He crawls forward, over Fernando's corpse, over the boots of the sergeant and the scout, until his fingers finally touch the heavy wooden door."
  },
  AvgDialog_13056_Content_44 = {
    Text = "The wood feels warm, carrying a slightly pungent fragrance. Behind this door, a gentle voice used to call to him. Now, the only sound left is the steady tick-tock of the water clock."
  },
  AvgDialog_13056_Content_45 = {
    Text = "Leave... here..."
  },
  AvgDialog_13056_Content_46 = {
    Text = "<Big:AAAHHHHH—!>"
  },
  AvgDialog_13056_Content_47 = {
    Text = "This time, it's his own spear that pierces deep into the flesh."
  },
  AvgDialog_13056_Content_48 = {
    Text = "The weapon mocked by many and despised by enemies—the one he never let go of from beginning to end."
  },
  AvgDialog_13056_Content_49 = {
    Text = "The spear tip pierces through his body, pinning him to the door. He cannot move."
  },
  AvgDialog_13056_Content_5 = {
    Text = "These are not Duchy knights... Hide! Quick!"
  },
  AvgDialog_13056_Content_50 = {
    Text = "Aww—don't be so cruel. What if the \"Witch Princess\" puts a curse on us for torturing her knight?"
  },
  AvgDialog_13056_Content_51 = {
    Text = "A witch? Her? Ridiculous."
  },
  AvgDialog_13056_Content_52 = {
    Text = "<Small:Princess @1... is not...>"
  },
  AvgDialog_13056_Content_53 = {
    Text = "Ogier's mouth hangs open. The princess's name is on the tip of his tongue, yet he simply could not remember it."
  },
  AvgDialog_13056_Content_54 = {
    Text = "<Small:@1...>"
  },
  AvgDialog_13056_Content_55 = {
    Text = "He hears the sound of flowing water. Did the water clock fall? Does that mean... the Princess is still alive?"
  },
  AvgDialog_13056_Content_56 = {
    Text = "<Small:No... don't come out... no... leave...>"
  },
  AvgDialog_13056_Content_57 = {
    Text = "Enough... Ogier... Thank you..."
  },
  AvgDialog_13056_Content_58 = {
    Text = "Thank you... my..."
  },
  AvgDialog_13056_Content_59 = {
    Text = "First, a few black streams seep under the door seam, mingling with Ogier's blood, like tears shed for someone."
  },
  AvgDialog_13056_Content_6 = {
    Text = "Wait! What about you?!"
  },
  AvgDialog_13056_Content_60 = {
    Text = "Then, a torrential flood burst through the doorframe, cracking it open. Roaring and surging, it instantly engulfs the palace."
  },
  AvgDialog_13056_Content_61 = {
    Text = "<Shake:GAH—Ugh!>"
  },
  AvgDialog_13056_Content_62 = {
    Text = "The plague, invisible to ordinary people, washes over the two intruders. Black ooze gushes into their eyes, nose, and mouth, drowning them in midair."
  },
  AvgDialog_13056_Content_63 = {
    Text = "<Shake:Curse... It's a curse—>"
  },
  AvgDialog_13056_Content_65 = {
    Text = "Keeper? Wake up! Keeper? %player%?"
  },
  AvgDialog_13056_Content_66 = {Text = "Ogier!"},
  AvgDialog_13056_Content_67 = {
    Text = "Had a nightmare? It's me."
  },
  AvgDialog_13056_Content_68 = {
    Text = "...Doll? Why are you in my room?"
  },
  AvgDialog_13056_Content_69 = {
    Text = "I don't care about the content of your nightmare, but last night, your spirit waves were active like they were dancing."
  },
  AvgDialog_13056_Content_7 = {
    Text = "Ogier shoves you hard, pushing you under the low table. Your vision spins, and all you can see is the luxurious Persian rug curling at the edges due to the flames."
  },
  AvgDialog_13056_Content_70 = {
    Text = "Awakeners linked to you, including me, have more or less sensed abnormalities."
  },
  AvgDialog_13056_Content_71 = {
    Text = "Last night? ...It was only one night? Was it really just a dream..."
  },
  AvgDialog_13056_Content_72 = {
    Text = "You describe everything in the absurd dream to Doll. The princess, the knights, the plague..."
  },
  AvgDialog_13056_Content_73 = {
    Text = "Among Investigators linked to Awakeners, there are occasional cases of shared memories or emotions. But what you described... I've never heard of it."
  },
  AvgDialog_13056_Content_74 = {
    Text = "It seems that this \"dream\" hasn't caused you any further effects. I'll keep monitoring your spirit waves closely."
  },
  AvgDialog_13056_Content_75 = {
    Text = "...Perhaps you'd like to meet Ogier now?"
  },
  AvgDialog_13056_Content_76 = {
    Text = "The feeling of being devoured by D-Slime was all too real. The morning sun shines on the blanket, but the warmth that should feel comforting now makes your body feel as if plunged into icy water."
  },
  AvgDialog_13056_Content_77 = {
    Text = "Ogier... right. We had planned to continue training today..."
  },
  AvgDialog_13056_Content_78 = {
    Text = [[
Mythag University  Training Ground
Morning]]
  },
  AvgDialog_13056_Content_79 = {
    Text = "Wahhh—No, no, no, I'm going to die—"
  },
  AvgDialog_13056_Content_8 = {
    Text = "Just this little kid? Have we come to the right place?"
  },
  AvgDialog_13056_Content_80 = {
    Text = "Spare me, please spare this poor little reporter, Sir Ogier—"
  },
  AvgDialog_13056_Content_81 = {
    Text = "Just a bit longer, Miss Hanna—one more lap and we're done. You'll definitely pass this physical test!"
  },
  AvgDialog_13056_Content_82 = {
    Text = "Sob... okay..."
  },
  AvgDialog_13056_Content_83 = {
    Text = "The campus broker's calves are bound with weighted sandbags as she tearfully jogs slowly around the track. Ogier jogs alongside her, encouraging her, effortlessly keeping pace without breaking a sweat."
  },
  AvgDialog_13056_Content_84 = {Text = "Ogier"},
  AvgDialog_13056_Content_85 = {Text = "Keeper!"},
  AvgDialog_13056_Content_86 = {
    Text = "He hands over the supervision of Hannah to another staff and runs towards you."
  },
  AvgDialog_13056_Content_87 = {
    Text = "Didn't you say our training starts in the afternoon? Why are you here so early?"
  },
  AvgDialog_13056_Content_88 = {
    Text = "He has been training with other students and Awakeners all morning, yet he stands before you bright-eyed, brimming with reverence and vigor."
  },
  AvgDialog_13056_Content_89 = {Text = "I..."},
  AvgDialog_13056_Content_9 = {
    Text = "That's right. The strategic map clearly marks this as the royal women's palace."
  },
  AvgDialog_13056_Content_90 = {
    Text = "... After Hannah's training, let's go for a walk in downtown Londinium."
  },
  AvgDialog_13056_Content_91 = {Text = "Huh?"},
  AvgDialog_13056_Content_92 = {
    Text = "Ogier clearly didn't expect you to suddenly suggest a break. Even you yourself didn't expect it."
  },
  AvgDialog_13056_Content_93 = {
    Text = "My lord, please allow me to refuse. The Dissolution crisis is imminent. But I... I'm not ready yet."
  },
  AvgDialog_13056_Content_94 = {
    Text = "I need to focus entirely on honing my skills. I have no time for such leisurely activities."
  },
  AvgDialog_13056_Content_95 = {
    Text = "Then let me rephrase it."
  },
  AvgDialog_13056_Content_96 = {
    Text = "That afternoon spent with him in the Knights' Order suddenly jumps into your mind. Memories you thought would fade with the dream resurface."
  },
  AvgDialog_13056_Content_97 = {
    Text = "It's time to fulfill that wish, Sir Ogier."
  },
  AvgDialog_13056_Content_98 = {Text = "!?"},
  AvgDialog_13056_Content_99 = {
    Text = "How... How did you know that?!"
  },
  AvgDialog_130571_Content_1 = {Text = "BANG—!"},
  AvgDialog_130571_Content_10 = {
    Text = "Ow... owie... Coalsie, sorry... Vortice... squishing you."
  },
  AvgDialog_130571_Content_11 = {
    Text = "It is alright. But Vortice, why the sudden rush?"
  },
  AvgDialog_130571_Content_12 = {
    Text = "Ah! Vortice... hot! Hug Coalsie... feel better!"
  },
  AvgDialog_130571_Content_13 = {
    Text = "Vortice strange... not cold anymore."
  },
  AvgDialog_130571_Content_14 = {
    Text = "But so hot... so hot..."
  },
  AvgDialog_130571_Content_15 = {
    Text = "(This is bad. Could it be the influence of the Holy River?)"
  },
  AvgDialog_130571_Content_16 = {
    Text = "Vortice... don't know..."
  },
  AvgDialog_130571_Content_17 = {
    Text = "Her gaze grows hazy and unfocused. Her slender fingers slip through the gaps in your clothes, gently tracing the surface of your skin."
  },
  AvgDialog_130571_Content_18 = {
    Text = "You are all too familiar with this sensation. In those dreams of yours, 'Coalsie' would often enjoy this sort of 'petting' while curled in her arms."
  },
  AvgDialog_130571_Content_19 = {
    Text = "Coalsie... hug... feel calm..."
  },
  AvgDialog_130571_Content_2 = {
    Text = "Coalsie! Hug!"
  },
  AvgDialog_130571_Content_20 = {
    Text = "Coalsie... smell nice..."
  },
  AvgDialog_130571_Content_21 = {
    Text = "She leans in, sniffing you softly. You aren't sure if it is a lingering fragrance or your own unique nature that finally settles her spirit."
  },
  AvgDialog_130571_Content_22 = {
    Text = "But one thing is certain: you cannot let this continue on the floor."
  },
  AvgDialog_130571_Content_23 = {
    Text = "The wood is hard against your back, and your waist is already aching for the comfort of a mattress."
  },
  AvgDialog_130571_Content_24 = {
    Text = "How about you hold me like this in bed tonight? Let's sleep together."
  },
  AvgDialog_130571_Content_25 = {
    Text = "Yes! Coalsie, love! Want hug!"
  },
  AvgDialog_130571_Content_26 = {
    Text = "Hug Coalsie... sleep, sleep time..."
  },
  AvgDialog_130571_Content_27 = {
    Text = "You take the opportunity to lead her to the bed. The two of you sink into the soft blankets, locked in an embrace and staring into each other's eyes, just as you once did upon that ship."
  },
  AvgDialog_130571_Content_28 = {
    Text = "Vortice... not hot now... Vortice... so happy..."
  },
  AvgDialog_130571_Content_29 = {
    Text = "Night-night... zzz... Coalsie... zzz..."
  },
  AvgDialog_130571_Content_3 = {Text = "V-Vortice?"},
  AvgDialog_130571_Content_4 = {
    Text = "Vortice suddenly bursts into the room. She throws her arms around your waist, burying her face in your chest as her long silver hair tickles your skin."
  },
  AvgDialog_130571_Content_5 = {
    Text = "You breathe a silent sigh of relief. It seems she had the foresight to retract the 'horrific object' on her right hand, sparing you the risk of an accidental bite."
  },
  AvgDialog_130571_Content_6 = {
    Text = "Coalsie... feel good..."
  },
  AvgDialog_130571_Content_7 = {
    Text = "Vortice, wait—wait a second—ah!"
  },
  AvgDialog_130571_Content_8 = {Text = "THUD."},
  AvgDialog_130571_Content_9 = {
    Text = "Just as you feared, Vortice fails to temper her strength. The momentum sends you both tumbling onto the floor."
  },
  AvgDialog_131200_Content_1 = {
    Text = "Tender Chains"
  },
  AvgDialog_131200_Content_10 = {
    Text = "Arachne caresses the remaining half of her cheek. As she gently closes the dead eyes, the massive pillar behind her emits a faint glow."
  },
  AvgDialog_131200_Content_11 = {
    Text = "Arachne reaches out. The final embers within the pillar swirl like fine sand, dancing around her slender fingers before scattering to the floor."
  },
  AvgDialog_131200_Content_12 = {
    Text = "Residual embers... we were right. This is where Nefraea hid the embers, but she has already reclaimed them."
  },
  AvgDialog_131200_Content_13 = {
    Text = "She takes the embers, she kills the puppets... what is her endgame?"
  },
  AvgDialog_131200_Content_14 = {Text = "Hm?"},
  AvgDialog_131200_Content_15 = {
    Text = "Something startles her. Arachne looks up, staring through the stained-glass Lantern emblem toward the distant station."
  },
  AvgDialog_131200_Content_16 = {
    Text = "Arachne? What's wrong?"
  },
  AvgDialog_131200_Content_17 = {
    Text = "My main body... I can no longer sense her presence."
  },
  AvgDialog_131200_Content_18 = {Text = "!!!"},
  AvgDialog_131200_Content_19 = {
    Text = "You mean she left the theater?"
  },
  AvgDialog_131200_Content_2 = {
    Text = "Fingers, shins, eyes, ribs, skull... Before you is a cherished doll torn apart by her mistress, her pieces left to drown in the muck and blood."
  },
  AvgDialog_131200_Content_20 = {
    Text = "While we hunted the puppets, my main body was purging the Abyssal Squires across the city. After finding \"Memories,\" she came to this church to meet us."
  },
  AvgDialog_131200_Content_21 = {
    Text = "She was so close... but now, her light has vanished."
  },
  AvgDialog_131200_Content_22 = {
    Text = "Did something happen to her? But \"Memories\" only just died... how..."
  },
  AvgDialog_131200_Content_23 = {
    Text = "I don't know the details. But before she vanished, she touched the web to send a final message. Aside from the order to return, she left a single word."
  },
  AvgDialog_131200_Content_24 = {Text = "\"Rapture.\""},
  AvgDialog_131200_Content_25 = {
    Text = "Rapture...?"
  },
  AvgDialog_131200_Content_26 = {
    Text = "N's detestable, smiling face flashes before you."
  },
  AvgDialog_131200_Content_27 = {
    Text = "I don't understand. You share the same memories—you must know what she meant."
  },
  AvgDialog_131200_Content_28 = {
    Text = "Arachne shakes her head."
  },
  AvgDialog_131200_Content_29 = {
    Text = "Your fate is a butterfly I dare not touch; any explanation would cause immeasurable ripples."
  },
  AvgDialog_131200_Content_3 = {
    Text = "\"Memories\"..."
  },
  AvgDialog_131200_Content_30 = {
    Text = "But know this: In your immediate future, \"Rapture\" is a key. It will unlock the secret lock before you."
  },
  AvgDialog_131200_Content_31 = {
    Text = "My... future? You mean you can actually see my Thread of Fate now?!"
  },
  AvgDialog_131200_Content_32 = {
    Text = "You meet her stare. Within that gentle smile, you see the undeniable authority of Fate."
  },
  AvgDialog_131200_Content_33 = {
    Text = "...No matter what happens, trust me. And trust yourself."
  },
  AvgDialog_131200_Content_34 = {
    Text = "Return to the Theater of Fate. The key and the lock await you there, %player%."
  },
  AvgDialog_131200_Content_35 = {Text = "But..."},
  AvgDialog_131200_Content_36 = {
    Text = "Arachne's voice is as warm as an autumn sunset. Her form dissolves into a wisp of spider silk, vanishing into the dim light of the cathedral."
  },
  AvgDialog_131200_Content_37 = {
    Text = "Under the kaleidoscopic glow of the stained glass, only dimensional embers drift over the gore and severed limbs."
  },
  AvgDialog_131200_Content_38 = {
    Text = "\"Rapture\"..."
  },
  AvgDialog_131200_Content_39 = {
    Text = "You murmur the word, then turn back to the remains of \"Memories.\""
  },
  AvgDialog_131200_Content_4 = {
    Text = "You gently gather the girl's remains. The sticky fluids and blood stain your clothes as you hold her severed limbs."
  },
  AvgDialog_131200_Content_40 = {
    Text = "Bathed in murky fluid and sacred light, the fragments seem to merge with the holy cathedral itself."
  },
  AvgDialog_131200_Content_41 = {Text = "..."},
  AvgDialog_131200_Content_42 = {
    Text = "The silken path trembles. As you step onto the stage, every puppet freezes mid-performance."
  },
  AvgDialog_131200_Content_43 = {
    Text = "Countless eyes from every dimension turn toward you—filled with curiosity, elation, and a terrifying reverence."
  },
  AvgDialog_131200_Content_44 = {
    Text = "It is a grand, silent welcoming ceremony. The performers have become the audience, and the sole spectator has become the star."
  },
  AvgDialog_131200_Content_45 = {
    Text = "Maybe listening to Arachne was a mistake..."
  },
  AvgDialog_131200_Content_46 = {
    Text = "You tighten your grip on the Silver Key, walking alone through the eerie silence."
  },
  AvgDialog_131200_Content_47 = {
    Text = "The theater's new master has been expecting you, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131200_Content_48 = {
    Text = "Shadows converge on the high stage. Instinctively, you lunge backward and raise the Silver Key."
  },
  AvgDialog_131200_Content_49 = {
    Text = "New master?!"
  },
  AvgDialog_131200_Content_5 = {
    Text = "Maybe... maybe there's a way to save her. The power of the Aeons... a correction of Fate..."
  },
  AvgDialog_131200_Content_50 = {
    Text = "Welcome back to the theater, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131200_Content_51 = {
    Text = "Arachne, you..."
  },
  AvgDialog_131200_Content_52 = {
    Text = "I am sorry, but our new story requires your participation."
  },
  AvgDialog_131200_Content_53 = {
    Text = "The web quivers. The master of the theater approaches with unhurried steps, her voice still as warm as the evening dusk."
  },
  AvgDialog_131200_Content_54 = {
    Text = "All around you, the puppets—indistinguishable from Leng Spider Maids—turn and leap toward you in unison."
  },
  AvgDialog_131200_Content_55 = {Text = "!!"},
  AvgDialog_131200_Content_6 = {
    Text = "Nefraea severed her threads. Her story has reached its end, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131200_Content_7 = {
    Text = "The whir of Arachne's spinning wheel remains calm and distant."
  },
  AvgDialog_131200_Content_8 = {
    Text = "\"Memories\" is dead too... does this mean...?"
  },
  AvgDialog_131200_Content_9 = {
    Text = "Nefraea now possesses the power to rewrite this entire stage."
  },
  AvgDialog_131201_Content_1 = {
    Text = "Phew... Nefraea's squires are a real handful..."
  },
  AvgDialog_131201_Content_10 = {
    Text = "Memories of this world—both new and strangely familiar—surge through your mind. You have never seen a place so vibrant and thriving."
  },
  AvgDialog_131201_Content_11 = {
    Text = "You have seen too much. Images of the desolate, ash-choked landscapes caused by Dissolution easily overwrite this prosperity, crowding your mind with visions of decay."
  },
  AvgDialog_131201_Content_12 = {
    Text = "Arachne reaches out, her fingers gently brushing the morning light spilling into the alley. She is mourning for yet another world on the brink of death."
  },
  AvgDialog_131201_Content_13 = {
    Text = "A world unnoticed by the gods... I never even imagined such a thing was possible."
  },
  AvgDialog_131201_Content_14 = {
    Text = "Do we still have a chance to change it?"
  },
  AvgDialog_131201_Content_15 = {
    Text = "That is precisely why we are here."
  },
  AvgDialog_131201_Content_16 = {
    Text = "Tell me. What do I need to do?"
  },
  AvgDialog_131201_Content_17 = {Text = "Wait!"},
  AvgDialog_131201_Content_18 = {
    Text = "You've noticed them, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131201_Content_19 = {
    Text = "Outside the alley, a group of individuals with unnervingly abnormal spiritual frequencies is closing in on your position."
  },
  AvgDialog_131201_Content_2 = {
    Text = "You lean against the damp wall of a secluded alley, gasping for air. You never once saw Arachne run; she simply stands beside you, as calm as if it were her absolute destiny to be in this exact spot at this exact moment."
  },
  AvgDialog_131201_Content_20 = {
    Text = "Behind you, above you, in front of you... more and more enemies manifest within your awareness."
  },
  AvgDialog_131201_Content_21 = {
    Text = "We're surrounded!"
  },
  AvgDialog_131201_Content_22 = {
    Text = "Since we stepped onto this stage, I have been working to mend the tampered fate. But correcting the destinies of so many people is no simple task."
  },
  AvgDialog_131201_Content_23 = {
    Text = "Nefraea left these obstacles behind specifically to hinder my restoration."
  },
  AvgDialog_131201_Content_24 = {
    Text = "Maybe there's another way."
  },
  AvgDialog_131201_Content_25 = {
    Text = "Arachne, I'm one of the operatives assigned to the assassination the Iron Hand planned for today."
  },
  AvgDialog_131201_Content_26 = {
    Text = "This world will burn because that prince studies that grimoire. If I succeed in the assassination, maybe I can stop it all before it starts!"
  },
  AvgDialog_131201_Content_27 = {
    Text = "That isn't exactly the right..."
  },
  AvgDialog_131201_Content_28 = {
    Text = "There they are! Get them!"
  },
  AvgDialog_131201_Content_29 = {
    Text = "Arachne plucks an invisible string. A squire frozen mid-mutation at the alley's entrance stops dead, turning into a motionless statue."
  },
  AvgDialog_131201_Content_3 = {
    Text = "She went to such lengths... what is she actually trying to achieve?"
  },
  AvgDialog_131201_Content_30 = {
    Text = "The distant blare of trumpets and saxophones drifts through the air, accompanied by the low, steady rumble of approaching engines."
  },
  AvgDialog_131201_Content_31 = {
    Text = "The plot has been exposed; the other assassins won't be able to pull it off. The prince is right there. If I don't act now, we'll lose our chance!"
  },
  AvgDialog_131201_Content_32 = {
    Text = "Arachne looks into your frantic eyes and gives a slow, deliberate nod."
  },
  AvgDialog_131201_Content_33 = {
    Text = "Since the currents of Fate have brought us here... perhaps making a choice for this world is exactly what you are meant to do."
  },
  AvgDialog_131201_Content_34 = {
    Text = "Go. Do what you must, {Male=Mr.,Female=Miss} Keeper. The truth of Fate will be revealed to you here."
  },
  AvgDialog_131201_Content_35 = {
    Text = "You have no time to parse her words. You nod, and with Arachne's assistance, you bolt from the alley and vanish into the surging crowd."
  },
  AvgDialog_131201_Content_36 = {
    Text = "That's Archduke Flavian? The heir to the empire... I wonder how much a car like that even costs."
  },
  AvgDialog_131201_Content_37 = {
    Text = "Bah! Bastard son of a thief! Every cent he spends was wrung out of our blood and sweat!"
  },
  AvgDialog_131201_Content_38 = {
    Text = "If I weren't a cripple, I'd have died on the battlefield charging those bandits!"
  },
  AvgDialog_131201_Content_39 = {
    Text = "Shh! The streets are crawling with Imperial Guards! Do you have a death wish?!"
  },
  AvgDialog_131201_Content_4 = {
    Text = "Nefraea left a catalyst behind. Within the vast Web of Fate governing this world, she has polluted a single thread."
  },
  AvgDialog_131201_Content_40 = {Text = "..."},
  AvgDialog_131201_Content_41 = {
    Text = "You elbow your way through the dense throng until you finally reach the curb, just as a gleaming new convertible rolls slowly past."
  },
  AvgDialog_131201_Content_42 = {
    Text = "The crown prince, a man nearing sixty, sits in the back with his wife. They wave graciously to the crowd while pointing out the historic architecture of Hvatz."
  },
  AvgDialog_131201_Content_43 = {
    Text = "Even with your memories blurred, you know all too well the profound suffering this royal house has inflicted upon the land."
  },
  AvgDialog_131201_Content_44 = {
    Text = "Fearing the cosmic consequences of using your true power, you pull your hand away from the Silver Key. Instead, you draw the pistol that is supposed to be there and approach the slow-moving vehicle."
  },
  AvgDialog_131201_Content_45 = {
    Text = "Hey! You, student! Get back!"
  },
  AvgDialog_131201_Content_46 = {
    Text = "Forgive me, Your Highness. But since I've taken the stage, I have to play this role to the end!"
  },
  AvgDialog_131201_Content_47 = {
    Text = "BANG BANG BANG!!"
  },
  AvgDialog_131201_Content_48 = {
    Text = "Amidst the chaotic streets, the prideful imperial heir is surprisingly vulnerable. Drawing on your rigorous training, you close the distance with ease and pull the trigger."
  },
  AvgDialog_131201_Content_49 = {
    Text = "As three bullets pierce the Archduke's chest with lethal precision, the entire world grinds to a halt."
  },
  AvgDialog_131201_Content_5 = {
    Text = "In this corrupted timeline, the Phio-Garian crown prince discovered a certain book two months ago."
  },
  AvgDialog_131201_Content_50 = {
    Text = "The Archduke's agony, the princess's shock, the guards mid-stride—everything freezes into a grotesque, vivid oil painting."
  },
  AvgDialog_131201_Content_51 = {
    Text = "!!! This is..."
  },
  AvgDialog_131201_Content_52 = {
    Text = "After a heartbeat of silence, the colors of the painting begin to bleed and run. Time, space, and gravity collapse into a chaotic frenzy. Your body feels as if it's being torn apart as a hurricane of images flashes before your eyes."
  },
  AvgDialog_131201_Content_53 = {
    Text = "A grand funeral. The fury of a monarch. War. Cannons. Death. The blare of war horns and the screams of civilians. Vultures descending on the crimson fields of Verdun to feast on mangled remains."
  },
  AvgDialog_131201_Content_54 = {
    Text = "The fall of empires, lands torn asunder, kings in exile, and the grimoire... falling open once more."
  },
  AvgDialog_131201_Content_55 = {
    Text = "A viscous black liquid floods your vision. The familiar tragedy plays out again—absolute darkness and agony, a corrosion that seeps into every single cell of your being."
  },
  AvgDialog_131201_Content_56 = {
    Text = "Don't worry, {Male=Mr.,Female=Miss} Keeper. You're safe now."
  },
  AvgDialog_131201_Content_57 = {
    Text = "A hand rests on your shoulder. The chaotic, bleeding colors and the boundless darkness vanish."
  },
  AvgDialog_131201_Content_58 = {
    Text = "Your eyes snap open. The café is as quiet as ever; the Browning pistol is gone from your hand, and the freshly served Sachertorte sits before you, wafting an irresistible aroma."
  },
  AvgDialog_131201_Content_59 = {
    Text = "Arachne... what... what happened? We were just..."
  },
  AvgDialog_131201_Content_6 = {
    Text = "A grimoire of forbidden sorcery—one capable of calling upon a certain deity that do not belong to this dimension."
  },
  AvgDialog_131201_Content_60 = {
    Text = "Don't be alarmed. We've simply returned to the moment we first entered the café. On the bright side, we managed to get a free cup of coffee out of it."
  },
  AvgDialog_131201_Content_61 = {
    Text = "Arachne lifts her cup and takes a small, smiling sip. Your own stunned reflection stares back at you from the surface of the dark liquid."
  },
  AvgDialog_131201_Content_62 = {
    Text = "The Threads of Fate are not for your eyes to perceive. When an actor from outside the stage tries to forcibly alter this world's destiny, they inevitably lose themselves in the web."
  },
  AvgDialog_131201_Content_63 = {
    Text = "Past and future, the countless destinies of this stage intertwining before your eyes... that is the true face of the Web of Fate."
  },
  AvgDialog_131201_Content_64 = {
    Text = "The future... are you saying everything I saw was real? The wars, the millions of deaths... did I really cause all of that?"
  },
  AvgDialog_131201_Content_65 = {
    Text = "Fate allowed you to witness it. After the assassination of the Archduke, that was indeed the path the world was meant to take. But rest easy, {Male=Mr.,Female=Miss} Keeper. I have already rewoven the destiny of this stage."
  },
  AvgDialog_131201_Content_66 = {
    Text = "You glance out the window. The crowd is still bustling, but the citizens and officers corrupted by Nefraea's influence have vanished without a trace."
  },
  AvgDialog_131201_Content_67 = {
    Text = "If I had gone through with it... if you hadn't repaired the damage..."
  },
  AvgDialog_131201_Content_68 = {
    Text = "A month from now, the death of that Crown Prince would have triggered the largest war in history. Eight empires would have been dragged into the abyss, and twenty million souls would have perished."
  },
  AvgDialog_131201_Content_69 = {
    Text = "The very ground beneath our feet would have turned to ash. Of all the people sitting around us in this café, not a single one would have survived."
  },
  AvgDialog_131201_Content_7 = {
    Text = "Arachne raises her head, her gaze fixed on the threads you cannot see."
  },
  AvgDialog_131201_Content_70 = {
    Text = "Arachne swirls her coffee, watching the steady flow of traffic outside. She speaks with a terrifying calm, as if she were merely describing the ingredients of a common dessert."
  },
  AvgDialog_131201_Content_71 = {
    Text = "The lively hum of the street reaches your ears, a melody of peace and prosperity that now feels incredibly fragile."
  },
  AvgDialog_131201_Content_72 = {
    Text = "And what about the Dissolution? Why did killing the prince still lead to the end of the world?"
  },
  AvgDialog_131201_Content_73 = {
    Text = "In that great war, the empire was defeated. The Monarch was left with no choice but to accept Fate's cruel verdict—until he found a new path."
  },
  AvgDialog_131201_Content_74 = {
    Text = "Sorcery from beyond this world, a deity that transcends all known power... for a father who has lost his son and an Emperor who has lost his nation, could anything be more alluring?"
  },
  AvgDialog_131201_Content_75 = {
    Text = "Her gentle tone sends a chill down your spine. The crushing weight of two billion lives feels like a physical burden pressing against your chest."
  },
  AvgDialog_131201_Content_76 = {
    Text = "<Shake:I never imagined assassinating one prince would spiral into this... I thought I was helping...>"
  },
  AvgDialog_131201_Content_77 = {
    Text = "Fate compelled you to make that choice so that you might finally see it for what it is. You cannot see the threads themselves, but you now understand the intricate ways in which they are woven."
  },
  AvgDialog_131201_Content_78 = {
    Text = "These threads form a vast web. The slightest tremor in a single strand can bring the entire structure crashing down."
  },
  AvgDialog_131201_Content_79 = {
    Text = "This is Fate—in all its terrible complexity."
  },
  AvgDialog_131201_Content_8 = {
    Text = "This stage was never meant to connect with the divine. For a long time, it could have been spared the fate of Dissolution."
  },
  AvgDialog_131201_Content_80 = {
    Text = "You take a deep breath, trying to steady your heart, which is still hammering against your ribs from the lingering terror."
  },
  AvgDialog_131201_Content_81 = {
    Text = "At least... at least you stopped the war..."
  },
  AvgDialog_131201_Content_82 = {
    Text = "I did not stop the war, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131201_Content_83 = {
    Text = "Arachne shakes her head gently."
  },
  AvgDialog_131201_Content_84 = {
    Text = "In the new destiny I have woven, the Emperor will witness a mere fraction of the miracles within that grimoire. That taste of power will become the very foundation upon which he builds his war."
  },
  AvgDialog_131201_Content_85 = {
    Text = "The Monarch and his allies will launch a conflict on an even grander scale, pulling empires from across the oceans into the fray."
  },
  AvgDialog_131201_Content_86 = {
    Text = "The number of people who die in this version of history will be four times greater than before."
  },
  AvgDialog_131201_Content_87 = {
    Text = "She continues her calm narration, sounding like a mother telling a bedtime story to a child who cannot sleep."
  },
  AvgDialog_131201_Content_88 = {
    Text = "What? Why... why would that happen?"
  },
  AvgDialog_131201_Content_89 = {
    Text = "You have seen the complexity of the web. To forcibly avoid an event that is destined to occur only invites a far more horrific outcome."
  },
  AvgDialog_131201_Content_9 = {
    Text = "In twenty days, he will begin to study the secrets within that book in earnest. From that moment on, this stage will follow all the others, descending inevitably toward total destruction."
  },
  AvgDialog_131201_Content_90 = {
    Text = "The Monarch is still defeated; the limited knowledge in that book offers the empire no lasting salvation."
  },
  AvgDialog_131201_Content_91 = {
    Text = "After this second failure, sorcery will be dismissed as a farce. No ruler on this stage will ever turn to it again."
  },
  AvgDialog_131201_Content_92 = {
    Text = "Their eyes will turn elsewhere. They will put their faith in science, researching weapons capable of devouring entire planets. They will enjoy a brief, tense peace under the shadow of these armaments, only to be destroyed by the very tools they created."
  },
  AvgDialog_131201_Content_93 = {
    Text = "This stage is still destined to vanish in some future apocalypse—that is its inescapable fate. But for a time, they will enjoy a period of prosperity as beautiful as a work of art."
  },
  AvgDialog_131201_Content_94 = {
    Text = "The Gaze of Tohuwabohu will be kept at bay, at least for a while."
  },
  AvgDialog_131201_Content_95 = {
    Text = "Arachne's spoon stirs slowly in her cup. The dark brown vortex it creates looks exactly like the swirling patterns you saw within the Web of Fate."
  },
  AvgDialog_131201_Content_96 = {
    Text = "She bows her head. The sunlight from the window falls over her like a mournful shroud."
  },
  AvgDialog_131201_Content_97 = {
    Text = "Struggle, weave, mend... yet nothing truly changes. This is Fate, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131201_Content_98 = {
    Text = "The blare of trumpets and saxophones drifts past the window, carrying with it the cheers and curses of the distant crowd."
  },
  AvgDialog_131201_Content_99 = {
    Text = "The Archduke and his wife sit in the back of their open-top car, admiring the ancient city. The people chase after the vehicle, rushing headlong toward the destiny that was written for them long ago."
  },
  AvgDialog_131202_Content_1 = {Text = "Clatter!"},
  AvgDialog_131202_Content_10 = {Text = "Believers?"},
  AvgDialog_131202_Content_11 = {
    Text = "In purple robes... I have never... never seen their like..."
  },
  AvgDialog_131202_Content_12 = {
    Text = "They took \"Memories\" to the altar... cough, cough..."
  },
  AvgDialog_131202_Content_13 = {
    Text = "St. Vasily Street... to a church that belongs to them..."
  },
  AvgDialog_131202_Content_14 = {
    Text = "Bone and meat tremble as the old man fights to wring one last breath from his shattered frame."
  },
  AvgDialog_131202_Content_15 = {
    Text = "He knows Arachne cannot perceive the threads of those men. He knows this is his final duty."
  },
  AvgDialog_131202_Content_16 = {
    Text = "Miss... villains in the shadows are hunting us... She has corrupted our destinies..."
  },
  AvgDialog_131202_Content_17 = {
    Text = "They took my blood... In that church, she will perform her horrific ritual..."
  },
  AvgDialog_131202_Content_18 = {
    Text = "An Avenger of Fate, bathed in our blood... the evil god of the shadows is coming... all destiny will fall... into total... cough, cough... total chaos!"
  },
  AvgDialog_131202_Content_19 = {
    Text = "His pupils dilate. He shudders with a cold, primal terror, as if he is staring into a purgatory more horrific than his darkest nightmare."
  },
  AvgDialog_131202_Content_2 = {
    Text = "Spiders scatter. The last squire falls in a flash of silver light, but the master of the storm has long since vanished. You and Arachne approach the broken man huddled in the center of the room."
  },
  AvgDialog_131202_Content_20 = {
    Text = "He grips Arachne's sleeve, looking up at her with pleading eyes."
  },
  AvgDialog_131202_Content_21 = {
    Text = "Miss... I still find myself calling you Miss... You were so slow to learn your first words. You worried the Master and the Madam to no end..."
  },
  AvgDialog_131202_Content_22 = {
    Text = "When you finally spoke to bid me farewell, everyone else rejoiced... but I knew. Only I knew those words were a verdict Fate would never let you escape."
  },
  AvgDialog_131202_Content_23 = {
    Text = "I went home to wait for death. I couldn't stop weeping—not for myself, but for you, Miss Arachne..."
  },
  AvgDialog_131202_Content_24 = {
    Text = "I knew then... what a heavy curse you were meant to bear..."
  },
  AvgDialog_131202_Content_25 = {
    Text = "Tears stream down his weathered, furrowed cheeks. With a trembling hand, he reaches out for Arachne. Through his blurred vision, he sees her once again as a young girl."
  },
  AvgDialog_131202_Content_26 = {
    Text = "That innocent face never cried out; she simply watched the empty sky with curiosity, smiling at destinies no one else could see."
  },
  AvgDialog_131202_Content_27 = {
    Text = "Miss Arachne, please... protect her. Protect \"Memories\"... and please, take care of yourself."
  },
  AvgDialog_131202_Content_28 = {
    Text = "Don't... get lost... in the web..."
  },
  AvgDialog_131202_Content_29 = {
    Text = "His voice fades to a whisper and finally vanishes. When his breathing stops, Arachne gently closes his eyes."
  },
  AvgDialog_131202_Content_3 = {
    Text = "It's you..."
  },
  AvgDialog_131202_Content_30 = {
    Text = "Rest now, Mr. Lawrence."
  },
  AvgDialog_131202_Content_31 = {
    Text = "The corner of Lawrence's mouth lifts into a faint smile. In his final moments, he hears once more the very first words Arachne ever spoke."
  },
  AvgDialog_131202_Content_32 = {
    Text = "He asks for nothing more."
  },
  AvgDialog_131202_Content_33 = {
    Text = "You used your own butler's memories to create this Puppet... he's nothing like the other dolls you've made. Why?"
  },
  AvgDialog_131202_Content_34 = {
    Text = "Perhaps as a memorial. Or perhaps... I was just looking for a bit of comfort."
  },
  AvgDialog_131202_Content_35 = {Text = "Comfort?"},
  AvgDialog_131202_Content_36 = {
    Text = "I wanted to tell myself they were still with me. That they had never truly left."
  },
  AvgDialog_131202_Content_37 = {
    Text = "Arachne lowers the old man's broken body to the floor. She offers no further explanation, and you don't push for one. You know the answers are waiting for you, not far away."
  },
  AvgDialog_131202_Content_38 = {
    Text = "Within this Great Web, Nefraea's power is tied to these Puppets. Their deaths only draw her closer to the center of the weave."
  },
  AvgDialog_131202_Content_39 = {
    Text = "We must stop her before she gains the power to tear the web asunder. That is all that matters now, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131202_Content_4 = {
    Text = "<Shake:Miss Arachne... and you, young {Male=mister,Female=miss}... cough cough...>"
  },
  AvgDialog_131202_Content_40 = {
    Text = "Arachne rests her hands on the old man's head, touching the nearly invisible thread. On the far side of the city, a faint echo vibrates through the weave."
  },
  AvgDialog_131202_Content_41 = {
    Text = "Fate answered you?"
  },
  AvgDialog_131202_Content_42 = {
    Text = "Arachne nods. Before she stands, she takes one last look at Lawrence's smiling face."
  },
  AvgDialog_131202_Content_43 = {
    Text = "\"Memories\" is still alive. And those from the Abyssal Prison... they are waiting for us."
  },
  AvgDialog_131202_Content_5 = {
    Text = "The body before you is a ruin. Half of his flesh has been gnawed away, leaving a mess of rot and blood-stained bone."
  },
  AvgDialog_131202_Content_6 = {
    Text = "A fit of coughing wracks the old man, forcing out a few final drops of blood. Arachne holds a single, invisible thread that flickers like a candle in a gale, poised on the brink of snapping."
  },
  AvgDialog_131202_Content_7 = {
    Text = "We have to stop the bleeding... help me find something!"
  },
  AvgDialog_131202_Content_8 = {
    Text = "It's too late... Miss Arachne... save her... save \"Memories\"..."
  },
  AvgDialog_131202_Content_9 = {
    Text = "The believers... they took her..."
  },
  AvgDialog_131203_Content_1 = {
    Text = "Arachne! What are you doing?! Is this what you call... \"trust\"?"
  },
  AvgDialog_131203_Content_10 = {
    Text = "On this stage, you shall have your heart's desire."
  },
  AvgDialog_131203_Content_2 = {
    Text = "This is a destiny neither of us can escape, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131203_Content_3 = {
    Text = "I have never lied to you. I am taking you to your own stage, where you will give the performance of a lifetime. A performance that is entirely yours."
  },
  AvgDialog_131203_Content_4 = {
    Text = "As she draws near, you stare into her misty eyes, searching for the message she cannot speak aloud."
  },
  AvgDialog_131203_Content_5 = {
    Text = "(A performance... entirely mine...)"
  },
  AvgDialog_131203_Content_6 = {
    Text = "A spark of inspiration streaks through your mind like a shooting star, only to vanish into the clutter of your thoughts."
  },
  AvgDialog_131203_Content_7 = {
    Text = "The spider maids retreat. Arachne raises her hand, plucking an invisible string."
  },
  AvgDialog_131203_Content_8 = {
    Text = "Performance. Deception. Manipulation."
  },
  AvgDialog_131203_Content_9 = {
    Text = [[
"Rapture," this is your destiny. Take the stage, {Male=Mr.,Female=Miss} Keeper. 
On this stage, you shall finish your own story.]]
  },
  AvgDialog_131204_Content_1 = {
    Text = "Silver light shears through the silk. Using the opening, you break through the maids' defense and reach Arachne."
  },
  AvgDialog_131204_Content_10 = {
    Text = "She turns away. As her threads shift, an unbidden impulse ignites in your heart, forcing you to your feet."
  },
  AvgDialog_131204_Content_11 = {
    Text = "You feel certain of your own autonomy, a perfect vessel of free will. Yet, of your own volition, you follow Arachne, matching her pace and rhythm exactly as you walk toward the end of the silken path."
  },
  AvgDialog_131204_Content_12 = {Text = "..."},
  AvgDialog_131204_Content_13 = {
    Text = "Oh, welcome! {Male=Mr.,Female=Miss} %player%, my esteemed guest! Your footsteps have never sounded so musical."
  },
  AvgDialog_131204_Content_14 = {
    Text = "The theater's new master makes her entrance, her exaggerated voice echoing across the darkened stage."
  },
  AvgDialog_131204_Content_15 = {
    Text = "It isn't pleasant, is it? To have your fate toyed with? No matter, {Male=Mr.,Female=Miss} Keeper. This story is nearly over."
  },
  AvgDialog_131204_Content_16 = {
    Text = "Nefraea, what are you doing? ..."
  },
  AvgDialog_131204_Content_17 = {
    Text = "Suspense! That is why the audience comes to this theater! But don't be in such a rush, darling."
  },
  AvgDialog_131204_Content_18 = {
    Text = "Ladies and gentlemen! Prepare to cheer... wait, where are my puppets? Ah, there."
  },
  AvgDialog_131204_Content_19 = {
    Text = "What imaginative performance will our great avenger give, now that she has slain three Puppets?"
  },
  AvgDialog_131204_Content_2 = {
    Text = "I've got you!!"
  },
  AvgDialog_131204_Content_20 = {
    Text = "Now, witness the <Big:<Red:Climax of Act Two!>>"
  },
  AvgDialog_131204_Content_21 = {
    Text = "I call it... \"Rebirth.\""
  },
  AvgDialog_131204_Content_22 = {Text = "SNAP—"},
  AvgDialog_131204_Content_23 = {
    Text = "A beam of light shatters the darkness. A puppet holding a spinning wheel stumbles onto the stage."
  },
  AvgDialog_131204_Content_24 = {
    Text = "Nefraea, Reaper from the Abyss, Avenger of Fate... <Shake:I submit to your glorious power!>"
  },
  AvgDialog_131204_Content_25 = {
    Text = "This is Romance; it makes men fools. This is Kindness; it makes them weak. And these are my Memories... the source of all agony."
  },
  AvgDialog_131204_Content_26 = {
    Text = "I can bear them no longer... I offer them to you, great Nefraea."
  },
  AvgDialog_131204_Content_27 = {
    Text = "Truly, sister? My dear sister..."
  },
  AvgDialog_131204_Content_28 = {
    Text = "It's all right. I understand you best. Give your suffering to me."
  },
  AvgDialog_131204_Content_29 = {
    Text = "See? The Lantern of the Abyss is lit. Its light will guide us home."
  },
  AvgDialog_131204_Content_3 = {Text = "Ding—"},
  AvgDialog_131204_Content_30 = {
    Text = "What a warm light... but how do we go home?"
  },
  AvgDialog_131204_Content_31 = {
    Text = "Don't you see, sister?"
  },
  AvgDialog_131204_Content_32 = {
    Text = "This spinning wheel is the Apostle's body. These flames are the Apostle's eyes—They are watching us!"
  },
  AvgDialog_131204_Content_33 = {
    Text = "\"Nefraea\" stands in triumph, arms wide."
  },
  AvgDialog_131204_Content_34 = {
    Text = "Only by uniting the Authority of the Three Aeons shall the Nameless Apostle awaken!"
  },
  AvgDialog_131204_Content_35 = {
    Text = "They will open the path to the Supreme Deity... and then, all suffering and futility will end!"
  },
  AvgDialog_131204_Content_36 = {
    Text = "The puppet \"Nefraea\" tears off its wooden mask, revealing the real Nefraea beneath."
  },
  AvgDialog_131204_Content_37 = {
    Text = "A wooden stage, wooden puppets, and one living woman standing in the center, basking in the stare of her only audience member."
  },
  AvgDialog_131204_Content_38 = {
    Text = "The gateway is opening. Your mission is almost complete. Don't you see, sister?"
  },
  AvgDialog_131204_Content_39 = {
    Text = "You don't have to weave that endless web anymore. You don't have to keep cutting yourself apart!"
  },
  AvgDialog_131204_Content_4 = {
    Text = "Slender fingers pluck the air. A string hums, sending an elegant ripple through the room."
  },
  AvgDialog_131204_Content_40 = {
    Text = "Take me back, will you, Arachne? ...Please... Make me a part of you once more..."
  },
  AvgDialog_131204_Content_41 = {
    Text = "Tears ruin her makeup, leaving black, corrosive streaks on her face. Her manic laughter and sobs weaves a suffocating web around around her—the only living soul on this stage."
  },
  AvgDialog_131204_Content_42 = {
    Text = "Nefraea sinks to her knees to cradle the smooth, unfeeling cheek of \"Arachne,\" her tears pooling in the hollow rictus of its smiling mask."
  },
  AvgDialog_131204_Content_43 = {
    Text = "She stares intensely at the real Arachne below the stage, her trembling lips pressed against the puppet's wooden ear. Her voice is so soft, it feels like a whisper meant only for herself."
  },
  AvgDialog_131204_Content_44 = {
    Text = "Don't abandon me. Don't leave me behind again... <Italic:please?>"
  },
  AvgDialog_131204_Content_5 = {
    Text = "The ripple swallows your silver light, and the Silver Key vanishes instantly. As the wave passes through you, your flesh withers to bone and your blood turns to mire. you are torn into pieces, then restored as if nothing happened."
  },
  AvgDialog_131204_Content_6 = {
    Text = "All power fades; all thought is extinguished. Wherever the ripple reaches, worlds transform into threads in her hands. Including you."
  },
  AvgDialog_131204_Content_7 = {
    Text = [[
She is the Master of this Theater. 
She is Fate itself.]]
  },
  AvgDialog_131204_Content_8 = {
    Text = "Arachne... you can control my Fate?!..."
  },
  AvgDialog_131204_Content_9 = {
    Text = "Arachne's smile is like a placid lake; you cannot see beneath the surface, only the reflection of yourself."
  },
  AvgDialog_131205_Content_1 = {Text = "Gunfire"},
  AvgDialog_131205_Content_10 = {
    Text = "You don't need to turn in any assignments."
  },
  AvgDialog_131205_Content_11 = {
    Text = "Professor Arachne... what do you mean?"
  },
  AvgDialog_131205_Content_12 = {
    Text = "Do you remember who you are and where you come from?"
  },
  AvgDialog_131205_Content_13 = {
    Text = "Me? I'm obviously..."
  },
  AvgDialog_131205_Content_14 = {
    Text = "%player%. A Hvatz local through and through. A first-year student at the Academy of Dramatic Arts. Your parents are ordinary government clerks who dote on you. You've had two respectable romances. Passionate, if not exceptionally talented, with a weakness for Sachertorte and grilled meat wraps."
  },
  AvgDialog_131205_Content_15 = {
    Text = "The clear memories suddenly blur as a different set of recollections forces its way to the surface. Mythag, Awakeners, Dissolution, Tohuwabohu..."
  },
  AvgDialog_131205_Content_16 = {
    Text = "Your eyes snap open, and you stare at the woman sitting across from you, calmly savoring her coffee."
  },
  AvgDialog_131205_Content_17 = {
    Text = "No... that's not right... I'm the Keeper of Mythag... What's happening?!"
  },
  AvgDialog_131205_Content_18 = {
    Text = "I remember now... We were in your theater. We stepped onto a stage, and then... and then..."
  },
  AvgDialog_131205_Content_19 = {
    Text = "And then you ordered afternoon tea. Your taste as a local is quite refined."
  },
  AvgDialog_131205_Content_2 = {Text = "Ding-ding!"},
  AvgDialog_131205_Content_20 = {
    Text = "Arachne takes a sip of the dark liquid in her cup and nods in approval."
  },
  AvgDialog_131205_Content_21 = {
    Text = "Here is your order. Everything is served."
  },
  AvgDialog_131205_Content_22 = {
    Text = "The plates release a mouth-watering aroma. As the waiter leans in to set the table, he brings his mouth close to your ear."
  },
  AvgDialog_131205_Content_23 = {
    Text = "The assassination plot has leaked. The Archduke will likely change his route. The handler will notify you as soon as there's news. Get ready, %player%."
  },
  AvgDialog_131205_Content_24 = {
    Text = "He discreetly presses a brand-new Browning pistol into your hand. When you look up, the waiter is wearing a friendly, professional smile again. He bows and disappears back into the kitchen with his tray."
  },
  AvgDialog_131205_Content_25 = {
    Text = "The weight of conflicting memories piles up, and you rub your aching temples in pain."
  },
  AvgDialog_131205_Content_26 = {
    Text = "Carrying two distinct lives in a single mind is rarely a pleasant experience for a novice."
  },
  AvgDialog_131205_Content_27 = {
    Text = "It's fine. Compared to facing Tohuwabohu, a headache feels like a massage."
  },
  AvgDialog_131205_Content_28 = {
    Text = "My memory says I'm following the Iron Hand's orders. In two hours, I'm supposed to use this gun to assassinate the visiting heir to the Phio-Garian Empire throne..."
  },
  AvgDialog_131205_Content_29 = {
    Text = "You trace the grooves of the pistol, trying to organize the memories that belong to this world."
  },
  AvgDialog_131205_Content_3 = {
    Text = "Wheels rattle over the rugged cobblestones. An angry bell shrieks at the massive procession, kicking up clouds of dust and a chorus of curses."
  },
  AvgDialog_131205_Content_30 = {
    Text = "Before you can ask anything else, a harsh light floods the café. The sharp click of military boots on concrete rings out as soldiers march toward the counter."
  },
  AvgDialog_131205_Content_31 = {
    Text = "Good afternoon, officers. How can I—"
  },
  AvgDialog_131205_Content_32 = {
    Text = "Without a word, an officer lunges forward, pinning the waiter's hands behind his back and slamming his head onto the bar."
  },
  AvgDialog_131205_Content_33 = {
    Text = "A gun barrel is pressed against his forehead. The waiter's eyes go wide with terror."
  },
  AvgDialog_131205_Content_34 = {
    Text = "Bosant, member of the Iron Hand. You have ten seconds to tell me where your accomplices are."
  },
  AvgDialog_131205_Content_35 = {
    Text = "The waiter gasps for air, trembling. In his desperate struggle, his eyes dart toward the corner of the room."
  },
  AvgDialog_131205_Content_36 = {
    Text = "But the table you were just occupying is empty. Only half a cup of coffee remains, its steam drifting lazily into the air."
  },
  AvgDialog_131205_Content_37 = {Text = "..."},
  AvgDialog_131205_Content_38 = {
    Text = "We should be safe here for a moment."
  },
  AvgDialog_131205_Content_39 = {
    Text = "You slip out the café's back door, merging like two unremarkable drops of water into the chaotic crowd outside."
  },
  AvgDialog_131205_Content_4 = {
    Text = "You wave a hand, brushing away the dust drifting through the café curtains."
  },
  AvgDialog_131205_Content_40 = {
    Text = "What's happening? Why do I have these conflicting memories?"
  },
  AvgDialog_131205_Content_41 = {
    Text = "To step onto the stage of the Theater of Fate is to become a character. And every character has a life of their own."
  },
  AvgDialog_131205_Content_42 = {
    Text = "This is a world in a distant dimension you've never heard of or visited. Yet, as a character born here, you know it like the back of your hand."
  },
  AvgDialog_131205_Content_43 = {
    Text = "Welcome to one of my stages, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131205_Content_44 = {
    Text = "You mean... you can use the stage to reach other worlds?!"
  },
  AvgDialog_131205_Content_45 = {
    Text = "Arachne sees the sudden intensity in your eyes. She lifts the coffee she brought from the café, savoring the scent before shaking her head."
  },
  AvgDialog_131205_Content_46 = {
    Text = "The strange fact that she's fleeing a crime scene with coffee and cake doesn't even strike you as odd. It feels perfectly natural for her, as if it's simply a part of her fate."
  },
  AvgDialog_131205_Content_47 = {
    Text = "Lady Daffodil explained the principles of dimensional travel to you. The barriers between worlds are incredibly solid. Every crossing demands a terrible price; it is not something done lightly."
  },
  AvgDialog_131205_Content_48 = {
    Text = "But aren't we here right now?..."
  },
  AvgDialog_131205_Content_49 = {
    Text = "The Theater of Fate can briefly bridge the destinies of different worlds. Currently, we are just two characters lost in a sea of people—fleeting projections that will vanish in the blink of an eye."
  },
  AvgDialog_131205_Content_5 = {
    Text = "One shawarma wrap, one Sachertorte, and two cups of Hvatz coffee. Thank you."
  },
  AvgDialog_131205_Content_50 = {
    Text = "A projection... even a projection is fine. Can you use this method to help me return?"
  },
  AvgDialog_131205_Content_51 = {
    Text = "I'm truly sorry, %player%. The gate you closed blocked Tohuwabohu's Gaze, but it also severed the Threads of Fate."
  },
  AvgDialog_131205_Content_52 = {
    Text = "Attempting to exert influence there now would trigger a disaster beyond our endurance."
  },
  AvgDialog_131205_Content_53 = {
    Text = "She sees the disappointment on your face and smiles, handing you the cake."
  },
  AvgDialog_131205_Content_54 = {
    Text = "Rest assured, %player%. Once we've dealt with my sister, the passage back to Kadath will open again."
  },
  AvgDialog_131205_Content_55 = {
    Text = "Fate never betrays those who wait, and we must never spurn the gifts Fate provides. Go on, try it."
  },
  AvgDialog_131205_Content_56 = {
    Text = "You take a breath and take a small bite of the cake. The sweetness is so overwhelming that you almost forget the jarring discomfort of your colliding memories."
  },
  AvgDialog_131205_Content_57 = {
    Text = "Hmm... Word is Archduke Flavian never misses a chance to sample the local specialty cake whenever he visits. For a crown prince, he certainly has fine taste."
  },
  AvgDialog_131205_Content_58 = {
    Text = "So, what exactly did Nefraea influence here? How are we supposed to fix this..."
  },
  AvgDialog_131205_Content_59 = {
    Text = "As you speak, Arachne seems drawn to something else. She glances up at invisible threads in the air that remain hidden from your sight."
  },
  AvgDialog_131205_Content_6 = {
    Text = "You hand the parchment menu back to the waiter and stare glumly out the window at the familiar street."
  },
  AvgDialog_131205_Content_60 = {
    Text = "She smiles, draining the last drop of her coffee. She hands a few coins and the empty tray to a passing waiter heading back to the café, offering him a soft word of thanks."
  },
  AvgDialog_131205_Content_61 = {
    Text = "She has found us. Perfect timing. Be careful, %player%."
  },
  AvgDialog_131205_Content_62 = {Text = "BANG—"},
  AvgDialog_131205_Content_63 = {
    Text = "You instinctively duck. A bullet whizzes past, nearly grazing the top of your head."
  },
  AvgDialog_131205_Content_64 = {
    Text = "Right there!"
  },
  AvgDialog_131205_Content_65 = {
    Text = "It's the Iron Hand assassins! Get them!"
  },
  AvgDialog_131205_Content_66 = {
    Text = "Led by a few shouting citizens, a swarm of officers pushes through the crowd to surround you. As they close in, their bodies begin to warp—dark, chitinous spider limbs erupt from their torsos, and razor-sharp claws lash out."
  },
  AvgDialog_131205_Content_7 = {
    Text = "This street really needs to be widened. It looked exactly like this when I was a kid. Aside from getting more run-down, it hasn't changed a bit in all these years."
  },
  AvgDialog_131205_Content_8 = {
    Text = "The authorities are useless at building anything. The only thing they're good at is selling off Hvatz land and serving up cake to the Archduke."
  },
  AvgDialog_131205_Content_9 = {
    Text = "Refugees, protests, and an Archduke who just had to visit now... Professor Arachne, can I get an extension on my folklore assignment? The Iron Hand's activities have been draining all my energy lately."
  },
  AvgDialog_131206_Content_1 = {
    Text = "The Old Smoke, Asleep"
  },
  AvgDialog_131206_Content_10 = {
    Text = "Creak—creak—the Threads of Fate converge in her hands."
  },
  AvgDialog_131206_Content_11 = {
    Text = "The puppets march in line, stepping into the Great Web."
  },
  AvgDialog_131206_Content_12 = {
    Text = "They dance. They sing. Creak—creak—"
  },
  AvgDialog_131206_Content_13 = {
    Text = "They die with the Great Web, silent and without a trace."
  },
  AvgDialog_131206_Content_14 = {Text = "..."},
  AvgDialog_131206_Content_15 = {
    Text = "My lady, our new play has begun."
  },
  AvgDialog_131206_Content_16 = {
    Text = "The passage back to Kadath has been closed just in time. That {Male=mister,Female=miss} has arrived in the city."
  },
  AvgDialog_131206_Content_17 = {
    Text = "Well then. Do you like the new play?"
  },
  AvgDialog_131206_Content_18 = {
    Text = "Hmm... perhaps it's a touch too complicated?"
  },
  AvgDialog_131206_Content_19 = {
    Text = "Simple stories are easier to manage, yes—but for certain people, a simple story cannot contain their Fate."
  },
  AvgDialog_131206_Content_2 = {
    Text = "The trumpet plays a flourish. The dark-cloaked warrior enters."
  },
  AvgDialog_131206_Content_20 = {
    Text = "Intense emotions, dramatic turns, a moving plot, a tragic end..."
  },
  AvgDialog_131206_Content_21 = {
    Text = "These are the destiny that belongs to a \"Hero.\""
  },
  AvgDialog_131206_Content_22 = {
    Text = "Go on; it's your turn on stage."
  },
  AvgDialog_131206_Content_23 = {
    Text = "The maiden prostrates herself. The moment her forehead touches the floor, her body splinters apart—flesh and skin dissolving into pale violet spiders that scatter into every corner of the room and vanish."
  },
  AvgDialog_131206_Content_24 = {Text = "..."},
  AvgDialog_131206_Content_25 = {
    Text = "Cough... cough, cough..."
  },
  AvgDialog_131206_Content_26 = {
    Text = "Beneath you is hard asphalt. You stagger to your feet, pressing your palms against your aching, muddled head."
  },
  AvgDialog_131206_Content_27 = {
    Text = "What was that..."
  },
  AvgDialog_131206_Content_28 = {
    Text = "Ah! The gateway to Kadath!!"
  },
  AvgDialog_131206_Content_29 = {
    Text = "You snap to alertness, lifting your gaze to the sky."
  },
  AvgDialog_131206_Content_3 = {
    Text = "Ah, Kadath, the homeland of my dreams! At last, I can return!"
  },
  AvgDialog_131206_Content_30 = {
    Text = "The sky is a clear, brilliant blue. Sunlight shines on you. No trace of the dark sun or dimensional passage remains."
  },
  AvgDialog_131206_Content_31 = {
    Text = "Th-this person is so strange... did {Male=he,Female=she} just fall from the sky?"
  },
  AvgDialog_131206_Content_32 = {
    Text = "Well, from what I know, there's a tech company nearby testing aircraft. {Male=he,Female=she} is probably one of their test pilots."
  },
  AvgDialog_131206_Content_33 = {
    Text = "Ugh... I..."
  },
  AvgDialog_131206_Content_34 = {Text = "People."},
  AvgDialog_131206_Content_35 = {
    Text = "A dense crowd fills your vision, your eyes still stinging from the light."
  },
  AvgDialog_131206_Content_36 = {
    Text = "A city as bustling as Londinium pulls you back to distant memories of Kadath."
  },
  AvgDialog_131206_Content_37 = {
    Text = "Busy streets, gathered crowds, shops bursting with color everywhere..."
  },
  AvgDialog_131206_Content_38 = {
    Text = "The world of this dimension has seen its population sharply decline due to the Dissolution. You have never witnessed a scene this alive, not even in Necrovia."
  },
  AvgDialog_131206_Content_39 = {
    Text = "Excuse me... where am I?"
  },
  AvgDialog_131206_Content_4 = {
    Text = "My mentors, my companions, my dearest friend, my... everything."
  },
  AvgDialog_131206_Content_40 = {
    Text = "Ha, strange! Someone who's never even heard of Londinium? This is the greatest city in the world!"
  },
  AvgDialog_131206_Content_41 = {
    Text = "<Shake:!!!>"
  },
  AvgDialog_131206_Content_42 = {
    Text = "What did you say this place is called?!"
  },
  AvgDialog_131206_Content_43 = {
    Text = "You are certain you heard those words."
  },
  AvgDialog_131206_Content_44 = {
    Text = "Your groggy mind snaps clear in an instant. You spring to your feet and take in everything around you."
  },
  AvgDialog_131206_Content_45 = {
    Text = "Brick Crossroads. The weathered lettering on the intersection signpost is exactly as you remember it."
  },
  AvgDialog_131206_Content_46 = {
    Text = "Time Wrinkle Bookshop. Every time you used to sneak out of school, your favorite thing was to hide here and lose yourself in detective novels."
  },
  AvgDialog_131206_Content_47 = {
    Text = "Fragrant Market Grocery... where Professor Dexter always asked you to bring him back a bottle of gin. N's little trick."
  },
  AvgDialog_131206_Content_48 = {
    Text = "Morning Dew Florist. On the anniversary of your first year as a Keeper, Ramona had planned to order you the brightest bouquet in all of Londinium here..."
  },
  AvgDialog_131206_Content_49 = {Text = "..."},
  AvgDialog_131206_Content_5 = {
    Text = "Once I pass through this dark gateway, I shall be reunited with them once more!"
  },
  AvgDialog_131206_Content_50 = {
    Text = "Londinium... I really... came back?"
  },
  AvgDialog_131206_Content_51 = {
    Text = "Excuse me... excuse me, what has become of Mythag?!"
  },
  AvgDialog_131206_Content_52 = {
    Text = "Mythag? We've never heard of any such place, {Male=sir,Female=miss}."
  },
  AvgDialog_131206_Content_53 = {
    Text = "What about the Dissolution? How badly has it struck here?!"
  },
  AvgDialog_131206_Content_54 = {
    Text = "Dis... what? This city has never suffered anything of the sort."
  },
  AvgDialog_131206_Content_55 = {
    Text = "Young {Male=sir,Female=lady}, I think you're just tired and a little confused... Sit down on that bench and eat something. I happen to have a little with me."
  },
  AvgDialog_131206_Content_56 = {
    Text = "The elder holds out the bread and water he just bought from the grocery store."
  },
  AvgDialog_131206_Content_57 = {
    Text = "Ah, thank you so much... But I'm not hungry right now, I just... have some things I can't make sense of..."
  },
  AvgDialog_131206_Content_58 = {
    Text = "This can't be right... No Mythag, no Dissolution..."
  },
  AvgDialog_131206_Content_59 = {
    Text = "Grandpa, {Male=he,Female=she}'s so weird. Why does {Male=he,Female=she} keep talking to {Male=him,Female=herself}?"
  },
  AvgDialog_131206_Content_6 = {
    Text = "Then why is this door, so close within reach, shut tight? Why has this cruel sky forsaken me?"
  },
  AvgDialog_131206_Content_60 = {
    Text = "That's not nice to say. {Male=he,Female=she} may be going through something difficult. Mind your manners with guests who've come from far away."
  },
  AvgDialog_131206_Content_61 = {
    Text = "A hand taps gently on your shoulder. You turn around to find an unfamiliar face."
  },
  AvgDialog_131206_Content_62 = {
    Text = "We're patrol officers in the area, under the jurisdiction of the MTC. Here's my ID."
  },
  AvgDialog_131206_Content_63 = {
    Text = "Good day to you. A kind citizen let us know that a traveler has gotten lost in our beautiful city."
  },
  AvgDialog_131206_Content_64 = {
    Text = "Is there anything we can help you with, {Male=sir,Female=miss}?"
  },
  AvgDialog_131206_Content_65 = {
    Text = "You take a brief moment to think. Until you understand what's going on, it's best to draw as little attention as possible."
  },
  AvgDialog_131206_Content_66 = {
    Text = "Ah... thank you for the concern. I just fainted while wandering around—nothing serious."
  },
  AvgDialog_131206_Content_67 = {
    Text = "Thank you both. We have things to attend to, so we'll be on our way..."
  },
  AvgDialog_131206_Content_68 = {
    Text = "I see. In that case, if you don't mind—I'd like just a little more of your time. There are a few things I'd like to ask."
  },
  AvgDialog_131206_Content_69 = {
    Text = "The officer steps toward you with a smile, brushing the dust from your shoulder"
  },
  AvgDialog_131206_Content_7 = {
    Text = "My dear Silver Key... illuminate my path... grant me even a fragment of an answer..."
  },
  AvgDialog_131206_Content_70 = {
    Text = "Keeper—that's what I should call you, isn't it?"
  },
  AvgDialog_131206_Content_71 = {
    Text = "I'd like to ask... are you satisfied with the welcome ceremony I've arranged for you?"
  },
  AvgDialog_131206_Content_72 = {Text = "!!!"},
  AvgDialog_131206_Content_73 = {
    Text = "A nauseating, wet tearing sound rises in the air. Massive spider limbs burst through the bodies of the officers and bystanders, splattering thick, iron-smelling blood across you."
  },
  AvgDialog_131206_Content_74 = {
    Text = "Fate sends its greetings, dear Keeper."
  },
  AvgDialog_131206_Content_75 = {
    Text = "Our distinguished guest has arrived at the theater. Show {Male=him,Female=her} to {Male=his,Female=her} seat, my children."
  },
  AvgDialog_131206_Content_76 = {
    Text = "Yes, my lady."
  },
  AvgDialog_131206_Content_77 = {
    Text = "Watch out!!"
  },
  AvgDialog_131206_Content_8 = {
    Text = "The lights shift. The Silver Singer takes the stage."
  },
  AvgDialog_131206_Content_9 = {
    Text = "Creak—creak—the Goddess of Fate turns Her spinning wheel."
  },
  AvgDialog_131207_Content_1 = {
    Text = "Reflection of Divinity"
  },
  AvgDialog_131207_Content_10 = {
    Text = "You still have a chance to stop, Nefraea."
  },
  AvgDialog_131207_Content_11 = {
    Text = "And if we all vanish? What of it?"
  },
  AvgDialog_131207_Content_12 = {
    Text = "Nefraea offers a coy smile, turning to stare at her devoted squires."
  },
  AvgDialog_131207_Content_13 = {
    Text = "Tell me, children, are you afraid?"
  },
  AvgDialog_131207_Content_14 = {
    Text = "A wave of desperate laughter meets Arachne's warning."
  },
  AvgDialog_131207_Content_15 = {
    Text = "Hahaha! We are those abandoned by Fate. No disaster can make us tremble... Please, bring us salvation, my lady!"
  },
  AvgDialog_131207_Content_16 = {
    Text = "Good child."
  },
  AvgDialog_131207_Content_17 = {
    Text = "Nefraea affectionately pats a squire on the head."
  },
  AvgDialog_131207_Content_18 = {
    Text = "You have it all wrong, my dear sister. Fate has already sentenced us to death and eternal imprisonment. Forsaken souls do not beg for mercy."
  },
  AvgDialog_131207_Content_19 = {
    Text = "We are here for revenge. Revenge against Fate."
  },
  AvgDialog_131207_Content_2 = {
    Text = "On a grand stage unlike anything you have ever seen, Nefraea's black spinning wheel stands alone at the center. Within the massive ring, an ethereal blue light that never fades illuminates Nefraea's joyful face."
  },
  AvgDialog_131207_Content_20 = {
    Text = "Whether by accident or design, one of the Threads of Fate Nefraea is toying with snaps quietly."
  },
  AvgDialog_131207_Content_21 = {
    Text = "At that exact moment, a stage not far away shatters with a thunderous crash, breaking into fragments that dissolve into the theater's endless void."
  },
  AvgDialog_131207_Content_22 = {
    Text = "Oh! My apologies. I accidentally broke your thread..."
  },
  AvgDialog_131207_Content_23 = {
    Text = "Hurry now, dear sister. There are plenty of stages in this theater, but you would hate to see another one get wrecked, wouldn't you?"
  },
  AvgDialog_131207_Content_24 = {
    Text = "Arachne lets out a faint sigh. When she opens her eyes again, she raises a fingertip and lightly taps the top of your head."
  },
  AvgDialog_131207_Content_25 = {
    Text = "Arachne! Don't do this... there must be another way!"
  },
  AvgDialog_131207_Content_26 = {
    Text = "Take the stage. Offer the Aeons' Authority to the Apostle... This is your inescapable destiny, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131207_Content_27 = {
    Text = "Arachne's irresistible voice resonates through your mind. As you lift your feet and walk toward the stage, the three long-absent powers within you begin to stir."
  },
  AvgDialog_131207_Content_28 = {
    Text = "They writhe and clash within you, raging against Arachne's oracular command."
  },
  AvgDialog_131207_Content_29 = {
    Text = "Impressive. Worthy of the Three Aeons... to have such a sliver of Authority left, yet still possess the power to influence their host across such a distance."
  },
  AvgDialog_131207_Content_3 = {
    Text = "Look, {Male=Mr.,Female=Miss} Keeper, what beautiful lights..."
  },
  AvgDialog_131207_Content_30 = {
    Text = "Make them behave, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131207_Content_4 = {
    Text = "This beam is a gift of Fate. It will guide us toward that land of Rapture where suffering does not exist."
  },
  AvgDialog_131207_Content_5 = {
    Text = "Nefraea reaches out, tracing the patterns left by the light within the dimensional space. The shadow of her hand slowly closes, crawling across Arachne's face."
  },
  AvgDialog_131207_Content_6 = {
    Text = "Come, sister. It is time for our protagonist to make their entrance."
  },
  AvgDialog_131207_Content_7 = {
    Text = "...Fate is not something to be toyed with or tampered with, Nefraea."
  },
  AvgDialog_131207_Content_8 = {
    Text = "Every destiny is already sealed. If you awaken that deity and let everything end... forcibly altering Fate will bring a catastrophe beyond your imagination."
  },
  AvgDialog_131207_Content_9 = {
    Text = "Whether it is what you despise or what you hold dear, all of it will vanish in the apocalypse."
  },
  AvgDialog_131208_Content_1 = {
    Text = "The Verdict"
  },
  AvgDialog_131208_Content_10 = {
    Text = "The girl draws a deep breath and smiles with contentment."
  },
  AvgDialog_131208_Content_11 = {
    Text = "The irises have begun to bloom... spring has truly arrived."
  },
  AvgDialog_131208_Content_12 = {
    Text = "Hey, Rea, have I ever asked you what your favorite season is?"
  },
  AvgDialog_131208_Content_13 = {
    Text = "I have no favorite season, my lady."
  },
  AvgDialog_131208_Content_14 = {Text = "Boring."},
  AvgDialog_131208_Content_15 = {
    Text = "Arachne rolls her eyes. She extends her free hand, catching the sunlight in her palm."
  },
  AvgDialog_131208_Content_16 = {
    Text = "I love every season, especially spring. It's been so long since we left the house... should we find time to go hiking?"
  },
  AvgDialog_131208_Content_17 = {
    Text = "Beside the estate where I was born, there is a beautifully tended garden. I know you would love it."
  },
  AvgDialog_131208_Content_18 = {
    Text = "You have waited for three days, my lady. It is time to decide."
  },
  AvgDialog_131208_Content_19 = {
    Text = "The maid carries out her duty. Her cold words fall like a chilling rain, extinguishing the brilliant spring within Arachne's eyes."
  },
  AvgDialog_131208_Content_2 = {
    Text = "Creak—creak—the Goddess of Fate turns Her spinning wheel."
  },
  AvgDialog_131208_Content_20 = {
    Text = "Creak, creak..."
  },
  AvgDialog_131208_Content_21 = {
    Text = "After a brief pause, the spinning wheel resumes its rotation. Its rhythm is gentle, crisp, and eternal."
  },
  AvgDialog_131208_Content_22 = {
    Text = "Our land has only just emerged from a century of war. People have rebuilt their cities upon the ruins. A long, lasting peace awaits them."
  },
  AvgDialog_131208_Content_23 = {
    Text = "Look, over there..."
  },
  AvgDialog_131208_Content_24 = {
    Text = "Following Arachne's gaze, the maid looks toward a massive painting in the hall. She has never been able to make sense of it."
  },
  AvgDialog_131208_Content_25 = {
    Text = "Of all Mr. Zoss's masterpieces, this one goes unnoticed, yet it is my favorite."
  },
  AvgDialog_131208_Content_26 = {
    Text = "These deer, painted in ochre and geometric forms... even as abstract symbols, they pulse with life."
  },
  AvgDialog_131208_Content_27 = {
    Text = "Every time I see it, I'm reminded of my favorite play..."
  },
  AvgDialog_131208_Content_28 = {
    Text = "The rift has existed for three days. The fate of this dimension has already been tainted by the Gaze of that deity."
  },
  AvgDialog_131208_Content_29 = {
    Text = "If this continues, the destruction wrought by Its stare will not stop at our borders."
  },
  AvgDialog_131208_Content_3 = {
    Text = "Creak—creak—the Threads of Fate converge in her hands."
  },
  AvgDialog_131208_Content_30 = {
    Text = "Creak, creak."
  },
  AvgDialog_131208_Content_31 = {
    Text = "The girl closes her eyes, basking in the warmth. The room falls into silence, save for the eternal whir of the wheel."
  },
  AvgDialog_131208_Content_32 = {
    Text = "Do you remember how many worlds' fates we have woven?"
  },
  AvgDialog_131208_Content_33 = {
    Text = "Twenty-seven in total, my lady."
  },
  AvgDialog_131208_Content_34 = {
    Text = "After Father gave me this wheel, I followed its threads to the Gate of Truth. Beyond that Gate, I glimpsed the fate that awaits this world."
  },
  AvgDialog_131208_Content_35 = {
    Text = "I know what lies ahead. I know the choice I must make... but I can't bring myself to do it."
  },
  AvgDialog_131208_Content_36 = {
    Text = "Family. Friends. Memories. Seventeen thousand years of grand history. Technology and art as countless as the stars..."
  },
  AvgDialog_131208_Content_37 = {
    Text = "After seeing the truth, I began to weave the fate of this world... I believed that because Fate granted me this power, I had to do something for my people."
  },
  AvgDialog_131208_Content_38 = {
    Text = "This is my home. My child. <Shake:I... I can't do it>, Rea..."
  },
  AvgDialog_131208_Content_39 = {Text = "My lady..."},
  AvgDialog_131208_Content_4 = {
    Text = "The puppets march in line, stepping into the Great Web."
  },
  AvgDialog_131208_Content_40 = {
    Text = "The maid kneels and brushes away her master's tears. In the spring sunlight, her voice is clear and resolute."
  },
  AvgDialog_131208_Content_41 = {
    Text = "You foresaw this day. That is why you made me your maid."
  },
  AvgDialog_131208_Content_42 = {
    Text = "The entire purpose of my existence is to tell you, in this moment, what must be done."
  },
  AvgDialog_131208_Content_43 = {
    Text = "You are the Master of Fate, the Guardian of the Dimensions. It is a cruel path, but you have already made your choice."
  },
  AvgDialog_131208_Content_44 = {
    Text = "The three Fates are responsible for weaving, measuring... and cutting."
  },
  AvgDialog_131208_Content_45 = {
    Text = "From the moment you chose this, these became your sacred duties."
  },
  AvgDialog_131208_Content_46 = {
    Text = "Arachne looks up. In her unfocused eyes, a rift invisible to mortals flickers at the edge of the sky. It sits beside the warm sun like a cruel, jagged smile."
  },
  AvgDialog_131208_Content_47 = {
    Text = "The rift whispers to her, telling of cold futures. She accepted this curse long ago, yet now that the moment has arrived, she trembles with terror."
  },
  AvgDialog_131208_Content_48 = {
    Text = "Arachne sits back at her loom. A feverish flush creeps onto her cheeks. She strokes the dense, tangled threads as if caressing a child's face."
  },
  AvgDialog_131208_Content_49 = {
    Text = "In the year 804, before I could even speak, our butler played a piece on the piano. Elychion's <Italic:\"Funeral of the Lahosse River.\"> The music was like a fountain flowing outside a temple. I saw even the gods stop to listen..."
  },
  AvgDialog_131208_Content_5 = {
    Text = "They dance. They sing. Creak—creak—"
  },
  AvgDialog_131208_Content_50 = {
    Text = "She snips a single thread. It drifts into the air, swaying silently in the ripples of Fate."
  },
  AvgDialog_131208_Content_51 = {
    Text = "The music in the hall dies, though the phonograph continues to spin. The grooves on the record vanish; the elegant cursive of the song title is erased."
  },
  AvgDialog_131208_Content_52 = {
    Text = "Elychion meets a different fate. In this desolate world, his magnificent life never happened."
  },
  AvgDialog_131208_Content_53 = {
    Text = "Cassandra... the cathedrals she designed was more worthy of worship than the gods within it..."
  },
  AvgDialog_131208_Content_54 = {
    Text = "Another thread snaps. Miles away, a magnificent cathedral crumbles. The compassionate eyes of a divine statue shatter, becoming indistinguishable from the dust."
  },
  AvgDialog_131208_Content_55 = {
    Text = "Mornlin's fairy tales, Aldo's operas, Marmo's paintings, Rovell's poetry..."
  },
  AvgDialog_131208_Content_56 = {
    Text = "Books turn to scrap paper; sculptures shatter; paintings dissolve into chaotic swirls of color."
  },
  AvgDialog_131208_Content_57 = {
    Text = "She is the Record Keeper. She is the Executioner. She recites the names of every great artist, severing their threads one by one."
  },
  AvgDialog_131208_Content_58 = {
    Text = "St. Vildburg, a grand city of heroes. It weathered a hundred battles, faced destruction and rebirth thirty-seven times, and saw twenty-one great rulers rise to glory and fall into ruin."
  },
  AvgDialog_131208_Content_59 = {
    Text = "Nobles celebrate here; the poor wail in agony; poets leave behind elegant verses. Along the Nevrich River, the echo of song and cannon fire rings through the air. Today, its heroic history ends."
  },
  AvgDialog_131208_Content_6 = {
    Text = "Sunlight bathes their faces. How joyful they are!"
  },
  AvgDialog_131208_Content_60 = {
    Text = "A cluster of severed threads drifts in a frenzied dance. 2,300 kilometers away, that magnificent city collapses in a thunderous ruin."
  },
  AvgDialog_131208_Content_61 = {
    Text = "Seventeen thousand years of endurance... an ancient civilization that survived every disaster, now falling..."
  },
  AvgDialog_131208_Content_62 = {
    Text = "Weak and trembling, Arachne summons her last ounce of strength to grasp the endless threads before her."
  },
  AvgDialog_131208_Content_63 = {
    Text = "The threads snap. 8,000 kilometers away, a vast ancient empire—the unbroken bearer of human civilization—vanishes from the scrolls of history like a wisp of smoke."
  },
  AvgDialog_131208_Content_64 = {Text = "..."},
  AvgDialog_131208_Content_65 = {
    Text = "People. Art. Cities. Nations. Civilization."
  },
  AvgDialog_131208_Content_66 = {
    Text = "Everything is collapsing. Everything is disappearing."
  },
  AvgDialog_131208_Content_67 = {
    Text = "Do you see, Rea? My first child is dead... I killed her with my own hands."
  },
  AvgDialog_131208_Content_68 = {
    Text = "Tears fall in silence. Arachne smiles weakly, gazing out the window. Amidst the ruins of the world, only the crumbling manor outside remains standing."
  },
  AvgDialog_131208_Content_69 = {
    Text = "I thought that if I could keep watch over the place I once lived, I wouldn't feel so alone."
  },
  AvgDialog_131208_Content_7 = {
    Text = "Creak, creak."
  },
  AvgDialog_131208_Content_70 = {
    Text = "How childish... for an executioner with no choice, I have only prepared the cruelest punishment for myself."
  },
  AvgDialog_131208_Content_71 = {
    Text = "She reaches out, plucking a faint, misty thread from above her own head—one she cannot clearly see—and connects a portion of it to the last remaining thread of this world."
  },
  AvgDialog_131208_Content_72 = {
    Text = "My lady, what are you...?"
  },
  AvgDialog_131208_Content_73 = {
    Text = "Romance brings foolishness. Kindness brings fragility. Memories only bring pain."
  },
  AvgDialog_131208_Content_74 = {
    Text = "I've made up my mind, Rea. I am a cursed executioner; beauty has no place within me."
  },
  AvgDialog_131208_Content_75 = {
    Text = "You are... going to snuff out a part of yourself? But these are the pieces you cherish most—how can you..."
  },
  AvgDialog_131208_Content_76 = {
    Text = "When I was very young, I had my first dream."
  },
  AvgDialog_131208_Content_77 = {
    Text = "Arachne reaches out, catching the light that shines upon the endless ruins."
  },
  AvgDialog_131208_Content_78 = {
    Text = "In the dream, I was walking on the surface of a lake. Around me were ruins and withered bones, but beneath the surface, my childhood reflection was walking through a beautiful land."
  },
  AvgDialog_131208_Content_79 = {
    Text = "No death, no suffering, no forgetting. Gentle sunlight shines there forever, and the people sing joyfully by her side."
  },
  AvgDialog_131208_Content_8 = {
    Text = "An ancient spinning wheel hums a gentle accompaniment. A young woman sits before it, murmuring a simple tune."
  },
  AvgDialog_131208_Content_80 = {
    Text = "I cannot see where my threads lead, but I think I understand the destiny foretold by that dream now."
  },
  AvgDialog_131208_Content_81 = {
    Text = "She forces a smile—perhaps for her maid, or perhaps for something else entirely."
  },
  AvgDialog_131208_Content_82 = {
    Text = "Mother once said that if you try to read Arachne backwards, it sounds like \"Nefraea.\" In this world's legends, that is the name of the Goddess of Spring."
  },
  AvgDialog_131208_Content_83 = {
    Text = "I love every season, especially spring. Spring is much smaller than Fate. But Fate leads to death, while spring... spring brings only rebirth."
  },
  AvgDialog_131208_Content_84 = {
    Text = "She stares out the window. On either side of the frame, Fate and Spring share one last glance."
  },
  AvgDialog_131208_Content_85 = {
    Text = "Leave me, my reflection. My dear sister. Take all of our goodness and our beautiful memories with you."
  },
  AvgDialog_131208_Content_86 = {
    Text = "Fate... I offer a part of myself as a total sacrifice to you. I will walk this arduous path in her place."
  },
  AvgDialog_131208_Content_87 = {
    Text = "Arachne gently strokes the tangled threads. They tremble as if struggling, as if crying out."
  },
  AvgDialog_131208_Content_88 = {
    Text = "Her tears fall through the threads and onto the \"Moirae\" plate."
  },
  AvgDialog_131208_Content_89 = {
    Text = "Now I set you free, \"Arachne.\""
  },
  AvgDialog_131208_Content_9 = {
    Text = "A ray of sunlight streams through the window, illuminating a nameplate engraved with \"Moirae\" beside the wheel."
  },
  AvgDialog_131208_Content_90 = {Text = "Creak."},
  AvgDialog_131208_Content_91 = {
    Text = "The thread snaps. In the warm spring light, the spinning wheel lets out a final sigh."
  },
  AvgDialog_131209_Content_1 = {Text = "Reunion"},
  AvgDialog_131209_Content_10 = {
    Text = "If I had chosen to be an opera singer, the lines at the theater would stretch three blocks down the street."
  },
  AvgDialog_131209_Content_11 = {
    Text = "It's a tragedy the puppets of Londinium never witnessed my spectacular performance. In that light, you are a lucky little darling."
  },
  AvgDialog_131209_Content_12 = {
    Text = "Nefraea pinches the girl's cheeks with mock affection, like a mother caressing a beloved daughter."
  },
  AvgDialog_131209_Content_13 = {
    Text = "In the center of the cathedral hall, steel nails drive through the girl's chest, abdomen, shoulders, shins, and palms—piercing every point suited for suspension and the sensing of pain, pinning her firmly to a massive spinning-wheel chandelier."
  },
  AvgDialog_131209_Content_14 = {
    Text = "Nefraea brings a blood-stained hand to her nose and closes her eyes in obsession."
  },
  AvgDialog_131209_Content_15 = {
    Text = "Ah... the scent of lifeblood. So vibrant."
  },
  AvgDialog_131209_Content_16 = {
    Text = "For years, I tried everything—tearing into the bodies of children, even my own flesh—yet I could never taste a single drop of vitality."
  },
  AvgDialog_131209_Content_17 = {
    Text = "The correct destiny. A burning spirit. How enviable... but did you know? You were meant to be tossed into the scrap heap of Fate, just like us."
  },
  AvgDialog_131209_Content_18 = {
    Text = "You have no need for food, and you never speak. Aside from the memories you keep for her, you are nothing and you know nothing."
  },
  AvgDialog_131209_Content_19 = {
    Text = "Fate abandoned you long ago, you poor thing. You are merely a doll she uses for comfort—a gravedigger for her memories, wandering alone across this hollow stage."
  },
  AvgDialog_131209_Content_2 = {
    Text = "<Shake:La... La la...>"
  },
  AvgDialog_131209_Content_20 = {
    Text = "She watches the little girl, who is barely breathing at this point, her voice trembling with a feigned grief as she smooths a stray strand of hair from the girl's temple."
  },
  AvgDialog_131209_Content_21 = {
    Text = "Now, your cruel mother, the Fate, is coming... No matter what happens, meet her as your most beautiful self, won't you?"
  },
  AvgDialog_131209_Content_22 = {Text = "..."},
  AvgDialog_131209_Content_23 = {
    Text = "Once you adjust to the dim light of the church, a set of massive murals catches your eye."
  },
  AvgDialog_131209_Content_24 = {
    Text = "Viscous pigments smear across walls dozens of meters high, stretching into a ceiling of absolute darkness. Towering, sacred, and filthy—like a statue of a savior saint erected in a sewer."
  },
  AvgDialog_131209_Content_25 = {
    Text = "Their considerate hostess has cleared the room, leaving only the echo of your footsteps and breathing. You walk beneath the towering mural and look up."
  },
  AvgDialog_131209_Content_26 = {
    Text = "A woman sits at a spinning wheel, cutting silk threads with scissors... is this a portrait of you, Arachne?"
  },
  AvgDialog_131209_Content_27 = {
    Text = "It certainly appears so. I believe these are the words my sister wishes to convey."
  },
  AvgDialog_131209_Content_28 = {
    Text = "Arachne shows no haste in finding \"Memories.\" Instead, she follows you, studying the murals with quiet interest."
  },
  AvgDialog_131209_Content_29 = {
    Text = "An identical figure leaves the seated woman and falls into the darkness of a cave..."
  },
  AvgDialog_131209_Content_3 = {
    Text = "Creak—creak—the Goddess of Fate turns Her spinning wheel."
  },
  AvgDialog_131209_Content_30 = {
    Text = "In the dark cave, a woman and other creatures of the night perform a strange dance. She holds... a spinning wheel?"
  },
  AvgDialog_131209_Content_31 = {
    Text = "The center glows like a Lantern, illuminating the shadows."
  },
  AvgDialog_131209_Content_32 = {
    Text = "A woman carrying a Lantern shaped like a spinning wheel arrives in a city... a group of robed figures kneels before her. The sigil on their clothes... is that the Lightbearer's sigil?!"
  },
  AvgDialog_131209_Content_33 = {
    Text = "It differs slightly from the sigils you've seen before—around that sinister inverted triangle sits an additional ring, like a spinning wheel."
  },
  AvgDialog_131209_Content_34 = {
    Text = "But you recognize the elements. You know exactly what it is. This is the birth of the Church of the Lightbearers."
  },
  AvgDialog_131209_Content_35 = {
    Text = "The last one..."
  },
  AvgDialog_131209_Content_36 = {
    Text = "The final mural stands at the end of the corridor like a gate sealing off Fate. Grimy paint ripples across the surface, reflecting the murky shadows of the chapel."
  },
  AvgDialog_131209_Content_37 = {
    Text = "A woman holds a Lantern, kneeling before a blurred figure. Behind them looms something enormous..."
  },
  AvgDialog_131209_Content_38 = {Text = "Urgh..."},
  AvgDialog_131209_Content_39 = {
    Text = "As you recognize that massive, lidded eyeball, a violent sting surges through you, stirring turbulent waves in your mind."
  },
  AvgDialog_131209_Content_4 = {
    Text = "Creak—creak—the Threads of Fate converge in her hands."
  },
  AvgDialog_131209_Content_40 = {
    Text = "You quickly look away and take a deep breath to steady the rising tide of nausea."
  },
  AvgDialog_131209_Content_41 = {
    Text = "<Shake:Huff... huff...> The Lightbearers... Tohuwabohu..."
  },
  AvgDialog_131209_Content_42 = {
    Text = "In this dimension, Nefraea was actually... the Church of the Lightbearers' founder!"
  },
  AvgDialog_131209_Content_43 = {
    Text = "I see now. I understand!..."
  },
  AvgDialog_131209_Content_44 = {
    Text = "You have seen the truth, {Male=Mr.,Female=Miss} Keeper. As the Supreme Deity neared its awakening, my abandoned sister escaped from the Abyssal Prison."
  },
  AvgDialog_131209_Content_45 = {
    Text = "Her interference clouded my vision, allowing her to hide this cult beneath my stage."
  },
  AvgDialog_131209_Content_46 = {
    Text = "The one she revered was the Apostle—the one connected to that Supreme Deity in this dimension."
  },
  AvgDialog_131209_Content_47 = {
    Text = "You look again at the blurred dark figure on the mural, the one drawn next to Tohuwabohu."
  },
  AvgDialog_131209_Content_48 = {
    Text = "I understand... Nefraea wants to use the Apostle's power to re-establish a link with Tohuwabohu!"
  },
  AvgDialog_131209_Content_49 = {
    Text = "But if that's the case, why hunt the Puppets...?"
  },
  AvgDialog_131209_Content_5 = {
    Text = "The puppets march in line, stepping into the Great Web."
  },
  AvgDialog_131209_Content_50 = {Text = "CLANG—"},
  AvgDialog_131209_Content_51 = {
    Text = "A murky toll rings out from the bell tower. A filthy divine oracle."
  },
  AvgDialog_131209_Content_52 = {
    Text = "The cathedral rumbles with a low roar. Amidst the heavy tremors, the stone walls bearing the murals grind upward."
  },
  AvgDialog_131209_Content_53 = {Text = "There!!"},
  AvgDialog_131209_Content_54 = {
    Text = "Lady... Arachne..."
  },
  AvgDialog_131209_Content_55 = {
    Text = "Oh my... our little \"Memories.\" Your voice is so weak, it's almost pitiful."
  },
  AvgDialog_131209_Content_56 = {
    Text = "Nefraea! Let her go!"
  },
  AvgDialog_131209_Content_57 = {
    Text = "The girl's small frame hangs from the grand spinning-wheel chandelier. Crimson blood seeps across the white marble floor."
  },
  AvgDialog_131209_Content_58 = {
    Text = "Bright lights shine from behind her, casting a holy silhouette around her blood-soaked body."
  },
  AvgDialog_131209_Content_59 = {
    Text = "Nefraea, end this pointless conflict. Release her."
  },
  AvgDialog_131209_Content_6 = {
    Text = "They dance. They sing. Creak—creak—"
  },
  AvgDialog_131209_Content_60 = {
    Text = "Oh? Our Goddess of Fate suddenly cares for her \"Memories\" now?"
  },
  AvgDialog_131209_Content_61 = {
    Text = "You never cared. You abandoned them, Arachne."
  },
  AvgDialog_131209_Content_62 = {
    Text = "Nefraea, I know you want to summon the Apostle and wake Tohuwabohu... we can find another way. There's no need to kill them."
  },
  AvgDialog_131209_Content_63 = {
    Text = "The way you stall for time is adorably childish, %player%."
  },
  AvgDialog_131209_Content_64 = {
    Text = "You understand nothing. I never killed them. I am simply bringing them home."
  },
  AvgDialog_131209_Content_65 = {
    Text = "I brought you here only so you could witness their perfect ending together."
  },
  AvgDialog_131209_Content_66 = {
    Text = "Act Two, Scene Three. I call it... \"Happy Reunion.\""
  },
  AvgDialog_131209_Content_67 = {
    Text = "Nefraea shoots you a contemptuous look. Her nail grazes Memories' cheek, leaving a thin trail of red."
  },
  AvgDialog_131209_Content_68 = {
    Text = "She leans down, watching the girl's trembling face with a predatory tenderness."
  },
  AvgDialog_131209_Content_69 = {
    Text = "Good girl, don't be afraid. We'll be home soon."
  },
  AvgDialog_131209_Content_7 = {
    Text = "They die with the Great Web, silent and without a trace."
  },
  AvgDialog_131209_Content_70 = {
    Text = "Say goodbye to your wretched memories, dear sister!"
  },
  AvgDialog_131209_Content_71 = {
    Text = "Stop... Nefraea!"
  },
  AvgDialog_131209_Content_72 = {Text = "Snap—"},
  AvgDialog_131209_Content_73 = {
    Text = "With a sharp snap of Nefraea's fingers, the little girl's body explodes like a vivid crimson firework."
  },
  AvgDialog_131209_Content_74 = {
    Text = "The Lantern's light catches the spray, casting a blood-red flower across the mural."
  },
  AvgDialog_131209_Content_75 = {
    Text = "Droplets of blood fly into the air, hover, and then reverse course, greedily surging toward Nefraea and staining every inch of her skin."
  },
  AvgDialog_131209_Content_76 = {
    Text = "The gore seeps into her clothes and flesh, flooding her veins and rushing through her slender frame."
  },
  AvgDialog_131209_Content_77 = {
    Text = "Nefraea licks the blood from her lips and spreads her arms wide, like a gracious lady welcoming a loved one home."
  },
  AvgDialog_131209_Content_78 = {
    Text = "Welcome home, darling."
  },
  AvgDialog_131209_Content_79 = {Text = "STOP!!"},
  AvgDialog_131209_Content_8 = {
    Text = "The song echoes through the cavernous church. Nefraea spreads her arms wide, savoring the sound of her own voice."
  },
  AvgDialog_131209_Content_80 = {
    Text = "The moment that small body shatters, silver light blooms from your hands as you charge toward Nefraea."
  },
  AvgDialog_131209_Content_81 = {
    Text = "Under the sacred, bloody light, countless shadows stretch out from the grimy murals to block your path..."
  },
  AvgDialog_131209_Content_9 = {
    Text = "Well? Was I in tune?"
  },
  AvgDialog_131210_Content_1 = {
    Text = "I didn't expect you to look so pathetic the next time we met."
  },
  AvgDialog_131210_Content_2 = {Text = "Thais..."},
  AvgDialog_131210_Content_3 = {
    Text = "Tawil is right. It's okay, Keeper."
  },
  AvgDialog_131210_Content_4 = {
    Text = "You promised to show me another ending. I believe in you, now and always."
  },
  AvgDialog_131210_Content_5 = {
    Text = "Whether you stop here or move past me, I am always by your side."
  },
  AvgDialog_131211_Content_1 = {Text = "Cocoon"},
  AvgDialog_131211_Content_10 = {
    Text = "I never want to experience that a second time..."
  },
  AvgDialog_131211_Content_11 = {
    Text = "You aren't sure if you truly mean that. You clench your fist, readjusting to the body you just shared with \"N\"."
  },
  AvgDialog_131211_Content_12 = {
    Text = "Your vision clears. Rubbing your throbbing head, you walk toward the frail figure kneeling at the edge of the stage."
  },
  AvgDialog_131211_Content_13 = {
    Text = "Nefraea, your plan has already—"
  },
  AvgDialog_131211_Content_14 = {Text = "Careful."},
  AvgDialog_131211_Content_16 = {
    Text = "As if a thread pulls you, your pace slows. A sharp black spider claw shears through the air, grazing dangerously close to your eyes."
  },
  AvgDialog_131211_Content_17 = {
    Text = "Eight massive venomous limbs tear through her clothing along her spine, thrashing and twisting in the air. Nefraea seems utterly indifferent to them."
  },
  AvgDialog_131211_Content_18 = {
    Text = "Fragments of the dimensional passage flutter around her like falling confetti. Her tears fall, dampening the dark, broken wheel in her hands. Its light is gone."
  },
  AvgDialog_131211_Content_19 = {
    Text = "The portal has vanished. You have no more chances."
  },
  AvgDialog_131211_Content_2 = {Text = "...Keep..."},
  AvgDialog_131211_Content_20 = {
    Text = "Fate walks its intended path, Nefraea. Accept it."
  },
  AvgDialog_131211_Content_21 = {
    Text = "Chance? Heh... hahaha!"
  },
  AvgDialog_131211_Content_22 = {
    Text = "Her frail body trembles with laughter, her venomous limbs carving harrowing trails through the air."
  },
  AvgDialog_131211_Content_23 = {
    Text = "I never had a chance, nor did I need one."
  },
  AvgDialog_131211_Content_24 = {
    Text = "Freedom, childhood, family, love, identity... Fate stole everything from us. I will never, ever be its prisoner like you."
  },
  AvgDialog_131211_Content_25 = {
    Text = "Nefraea slowly rises, positioning herself within the dim, shattered spinning wheel."
  },
  AvgDialog_131211_Content_26 = {
    Text = "Watch closely, Arachne! I will do what you desperately craved but never dared!"
  },
  AvgDialog_131211_Content_27 = {
    Text = "With an enraged roar, Nefraea's body is pierced by countless spikes. Blood pours from her wounds, connecting to the broken wheel like a gory web."
  },
  AvgDialog_131211_Content_28 = {
    Text = "<Shake:@2—!>"
  },
  AvgDialog_131211_Content_29 = {
    Text = "A high-frequency shriek beyond human endurance erupts from Nefraea. Her body tremors in agony as dark purple veins bulge across her skin."
  },
  AvgDialog_131211_Content_3 = {
    Text = "{Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131211_Content_30 = {
    Text = "The shards of the dimensional passage stop drifting, drawn toward the web of blood. The dark wheel reignites with a grim, blood-soaked radiance."
  },
  AvgDialog_131211_Content_31 = {
    Text = "Heh... Hahaha! <Big:<Shake:If there are no gods, I will become one!>>"
  },
  AvgDialog_131211_Content_32 = {
    Text = "My story... my stage... will never end! I will bring liberation to this web that should never have existed... <Big:<Shake:<Red:liberation!!!>>>"
  },
  AvgDialog_131211_Content_33 = {
    Text = "In Nefraea's agonized shriek, the entire Theater of Fate shakes violently. Puppets topple and collide, their strings tangling into a disheveled mess."
  },
  AvgDialog_131211_Content_34 = {
    Text = "Arachne watches her being consumed by power and madness. Sorrow ripples in her deep eyes, just like the day she first cut a piece of herself away."
  },
  AvgDialog_131211_Content_35 = {
    Text = "I tried to free you from this curse... I was wrong, Nefraea."
  },
  AvgDialog_131211_Content_36 = {
    Text = "The curse is inescapable. This cage... we can never leave."
  },
  AvgDialog_131211_Content_37 = {
    Text = "Those fragments... that wheel!"
  },
  AvgDialog_131211_Content_38 = {
    Text = "Nefraea is absorbing the residual power of the passage! She is turning herself into the Wick!"
  },
  AvgDialog_131211_Content_39 = {
    Text = "A faint sigh echoes through the trembling theater."
  },
  AvgDialog_131211_Content_4 = {
    Text = "<Shake:Ugh... cough, cough...>"
  },
  AvgDialog_131211_Content_40 = {
    Text = "Hold on tight, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131211_Content_41 = {Text = "Wh..."},
  AvgDialog_131211_Content_42 = {
    Text = "<Shake:Boom—>"
  },
  AvgDialog_131211_Content_43 = {
    Text = "Before her words could even fade, the entire theater tears apart. Nefraea rips at the Threads of Fate. Through the horrific rift, the city's buildings and dimensional debris tangle together."
  },
  AvgDialog_131211_Content_44 = {
    Text = "The main stage shatters. Shards of the past, future, and present intertwine in chaos across the broken stage, forming an incomprehensible scene."
  },
  AvgDialog_131211_Content_45 = {
    Text = "Arachne... your web!"
  },
  AvgDialog_131211_Content_46 = {
    Text = "Arachne's wheel spins at a furious pace. Vast Dimensional Embers surge from her, flowing along the threads to mend the shattered voids in the Great Web, barely holding the stage together."
  },
  AvgDialog_131211_Content_47 = {
    Text = "Guided by the threads, you struggle to your feet."
  },
  AvgDialog_131211_Content_48 = {
    Text = "You are absorbing Its scattered power to alter the course of Fate... but you are not a fragment of Tohuwabohu. You cannot bear this pressure. You do not have to die in such agony, Nefraea."
  },
  AvgDialog_131211_Content_49 = {
    Text = "Agony? No, I'm thrilled, sister! I dreamed of this every second in the Abyssal Prison."
  },
  AvgDialog_131211_Content_5 = {
    Text = "What happened..."
  },
  AvgDialog_131211_Content_50 = {
    Text = "This fantasy is the only thing that kept me alive!"
  },
  AvgDialog_131211_Content_51 = {
    Text = "Nefraea's manic laughter rings through the shattered space. She lifts her head, greedily absorbing the dim remnants of light."
  },
  AvgDialog_131211_Content_52 = {
    Text = "A sleeping god, a stolen fate... it doesn't matter! If the god will not bless us, I will do it in Its place!"
  },
  AvgDialog_131211_Content_53 = {
    Text = "Avengers of Fate, take the stage! <Red:This act belongs to you!>"
  },
  AvgDialog_131211_Content_54 = {
    Text = "Nefraea raises her hand. Endless black sludge surges from her body, weaving a dark web across the theater's void."
  },
  AvgDialog_131211_Content_55 = {
    Text = "Countless grudges, once cast aside by Fate, take physical form. They crawl along the massive web in an overwhelming tide, surging toward you."
  },
  AvgDialog_131211_Content_56 = {
    Text = "Arachne, our bodies...!!"
  },
  AvgDialog_131211_Content_57 = {
    Text = "You discover a black thread, barely visible, emerging from Arachne's frame."
  },
  AvgDialog_131211_Content_58 = {
    Text = "You look up to find a similar black strand extending from yourself, from every stage, and from every puppet. They all lead to the spindle in Nefraea's hands."
  },
  AvgDialog_131211_Content_59 = {
    Text = "Ave, Arachne! Blessed be, the Goddess of Fate!"
  },
  AvgDialog_131211_Content_6 = {
    Text = "Intense vertigo and stomach spasms are the wreckage Rapture left behind. You fight back the nausea and slowly pull yourself up."
  },
  AvgDialog_131211_Content_60 = {
    Text = "Draw your blades, soldiers! Fight for our destiny!"
  },
  AvgDialog_131211_Content_61 = {
    Text = "Miss Arachne, accept your fate... cease this futile resistance."
  },
  AvgDialog_131211_Content_62 = {
    Text = "Do not worry, darling. Your liberation is coming soon. Very soon..."
  },
  AvgDialog_131211_Content_63 = {
    Text = "Arachne closes her eyes. Her hands tremble as she grips her threads in agony."
  },
  AvgDialog_131211_Content_64 = {
    Text = "Arachne closes her eyes. Her hands tremble as she grips her threads in agony."
  },
  AvgDialog_131211_Content_65 = {
    Text = "Nefraea, they cannot help you become the deity you seek. By doing this, you only condemn them to another cycle of agonizing destruction."
  },
  AvgDialog_131211_Content_66 = {
    Text = "What does it matter? We seek nothing but vengeance! Is that not right, my fellow forsaken children of Fate?"
  },
  AvgDialog_131211_Content_67 = {
    Text = "<Shake:Heh... hahaha!>"
  },
  AvgDialog_131211_Content_68 = {
    Text = "Sharp, booming, and soul-piercing laughter erupts from the endless black webs—a chorus of pure agony."
  },
  AvgDialog_131211_Content_69 = {
    Text = "The Abandoned Fates howl and wail, forming a wall of shadow before Nefraea."
  },
  AvgDialog_131211_Content_7 = {
    Text = "The Apostle's consciousness has left the spindle. Severed from the Divine, it is now utterly destroyed. The Aeons' Authority has calmed."
  },
  AvgDialog_131211_Content_70 = {
    Text = "The gates of the Abyss stand wide. Behold, Arachne! Behold the destinies you forged with your own hands! Look upon your beloved children!"
  },
  AvgDialog_131211_Content_71 = {
    Text = "See their agony, their despair... look at them, and then, kill them once more!"
  },
  AvgDialog_131211_Content_72 = {
    Text = "Watch as every Thread of Fate spins and shatters in my palms! Witness my ascension! I am the god who brings the end!"
  },
  AvgDialog_131211_Content_73 = {
    Text = "Dimensional shards, heavy with divine power and manic will, pierce Nefraea's flesh one by one. Lifeblood pours into her wheel without end. Her face contorts in agony, yet her laughter only grows more frenzied."
  },
  AvgDialog_131211_Content_74 = {
    Text = "She watches the ruined stage with eager anticipation, like a playwright awaiting the debut of her masterpiece."
  },
  AvgDialog_131211_Content_75 = {
    Text = "The Abyss has manifest upon this stage... Nefraea is sacrificing her very existence."
  },
  AvgDialog_131211_Content_76 = {
    Text = "She intends to turn every soul here into her puppets. She seeks to become that god. She seeks to become Fate itself."
  },
  AvgDialog_131211_Content_77 = {
    Text = "Arachne speaks with the detached calm of a spectator who has never truly entered the play. Reclaimed Dimensional Embers drift around her fingertips like endless, shifting sand."
  },
  AvgDialog_131211_Content_78 = {
    Text = "Her wheel groans as it turns, struggling to preserve the destinies Nefraea seeks to unmake. She fights to prevent the black threads from converging in her sister's grasp."
  },
  AvgDialog_131211_Content_79 = {
    Text = "My embers have returned. I no longer have reason to hesitate."
  },
  AvgDialog_131211_Content_8 = {
    Text = "You put on a magnificent performance."
  },
  AvgDialog_131211_Content_80 = {
    Text = "Help me reach her. I will stop Nefraea's wheel. Together, we shall correct this broken destiny."
  },
  AvgDialog_131211_Content_81 = {
    Text = "Please help me, get as close to her as you can. Nephreya's spinning wheel will stop turning, and I will correct this flawed fate together with you."
  },
  AvgDialog_131211_Content_82 = {
    Text = "Please help me... bring relief to these abandoned fates."
  },
  AvgDialog_131211_Content_9 = {
    Text = "Phew... I can't believe those words actually came out of my mouth."
  },
  AvgDialog_131212_Content_1 = {
    Text = "Meanwhile, across the city..."
  },
  AvgDialog_131212_Content_10 = {
    Text = "Number six was handpicked from the Duke's own stables. He's taking the cup, mark my words. Put everything on six!"
  },
  AvgDialog_131212_Content_11 = {
    Text = "The subway chatter flows like a babbling stream. Arachne stares quietly at the lights rushing past the window, smiling as she listens to her puppets discuss plays, horse races, and weddings."
  },
  AvgDialog_131212_Content_12 = {
    Text = "She turns her spindle in silence. Amidst the billions of intricate threads, she savors this fleeting moment of peace."
  },
  AvgDialog_131212_Content_13 = {
    Text = "My lady, we are nearing our stop. The carriage is ready, and our sisters await you at the transfer point."
  },
  AvgDialog_131212_Content_14 = {Text = "Good girl."},
  AvgDialog_131212_Content_15 = {
    Text = "She scans the puppets still immersed in their performances, looking like a spectator who cannot bear to leave her seat."
  },
  AvgDialog_131212_Content_16 = {
    Text = "Do you remember how long it has been since we last left the theater?"
  },
  AvgDialog_131212_Content_17 = {
    Text = "I have been by your side since the day I became a Leng Spider. Fifty years? Sixty? I've lost count."
  },
  AvgDialog_131212_Content_18 = {
    Text = "But we have been away from the theater for quite a while this time."
  },
  AvgDialog_131212_Content_19 = {
    Text = "I have Nefraea to thank for that. Were it not for her arrival, I would never have had the chance to linger outside for so long."
  },
  AvgDialog_131212_Content_2 = {
    Text = "Ticket, please. Sir, may I see your ticket?"
  },
  AvgDialog_131212_Content_20 = {
    Text = "We've hunted hundreds of Abyssal squires alongside the Keeper. Once we rescue \"Memories,\" it will be time to go home."
  },
  AvgDialog_131212_Content_21 = {
    Text = "Who knows when we will have such an opportunity again..."
  },
  AvgDialog_131212_Content_22 = {
    Text = "As if sensing her thoughts, the subway lights dim. She stares into the darkness, searching through the rising and falling memories of a thousand civilizations for a few ordinary traces of herself."
  },
  AvgDialog_131212_Content_23 = {
    Text = "Two seconds tick by. The master of the city notices that the lively chatter vanishes the instant the train plunges into total darkness."
  },
  AvgDialog_131212_Content_24 = {
    Text = "My lady, something is..."
  },
  AvgDialog_131212_Content_25 = {Text = "CRACK—"},
  AvgDialog_131212_Content_26 = {
    Text = "The maid's icy blood splatters across Arachne's calm face, carrying the delicate fragrance of irises."
  },
  AvgDialog_131212_Content_27 = {
    Text = "The lights flicker back on. Arachne sees her maid's severed body and the blade that passed through her, still driving forward. Behind the steel, the puppets surge toward her like a pack of starving beasts."
  },
  AvgDialog_131212_Content_28 = {Text = "..."},
  AvgDialog_131212_Content_29 = {
    Text = "The brakes groan with a weary metallic shriek. The resulting breeze stirs the hair of another maid."
  },
  AvgDialog_131212_Content_3 = {
    Text = "Didn't they just check it at the gate? This is exactly how the taxpayers' money is squandered..."
  },
  AvgDialog_131212_Content_30 = {
    Text = "Ah! We're here!"
  },
  AvgDialog_131212_Content_31 = {
    Text = "The doors slide open, but no crowd emerges. Only a thick, metallic stream of blood seeps through the cracks, flowing in a silent ensemble."
  },
  AvgDialog_131212_Content_32 = {
    Text = "Treading upon the river of gore, Arachne steps out. Her robes remain spotless; her spindle continues to turn, never ceasing."
  },
  AvgDialog_131212_Content_33 = {Text = "This is..."},
  AvgDialog_131212_Content_34 = {
    Text = "A fascinating piece of interactive theater. As both audience and actor, the experience is far more vivid than that of a playwright."
  },
  AvgDialog_131212_Content_35 = {
    Text = "She looks at the maid before her, her expression unreadable."
  },
  AvgDialog_131212_Content_36 = {
    Text = "My maids have been with me for many years. I rarely touch the threads of their fates."
  },
  AvgDialog_131212_Content_37 = {
    Text = "In that dull theater, they were among the few vibrant souls."
  },
  AvgDialog_131212_Content_38 = {
    Text = "You murdered two of my maids today. Such a violation of Fate comes with a price, Nefraea."
  },
  AvgDialog_131212_Content_39 = {
    Text = "Heh... hahaha! How noble of you, Arachne."
  },
  AvgDialog_131212_Content_4 = {
    Text = "Charlie! Where is my brooch?"
  },
  AvgDialog_131212_Content_40 = {
    Text = "Like butter dropped into a scorching pan, the maid's body melts. Beneath the boiling black sludge, a face identical to Arachne's laughs with unbridled joy."
  },
  AvgDialog_131212_Content_41 = {
    Text = "<Italic:\"Behold! I am the master of Fate, the dutiful executioner! I shall choose the righteous paths and cast every error into the abyss!\">"
  },
  AvgDialog_131212_Content_42 = {
    Text = "You are my idol, my faith, dear sister. I am simply playing your role."
  },
  AvgDialog_131212_Content_43 = {
    Text = "Well? Have I been a worthy student?"
  },
  AvgDialog_131212_Content_44 = {
    Text = "Arachne quietly meets Nefraea's stare. The eyes looking back are bright and full of anticipation, like a little girl waiting for her beloved sister's praise."
  },
  AvgDialog_131212_Content_45 = {
    Text = "Platforms, stairwells, colonnades... as she speaks, shadows manifest in every corner of the station."
  },
  AvgDialog_131212_Content_46 = {
    Text = "Their murky auras intertwine, converging in Nefraea's hands like a vast net tightening around Arachne."
  },
  AvgDialog_131212_Content_47 = {
    Text = "Arachne's lips curl into a gentle smile."
  },
  AvgDialog_131212_Content_48 = {
    Text = "I never imagined anyone would try to trap <Italic:me> in a net."
  },
  AvgDialog_131212_Content_49 = {
    Text = "Have you seen a silkworm, sister? They spend their lives doing nothing but eating and spinning silk... and then they wait for the very cocoons they wove to smother them."
  },
  AvgDialog_131212_Content_5 = {
    Text = "Didn't I pin it to your dress before we left?"
  },
  AvgDialog_131212_Content_50 = {
    Text = "Nearly all of your squires have perished in the corners of this city and upon this train. They were your only companions during those long years in the void."
  },
  AvgDialog_131212_Content_51 = {
    Text = "You gave them an ending they were never meant to have. Fate cannot be defied, Nefraea."
  },
  AvgDialog_131212_Content_52 = {
    Text = "You mean their \"correct\" fate was to rot in that dark prison for all eternity? Is that right, esteemed Master of Fate?"
  },
  AvgDialog_131212_Content_53 = {
    Text = "Nefraea shakes her head with a scornful laugh."
  },
  AvgDialog_131212_Content_54 = {
    Text = "I love them more than you can imagine. And they told me that if death could spare them from being imprisoned again, they would embrace it without hesitation."
  },
  AvgDialog_131212_Content_55 = {
    Text = "After this massacre in the tunnels, how many embers do you have left to mend the damage?"
  },
  AvgDialog_131212_Content_56 = {
    Text = "Nefraea flaunts the black spindle in her hand. Countless threads from the city's stage are connected to the motionless wheel."
  },
  AvgDialog_131212_Content_57 = {
    Text = "The threads of this city are in my hands. I can't manipulate them... which is a shame, really, as I'm missing out on so much fun..."
  },
  AvgDialog_131212_Content_58 = {
    Text = "Luckily, while repairing them costs you your precious embers, polluting them costs me nothing."
  },
  AvgDialog_131212_Content_59 = {
    Text = "If I simply let go... your theater and your stage will become the perfect breeding ground for Chaos. Just like the hole where I spent my life."
  },
  AvgDialog_131212_Content_6 = {
    Text = "Oh, heavens... I spent a month preparing for today! Without that brooch, this gown is little more than a burial shroud..."
  },
  AvgDialog_131212_Content_60 = {
    Text = "And you will have to watch it happen. Powerless to change it. Powerless to resist."
  },
  AvgDialog_131212_Content_61 = {
    Text = "Nefraea steps up to Arachne and gently caresses her face."
  },
  AvgDialog_131212_Content_62 = {
    Text = "What shall it be, dear sister? Will you obey me, or shall we watch this world turn into a living hell together?"
  },
  AvgDialog_131212_Content_63 = {
    Text = "You are an incomplete piece of Fate. To pollute an entire city... you lack the—"
  },
  AvgDialog_131212_Content_64 = {
    Text = "The snap of a silk thread echoes in Arachne's ear. She looks up, her eyes filled with a spectator's sorrow."
  },
  AvgDialog_131212_Content_65 = {
    Text = "...You just killed \"Memories\" as well."
  },
  AvgDialog_131212_Content_66 = {
    Text = "No, I accepted her. Romance, Kindness, Memories... one by one, I have brought home everything you cast away."
  },
  AvgDialog_131212_Content_67 = {
    Text = "Nefraea stands and spins around with delight."
  },
  AvgDialog_131212_Content_68 = {
    Text = "A complete me. A complete avenger. Do you like the view, sister?"
  },
  AvgDialog_131212_Content_69 = {
    Text = "You have the Chaos you craved. Why wait any longer?"
  },
  AvgDialog_131212_Content_7 = {
    Text = "The Cycnus Troupe is graceful enough, I suppose, but if it came down to a conflict of schedule, I would choose <Italic:Dream in the Emerald Garden> every time."
  },
  AvgDialog_131212_Content_70 = {
    Text = "Oh, no, no, no. I'm still very, very far from what I truly want."
  },
  AvgDialog_131212_Content_71 = {
    Text = "I'll take good care of your spindle for you. Your Dimentional Embers will never run dry. I won't harm a single one of your precious stages."
  },
  AvgDialog_131212_Content_72 = {
    Text = "And all I ask is a tiny, tiny little favor."
  },
  AvgDialog_131212_Content_73 = {
    Text = "Nefraea leans in, tracing the wheel that never stops turning in Arachne's hands. Her breathing hitches, fueled by the rush of her own manic imagination."
  },
  AvgDialog_131212_Content_74 = {
    Text = "Take control of the Keeper for me, dear sister. Only the Keeper can bring me what I truly desire."
  },
  AvgDialog_131212_Content_75 = {
    Text = "You know well that %player% is a fragment of the Supreme One. We cannot command {Male=his,Female=her} fate..."
  },
  AvgDialog_131212_Content_76 = {
    Text = "A sickly green light bleeds from the black spindle in Nefraea's hands. In the glow, a murky, hidden thread manifests before Arachne's eyes."
  },
  AvgDialog_131212_Content_77 = {
    Text = "This is... <Shake:the Keeper's Thread of Fate?!>"
  },
  AvgDialog_131212_Content_78 = {
    Text = "<Shake:Heh...> <Big:<Shake:HAHAHAHA!>> That's the first time I've heard your voice tremble. Well, sister? Isn't it exhilarating?!"
  },
  AvgDialog_131212_Content_79 = {
    Text = "In the Abyssal Prison, the Apostle—an embodiment of <Italic:Its> divine will—was trapped within this wheel to serve as its Wick. It was the only light we ever had in that darkness."
  },
  AvgDialog_131212_Content_8 = {
    Text = "The multi-layered ensemble, the intricate non-linear narrative... the rise and fall of the royal gardens is far superior to those clichéd plots."
  },
  AvgDialog_131212_Content_80 = {
    Text = "With our power and the Apostle's guidance, <Big:even the fate of a divine fragment rests in OUR palms!>"
  },
  AvgDialog_131212_Content_81 = {
    Text = "This is not the correct course of Fate, Nefraea... No one can defy Fate."
  },
  AvgDialog_131212_Content_82 = {
    Text = "Soon they will, sister. Once we get hold of the Authorities of the Three Aeons, the Apostle shall be reborn! They will reopen the channel to the Divine; They will carry the voices of the Believers into the Eternal Sanctuary!"
  },
  AvgDialog_131212_Content_83 = {
    Text = "The Supreme Deity will awaken... and you will never have to prune another agonizing destiny or weave a web destined to shatter."
  },
  AvgDialog_131212_Content_84 = {
    Text = "Nefraea draws a sharp breath, a single tear tracing a path through her ecstatic expression."
  },
  AvgDialog_131212_Content_85 = {
    Text = "Her voice tremors with the weight of her beautiful dream. Through a veil of tears, she stares deep into Arachne's placid face."
  },
  AvgDialog_131212_Content_86 = {
    Text = "Stop fighting me, sister. It only brings you pain."
  },
  AvgDialog_131212_Content_87 = {
    Text = "Come to my side. Let us welcome Its awakening together and grant every stage the ending it deserves!"
  },
  AvgDialog_131212_Content_9 = {
    Text = "Ha! If you back number eight, you're throwing money away. I have it on good authority that someone is drugging his feed today."
  },
  AvgDialog_131213_Content_1 = {
    Text = "Impromptu Comedy"
  },
  AvgDialog_131213_Content_10 = {
    Text = "Now, you have a new believer—"
  },
  AvgDialog_131213_Content_100 = {
    Text = "I am borrowing \"N\"'s Authority... <color=#98918C>I am occupying half of %player%'s consciousness</color>... but a name is the least important thing right now."
  },
  AvgDialog_131213_Content_101 = {
    Text = "What matters is that we worked well together, Arachne."
  },
  AvgDialog_131213_Content_102 = {
    Text = "<Shake:You... you all... you knew from the start...>"
  },
  AvgDialog_131213_Content_103 = {
    Text = "Nefraea's weak gaze shifts from Arachne to you. You greedily savor the venom and anguish smoldering within it. Ah, what an intoxicating fragrance..."
  },
  AvgDialog_131213_Content_104 = {
    Text = "Take a good look, dear Nefraea, you little troublemaker who sneaked out of the void."
  },
  AvgDialog_131213_Content_105 = {
    Text = "Your game delights me. A wisp of Tohuwabohu's consciousness, a fragment of Tohuwabohu's divinity... only through their union could the Aeons' Authority be so perfectly unleashed. Only then could I finally savor an entertainment I have never before known."
  },
  AvgDialog_131213_Content_106 = {
    Text = "If I could, I would keep playing like this forever. This is enough fun to last a week..."
  },
  AvgDialog_131213_Content_107 = {
    Text = "You let out a sigh of profound regret."
  },
  AvgDialog_131213_Content_108 = {
    Text = "But alas, I cannot let it go on. If that God were to wake, this magnificent funfair would vanish."
  },
  AvgDialog_131213_Content_109 = {
    Text = "So, unfortunately... the climax must end. Look up, darling. No matter what, we can at least agree on one thing about this story of Fate..."
  },
  AvgDialog_131213_Content_11 = {
    Text = "The threads of Fate guide your body. You interlace your fingers, clasp your hands to your chest, and slowly kneel before the spinning wheel, bowing your head in reverence."
  },
  AvgDialog_131213_Content_110 = {
    Text = "You lean down, catching Nefraea's elegant chin in a mocking pinch, and draw your lips close to her ear."
  },
  AvgDialog_131213_Content_111 = {
    Text = "Destruction is the most beautiful sight in the universe, isn't it, my dear?"
  },
  AvgDialog_131213_Content_112 = {
    Text = "You snap your fingers before her eyes. The sound rings with boundless elation and regret."
  },
  AvgDialog_131213_Content_113 = {Text = "Boom."},
  AvgDialog_131213_Content_114 = {
    Text = "The passage to the Divine shudders. Cracks spiderweb across its ethereal surface..."
  },
  AvgDialog_131213_Content_115 = {
    Text = "<Big:<Shake:NOOOO!!—>>"
  },
  AvgDialog_131213_Content_116 = {
    Text = "Nefraea lunges for the passage, but it shatters inches from her fingertips."
  },
  AvgDialog_131213_Content_117 = {
    Text = "Countless illusory shards flutter before Nefraea like a shattered kaleidoscope; garish scraps of cheap, colored paper fill the air, their jagged edges scraping across her face."
  },
  AvgDialog_131213_Content_118 = {
    Text = "You tip your invisible top hat, spin it twice, and offer a deep bow to her bewildered back."
  },
  AvgDialog_131213_Content_119 = {
    Text = "Fate is such an entertaining stage. And so, the curtain falls on Act Three. I thoroughly enjoyed your applause and cheers."
  },
  AvgDialog_131213_Content_12 = {
    Text = "O Apostle... of my adoration... I am but a humble servant... of You and the Supreme Deity... Your most faithful devotee."
  },
  AvgDialog_131213_Content_120 = {
    Text = "Enjoy the show, dear Nefreya."
  },
  AvgDialog_131213_Content_121 = {
    Text = "In Nephreya's heart-wrenching cry, the Apostle's consciousness shatters with the severing of the link. You fall straight onto the stage, wearing a final smile of joy."
  },
  AvgDialog_131213_Content_13 = {
    Text = "Your throat and limbs take on a fate of their own. They no longer belong to you, and you make no futile attempt to reclaim them."
  },
  AvgDialog_131213_Content_14 = {
    Text = "Don't try to control. Don't try to comprehend. Enjoy. The truth of Rapture lies within..."
  },
  AvgDialog_131213_Content_15 = {
    Text = "Look, sister! What an outstanding actor you've trained!"
  },
  AvgDialog_131213_Content_16 = {
    Text = "Arachne sits quietly beneath the stage, her wheel turning at its eternal rhythm. She gazes at the shadowy glow of the Lantern on stage, an observer dutifully following the proprieties."
  },
  AvgDialog_131213_Content_17 = {
    Text = "My dear Apostle... our believer has brought you the sacrifice you desire most."
  },
  AvgDialog_131213_Content_18 = {
    Text = "The dark spindle erupts in a sudden burst, scattering dim, viscous light into every corner of the stage."
  },
  AvgDialog_131213_Content_19 = {Text = "Ugh!!..."},
  AvgDialog_131213_Content_2 = {
    Text = "Tap, tap, tap."
  },
  AvgDialog_131213_Content_20 = {
    Text = "Pain strikes without warning. It does not hit your flesh or organs, but erupts from the deepest recesses of your Spirit Realm—from the very seat of your soul."
  },
  AvgDialog_131213_Content_21 = {
    Text = "A great beast manifests within you. It struggles and roars, its massive form rapidly expanding inside you."
  },
  AvgDialog_131213_Content_22 = {
    Text = "The beast fills your entire body, crushing every organ. It expands further, raging to burst through your skin. The intense, overwhelming pressure almost knocks you unconscious..."
  },
  AvgDialog_131213_Content_23 = {
    Text = "Hah... <Big:<Shake:AAAARGH!!—>>"
  },
  AvgDialog_131213_Content_24 = {
    Text = "Amidst your gut-wrenching cries of agony, three flickering auras seep out from your tormented body, drifting toward the glowing spinning wheel."
  },
  AvgDialog_131213_Content_25 = {
    Text = "Authority converges into the light like pure fuel poured into a fire. Pale green flames burst forth, burning fiercely within the ring of the spindle. The Lantern's radiance climbs, illuminating the entire dimension."
  },
  AvgDialog_131213_Content_26 = {
    Text = "<Shake:Hah... Hah...>"
  },
  AvgDialog_131213_Content_27 = {
    Text = "Oh, you poor, faithful little believer..."
  },
  AvgDialog_131213_Content_28 = {
    Text = "Nefraea comes to your side, her face full of concern as she caresses your sweat-dampened cheek."
  },
  AvgDialog_131213_Content_29 = {
    Text = "It's alright, {Male=Mr.,Female=Miss} Keeper. You see? Our Apostle has already revealed Their form..."
  },
  AvgDialog_131213_Content_3 = {
    Text = "The silken threads of Fate pull gently. The puppet's shoes strike the stage, producing a crisp, clear sound."
  },
  AvgDialog_131213_Content_30 = {
    Text = "You lift your head in agony. The light of the spinning wheel converges, and a shifting, fleeting form materializes above the glow."
  },
  AvgDialog_131213_Content_31 = {
    Text = "They have no face and no shape. They are the faithful herald of the Divine, gazing into the void toward the slumbering God."
  },
  AvgDialog_131213_Content_32 = {
    Text = "Their stare is an invitation. Beneath that unblinking gaze, a staircase connecting to the resting place of the God slowly takes shape..."
  },
  AvgDialog_131213_Content_33 = {
    Text = "<Shake:It worked... it worked!> The passage to the Higher Plane is opening... The God is about to awaken..."
  },
  AvgDialog_131213_Content_34 = {
    Text = "Sister, do you see? Your web is almost complete..."
  },
  AvgDialog_131213_Content_35 = {
    Text = "Nefraea watches the passage sharpen into view, smiling through a flood of tears in her ecstasy."
  },
  AvgDialog_131213_Content_36 = {Text = "@2...@3..."},
  AvgDialog_131213_Content_37 = {
    Text = "The theater trembles violently. The stage collapses, and the dimension shakes. All things cower in fear, submitting before this Arrival."
  },
  AvgDialog_131213_Content_38 = {
    Text = "The Authority within you has dwindled to almost nothing. The Aeon's power has been absorbed into the Apostle's body. Their brilliance is too fierce to gaze upon; Their existence is utterly undeniable."
  },
  AvgDialog_131213_Content_39 = {
    Text = "Beneath Arachne's calm gaze, amidst the trembling of all Fate, They descend upon this final stage—"
  },
  AvgDialog_131213_Content_4 = {
    Text = "Ah, dear audience, the moment you have been waiting for is finally here! Let's welcome our star! Woooh!"
  },
  AvgDialog_131213_Content_40 = {
    Text = "In the name of... @2... @3 believers..."
  },
  AvgDialog_131213_Content_41 = {
    Text = "Speak, Apostle... what do you wish to tell me? Your own desires? Or the words of the Divine?"
  },
  AvgDialog_131213_Content_42 = {
    Text = "What decree does It deliver? Does It wish to shatter these stages? Or does It want these puppets to welcome Its coming?!"
  },
  AvgDialog_131213_Content_43 = {
    Text = "Tell me, my dear Apostle! What a dangerous, adorable beast you are, knowing only how to wrench and destroy... tell me what you desire..."
  },
  AvgDialog_131213_Content_44 = {
    Text = "Recite @2... my name... awaken @2... @3 Primordial..."
  },
  AvgDialog_131213_Content_45 = {
    Text = "Ah, your name! Yes... I shall speak it aloud! I will bring everything you wish to devour to your lips. I shall open this cage for you..."
  },
  AvgDialog_131213_Content_46 = {
    Text = "My name... @2..."
  },
  AvgDialog_131213_Content_47 = {
    Text = "The Apostle's voice is murky and indistinct. Nefraea walks toward the brightening pillar of light, without a single glance at you as you tremble in agony."
  },
  AvgDialog_131213_Content_48 = {
    Text = "Fervor fills her with wonder and laughter as she approaches the great figure. Her breath hitches with elation."
  },
  AvgDialog_131213_Content_49 = {
    Text = "She caresses the dim green light—caresses the magnificent beast about to devour everything. She will be the beast's first meal, and she presses forward in sweet surrender."
  },
  AvgDialog_131213_Content_5 = {
    Text = "Nefraea raises her hand, and webs scatter like confetti. You stand at the center of the stage, the dim light illuminating your face."
  },
  AvgDialog_131213_Content_50 = {
    Text = "Now is the time, Apostle... tell me, tell the world your name!"
  },
  AvgDialog_131213_Content_51 = {
    Text = "My name... @2..."
  },
  AvgDialog_131213_Content_52 = {
    Text = "My name is... <Red:%player%>..."
  },
  AvgDialog_131213_Content_53 = {
    Text = "My name is... <Yellow:%player%>!"
  },
  AvgDialog_131213_Content_54 = {Text = "!!!"},
  AvgDialog_131213_Content_55 = {
    Text = "Time freezes. In Nefraea's eyes, the Threads of Fate liquefy and shatter. The ruin of destiny swirls like a violent vortex in a vast ocean, sweeping her into the depths to devour her whole."
  },
  AvgDialog_131213_Content_56 = {
    Text = "<Shake:What is... what is happening?!!>"
  },
  AvgDialog_131213_Content_57 = {
    Text = "The vortex stills. The ocean retreats. Droplets coalesce into silk once more, yet the web they weave takes a shape Nefraea never imagined."
  },
  AvgDialog_131213_Content_58 = {
    Text = "Don't you understand, Nefraea? Prostrate yourself in reverence. The Apostle you prayed for stands before you now."
  },
  AvgDialog_131213_Content_59 = {
    Text = "You stand over Nefraea, staring into the passage that leads to the Temple of Tohuwabohu. You grin at that supreme silhouette."
  },
  AvgDialog_131213_Content_6 = {
    Text = "Come now, {Male=Mr.,Female=Miss} Keeper. Our final act begins..."
  },
  AvgDialog_131213_Content_60 = {
    Text = "The Authority of the Three Aeons rushes through your veins, but it no longer brings you pain. The brilliance from the spindle—the absolute will within the light—pours into you like a rising tide, merging with your power."
  },
  AvgDialog_131213_Content_61 = {
    Text = "You feel the Apostle's shadow overlap with your own. You feel immense. Boundless. Free. You feel... the supreme, absolute Rapture."
  },
  AvgDialog_131213_Content_62 = {
    Text = "You... you stole the Apostle's destiny?!"
  },
  AvgDialog_131213_Content_63 = {
    Text = "Heh... hahaha! Act Three: The Arrival, huh?... Ha, it is a fine title. But this isn't your story, my dear Nefraea."
  },
  AvgDialog_131213_Content_64 = {
    Text = "I am the one writing this act. And I name it... <Big:<color=#98918C>Rapture</color>>!"
  },
  AvgDialog_131213_Content_65 = {
    Text = "<Shake:You... all of you...>"
  },
  AvgDialog_131213_Content_66 = {
    Text = "No, this is impossible... I can see your fate... this cannot be..."
  },
  AvgDialog_131213_Content_67 = {
    Text = "<color=#EE4D0C><Italic:\"Oh, my dear Duke, why the long face? Let your jester restore that precious smile!\"></color>"
  },
  AvgDialog_131213_Content_68 = {
    Text = "<color=#BF0909><Italic:\"Look at it—the cruel fate, the wicked curse... what a ridiculous spectacle! What a sweet, delicious lie!\"></color>"
  },
  AvgDialog_131213_Content_69 = {
    Text = "<color=#FC1818><Italic:\"This is how the story ends for the villain... the only reward for malice is Rapture!\"></color>"
  },
  AvgDialog_131213_Content_7 = {
    Text = "I call this moment—\"The Arrival!\""
  },
  AvgDialog_131213_Content_70 = {
    Text = [[
Thunderous applause erupts from the empty seats. Brilliant lights drench the ruined stage. You are the pivot of the world, the master of the Singularity. 
You spread your arms. You declare Fate shall bow to you. You declare this performance a masterpiece.]]
  },
  AvgDialog_131213_Content_71 = {
    Text = "Deception. Manipulation. Pure enjoyment... <Shake:Hehe... <Big:HAHAHAHA!>> What a delightful show, little spider."
  },
  AvgDialog_131213_Content_72 = {
    Text = "<Shake:You... you cannot possibly have the power to alter Fate...>"
  },
  AvgDialog_131213_Content_73 = {
    Text = "Aww.. No, no, no. Such exertion is for people like you. A devotee of Rapture would never stoop to such labor."
  },
  AvgDialog_131213_Content_74 = {
    Text = "<Shake:I saw the end... You were meant to surrender your Authority! <Big:You were meant to watch the passage open and die on this stage! WHY?!>>"
  },
  AvgDialog_131213_Content_75 = {
    Text = "Those who manipulate Fate know everything—except for the ones who dwell in Rapture. Because, my dear... those in Rapture follow no fate..."
  },
  AvgDialog_131213_Content_76 = {
    Text = "You lean down, savoring Nefraea's trembling gaze. The agony and despair in her eyes nourish every inch of your being."
  },
  AvgDialog_131213_Content_77 = {
    Text = "Our entire lives are spent in the pursuit of pleasure. Without it, we are nothing. And those who find it... are beyond the reach of destiny."
  },
  AvgDialog_131213_Content_78 = {
    Text = "What you see is a parlor trick. A small joke played on my past self and on Fate by the new me, the one blessed with the will and power of a God."
  },
  AvgDialog_131213_Content_79 = {
    Text = "Why control Fate when you can make a fool of it instead? Isn't that right, Proxy of Fate?"
  },
  AvgDialog_131213_Content_8 = {
    Text = "The Arrival. On the curtain behind the stage, slime-like cobwebs weave the massive, horrifying words. Nefraea draws a deep breath and spreads her arms wide."
  },
  AvgDialog_131213_Content_80 = {
    Text = "You try to maintain a serious tone, but you cannot suppress your manic laughter."
  },
  AvgDialog_131213_Content_81 = {
    Text = "Are you the Keeper? Are you \"N\"? You don't know, and you don't care. The essence of Rapture floods into the Apostle's will, filling every cell of your body."
  },
  AvgDialog_131213_Content_82 = {
    Text = "You want to howl with laughter. You want to cheer. You want to subject this failed manipulator to the most tender, devastating humiliation."
  },
  AvgDialog_131213_Content_83 = {
    Text = "You found the key. You turn and offer a graceful bow to the architect of this scheme."
  },
  AvgDialog_131213_Content_84 = {
    Text = "Arachne, you magnificent playwright! You have been weaving this stage for me since the moment I stepped into this world!"
  },
  AvgDialog_131213_Content_85 = {
    Text = "You showed me how the threads move, taught me the charm of the lie, and whispered the secret of \"Rapture.\""
  },
  AvgDialog_131213_Content_86 = {
    Text = "Now, the lock is open. Well? Are you satisfied with your lead actor?"
  },
  AvgDialog_131213_Content_87 = {
    Text = "I only set the stage. You are the one who writes the script."
  },
  AvgDialog_131213_Content_88 = {
    Text = "You grin at her. You are an Apostle of the Divine. You are a Slave to Rapture. You are the undisputed, only master of this world. You raise your hand and bring it down gently, like a conductor."
  },
  AvgDialog_131213_Content_89 = {
    Text = "As a token of my gratitude... put on your costume, Arachne. Your cue is coming!"
  },
  AvgDialog_131213_Content_9 = {
    Text = "Apostle of the Supreme Deity, Messenger of the Idiot Blind God. Your radiance illuminates the eternal prison. I have heard your voice calling for Chaos!"
  },
  AvgDialog_131213_Content_90 = {
    Text = "You pluck the once-invisible Threads as if shifting blocks in a nursery."
  },
  AvgDialog_131213_Content_91 = {
    Text = "As the weave reshapes itself, the stolen Dimensional Embers fly back to her."
  },
  AvgDialog_131213_Content_92 = {
    Text = "Endless violet sand swirls around Arachne. In your new reality, those embers were never stolen."
  },
  AvgDialog_131213_Content_93 = {
    Text = "<color=#8C7E96>Past and future, they belong to her alone.</color>"
  },
  AvgDialog_131213_Content_94 = {
    Text = "Arachne nods with a smile, drawing the ashes into her body. Her wheel never stops. Her smile never changes."
  },
  AvgDialog_131213_Content_95 = {
    Text = "You shake your head on stage and let out an exaggerated, theatrical sigh."
  },
  AvgDialog_131213_Content_96 = {
    Text = "Dull and passionless... you could have been so interesting, Arachne."
  },
  AvgDialog_131213_Content_97 = {
    Text = "You are a slave to destiny, just like Tawil. You will never know this joy."
  },
  AvgDialog_131213_Content_98 = {
    Text = "Take a look at your lifeless face, Arachne. I truly pity the both of you."
  },
  AvgDialog_131213_Content_99 = {
    Text = "Everyone makes their choice, %player%... or should I call you the Apostle? Or perhaps... \"N\"?"
  },
  AvgDialog_131214_Content_1 = {
    Text = "<Shake:AAAAARGH!!>"
  },
  AvgDialog_131214_Content_10 = {
    Text = "Because... our revenge is not over. It will never be over..."
  },
  AvgDialog_131214_Content_11 = {
    Text = "You instinctively step back, but no danger emanates from Nefraea."
  },
  AvgDialog_131214_Content_12 = {
    Text = "She simply swings a claw and tears away the curtain at her side, revealing the scene hidden behind the veil."
  },
  AvgDialog_131214_Content_13 = {
    Text = "This is...!"
  },
  AvgDialog_131214_Content_14 = {
    Text = "Crimson threads connect the many stages, the grand city, and the countless puppets within it. All of them converge into Nefraea's wounded body."
  },
  AvgDialog_131214_Content_15 = {
    Text = "You... you didn't attach the threads to the spinning wheel?"
  },
  AvgDialog_131214_Content_16 = {
    Text = "She saw her own defeat. While she still had power, she bound these fates to herself, much like..."
  },
  AvgDialog_131214_Content_17 = {
    Text = "Just like the first time you killed me."
  },
  AvgDialog_131214_Content_18 = {
    Text = "Nefraea smiles, pinching a hidden thread before her."
  },
  AvgDialog_131214_Content_19 = {
    Text = "That crimson strand extends from the back of her head, weaving through the air until it flows into Arachne's body."
  },
  AvgDialog_131214_Content_2 = {Text = "BOOM!"},
  AvgDialog_131214_Content_20 = {
    Text = "It has been so long since we were this close, sister. I only just found the chance to return this thread to you."
  },
  AvgDialog_131214_Content_21 = {Text = "Return...?"},
  AvgDialog_131214_Content_22 = {
    Text = "This thread... is the one I snip when I destroyed my first creation."
  },
  AvgDialog_131214_Content_23 = {
    Text = "Your Romance, your Kindness, your Memories... everything that was once mine is yours again."
  },
  AvgDialog_131214_Content_24 = {
    Text = "You are whole, Arachne."
  },
  AvgDialog_131214_Content_25 = {
    Text = "Nefraea's lips curl into a smirk, like a child hiding behind a curtain to watch an adult fall for a prank."
  },
  AvgDialog_131214_Content_26 = {
    Text = "Is this what you wanted to do... when you had that power?"
  },
  AvgDialog_131214_Content_27 = {
    Text = "How do you like it? A brilliant idea, isn't it?"
  },
  AvgDialog_131214_Content_28 = {
    Text = "Come then, kill me! Destroy the fates you once abandoned! Destroy the city you took refuge in, destroy the theater you hold dear, and destroy every single soul here!"
  },
  AvgDialog_131214_Content_29 = {
    Text = "Come, Arachne! Take every bit of your weakness, take everything you love... and kill them all over again!!"
  },
  AvgDialog_131214_Content_3 = {
    Text = "Agonized screams and the roar of collapse echo through the ruins. The crimson threads snap. The spinning wheel that accompanied Nefraea her entire life tumbles to the floor."
  },
  AvgDialog_131214_Content_30 = {
    Text = "Nefraea's frenzied screams and laughter echo endlessly through the shattered theater."
  },
  AvgDialog_131214_Content_31 = {
    Text = "Arachne's body seems to grow impossibly heavy. She slowly turns her head, scanning everything connected to Nefraea."
  },
  AvgDialog_131214_Content_32 = {
    Text = "Through the rifts in the theater, she sees the bustling city packed with cars and crowds. She sees familiar faces and familiar names in every corner."
  },
  AvgDialog_131214_Content_33 = {
    Text = "She sees the stage you once stepped onto together. The brutal war has ended, and that world is about to welcome two centuries of magnificent peace."
  },
  AvgDialog_131214_Content_34 = {
    Text = "In the black sludge, she sees her mother's face. She sees her father sitting beneath the birch trees in the courtyard, beckoning to her."
  },
  AvgDialog_131214_Content_35 = {
    Text = "Mr. Lawrence stands beside them, wiping the cutlery crafted especially for her."
  },
  AvgDialog_131214_Content_36 = {
    Text = "You call this revenge because you never saw Fate clearly, Nefraea. And you never saw me."
  },
  AvgDialog_131214_Content_37 = {
    Text = "A thread covered in slime connects Arachne to the shattered stage beneath Nefraea's feet. Dragging her heavy frame, Arachne steps onto the fragile strand."
  },
  AvgDialog_131214_Content_38 = {
    Text = "The thread trembles as if it might snap and cast the Prisoner of Fate into the abyss."
  },
  AvgDialog_131214_Content_39 = {
    Text = "Arachne stares calmly into Nefraea's astonished eyes. Her steps never falter."
  },
  AvgDialog_131214_Content_4 = {
    Text = "She clutches the wheel like a drowning infant. The darkened spindle dissolves in her hands, turning into dimensional embers that flow into the shifting sands beside Arachne."
  },
  AvgDialog_131214_Content_40 = {
    Text = "The fated moment is here..."
  },
  AvgDialog_131214_Content_41 = {
    Text = "Standing upon her web, Arachne raises her spindle. The entire world pauses. The universe connected to this theater holds its breath, waiting for her decree."
  },
  AvgDialog_131214_Content_42 = {
    Text = "In the name of Fate, I hereby declare—"
  },
  AvgDialog_131214_Content_43 = {
    Text = "All erroneous fates shall be buried in the dust of time. The destiny of the world shall return to its intended course."
  },
  AvgDialog_131214_Content_44 = {
    Text = "The wrong fate ends here. The forsaken shall find rest..."
  },
  AvgDialog_131214_Content_45 = {
    Text = "The spindle tilts. Countless threads tremble."
  },
  AvgDialog_131214_Content_46 = {
    Text = "The threads snap. The stage awaiting peace crumbles into nothing."
  },
  AvgDialog_131214_Content_47 = {
    Text = "The threads snap. Through the cracks in the theater, the city vanishes."
  },
  AvgDialog_131214_Content_48 = {
    Text = "The threads break, and break, and break..."
  },
  AvgDialog_131214_Content_49 = {
    Text = "You struggle to see the threads, but you hear the cry of Fate clearly."
  },
  AvgDialog_131214_Content_5 = {
    Text = "Nefraea stares blankly at her vanishing hope, then suddenly breaks into a quiet giggle."
  },
  AvgDialog_131214_Content_50 = {
    Text = "Countless lives, joys, and sorrows shatter and dissolve at your ear, only to be reconstructed and annihilated."
  },
  AvgDialog_131214_Content_51 = {Text = "...Lights?"},
  AvgDialog_131214_Content_52 = {
    Text = "Stage lights flicker on from an unknown source. The light pierces the shattered theater. The forsaken ones lurking in the shadows vanish the moment the light falls upon them—as if they were never there at all."
  },
  AvgDialog_131214_Content_53 = {
    Text = "Arachne... sister... you..."
  },
  AvgDialog_131214_Content_54 = {
    Text = "Arachne steps across the fragile thread and stops before her. Nefraea looks up at her as if gazing upon the unyielding face of Fate itself."
  },
  AvgDialog_131214_Content_55 = {
    Text = "Come closer, Nefraea."
  },
  AvgDialog_131214_Content_56 = {
    Text = "Arachne takes Nefraea's hand and presses it against her own cheek."
  },
  AvgDialog_131214_Content_57 = {
    Text = "The moment she touches Arachne, a secret gate opens. Nefraea passes through layers of cages, standing truly before Arachne for the first time."
  },
  AvgDialog_131214_Content_58 = {
    Text = "In that cage, she sees three familiar faces."
  },
  AvgDialog_131214_Content_59 = {
    Text = "Arachne!!! You..."
  },
  AvgDialog_131214_Content_6 = {
    Text = "Her laughter grows louder, though she barely has the strength to sit up. Blood drips from her trembling body, staining the dim fragments of the wheel."
  },
  AvgDialog_131214_Content_60 = {
    Text = "<Shake:Romance, Kindness, Memories... they... they...>"
  },
  AvgDialog_131214_Content_61 = {
    Text = "I could never fully let them go. I could never truly let <Italic:you> go."
  },
  AvgDialog_131214_Content_62 = {
    Text = "But you said you couldn't handle the pain..."
  },
  AvgDialog_131214_Content_63 = {
    Text = "Foolishly and painfully destroying everything I hold dear... you cannot use that to take revenge on me, Nefraea."
  },
  AvgDialog_131214_Content_64 = {
    Text = "Because that is the punishment Fate decreed for me long ago."
  },
  AvgDialog_131214_Content_65 = {
    Text = "Arachne smiles calmly. Her wheel turns, endlessly through eternity."
  },
  AvgDialog_131214_Content_66 = {
    Text = "It is over, Nefraea."
  },
  AvgDialog_131214_Content_67 = {
    Text = "A single string trembles. Nefraea hears the cry of an egret, just like the day her father brought her the spindle named Moirae."
  },
  AvgDialog_131214_Content_68 = {
    Text = "This is her room. The birch trees outside the window are her faithful companions—eternal, lonely prisoners."
  },
  AvgDialog_131214_Content_69 = {
    Text = "They are imprisoned by Fate, and here they depend on each other to survive."
  },
  AvgDialog_131214_Content_7 = {
    Text = "The ending... the ending truly cannot be changed. This is Fate..."
  },
  AvgDialog_131214_Content_70 = {Text = "Creak—"},
  AvgDialog_131214_Content_71 = {
    Text = "The plain wooden door swings open. Arachne comes to her side and leans down, gently caressing her face."
  },
  AvgDialog_131214_Content_72 = {
    Text = "Sister... I lost... we lost..."
  },
  AvgDialog_131214_Content_73 = {
    Text = "We never had the right to win."
  },
  AvgDialog_131214_Content_74 = {
    Text = "Do you remember the wish we made the day we received the wheel?"
  },
  AvgDialog_131214_Content_75 = {
    Text = "I will not squander the gifts of Fate... I will bring a beautiful destiny to this world..."
  },
  AvgDialog_131214_Content_76 = {
    Text = "What a naive wish, Arachne... we had no idea what it meant."
  },
  AvgDialog_131214_Content_77 = {
    Text = "Arachne reaches out with a trembling hand, touching the face of her distant self."
  },
  AvgDialog_131214_Content_78 = {
    Text = "Fate... who can truly see it?"
  },
  AvgDialog_131214_Content_79 = {
    Text = "Even if I could have foreseen this, my choice would not change."
  },
  AvgDialog_131214_Content_8 = {
    Text = "You saw this tragic victory coming, didn't you, Arachne?"
  },
  AvgDialog_131214_Content_80 = {
    Text = "<Shake:Why, Arachne?> You could have left. You could have given up. You could..."
  },
  AvgDialog_131214_Content_81 = {
    Text = "You could have had eternal freedom after leaving the Abyss. You knew you would fail, yet you came here anyway to try to bring liberation to me and to those who followed you."
  },
  AvgDialog_131214_Content_82 = {
    Text = "Every manipulator of Fate becomes its prisoner. We are no different, Nefraea."
  },
  AvgDialog_131214_Content_83 = {
    Text = "Nefraea sits in silence, gazing sadly at the birch tree outside. She watches it bud, grow, and wither in an instant."
  },
  AvgDialog_131214_Content_84 = {
    Text = "She lets out a soft sigh and brushes away the tears falling down Arachne's face. She smiles."
  },
  AvgDialog_131214_Content_85 = {
    Text = "It's so good to see you again... Sis."
  },
  AvgDialog_131214_Content_86 = {
    Text = "A single tear falls onto the face that is identical to Arachne's."
  },
  AvgDialog_131214_Content_87 = {
    Text = "Forgive me for my selfishness..."
  },
  AvgDialog_131214_Content_88 = {
    Text = "You... are free now, <Red:\"Arachne.\">"
  },
  AvgDialog_131214_Content_89 = {Text = "Creak."},
  AvgDialog_131214_Content_9 = {
    Text = "You caught a brief glimpse of it yourself just now. Since you know how it ends, why do you still cling to it?"
  },
  AvgDialog_131214_Content_90 = {
    Text = "When the last thread snaps, a thunderous round of applause erupts."
  },
  AvgDialog_131214_Content_91 = {
    Text = "The seats below, once eternally vacant, are now packed to capacity. The Abandoned Fates and the Puppets who died by your hand fill every tattered velvet chair."
  },
  AvgDialog_131214_Content_92 = {
    Text = "The actors take their places among the audience, watching the ending unfold on this broken stage in silence."
  },
  AvgDialog_131214_Content_93 = {
    Text = [[
They are expressionless, silent. 
 They applaud enthusiastically. The applause thunders, lasting endlessly.]]
  },
  AvgDialog_131215_Content_1 = {
    Text = "The Actor Within"
  },
  AvgDialog_131215_Content_10 = {
    Text = "I didn't understand why Arachne removed her sister from the Web, or why you needed the power of those three Puppets."
  },
  AvgDialog_131215_Content_100 = {Text = "..."},
  AvgDialog_131215_Content_101 = {
    Text = "A destiny as resolute as it is futile... what a desperate, hauntingly beautiful sight."
  },
  AvgDialog_131215_Content_102 = {
    Text = "Why do you think she does it?"
  },
  AvgDialog_131215_Content_103 = {
    Text = "Nefraea stares intently at the sparse stage, her voice a mere whisper."
  },
  AvgDialog_131215_Content_104 = {
    Text = "It's all a dream, Goddess of Fate... You could have chosen the happiest fate for everyone. You could have mended your own childish fantasies and fulfilled every desire."
  },
  AvgDialog_131215_Content_105 = {
    Text = "But you never even considered it. In creating perfection, you also created suffering. Over and over again, you let agony descend upon this world."
  },
  AvgDialog_131215_Content_106 = {
    Text = "You poured your very soul into weaving that Great Web, yet we have both seen the sight beyond the Gateway. We know the destination."
  },
  AvgDialog_131215_Content_107 = {
    Text = "The moment the Web of Fate is complete is the moment the Supreme Deity fully awakens."
  },
  AvgDialog_131215_Content_108 = {Text = "What...?!"},
  AvgDialog_131215_Content_109 = {
    Text = "You look at Arachne, searching for a denial on her face."
  },
  AvgDialog_131215_Content_11 = {
    Text = "At least I can thank you for clearing up the mystery."
  },
  AvgDialog_131215_Content_110 = {
    Text = "You find only her usual, eternal calm. On the stage of Fate, serenity is a mask she cannot remove."
  },
  AvgDialog_131215_Content_111 = {
    Text = "Sister, you cannot stop weaving, because you cannot bear to watch the universe fall into chaos. But the day your web is finished, you will be the one to bury everything you love with your own hands."
  },
  AvgDialog_131215_Content_112 = {
    Text = "How ironic, Arachne. Why? Why not let the universe embrace its end in pure bliss?"
  },
  AvgDialog_131215_Content_113 = {
    Text = "All that is Fate is written in the Constant; all that is Fate is subject to the Variable. These contradictory maxims are the essence of destiny."
  },
  AvgDialog_131215_Content_114 = {
    Text = "Arachne looks into Nefraea's eyes, answering the question she has asked herself a thousand times."
  },
  AvgDialog_131215_Content_115 = {
    Text = "Nefraea, within the endless dimensions, there are still countless souls fighting for that single Variable of hope."
  },
  AvgDialog_131215_Content_116 = {
    Text = "To keep the stage running, to wait for the Variable to appear... these are the fetters Fate placed upon me. It is a duty I cannot escape."
  },
  AvgDialog_131215_Content_117 = {
    Text = "Duty, peril... you always speak of grand things, but never of yourself, Arachne. My poor, tragic sister. No matter... Your painful duty is finally coming to an end."
  },
  AvgDialog_131215_Content_118 = {
    Text = "Nefraea tenderly caresses Arachne's cheek and offers a sweet smile."
  },
  AvgDialog_131215_Content_119 = {
    Text = "In the Abyss, I imagined our reunion a thousand times. I wondered what gift could possibly be worthy of such a moment."
  },
  AvgDialog_131215_Content_12 = {
    Text = "Why didn't you tell me any of this before?"
  },
  AvgDialog_131215_Content_120 = {
    Text = "I thought for so, so long... and then it hit me. This is the best gift I can give you, my dear sister!"
  },
  AvgDialog_131215_Content_121 = {
    Text = "I give you... <Red:Liberation.>"
  },
  AvgDialog_131215_Content_122 = {
    Text = "As Nefraea speaks those gentle words, inky black sludge gathers within the dimensional rifts. At the end of the silken path, a magnificent stage reveals itself."
  },
  AvgDialog_131215_Content_13 = {
    Text = "You look at the Arachne beside you, who still guides your every step."
  },
  AvgDialog_131215_Content_14 = {
    Text = "A stone that stirs no ripples in the lake of Fate serves no purpose but to disturb the peace."
  },
  AvgDialog_131215_Content_15 = {
    Text = "She and I became two separate people a long time ago, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131215_Content_16 = {
    Text = "Did you foresee this day?"
  },
  AvgDialog_131215_Content_17 = {
    Text = "No prisoner sees their own fate until the verdict is delivered."
  },
  AvgDialog_131215_Content_18 = {
    Text = "If you had known those discarded fates would be exiled to the Abyssal Prison instead of vanishing... would you still have done it, Arachne?"
  },
  AvgDialog_131215_Content_19 = {Text = "..."},
  AvgDialog_131215_Content_2 = {
    Text = "La la la la..."
  },
  AvgDialog_131215_Content_20 = {
    Text = "Silence. Silence is the playwright's eternal blight. Silence is the prisoner's powerless self-defense. Amid a silence like a death sentence, Nefraea's frenzied laughter rang out."
  },
  AvgDialog_131215_Content_21 = {
    Text = "Oh, you certainly would have, sister. Fate is your doctrine; no condition can change its final answer."
  },
  AvgDialog_131215_Content_22 = {
    Text = "You, the Goddess of Fate. So insignificant, so fragile, so cruel..."
  },
  AvgDialog_131215_Content_23 = {
    Text = "But it's fine. No matter what you do, I've always kept you in my thoughts during those long years, dear sister."
  },
  AvgDialog_131215_Content_24 = {
    Text = "Romance, Kindness, Memories. These beautiful ingredients have fermented, brewing Nefraea's smile into a sweet poison."
  },
  AvgDialog_131215_Content_25 = {
    Text = "As she beams, the lights along the silken path illuminate the stage."
  },
  AvgDialog_131215_Content_26 = {
    Text = "Sister, {Male=Mr.,Female=Miss} Keeper... these new plays are a gift from me, the new master of the theater."
  },
  AvgDialog_131215_Content_27 = {
    Text = "Before the grand third act, please enjoy this prelude... and remember the rules of the theater. No talking!"
  },
  AvgDialog_131215_Content_28 = {
    Text = "Nefraea spreads her arms like an announcer. Countless stages light up one by one as you walk past."
  },
  AvgDialog_131215_Content_29 = {Text = "..."},
  AvgDialog_131215_Content_3 = {
    Text = "They dance. They sing. Creak, creak!"
  },
  AvgDialog_131215_Content_30 = {
    Text = "Great Goddess of Fate, three puppet vessels are ready for you."
  },
  AvgDialog_131215_Content_31 = {
    Text = "What exquisite dolls... Those I have lost shall find new life within them..."
  },
  AvgDialog_131215_Content_32 = {
    Text = "The \"Arachne\" puppet leaves her loom and approaches the dolls."
  },
  AvgDialog_131215_Content_33 = {
    Text = "To the first, I bestow the name \"Romance.\""
  },
  AvgDialog_131215_Content_34 = {
    Text = "You are the most passionate movement of the symphony: a collective of raw emotion, the heavy fruit of a spring in bloom."
  },
  AvgDialog_131215_Content_35 = {
    Text = "You shall go to the midnight paradise, bringing wine, chance encounters, and an undying fire to this city."
  },
  AvgDialog_131215_Content_36 = {
    Text = "I thank you, great Goddess Arachne. As you command, wine and honey shall flow from my lips."
  },
  AvgDialog_131215_Content_37 = {
    Text = "The beautiful woman bows gracefully to the Arachne puppet."
  },
  AvgDialog_131215_Content_38 = {
    Text = "To the second, I bestow the name \"Kindness.\""
  },
  AvgDialog_131215_Content_39 = {
    Text = "You are the elder who raised me—a white feather shed by an angel, the most sacred ray of sunlight."
  },
  AvgDialog_131215_Content_4 = {
    Text = "Ancient tales and joyful footsteps tremble across the web. Nefraea clasps her hands behind her back, skipping forward."
  },
  AvgDialog_131215_Content_40 = {
    Text = "You shall walk the city streets, warming all you see with your benevolence."
  },
  AvgDialog_131215_Content_41 = {
    Text = "I thank you, great Goddess Arachne! You gave me life; I can never repay such a debt."
  },
  AvgDialog_131215_Content_42 = {
    Text = "I have nothing, yet I love this world deeply. I shall protect the weak and aid the suffering."
  },
  AvgDialog_131215_Content_43 = {
    Text = "All I have belongs to those in pain."
  },
  AvgDialog_131215_Content_44 = {
    Text = "The kind elder offers a deep, respectful bow."
  },
  AvgDialog_131215_Content_45 = {
    Text = "And to you, the third... I bestow the name \"Memories.\""
  },
  AvgDialog_131215_Content_46 = {
    Text = "The \"Arachne\" puppet stops before the small doll. She crouches, staring into its vacant eyes."
  },
  AvgDialog_131215_Content_47 = {
    Text = "You are the orphan of Fate—a withered leaf buried beneath the deep snow."
  },
  AvgDialog_131215_Content_48 = {
    Text = "You walk alone in silence, unspoken and unknown to the world."
  },
  AvgDialog_131215_Content_49 = {
    Text = "In your long, quiet life, you shall be the sole keeper of those memories."
  },
  AvgDialog_131215_Content_5 = {
    Text = "You follow Arachne irresistibly, walking along the silken path toward its end."
  },
  AvgDialog_131215_Content_50 = {
    Text = "The silent girl looks up, her hand tracing the cheek of puppet \"Arachne.\""
  },
  AvgDialog_131215_Content_51 = {
    Text = "\"Arachne\" stands, looking over her creations with tenderness."
  },
  AvgDialog_131215_Content_52 = {
    Text = "Go, my children. I shall watch over you from the loom of Fate forever."
  },
  AvgDialog_131215_Content_53 = {
    Text = "Those abandoned by eternity shall bloom, one by one, within your destinies."
  },
  AvgDialog_131215_Content_54 = {Text = "..."},
  AvgDialog_131215_Content_55 = {
    Text = "The stage darkens. With every step you take, the lights of the next act ignite."
  },
  AvgDialog_131215_Content_56 = {
    Text = "Sunlight never reached this place. No wind, no flowers, no clouds... in three long centuries, even the calendar ceased to exist."
  },
  AvgDialog_131215_Content_57 = {
    Text = "My lady, another of the Forsaken has arrived."
  },
  AvgDialog_131215_Content_58 = {
    Text = "A trumpet blares a florid melody. A Forsaken in ragged clothes enters the stage."
  },
  AvgDialog_131215_Content_59 = {
    Text = "The \"Nefraea\" puppet stands and walks to the center of the stage."
  },
  AvgDialog_131215_Content_6 = {
    Text = "Well, {Male=Mr.,Female=Miss} Keeper? Was the performance spectacular? Especially with that behind-the-scenes look?"
  },
  AvgDialog_131215_Content_60 = {
    Text = "Tell me, poor children... who are you, and where do you come from?"
  },
  AvgDialog_131215_Content_61 = {
    Text = "Goddess of Fate, forgive my insolence... but rage compels me to question you."
  },
  AvgDialog_131215_Content_62 = {
    Text = "I endured a thousand hardships to leave behind an epic written in blood and courage—a legacy meant to sail with my homeland to the edge of the universe."
  },
  AvgDialog_131215_Content_63 = {
    Text = "Why, great Goddess? Why cast us into this savage wasteland? Why dissolve those immortal melodies into dust?"
  },
  AvgDialog_131215_Content_64 = {
    Text = "My soldiers survived a brutal winter. We repelled the barbarians and defended our civilization, our history."
  },
  AvgDialog_131215_Content_65 = {
    Text = "In our darkest hour, the wounded offered their own flesh to feed their comrades... it was a victory of pure agony, my Goddess."
  },
  AvgDialog_131215_Content_66 = {
    Text = "When the enemy retreated, we wept with joy. At the feast, I poured strong spirits for every man who remained."
  },
  AvgDialog_131215_Content_67 = {
    Text = "But in that exact moment—before we could even raise a toast—our homes crumbled to ash, and our loved ones vanished into nothingness."
  },
  AvgDialog_131215_Content_68 = {
    Text = "<Shake:Beloved Goddess, would you not grant us even a single moment of joy?>"
  },
  AvgDialog_131215_Content_69 = {Text = "..."},
  AvgDialog_131215_Content_7 = {
    Text = "Nefraea has shed her manic stage persona. She turns back, looking at you with eager anticipation."
  },
  AvgDialog_131215_Content_70 = {
    Text = "\"Nefraea\" endures the puppets' endless wails. Two streaks of tears trace paths down her expressionless face."
  },
  AvgDialog_131215_Content_71 = {
    Text = "I hear you. I see you."
  },
  AvgDialog_131215_Content_72 = {
    Text = "Great civilizations crumble; magnificent art and architecture turn to ash. Soulmates forget one another and meet their violent end in terror."
  },
  AvgDialog_131215_Content_73 = {
    Text = "Only one \"correct\" fate remains. The countless \"errors\" born in that same moment surge into this savage Abyss. In this frozen time, the same play repeats every single day."
  },
  AvgDialog_131215_Content_74 = {
    Text = "How much longer must I watch this, sister? How much longer must I listen?"
  },
  AvgDialog_131215_Content_75 = {
    Text = "\"Nefraea\" draws a sharp breath and turns away from the audience."
  },
  AvgDialog_131215_Content_76 = {
    Text = "Fear not, my children. The suffering I wrought upon you... I shall be the one to end it."
  },
  AvgDialog_131215_Content_77 = {
    Text = "Rest here for now. One day, I will lead you out of this place and reclaim the destinies that are rightfully yours."
  },
  AvgDialog_131215_Content_78 = {
    Text = "In the name of Nefraea, Avenger of Fate, I give you my word..."
  },
  AvgDialog_131215_Content_79 = {Text = "..."},
  AvgDialog_131215_Content_8 = {
    Text = "Seeing your silence, she shakes her head in disappointment."
  },
  AvgDialog_131215_Content_80 = {
    Text = "La la la la... la la..."
  },
  AvgDialog_131215_Content_81 = {
    Text = "As the stage fades and the lights die, you catch a glimpse of the puppet's outstretched arms and the dark streaks upon its face."
  },
  AvgDialog_131215_Content_82 = {
    Text = "You remain silent. Only Nefraea hums the melody from the stage. Her voice is bright and clear, like a story told so many times that all emotion has been drained from it."
  },
  AvgDialog_131215_Content_83 = {
    Text = "Oh! One of my favorite acts is coming up! Hurry, sister!"
  },
  AvgDialog_131215_Content_84 = {
    Text = "Nefraea's voice rings with elation. She takes Arachne's hand and dashes toward the next stage."
  },
  AvgDialog_131215_Content_85 = {Text = "..."},
  AvgDialog_131215_Content_86 = {
    Text = "The lights ignite. There is no music, no dialogue—only a lone puppet at a spinning wheel on an empty stage."
  },
  AvgDialog_131215_Content_87 = {
    Text = "Creak, creak. The wheel turns, as if the day it stops will never come."
  },
  AvgDialog_131215_Content_88 = {
    Text = "...They dance. They sing. Creak—creak—"
  },
  AvgDialog_131215_Content_89 = {
    Text = "Sunlight bathes their faces. How joyful they are..."
  },
  AvgDialog_131215_Content_9 = {
    Text = "No applause? No tears? Silence is such an insult... and after I rehearsed for so long in the Abyssal Prison. A shame, really."
  },
  AvgDialog_131215_Content_90 = {
    Text = "The \"Arachne\" puppet hums a lullaby with its blank face. Her fingers turn the wheel at a steady, unhurried pace."
  },
  AvgDialog_131215_Content_91 = {
    Text = "It is a haunting rhythm—one look tells you that once begun, it will never change until the end of all things."
  },
  AvgDialog_131215_Content_92 = {
    Text = "The Goddess of Fate is nearly finished with her Great Web."
  },
  AvgDialog_131215_Content_93 = {
    Text = "The complete Web of Fate watches over everyone... they dance, they sing..."
  },
  AvgDialog_131215_Content_94 = {
    Text = "A massive web spreads across the stage. The loose threads of Fate spill past the edge of the platform."
  },
  AvgDialog_131215_Content_95 = {
    Text = "Every time the web nears completion, its outermost edges begin to melt away."
  },
  AvgDialog_131215_Content_96 = {
    Text = "Inky sludge and dark soot dissolve into nothingness. You know this sight all too well."
  },
  AvgDialog_131215_Content_97 = {
    Text = "Rejoice, my children, my people... the Goddess of Fate is nearly finished with her Great Web..."
  },
  AvgDialog_131215_Content_98 = {
    Text = "The puppet stares at the web, woven and erased in a cycle without end."
  },
  AvgDialog_131215_Content_99 = {
    Text = "Her voice does not tremble; her hands do not hesitate. She continues her gentle tune as the wheel turns, never stopping."
  },
  AvgDialog_131216_Content_1 = {Text = "Masquerade"},
  AvgDialog_131216_Content_10 = {
    Text = "A rather shameless double standard, Senior."
  },
  AvgDialog_131216_Content_11 = {
    Text = "Ahem... Making judgments that align with each person's character is a basic skill for an Investigator..."
  },
  AvgDialog_131216_Content_12 = {
    Text = "William pretends not to catch your jab and starts seriously looking for a worthy target to approach."
  },
  AvgDialog_131216_Content_13 = {
    Text = "I lost everything in that battle. My title, my family, my left leg... my life."
  },
  AvgDialog_131216_Content_14 = {
    Text = "Twenty years. A full twenty years. It has been a slow torture, my friend. Fate saw fit to let me live, leaving me to spend my remaining days atoning for my mistakes."
  },
  AvgDialog_131216_Content_15 = {
    Text = "I destroyed my own lineage with my own hands, but what does it matter now? Tell me, is there anything in this life more important than a drink?"
  },
  AvgDialog_131216_Content_16 = {Text = "..."},
  AvgDialog_131216_Content_17 = {
    Text = "Oh, darling, do you remember the cocktail the bartender made for us the last time we were here?"
  },
  AvgDialog_131216_Content_18 = {
    Text = "I'd wager you won't find a finer drink in all of Londinium. It was so precise, so elegant—it felt less like a recipe and more like a prophecy!"
  },
  AvgDialog_131216_Content_19 = {
    Text = "I was thinking how wonderful it would be if we could invite that bartender to our party next month."
  },
  AvgDialog_131216_Content_2 = {
    Text = "\"90 minutes past midnight, a 15-inch mask, 10 gallons of dream, 2 ounces of spirits—the only formula for happiness.\""
  },
  AvgDialog_131216_Content_20 = {Text = "..."},
  AvgDialog_131216_Content_21 = {Text = "Snap—"},
  AvgDialog_131216_Content_22 = {
    Text = "A sharp snap of fingers echoes like a firework beside your ear. You turn to find a face glowing with a radiant smile."
  },
  AvgDialog_131216_Content_23 = {
    Text = "Pardon the interruption, honored guests. Since you're discussing such fascinating topics, perhaps you'd like an equally fascinating drink to match?"
  },
  AvgDialog_131216_Content_24 = {
    Text = "Let's see a menu, William."
  },
  AvgDialog_131216_Content_25 = {
    Text = "William understands your look. Two people in unidentified uniforms sitting in a place like this without touching a drop of alcohol is a sure way to attract the wrong kind of attention."
  },
  AvgDialog_131216_Content_26 = {
    Text = "Seeing him search for a menu, the bartender shakes her head with a playful smile."
  },
  AvgDialog_131216_Content_27 = {
    Text = "A menu? How droll. How tedious. How... ordinary."
  },
  AvgDialog_131216_Content_28 = {
    Text = "A truly romantic establishment has no room for something so mundane."
  },
  AvgDialog_131216_Content_29 = {
    Text = "No menu? Then how are we supposed to order?"
  },
  AvgDialog_131216_Content_3 = {
    Text = "I've had the Midnight Masquerade's slogan memorized for years. Back in Kadath, it was the one place I wanted to visit more than anything."
  },
  AvgDialog_131216_Content_30 = {
    Text = "Every seat at the Midnight Masquerade is a private theater for the guest who occupies it. Here, you observe, you perform, and you savor..."
  },
  AvgDialog_131216_Content_31 = {
    Text = "From a library of infinite stories, I shall select the one that suits you best."
  },
  AvgDialog_131216_Content_32 = {
    Text = "Please, take a seat. The storyteller is ready."
  },
  AvgDialog_131216_Content_33 = {
    Text = "You and William exchange a glance before hesitantly taking seats at the bar."
  },
  AvgDialog_131216_Content_34 = {
    Text = "First, let's look at you—the stoic, fair-haired gentleman."
  },
  AvgDialog_131216_Content_35 = {
    Text = "The bartender leans in close. Under her scrutinizing gaze, William coughs softly and looks away, slightly uncomfortable."
  },
  AvgDialog_131216_Content_36 = {
    Text = "Ah... I see the fruits of grueling, daily discipline. Tenacity, composure, resilience, bravery, wisdom... A living legend, draped in floral tributes and glory."
  },
  AvgDialog_131216_Content_37 = {
    Text = "And yet, behind the praise and the halo lies... regret. A regret deeper and more agonizing than the fog that chokes this city."
  },
  AvgDialog_131216_Content_38 = {
    Text = "I see the tears that glisten unseen in the dead of night. I hear the vows whispered only to oneself."
  },
  AvgDialog_131216_Content_39 = {
    Text = "The light that once guided you through the dark has been extinguished, and with it, your world shattered... and shattered again."
  },
  AvgDialog_131216_Content_4 = {
    Text = "Don't you think Mythag's rules are a little too strict sometimes?"
  },
  AvgDialog_131216_Content_40 = {
    Text = "He thinks to himself: <Italic:If only I had worked harder. If only I were stronger... perhaps I could have woven a different fate for my dear friend.>"
  },
  AvgDialog_131216_Content_41 = {
    Text = "William's expression remains a mask of indifference, but you notice the veins bulging on the hand currently white-knuckling his glass."
  },
  AvgDialog_131216_Content_42 = {
    Text = "I can hear the sound of a world breaking. A little boy braves the pain, picking up the shards one by one, stitching them back together..."
  },
  AvgDialog_131216_Content_43 = {
    Text = "Through this long, brutal mending, the boy has finally become a man."
  },
  AvgDialog_131216_Content_44 = {
    Text = "Her voice is a low, melodic lilt as she plucks strangely shaped bottles from a shelf that seems to stretch into infinity, beginning her craft."
  },
  AvgDialog_131216_Content_45 = {
    Text = "Before long, she slides a glass of pale golden liquid toward William."
  },
  AvgDialog_131216_Content_46 = {
    Text = "Two ounces of whiskey, one ounce of white wine, and a base of painful resilience—two dashes of bitters."
  },
  AvgDialog_131216_Content_47 = {
    Text = "The \"Wayfinder.\" May you lead those who admire you toward the right path—just as <Italic:he> once did for you, the one you hold in highest regard."
  },
  AvgDialog_131216_Content_48 = {
    Text = "William accepts the golden drink, swirling it slowly as he studies the bartender with a piercing look."
  },
  AvgDialog_131216_Content_49 = {
    Text = "Everything you just said... how do you know all that?"
  },
  AvgDialog_131216_Content_5 = {
    Text = "I proposed banning Mythag students from entering such establishments without authorization precisely to prevent certain Keepers—the negligent kind—from burning through mission funds under the pretense of conducting investigations."
  },
  AvgDialog_131216_Content_50 = {
    Text = "A master bartender must know how to listen to the soul. That is a trade secret, my dear guest."
  },
  AvgDialog_131216_Content_51 = {
    Text = "The bartender dodges William's stare with the grace of a fawn. She presses a finger to her lips in a shushing gesture, then points directly at you."
  },
  AvgDialog_131216_Content_52 = {
    Text = "Now, for you..."
  },
  AvgDialog_131216_Content_53 = {
    Text = "I have a feeling this might be the most dangerous thing I've ever attempted—but no matter. I've always had a taste for adventure."
  },
  AvgDialog_131216_Content_54 = {
    Text = "She leans in close, staring intently into your eyes. You can almost hear the soft rhythm of her breath."
  },
  AvgDialog_131216_Content_55 = {
    Text = "Hmm... What am I looking at? A traveler from a far-off place? Or perhaps... a fallen deity, struggling through the mire of the mortal realm?"
  },
  AvgDialog_131216_Content_56 = {Text = "?!!"},
  AvgDialog_131216_Content_57 = {
    Text = "You instinctively lurch back, heart hammering against your ribs."
  },
  AvgDialog_131216_Content_58 = {
    Text = "There is no way an ordinary bartender would know that... Who—or what—are you?!"
  },
  AvgDialog_131216_Content_59 = {
    Text = "Rest assured, dear guest. In this bar, I am not the one with malicious intent."
  },
  AvgDialog_131216_Content_6 = {
    Text = "This particular Keeper did, after all, accumulate quite a record during their time as a student."
  },
  AvgDialog_131216_Content_60 = {
    Text = "You may have noticed that some of your \"old friends\" have just arrived behind you."
  },
  AvgDialog_131216_Content_61 = {
    Text = "%player%, watch behind."
  },
  AvgDialog_131216_Content_62 = {
    Text = "I feel them..."
  },
  AvgDialog_131216_Content_63 = {
    Text = "Alerted by the warning, you sense over a dozen sharp psychic ripples closing in rapidly from every direction."
  },
  AvgDialog_131216_Content_64 = {
    Text = "William moves to cover your back in perfect sync. You grip your Silver Key tightly, your eyes locked on the enigmatic bartender."
  },
  AvgDialog_131216_Content_65 = {
    Text = "The bartender sets down her glass and moves the bottles to a safe corner where they won't be broken in the fray."
  },
  AvgDialog_131216_Content_66 = {
    Text = "Easy there, %player%. They have been tracking you for some time. Here, at least, I can offer you some kind of help."
  },
  AvgDialog_131216_Content_67 = {
    Text = "You? Them? ..."
  },
  AvgDialog_131216_Content_68 = {
    Text = "Heh... Found you."
  },
  AvgDialog_131216_Content_69 = {
    Text = "This filthy place is no fit for a long stay, my little visitors from afar."
  },
  AvgDialog_131216_Content_7 = {
    Text = "Oh, but I seem to recall reading in Senior Fingal's file that his greatest hobby was stopping by the Midnight Masquerade for a drink after work..."
  },
  AvgDialog_131216_Content_70 = {
    Text = "Watch out! They're coming!"
  },
  AvgDialog_131216_Content_8 = {
    Text = "...And of course, an occasional rest is not entirely without merit."
  },
  AvgDialog_131216_Content_9 = {
    Text = "Besides, the Midnight Masquerade's membership list includes the elite of all Londinium. It's the ideal venue for gathering intelligence."
  },
  AvgDialog_131217_Content_1 = {
    Text = "The Authority of the Three Aeons settles within you, yet you keep your eyes closed."
  },
  AvgDialog_131217_Content_10 = {
    Text = "The spirit of contracts, business principles... a deal requires leverage. You know how this works, don't you?"
  },
  AvgDialog_131217_Content_11 = {
    Text = "\"N\" shakes his head, struggling to suppress his laughter."
  },
  AvgDialog_131217_Content_12 = {
    Text = "The good news is, you always have perfect leverage. A valiant guardian about to abandon {Male=his,Female=her} faith, drowning in the web of Fate—deceiving, cheating, utterly without principle... what a captivating scene!"
  },
  AvgDialog_131217_Content_13 = {
    Text = "I wouldn't miss the best seat in the house for the world."
  },
  AvgDialog_131217_Content_14 = {
    Text = "When did I ever say—"
  },
  AvgDialog_131217_Content_15 = {
    Text = "The Reveler has no patience for your questions. He weighs the debt you will owe in the future and wags a finger with a grin."
  },
  AvgDialog_131217_Content_16 = {
    Text = "Not so much a hint, as a small and sincere suggestion."
  },
  AvgDialog_131217_Content_17 = {
    Text = "Why resist Nefraea? Why not submit to her, %player%?"
  },
  AvgDialog_131217_Content_18 = {
    Text = "\"N\" smiles and leans toward you, as benevolent as a lawyer visiting a client in prison."
  },
  AvgDialog_131217_Content_19 = {
    Text = "You... what did you say? No, I could never—"
  },
  AvgDialog_131217_Content_2 = {
    Text = "Your consciousness dives deeper into the vast ocean of the mind, plunging into the boundless darkness, descending into the abyss within yourself."
  },
  AvgDialog_131217_Content_20 = {
    Text = "Ah, that's right. Never give up, never surrender, never accept Nefraea's crimes... old-fashioned, classic heroism."
  },
  AvgDialog_131217_Content_21 = {
    Text = "Hand us over to Nefraea, summon that dear <Italic:cousin> of yours, and return to the <Italic:palace> that belongs to you... beyond that, what else can you do, %player%?"
  },
  AvgDialog_131217_Content_22 = {
    Text = "I will give you a secret: since you cannot escape the net, why not open your arms and welcome it?"
  },
  AvgDialog_131217_Content_23 = {
    Text = "Stop dreaming, \"N.\" I could never..."
  },
  AvgDialog_131217_Content_24 = {
    Text = "Shh. Don't sell yourself short, darling."
  },
  AvgDialog_131217_Content_25 = {
    Text = "Don't forget, Arachne has woven your fate into the Great Web. You are already one of them."
  },
  AvgDialog_131217_Content_26 = {
    Text = "The Goddess of Fate gave you a key called Rapture. But have you ever wondered where that Gate faces, and where it leads?"
  },
  AvgDialog_131217_Content_27 = {
    Text = "Where the Gate faces... where it leads...?"
  },
  AvgDialog_131217_Content_28 = {
    Text = "I assumed Arachne was a hardworking, kind, and utterly unremarkable lady whose only talents were weaving and smiling. But she is far more interesting than I imagined."
  },
  AvgDialog_131217_Content_29 = {
    Text = "She wove a vast web for this stage, and from the moment you arrived in this world, that web began to unfold for you."
  },
  AvgDialog_131217_Content_3 = {
    Text = "You strain to open a mouth that doesn't exist, screaming in silent fury into the depths."
  },
  AvgDialog_131217_Content_30 = {
    Text = "To have such remarkable talent, yet waste it on something as foolish as keeping the world running... A pity, truly. What a waste."
  },
  AvgDialog_131217_Content_31 = {
    Text = "To step onto the stage of the Theater of Fate is to become a character. And every character has a life of their own."
  },
  AvgDialog_131217_Content_32 = {
    Text = "Fate compelled you to make that choice so that you might finally see it for what it is. You cannot see the threads themselves, but you now understand the intricate ways in which they are woven."
  },
  AvgDialog_131217_Content_33 = {
    Text = "These threads form a vast web. The slightest tremor in a single strand can bring the entire structure crashing down."
  },
  AvgDialog_131217_Content_34 = {
    Text = "This is Fate, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131217_Content_35 = {
    Text = "To perform, to deceive, to entertain... you carry those powers within you. The stage of Fate rarely grants time for rehearsal. When the moment comes, that power will support you."
  },
  AvgDialog_131217_Content_36 = {
    Text = "You cannot hide from the roles you were meant to play. Think, then perform, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131217_Content_37 = {Text = "\"Rapture.\""},
  AvgDialog_131217_Content_38 = {
    Text = "In your immediate future, \"Rapture\" is a key. It will unlock the secret lock before you."
  },
  AvgDialog_131217_Content_39 = {
    Text = "...No matter what happens, trust me. And trust yourself."
  },
  AvgDialog_131217_Content_4 = {Text = "\"N\"!"},
  AvgDialog_131217_Content_40 = {
    Text = "Return to the Theater of Fate. The key and the lock await you there, %player%."
  },
  AvgDialog_131217_Content_41 = {
    Text = "Arachne's words weave through your mind like silk threads, crossing and intertwining. At last, they converge into a vast, intricate web."
  },
  AvgDialog_131217_Content_42 = {
    Text = "You finally understand. From the very first meeting, Arachne has been speaking to you across time."
  },
  AvgDialog_131217_Content_43 = {
    Text = "You stare at the intricate web in amazement. Something vital is taking shape in your mind."
  },
  AvgDialog_131217_Content_44 = {
    Text = "Perform... deceive... entertain..."
  },
  AvgDialog_131217_Content_45 = {
    Text = "Ah, yes. Never try to make sense of anything. Simply enjoy! That is the only secret of Rapture."
  },
  AvgDialog_131217_Content_46 = {
    Text = "Joy and sorrow, good and evil—emotions and morality cease to exist. There is nothing but pleasure."
  },
  AvgDialog_131217_Content_47 = {
    Text = "Now, tell me... do you understand \"Rapture,\" Keeper?"
  },
  AvgDialog_131217_Content_48 = {
    Text = "\"N\"'s crimson smile fades from your mind. You see a mirror, and reflected in it is your own laughing face."
  },
  AvgDialog_131217_Content_49 = {
    Text = "Rapture...? Rapture..."
  },
  AvgDialog_131217_Content_5 = {
    Text = "Shh... you're too loud, Keeper."
  },
  AvgDialog_131217_Content_50 = {
    Text = "Hehehe... hahahaha. Yes! Rapture, my friend!"
  },
  AvgDialog_131217_Content_51 = {
    Text = "The most wondrous word in existence, the entire meaning of this dream..."
  },
  AvgDialog_131217_Content_52 = {
    Text = "As if catching a glimpse of the scene about to unfold, N's entire body trembles with delight. He presses a finger wreathed in dark mist against his own forehead."
  },
  AvgDialog_131217_Content_53 = {
    Text = "You are almost there. Only one step away. Think it through, then step into the web, Keeper."
  },
  AvgDialog_131217_Content_54 = {
    Text = "The truth of Rapture lies within."
  },
  AvgDialog_131217_Content_6 = {
    Text = "\"N\"'s phantasm remains. He appears in your mental space with ease, looking like the undisputed master of the realm."
  },
  AvgDialog_131217_Content_7 = {
    Text = "The \"Rapture\" Arachne spoke of... she meant you!"
  },
  AvgDialog_131217_Content_8 = {
    Text = "\"N,\" give me a hint..."
  },
  AvgDialog_131217_Content_9 = {
    Text = "A hint? Hahaha... what have I done to deserve such an insult?"
  },
  AvgDialog_131218_Content_10 = {
    Text = "You... All of you... what is happening?"
  },
  AvgDialog_131218_Content_11 = {
    Text = "The drunk, the young lady, the noble gentleman, the thug, the weary waiter, the beautiful bartender..."
  },
  AvgDialog_131218_Content_12 = {
    Text = "Every face in the bar—young, old, handsome, or plain—turns toward you in unison, their expressions as identical as carbon copies."
  },
  AvgDialog_131218_Content_13 = {
    Text = "They aren't individuals. They're more like..."
  },
  AvgDialog_131218_Content_14 = {
    Text = "Those who seemed so full of life just moments ago now stand before you like lifeless wooden mannequins."
  },
  AvgDialog_131218_Content_15 = {
    Text = "...More like puppets, caught in a web."
  },
  AvgDialog_131218_Content_16 = {
    Text = "I have heard much of your keen intuition, Mr. William."
  },
  AvgDialog_131218_Content_17 = {
    Text = "What you see before you are merely props on a stage—reflections in a mirror."
  },
  AvgDialog_131218_Content_18 = {
    Text = "Please excuse me. I cannot yet leave my web. I must use these vessels to speak with you."
  },
  AvgDialog_131218_Content_19 = {
    Text = "Welcome to my stage, Mr. William... and you, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131218_Content_2 = {
    Text = "It's over... but what on earth were those things?"
  },
  AvgDialog_131218_Content_20 = {
    Text = "Each word is delivered with unsettling precision; twenty distinct voices weave together into a single, cold thread of voice."
  },
  AvgDialog_131218_Content_21 = {
    Text = "Everyone in the room bows in perfect unison. The angle of their spines and the placement of their hands are mirrored with unnatural exactness."
  },
  AvgDialog_131218_Content_22 = {
    Text = "Your... stage? Just who are you?"
  },
  AvgDialog_131218_Content_23 = {
    Text = "I am the master of this place—and its prisoner."
  },
  AvgDialog_131218_Content_24 = {
    Text = "I imagine you have many questions."
  },
  AvgDialog_131218_Content_25 = {
    Text = "This place is no longer safe; their people will return soon. My maid will come to fetch you. Do not be alarmed when you see her."
  },
  AvgDialog_131218_Content_26 = {
    Text = "Once we meet face to face, I will answer everything."
  },
  AvgDialog_131218_Content_27 = {
    Text = "The moment those words leave her lips, the consciousness of the crowd seems to drain away in an instant."
  },
  AvgDialog_131218_Content_28 = {
    Text = "A gentleman's crystal glass freezes at his lips; a lady's open fan stills just below her chin; the bartender remains poised, glass held aloft."
  },
  AvgDialog_131218_Content_29 = {
    Text = "As if their strings have been cut all at once, everyone holds their final pose—wax figures frozen in place."
  },
  AvgDialog_131218_Content_3 = {
    Text = "Watch your back!!"
  },
  AvgDialog_131218_Content_30 = {
    Text = "You draw a slow breath and look around uneasily at the sea of \"puppets,\" each frozen with that same, unchanging smile."
  },
  AvgDialog_131218_Content_31 = {
    Text = "They did help me just now, but I still can't bring myself to fully trust them..."
  },
  AvgDialog_131218_Content_32 = {
    Text = "William, for everything we need to know... this \"Lady\" may be our best chance at answers."
  },
  AvgDialog_131218_Content_33 = {
    Text = "Even if it's dangerous, I think I have to go. It's just..."
  },
  AvgDialog_131218_Content_34 = {Text = "I know."},
  AvgDialog_131218_Content_35 = {
    Text = "Catching your eyes, William gives a quiet, knowing nod."
  },
  AvgDialog_131218_Content_36 = {
    Text = "I'll track the movements of those shadows out here. They're looking for you. I'll draw less attention moving around outside than you would."
  },
  AvgDialog_131218_Content_37 = {
    Text = "This \"Lady\" has unknown origins. If something goes wrong..."
  },
  AvgDialog_131218_Content_38 = {
    Text = "William taps the badge on his chest. Stranded together in this foreign world, your badges reach only each other."
  },
  AvgDialog_131218_Content_39 = {
    Text = "Understood... You too, William."
  },
  AvgDialog_131218_Content_4 = {
    Text = "A spike of pure adrenaline jolts you awake. You spin around to find a blade of solidified shadow hovering mere inches from your throat."
  },
  AvgDialog_131218_Content_40 = {
    Text = "The Lady understands your caution. Mr. William, this stage holds many dangers right now; please tread carefully. We will offer whatever assistance we can."
  },
  AvgDialog_131218_Content_41 = {
    Text = "Pale violet spiders converge from every corner of the bar, and a maid bearing spider-like features appears silently behind you all. After politely bowing to you, she walks toward the door."
  },
  AvgDialog_131218_Content_42 = {
    Text = "{Male=Mr.,Female=Miss} Keeper, please follow me. The Lady has been expecting you."
  },
  AvgDialog_131218_Content_5 = {Text = "Slash—"},
  AvgDialog_131218_Content_6 = {
    Text = "You slowly lower the arm shielding your face. The shadow has been sliced apart by someone behind you; black ichor sprays through the air, splattering across your clothes."
  },
  AvgDialog_131218_Content_7 = {
    Text = "Apologies for the fright."
  },
  AvgDialog_131218_Content_8 = {
    Text = "They have been hunting you. Within these walls, I can at least lend you a hand."
  },
  AvgDialog_131218_Content_9 = {
    Text = "Forgive me for taking the liberty of guiding you here without your consent."
  },
  AvgDialog_131219_Content_1 = {
    Text = "To be determined"
  },
  AvgDialog_131220_Content_1 = {
    Text = "Fly, Swan, Fly"
  },
  AvgDialog_131220_Content_10 = {
    Text = "You remember the rusted gate that groans whenever it moves, sounding like a grandfather's steady breath."
  },
  AvgDialog_131220_Content_11 = {
    Text = "The University of Londinium..."
  },
  AvgDialog_131220_Content_12 = {
    Text = "Within this familiar setting, you trace the unfamiliar name etched into the plaza's plaque."
  },
  AvgDialog_131220_Content_13 = {
    Text = "Every actor has a stage they love most. Even a campus built from memories is irreplaceable to you."
  },
  AvgDialog_131220_Content_14 = {
    Text = "Why create a place exactly like Mythag...?"
  },
  AvgDialog_131220_Content_15 = {
    Text = "I didn't create it; it simply belongs here. Like this city and this world, it is a piece of the Great Web."
  },
  AvgDialog_131220_Content_16 = {
    Text = "Don't look so far ahead, %player%. If you are on a stage, there is a reason for you to be here."
  },
  AvgDialog_131220_Content_17 = {
    Text = "Come to think of it, after all the time I've spent with Liz, I've never actually seen her perform live."
  },
  AvgDialog_131220_Content_18 = {
    Text = "You look around the familiar square, your fingers brushing against the grass."
  },
  AvgDialog_131220_Content_19 = {
    Text = "The most beautiful moments in life are those when you don't even realize you're smiling."
  },
  AvgDialog_131220_Content_2 = {
    Text = "This is a rare treat. Even the cheapest ticket for this troupe would normally cost me two months' salary."
  },
  AvgDialog_131220_Content_20 = {
    Text = "Oh... sorry."
  },
  AvgDialog_131220_Content_21 = {
    Text = "Thinking about Mythag?"
  },
  AvgDialog_131220_Content_22 = {
    Text = "We held so many performances in this plaza. Back then, it was packed with Mythag students, just like this."
  },
  AvgDialog_131220_Content_23 = {
    Text = "Many Awakeners are masters of their craft. Some were reluctant to perform at first, so the faculty and I had to find ways to convince them..."
  },
  AvgDialog_131220_Content_24 = {
    Text = "Eventually, many of them started volunteering to put on shows for their peers."
  },
  AvgDialog_131220_Content_25 = {
    Text = "Liz's dancing, Tinct's ballads, Hameln's symphonies, Horla's poetry, Sanga's sculptures..."
  },
  AvgDialog_131220_Content_26 = {
    Text = "I wonder if life at Mythag ever went back to the way it was after I left..."
  },
  AvgDialog_131220_Content_27 = {
    Text = "The curtain just moved! Miss Elizabeth is about to make her entrance!"
  },
  AvgDialog_131220_Content_28 = {
    Text = "You shake your head, driving the melancholy from your mind."
  },
  AvgDialog_131220_Content_29 = {
    Text = "Regardless, seeing Liz dance again in this distant world is something to be grateful for."
  },
  AvgDialog_131220_Content_3 = {
    Text = "I heard Lady Sorel is personally sponsoring this charity performance! If only every noble in this city were so generous."
  },
  AvgDialog_131220_Content_30 = {
    Text = "Once this is over, if there's time, I'd like to sit down and truly talk with them."
  },
  AvgDialog_131220_Content_31 = {
    Text = "Ladies and gentlemen... welcome to our performance!"
  },
  AvgDialog_131220_Content_32 = {
    Text = "The Cycnus Dance Troupe—a name as sacred as it is untouchable! Today, the most elegant white swan of Londinium alights before the public for the very first time!"
  },
  AvgDialog_131220_Content_33 = {
    Text = "Thank you for your patience. Our performers are ready. A spectacular show is about to begin!"
  },
  AvgDialog_131220_Content_34 = {
    Text = "At the announcer's sharp snap, the lights die. Spotlights converge on the center of the stage."
  },
  AvgDialog_131220_Content_35 = {
    Text = "Next, please enjoy \"Swan's Flight,\" performed by Miss Elizabeth Salle!"
  },
  AvgDialog_131220_Content_36 = {
    Text = "Amidst thunderous applause and cheers, the curtain slowly draws open—"
  },
  AvgDialog_131220_Content_37 = {Text = "!!!!"},
  AvgDialog_131220_Content_38 = {
    Text = "You have seen Liz many times."
  },
  AvgDialog_131220_Content_39 = {
    Text = "In the ceremonial hall of Mythag, she pirouettes for you alone."
  },
  AvgDialog_131220_Content_4 = {
    Text = "I don't understand it, but I'm not missing an opportunity like this."
  },
  AvgDialog_131220_Content_40 = {
    Text = "Beneath the stars of Londinium, her tiptoes brushed against fireflies dancing in the night."
  },
  AvgDialog_131220_Content_41 = {
    Text = "In the breeze of Charing Cross Road, her skirt billowed like a blazing flame."
  },
  AvgDialog_131220_Content_42 = {
    Text = "But today, on this foreign stage, she appears in a way you never imagined."
  },
  AvgDialog_131220_Content_43 = {
    Text = "The prima ballerina, the most dazzling firework in the city, is impaled. Black spikes pierce her throat, her arms, her chest, and her arched feet—tearing through the body that once commanded the dance."
  },
  AvgDialog_131220_Content_44 = {
    Text = "Blood splatters against the backdrop, forming a pair of crimson wings behind her. Violent red streaks mar her calm, serene smile."
  },
  AvgDialog_131220_Content_45 = {
    Text = "The crowd falls into a deathly silence. Wind sweeps across the plaza, fluttering her black-and-green tutu like an eternally burning flame."
  },
  AvgDialog_131220_Content_46 = {
    Text = "In this moment, you realize: if death is inevitable, this is exactly how Liz would choose to meet it."
  },
  AvgDialog_131220_Content_47 = {
    Text = "She has given her final curtain call with her own life. Her form is frozen in a beautiful leap, like a soaring black swan."
  },
  AvgDialog_131220_Content_48 = {
    Text = "Behold, Miss Elizabeth's ending pose... how elegant, how graceful!"
  },
  AvgDialog_131220_Content_49 = {
    Text = "Enjoy the view, my dear audience! Witnessing this is the greatest honor of your lives."
  },
  AvgDialog_131220_Content_5 = {
    Text = "Thirty years... I haven't been back to a theater in thirty years."
  },
  AvgDialog_131220_Content_50 = {
    Text = "You watch as the announcer's face tears in half. The lifeless mask of the middle-aged man melts away like sludge, revealing Nefraea's eyes, wide with elation."
  },
  AvgDialog_131220_Content_51 = {
    Text = "Amidst the panicked screams and the stampede of the crowd, her shrill laughter pierces your ears like a venomous needle."
  },
  AvgDialog_131220_Content_52 = {Text = "LIZ!!"},
  AvgDialog_131220_Content_53 = {
    Text = "You shove through the terrified crowd and rush to the stage."
  },
  AvgDialog_131220_Content_54 = {
    Text = "Oh? Such a clever guest. How did you know this performance had a second act?"
  },
  AvgDialog_131220_Content_55 = {
    Text = "Those who stayed behind suddenly converge on you. Their bodies burst apart as they run, and relentless black spider-squires crawl out from the remains."
  },
  AvgDialog_131220_Content_56 = {
    Text = "On the stage, Liz's body slides off the spikes. She is a work of art crafted by a heretic, marked by cruel hollows and vivid red."
  },
  AvgDialog_131220_Content_57 = {
    Text = "Bloody footprints extend from the center of the stage. Liz walks toward you, her face painted in a ghastly, stunning mask of gore that leaves you breathless."
  },
  AvgDialog_131220_Content_58 = {
    Text = "She looks up at you. Her hollow, bleeding eyes remind you of a masterpiece destined for the ages."
  },
  AvgDialog_131220_Content_59 = {
    Text = "Now, time to dance with your old friend... {Male=Mr.,Female=Miss} Keeper!"
  },
  AvgDialog_131220_Content_6 = {
    Text = "Ballet is the purest dance on earth. Only those who have performed it truly understand the beauty of that brutal elegance!"
  },
  AvgDialog_131220_Content_7 = {
    Text = "Seeing Miss Elizabeth perform live is something I never even dreamed of..."
  },
  AvgDialog_131220_Content_8 = {
    Text = "The ambient noise of the crowd fades into a distant hum."
  },
  AvgDialog_131220_Content_9 = {
    Text = "You remember this meadow, that lake. You remember the varied heights of the campus buildings and the sculpture staring resolutely toward the horizon."
  },
  AvgDialog_131221_Content_1 = {Text = "Act Two"},
  AvgDialog_131221_Content_10 = {
    Text = "I am but a prisoner of Fate; this is a duty I have no choice but to uphold."
  },
  AvgDialog_131221_Content_11 = {
    Text = "For someone who manipulates the destinies of countless worlds, perhaps \"judge\" or \"warden\" of Fate would be a more fitting title?"
  },
  AvgDialog_131221_Content_12 = {
    Text = "In this place, there is no difference between a jailer and a prisoner."
  },
  AvgDialog_131221_Content_13 = {
    Text = "Mr. William, has your journey been a comfortable one?"
  },
  AvgDialog_131221_Content_14 = {
    Text = "Thanks to your maid's help. If I had been left to my own devices, evading those squires lurking in the shadows would have cost me far more."
  },
  AvgDialog_131221_Content_15 = {
    Text = "Nefraea... you ran into her people again?"
  },
  AvgDialog_131221_Content_16 = {
    Text = "William nods solemnly."
  },
  AvgDialog_131221_Content_17 = {
    Text = "When we were separated, I came across some passersby who seemed... off. I tailed them for a while and caught fragments of their conversation."
  },
  AvgDialog_131221_Content_18 = {
    Text = "They are searching for things they call \"Puppets.\""
  },
  AvgDialog_131221_Content_19 = {
    Text = "I suspect that the pollution of the stage's fate you mentioned earlier might only be a preliminary measure."
  },
  AvgDialog_131221_Content_2 = {
    Text = "Quite a spectacle..."
  },
  AvgDialog_131221_Content_20 = {
    Text = "Those \"Puppets\" are their true objective."
  },
  AvgDialog_131221_Content_21 = {
    Text = "My sister has hidden her own Threads of Fate along with those of her squires; I cannot perceive them easily. This is a vital piece of intelligence, Mr. William."
  },
  AvgDialog_131221_Content_22 = {
    Text = "For the next phase, I'll be coming with you—"
  },
  AvgDialog_131221_Content_23 = {Text = "No!"},
  AvgDialog_131221_Content_24 = {
    Text = "No, you must stay! Splitting up before was a necessity, but I won't risk a repeat of what happened at Remouahe."
  },
  AvgDialog_131221_Content_25 = {
    Text = "The Keeper is right. My maid will treat the toxins in your system. Until you are fully recovered, please remain in the theater to rest."
  },
  AvgDialog_131221_Content_26 = {
    Text = "The day we truly require your strength is coming soon."
  },
  AvgDialog_131221_Content_27 = {
    Text = "Arachne's words fall like a gentle verdict, effortlessly piercing through flesh and soul to settle within the weave of William's fate."
  },
  AvgDialog_131221_Content_28 = {
    Text = "William glances at the blood seeping through his bandages and gives a slow nod."
  },
  AvgDialog_131221_Content_29 = {
    Text = "If I went now, I would only be a burden. Rest assured, I will ensure I am ready when that day comes."
  },
  AvgDialog_131221_Content_3 = {
    Text = "<Shake:Cough, cough...>"
  },
  AvgDialog_131221_Content_30 = {
    Text = "Arachne offers a small smile and extends her hand. One, two... then countless spiders crawl from her sleeves, descending to the floor along silken threads."
  },
  AvgDialog_131221_Content_31 = {
    Text = "The spiders drop like rain, converging and swarming together. The mass of arachnids overlaps into a human silhouette as color and light cling to the shifting form."
  },
  AvgDialog_131221_Content_32 = {
    Text = "Within moments, a second, identical Arachne stands before you."
  },
  AvgDialog_131221_Content_33 = {
    Text = "Follow me, {Male=Mr.,Female=Miss} Keeper. I believe the time for a face-to-face meeting with my sister is at hand."
  },
  AvgDialog_131221_Content_34 = {Text = "..."},
  AvgDialog_131221_Content_35 = {
    Text = "There are many shops in this city that I adore, but like you, I find this place to be one of my favorites."
  },
  AvgDialog_131221_Content_36 = {
    Text = "You sit in your usual spot at the Midnight Masquerade, brow furrowed as you watch Arachne study her surroundings."
  },
  AvgDialog_131221_Content_37 = {
    Text = "So what exactly are you right now? A puppet? A decoy? Some mysterious machine made of a bunch of spiders so the real you can cut class?"
  },
  AvgDialog_131221_Content_38 = {
    Text = "Essentially, the 'me' here and the 'me' in the theater are the same Fate; we are two distinct experiences unfolding in the same moment."
  },
  AvgDialog_131221_Content_39 = {
    Text = "Most of my power must remain in the theater to maintain the Great Web. Beyond that, there is no difference between us. Don't let suspicion spoil the mood, Keeper."
  },
  AvgDialog_131221_Content_4 = {
    Text = "The sound agitates his wound. William clutches his bandaged abdomen, unable to suppress a sharp fit of coughing."
  },
  AvgDialog_131221_Content_40 = {
    Text = "Arachne offers a calm smile, the ice clinking softly in her glass as she swirls her drink."
  },
  AvgDialog_131221_Content_41 = {
    Text = "Did you know this establishment hosts a masquerade every month? Every guest who enters is required to wear their most interesting mask."
  },
  AvgDialog_131221_Content_42 = {
    Text = "High society usually makes this place droll, but on that one night, it becomes the most fascinating corner of the city."
  },
  AvgDialog_131221_Content_43 = {
    Text = "Perhaps for the next masquerade, I should set everything aside and truly experience it."
  },
  AvgDialog_131221_Content_44 = {
    Text = "I thought someone who could see the entire tapestry of Fate would lose all interest in the future."
  },
  AvgDialog_131221_Content_45 = {
    Text = "That is true, %player%. However, I discovered a way to ward off boredom a long time ago."
  },
  AvgDialog_131221_Content_46 = {
    Text = "Sometimes I step out from behind the curtain and onto the very stage I created, transforming myself into one of the characters."
  },
  AvgDialog_131221_Content_47 = {
    Text = "I blind myself to my own foresight and surrender to the performance. I let myself feel the flow of time and the shifting of destiny..."
  },
  AvgDialog_131221_Content_48 = {
    Text = "It is a rare moment of rest. Such opportunities are few, so I cherish each one like a sacred holiday."
  },
  AvgDialog_131221_Content_49 = {
    Text = "Arachne speaks while watching the lavish guests and attentive servers with genuine interest. The bar's amber light dances in her eyes."
  },
  AvgDialog_131221_Content_5 = {
    Text = "William?! You're hurt!"
  },
  AvgDialog_131221_Content_50 = {
    Text = "Even so... aren't we supposed to be hunting for those \"Puppets\"? Why are we here?"
  },
  AvgDialog_131221_Content_51 = {
    Text = "One of them is right here. You will see her soon... or rather, you already have."
  },
  AvgDialog_131221_Content_52 = {
    Text = "Hello there, dear customers."
  },
  AvgDialog_131221_Content_53 = {
    Text = "Her voice is smooth as honey. Her fingers look as though they were carved from fine porcelain. The bright scent of jasmine and mimosa clings to her bare neck, and her eyes scintillate with a piercing, all-seeing light."
  },
  AvgDialog_131221_Content_54 = {
    Text = "Ah, I remember you, the elegant %player%."
  },
  AvgDialog_131221_Content_55 = {
    Text = "Monsters in the shadows, a dazzling silver radiance... what a magnificent heroic epic!"
  },
  AvgDialog_131221_Content_56 = {
    Text = "Honestly, while you were away, the Midnight Masquerade made quite a profit off your story. We owe you royalties—at the very least, let us buy you a drink."
  },
  AvgDialog_131221_Content_57 = {
    Text = "It's you... I'll pass on the drink for now, but could you get one for my friend here?"
  },
  AvgDialog_131221_Content_58 = {
    Text = "I've already got a name for it: \"The Solo Act.\""
  },
  AvgDialog_131221_Content_59 = {
    Text = "A fine name. As for whether it suits your friend... I'll have to take a closer look."
  },
  AvgDialog_131221_Content_6 = {
    Text = "Led by Arachne, you step through the inconspicuous wall beside the Hvatz café."
  },
  AvgDialog_131221_Content_60 = {
    Text = "The Puppet known as \"Romance\" leans over the bar, staring intently into Arachne's eyes."
  },
  AvgDialog_131221_Content_61 = {
    Text = "The humble Creator remains immersed in her own performance. Arachne smiles and meets her gaze."
  },
  AvgDialog_131221_Content_62 = {
    Text = "Oh, what a pair of soulful eyes you have, my lady."
  },
  AvgDialog_131221_Content_63 = {
    Text = "They are like a vast, unfathomable ocean. Buried in those unseen depths are secrets no soul has ever known."
  },
  AvgDialog_131221_Content_64 = {
    Text = "This ocean swallows every raging wave. No matter how great the storm, the surface remains as calm as it has been since the dawn of time."
  },
  AvgDialog_131221_Content_65 = {
    Text = "Time flows, stars shift. Mountains crumble into fields, and seas turn to meadows..."
  },
  AvgDialog_131221_Content_66 = {
    Text = "But beneath all this change... what has this ocean cast aside?"
  },
  AvgDialog_131221_Content_67 = {
    Text = "The bartender sits across from Arachne and tilts her chin up. Her long nails rest naturally against Arachne's carotid artery."
  },
  AvgDialog_131221_Content_68 = {
    Text = "What are you..."
  },
  AvgDialog_131221_Content_69 = {
    Text = "Goddess of Fate, the great Arachne. How elegant you are when you toy with destiny. I truly envy them—the ones you chose, the ones you kept."
  },
  AvgDialog_131221_Content_7 = {
    Text = "As you return to the theater stage, you immediately notice William, sitting alone in the audience."
  },
  AvgDialog_131221_Content_70 = {
    Text = "Too bad... some of us were born only to be cast away."
  },
  AvgDialog_131221_Content_71 = {
    Text = "...It seems I won't get to taste that drink today after all."
  },
  AvgDialog_131221_Content_72 = {
    Text = "Arachne makes no move to pull away from that menacing hand. She sighs softly, as if mourning distant memories... or perhaps just the drink she'll never have."
  },
  AvgDialog_131221_Content_73 = {
    Text = "You can pollute the threads of these Puppets to cloud my vision, Nefraea, but it is futile. You do not have the power to control Fate."
  },
  AvgDialog_131221_Content_74 = {
    Text = "Like a doll made of melting black cream, the bartender's skin sloughs off her body in a muddy heap."
  },
  AvgDialog_131221_Content_75 = {
    Text = "Beneath the muck, a familiar face is revealed."
  },
  AvgDialog_131221_Content_76 = {Text = "It's you?!"},
  AvgDialog_131221_Content_77 = {
    Text = "My dear sister. You have so few Dimensional Embers left to burn."
  },
  AvgDialog_131221_Content_78 = {
    Text = "I'd love to have a proper heart-to-heart, but for now, I'll let my little spiders welcome you instead."
  },
  AvgDialog_131221_Content_79 = {
    Text = "Watch your back!"
  },
  AvgDialog_131221_Content_8 = {
    Text = "It's just a scratch."
  },
  AvgDialog_131221_Content_9 = {
    Text = "I witnessed the fate that unfolded on that stage. I believe someone owes you a debt of gratitude for your efforts, Lady Arachne."
  },
  AvgDialog_131222_Content_1 = {
    Text = "The Manor's Invitation"
  },
  AvgDialog_131222_Content_10 = {
    Text = "An invitation? I have lived my entire life without once having to show a scrap of paper to enter a room."
  },
  AvgDialog_131222_Content_100 = {
    Text = "Sorel narrows her eyes, a rare flash of anger igniting within them."
  },
  AvgDialog_131222_Content_101 = {
    Text = "I don't know what you've done to Karen, but it doesn't matter. Your price has already been set."
  },
  AvgDialog_131222_Content_102 = {
    Text = "Ah, a failed negotiation. How tragic, Lady Sorel. It seems I'll have to extract the answers from your corpse."
  },
  AvgDialog_131222_Content_103 = {
    Text = "Sorel scowls, sensing the powerful psychic ripples emanating from her opponent. Inky shadows close in rapidly, sealing off every escape."
  },
  AvgDialog_131222_Content_105 = {
    Text = "Just as a blade lunges from the dark, a streak of silver light shoots into the room like a falling star."
  },
  AvgDialog_131222_Content_106 = {
    Text = "Sorel, get back!"
  },
  AvgDialog_131222_Content_11 = {
    Text = "Move aside."
  },
  AvgDialog_131222_Content_12 = {
    Text = "My apologies, sir. Tonight's banquet is strictly for those with an invitation."
  },
  AvgDialog_131222_Content_13 = {
    Text = "You blind fool. Do you have any idea who I am?"
  },
  AvgDialog_131222_Content_14 = {
    Text = "That is not my concern, sir."
  },
  AvgDialog_131222_Content_15 = {
    Text = "You sound like a local, sir. I assume you can understand plain English."
  },
  AvgDialog_131222_Content_16 = {
    Text = "Why, you—!! Fine! I'll make sure you and the lady of this house pay for this!"
  },
  AvgDialog_131222_Content_17 = {
    Text = "Arachne watches the noble storm off and shakes her head."
  },
  AvgDialog_131222_Content_18 = {
    Text = "It seems gaining entry to this manor will be more difficult than I anticipated."
  },
  AvgDialog_131222_Content_19 = {
    Text = "If I could find that maid who sells bathwater, maybe I could buy a couple of invites from her..."
  },
  AvgDialog_131222_Content_2 = {
    Text = "The Duke of Cadrin's Manor stands as the most prestigious social venue in old Londinium."
  },
  AvgDialog_131222_Content_20 = {
    Text = "Rare sea salts from Thira, lavender, citrus, cloves, and rose petals from southern Constan..."
  },
  AvgDialog_131222_Content_21 = {
    Text = "Bathwater like that is far more precious—and harder to find—than a simple invitation."
  },
  AvgDialog_131222_Content_22 = {Text = "???"},
  AvgDialog_131222_Content_23 = {
    Text = "I was just talking to myself... how could you possibly know what happened in my dreams?"
  },
  AvgDialog_131222_Content_24 = {
    Text = "Though your own fate remains hidden from me, I have always watched the destinies of those around you."
  },
  AvgDialog_131222_Content_25 = {
    Text = "If you control their fates, surely you can manage something as small as manifesting two invitations? Even if the ripples are complicated?"
  },
  AvgDialog_131222_Content_26 = {
    Text = "You have already seen the chaos that follows a shift in destiny. Fate is no toy; it is a glass house that requires my constant, careful maintenance."
  },
  AvgDialog_131222_Content_27 = {
    Text = "Every choice I make requires immense focus and dimensional embers. A single oversight could lead to total collapse."
  },
  AvgDialog_131222_Content_28 = {
    Text = "Besides... as I've said before, being a spectator is often much more entertaining than being the playwright."
  },
  AvgDialog_131222_Content_29 = {
    Text = "I'm looking forward to your performance, %player%."
  },
  AvgDialog_131222_Content_3 = {
    Text = "In his prime, the Prime Minister and cabinet officials sat at garden tables here, penning decrees that shaped the very fate of the empire."
  },
  AvgDialog_131222_Content_30 = {
    Text = "But I don't know the first thing about this place..."
  },
  AvgDialog_131222_Content_31 = {
    Text = "To perform, to deceive, to entertain... you carry those powers within you. The stage of Fate rarely grants time for rehearsal. When the moment comes, that power will support you."
  },
  AvgDialog_131222_Content_32 = {
    Text = "You cannot hide from the roles you were meant to play. Think, then perform, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131222_Content_33 = {
    Text = "A sharp seriousness flickers behind Arachne's polite smile. She speaks to you, yet her eyes seem to pierce through your form, addressing a future far beyond this moment."
  },
  AvgDialog_131222_Content_34 = {
    Text = "Her words carry the weight of a command you cannot refuse. A command from your Fate. You look down, pondering her meaning."
  },
  AvgDialog_131222_Content_35 = {
    Text = "To perform, to deceive, to entertain... you mean, the Authority of N?"
  },
  AvgDialog_131222_Content_36 = {
    Text = "But since the final battle with Tohuwabohu, I've lost my connection to the power of the Three Aeons..."
  },
  AvgDialog_131222_Content_37 = {
    Text = "Their power slumbers, yes. But the Authority is more than just raw power."
  },
  AvgDialog_131222_Content_38 = {
    Text = "Authority is more than power..."
  },
  AvgDialog_131222_Content_39 = {
    Text = "As you mull over her words, a spark of inspiration illuminates your mind."
  },
  AvgDialog_131222_Content_4 = {
    Text = "In his downfall, the sold manor stood as a silent witness, watching his hunched figure being led toward the gallows."
  },
  AvgDialog_131222_Content_40 = {
    Text = "You pluck two fallen maple leaves from the grass. Their veins feel almost like printed parchment under your fingertips."
  },
  AvgDialog_131222_Content_41 = {
    Text = "You said everyone in this world carries a Silver Core. That means their minds are open to the influence of my Silver Key... right?"
  },
  AvgDialog_131222_Content_42 = {
    Text = "Arachne offers a smile and falls into step beside you as you approach the manor gates."
  },
  AvgDialog_131222_Content_43 = {
    Text = "Good evening. Please show your—"
  },
  AvgDialog_131222_Content_44 = {
    Text = "What a magnificent estate. We are honored to accept Lady Sorel's invitation."
  },
  AvgDialog_131222_Content_45 = {
    Text = "As you hand the guard the maple leaves, the Silver Key glows faintly in your pocket. You easily lock onto the guard's point of light."
  },
  AvgDialog_131222_Content_46 = {
    Text = "Simultaneously, another light flickers in your mind. At the meeting point of those two points of light, the phantom of Clementine appears, swaying her pendulum."
  },
  AvgDialog_131222_Content_47 = {
    Text = "C-Count Huey..."
  },
  AvgDialog_131222_Content_48 = {
    Text = "Ah! Count Huey, Countess! Cadrin Manor is honored by your presence."
  },
  AvgDialog_131222_Content_49 = {
    Text = "Under the guard's respectful stare, you step onto the smooth cobblestone path of the estate."
  },
  AvgDialog_131222_Content_5 = {
    Text = "After a brief period of mourning, the manor fills once more with distinguished guests. Its new owner holds salon after salon, loudly proclaiming the estate's return to glory."
  },
  AvgDialog_131222_Content_50 = {
    Text = "How does it feel, {Male=Mr.,Female=Miss} Keeper?"
  },
  AvgDialog_131222_Content_51 = {
    Text = "I still don't quite grasp what you mean by \"Authority,\" but I definitely felt something change just now..."
  },
  AvgDialog_131222_Content_52 = {
    Text = "It was... a thrill. A rush of excitement from deceiving them—from making them believe I was the Count. I've never felt anything like it. It was as if the emotion didn't even belong to me."
  },
  AvgDialog_131222_Content_53 = {
    Text = "You open your hand, letting the two maple leaves slip from your fingers to dance away on the breeze."
  },
  AvgDialog_131222_Content_54 = {
    Text = "As you and Arachne enter the manor with composed smiles, you could swear an amused chuckle echoes from deep within your own chest."
  },
  AvgDialog_131222_Content_55 = {Text = "..."},
  AvgDialog_131222_Content_56 = {
    Text = "It's truly remarkable to see someone achieve so much at such a young age."
  },
  AvgDialog_131222_Content_57 = {
    Text = "Once these trade talks conclude, the ties between this city's business and political elite will be completely transformed. This is a rare opportunity..."
  },
  AvgDialog_131222_Content_58 = {
    Text = "The chief went through hell to get these invites. We need to get some perfect shots. Keep the gear ready and follow me—we need to get as close to the front as possible..."
  },
  AvgDialog_131222_Content_59 = {
    Text = "She's here! She's coming out!!"
  },
  AvgDialog_131222_Content_6 = {
    Text = "Good evening. Here is my invitation."
  },
  AvgDialog_131222_Content_60 = {
    Text = "At the young man's shout, the crowd surges toward the opening doors."
  },
  AvgDialog_131222_Content_61 = {
    Text = "A lady in a crimson gown appears, looking like a blooming rose. Her presence makes the lavish decor and the bustling crowd seem dull by comparison."
  },
  AvgDialog_131222_Content_62 = {
    Text = "Sorel wears a flawless, practiced smile, waving to the guests with effortless poise."
  },
  AvgDialog_131222_Content_63 = {
    Text = "So, she's the current owner of the manor..."
  },
  AvgDialog_131222_Content_64 = {
    Text = "Ladies and gentlemen, welcome. At today's salon, several of our city's commercial districts will find their new masters."
  },
  AvgDialog_131222_Content_65 = {
    Text = "And, of course, our noble friends will receive the benefits they so rightly deserve."
  },
  AvgDialog_131222_Content_66 = {
    Text = "I trust this will be a most splendid and delightful evening."
  },
  AvgDialog_131222_Content_67 = {
    Text = "My chefs have prepared the finest pastries and champagne. Please, enjoy yourselves for a moment. Our dinner service will begin shortly."
  },
  AvgDialog_131222_Content_68 = {
    Text = "Sorel scans the room with a smile before turning to head upstairs."
  },
  AvgDialog_131222_Content_69 = {
    Text = "Sor... Sorel! Karen!"
  },
  AvgDialog_131222_Content_7 = {
    Text = "Ah, welcome, Mr. Fugen. The Lady is expecting you. Please, go right in."
  },
  AvgDialog_131222_Content_70 = {
    Text = "Your voice is swallowed by the chatter and cheers of the crowd."
  },
  AvgDialog_131222_Content_71 = {
    Text = "Lady Sorel! Lady Sorel! How do you plan to divide the commercial districts? Will this affect..."
  },
  AvgDialog_131222_Content_72 = {
    Text = "Shh, Mr. Reporter. I've only just returned from business. Once I've had a chance to change, I will answer all of your questions."
  },
  AvgDialog_131222_Content_73 = {
    Text = "Sorel offers a final wave before disappearing into the private quarters on the upper floor."
  },
  AvgDialog_131222_Content_74 = {
    Text = "Looks like we'll have to wait for her to come back out."
  },
  AvgDialog_131222_Content_75 = {
    Text = "Did you notice the maid standing beside Sorel?"
  },
  AvgDialog_131222_Content_76 = {
    Text = "Karen? Yes, she didn't seem to hear me either... wait, what are you saying?"
  },
  AvgDialog_131222_Content_77 = {
    Text = "You recall Karen's aura. It felt entirely wrong—even accounting for different dimensions, that presence couldn't possibly belong to the girl you knew."
  },
  AvgDialog_131222_Content_78 = {
    Text = "I sense a path of fate within her that does not belong on this stage. Her destiny has been polluted."
  },
  AvgDialog_131222_Content_79 = {
    Text = "Lady Sorel is in danger!"
  },
  AvgDialog_131222_Content_8 = {
    Text = "Hmph. When money-grubbing merchants like Fugen can waltz into the old Duke's residence, you know the grace of Londinium has truly vanished..."
  },
  AvgDialog_131222_Content_80 = {
    Text = "You shove through the crowd, finding a hidden service staircase at the rear of the building."
  },
  AvgDialog_131222_Content_81 = {
    Text = "My apologies, {Male=sir,Female=lady}, but this is Lady Sorel's private residence. No unauthorized—"
  },
  AvgDialog_131222_Content_82 = {
    Text = "Lady Sorel invited me here to discuss an urgent matter in private."
  },
  AvgDialog_131222_Content_83 = {
    Text = "You pull out a napkin you just snatched from a table. With a flash of silver, a Mystia Treaty Committee officer ID appears in your hand."
  },
  AvgDialog_131222_Content_84 = {
    Text = "Forgive me, {Male=sir,Female=lady}, I didn't know... Lady Sorel is just upstairs. I can lead the—"
  },
  AvgDialog_131222_Content_85 = {
    Text = "This is a confidential mission. Do not tell anyone I was here."
  },
  AvgDialog_131222_Content_86 = {
    Text = "You dash up the stairs before the officer can utter another word."
  },
  AvgDialog_131222_Content_87 = {Text = "..."},
  AvgDialog_131222_Content_88 = {
    Text = "Your gown is ready, Lady Sorel!"
  },
  AvgDialog_131222_Content_89 = {
    Text = "Londinium is a wilderness. The politicians and merchants are the hyenas of this city..."
  },
  AvgDialog_131222_Content_9 = {
    Text = "Good evening, sir. Please present your invitation."
  },
  AvgDialog_131222_Content_90 = {
    Text = "Sorel picks up the attire Karen prepared. Sunlight filters through the red gauze, casting a vivid crimson shadow across the lavish bedroom."
  },
  AvgDialog_131222_Content_91 = {
    Text = "Even hyenas have their charms. A single piece of carrion is enough to bring them running. Greedy, sharp, ruthless, and naive—there is no better weapon."
  },
  AvgDialog_131222_Content_92 = {
    Text = "They've grown impatient out there. You appeared much too late today, and this expensive dress has been stained."
  },
  AvgDialog_131222_Content_93 = {
    Text = "You should have returned sooner, ma'am."
  },
  AvgDialog_131222_Content_94 = {
    Text = "Sorel pauses mid-motion. She lowers the crimson hem of her skirt and studies Karen's placid expression."
  },
  AvgDialog_131222_Content_95 = {
    Text = "Someone should have taught you how a servant addresses her Lady. What has gotten into you today?"
  },
  AvgDialog_131222_Content_96 = {
    Text = "Lady Sorel, you carry the filth of the East District upon you. I'm curious: where did you send that kind gentleman?"
  },
  AvgDialog_131222_Content_97 = {
    Text = "The bright room dims for a heartbeat. Several black spiders emerge from the shadows, coalescing into human shapes that surround Sorel."
  },
  AvgDialog_131222_Content_98 = {
    Text = "You have a very loyal servant, Lady Sorel. Despite her fondness for stealing and selling off your assets, her devotion to your safety is beyond question."
  },
  AvgDialog_131222_Content_99 = {
    Text = "Even now, her will fights fiercely against me. A pity, really—no mortal can resist the power of Fate."
  },
  AvgDialog_131223_Content_1 = {
    Text = "Help me... grant these abandoned souls their liberation."
  },
  AvgDialog_131223_Content_10 = {
    Text = "Nefraea's voice turns shrill. A dim light flares as crimson threads bind her tight, the dying embers of the Lantern scorching her flesh."
  },
  AvgDialog_131223_Content_11 = {
    Text = "Massive claws snap in the air. She stares at you with a smile through a pair of enormous compound eyes weeping black sludge. Crimson threads entwine her body, drifting through the currents of Fate's vortex."
  },
  AvgDialog_131223_Content_12 = {
    Text = "Beside her, the broken spinning wheel where the threads converge turns slowly and unstoppably, throttling the stages, throttling Nefraea herself."
  },
  AvgDialog_131223_Content_13 = {Text = "Ugh—"},
  AvgDialog_131223_Content_14 = {
    Text = "You clutch your head in agony. As the wheel turns, your Spirit Realm surges and churns. You gasp for breath, struggling to master the intense pain."
  },
  AvgDialog_131223_Content_15 = {
    Text = "Beside Nefraea, the fragments of the dimensional passage are nearly spent. The threads on your body—the puppet-like textures—grow ever clearer."
  },
  AvgDialog_131223_Content_16 = {
    Text = "The power of the passage... she has almost completely absorbed it!"
  },
  AvgDialog_131223_Content_17 = {
    Text = "Golden embers pour endlessly from Arachne's body, flying like moths toward the nearly shattered Web of Fate."
  },
  AvgDialog_131223_Content_18 = {
    Text = "Arachne's hands tremble as she turns her wheel at an eternal, unchanging rhythm. Her voice remains as calm as the first day you met."
  },
  AvgDialog_131223_Content_19 = {
    Text = "You have seen it. This is the intersection of Fate, Nefraea."
  },
  AvgDialog_131223_Content_2 = {
    Text = "Fate. Savage, hollow, pitiful Fate. The Abandoned Fates know not where they came from, nor where they go. They are drawn by silken threads, surging toward you, only to dissolve into pools of black sludge within your silver radiance."
  },
  AvgDialog_131223_Content_20 = {
    Text = "All errors come to an end here."
  },
  AvgDialog_131223_Content_21 = {
    Text = "What a confident declaration, Lady Prisoner. Then show me how you will stop a god. Show me how you stop Fate itself..."
  },
  AvgDialog_131223_Content_22 = {
    Text = "A manic smile blooms on Nefraea's face. The threads lift her into the air. On this shattered stage, she is the only light."
  },
  AvgDialog_131223_Content_23 = {
    Text = "Believers of the world, prostrate yourselves!"
  },
  AvgDialog_131223_Content_24 = {
    Text = "The Supreme Deity, the Unstoppable Fate, has arrived!"
  },
  AvgDialog_131223_Content_3 = {
    Text = "This sludge is savage, hollow, and pitiful—just like their destinies."
  },
  AvgDialog_131223_Content_4 = {
    Text = "Nefraea pays no attention. She has watched this scene play out for an eternity; she has long since grown used to it."
  },
  AvgDialog_131223_Content_5 = {
    Text = "I see it clearly now. Those images you saw, everything you witnessed... I finally see it all."
  },
  AvgDialog_131223_Content_6 = {
    Text = "She has grown numb to the pain of the fragments buried in her skin. A smile plays on her lips as she stares into the theater's chaotic void."
  },
  AvgDialog_131223_Content_7 = {
    Text = "Proud, pitying, indifferent... for a moment, you almost cannot tell her apart from Arachne."
  },
  AvgDialog_131223_Content_8 = {
    Text = "Only those within the cage can truly open it. The chaos and destruction you see is not the truth of Fate, Nefraea..."
  },
  AvgDialog_131223_Content_9 = {
    Text = "Heh... hahaha! Is that how you have been deceiving yourself all these years, Arachne?"
  },
  AvgDialog_131224_Content_1 = {
    Text = "Audience, Player, Author"
  },
  AvgDialog_131224_Content_10 = {
    Text = "This is...!"
  },
  AvgDialog_131224_Content_100 = {
    Text = "Go, my children. Find %player%."
  },
  AvgDialog_131224_Content_101 = {
    Text = "Seize {Male=his,Female=her} power, sever every thread of Fate, and tear the Great Web to shreds! Let every soul who stands in our path die upon it!"
  },
  AvgDialog_131224_Content_102 = {
    Text = "We shall use the blood of this fragment to awaken the Great Primordial One once more."
  },
  AvgDialog_131224_Content_103 = {
    Text = "When you see your precious Web of Fate shattered and reduced to a mire of filth, will you sink into the endless void just like us?"
  },
  AvgDialog_131224_Content_104 = {
    Text = "Goddess of Fate... my dear sister... my beloved <Red:Arachne>?"
  },
  AvgDialog_131224_Content_105 = {
    Text = "The boundary between the stage and the audience seems to vanish; space itself loses all meaning."
  },
  AvgDialog_131224_Content_106 = {
    Text = "Amidst her piercing laughter, the puppet appears to stand directly before you, staring straight into Arachne's eyes."
  },
  AvgDialog_131224_Content_107 = {
    Text = "The light fades and the curtain falls. The puppet and her laughter vanish, leaving the empty theater in silence, save for the soft, rhythmic whirring of the spinning wheel."
  },
  AvgDialog_131224_Content_108 = {
    Text = "I'm sorry, I don't quite understand... what exactly is the \"Abandoned Fate\"?"
  },
  AvgDialog_131224_Content_109 = {
    Text = "As you can see, Fate is a tangled mess of raw threads. If left unmanaged, the universe would descend into bottomless chaos. I believe that is a sight none of us wish to behold."
  },
  AvgDialog_131224_Content_11 = {
    Text = "The moment you step inside, the door behind you vanishes."
  },
  AvgDialog_131224_Content_110 = {
    Text = "Of course not..."
  },
  AvgDialog_131224_Content_111 = {
    Text = "It is my eternal duty to weave those threads into the Web of Fate, ensuring the universe functions as it should."
  },
  AvgDialog_131224_Content_112 = {
    Text = "At every moment, Fate holds infinite possibilities. At every moment, I am forced to make a choice."
  },
  AvgDialog_131224_Content_113 = {
    Text = "The correct destinies are woven into the Great Web; the wrong ones are cast aside. This is how the web functions. It is inevitable."
  },
  AvgDialog_131224_Content_114 = {
    Text = "My sister... she is a part of me that I discarded within those mistaken twists of Fate."
  },
  AvgDialog_131224_Content_115 = {
    Text = "Arachne remains smiling. As she speaks, you cannot detect even the slightest ripple of emotion in her voice."
  },
  AvgDialog_131224_Content_116 = {
    Text = "And these abandoned fates... they get sent to the \"Abyssal Prison\"?"
  },
  AvgDialog_131224_Content_117 = {
    Text = "The dreams of the Supreme Deity form the substance of this universe. The Abyssal Prison is the subconscious of that God—a dumping ground for every event that never happened and every fate that does not exist."
  },
  AvgDialog_131224_Content_118 = {
    Text = "They were meant to dissolve into nothingness in that void, but under my sister's guidance, they somehow found a way to survive."
  },
  AvgDialog_131224_Content_119 = {
    Text = "Arachne stares at the massive curtain, looking through it toward the puppet that represents Nefraea."
  },
  AvgDialog_131224_Content_12 = {
    Text = "Where you expected a narrow interior lies a vast, boundless dimensional space."
  },
  AvgDialog_131224_Content_120 = {
    Text = "She cannot weave destiny as I do. But like me, she can see the threads. She obscures them, pollutes them, and disrupts the trails I have laid, leading them toward death instead."
  },
  AvgDialog_131224_Content_121 = {
    Text = "So she wants to find me and use my power to reawaken Tohuwabohu?"
  },
  AvgDialog_131224_Content_122 = {
    Text = "I cannot know her specific plan, but all signs point to that. Regardless, she is a mistake that I must rectify."
  },
  AvgDialog_131224_Content_123 = {
    Text = "So that's why she closed the dimensional gateway..."
  },
  AvgDialog_131224_Content_124 = {
    Text = "No, I was the one who closed the gateway. She has been waiting for this exact moment—waiting to follow you to Kadath."
  },
  AvgDialog_131224_Content_125 = {
    Text = "Kadath is a dimension my power has never reached. It is also the place where the connection to the Supreme Deity is strongest."
  },
  AvgDialog_131224_Content_126 = {
    Text = "If she were to follow you back there, disaster would become unavoidable."
  },
  AvgDialog_131224_Content_127 = {
    Text = "Forgive me for taking such liberties, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131224_Content_128 = {
    Text = "I understand, Arachne. If what you're saying is true, I don't want to see that happen either."
  },
  AvgDialog_131224_Content_129 = {
    Text = "So, if I want to get back to Kadath, I have to deal with her first..."
  },
  AvgDialog_131224_Content_13 = {
    Text = "Countless stages float like stars in this dark expanse, puppets on each one reciting their lines."
  },
  AvgDialog_131224_Content_130 = {
    Text = "My lady, an anomaly has been detected on the stage in Area GI-9849. That's the third one today."
  },
  AvgDialog_131224_Content_131 = {
    Text = "Ever since she stole the materials for weaving, she has found endless joy in unraveling the destinies of others."
  },
  AvgDialog_131224_Content_132 = {
    Text = "My apologies, %player%, but I must tend to these disturbances. Please, come with me. There are vital matters I need you to see."
  },
  AvgDialog_131224_Content_133 = {
    Text = "Arachne shakes her head with a weary smile. She gestures for you to follow, picks up her spinning wheel, and stands."
  },
  AvgDialog_131224_Content_134 = {Text = "..."},
  AvgDialog_131224_Content_135 = {
    Text = "This... this is the stage that was destroyed?"
  },
  AvgDialog_131224_Content_136 = {
    Text = "Following a path woven of spider silk, you reach a dilapidated stage. Within a makeshift café on the set, a few people who look like students are huddled together, whispering."
  },
  AvgDialog_131224_Content_137 = {
    Text = "Lately, she has been sending her squires to sabotage the fates of these worlds. My maids have been hunting them down, but the battles have cost many of my good children their lives."
  },
  AvgDialog_131224_Content_138 = {
    Text = "The destinies of all worlds are bound to the same Great Web. If one world collapses, it tears the entire structure, plunging existence into absolute, fatal disorder."
  },
  AvgDialog_131224_Content_139 = {
    Text = "Nefraea stole the raw materials I use for weaving, leaving me unable to exert my power freely. {Male=Mr.,Female=Miss} Keeper, I wonder... would you be willing to help me restore this world's fate?"
  },
  AvgDialog_131224_Content_14 = {
    Text = "The words drift to you from a distance, like the murmur of countless devotees at prayer."
  },
  AvgDialog_131224_Content_140 = {
    Text = "If your story is true, then she is a problem I have to deal with regardless."
  },
  AvgDialog_131224_Content_141 = {
    Text = "Arachne nods to you in gratitude. She raises her hand and gently plucks at the hidden threads suspended in the empty air."
  },
  AvgDialog_131224_Content_142 = {Text = "Clang—"},
  AvgDialog_131224_Content_143 = {
    Text = "Following a sharp, musical chime, the announcer's melodic voice rings out like an eternal stream flowing into a deep pool."
  },
  AvgDialog_131224_Content_144 = {
    Text = "The trumpets play a flourish. Enter: The Student and the Scholar!"
  },
  AvgDialog_131224_Content_145 = {
    Text = "Arachne makes a grand, inviting gesture toward the stage."
  },
  AvgDialog_131224_Content_146 = {
    Text = "It's time for our entrance, %player%."
  },
  AvgDialog_131224_Content_147 = {
    Text = "You nod. To the sound of the announcer's call, two puppets step onto the stage that has been set for them."
  },
  AvgDialog_131224_Content_15 = {
    Text = "Threads of silk extend from each puppet and stage, converging with the silk-woven path beneath your feet toward the single stage at the very center of this space."
  },
  AvgDialog_131224_Content_16 = {
    Text = "You turn around. The maid has already moved ahead."
  },
  AvgDialog_131224_Content_17 = {
    Text = "What a strange welcome..."
  },
  AvgDialog_131224_Content_18 = {
    Text = "You hesitate, then make your way along the web-like path toward the central stage. As you pass the floating stages, fragments of conversation drift into your ears."
  },
  AvgDialog_131224_Content_19 = {
    Text = "My dear customer, I see confusion in your eyes."
  },
  AvgDialog_131224_Content_2 = {
    Text = "I have one more question..."
  },
  AvgDialog_131224_Content_20 = {
    Text = "I hope the incident just now didn't frighten you too badly?"
  },
  AvgDialog_131224_Content_21 = {
    Text = "A gin base with a touch of hibiscus—I think it would suit your mood perfectly right now."
  },
  AvgDialog_131224_Content_22 = {Text = "..."},
  AvgDialog_131224_Content_23 = {
    Text = "Ah! A homeless child, so small, so lost."
  },
  AvgDialog_131224_Content_24 = {
    Text = "With nothing but those thin clothes, how will you make it through the winter?"
  },
  AvgDialog_131224_Content_25 = {
    Text = "Come with me. Let me find you somewhere to shelter from the storm..."
  },
  AvgDialog_131224_Content_26 = {Text = "..."},
  AvgDialog_131224_Content_27 = {
    Text = "These... are the people I just ran into?"
  },
  AvgDialog_131224_Content_28 = {
    Text = "How did they end up on these stages..."
  },
  AvgDialog_131224_Content_29 = {
    Text = "A patrolling officer, a clerk reading a newspaper, a driver watching the street, lovers buying flowers, nobles mid-conversation..."
  },
  AvgDialog_131224_Content_3 = {
    Text = "That is already your twenty-third question, %player%."
  },
  AvgDialog_131224_Content_30 = {
    Text = "Those you have met and those you never will—all of them playing out their own stories across countless stages. On each of their own stages, every one of them is the lead."
  },
  AvgDialog_131224_Content_31 = {
    Text = "Ave, %player%! Blessed be, infant from Yakutsk!"
  },
  AvgDialog_131224_Content_32 = {
    Text = "Ave, %player%! Blessed be, Keeper of Mythag!"
  },
  AvgDialog_131224_Content_33 = {
    Text = "Ave, %player%! Blessed be, god of destruction!"
  },
  AvgDialog_131224_Content_34 = {
    Text = "As you near the central stage, three puppets of different shapes step onto it and bow in your direction."
  },
  AvgDialog_131224_Content_35 = {
    Text = "The Lady is waiting for you inside. Please, come in—{Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131224_Content_36 = {
    Text = "When the door of the box opens, the images and sounds of the entire theater seem to pause for a single, suspended moment."
  },
  AvgDialog_131224_Content_37 = {
    Text = "You step through and draw back the curtain—"
  },
  AvgDialog_131224_Content_38 = {
    Text = "They appear on these stages because this theater bears a single name: Fate."
  },
  AvgDialog_131224_Content_39 = {
    Text = "A cool, unhurried voice reaches you before any color does."
  },
  AvgDialog_131224_Content_4 = {
    Text = "Compared to the mysteries of this place, twenty-three is nowhere near enough."
  },
  AvgDialog_131224_Content_40 = {
    Text = "In a box that seems to have no walls, the threads connecting every stage and every puppet converge upon a quietly glowing spindle. A woman sits at the point where all threads meet, turning it with a gentle hand."
  },
  AvgDialog_131224_Content_41 = {
    Text = "You see every detail of her with perfect clarity. Yet in each blink, every impression vanishes from your mind, leaving nothing behind. Her image refuses to hold."
  },
  AvgDialog_131224_Content_42 = {
    Text = "When she turns her head to look at you, your heart—wound tight with vigilance all this time—lurches into a violent beat."
  },
  AvgDialog_131224_Content_43 = {
    Text = "It's you?!!"
  },
  AvgDialog_131224_Content_44 = {
    Text = "On the Paradise... and those attacks...!"
  },
  AvgDialog_131224_Content_45 = {
    Text = "The moment you prepare to channel your spiritual energy into the Silver Key, the lady of the theater reaches out. Her hand sweeps through the air with a grace so delicate it's as if she's plucking an invisible string."
  },
  AvgDialog_131224_Content_46 = {Text = "!!!"},
  AvgDialog_131224_Content_47 = {
    Text = "Spiritual energy surges to your fingertips, only to recoil like a flood hitting a massive dam. As you lift your hand, a jolt of shock strikes you: your palm is empty. The key is gone."
  },
  AvgDialog_131224_Content_48 = {
    Text = "The Silver Key... I was holding it just a second ago... How..."
  },
  AvgDialog_131224_Content_49 = {
    Text = "The lady offers a faint smile and gives her maid a small nod."
  },
  AvgDialog_131224_Content_5 = {
    Text = "I am not the one you are looking for. The person who can answer your questions is waiting for you just ahead."
  },
  AvgDialog_131224_Content_50 = {
    Text = "Under your astonished gaze, the maid steps forward and respectfully places the Silver Key back into your hand."
  },
  AvgDialog_131224_Content_51 = {
    Text = "Impossible... There's no way she could have stolen it from me!"
  },
  AvgDialog_131224_Content_52 = {
    Text = "Before entering the theater, you gripped that key tightly, maintaining a constant spiritual link."
  },
  AvgDialog_131224_Content_53 = {
    Text = "Your training at Mythag has granted you a level of vigilance so high that no one could ever hope to snatch it from your grasp."
  },
  AvgDialog_131224_Content_54 = {
    Text = "Then why..."
  },
  AvgDialog_131224_Content_55 = {
    Text = "No person could take it from you. But Fate can."
  },
  AvgDialog_131224_Content_56 = {
    Text = "Forgive me, %player%. I understand your anxiety and I respect your power."
  },
  AvgDialog_131224_Content_57 = {
    Text = "To prevent any unintentional damage to my theater, I had no choice but to briefly alter the fate of the key in your hand. I hope you can overlook this liberty."
  },
  AvgDialog_131224_Content_58 = {
    Text = "She waves a hand, and a beam of light pierces the space between you. Looking closely, you see a faint, nearly imperceptible thread extending from the Silver Key, trailing back to the spinning wheel at her side."
  },
  AvgDialog_131224_Content_59 = {
    Text = "These threads... what are they?"
  },
  AvgDialog_131224_Content_6 = {
    Text = "You stop before a theater entrance barely wide enough for one person. No sign, no customers—an unremarkable thread of cobweb tucked among Londinium's grand storefronts."
  },
  AvgDialog_131224_Content_60 = {
    Text = "There are many explanations for the threads, most far too complex for this moment. You may simply think of them as... Fate."
  },
  AvgDialog_131224_Content_61 = {
    Text = "The spinning wheel turns softly on its own. She rises to her feet and offers a graceful nod of greeting."
  },
  AvgDialog_131224_Content_62 = {
    Text = "Arachne. I am the Master of this Theater of Fate. It is an honor to meet you, Keeper."
  },
  AvgDialog_131224_Content_63 = {
    Text = "Please, rest easy. You are safe here."
  },
  AvgDialog_131224_Content_64 = {
    Text = "I suppose so. If you wanted me dead, I wouldn't have survived that display just now."
  },
  AvgDialog_131224_Content_65 = {
    Text = "You look down at the returned key with a conflicted expression, then turn a suspicious frown toward her."
  },
  AvgDialog_131224_Content_66 = {
    Text = "Back on the Paradise, you helped me. But since I've been in this city, you've attacked me twice."
  },
  AvgDialog_131224_Content_67 = {
    Text = "I understand your wariness. But please believe me when I say I have never lifted a finger to harm you."
  },
  AvgDialog_131224_Content_68 = {
    Text = "You blocked my link to Kadath and ambushed me multiple times... are you telling me none of that was your doing?"
  },
  AvgDialog_131224_Content_69 = {
    Text = "The one who troubled you may share my face, but she is not me."
  },
  AvgDialog_131224_Content_7 = {
    Text = "The maid pushes the door open gently and slips into the darkness beyond. A faint light flickers inside from no discernible source, like a quiet, hidden invitation."
  },
  AvgDialog_131224_Content_70 = {
    Text = "As for your link to Kadath... that is a dangerous trap, %player%."
  },
  AvgDialog_131224_Content_71 = {Text = "A trap?"},
  AvgDialog_131224_Content_72 = {
    Text = "A child born of my own existence has caused you unnecessary grief, and for that, I am truly sorry. This situation began with me, and I am doing everything in my power to mend the mistake."
  },
  AvgDialog_131224_Content_73 = {
    Text = "I'm not following you..."
  },
  AvgDialog_131224_Content_74 = {
    Text = "It is a long tale, and one bound to the nature of Fate. Stories are always easier to digest than plain facts."
  },
  AvgDialog_131224_Content_75 = {
    Text = "Please, take a seat, {Male=Mr.,Female=Miss} Keeper. This new act of our play began only a short while ago."
  },
  AvgDialog_131224_Content_76 = {
    Text = "Arachne waves her hand gently. The curtains part, revealing a vast, floating stage suspended in the void."
  },
  AvgDialog_131224_Content_77 = {
    Text = "A shimmering, ethereal mirror stands upon the stage, reflecting both of your silhouettes."
  },
  AvgDialog_131224_Content_78 = {
    Text = "The trumpets sound a flourish. Enter: The Abandoned Fate."
  },
  AvgDialog_131224_Content_79 = {
    Text = "Your reflection vanishes from the mirror's surface, while Arachne's image transforms into a puppet."
  },
  AvgDialog_131224_Content_8 = {
    Text = "You hesitate for a moment, then step through."
  },
  AvgDialog_131224_Content_80 = {
    Text = "The puppet remains seated, but her gentle composure has evaporated."
  },
  AvgDialog_131224_Content_81 = {
    Text = "She swirls a goblet filled with a blood-red vintage as if enthroned upon a seat of slaughter. Her eyes, innocent yet utterly ruthless, sweeps across the audience."
  },
  AvgDialog_131224_Content_82 = {
    Text = "Behind the puppet, four pairs of razor-sharp spider limbs sway lazily, the tips grazing the cheeks of the attendants standing nearby."
  },
  AvgDialog_131224_Content_83 = {
    Text = "Ah, the sweet scent of freedom..."
  },
  AvgDialog_131224_Content_84 = {
    Text = "How many years were we rotting in that Abyssal Prison, my dear squire?"
  },
  AvgDialog_131224_Content_85 = {
    Text = "I do not know, my lady."
  },
  AvgDialog_131224_Content_86 = {
    Text = "Names, time, emotions... I have forgotten it all. I remember only you, my lady—the esteemed Nefraea."
  },
  AvgDialog_131224_Content_87 = {
    Text = "I remember only your promise: that you would lead us out, and that we would swing the blade of vengeance against Fate itself."
  },
  AvgDialog_131224_Content_88 = {
    Text = "I remember, child. I gave you ninety thousand promises, and now, let me give you the ninety-thousand-and-first."
  },
  AvgDialog_131224_Content_89 = {
    Text = "At any given moment, only one fate can truly exist. The Proxy of Fate prunes away the countless \"wrong\" destinies, leaving only the one \"true\" path behind."
  },
  AvgDialog_131224_Content_9 = {Text = "..."},
  AvgDialog_131224_Content_90 = {
    Text = "We are the Abandoned Fate. Heh... my dear squire, you are a mistake. Just like me."
  },
  AvgDialog_131224_Content_91 = {
    Text = "In the subconscious of this universe, within that void of an Abyssal Prison, we were exiled and caged. We wander there, forgotten, for all eternity. Our sentence has outlasted time itself..."
  },
  AvgDialog_131224_Content_92 = {
    Text = "The woman named Nefraea rises from her seat and leans forward, her mirrored gaze locking onto the real Arachne in the audience."
  },
  AvgDialog_131224_Content_93 = {
    Text = "But by what right, O Goddess of Fate? Why must it be us who are cast aside?"
  },
  AvgDialog_131224_Content_94 = {
    Text = "The supreme, singular deity of the infinite cosmos finally stirred for a fleeting moment. It has fallen back into slumber, but the prison of Its consciousness—the eternal Abyssal Prison—has finally cracked open for us."
  },
  AvgDialog_131224_Content_95 = {
    Text = "I had already accepted oblivion. I had faded away. So why—why must I be forced to remember all this agony?"
  },
  AvgDialog_131224_Content_96 = {
    Text = "Nefraea drains her cup and lets out a sigh of pure satisfaction. Crimson droplets trail down her pale lips, staining the dull spinning wheel in her lap."
  },
  AvgDialog_131224_Content_97 = {
    Text = "Perhaps this is the will of Fate... a destiny that even you cannot control."
  },
  AvgDialog_131224_Content_98 = {
    Text = "The Primordial Deity sleeps again, but Its fragments have found their way to our doorstep."
  },
  AvgDialog_131224_Content_99 = {
    Text = "I do not possess your gift for weaving destiny. I am merely a corrector of Fate—an executioner from the void. I shall punish the sins within the river of time on behalf of the Primordial One."
  },
  AvgDialog_131225_Content_1 = {
    Text = "Echoes of Before"
  },
  AvgDialog_131225_Content_10 = {
    Text = "Instead of the spacious interior you expected, the villa is claustrophobically crowded. Nefraea seems intent on scribbling chaos into her script."
  },
  AvgDialog_131225_Content_11 = {
    Text = "Endless rows of cabinets and shelves stand in silence, every inch of space packed with jars of varying sizes."
  },
  AvgDialog_131225_Content_12 = {
    Text = "Silver mirrors, spider eggs, dance shoes infested with strange insects... objects are preserved in suspicious fluids, looking like mouths frozen in a silent scream."
  },
  AvgDialog_131225_Content_13 = {
    Text = "You walk up to the jars and read the labels aloud."
  },
  AvgDialog_131225_Content_14 = {
    Text = "<Italic:\"Two years old. Spoke their first words. Not a call for family, but a farewell to the old butler who served the house for generations.\">"
  },
  AvgDialog_131225_Content_15 = {
    Text = "<Italic:\"That same night, the butler died of heart failure. Crying outside the gatehouse, clutching his belongings...\">"
  },
  AvgDialog_131225_Content_16 = {
    Text = "It is an old family brooch."
  },
  AvgDialog_131225_Content_17 = {
    Text = "<Italic:\"Five years old. Dancing a shy waltz just like Mother, amidst the blushing cheers of dinner guests...\">"
  },
  AvgDialog_131225_Content_18 = {
    Text = "It is a pair of vibrant red dance shoes."
  },
  AvgDialog_131225_Content_19 = {
    Text = "<Italic:\"Seven years old. Received a birthday gift from Father: a spinning wheel named Moirae.\">"
  },
  AvgDialog_131225_Content_2 = {
    Text = "Brick Lane. You remember your previous investigations in this part of Londinium."
  },
  AvgDialog_131225_Content_20 = {
    Text = "<Italic:\"Saw the shadow of Fate projected within the threads...\">"
  },
  AvgDialog_131225_Content_21 = {
    Text = "It is a handful of broken thread."
  },
  AvgDialog_131225_Content_22 = {
    Text = "<Italic:\"First trip to the opera with parents... First time meeting a soulmate... First time burying a beloved dog...\">"
  },
  AvgDialog_131225_Content_23 = {
    Text = "The words on the jar labels drift into your sight, one after another. Each time you touch them, a hazy memory flickers in the back of your mind. You turn around to cast Arachne a puzzled look."
  },
  AvgDialog_131225_Content_24 = {
    Text = "These... are these your memories?"
  },
  AvgDialog_131225_Content_25 = {
    Text = "They were mine, once. Long ago, they were given to the Puppet named 'Memories.'"
  },
  AvgDialog_131225_Content_26 = {
    Text = "These are precious. Why would you put them inside a Puppet?"
  },
  AvgDialog_131225_Content_27 = {
    Text = "Everyone must make choices. And every choice has a price."
  },
  AvgDialog_131225_Content_28 = {
    Text = "To reach the end of the road, one must always cast something aside. I think you understand that better than anyone, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131225_Content_29 = {
    Text = "Arachne avoids a direct answer. She stares at the cabinets, her fingers tracing the glass of the jars."
  },
  AvgDialog_131225_Content_3 = {
    Text = "Filthy and chaotic. The air is thick with coal smoke and sewage—the scents that defined the lives of Mason and Jenkin."
  },
  AvgDialog_131225_Content_30 = {
    Text = "Her touch is light and slow, like an elder gently caressing cherished toys from their childhood."
  },
  AvgDialog_131225_Content_31 = {
    Text = "Extracting these memories and putting them on display like this... this is the view you prepared for me, isn't it, Nefraea?"
  },
  AvgDialog_131225_Content_32 = {
    Text = "I hear what you're trying to say..."
  },
  AvgDialog_131225_Content_33 = {
    Text = "<Big:<Shake:AAAHHHH!—>>"
  },
  AvgDialog_131225_Content_34 = {
    Text = "A piercing shriek echoes through the room. The jars of memory rattle, sounding like a crowd of silent, laughing spectators."
  },
  AvgDialog_131225_Content_35 = {
    Text = "!! It's coming from the room at the end of the hall!"
  },
  AvgDialog_131225_Content_36 = {Text = "BANG!"},
  AvgDialog_131225_Content_37 = {
    Text = "You sprint down the hallway, kick the door open..."
  },
  AvgDialog_131225_Content_38 = {
    Text = "...and step into a torrential downpour."
  },
  AvgDialog_131225_Content_39 = {
    Text = "There is no thunder, no wind, no rain. Only a deluge of spiders falling from the ceiling like a storm."
  },
  AvgDialog_131225_Content_4 = {
    Text = "Suddenly, a magnificent, gilded villa appears between two shanties, looking like a jewelry box tossed into a scrap heap."
  },
  AvgDialog_131225_Content_40 = {
    Text = "The mass of sticky black anarchid limbs forms a surging tide, devouring every object and every scrap of light."
  },
  AvgDialog_131225_Content_41 = {
    Text = "In the center of the dark storm, the swarming, gnawing spiders coalesce into a human shape. Where the tide has not yet reached, a wizened, familiar face peers through."
  },
  AvgDialog_131225_Content_42 = {
    Text = "Lady... Arachne..."
  },
  AvgDialog_131225_Content_43 = {
    Text = "Run... get out of here...!"
  },
  AvgDialog_131225_Content_44 = {
    Text = "Shh... you have no lines in this scene, Mr. Kindness."
  },
  AvgDialog_131225_Content_45 = {
    Text = "Fate's Revenge, Act Two, Scene Two. I call it \"Downpour.\""
  },
  AvgDialog_131225_Content_46 = {
    Text = "Enjoy the rain, my dear audience."
  },
  AvgDialog_131225_Content_47 = {
    Text = "The pooled liquid surges. Obeying a supreme command, the black spiders flood into every corner of the room."
  },
  AvgDialog_131225_Content_48 = {
    Text = "To Nefraea's delighted laughs, the Abyssal Squires born from the swarm surge toward you—"
  },
  AvgDialog_131225_Content_5 = {
    Text = "Vagrants and weary laborers pass by the ornate structure without a second glance, as if it has been there since the dawn of time."
  },
  AvgDialog_131225_Content_6 = {
    Text = "Even the fate of the city is warped... Nefraea's power is growing."
  },
  AvgDialog_131225_Content_7 = {
    Text = "You approach cautiously. Just as you reach out to knock, the door swings open silently."
  },
  AvgDialog_131225_Content_8 = {
    Text = "It seems our thoughtful host has left the door open for us."
  },
  AvgDialog_131225_Content_9 = {
    Text = "What is this...?"
  },
  AvgDialog_131226_Content_1 = {
    Text = "T-they‘re dead!!"
  },
  AvgDialog_131226_Content_10 = {
    Text = "I saw everything. You didn't pass through that gateway, %player%. This is not where we need to be."
  },
  AvgDialog_131226_Content_11 = {
    Text = "Everything feels off... the Dissolution, Mythag, the Cataclysms—they have no idea about any of it."
  },
  AvgDialog_131226_Content_12 = {
    Text = "But this city looks exactly as I remember it. Exactly as it was before Tohuwabohu. Maybe we should go back to the school and take a look. We might find something..."
  },
  AvgDialog_131226_Content_13 = {
    Text = "I just came from there. There is no Mythag here, %player%."
  },
  AvgDialog_131226_Content_14 = {
    Text = "No Mythag...?"
  },
  AvgDialog_131226_Content_15 = {
    Text = "The world map in the shop was unlike anything I've ever seen. And every calendar I found—they're different. Not the After Flood calendar we use."
  },
  AvgDialog_131226_Content_16 = {
    Text = "The strangest thing is... this city has no end."
  },
  AvgDialog_131226_Content_17 = {Text = "No... end?"},
  AvgDialog_131226_Content_18 = {
    Text = "Heading north from where Mythag should be ought to take you beyond Londinium's boundaries."
  },
  AvgDialog_131226_Content_19 = {
    Text = "I was attacked by those spiders along the way. To escape them, I kept to that road. But in the end... I found myself back near where you were. The southern end of Londinium."
  },
  AvgDialog_131226_Content_2 = {
    Text = "The crowd screams and scatters. Before you even noticed, William is there beside you, that golden hair unmistakable as ever."
  },
  AvgDialog_131226_Content_20 = {
    Text = "This is not Londinium. This is not Kadath."
  },
  AvgDialog_131226_Content_21 = {
    Text = "So my memory was right... the gateway really did close before I could enter..."
  },
  AvgDialog_131226_Content_22 = {
    Text = "You look up at the familiar sights beyond the alley and sigh, a hollow feeling settling in."
  },
  AvgDialog_131226_Content_23 = {
    Text = "A place identical to Londinium, a city with no end, black spiders appearing from nowhere... and the \"Lady\" they answer to..."
  },
  AvgDialog_131226_Content_24 = {
    Text = "It's too early to be certain, but I don't believe the gateway closing and our arrival here are a coincidence. Someone engineered all of this deliberately—whoever commands those spiders."
  },
  AvgDialog_131226_Content_25 = {
    Text = "We still don't understand anything. We need to gather information first..."
  },
  AvgDialog_131226_Content_26 = {Text = "You two..."},
  AvgDialog_131226_Content_27 = {
    Text = "Who's there?!"
  },
  AvgDialog_131226_Content_28 = {
    Text = "A silver radiance flares within William's mechanical palm, like a blade ready to be drawn at any moment."
  },
  AvgDialog_131226_Content_29 = {
    Text = "In that dangerous silver glow, you make out the elder who had just tried to offer you food."
  },
  AvgDialog_131226_Content_3 = {
    Text = "William... when did you... what's going on?"
  },
  AvgDialog_131226_Content_30 = {
    Text = "It's... it's only me..."
  },
  AvgDialog_131226_Content_31 = {
    Text = "This... does this belong to you?"
  },
  AvgDialog_131226_Content_32 = {
    Text = "The old man opens his hand. The Mythag school badge—your communicator—lies quietly in his rough palm."
  },
  AvgDialog_131226_Content_33 = {
    Text = "Ah! It must have fallen during the fight..."
  },
  AvgDialog_131226_Content_34 = {
    Text = "This means a great deal to me... thank you so much!"
  },
  AvgDialog_131226_Content_35 = {
    Text = "Under William's watchful eye, you take back the badge and carefully put it away."
  },
  AvgDialog_131226_Content_36 = {
    Text = "Sir... weren't you frightened by what just happened?"
  },
  AvgDialog_131226_Content_37 = {
    Text = "Frightened... of course I was. I've lived here my whole life. I've never seen anything like that..."
  },
  AvgDialog_131226_Content_38 = {
    Text = "But that thing looked important to you, and you've only just arrived—if you lost it, you'd have no idea where to start looking. So I brought it over."
  },
  AvgDialog_131226_Content_39 = {
    Text = "That's so kind of you... thank you."
  },
  AvgDialog_131226_Content_4 = {
    Text = "This isn't the place. Move!"
  },
  AvgDialog_131226_Content_40 = {
    Text = "We've just arrived and there's a great deal we don't know. Would it be alright to ask you a few things?"
  },
  AvgDialog_131226_Content_41 = {
    Text = "I don't mind spending a little more time with you two, but I'm afraid I know very little about what you're after. I'd hate to hold you up."
  },
  AvgDialog_131226_Content_42 = {
    Text = "Somewhere with a bigger crowd might serve you better—easier to find someone who knows what you're looking for."
  },
  AvgDialog_131226_Content_43 = {
    Text = "Alright, I've returned what needed returning. I'll be on my way."
  },
  AvgDialog_131226_Content_44 = {
    Text = "The old man brushes off your parting courtesies with a wave as he exits the alleyway."
  },
  AvgDialog_131226_Content_45 = {
    Text = "He doesn't appear to have any ill intentions. He makes a good point—we need to find somewhere information moves more freely, and quickly."
  },
  AvgDialog_131226_Content_46 = {
    Text = "I know just the place!"
  },
  AvgDialog_131226_Content_47 = {
    Text = "If this city truly mirrors Londinium, then that place should be exactly what we need."
  },
  AvgDialog_131226_Content_48 = {
    Text = "As you leave, a pale violet spider lurks just beyond the edge of your vision, crawling along its thread and slipping into a crack in the wall, vanishing without a trace."
  },
  AvgDialog_131226_Content_5 = {
    Text = "William grabs you and heads in the opposite direction of the crowd."
  },
  AvgDialog_131226_Content_6 = {Text = "..."},
  AvgDialog_131226_Content_7 = {
    Text = "There shouldn't be anyone near this alley."
  },
  AvgDialog_131226_Content_8 = {
    Text = "What is going on? Why has Londinium become like this..."
  },
  AvgDialog_131226_Content_9 = {
    Text = "Those spiders that attacked us, and that person... could she be connected to the woman we encountered on the Paradise?"
  },
  AvgDialog_131227_Content_1 = {
    Text = "Tawil! I..."
  },
  AvgDialog_131227_Content_2 = {
    Text = "I understand, Keeper."
  },
  AvgDialog_131227_Content_3 = {
    Text = "Your fate is rewritten. You cannot stop, nor should you."
  },
  AvgDialog_131227_Content_4 = {
    Text = "Arachne cannot speak of the future... Please, tell me what I must do..."
  },
  AvgDialog_131227_Content_5 = {
    Text = "I cannot speak of what lies beyond the Gate. There are others better suited to guide you in this matter."
  },
  AvgDialog_131227_Content_6 = {
    Text = "Move forward, Keeper. Your fate is yours to see clearly."
  },
  AvgDialog_131228_Content_1 = {
    Text = "Hmm... Heroes and jesters, marionettes of fate... quite the spectacle."
  },
  AvgDialog_131228_Content_2 = {
    Text = "Arachne told me the key to the lock is \"Rapture\"... that is your domain, N."
  },
  AvgDialog_131228_Content_3 = {
    Text = "Shh! No rush, please. Ruining a good show is the most unforgivable sin in this universe."
  },
  AvgDialog_131228_Content_4 = {
    Text = "Come now, Keeper. It's been so long! Let me see if you've gained any new insights into... \"Rapture.\""
  },
  AvgDialog_131229_Content_10 = {
    Text = "Answer me... Liz!"
  },
  AvgDialog_131229_Content_11 = {
    Text = "Her threads of fate are severed. Her life is spent."
  },
  AvgDialog_131229_Content_12 = {
    Text = "<Shake:No... we can't let Nefraea get away with this.> <Big:<Red:She must pay for this atrocity!>>"
  },
  AvgDialog_131229_Content_13 = {
    Text = "Fate has already prepared the price she must pay. The trail doesn't end here."
  },
  AvgDialog_131229_Content_14 = {
    Text = "But you just said Liz is..."
  },
  AvgDialog_131229_Content_15 = {
    Text = "Death is but a part of Fate. This is my stage, {Male=Mr.,Female=Miss} Keeper. All destinies are threads in my hands, and I alone weave their course."
  },
  AvgDialog_131229_Content_16 = {Text = "!!!"},
  AvgDialog_131229_Content_17 = {
    Text = "<Shake:Wait, you mean...>"
  },
  AvgDialog_131229_Content_18 = {
    Text = "Arachne's expression shows neither sorrow nor joy. She approaches the announcer who was just puppeted by Nefraea. The dusk light outlines her steady silhouette, never-changing like Fate itself."
  },
  AvgDialog_131229_Content_19 = {
    Text = "Heh... hahaha... Arachne, you're still so, so arrogant! Hahaha..."
  },
  AvgDialog_131229_Content_2 = {
    Text = "The surrounding enemies fall, but you don't stop."
  },
  AvgDialog_131229_Content_20 = {
    Text = "Nefraea seems to find this hilarious, her laughter echoing as she rolls across the floor."
  },
  AvgDialog_131229_Content_21 = {
    Text = "You polluted Miss Salle's fate and led her to a hollow death. The Great Web remembers everything you do."
  },
  AvgDialog_131229_Content_22 = {
    Text = "Corrupted destinies must be mended. A price awaits you in the shadows of your future."
  },
  AvgDialog_131229_Content_23 = {
    Text = "Arachne reaches out, her fingers dancing over the corpse's head. Her spindle turns softly, and reality begins to warp and reshape itself with every rotation..."
  },
  AvgDialog_131229_Content_24 = {
    Text = "Threads of Fate, heed the call of the Web. Walk the only path and take the stage once more..."
  },
  AvgDialog_131229_Content_25 = {
    Text = "Her body... it's gone?"
  },
  AvgDialog_131229_Content_26 = {
    Text = "Under Arachne's touch, Liz's body seems to undergo a silent combustion, dissolving into ash that dissipates into the air."
  },
  AvgDialog_131229_Content_27 = {
    Text = "Beneath the falling embers, a new form reveals itself."
  },
  AvgDialog_131229_Content_28 = {
    Text = "Is that... the announcer?!"
  },
  AvgDialog_131229_Content_29 = {
    Text = "Spikes now pierce the announcer's body, suspending her above the stage in a perfect, macabre mirror of Liz's pose."
  },
  AvgDialog_131229_Content_3 = {
    Text = "You scream, manically stomping the announcer's smiling face into the floorboards until it's unrecognizable."
  },
  AvgDialog_131229_Content_30 = {
    Text = "The announcer's hideous grin is the last thing left of her as she falls silent forever."
  },
  AvgDialog_131229_Content_31 = {
    Text = "Arachne, you..."
  },
  AvgDialog_131229_Content_32 = {
    Text = "Sorry I'm late, I just... Oh!"
  },
  AvgDialog_131229_Content_33 = {
    Text = "A familiar figure pulls back the curtain. Her eyes sweep past you and lock onto the corpse hanging above."
  },
  AvgDialog_131229_Content_34 = {
    Text = "Her posture... it's beautiful..."
  },
  AvgDialog_131229_Content_35 = {
    Text = "Liz seems to ignore the corpses and the remaining audience. She walks to the center of the stage, her hand tracing the air near the hanging body's legs as if studying the curve of its form."
  },
  AvgDialog_131229_Content_36 = {
    Text = "Arachne... did you swap their destinies?!"
  },
  AvgDialog_131229_Content_37 = {
    Text = "But you said a toll like this was unbearable..."
  },
  AvgDialog_131229_Content_38 = {
    Text = "The cost is irrelevant to the choice. In my own destiny, this is the price I am meant to pay."
  },
  AvgDialog_131229_Content_39 = {
    Text = "Go, %player%. Don't keep Miss Liz waiting."
  },
  AvgDialog_131229_Content_4 = {
    Text = "Yes... just like that... Let it out! What a magnificent expression..."
  },
  AvgDialog_131229_Content_40 = {
    Text = "Empty eyes and frozen breath. Her skirt drifts in the wind, flickering with faint green flames. Every twitch of her fingers looks like a choreographed dance."
  },
  AvgDialog_131229_Content_41 = {
    Text = "The bloody figure that rushed towards you just moments ago overlaps with the woman before you now. Liz stands there, vivid and alive—the intricate reweaving of fate has left no mark upon her."
  },
  AvgDialog_131229_Content_42 = {
    Text = "Eventually, Liz snaps out of her trance and turns to you."
  },
  AvgDialog_131229_Content_43 = {
    Text = "I slept until the afternoon and missed the show. That's never happened before..."
  },
  AvgDialog_131229_Content_44 = {
    Text = "I take it I missed something important?"
  },
  AvgDialog_131229_Content_45 = {
    Text = "Her eyes drift over the bodies and bloodstains she had previously ignored."
  },
  AvgDialog_131229_Content_46 = {
    Text = "No, you haven't missed a thing, Liz."
  },
  AvgDialog_131229_Content_47 = {
    Text = "Are you... okay? Do you feel alright?"
  },
  AvgDialog_131229_Content_48 = {
    Text = "I feel fine. But tell me, {Male=sir,Female=miss}, have we met? You feel strangely familiar..."
  },
  AvgDialog_131229_Content_49 = {
    Text = "Perhaps it's because I'm a devoted fan of yours. I've seen many of your shows."
  },
  AvgDialog_131229_Content_5 = {
    Text = "The mangled face continues to smile. A faint voice escapes her shattered throat."
  },
  AvgDialog_131229_Content_50 = {
    Text = "You smile at her. This stage has its own story, and you have no intention of burdening her with the past."
  },
  AvgDialog_131229_Content_51 = {
    Text = "We are here for \"Kindness.\""
  },
  AvgDialog_131229_Content_52 = {
    Text = "Ah, so you're Lady Sorel's friends. I was worried I'd been a bit rude leaving Mr. Kindness at home while I came to perform. Please, follow me. I live nearby."
  },
  AvgDialog_131229_Content_53 = {
    Text = "Liz casts a lingering look at the corpse on the wall before leading you behind the curtain."
  },
  AvgDialog_131229_Content_54 = {Text = "..."},
  AvgDialog_131229_Content_55 = {
    Text = "So... it should have been my body hanging there... on the stage..."
  },
  AvgDialog_131229_Content_56 = {
    Text = "She seems far too entranced by the beauty of the scene to mourn her fallen colleagues, or spare another word of thanks for her savior."
  },
  AvgDialog_131229_Content_57 = {
    Text = "As you speak, Liz's eyes flicker like dancing flames. She reaches out, mimicking the pose of the corpse."
  },
  AvgDialog_131229_Content_58 = {
    Text = "Was it... beautiful?"
  },
  AvgDialog_131229_Content_59 = {
    Text = "True beauty only reveals itself at birth and at death. It was a sight beyond compare, Miss Salle."
  },
  AvgDialog_131229_Content_6 = {
    Text = "Nefraea isn't here. This is merely an illusion. Don't let rage blind you, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131229_Content_60 = {
    Text = "Thank you, Lady Arachne. As a weaver of Fate, you must be surrounded by such beauty constantly. I truly... envy you."
  },
  AvgDialog_131229_Content_61 = {
    Text = "Too many treasures can become a curse."
  },
  AvgDialog_131229_Content_62 = {
    Text = "If that is your curse, what reward do you seek?"
  },
  AvgDialog_131229_Content_63 = {
    Text = "Liz doesn't notice Arachne's brief hesitation as she opens the guest room door."
  },
  AvgDialog_131229_Content_64 = {
    Text = "This is Mr. Kindness's room. Sir, your friends are here."
  },
  AvgDialog_131229_Content_65 = {
    Text = "Mr. Kindness?"
  },
  AvgDialog_131229_Content_66 = {
    Text = "The room is simple. Nothing is out of place, but no one is inside."
  },
  AvgDialog_131229_Content_67 = {
    Text = "A lone note sits on the bookshelf in the empty room."
  },
  AvgDialog_131229_Content_68 = {
    Text = "<Italic:\"Forgive my sudden departure. Lady Sorel feared for your safety and made new arrangements. I am heading to the villa where 'Memories' resides.\">"
  },
  AvgDialog_131229_Content_69 = {
    Text = "<Italic:\"I am deeply grateful for your care. I will find a way to repay this debt.\">"
  },
  AvgDialog_131229_Content_7 = {
    Text = "<Shake:Huff... huff...>"
  },
  AvgDialog_131229_Content_70 = {
    Text = "Sorel would have told us if she changed the plan..."
  },
  AvgDialog_131229_Content_71 = {
    Text = "You look at Arachne's calm eyes. Behind her eternal, serene smile, you catch a fleeting shadow of concern."
  },
  AvgDialog_131229_Content_72 = {
    Text = "\"Memories\" is homeless. She has no villa."
  },
  AvgDialog_131229_Content_73 = {
    Text = "What?!! Then..."
  },
  AvgDialog_131229_Content_74 = {
    Text = "Nefraea has likely tampered with Memory's fate as well. They are both in grave danger."
  },
  AvgDialog_131229_Content_75 = {
    Text = "I'm sorry. I didn't realize..."
  },
  AvgDialog_131229_Content_76 = {
    Text = "This is not your fault, Miss Salle."
  },
  AvgDialog_131229_Content_77 = {
    Text = "If Nefraea can rewrite your destiny, finding those around you is a simple task. This is our burden to bear."
  },
  AvgDialog_131229_Content_78 = {
    Text = "The ink isn't even dry. She was here recently—if we hurry, we might still make it."
  },
  AvgDialog_131229_Content_79 = {
    Text = "Liz, there are things I wanted to say, but there's no time..."
  },
  AvgDialog_131229_Content_8 = {
    Text = "You finally stop once the face is nothing but a pulp."
  },
  AvgDialog_131229_Content_80 = {
    Text = "There will be other chances, {Male=Mr.,Female=Miss} Keeper. I hope my next dance moves you just as much."
  },
  AvgDialog_131229_Content_81 = {
    Text = "With a simple farewell smile, Liz turns back to her own world."
  },
  AvgDialog_131229_Content_82 = {
    Text = "She raises her arms, mimicking the curve of the corpse she saw, trying to capture the pose that has haunted her mind."
  },
  AvgDialog_131229_Content_83 = {
    Text = "The breeze stirs her skirt. She looks just like a swan in flight."
  },
  AvgDialog_131229_Content_9 = {
    Text = "Liz's manipulated corpse has lost all sign of life. You lay her mangled body gently on the floor and activate the spiritual link."
  },
  AvgDialog_131230_Content_1 = {
    Text = "The Curtain Falls"
  },
  AvgDialog_131230_Content_10 = {
    Text = "...You miss them, don't you?"
  },
  AvgDialog_131230_Content_11 = {
    Text = "I would rather see the stage present itself as it truly is than have a perfect cup of coffee."
  },
  AvgDialog_131230_Content_12 = {
    Text = "I recreated this place from memory, yet I cannot change the fact that it is a brand-new stage."
  },
  AvgDialog_131230_Content_13 = {
    Text = "Besides, the new coffee here has its own unique flavor, does it not?"
  },
  AvgDialog_131230_Content_14 = {
    Text = "Arachne smiles and takes a small sip of the bitter liquid."
  },
  AvgDialog_131230_Content_15 = {
    Text = "Nefraea... what happened to her in the end? I mean..."
  },
  AvgDialog_131230_Content_16 = {
    Text = "The Web of Fate is singular. Those like her are Abandoned Fates—even if they escape the Abyssal Prison, they vanish if they cannot leave a mark upon this web."
  },
  AvgDialog_131230_Content_17 = {
    Text = "She... faded away, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131230_Content_18 = {
    Text = "The spindle turns softly, endlessly. Arachne closes her eyes and tilts her head back, breathing in the faint scent of flowers carried on the wind."
  },
  AvgDialog_131230_Content_19 = {
    Text = "The Abandoned Fates... faced with only eternal imprisonment or complete annihilation. How cruel..."
  },
  AvgDialog_131230_Content_2 = {
    Text = "<Italic:Lascia ch'io pianga / Let me weep over\nmia cruda sorte, / my cruel fate,\nE che sospiri la libertà! / and sigh for my liberty!>"
  },
  AvgDialog_131230_Content_20 = {
    Text = "At every moment, Fate requires a Choice. The right paths remain, while the wrong ones are cast aside. Until we find the True Path, this is as inevitable as the collapse of the universe itself."
  },
  AvgDialog_131230_Content_21 = {
    Text = "Until we find the True Path, this is as inevitable as the collapse of the universe itself."
  },
  AvgDialog_131230_Content_22 = {
    Text = "Tell me, {Male=Mr.,Female=Miss} Keeper, if you had the power to control Fate, would you let it descend into chaos? Or would you make the choice for others, even if it meant bearing the name of a killer?"
  },
  AvgDialog_131230_Content_23 = {
    Text = "I... I don't know."
  },
  AvgDialog_131230_Content_24 = {
    Text = "This is merely a debate for your amusement, not a question you must answer. You already carry far too much; you do not need to shoulder this weight."
  },
  AvgDialog_131230_Content_25 = {
    Text = "Arachne shakes her head with a gentle smile."
  },
  AvgDialog_131230_Content_26 = {
    Text = "Choice is a form of power, yet many choose to surrender it even when it is within their grasp."
  },
  AvgDialog_131230_Content_27 = {
    Text = "To choose is to bear the consequences, and that is no easy task, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131230_Content_28 = {
    Text = "I am the Master of Fate. Every consequence of destiny rests on my shoulders."
  },
  AvgDialog_131230_Content_29 = {
    Text = "These were the words bestowed upon me when I first knocked on the Gate of Chokmah-Da'at. I accepted them with open arms."
  },
  AvgDialog_131230_Content_3 = {
    Text = "The melodious singing rings through the streets, drifting gracefully on a gentle breeze. Passersby on the path pause or continue on, savoring the quiet life found in this pocket of spring."
  },
  AvgDialog_131230_Content_30 = {
    Text = "So... even though you cannot see your own fate, you knew all of this was coming. Everything happening right now... you knew."
  },
  AvgDialog_131230_Content_31 = {
    Text = "Warm sunlight bathes the street. As you study Arachne's calm face and imagine the burden she faces every day, you cannot help but shudder."
  },
  AvgDialog_131230_Content_32 = {
    Text = "Romance brings foolishness, Kindness brings fragility, Memories bring pain..."
  },
  AvgDialog_131230_Content_33 = {
    Text = "Even though you prepared yourself for this long ago, you never truly let them go. Why?"
  },
  AvgDialog_131230_Content_34 = {
    Text = "Letting them go would have made your life so much easier."
  },
  AvgDialog_131230_Content_35 = {
    Text = "Have you ever visited a prison? Inmates locked away for years always keep a small treasure close to them."
  },
  AvgDialog_131230_Content_36 = {
    Text = "A medal won in a fight, an heirloom watch, a family photo..."
  },
  AvgDialog_131230_Content_37 = {
    Text = "For a prisoner, the very desires that torment them are the only things that keep them alive."
  },
  AvgDialog_131230_Content_38 = {
    Text = "They retain these most cherished possessions until death draws near. Only then do they surrender those worthless things, one by one."
  },
  AvgDialog_131230_Content_39 = {
    Text = "...In the cage of Fate, we have nothing else, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131230_Content_4 = {
    Text = "You pick up your coffee and take a long sip."
  },
  AvgDialog_131230_Content_40 = {
    Text = "<Italic:Il duolo infranga / May sorrow shatter\nqueste ritorte / these chains\nde miei martiri / of my torments\nsol per pietà. / out of pity alone>"
  },
  AvgDialog_131230_Content_41 = {
    Text = "A street singer performs for the river of Fate flowing through the city. Arachne sips her coffee, listening intently. From beginning to end, her smile never wavers."
  },
  AvgDialog_131230_Content_42 = {
    Text = "You know, {Male=Mr.,Female=Miss} Keeper, I often dream of the same scene over and over."
  },
  AvgDialog_131230_Content_43 = {
    Text = "It is a beautiful theater, and only Nefraea and I are there. It is to this beautiful song that I say my farewell to her."
  },
  AvgDialog_131230_Content_44 = {
    Text = "You see, even when we cannot see our own fate clearly, its verdict is everywhere."
  },
  AvgDialog_131230_Content_45 = {
    Text = "<Italic:E che sospiri la libertà! / And sigh for my liberty!\nE che sospiri la libertà! / And sigh for my liberty!>"
  },
  AvgDialog_131230_Content_46 = {
    Text = "The singer's voice holds its note as the threads of the spinning wheel turn eternally. Arachne sets down her cup and joins the audience in soft, sincere applause."
  },
  AvgDialog_131230_Content_47 = {
    Text = "Regardless, the performance has reached its end. This stage earns a brief moment of rest. We, the performers, must make our way to the next act."
  },
  AvgDialog_131230_Content_48 = {
    Text = "Nefraea's influence has faded. Can the passage to Kadath be reopened now?"
  },
  AvgDialog_131230_Content_49 = {
    Text = "The passage to Kadath lies within the fate of this world. You have already attempted to cross dimensions."
  },
  AvgDialog_131230_Content_5 = {
    Text = "Not even close to Bosnian coffee."
  },
  AvgDialog_131230_Content_50 = {
    Text = "You already know the dangers that lie within."
  },
  AvgDialog_131230_Content_51 = {
    Text = "Tohuwabohu's Gaze... I have no desire to face it again."
  },
  AvgDialog_131230_Content_52 = {
    Text = "Arachne, you control the Fate of this world—perhaps you have a way to help me?"
  },
  AvgDialog_131230_Content_53 = {
    Text = "I would be happy to help, but only this city is my stage. I am not the Master of Fate for this entire world."
  },
  AvgDialog_131230_Content_54 = {
    Text = "What? No way..."
  },
  AvgDialog_131230_Content_55 = {
    Text = "The master of this world possesses abilities beyond even my reach. His will has the power to isolate this world from the dream of Tohuwabohu."
  },
  AvgDialog_131230_Content_56 = {
    Text = "Unless the passage is deliberately opened, this place remains hidden from the Divine sight... That is precisely why I chose to dwell here."
  },
  AvgDialog_131230_Content_57 = {
    Text = "Does that mean opening the portal puts this place in danger?"
  },
  AvgDialog_131230_Content_58 = {
    Text = "As I said, Fate follows its own trail. Dwelling here is merely a slow wait for death. Helping you return to Kadath is also the long-held wish of this world's master."
  },
  AvgDialog_131230_Content_59 = {
    Text = "Compared to the light ahead on the path of destiny, this is a danger we are more than willing to bear."
  },
  AvgDialog_131230_Content_6 = {
    Text = "I thought it was quite good when I tasted it on that stage last time. Unfortunately, on this specific stage, the family that invented that blend died out long ago."
  },
  AvgDialog_131230_Content_60 = {
    Text = "I see. I understand now."
  },
  AvgDialog_131230_Content_61 = {
    Text = "Where can I find Him?"
  },
  AvgDialog_131230_Content_62 = {
    Text = "His Threads of Fate are as vast as a sea of stars, yet as fleeting as wisps of smoke. I cannot point you directly to his location."
  },
  AvgDialog_131230_Content_63 = {
    Text = "But perhaps this will help you."
  },
  AvgDialog_131230_Content_64 = {
    Text = "Arachne hands you a slip of paper. You furrow your brow, staring at the elegant, ornate script written with religious reverence."
  },
  AvgDialog_131230_Content_65 = {
    Text = "Job Posting:"
  },
  AvgDialog_131230_Content_66 = {
    Text = "The great leader, the Chosen One of the Divine, Proxy of the Supreme God, Rightful Heir of the Grand Order, Savior of the Suffering, and Bosom Friend of the God-King, has arrived in Hyperborea. The sect is expanding rapidly—believers are welcome to come and pay their respects."
  },
  AvgDialog_131230_Content_67 = {
    Text = "The first twelve faithful to arrive shall be ordained as saints, following the Fairy's side forever, blessed by the Divine for all eternity..."
  },
  AvgDialog_131230_Content_68 = {
    Text = "What on earth is this...?"
  },
  AvgDialog_131230_Content_69 = {
    Text = "As you can see, it is a carefully crafted brochure."
  },
  AvgDialog_131230_Content_7 = {
    Text = "You survey the city. The Brick Crossroads, Time Wrinkle Bookshop, Fragrant Market Grocery..."
  },
  AvgDialog_131230_Content_70 = {
    Text = "This content is incredibly weird... Arachne, you can see the course of Fate—are you sure this isn't a trick?"
  },
  AvgDialog_131230_Content_71 = {
    Text = "I saw your silhouette on these threads. I am certain—this is the destiny you are about to meet."
  },
  AvgDialog_131230_Content_72 = {
    Text = "Whether it brings help or danger, I cannot say. But I know that this is the only connection between you and the one who rules this world."
  },
  AvgDialog_131230_Content_73 = {
    Text = "I see. I'll go, then..."
  },
  AvgDialog_131230_Content_74 = {
    Text = "In my brief glimpse into your threads, I saw an interesting story. I could not see your ending, and that is our good fortune."
  },
  AvgDialog_131230_Content_75 = {
    Text = "I believe that when you return to that gateway, the fate of the entire universe will tremble because of you."
  },
  AvgDialog_131230_Content_77 = {
    Text = "Arachne picks up the coffee. Out of your sight, her lips curl slightly into a sly arc."
  },
  AvgDialog_131230_Content_8 = {
    Text = "Everything remains unchanged. Even the patches of rust on the shop signs look exactly as you remember them."
  },
  AvgDialog_131230_Content_9 = {
    Text = "Since you recreated this city... I thought you would bring back the things that disappeared."
  },
  AvgDialog_131231_Content_1 = {
    Text = "Phew... made it just in time."
  },
  AvgDialog_131231_Content_10 = {
    Text = "Sorel narrows her eyes, studying Arachne. She finds that her gift for reading people—a skill she prides herself on—has completely failed. She cannot see this woman's past, nor can she fathom her desires."
  },
  AvgDialog_131231_Content_11 = {
    Text = "Every detail Sorel tries to commit to memory vanishes in the blink of an eye. Her lips curl into an intrigued smile."
  },
  AvgDialog_131231_Content_12 = {
    Text = "Two captivating guests. This salon will certainly be unforgettable. Please, take a seat."
  },
  AvgDialog_131231_Content_13 = {
    Text = "Sorel sits on the sofa and gestures for you to join her."
  },
  AvgDialog_131231_Content_14 = {
    Text = "I've crossed paths with \"Kindness\" a few times. He came to me seeking asylum."
  },
  AvgDialog_131231_Content_15 = {
    Text = "You saved me. I cannot see your true identities, but I can tell you mean no harm."
  },
  AvgDialog_131231_Content_16 = {
    Text = "That's right, Lady Sorel. We're here to save him."
  },
  AvgDialog_131231_Content_17 = {
    Text = "He isn't at the manor."
  },
  AvgDialog_131231_Content_18 = {
    Text = "But you just said..."
  },
  AvgDialog_131231_Content_19 = {
    Text = "As you can see, my estate is hardly a sanctuary."
  },
  AvgDialog_131231_Content_2 = {
    Text = "After checking on Karen, you stand up and wipe the cold sweat from your brow."
  },
  AvgDialog_131231_Content_20 = {
    Text = "Sorel raises her arm, gesturing toward the mangled corpses scattered across her immaculate room as if showcasing a prized collection."
  },
  AvgDialog_131231_Content_21 = {
    Text = "He is a kind man, but by no means a fool. I could tell his situation was dire."
  },
  AvgDialog_131231_Content_22 = {
    Text = "Many people know of my association with him. Hiding him here would have been unwise."
  },
  AvgDialog_131231_Content_23 = {
    Text = "Where is he now?"
  },
  AvgDialog_131231_Content_24 = {
    Text = "Sorel stands and walks to an oil painting. You follow her, taking in the image."
  },
  AvgDialog_131231_Content_25 = {Text = "That's...!"},
  AvgDialog_131231_Content_26 = {
    Text = "Years ago, I attended a performance by the Cycnus Dance Troupe at the Londinium Theater. It was a mere social obligation, but her dancing deeply moved me."
  },
  AvgDialog_131231_Content_27 = {
    Text = "Over the years, I've occasionally visited the backstage areas. We have no real public connection, which makes her troupe the perfect place to hide \"Kindness.\""
  },
  AvgDialog_131231_Content_28 = {
    Text = "In the painting, Liz is dressed in ethereal dance attire, leaping high into the air like a swan in flight."
  },
  AvgDialog_131231_Content_29 = {
    Text = "Liz... where is her troupe now?"
  },
  AvgDialog_131231_Content_3 = {
    Text = "Karen should be fine. She's been affected by the possession, but she'll recover with some rest."
  },
  AvgDialog_131231_Content_30 = {
    Text = "Arachne follows the tightening Threads of Fate, looking out the window toward a spot hidden deep within the woods."
  },
  AvgDialog_131231_Content_31 = {
    Text = "In a place you know all too well."
  },
  AvgDialog_131231_Content_4 = {
    Text = "I can recall every face I've ever seen, yet you feel... strange. I can't be sure if we've met. That has never happened to me before."
  },
  AvgDialog_131231_Content_5 = {
    Text = "Sorel picks up an upright bottle from the table and pours a drink. Stepping over the dissolving corpses, she offers the glass to you."
  },
  AvgDialog_131231_Content_6 = {
    Text = "A forty-year-old vintage Port from my private collection. The hyenas downstairs aren't worthy of a single drop. Whoever you are, I believe this glass belongs to you."
  },
  AvgDialog_131231_Content_7 = {
    Text = "We are here for \"Kindness,\" Lady Sorel."
  },
  AvgDialog_131231_Content_8 = {
    Text = "Arachne takes the glass and offers a small, polite nod."
  },
  AvgDialog_131231_Content_9 = {
    Text = "While silent, she is as inconspicuous as a spiderweb in the morning light. The moment she speaks, however, she seems to draw every bit of radiance in the room toward her."
  },
  AvgDialog_131232_Content_1 = {
    Text = "What a spectacular performance, sister."
  },
  AvgDialog_131232_Content_10 = {
    Text = "You and your squires are those without destiny; I cannot grasp your threads. But since your power originates from mine, you are as blind to your own fate as I am to mine."
  },
  AvgDialog_131232_Content_11 = {
    Text = "You and I... this is a stalemate. A pointless war that should never have begun."
  },
  AvgDialog_131232_Content_12 = {
    Text = "Of course, of course. To you, we \"discarded things\" belong in the graveyard of Fate—to be dismantled, forgotten, and dissolved for all eternity."
  },
  AvgDialog_131232_Content_13 = {
    Text = "What a pity you cannot see 'Him'... No matter how great your power, how could you ever compare to the Supreme Deity?"
  },
  AvgDialog_131232_Content_14 = {
    Text = "You know it. You know deep down that all of this is futile. And yet, you cannot stop spinning your web..."
  },
  AvgDialog_131232_Content_15 = {
    Text = "Because you have seen the threads, you cannot bear the sight of them tangled. Because you have the power, you cannot stand by and watch worlds fall into endless chaos."
  },
  AvgDialog_131232_Content_16 = {
    Text = "You offer them a false peace while leading them down a path that ends only in ruin."
  },
  AvgDialog_131232_Content_17 = {
    Text = "What a pitiful creature you are, Arachne."
  },
  AvgDialog_131232_Content_18 = {
    Text = "This is our destiny, Nefraea."
  },
  AvgDialog_131232_Content_19 = {
    Text = "Ah... I'm getting sleepy. Arguing with a fool is the most tedious thing in the world."
  },
  AvgDialog_131232_Content_2 = {
    Text = "The lively bar falls silent. The corpses strewn across the floor dissolve into black sludge and dust, fading away under the warm lights."
  },
  AvgDialog_131232_Content_20 = {
    Text = "Welcome to Act Two. This is your stage, but from now on, I will be the one writing the script."
  },
  AvgDialog_131232_Content_21 = {
    Text = "The opening notes are the most important, aren't they? What should we call it... how about \"Reunion\"?"
  },
  AvgDialog_131232_Content_22 = {
    Text = "Nefraea seems delighted with the name. She dips a spider-like limb into her drink, tastes it, and lets out a blissful sigh."
  },
  AvgDialog_131232_Content_23 = {
    Text = "I have prepared so very long for this day. I'm going to savor every moment of our story together, dear sister."
  },
  AvgDialog_131232_Content_24 = {
    Text = "Without giving you a chance to question her further, Nefraea grazes Arachne's cheek with a sharp nail and then collapses to the floor."
  },
  AvgDialog_131232_Content_25 = {Text = "Wait...!"},
  AvgDialog_131232_Content_26 = {
    Text = "She is not here, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131232_Content_27 = {
    Text = "With a bubbling sound, black sludge sloughs off the corpse's face once more."
  },
  AvgDialog_131232_Content_28 = {
    Text = "Romance's eyes remain fixed in a smile, even as black spiders crawl through her hollowed body, visible behind her clouded gaze. Her elegant lips will never speak again."
  },
  AvgDialog_131232_Content_29 = {Text = "This is..."},
  AvgDialog_131232_Content_3 = {
    Text = "Nefraea and Arachne remain seated across from each other. Nefraea makes a glass of cocktail and slides it toward her sister."
  },
  AvgDialog_131232_Content_30 = {
    Text = "She murdered this Puppet. She left her mark, polluted her fate, and used her as a temporary vessel."
  },
  AvgDialog_131232_Content_31 = {
    Text = "Arachne approaches the Puppet and reaches toward her head, staring at the thread of fate that has nearly vanished."
  },
  AvgDialog_131232_Content_32 = {
    Text = "...Can you see anything?"
  },
  AvgDialog_131232_Content_33 = {
    Text = "The other Puppets have been polluted as well; I can no longer sense them through the Great Web. But Romance's fate was connected to theirs."
  },
  AvgDialog_131232_Content_34 = {
    Text = "She showed me where to find \"Kindness.\""
  },
  AvgDialog_131232_Content_35 = {
    Text = "Arachne releases the thread and gently brushes Romance's bangs back into place."
  },
  AvgDialog_131232_Content_36 = {
    Text = "Nefraea's power is derived from mine. I cannot see the fates she has polluted, and my own abilities are hindered because of it."
  },
  AvgDialog_131232_Content_37 = {
    Text = "You are a fragment of the Divine—one whose fate is invisible to us. That is why I need your help, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_131232_Content_38 = {
    Text = "Don't worry. If only to return to Kadath, I must deal with her."
  },
  AvgDialog_131232_Content_39 = {
    Text = "Why is she hunting these Puppets?"
  },
  AvgDialog_131232_Content_4 = {
    Text = "Even if Ms. \"Romance\" is gone, we shouldn't let a good drink go to waste."
  },
  AvgDialog_131232_Content_40 = {
    Text = "These Puppets will become the source of her power."
  },
  AvgDialog_131232_Content_41 = {
    Text = "Then we need to move fast. We have to find the Puppets and the dimensional embers you need to weave."
  },
  AvgDialog_131232_Content_42 = {
    Text = "This Puppet called \"Kindness\"... where is he?"
  },
  AvgDialog_131232_Content_43 = {
    Text = "Romance managed to warn him of the danger before she fell. He is in hiding now, sheltered by an old friend of yours."
  },
  AvgDialog_131232_Content_44 = {
    Text = "An old friend...?"
  },
  AvgDialog_131232_Content_45 = {
    Text = "Follow me, {Male=Mr.,Female=Miss} Keeper. Lady Sorel's grand salon is about to begin."
  },
  AvgDialog_131232_Content_5 = {
    Text = "Want a sip? I understand you far better than that Puppet ever could."
  },
  AvgDialog_131232_Content_6 = {
    Text = "Arachne doesn't hesitate. She smiles, raises the glass, and takes a refined sip."
  },
  AvgDialog_131232_Content_7 = {
    Text = "You aren't cut out for this trade, Nefraea. This drink has nothing to offer but bitterness."
  },
  AvgDialog_131232_Content_8 = {
    Text = "I call it \"Fate.\" Do you like the taste?"
  },
  AvgDialog_131232_Content_9 = {
    Text = "Arachne ignores the expectant look in Nefraea's eyes. She finishes the cocktail slowly and sets the glass back on the table."
  },
  AvgDialog_13733_Content_1 = {
    Text = "Vermilion rite"
  },
  AvgDialog_13733_Content_10 = {
    Text = "Heh, you can never rely on the insight of the Remouans. Keep your eyes wide open and watch..."
  },
  AvgDialog_13733_Content_11 = {
    Text = "Prine pulled a ritual knife from his sleeve and, without hesitation, cut his own wrist."
  },
  AvgDialog_13733_Content_12 = {
    Text = "Crimson blood drips onto the sulfur-lined magic circle, and just like that, a miracle occurs—"
  },
  AvgDialog_13733_Content_13 = {
    Text = "Like a drop of water in a desert, the magic circle absorbed the fresh blood, radiating rings of dark red light"
  },
  AvgDialog_13733_Content_14 = {
    Text = "They are like flames under the dark sky, greedily licking the wind-swept sands, as if devouring the entire earth."
  },
  AvgDialog_13733_Content_15 = {
    Text = "Did you see that? This is the true magical moment! Hahaha!"
  },
  AvgDialog_13733_Content_16 = {
    Text = "Hahaha...<Big:Ugh!!!>"
  },
  AvgDialog_13733_Content_17 = {
    Text = "Prine \"plop\" fell to his knees, uncontrollably clutching his throat."
  },
  AvgDialog_13733_Content_18 = {
    Text = "The chain connecting him and Uvhash tightened quickly, binding their flesh and souls together"
  },
  AvgDialog_13733_Content_19 = {
    Text = "Hmm... What...?"
  },
  AvgDialog_13733_Content_2 = {
    Text = [[
Edge of the Kuxi Desert
Ritual Site]]
  },
  AvgDialog_13733_Content_20 = {
    Text = "Uvhash could no longer maintain a relaxed sitting posture."
  },
  AvgDialog_13733_Content_21 = {
    Text = "He was suddenly knocked over by an invisible force, staring blankly at the runaway magic circle before him"
  },
  AvgDialog_13733_Content_22 = {Text = "Hmm..."},
  AvgDialog_13733_Content_23 = {
    Text = "<Big:AHHH!>"
  },
  AvgDialog_13733_Content_24 = {
    Text = "Prinn lay on the ground, glaring viciously at the struggling Uvhash, and started laughing."
  },
  AvgDialog_13733_Content_25 = {
    Text = "Is it painful...? Good, it should be."
  },
  AvgDialog_13733_Content_26 = {
    Text = "At this moment, our consciousness is tightly linked together..."
  },
  AvgDialog_13733_Content_27 = {
    Text = "Did you see how the Remouahe dogs slaughtered my kin and defiled my wife... did you feel it..."
  },
  AvgDialog_13733_Content_28 = {
    Text = "<Big:Answer me, you @1 fool!>"
  },
  AvgDialog_13733_Content_29 = {Text = "Heh heh..."},
  AvgDialog_13733_Content_3 = {
    Text = "Good, first sprinkle a layer of sulfur, then charcoal powder..."
  },
  AvgDialog_13733_Content_30 = {
    Text = "Don't get too excited... old man."
  },
  AvgDialog_13733_Content_31 = {
    Text = "Once I break free from these chains, the first person I tear apart will be you—ugh!!"
  },
  AvgDialog_13733_Content_32 = {
    Text = "Unfortunately, it seems that your wish will not come true this time..."
  },
  AvgDialog_13733_Content_33 = {
    Text = "Pulin panted heavily, trembling as he gripped the invisible chain, then gave it a sharp pull—"
  },
  AvgDialog_13733_Content_34 = {
    Text = "The once unbreakable chains have now shattered."
  },
  AvgDialog_13733_Content_35 = {
    Text = "Hehe@3 Ah@1 Ah!!"
  },
  AvgDialog_13733_Content_36 = {
    Text = "Pryn let out a painful wail, the skin on his face rotting and peeling like tree bark, revealing the blurred Caro underneath."
  },
  AvgDialog_13733_Content_37 = {
    Text = "The magic circle opens its gaping maw, devouring his Caro bit by bit until the wizard is reduced to nothing but an empty skeleton."
  },
  AvgDialog_13733_Content_38 = {
    Text = "I have sacrificed my Caro, Soul, and everything... What about you..."
  },
  AvgDialog_13733_Content_39 = {
    Text = "You will never achieve true freedom until you have killed 10,000 Remouahe dogs!"
  },
  AvgDialog_13733_Content_4 = {
    Text = "No, let's see what the book says..."
  },
  AvgDialog_13733_Content_40 = {
    Text = "Uvhash slowly stood up."
  },
  AvgDialog_13733_Content_41 = {
    Text = "His face was burned to black ashes by invisible flames, crumbling away with the slightest breeze."
  },
  AvgDialog_13733_Content_42 = {Text = "Heh..."},
  AvgDialog_13733_Content_43 = {
    Text = "\"True freedom\"...? What is that?"
  },
  AvgDialog_13733_Content_44 = {
    Text = "The scorched warrior stands amidst the searing flames. His eyes are blood-red, and only a hoarse tremor escapes his throat."
  },
  AvgDialog_13733_Content_45 = {
    Text = "I, Uvhash, have always truly cared about only one thing—"
  },
  AvgDialog_13733_Content_46 = {
    Text = "He rushed out at lightning speed, tackling the wizard to the ground."
  },
  AvgDialog_13733_Content_47 = {
    Text = "Then he bared his sharp fangs and viciously bit through the wizard's neck."
  },
  AvgDialog_13733_Content_48 = {
    Text = "<Red:That's blood!>"
  },
  AvgDialog_13733_Content_49 = {Text = "Mr. Prinn!"},
  AvgDialog_13733_Content_5 = {
    Text = "Within fifty yards of the battlefield, Pulin is hard at work."
  },
  AvgDialog_13733_Content_50 = {
    Text = "<Shake:This life, for you... revenge@2 help me...>"
  },
  AvgDialog_13733_Content_51 = {
    Text = "Help you? Old man, are you mistaken...?"
  },
  AvgDialog_13733_Content_52 = {
    Text = "Prey has no right to make demands of Uvhash."
  },
  AvgDialog_13733_Content_53 = {
    Text = "I listen to you not because of that damn contract, but because I can smash your iron chain toy anytime."
  },
  AvgDialog_13733_Content_54 = {
    Text = "The game time is over. Now, I want you to watch closely—"
  },
  AvgDialog_13733_Content_55 = {
    Text = "Here's how I slaughtered your enemies, your kin, and every living creature you witnessed..."
  },
  AvgDialog_13733_Content_56 = {
    Text = "<Change>Devil... you devil..."
  },
  AvgDialog_13733_Content_57 = {
    Text = "Prinn's blood flowed freely within the magic circle, rendering the crimson light dim"
  },
  AvgDialog_13733_Content_58 = {
    Text = "He sacrificed his life to grant Uvhash \"freedom\"."
  },
  AvgDialog_13733_Content_59 = {
    Text = "Hehe... Aah@4..."
  },
  AvgDialog_13733_Content_6 = {
    Text = "Uvhash was seated at the center of the magic circle drawn with sulfur powder, at Pulin's request."
  },
  AvgDialog_13733_Content_60 = {
    Text = "Uvhash slowly raised his head, blood still lingering on his lips, his eyes already consumed by darkness."
  },
  AvgDialog_13733_Content_61 = {
    Text = "He transformed into a true beast. Or rather, this was his original form."
  },
  AvgDialog_13733_Content_62 = {
    Text = "<Red:It's back, everything has returned...>"
  },
  AvgDialog_13733_Content_7 = {
    Text = "Huff... huff..."
  },
  AvgDialog_13733_Content_8 = {
    Text = "Impressive, you can still fall asleep even in this situation..."
  },
  AvgDialog_13733_Content_9 = {
    Text = [[
I have a technical question for you, Mr. Pulin.
Won't the powder you scattered be blown away by the wind?]]
  },
  AvgDialog_13734_Content_1 = {
    Text = [[
Huff... Finally caught up.
I'm warning you, Uvhash. You know the consequences of leaving without permission, right?]]
  },
  AvgDialog_13734_Content_10 = {
    Text = "You've finally reached the end of your journey. Prinn let out a couple of strange laughs, his body trembling with the flames of vengeance."
  },
  AvgDialog_13734_Content_11 = {
    Text = "<Shake:Let's go, Uvhash...>"
  },
  AvgDialog_13734_Content_12 = {
    Text = "<Red:Go and kill to your heart's content.>"
  },
  AvgDialog_13734_Content_2 = {Text = "Shh!!"},
  AvgDialog_13734_Content_3 = {
    Text = "Uvhash squatted on a high dune, emitting an impatient hiss through his nostrils, like a hunting beast being bothered by insects."
  },
  AvgDialog_13734_Content_4 = {
    Text = "His lips slightly parted, his nostrils faintly quivered, and the blood-red gleam in his eyes grew more intense than ever."
  },
  AvgDialog_13734_Content_5 = {
    Text = "<RedShake:Found it, found it...>"
  },
  AvgDialog_13734_Content_6 = {
    Text = "You follow his gaze downward—"
  },
  AvgDialog_13734_Content_7 = {
    Text = "Countless tiny black dots are scattered across the undulating dunes, like ants wriggling on a sand table."
  },
  AvgDialog_13734_Content_8 = {
    Text = "The clash of weapons, roars, and the sound of hooves fill the air, unfolding a grand scene of war before you"
  },
  AvgDialog_13734_Content_9 = {
    Text = "Remouans, Leonians... Good, very good."
  },
  AvgDialog_13735_Content_1 = {
    Text = "Solar expedition"
  },
  AvgDialog_13735_Content_10 = {
    Text = "He remained bound by invisible chains, sitting awkwardly on the ground, almost blending into the darkness."
  },
  AvgDialog_13735_Content_11 = {
    Text = "...Didn't expect you to be awake."
  },
  AvgDialog_13735_Content_12 = {
    Text = "<Yellow:Golem> does not need to sleep."
  },
  AvgDialog_13735_Content_13 = {Text = "Golem...?"},
  AvgDialog_13735_Content_14 = {
    Text = "Heh... Stop pretending."
  },
  AvgDialog_13735_Content_15 = {
    Text = "You can see the chains on me, so you must know what a Golem is."
  },
  AvgDialog_13735_Content_16 = {
    Text = [[
I didn't expect him to notice your seemingly casual glance.
He truly possesses the instincts of a beast.]]
  },
  AvgDialog_13735_Content_17 = {
    Text = "My teacher once told me..."
  },
  AvgDialog_13735_Content_18 = {
    Text = "In ancient Rome, a mad alchemist created the earliest golem at the cost of many human sacrifices."
  },
  AvgDialog_13735_Content_19 = {
    Text = "This is also the closest existence to an Awakener in ancient texts."
  },
  AvgDialog_13735_Content_2 = {
    Text = "Northern Kusi Desert, Night"
  },
  AvgDialog_13735_Content_20 = {
    Text = "That golem, it's you, right?"
  },
  AvgDialog_13735_Content_21 = {
    Text = "That's right... It's me. I became <Blue:Caligula>'s henchman and killed many for him."
  },
  AvgDialog_13735_Content_22 = {
    Text = "Later, they no longer needed me and locked me in an underground place so dark that I couldn't see my hand in front of my face, until that person released me."
  },
  AvgDialog_13735_Content_23 = {
    Text = "Uvhash speaks, his eyes glancing at Prine, who is still snoring in the tent."
  },
  AvgDialog_13735_Content_24 = {
    Text = "—What's the condition?"
  },
  AvgDialog_13735_Content_25 = {
    Text = "The condition is to serve him like a dog and kill many Remouahe people on the battlefield."
  },
  AvgDialog_13735_Content_26 = {
    Text = "Then we go our separate ways and live our own lives."
  },
  AvgDialog_13735_Content_27 = {
    Text = "Uvhash stretched comfortably, lounging on the dune with legs spread apart."
  },
  AvgDialog_13735_Content_28 = {
    Text = "These chains can't hold you. Why not just kill the wizard and leave?"
  },
  AvgDialog_13735_Content_29 = {
    Text = "Because he said, \"There are many people on the battlefield.\""
  },
  AvgDialog_13735_Content_3 = {
    Text = "Snore... Snore... Whoosh..."
  },
  AvgDialog_13735_Content_30 = {
    Text = "<Red:Where there are many people, there will be much blood.>"
  },
  AvgDialog_13735_Content_31 = {
    Text = "<RedShake:You know, it's been nearly a thousand years since I last tasted that blood...>"
  },
  AvgDialog_13735_Content_32 = {Text = "..."},
  AvgDialog_13735_Content_33 = {
    Text = "That guy doesn't look like someone who keeps his promises. What if he deceives you?"
  },
  AvgDialog_13735_Content_34 = {
    Text = "Just kill him. Simple, isn't it?"
  },
  AvgDialog_13735_Content_35 = {Text = "..."},
  AvgDialog_13735_Content_36 = {
    Text = "I have to admit, he made a valid point."
  },
  AvgDialog_13735_Content_37 = {
    Text = "The evening breeze gently blows, the soft undulating dunes stretch endlessly before you, leaving only two tiny figures beneath the vast sky."
  },
  AvgDialog_13735_Content_38 = {
    Text = "You look up at the starry sky."
  },
  AvgDialog_13735_Content_39 = {
    Text = "To while away this long night, you decide to exchange some experiences with the golem before you."
  },
  AvgDialog_13735_Content_4 = {
    Text = "In the silent night, Prinn's thunderous snores indicate that the minor incident during the day has not affected his sound sleep."
  },
  AvgDialog_13735_Content_40 = {
    Text = [[
Being locked underground must be tough.
Once you fulfill the promise, you'll regain your freedom. How do you feel now?]]
  },
  AvgDialog_13735_Content_41 = {
    Text = [[
What about you?
You've long been free from slavery, wandering the desert to make a living. How does it feel?]]
  },
  AvgDialog_13735_Content_42 = {Text = "..."},
  AvgDialog_13735_Content_43 = {
    Text = "Not great at all. Can't even see the sun in this wretched place..."
  },
  AvgDialog_13735_Content_44 = {
    Text = "You must be truly blind. Can't you see the huge sun in the desert?"
  },
  AvgDialog_13735_Content_45 = {
    Text = "You don't get it. I'm talking about the gentle, bright, and warm sun... You won't see that in the desert."
  },
  AvgDialog_13735_Content_46 = {
    Text = [[
You let out a yawn, the drowsiness gradually taking over.
As your guard relaxed, the conversation grew more casual.]]
  },
  AvgDialog_13735_Content_47 = {
    Text = "To your surprise, Uvhash is a fairly decent listener."
  },
  AvgDialog_13735_Content_48 = {
    Text = "You might not believe it, but I actually have a mission to accomplish..."
  },
  AvgDialog_13735_Content_49 = {
    Text = "When I finish all the things I need to do, I'll definitely find a place to lie in the sun and eat lots and lots of small cakes..."
  },
  AvgDialog_13735_Content_5 = {
    Text = "You can't take it anymore and finally step out of the tent."
  },
  AvgDialog_13735_Content_50 = {
    Text = "...difficult to comprehend."
  },
  AvgDialog_13735_Content_51 = {
    Text = "The golem was born from darkness and naturally fears sunlight. Nearly a thousand years of imprisonment have deepened its aversion to the light."
  },
  AvgDialog_13735_Content_52 = {
    Text = "I truly pity you; basking in the sun is the most enjoyable thing in the world..."
  },
  AvgDialog_13735_Content_53 = {
    Text = "It's a pity that even such a wish is hard to achieve for me..."
  },
  AvgDialog_13735_Content_54 = {
    Text = [[
The wind is rising.
Fine sand floats, weaving layers of pale yellow gauze that gently drift under the starry night sky.]]
  },
  AvgDialog_13735_Content_55 = {
    Text = "You hear the pure wind from afar and finally drift off to sleep."
  },
  AvgDialog_13735_Content_56 = {Text = "..."},
  AvgDialog_13735_Content_57 = {
    Text = "Northern Kusi Desert, Daytime"
  },
  AvgDialog_13735_Content_58 = {
    Text = "What the heck! Didn't you just swear a few days ago that there wouldn't be any sandstorms?!"
  },
  AvgDialog_13735_Content_59 = {
    Text = "Pulin glared and pointed at the rolling sandstorm approaching from the horizon."
  },
  AvgDialog_13735_Content_6 = {
    Text = "So beautiful..."
  },
  AvgDialog_13735_Content_60 = {
    Text = "Now you tell me, <Big:What is that@1?>"
  },
  AvgDialog_13735_Content_61 = {Text = "Uh..."},
  AvgDialog_13735_Content_62 = {
    Text = "Before you \"entered the dream,\" the original owner indeed made some insincere promises to slaughter this fat sheep."
  },
  AvgDialog_13735_Content_63 = {
    Text = "Now is not the time to argue; a sandstorm is coming. Run!"
  },
  AvgDialog_13735_Content_64 = {
    Text = "After speaking, you dashed out at full speed, leaving Pulin far behind."
  },
  AvgDialog_13735_Content_65 = {
    Text = "<Big:Hey... Stop right there!>"
  },
  AvgDialog_13735_Content_66 = {
    Text = "Sandstorm? What's that? The scenery looks nice."
  },
  AvgDialog_13735_Content_67 = {
    Text = "Uvhash casually ran to your side, eyes unwaveringly fixed on the distance."
  },
  AvgDialog_13735_Content_68 = {
    Text = "Have you never seen a sandstorm?"
  },
  AvgDialog_13735_Content_69 = {
    Text = "Uvhash shrugged."
  },
  AvgDialog_13735_Content_7 = {
    Text = "Good evening, Mr. Guide."
  },
  AvgDialog_13735_Content_70 = {
    Text = "My past activities were limited to within the city of Rome, so there are many things I haven't seen."
  },
  AvgDialog_13735_Content_71 = {
    Text = "<Shake:Uh... Ugh...>"
  },
  AvgDialog_13735_Content_72 = {
    Text = "Pulled by the chains, Prin, who was lagging far behind you all, was yanked into the air."
  },
  AvgDialog_13735_Content_73 = {
    Text = "<Shake:Slower... slower... I'm dying...>"
  },
  AvgDialog_13735_Content_74 = {
    Text = "Tsk. Almost forgot about that old man."
  },
  AvgDialog_13735_Content_75 = {
    Text = "Uvhash doubled back, easily lifting the pudgy wizard's body."
  },
  AvgDialog_13735_Content_76 = {
    Text = "What... what do you intend to do?"
  },
  AvgDialog_13735_Content_77 = {
    Text = "Do nothing, just help you run a little faster."
  },
  AvgDialog_13735_Content_78 = {
    Text = "Saying this, Uvhash easily tucked the wizard under his arm, took a step forward, and bent his body like a bow."
  },
  AvgDialog_13735_Content_79 = {
    Text = "Hey... I'm warning you, now is not the time to play—<Big:Howl!!!>"
  },
  AvgDialog_13735_Content_8 = {Text = "!!"},
  AvgDialog_13735_Content_80 = {
    Text = "Uvhash kicked off sharply, flying out like an arrow."
  },
  AvgDialog_13735_Content_81 = {
    Text = "Me, you... damn @1, put me down!"
  },
  AvgDialog_13735_Content_82 = {
    Text = [[

Uvhash bursts into hearty laughter.
The sound rides the wind, mingling with golden sands and dust, joyfully rushing toward the horizon.]]
  },
  AvgDialog_13735_Content_83 = {
    Text = "That won't do. I still need you alive to help me regain my freedom!"
  },
  AvgDialog_13735_Content_9 = {
    Text = "Uvhash suddenly popped out from the corner, grinning at you."
  },
  AvgDialog_13736_Content_1 = {
    Text = "Guide, Wizard, and Slave"
  },
  AvgDialog_13736_Content_10 = {
    Text = "Charred and dry, with rough and wild palm lines—these are the hands of a warrior."
  },
  AvgDialog_13736_Content_100 = {
    Text = "Sorry, I have nothing to say to you."
  },
  AvgDialog_13736_Content_101 = {
    Text = "Mercenaries are a group of faithless individuals. As for slaves, they cannot possibly comprehend dignity and honor."
  },
  AvgDialog_13736_Content_102 = {
    Text = "You and that guy, there's no fundamental difference between the two of you."
  },
  AvgDialog_13736_Content_103 = {
    Text = "But I'm well past the age of impulsiveness."
  },
  AvgDialog_13736_Content_104 = {
    Text = [[
First, I can't defeat you.
Second, you're still somewhat useful to me.]]
  },
  AvgDialog_13736_Content_105 = {
    Text = "No matter where you came from, at this very moment, continue leading the team, my guide."
  },
  AvgDialog_13736_Content_11 = {
    Text = "<Gray:Jamila, 32 years old, former Mamulu mercenary, now a desert guide...>"
  },
  AvgDialog_13736_Content_12 = {
    Text = "You silently process your new identity."
  },
  AvgDialog_13736_Content_13 = {
    Text = "Looks like you've \"entered a dream\" again."
  },
  AvgDialog_13736_Content_14 = {
    Text = "Hey, what are you muttering about? If you're awake, get up quickly. My <Blue:slave> and I have urgent matters to attend to."
  },
  AvgDialog_13736_Content_15 = {
    Text = "The short, stout man in peculiar attire is your employer for this job <Blue:Ludwig Prin>."
  },
  AvgDialog_13736_Content_16 = {
    Text = "He impatiently gestured behind him with a whip."
  },
  AvgDialog_13736_Content_17 = {Text = "Hiss..."},
  AvgDialog_13736_Content_18 = {
    Text = "Uvhash—?!"
  },
  AvgDialog_13736_Content_19 = {
    Text = "You then noticed the man concealed behind the sand dunes."
  },
  AvgDialog_13736_Content_2 = {
    Text = [[
@Year 2, the Pope lost power, and the monarchy rose.
The holy city of Acre became a contested land.

Out of fear of the Mamluk forces led by Baibars,
the prince called upon everyone to join the crusade and reclaim the holy city of Acre.]]
  },
  AvgDialog_13736_Content_20 = {
    Text = "He maintained a crouching posture, with his long arms casually resting on the ground, like a beast ready to pounce."
  },
  AvgDialog_13736_Content_21 = {
    Text = "Seeing your shocked expression, he grinned, revealing a row of sharp, white teeth."
  },
  AvgDialog_13736_Content_22 = {
    Text = "What? Do you know me?"
  },
  AvgDialog_13736_Content_24 = {
    Text = "Before you could say a word, the wizard fiercely lashed Youwu with the long whip in his hand."
  },
  AvgDialog_13736_Content_25 = {
    Text = "Bro, I advise you not to talk to him."
  },
  AvgDialog_13736_Content_26 = {
    Text = "Don't be deceived by his human-like eyes and nose; he's still an uncivilized beast, or perhaps..."
  },
  AvgDialog_13736_Content_28 = {
    Text = "Another long whip fiercely lashed onto Youwu."
  },
  AvgDialog_13736_Content_29 = {
    Text = "He's a <Red:demon>."
  },
  AvgDialog_13736_Content_3 = {
    Text = "At this point, the grand <Yellow:Eastern Expedition> begins once again..."
  },
  AvgDialog_13736_Content_30 = {
    Text = "Lashed multiple times, Uvhash didn't even blink."
  },
  AvgDialog_13736_Content_31 = {
    Text = "He wiped the blood flowing from his temple, sniffed his hand, and then slowly licked the blood off his fingertip."
  },
  AvgDialog_13736_Content_32 = {
    Text = "Look, do you see that? Even my guard dog is more sensible than him! He's worse than an animal, hahaha!"
  },
  AvgDialog_13736_Content_33 = {
    Text = [[
Hey... old man, your strength is weaker today.
What, can't even hold the whip steady?]]
  },
  AvgDialog_13736_Content_34 = {Text = "Hmph..."},
  AvgDialog_13736_Content_35 = {
    Text = "Beasts are beasts because they can't keep their mouths shut or recognize their place."
  },
  AvgDialog_13736_Content_36 = {
    Text = "No worries, I'll <BigItalic:teach you well>—"
  },
  AvgDialog_13736_Content_37 = {
    Text = "Prinn's beard bristled with anger, and then he shot towards Uvhash like a bouncing ball."
  },
  AvgDialog_13736_Content_38 = {Text = "Wait."},
  AvgDialog_13736_Content_39 = {
    Text = "You grabbed Prin's wrist and pulled him back."
  },
  AvgDialog_13736_Content_4 = {Text = "..."},
  AvgDialog_13736_Content_40 = {
    Text = "Give me the whip."
  },
  AvgDialog_13736_Content_41 = {
    Text = "Let me go! Let me teach that beast a lesson..."
  },
  AvgDialog_13736_Content_42 = {
    Text = "Mr. Jamila, I am now your employer. There's no need to explain what an employer is, right?"
  },
  AvgDialog_13736_Content_43 = {
    Text = [[
Sorry, I only know that I'm the guide for this journey.
Since I'm the guide, you'll have to listen to me.]]
  },
  AvgDialog_13736_Content_44 = {
    Text = "Otherwise, I'll leave now, and you can head to the <Blue:battlefield> by yourselves."
  },
  AvgDialog_13736_Content_45 = {
    Text = "<Shake:Hey, hey...! Let's talk this over calmly...>"
  },
  AvgDialog_13736_Content_46 = {
    Text = "One more thing."
  },
  AvgDialog_13736_Content_47 = {
    Text = "You frown as you look at Uvhash."
  },
  AvgDialog_13736_Content_48 = {
    Text = "You and he rarely crossed paths on campus, but you knew a little about his various exploits."
  },
  AvgDialog_13736_Content_49 = {
    Text = "He is definitely not the type to be controlled by others."
  },
  AvgDialog_13736_Content_5 = {
    Text = "You awaken from a deep slumber to find yourself in a vast, endless desert."
  },
  AvgDialog_13736_Content_50 = {
    Text = "What did you do to this guy? How could he possibly obey you?"
  },
  AvgDialog_13736_Content_51 = {
    Text = "What? Are you questioning my ability as the <Blue:Chief Wizard of Levante>?"
  },
  AvgDialog_13736_Content_52 = {
    Text = "This is an exclusive secret technique in our line of work, as well as my personal privacy as the employer. Please, Guide, mind your own business..."
  },
  AvgDialog_13736_Content_53 = {
    Text = [[
Not talking, huh?
Then I'll beat you until you talk.]]
  },
  AvgDialog_13736_Content_54 = {
    Text = "Hey, wait... <Big:Roar!>"
  },
  AvgDialog_13736_Content_56 = {
    Text = "<Shake:Hiss, that hurts... You're definitely no ordinary guide!>"
  },
  AvgDialog_13736_Content_57 = {
    Text = "Speak up, are you a spy sent by <Blue:Remouahe> to intercept me?"
  },
  AvgDialog_13736_Content_58 = {
    Text = "You do not respond to Pulin's question, as your attention has already been drawn elsewhere—"
  },
  AvgDialog_13736_Content_59 = {
    Text = "A slender chain shimmers faintly in the daylight, emitting an unusual glimmer."
  },
  AvgDialog_13736_Content_6 = {
    Text = "Awake? Unbelievable, the guide fainted from heatstroke after just a few steps. What a mess!"
  },
  AvgDialog_13736_Content_60 = {
    Text = "It stretches from Prin's wrist all the way to Uvhash's neck."
  },
  AvgDialog_13736_Content_61 = {
    Text = "<Gray:This technique looks familiar... I seem to recall hearing someone mention it before...>"
  },
  AvgDialog_13736_Content_62 = {
    Text = "Disobedient ones should just be put on a leash."
  },
  AvgDialog_13736_Content_63 = {
    Text = "That's illegal in Londinium, Miss Agrippa. I'm afraid we'll need to teach you some basic legal knowledge..."
  },
  AvgDialog_13736_Content_64 = {
    Text = "Hehe, I'm no fool."
  },
  AvgDialog_13736_Content_65 = {
    Text = "Do you know @1?"
  },
  AvgDialog_13736_Content_66 = {
    Text = "That's an ancient arcane art, allowing the caster to control others with an invisible chain..."
  },
  AvgDialog_13736_Content_67 = {
    Text = "As for the cost..."
  },
  AvgDialog_13736_Content_68 = {
    Text = "What was the cost? Oh no, I don't remember..."
  },
  AvgDialog_13736_Content_69 = {
    Text = "You are lost in memories when suddenly the mask wrapped around your face is ripped off."
  },
  AvgDialog_13736_Content_7 = {
    Text = "Good thing I'm only visiting this hellhole once in my lifetime, @1!"
  },
  AvgDialog_13736_Content_70 = {
    Text = "Three winding rivers... Are you <Blue:Mamlio's Slave Mercenary>?!"
  },
  AvgDialog_13736_Content_71 = {
    Text = "As Prinn finished speaking, Uvhash, who had seemed indifferent, suddenly turned to look at you."
  },
  AvgDialog_13736_Content_72 = {
    Text = "Interesting..."
  },
  AvgDialog_13736_Content_73 = {
    Text = "No, no, that's not right. Mamulu's men should be on the battlefield now..."
  },
  AvgDialog_13736_Content_74 = {
    Text = "I see, you're a deserter."
  },
  AvgDialog_13736_Content_75 = {
    Text = "You instinctively touched your face."
  },
  AvgDialog_13736_Content_76 = {
    Text = "<Gray:So there's a tattoo on my face...>"
  },
  AvgDialog_13736_Content_77 = {
    Text = "Sure, I'm a deserter. My hometown is <Blue:Remouahe>, but I don't want to go back..."
  },
  AvgDialog_13736_Content_78 = {
    Text = [[
Deserters need to eat too, so I now make a living as a guide.
Don't worry, my greatest strength is my meticulous approach to work.]]
  },
  AvgDialog_13736_Content_79 = {
    Text = "Ensuring to bring you to the battlefield—"
  },
  AvgDialog_13736_Content_8 = {
    Text = "Guide? This... where is this place..."
  },
  AvgDialog_13736_Content_80 = {Text = "*Splat.*"},
  AvgDialog_13736_Content_81 = {
    Text = "Having had enough of the farce before him, Uvhash stretches and leisurely walks up to you."
  },
  AvgDialog_13736_Content_82 = {
    Text = "He grabs your shoulder and gently turns your chin until your gaze meets the silent wizard before you."
  },
  AvgDialog_13736_Content_83 = {
    Text = "Considering we are, or once were, slaves, let me give you a hint—"
  },
  AvgDialog_13736_Content_84 = {
    Text = [[
If I were you, I'd shut up right now.
Do you know what kind of people that guy hates the most?]]
  },
  AvgDialog_13736_Content_85 = {
    Text = "...The feeling of being taught to be cautious by this guy is truly peculiar."
  },
  AvgDialog_13736_Content_86 = {
    Text = "...I would like to hear more."
  },
  AvgDialog_13736_Content_87 = {
    Text = "Third, the Mamuliu Mercenaries."
  },
  AvgDialog_13736_Content_88 = {
    Text = [[
Second, the Remouans.
As for the first one...]]
  },
  AvgDialog_13736_Content_89 = {
    Text = "Intense pain shoots through your shoulder—Uvhash laughs while slapping your shoulder hard."
  },
  AvgDialog_13736_Content_9 = {
    Text = "The scorching sun makes you dizzy as you look down at your hands."
  },
  AvgDialog_13736_Content_90 = {
    Text = "<Big:Of course, it's the Mamulu mercenaries from Remouahe!>"
  },
  AvgDialog_13736_Content_91 = {
    Text = "<Gray:...Good. No one else should be able to laugh out loud except him.>"
  },
  AvgDialog_13736_Content_92 = {
    Text = "<Gray:This guy's talent for offending people is truly unmatched.>"
  },
  AvgDialog_13736_Content_93 = {Text = "Heh..."},
  AvgDialog_13736_Content_94 = {
    Text = "When the Mamlu mercenaries slaughtered tens of thousands of my compatriots, my wife, comrades, and mentor... all perished."
  },
  AvgDialog_13736_Content_95 = {
    Text = "Alright, I've finished telling my tragic story. You can continue laughing now."
  },
  AvgDialog_13736_Content_96 = {
    Text = "Sorry, Mr. Prinn. Allow me to explain. Though I have a... well, not so honorable past."
  },
  AvgDialog_13736_Content_97 = {
    Text = "But that's all in the past and has nothing to do with me now."
  },
  AvgDialog_13736_Content_98 = {
    Text = "Purin waved at you."
  },
  AvgDialog_13736_Content_99 = {
    Text = "His round face, baked by the scorching sun, resembled a fully ripened apple—unfortunately, this apple wasn't in a very happy mood right now."
  },
  AvgDialog_13737_Content_1 = {
    Text = "Tragedy's curtain"
  },
  AvgDialog_13737_Content_10 = {
    Text = "<RedShake:Walk...>"
  },
  AvgDialog_13737_Content_11 = {
    Text = "Uvhash effortlessly crushed the blocker's brain, then slowly approached another soldier."
  },
  AvgDialog_13737_Content_12 = {
    Text = "<RedShake:Blood... I need more blood...>"
  },
  AvgDialog_13737_Content_13 = {
    Text = "He slowly raised his hand."
  },
  AvgDialog_13737_Content_15 = {Text = "..."},
  AvgDialog_13737_Content_16 = {
    Text = "It's you..."
  },
  AvgDialog_13737_Content_17 = {
    Text = "Yes, it's me."
  },
  AvgDialog_13737_Content_18 = {
    Text = "You stand between the two, turning to look at the soldier who is kneeling in fear behind you."
  },
  AvgDialog_13737_Content_19 = {
    Text = "Hurry up. Run as far as you can."
  },
  AvgDialog_13737_Content_2 = {
    Text = "Edge of the Kuxi Desert, Battlefield"
  },
  AvgDialog_13737_Content_20 = {
    Text = "<Big:Get lost!!>"
  },
  AvgDialog_13737_Content_21 = {
    Text = "<Shake:Alright, alright... I'm outta here...>"
  },
  AvgDialog_13737_Content_22 = {
    Text = "The soldiers scrambled away."
  },
  AvgDialog_13737_Content_23 = {
    Text = "Why stop me? I've just begun to savor the thrill of blood and battle..."
  },
  AvgDialog_13737_Content_24 = {
    Text = "You just want to fight, right? I'll play along."
  },
  AvgDialog_13737_Content_25 = {
    Text = "You? Hahaha, what are you—"
  },
  AvgDialog_13737_Content_27 = {
    Text = "You press the scimitar against Uvhash's neck, calmly gazing into his unfocused eyes."
  },
  AvgDialog_13737_Content_28 = {
    Text = "You'll never know until you try."
  },
  AvgDialog_13737_Content_3 = {
    Text = "Hey, have you heard? Another one has gone mad, killing everyone in sight."
  },
  AvgDialog_13737_Content_4 = {
    Text = "They say he is neither Leorian nor Remouahean... no one knows where he came from."
  },
  AvgDialog_13737_Content_5 = {
    Text = "In short, leave quickly—"
  },
  AvgDialog_13737_Content_6 = {Text = "..."},
  AvgDialog_13737_Content_7 = {
    Text = "<Shake:When did you... show up...?>"
  },
  AvgDialog_13737_Content_8 = {
    Text = "Ahhh! Hurry—"
  },
  AvgDialog_13737_Content_9 = {Text = "—!!"},
  AvgDialog_13738_Content_1 = {
    Text = "Great, the sandstorm has moved to the other side. Next, we..."
  },
  AvgDialog_13738_Content_10 = {Text = "..."},
  AvgDialog_13738_Content_11 = {
    Text = "Don't you want to go to the battlefield? Then, of course, you should head towards the <Red:direction of blood>."
  },
  AvgDialog_13738_Content_12 = {
    Text = "The direction of blood...?"
  },
  AvgDialog_13738_Content_13 = {
    Text = "You point at Uvhash's retreating back."
  },
  AvgDialog_13738_Content_14 = {
    Text = "His direction."
  },
  AvgDialog_13738_Content_2 = {Text = "Ugh—!!"},
  AvgDialog_13738_Content_3 = {
    Text = "Pulin leaned against the bare tree trunk and began to vomit violently."
  },
  AvgDialog_13738_Content_4 = {
    Text = "I swear, once this deal is done. I swear..."
  },
  AvgDialog_13738_Content_5 = {
    Text = "This time, the wizard's curse of weakness received no response."
  },
  AvgDialog_13738_Content_6 = {
    Text = "Uvhash's pupils suddenly contracted slightly, as if having discovered something."
  },
  AvgDialog_13738_Content_7 = {
    Text = "<Red:...blood.>"
  },
  AvgDialog_13738_Content_8 = {
    Text = "After saying that, he left without looking back."
  },
  AvgDialog_13738_Content_9 = {
    Text = "Wait...! You can't go anywhere without my permission!"
  },
  AvgDialog_13739_Content_1 = {
    Text = "The vulture cries loudly in the blood-red twilight; the battlefield is already deserted."
  },
  AvgDialog_13739_Content_10 = {
    Text = "During the fight, you clearly feel Uvhash's state deteriorating at an alarming rate."
  },
  AvgDialog_13739_Content_11 = {
    Text = "Whatever it is, be it a Contract side effect, he's at his limit now."
  },
  AvgDialog_13739_Content_12 = {
    Text = "Battle is only interesting when it's evenly matched, so I don't mind becoming weaker to some extent."
  },
  AvgDialog_13739_Content_13 = {
    Text = "I never concern myself with human thoughts, just as humans don't concern themselves with ants."
  },
  AvgDialog_13739_Content_14 = {
    Text = "But you're different. You possess a powerful inner strength, and you understand restraint."
  },
  AvgDialog_13739_Content_15 = {
    Text = "Keep it up, warrior. Your mundane wishes—like the sun, little cakes, and such—might just come true."
  },
  AvgDialog_13739_Content_16 = {
    Text = "<Gray:It was just some random nonsense I blurted out, and he actually remembered...>"
  },
  AvgDialog_13739_Content_17 = {
    Text = "Let's go... to the place you mentioned, where the sun shines."
  },
  AvgDialog_13739_Content_18 = {Text = "?!"},
  AvgDialog_13739_Content_19 = {
    Text = "How about you?"
  },
  AvgDialog_13739_Content_2 = {
    Text = "You and Uvhash stood silently less than ten yards apart, looking at each other."
  },
  AvgDialog_13739_Content_20 = {
    Text = "Me...? That old man held back. I won't last long. Heh..."
  },
  AvgDialog_13739_Content_21 = {
    Text = "Both the old man and I must die... This is the true cost of breaking the contract."
  },
  AvgDialog_13739_Content_22 = {
    Text = "He trudges slowly toward you."
  },
  AvgDialog_13739_Content_23 = {
    Text = "He then bit into his own wrist."
  },
  AvgDialog_13739_Content_24 = {
    Text = "The pungent, scarlet blood pours down in torrents, dripping onto your head, eyelids, and flowing along the bridge of your nose to your parched lips."
  },
  AvgDialog_13739_Content_25 = {
    Text = "This blood... consider it my farewell gift."
  },
  AvgDialog_13739_Content_26 = {
    Text = "Vultures circled above him, clearly eyeing their dying prey."
  },
  AvgDialog_13739_Content_27 = {
    Text = "I was born from countless Caro, wandering this world for nearly a thousand years..."
  },
  AvgDialog_13739_Content_28 = {
    Text = "I have seen gold foil fluttering in victory parades, and golden palaces burning fiercely in flames."
  },
  AvgDialog_13739_Content_29 = {
    Text = "I've tasted the most delicious blood and experienced the most brutal battles."
  },
  AvgDialog_13739_Content_3 = {
    Text = "Hey... how long have we been fighting?"
  },
  AvgDialog_13739_Content_30 = {
    Text = "I slaughtered humans, was bound and used by them, and ultimately died at their hands, unsurprisingly."
  },
  AvgDialog_13739_Content_31 = {
    Text = "Now, it's time for me to leave..."
  },
  AvgDialog_13739_Content_32 = {
    Text = "He looks down at you, his eyes devoid of any emotion."
  },
  AvgDialog_13739_Content_33 = {
    Text = "Thick blood drips from the tip of your nose to the ground."
  },
  AvgDialog_13739_Content_34 = {
    Text = "You are like a bewildered novice, clueless about everything unfolding before you."
  },
  AvgDialog_13739_Content_35 = {
    Text = "I return all my Caro to you, and to this world."
  },
  AvgDialog_13739_Content_36 = {
    Text = "They belong to the sky, the earth... to you, but not to me."
  },
  AvgDialog_13739_Content_37 = {
    Text = "Now you can scram... Don't look back."
  },
  AvgDialog_13739_Content_38 = {
    Text = [[
The view is finally engulfed in a vast sea of blood mist. 
You close your eyes, feeling waves of dizziness as if the ground were sinking continuously.]]
  },
  AvgDialog_13739_Content_39 = {
    Text = "You can't quite remember the rest of the story."
  },
  AvgDialog_13739_Content_4 = {Text = "..."},
  AvgDialog_13739_Content_40 = {
    Text = "Perhaps you left long ago, or perhaps you died with him in this desert."
  },
  AvgDialog_13739_Content_41 = {
    Text = "These don't matter. Because you will forever remember the moment before his death."
  },
  AvgDialog_13739_Content_42 = {
    Text = "At that moment, a flock of black vultures flew by, blocking the glow of the sunset behind him."
  },
  AvgDialog_13739_Content_43 = {
    Text = "The light continues to fade, shadows spread around, and he kneels within them, gazing at you."
  },
  AvgDialog_13739_Content_44 = {Text = "He said—"},
  AvgDialog_13739_Content_45 = {Text = "Scram."},
  AvgDialog_13739_Content_46 = {
    Text = "Go find that sun-drenched hellhole."
  },
  AvgDialog_13739_Content_5 = {
    Text = "Who knows... an hour, a day?"
  },
  AvgDialog_13739_Content_6 = {Text = "..."},
  AvgDialog_13739_Content_7 = {
    Text = "A thousand years... I haven't experienced such an exhilarating battle in nearly a millennium."
  },
  AvgDialog_13739_Content_8 = {
    Text = "You are a born warrior."
  },
  AvgDialog_13739_Content_9 = {
    Text = "Surprising, since when did you learn to give human compliments?"
  },
  AvgDialog_13946_Content_1 = {
    Text = "Unmoored sea"
  },
  AvgDialog_13946_Content_10 = {
    Text = [[
They sent you to "escort" me to the witch?
That's laughable. Their intentions couldn't be more obvious...]]
  },
  AvgDialog_13946_Content_11 = {
    Text = "Goliath lets out a painful gasp. Beneath him, a pool of dark red blood slowly spreads, flowing all the way to your feet."
  },
  AvgDialog_13946_Content_12 = {
    Text = "<Red:They want us to die together at sea.>"
  },
  AvgDialog_13946_Content_13 = {
    Text = "Master, you are gravely injured! What has happened...?"
  },
  AvgDialog_13946_Content_14 = {
    Text = "Chaotic memories flood into your mind."
  },
  AvgDialog_13946_Content_15 = {
    Text = "In the last crucial battle, Leader Goliath lost to the rival tribe due to underestimating them."
  },
  AvgDialog_13946_Content_16 = {
    Text = "Perishites do not accept failure. The heavily injured Goliath was exiled, accompanied only by a broken little boat and you—"
  },
  AvgDialog_13946_Content_17 = {
    Text = "The weakest Perishite could even lose in a wrestling match to a ten-year-old."
  },
  AvgDialog_13946_Content_18 = {
    Text = "I remember the boss <Blue:Glen> mentioning a mysterious witch in the nearby waters who uses some kind of black slime..."
  },
  AvgDialog_13946_Content_19 = {
    Text = "Just apply it to the wound, and the injury will surely heal!"
  },
  AvgDialog_13946_Content_2 = {
    Text = [[
Lament for the Apostle of the Sea.
Lament for our light, our hope.

We wail, weep, and shed tears over our fate of being exiled to the ocean.]]
  },
  AvgDialog_13946_Content_20 = {
    Text = "You reflexively brought up the legend of the witch, only to realize something felt off afterward."
  },
  AvgDialog_13946_Content_21 = {
    Text = "<Gray:Wait, is this D-slime...?>"
  },
  AvgDialog_13946_Content_22 = {
    Text = "Boss, is it Glen?"
  },
  AvgDialog_13946_Content_23 = {
    Text = "A slow smile spread across Goliath's cold face."
  },
  AvgDialog_13946_Content_24 = {
    Text = "Looks like he has become your new leader. Very efficient, my dear clansmen."
  },
  AvgDialog_13946_Content_25 = {Text = "Splash!!"},
  AvgDialog_13946_Content_26 = {
    Text = "The decaying boat could no longer withstand the impact of the waves, cracking open a large hole, through which seawater poured in continuously."
  },
  AvgDialog_13946_Content_27 = {
    Text = "Tsk, just as I expected."
  },
  AvgDialog_13946_Content_28 = {
    Text = "Oh no, we're going to drown! We need to find something to plug the hole..."
  },
  AvgDialog_13946_Content_29 = {Text = "...Oh."},
  AvgDialog_13946_Content_3 = {
    Text = [[
Oh, please protect the afflicted!
Cast your merciful gaze upon us and grant us the black fountain of life.]]
  },
  AvgDialog_13946_Content_30 = {
    Text = "Goliath leaned disinterestedly against the deck, letting the blood beneath him stain the incoming seawater red."
  },
  AvgDialog_13946_Content_31 = {
    Text = "Relax. Even if we fix the ship, they still have ten thousand ways to kill me in this sea."
  },
  AvgDialog_13946_Content_32 = {
    Text = "My advice: Leave me alone. Get off the boat and swim back on your own."
  },
  AvgDialog_13946_Content_33 = {
    Text = "Tell them you've killed me. If you're lucky, you might just survive."
  },
  AvgDialog_13946_Content_34 = {
    Text = "What about you...?"
  },
  AvgDialog_13946_Content_35 = {Text = "Me?"},
  AvgDialog_13946_Content_36 = {
    Text = "Goliath leisurely takes in the sea view and gives you a slight smile."
  },
  AvgDialog_13946_Content_37 = {
    Text = "Sitting here admiring the sea, while waiting to die."
  },
  AvgDialog_13946_Content_38 = {Text = "...?"},
  AvgDialog_13946_Content_39 = {
    Text = "<Gray:So pessimistic, is this really the Goliath I know?>"
  },
  AvgDialog_13946_Content_4 = {
    Text = "<Red:Mercy, mercy, mercy...>"
  },
  AvgDialog_13946_Content_40 = {
    Text = "By the way, there's one more thing I need to remind you of."
  },
  AvgDialog_13946_Content_41 = {
    Text = "There's a hole at your rear. Based on my experience, this ship will break in two soon. You don't have much time left to think."
  },
  AvgDialog_13946_Content_42 = {Text = "Splash!!"},
  AvgDialog_13946_Content_43 = {
    Text = "As if to confirm Goliath's words, a massive wave struck, splitting the wooden boat in two instantly."
  },
  AvgDialog_13946_Content_44 = {
    Text = "<Shake:Aaaah—!!>"
  },
  AvgDialog_13946_Content_45 = {
    Text = "Salty seawater keeps flooding into your lungs. You open your mouth, but more water devours you whole."
  },
  AvgDialog_13946_Content_46 = {
    Text = "The body keeps sinking, and breathing becomes increasingly difficult..."
  },
  AvgDialog_13946_Content_47 = {
    Text = "In a daze, you seem to hear a sigh of helplessness."
  },
  AvgDialog_13946_Content_48 = {
    Text = "Before you can react, a powerful force grabs your hair and effortlessly lifts you out of the sea."
  },
  AvgDialog_13946_Content_49 = {
    Text = "Cough... Ugh!"
  },
  AvgDialog_13946_Content_5 = {Text = "..."},
  AvgDialog_13946_Content_50 = {
    Text = "Hold on tight, this is our only lifeline."
  },
  AvgDialog_13946_Content_51 = {
    Text = "You look around and realize that you and Goliath are squeezed together on a rickety wooden plank."
  },
  AvgDialog_13946_Content_52 = {
    Text = "Damn it... How can the Perishites, masters of the sea, not know how to swim?"
  },
  AvgDialog_13946_Content_53 = {
    Text = "Are you really a Perishite?"
  },
  AvgDialog_13946_Content_54 = {
    Text = "<SmallShake:Sorry, my body has been frail since childhood...>"
  },
  AvgDialog_13946_Content_55 = {
    Text = "Thank you, my lord. If it weren't for you, I would have died here..."
  },
  AvgDialog_13946_Content_56 = {
    Text = "...It seems you were not sent by them to kill me."
  },
  AvgDialog_13946_Content_57 = {
    Text = "Your survival instinct just now seemed genuine, not faked."
  },
  AvgDialog_13946_Content_58 = {
    Text = "Goliath wiped the damp hair from his forehead and gazed at the misty sea before him."
  },
  AvgDialog_13946_Content_59 = {
    Text = "When you fell into the sea, you clung to me like a giant crab, refusing to let go. Why?"
  },
  AvgDialog_13946_Content_6 = {
    Text = "Are you awake?"
  },
  AvgDialog_13946_Content_60 = {
    Text = "Huh? Of course, to survive..."
  },
  AvgDialog_13946_Content_61 = {
    Text = "Survive... but even alive, you're useless. You can't even swim."
  },
  AvgDialog_13946_Content_62 = {
    Text = "What are you living for?"
  },
  AvgDialog_13946_Content_63 = {
    Text = "Goliath's voice gradually weakened, as if he were asking you, or perhaps himself."
  },
  AvgDialog_13946_Content_64 = {
    Text = "Exiled by his tribe and gravely wounded, his path ahead, like the sea shrouded in dense fog before him, is filled with endless uncertainty."
  },
  AvgDialog_13946_Content_65 = {Text = "..."},
  AvgDialog_13946_Content_66 = {
    Text = "When you said you were ready to die, but when the waves came, not only did you find this plank and climb up, you also saved me."
  },
  AvgDialog_13946_Content_67 = {
    Text = "...That's because you keep pestering me."
  },
  AvgDialog_13946_Content_68 = {
    Text = "None of that matters. What matters is that, thanks to you, Master, we are both alive."
  },
  AvgDialog_13946_Content_69 = {
    Text = "Why do you think that is?"
  },
  AvgDialog_13946_Content_7 = {
    Text = "The sea churns up waves baked by the sun, carrying a salty breeze with a strong fishy smell to your nose."
  },
  AvgDialog_13946_Content_70 = {
    Text = "Goliath shook his head."
  },
  AvgDialog_13946_Content_71 = {
    Text = "To be honest, I don't know either. But I did realize one thing..."
  },
  AvgDialog_13946_Content_72 = {
    Text = "Goliath lowers his head, gazing at you thoughtfully."
  },
  AvgDialog_13946_Content_73 = {
    Text = "I can see why you're such a failure and yet still alive today."
  },
  AvgDialog_13946_Content_8 = {
    Text = "<Gray:Is this... a dream?>"
  },
  AvgDialog_13946_Content_9 = {
    Text = "As expected of the clan's notoriously frail member, a single large wave can leave you unconscious for half a day."
  },
  AvgDialog_13947_Content_1 = {
    Text = "Giants' Chronicles"
  },
  AvgDialog_13947_Content_10 = {
    Text = "Only fools would entrust their lives to others."
  },
  AvgDialog_13947_Content_11 = {
    Text = "<Gray:Witch...>"
  },
  AvgDialog_13947_Content_12 = {
    Text = "According to Goliath's Awakener file, this so-called \"witch\" is undoubtedly Miryam."
  },
  AvgDialog_13947_Content_13 = {
    Text = "Though the subsequent development was not as expected, Miryam did save Goliath's life."
  },
  AvgDialog_13947_Content_14 = {
    Text = "You are gravely injured, sir. I'm afraid there's no other way. Let us find the witch together—"
  },
  AvgDialog_13947_Content_15 = {Text = "Bang!!"},
  AvgDialog_13947_Content_16 = {
    Text = "With tremendous force, your fragile throat is tightly gripped, lifting you off the ground to come face-to-face with the giant."
  },
  AvgDialog_13947_Content_17 = {
    Text = "I'll say this only once: Don't look at me with that kind of gaze, and don't speak to me in that tone."
  },
  AvgDialog_13947_Content_18 = {
    Text = "The last thing I, Goliath, need is the pity of the weak."
  },
  AvgDialog_13947_Content_19 = {
    Text = "Goliath spoke calmly, his expression unchanged, as if discussing the weather with you."
  },
  AvgDialog_13947_Content_2 = {
    Text = "The sun scorched the sea, as if to wear away all life in endless heat."
  },
  AvgDialog_13947_Content_20 = {
    Text = "But you are so close that you can clearly see his eyes, red with pain and frustration."
  },
  AvgDialog_13947_Content_21 = {
    Text = "At this moment, he seemed to shed his glory as the sea overlord, becoming just another lost fish in the endless ocean, like you."
  },
  AvgDialog_13947_Content_22 = {
    Text = "Sorry... uh, my lord..."
  },
  AvgDialog_13947_Content_23 = {
    Text = "<Shake:Woo—>"
  },
  AvgDialog_13947_Content_24 = {
    Text = "The deep sound of a horn drifts in from afar."
  },
  AvgDialog_13947_Content_25 = {
    Text = "The weight on the neck suddenly lifted. Goliath released his grip and looked towards the direction from which the horn's sound came."
  },
  AvgDialog_13947_Content_26 = {
    Text = "<Gray:Cough... Phew, I'm saved...>"
  },
  AvgDialog_13947_Content_27 = {
    Text = "Interesting... Are you worried that I won't die quickly enough, so you've all come together to see me off?"
  },
  AvgDialog_13947_Content_28 = {
    Text = "Before long, the massive fleet surrounded you, leaving the swaying wooden planks as the only island in this vast sea."
  },
  AvgDialog_13947_Content_29 = {
    Text = "You are already surrounded."
  },
  AvgDialog_13947_Content_3 = {
    Text = "You and Goliath cling to the plank, the only island in the vast sea. Under the scorching sun, you feel dizzy again."
  },
  AvgDialog_13947_Content_30 = {
    Text = "Allow me to introduce to everyone the most valiant leader in Philistine history! The unyielding giant of immense power! The awe-inspiring, peerless tribal hero—"
  },
  AvgDialog_13947_Content_31 = {
    Text = "<BigShake:Lord Goliath!>"
  },
  AvgDialog_13947_Content_32 = {
    Text = "The sunlight reflecting off the sea is too intense; you can only catch a glimpse of a black figure standing at the bow, looking down at you."
  },
  AvgDialog_13947_Content_33 = {
    Text = "The newly arrived brothers may not know, but this lord was gravely injured in a duel and nearly captured, pushing our entire clan to the brink of an unprecedented crisis!"
  },
  AvgDialog_13947_Content_34 = {
    Text = "The impending doom devoured most of our people! Praise you, my dearest Lord Goliath!"
  },
  AvgDialog_13947_Content_35 = {
    Text = "Hehe... How could I dare to claim all the credit for such a great achievement, Glen?"
  },
  AvgDialog_13947_Content_36 = {
    Text = "Who was hiding behind me, too afraid to fight, and who was the first to drop their weapon and run home crying?"
  },
  AvgDialog_13947_Content_37 = {Text = "You...!"},
  AvgDialog_13947_Content_38 = {
    Text = "Glen's face flushed red, his cloudy eyes trembling before finally locking onto you."
  },
  AvgDialog_13947_Content_39 = {
    Text = "Oh, even if the tribe disperses, the leader still has a... very adorable follower."
  },
  AvgDialog_13947_Content_4 = {
    Text = "<Shake:Sorry, I'm not feeling well... I'll rest for a bit...>"
  },
  AvgDialog_13947_Content_40 = {
    Text = "Perishite's shame — a waste who can't even withstand a single punch within the tribe, yet seeks to follow you in becoming a warrior..."
  },
  AvgDialog_13947_Content_41 = {
    Text = "Hahaha...!!"
  },
  AvgDialog_13947_Content_42 = {
    Text = "Goliath looks up, surprised to see you through the crowd's laughter."
  },
  AvgDialog_13947_Content_43 = {
    Text = "Hey, little one, did you come to follow me of your own accord?"
  },
  AvgDialog_13947_Content_44 = {
    Text = "<Gray:Uh... That's how I remember it...>"
  },
  AvgDialog_13947_Content_45 = {
    Text = "Isn't it touching? I just casually mentioned the witch, and this little fool took it seriously, eagerly wanting to follow you here..."
  },
  AvgDialog_13947_Content_46 = {
    Text = "Can't be stopped, haha—"
  },
  AvgDialog_13947_Content_47 = {Text = "Splash!!"},
  AvgDialog_13947_Content_48 = {
    Text = "The laughter abruptly stopped. A fierce wind howled, and a severed leg rolled before everyone."
  },
  AvgDialog_13947_Content_49 = {
    Text = "Aaaah... my leg, my leg!!"
  },
  AvgDialog_13947_Content_5 = {
    Text = "A shirt stained with sweat and blood is thrown over your head, causing you to jump up immediately due to the stench."
  },
  AvgDialog_13947_Content_50 = {
    Text = "The once-dominant sea lord stands like a mountain before Glen, exuding an aura that chills the heart."
  },
  AvgDialog_13947_Content_51 = {
    Text = "That fly has been buzzing around my ear for a while now..."
  },
  AvgDialog_13947_Content_52 = {
    Text = "Goliath leisurely wiped the blood off his blade, then looked up and gave Glen a cold smile."
  },
  AvgDialog_13947_Content_53 = {
    Text = "Glenn, did I just ask you a question?"
  },
  AvgDialog_13947_Content_6 = {
    Text = "Cough... Ugh!"
  },
  AvgDialog_13947_Content_7 = {
    Text = "You're suffering from heatstroke. Place this on your head to shield yourself from the sun, and don't remove it."
  },
  AvgDialog_13947_Content_8 = {
    Text = [[
As expected from the clothes worn by Master, truly invigorating...
Where should we go next? To find the witch?]]
  },
  AvgDialog_13947_Content_9 = {
    Text = "What nonsense about witches? You can't actually believe their lies, can you?"
  },
  AvgDialog_13948_Content_1 = {
    Text = "Golden refrain"
  },
  AvgDialog_13948_Content_10 = {
    Text = "The pale calm of the sea is broken as a dark purplish-black sea serpent suddenly lunges, entwining everyone tightly."
  },
  AvgDialog_13948_Content_11 = {
    Text = "Hmm... Aaaahhh!!"
  },
  AvgDialog_13948_Content_12 = {
    Text = "With a faint hiss, the snake's body transforms into a pitch-black blade, piercing through the person completely."
  },
  AvgDialog_13948_Content_13 = {
    Text = "<Big:Out of my way>... Huh?"
  },
  AvgDialog_13948_Content_15 = {
    Text = "A soft, chilly sensation emanates from the neck where the black snake entwines, gradually healing the wound."
  },
  AvgDialog_13948_Content_16 = {
    Text = "My wounds... have all healed?"
  },
  AvgDialog_13948_Content_17 = {
    Text = "The black serpent leaves you without hesitation and quickly coils tightly around Glenn."
  },
  AvgDialog_13948_Content_18 = {
    Text = "Run, the witch is... coming..."
  },
  AvgDialog_13948_Content_19 = {
    Text = "The pitch-black snakes slithered out from Glen's eyes and mouth. He collapsed before he could utter a complete sentence."
  },
  AvgDialog_13948_Content_2 = {
    Text = [[
Lament for the Apostle of the Sea.
Lament for our light, our hope.

We wail, weep, and shed tears over our fate of being exiled to the ocean.]]
  },
  AvgDialog_13948_Content_20 = {
    Text = "In no time, countless broken corpses were floating on the sea."
  },
  AvgDialog_13948_Content_21 = {
    Text = "This is a silent massacre."
  },
  AvgDialog_13948_Content_22 = {
    Text = "<Gray:Is it over? Impressive, as expected from Miryam.>"
  },
  AvgDialog_13948_Content_23 = {
    Text = "You helped us... Who are you?"
  },
  AvgDialog_13948_Content_24 = {
    Text = "The woman in black veil remains silent. She stands at the bow, with a dense fog separating you from her."
  },
  AvgDialog_13948_Content_25 = {
    Text = "Seems so near, yet so far away."
  },
  AvgDialog_13948_Content_26 = {
    Text = "The woman gazed at the stunned Goliath, a faint smile playing on her lips. She extended her finger toward the distance, as if issuing a silent invitation."
  },
  AvgDialog_13948_Content_27 = {
    Text = "She then turned the bow and departed leisurely."
  },
  AvgDialog_13948_Content_28 = {
    Text = "Wait, don't go...<Big:Don't leave!>"
  },
  AvgDialog_13948_Content_29 = {
    Text = "The mist dissipates, and a ray of sunlight pierces through the clouds, casting a golden hue on the waves."
  },
  AvgDialog_13948_Content_3 = {
    Text = "Vision suddenly dims; the glaring sunlight gradually vanishes, and a thick fog blankets the entire sea surface."
  },
  AvgDialog_13948_Content_30 = {
    Text = "You blinked, and the sea's end was already empty."
  },
  AvgDialog_13948_Content_31 = {
    Text = "The storm subsides, and you and Goliath cling to the only intact plank, gasping for breath."
  },
  AvgDialog_13948_Content_32 = {
    Text = "The once azure sea has long been stained red with blood, and you drift like floating duckweed."
  },
  AvgDialog_13948_Content_33 = {
    Text = "Still couldn't get the ship... Now I don't even know how to get home."
  },
  AvgDialog_13948_Content_34 = {
    Text = "Not going home."
  },
  AvgDialog_13948_Content_35 = {
    Text = "Goliath propped up one leg, staring blankly in the direction Miryam had departed."
  },
  AvgDialog_13948_Content_36 = {
    Text = "I've decided. I'm going to find that witch. Will you come with me?"
  },
  AvgDialog_13948_Content_37 = {
    Text = "Ahem, \"Only a fool would entrust their life to someone else.\""
  },
  AvgDialog_13948_Content_38 = {
    Text = "You deliberately lower your voice, mimicking Goliath's earlier tone and repeating what he said."
  },
  AvgDialog_13948_Content_39 = {
    Text = "Hmph, that's because the stakes aren't high enough. I've never seen a power that can crush everything in an instant."
  },
  AvgDialog_13948_Content_4 = {
    Text = [[
Oh, please protect those plagued by misfortune.
Cast your compassionate gaze upon us...]]
  },
  AvgDialog_13948_Content_40 = {
    Text = "Moreover, she just helped us and even extended an invitation to me..."
  },
  AvgDialog_13948_Content_41 = {
    Text = "But what if... it's a trap?"
  },
  AvgDialog_13948_Content_42 = {Text = "Trap..."},
  AvgDialog_13948_Content_43 = {
    Text = "Do you remember the question you asked me before?"
  },
  AvgDialog_13948_Content_44 = {
    Text = "...The important thing is, thanks to you, my lord, both of us are alive now."
  },
  AvgDialog_13948_Content_45 = {
    Text = "Why do you think that is?"
  },
  AvgDialog_13948_Content_46 = {
    Text = "Now I know the answer."
  },
  AvgDialog_13948_Content_47 = {
    Text = "What is the answer?"
  },
  AvgDialog_13948_Content_48 = {
    Text = "A flock of seabirds suddenly flew together. Their white wings flapped like clouds in flight, freely drifting in the sea breeze."
  },
  AvgDialog_13948_Content_49 = {
    Text = "Goliath was not bothered by the flock of birds. He stared ahead, his eyes shining with excitement."
  },
  AvgDialog_13948_Content_5 = {
    Text = "Ancient, eerie songs drift. A woman's silhouette appears and disappears at the bow, like a ghost roaming in the mist."
  },
  AvgDialog_13948_Content_50 = {
    Text = "Because I am Goliath."
  },
  AvgDialog_13948_Content_51 = {
    Text = "Goliath, the longest-reigning leader in Philistine history, an indomitable giant, and a legendary tribal hero."
  },
  AvgDialog_13948_Content_52 = {
    Text = "Even if only one follower remains, as long as there's a glimmer of hope, I can rise again."
  },
  AvgDialog_13948_Content_53 = {
    Text = "That witch is my last chance. Only she can grant me absolute Power."
  },
  AvgDialog_13948_Content_54 = {
    Text = "Even if it's a trap, I'll go."
  },
  AvgDialog_13948_Content_55 = {
    Text = "Why save me, then? A \"good-for-nothing\" like me probably can't be of any help to you..."
  },
  AvgDialog_13948_Content_56 = {
    Text = "You deliberately emphasized the pronunciation of a word, causing Goliath to burst into laughter."
  },
  AvgDialog_13948_Content_57 = {
    Text = "The sunlight breaks through the clouds, casting a golden glow. Strands of hair gently dance under the azure sky."
  },
  AvgDialog_13948_Content_58 = {
    Text = "There's no way a commander without troops can succeed in this world."
  },
  AvgDialog_13948_Content_59 = {
    Text = [[
Little one, you're not useless.
You are the sole follower of the giant Goliath, and no one can replace you.]]
  },
  AvgDialog_13948_Content_6 = {
    Text = "Huh, is someone singing?"
  },
  AvgDialog_13948_Content_60 = {
    Text = "When I achieve my dominance, at the very least, I'll appoint you as a tribal chief!"
  },
  AvgDialog_13948_Content_61 = {
    Text = "...Not necessary."
  },
  AvgDialog_13948_Content_62 = {
    Text = "The sky gradually darkened. The glow of dusk resembled shimmering golden rivers flowing across the horizon."
  },
  AvgDialog_13948_Content_63 = {
    Text = "Hey, you know what? Heroes can only be heroes because of people like us."
  },
  AvgDialog_13948_Content_64 = {
    Text = "<Small:So I'm important too, got it...>"
  },
  AvgDialog_13948_Content_65 = {
    Text = "<Small:Hmm...>"
  },
  AvgDialog_13948_Content_66 = {
    Text = "Fragmented words scatter like dandelions in the sea breeze, carried far, far away."
  },
  AvgDialog_13948_Content_67 = {
    Text = "You and Goliath sat on a thin wooden plank, looking like tiny leaves drifting in a golden sea."
  },
  AvgDialog_13948_Content_68 = {
    Text = "Nobody knows where you will ultimately sail to."
  },
  AvgDialog_13948_Content_7 = {
    Text = "<Shake:The witch, it's the witch!>"
  },
  AvgDialog_13948_Content_8 = {
    Text = "How could this be... Could the legend actually be true..."
  },
  AvgDialog_13948_Content_9 = {
    Text = [[
<Red:Mercy.
         Mercy.
                  Mercy...>]]
  },
  AvgDialog_14530_Content_10 = {
    Text = [[
Lips parted, a faint salty taste spread.
This isn't rain.]]
  },
  AvgDialog_14530_Content_11 = {
    Text = "<Gray:...Tears?>"
  },
  AvgDialog_14530_Content_12 = {
    Text = "As if washed clean by the rain, the view gradually becomes clearer."
  },
  AvgDialog_14530_Content_14 = {
    Text = "Ra... Mona..."
  },
  AvgDialog_14530_Content_15 = {
    Text = "Your call suddenly comes to an abrupt end."
  },
  AvgDialog_14530_Content_16 = {
    Text = "Overwhelming stress comes from all directions, and black tides engulf you."
  },
  AvgDialog_14530_Content_17 = {Text = "..."},
  AvgDialog_14530_Content_18 = {
    Text = "The clock ticks, and the sound of birdsong filters through the half-open window."
  },
  AvgDialog_14530_Content_19 = {
    Text = "The lingering suffocation makes you instinctively pat your chest. Slowly sitting up, it takes a while before you truly feel awake."
  },
  AvgDialog_14530_Content_2 = {
    Text = "Tears of Rain"
  },
  AvgDialog_14530_Content_20 = {
    Text = "<Gray:I've had so many strange dreams, but this is the first time I've dreamed of my own death.>"
  },
  AvgDialog_14530_Content_21 = {
    Text = "Feels strange."
  },
  AvgDialog_14530_Content_22 = {
    Text = "Quite interesting."
  },
  AvgDialog_14530_Content_23 = {
    Text = "Ring Ring—"
  },
  AvgDialog_14530_Content_24 = {
    Text = "You turn off the alarm clock, stand up, and stretch."
  },
  AvgDialog_14530_Content_25 = {
    Text = "Fine, whatever. I remember I need to go today—"
  },
  AvgDialog_14530_Content_26 = {
    Text = "Special training tomorrow at 8 AM in the Awakening Room. Don't be late"
  },
  AvgDialog_14530_Content_27 = {
    Text = "Awakening Room? Is it for awakening-related training?"
  },
  AvgDialog_14530_Content_28 = {
    Text = "Testing the stability of <Yellow:Artificial Domain>."
  },
  AvgDialog_14530_Content_29 = {
    Text = "What is that?"
  },
  AvgDialog_14530_Content_3 = {Text = "Falling."},
  AvgDialog_14530_Content_30 = {
    Text = "A small project I've been working on, more like a hobby—using the Awakening device's amplification to enhance consciousness and spirit during sleep"
  },
  AvgDialog_14530_Content_31 = {
    Text = "In theory, a sufficiently large spirit can form a domain, and a stabilized domain can exist independently of both the reality dimension and the spirit dimension."
  },
  AvgDialog_14530_Content_32 = {
    Text = "This realm is quite similar to the <Yellow:Domain>, so I call it an Artificial Domain."
  },
  AvgDialog_14530_Content_33 = {
    Text = "Unlike the naturally occurring domains that intrude into reality from the spirit dimension, artificial domains are non-aggressive, more stable and controllable, and can <Yellow:recreate a moment from a time that does not exist in the present>."
  },
  AvgDialog_14530_Content_34 = {
    Text = "\"The present doesn't exist\"—Are you saying it can show someone's memories?"
  },
  AvgDialog_14530_Content_35 = {
    Text = "It can <Yellow:present a memory based on the Spirit Master's understanding>, and it also allows others to enter this memory."
  },
  AvgDialog_14530_Content_36 = {
    Text = "Like entering the Domain...?"
  },
  AvgDialog_14530_Content_37 = {
    Text = "Not bad. Yes, after an artificial Domain forms, other individuals can physically enter it and interact with the consciousness of the spirit entity—the owner of the Domain."
  },
  AvgDialog_14530_Content_38 = {
    Text = "At this moment, whether the spirit recognizes the visitor and what attitude it holds... Ha, just thinking about it is interesting."
  },
  AvgDialog_14530_Content_39 = {
    Text = "If the Artificial Domain works, it will be the best way for Investigators, Keepers, and their respective Awakeners to build rapport and deepen understanding."
  },
  AvgDialog_14530_Content_4 = {
    Text = "You are falling."
  },
  AvgDialog_14530_Content_40 = {
    Text = "Thinking of Doll's eager eyes, you felt a chill run down your scalp."
  },
  AvgDialog_14530_Content_41 = {
    Text = [[
They call it special training, but we're just guinea pigs...
I hope nothing goes wrong today.]]
  },
  AvgDialog_14530_Content_42 = {
    Text = "You gather your spirit and push open the door in the underground passage."
  },
  AvgDialog_14530_Content_43 = {
    Text = "Before you can react, a blinding light swallows you whole."
  },
  AvgDialog_14530_Content_5 = {
    Text = "The sensation of falling pulls you, slowly drawing your consciousness out of the pitch-black dream."
  },
  AvgDialog_14530_Content_6 = {
    Text = "A blurry light appears before your eyes. After a moment of confusion, you realize that you seem to have opened your eyes."
  },
  AvgDialog_14530_Content_7 = {
    Text = "<Gray:How... can't see clearly...>"
  },
  AvgDialog_14530_Content_8 = {
    Text = "One drop, two drops... A cool liquid falls on your forehead, rolling down your cheek."
  },
  AvgDialog_14530_Content_9 = {Text = "Rain...?"},
  AvgDialog_15363_Content_1 = {
    Text = "Death of Ms. Coral"
  },
  AvgDialog_15363_Content_10 = {
    Text = "The crowd gathered tightly around it, countless camera flashes going off, overlapping noisy discussions filling the air, until a staff member suddenly lifted the cover."
  },
  AvgDialog_15363_Content_11 = {
    Text = "This is... Oh my God."
  },
  AvgDialog_15363_Content_12 = {
    Text = "...Unbelievable."
  },
  AvgDialog_15363_Content_13 = {
    Text = "It's as if a switch had been flipped; the crowd automatically fell silent, making the once bustling hall feel somewhat empty."
  },
  AvgDialog_15363_Content_14 = {
    Text = "You struggle to push through the crowd and finally catch sight of the artwork surrounded in the center."
  },
  AvgDialog_15363_Content_15 = {Text = "..."},
  AvgDialog_15363_Content_16 = {
    Text = "It's Sanga. She lost all her color and emotion, turning into a pure white coral sculpture."
  },
  AvgDialog_15363_Content_17 = {
    Text = "Bright daylight refracted through the pristine dome glass, enveloping her in a soft golden glow."
  },
  AvgDialog_15363_Content_18 = {
    Text = "You look down at the brass plaque on the base of the sculpture, engraved with its name in elegant script: <Red:\"Nameless Daughter of Coral\">."
  },
  AvgDialog_15363_Content_19 = {
    Text = "Nameless Coral..."
  },
  AvgDialog_15363_Content_2 = {
    Text = "Dear Mr. Claudel:\n\nMany things have happened recently; please forgive my delayed response.\n\nSince Miss Sanga left, Mr. Auguste has not been able to create any remarkable works.\nUnder the pressure of public opinion, he announced an indefinite suspension of his sculpting career.\nHe has received the punishment he deserved, yet I cannot feel joy—<Yellow:Miss Sanga is still missing.>"
  },
  AvgDialog_15363_Content_20 = {
    Text = "You gaze at the text in a trance, your consciousness swaying and twisting along with the elegant strokes..."
  },
  AvgDialog_15363_Content_21 = {
    Text = "He raised his hand to rub his eyes, only to find layers of rough, dull white spreading between his fingers."
  },
  AvgDialog_15363_Content_22 = {Text = "?!"},
  AvgDialog_15363_Content_23 = {
    Text = "White coral mist spread from your fingertips, gradually covering your entire body, quickly filling the entire hall, and then—"
  },
  AvgDialog_15363_Content_24 = {Text = "—!!"},
  AvgDialog_15363_Content_25 = {
    Text = "You and the exhibition hall shatter into countless white Fragments, falling into the endless depths of the ocean."
  },
  AvgDialog_15363_Content_26 = {
    Text = "Among countless white sculptures and corals, bathed in the tranquil morning light, the ruins of a white palace stand prominently."
  },
  AvgDialog_15363_Content_27 = {
    Text = "Colorful fish swim through the crooked arches and corridors of the ruins, enjoying their leisurely moments."
  },
  AvgDialog_15363_Content_28 = {
    Text = "The entire ruin seems to have been abandoned in the shadows of time, far from the erosion of the world and the disturbance of the crowd."
  },
  AvgDialog_15363_Content_29 = {
    Text = "When you've witnessed those miracles... you'll understand me."
  },
  AvgDialog_15363_Content_3 = {
    Text = "<Yellow:Tomorrow, I will head to the Cité Salon to find the \"answer\" that Miss Sanga mentioned.>\nWish me luck.\n\nCamille@1\nA.F.2@1 Sep"
  },
  AvgDialog_15363_Content_30 = {
    Text = "Is this... the miracle you saw, Ms. Sanga?"
  },
  AvgDialog_15363_Content_31 = {
    Text = "You drift in the warm sea, fascinated yet bewildered by everything before you."
  },
  AvgDialog_15363_Content_32 = {
    Text = "Move aside, let me through!!"
  },
  AvgDialog_15363_Content_33 = {
    Text = "<Big:Let me through!!>"
  },
  AvgDialog_15363_Content_34 = {
    Text = "The clamorous commotion pulls you back to reality."
  },
  AvgDialog_15363_Content_35 = {
    Text = "A ragged old man breaks through the security barriers and lunges at you, gripping your hand tightly."
  },
  AvgDialog_15363_Content_36 = {
    Text = "You saw it, right? Aequor, the palace, those chaotic Illusions..."
  },
  AvgDialog_15363_Content_37 = {Text = "?!"},
  AvgDialog_15363_Content_38 = {
    Text = "This wicked woman is a thief..."
  },
  AvgDialog_15363_Content_39 = {
    Text = "The old man muttered to himself. You gazed at the face concealed beneath the wide brim and thick beard, suddenly noticing something unusual."
  },
  AvgDialog_15363_Content_4 = {
    Text = "Cité Salon Exhibition\nOpening Day"
  },
  AvgDialog_15363_Content_40 = {
    Text = "...Mr. August?!"
  },
  AvgDialog_15363_Content_41 = {
    Text = "Jeez, it really is him... My God! What has happened to him?"
  },
  AvgDialog_15363_Content_42 = {
    Text = "He went bankrupt long ago, didn't you know? After the <Italic:Tragic Muse> fiasco, he invested a fortune in several pieces, but none of them sold..."
  },
  AvgDialog_15363_Content_43 = {
    Text = "The government is now wary of his reputation and no longer places orders with him. Perhaps the stress has driven him mad..."
  },
  AvgDialog_15363_Content_44 = {
    Text = "People were both shocked and frightened, staring at August from a cautious distance."
  },
  AvgDialog_15363_Content_45 = {
    Text = "August jerks his hand away from you and limps toward the sculpture, his eyes brimming with uncontrollable hatred."
  },
  AvgDialog_15363_Content_46 = {
    Text = "Hmph... Do you think death can make up for everything you've done?"
  },
  AvgDialog_15363_Content_47 = {
    Text = "You fooled everyone... You took away all my talent, inspiration, and fame."
  },
  AvgDialog_15363_Content_48 = {
    Text = "I'm ruined, completely ruined. And you? Sitting here leisurely, enjoying everyone's admiration, waiting for them to crown you as a classic..."
  },
  AvgDialog_15363_Content_49 = {Text = "..."},
  AvgDialog_15363_Content_5 = {
    Text = "Have you heard? Mr. August is exhibiting his sculptures again."
  },
  AvgDialog_15363_Content_50 = {
    Text = "Faced with the hysterical curses of the former teacher, the sculpture stands silently, its indifferent expression unwavering."
  },
  AvgDialog_15363_Content_51 = {
    Text = "August could no longer tolerate it; he lunged at the sculpture with fury."
  },
  AvgDialog_15363_Content_52 = {
    Text = "The same expression, the same ridicule..."
  },
  AvgDialog_15363_Content_53 = {
    Text = "Devil... devil! <Big:I'll rip off your mask!>"
  },
  AvgDialog_15363_Content_6 = {
    Text = "Auguste, the sculptor? Didn't he vanish after being accused of plagiarism? I thought he'd never show his face again."
  },
  AvgDialog_15363_Content_7 = {
    Text = "I'm quite curious—without that female disciple, what could he possibly achieve now..."
  },
  AvgDialog_15363_Content_8 = {
    Text = "The opening ceremony of the salon exhibition was crowded with people."
  },
  AvgDialog_15363_Content_9 = {
    Text = "August's work is placed in the center of the exhibition hall, covered by heavy drapes, arousing endless curiosity."
  },
  AvgDialog_15364_Content_1 = {Text = "Hmm!!"},
  AvgDialog_15364_Content_10 = {
    Text = "Cité Salon Exhibit\nThe Night of the Opening Day"
  },
  AvgDialog_15364_Content_11 = {
    Text = "As the final lock clicked shut, the exhibition hall plunged into a deathly silence."
  },
  AvgDialog_15364_Content_12 = {
    Text = "You step out from the shadows in the corner and stand before her once again."
  },
  AvgDialog_15364_Content_13 = {
    Text = "Here, free from the clamor of the day, is the perfect time to talk."
  },
  AvgDialog_15364_Content_14 = {
    Text = [[
Ms. Sanga, Mr. Auguste was taken away today. He said...
You have deceived everyone.]]
  },
  AvgDialog_15364_Content_15 = {
    Text = "Does \"everyone\" here include me as well?"
  },
  AvgDialog_15364_Content_16 = {Text = "..."},
  AvgDialog_15364_Content_17 = {
    Text = "Did you promise to go home with me? Is that true?"
  },
  AvgDialog_15364_Content_18 = {Text = "..."},
  AvgDialog_15364_Content_19 = {
    Text = "The sculpture remains silent. Even though everyone's lives have been altered by her, she never lowers her gaze from the distance."
  },
  AvgDialog_15364_Content_2 = {
    Text = "Let me go! The person you're after is her, it's her—"
  },
  AvgDialog_15364_Content_20 = {
    Text = "Moonlight pierces through the gallery's glass window, enveloping her in a mist of white light."
  },
  AvgDialog_15364_Content_21 = {
    Text = "<Red:Follow my gaze...>"
  },
  AvgDialog_15364_Content_22 = {
    Text = "Follow the gaze... Could it be?!"
  },
  AvgDialog_15364_Content_23 = {
    Text = "You stand on tiptoe and notice that, under the moonlight, the originally indifferent and unfocused eyes of the sculpture have changed, now filled with a specific and intense emotion."
  },
  AvgDialog_15364_Content_24 = {
    Text = "She keeps gazing into the distance."
  },
  AvgDialog_15364_Content_25 = {
    Text = "You follow her gaze and turn around."
  },
  AvgDialog_15364_Content_26 = {
    Text = "The instant your gaze wandered, the exhibition hall beneath your feet miraculously disappeared."
  },
  AvgDialog_15364_Content_27 = {
    Text = "Instead, there is an endless sea and a vast, snow-white beach."
  },
  AvgDialog_15364_Content_28 = {
    Text = "Distant thunder rumbles, the tide surges violently, rushing towards you."
  },
  AvgDialog_15364_Content_29 = {
    Text = "This is the sea that you and Sanga once visited."
  },
  AvgDialog_15364_Content_3 = {
    Text = "Mr. Auguste, we have received reports that your actions have seriously disrupted the order of the salon exhibition. Please come with us."
  },
  AvgDialog_15364_Content_4 = {Text = "No, no..."},
  AvgDialog_15364_Content_5 = {
    Text = "The scene is chaotic, and the surge of people from all directions has completely separated you from August. You can only watch as he is forcibly dragged away by the police."
  },
  AvgDialog_15364_Content_6 = {
    Text = "Don't rejoice too soon... One day, you'll end up just like me..."
  },
  AvgDialog_15364_Content_7 = {
    Text = "Heh... Hehehe..."
  },
  AvgDialog_15364_Content_8 = {
    Text = "The exhibition hall has finally returned to order."
  },
  AvgDialog_15364_Content_9 = {
    Text = "August's final trembling, neurotic laughter echoed faintly in the empty gallery, like diminishing ripples."
  },
  AvgDialog_15365_Content_1 = {Text = "Midsea"},
  AvgDialog_15365_Content_10 = {
    Text = [[
As expected, it's you.
Sorry, did I disturb you when I got up at night?]]
  },
  AvgDialog_15365_Content_11 = {
    Text = "Instead of waking me up, you should be more concerned about whether you'll disturb those <Blue:old fellows sleeping underground>."
  },
  AvgDialog_15365_Content_12 = {
    Text = "You tilted your chin and gestured toward the grave in front of her, which had been dug open to nearly a foot deep."
  },
  AvgDialog_15365_Content_13 = {
    Text = "Are you looking for something? Do you need help?"
  },
  AvgDialog_15365_Content_14 = {
    Text = "It's alright, I've already found it."
  },
  AvgDialog_15365_Content_15 = {
    Text = "Sanga smiled and showed you her hand, covered in a black, sticky liquid—"
  },
  AvgDialog_15365_Content_16 = {
    Text = "It's D-slime. You are extremely familiar with them."
  },
  AvgDialog_15365_Content_17 = {
    Text = "Did you see that? Under the moonlight, they emit a strange blue glow. During the day, they take on a different appearance..."
  },
  AvgDialog_15365_Content_18 = {
    Text = "This is the most perfect sculpture material I've ever seen."
  },
  AvgDialog_15365_Content_19 = {Text = "..."},
  AvgDialog_15365_Content_2 = {
    Text = [[
Dear Mr. Claudel,

Miss Sanga did not refuse to return home but requested some time.
She said, <Yellow:"I will return home after the salon exhibition.">

However, Miss Sanga's recent state is concerning.
She sneaks out late at night and returns at dawn.]]
  },
  AvgDialog_15365_Content_20 = {
    Text = "Do you sneak out every night just to collect D-Slime here?"
  },
  AvgDialog_15365_Content_21 = {
    Text = "Do you know their names? You are very familiar with them."
  },
  AvgDialog_15365_Content_22 = {
    Text = "This... is not something rare. There are quite a few in Besançon."
  },
  AvgDialog_15365_Content_23 = {
    Text = "I see... I thought it was my own unique and wonderful discovery."
  },
  AvgDialog_15365_Content_24 = {
    Text = "Dissolution... What a fitting name."
  },
  AvgDialog_15365_Content_25 = {
    Text = "Now is not the time for jokes, Sanga."
  },
  AvgDialog_15365_Content_26 = {
    Text = "You will die. This is not something that ordinary people like us should meddle with."
  },
  AvgDialog_15365_Content_27 = {
    Text = "I understand, I truly do... Beauty inevitably invites danger."
  },
  AvgDialog_15365_Content_28 = {
    Text = [[
You could say that danger itself is a kind of beauty, right?
To me, death isn't something to be afraid of.]]
  },
  AvgDialog_15365_Content_29 = {
    Text = "What is truly terrifying is..."
  },
  AvgDialog_15365_Content_3 = {
    Text = [[
Strangely, this continuous nocturnal lifestyle has made her more energetic,
and even Mr. August is satisfied with her recent work efficiency.

<Yellow:She feels so unfamiliar.>

On several nights, I woke up from nightmares to find her standing by my bed...
She stared at me with eyes full of something frightening, something I couldn't comprehend.]]
  },
  AvgDialog_15365_Content_30 = {
    Text = "A gentle breeze swept away Sanga's next words. The moon peeked through the overlapping clouds, casting its cold light on both of you."
  },
  AvgDialog_15365_Content_31 = {
    Text = "Then you noticed the scar on Sanga's neck."
  },
  AvgDialog_15365_Content_32 = {
    Text = "Like coral tendrils, they climb upward, shimmering with cold, gray-blue light in the gaps of shifting moonlight."
  },
  AvgDialog_15365_Content_33 = {
    Text = "Miss Sanga, have you already been infected...?!"
  },
  AvgDialog_15365_Content_34 = {
    Text = "Even though you know it's just a dream, your heart still feels a slight pang for a moment."
  },
  AvgDialog_15365_Content_35 = {
    Text = "After all, you now possess all the memories and emotions of the original owner. This maid from the countryside of Besançon harbors deep affection for her mistress."
  },
  AvgDialog_15365_Content_36 = {
    Text = "Is it because of Mr. Auguste? His words gave you too much stress, so..."
  },
  AvgDialog_15365_Content_37 = {
    Text = "Sanga shook her head."
  },
  AvgDialog_15365_Content_38 = {
    Text = [[
From start to finish, this had nothing to do with him.
Let's go. I'll take you somewhere.]]
  },
  AvgDialog_15365_Content_39 = {
    Text = "Finally—my secret base."
  },
  AvgDialog_15365_Content_4 = {
    Text = [[
<Yellow:I've decided to secretly follow her tonight to see what she's really up to.>
Wish me luck.

Camille@1
A.F.2@Year 1, September]]
  },
  AvgDialog_15365_Content_40 = {
    Text = "This is an abandoned seaside warehouse filled with various bizarre and twisted sculpture studies."
  },
  AvgDialog_15365_Content_41 = {
    Text = "Coral, shells, Tentacles, and buildings and creatures adorned with strange carvings... Their only commonality is their close connection to the ocean."
  },
  AvgDialog_15365_Content_42 = {
    Text = "The texture of these sculptures..."
  },
  AvgDialog_15365_Content_43 = {
    Text = "It's neither marble nor granite. Where did you find it?"
  },
  AvgDialog_15365_Content_44 = {
    Text = "Sanga playfully winked at you."
  },
  AvgDialog_15365_Content_45 = {
    Text = "This is my secret. One day, you will know."
  },
  AvgDialog_15365_Content_46 = {
    Text = "In the center of the cabin stands an unfinished humanoid sculpture."
  },
  AvgDialog_15365_Content_47 = {
    Text = "Its body is wrapped in grotesque tentacles, twisted at impossible angles. The veins on its neck bulge like a winding snake"
  },
  AvgDialog_15365_Content_48 = {
    Text = [[
Beautiful, isn't it?
They all call me "The Butcher" because I'm always ruthless with my models.]]
  },
  AvgDialog_15365_Content_49 = {
    Text = "Precisely because of this, I can capture the essence of the pain that entangles and lurks beneath the flesh."
  },
  AvgDialog_15365_Content_5 = {
    Text = "September in Cité is already bitterly cold.\nYou walk silently down the street, trying to conceal yourself in the shadows."
  },
  AvgDialog_15365_Content_50 = {
    Text = "My teacher was always overly cautious with models, so he could only become a second-rate sculptor."
  },
  AvgDialog_15365_Content_51 = {
    Text = "You gaze at the sculpture before you. It is undoubtedly beautiful, yet also cruel."
  },
  AvgDialog_15365_Content_52 = {
    Text = "Is this the work you plan to exhibit at the exhibition?"
  },
  AvgDialog_15365_Content_53 = {
    Text = "Sanga shook her head."
  },
  AvgDialog_15365_Content_54 = {
    Text = "Just some practice pieces. Before encountering that... D-Slime, my understanding of sculpture was quite shallow."
  },
  AvgDialog_15365_Content_55 = {
    Text = "Now I am like a newborn baby, forced to rediscover the world before my eyes..."
  },
  AvgDialog_15365_Content_56 = {
    Text = "<Yellow:Get to know you again.>"
  },
  AvgDialog_15365_Content_57 = {Text = "Me...?"},
  AvgDialog_15365_Content_58 = {
    Text = "Yes, you. I see new possibilities in your eyes and demeanor."
  },
  AvgDialog_15365_Content_59 = {
    Text = "Sanga lightly traced the contours of your face with her fingers."
  },
  AvgDialog_15365_Content_6 = {
    Text = [[
Sanga's slim figure is just ahead.
You maintain a moderate yet respectful distance, as if subtly connected by an invisible thread.]]
  },
  AvgDialog_15365_Content_60 = {
    Text = "Unlike other pampered ladies, her fingertips bear a thin layer of calluses, giving them a distinct coarse texture."
  },
  AvgDialog_15365_Content_61 = {
    Text = "You're afraid. Don't worry, I won't make you do anything against your will."
  },
  AvgDialog_15365_Content_62 = {
    Text = "Do you still remember when we were kids?"
  },
  AvgDialog_15365_Content_63 = {
    Text = "When I was a child?"
  },
  AvgDialog_15365_Content_64 = {
    Text = "You follow her words, delving deeper into and exploring the chaotic thoughts of the original host..."
  },
  AvgDialog_15365_Content_65 = {
    Text = "Finally stuck in that dim and hazy summer."
  },
  AvgDialog_15365_Content_66 = {
    Text = "Of course, I remember. At the age of 5, you were able to shape a human skeleton out of mud."
  },
  AvgDialog_15365_Content_67 = {
    Text = "I'll go to the beach to gather various materials for you, and Master Paul Claudel is responsible for throwing those models into the furnace for firing."
  },
  AvgDialog_15365_Content_68 = {
    Text = "Yeah, it's a little secret among the three of us."
  },
  AvgDialog_15365_Content_69 = {
    Text = "One time, you were caught by your father. You took all the blame alone and were punished to stand for an entire night."
  },
  AvgDialog_15365_Content_7 = {
    Text = "This thread guides you through towering buildings and long, gloomy frost, ultimately leading to your shared destination—"
  },
  AvgDialog_15365_Content_70 = {
    Text = "Sanga's gray eyes were veiled by a thin, sorrowful mist."
  },
  AvgDialog_15365_Content_71 = {
    Text = "She gently embraces you."
  },
  AvgDialog_15365_Content_72 = {
    Text = "You are all my family forever. Did Paul send you to find me?"
  },
  AvgDialog_15365_Content_73 = {
    Text = "Yes. The young master... is unwell and cannot come in person."
  },
  AvgDialog_15365_Content_74 = {
    Text = [[
You breathe lightly into Sanga's neck, her scent filling your nose.
A hint of the sea breeze.]]
  },
  AvgDialog_15365_Content_75 = {
    Text = "Don't worry. Since I promised to go home with you, I won't break my word."
  },
  AvgDialog_15365_Content_76 = {
    Text = "However, I must leave you for now."
  },
  AvgDialog_15365_Content_77 = {
    Text = "Leaving me...? Where are you going?"
  },
  AvgDialog_15365_Content_78 = {
    Text = "Sanga said nothing, but turned to look at the grey sea outside."
  },
  AvgDialog_15365_Content_79 = {
    Text = "It's a foggy night, with gentle waves rhythmically lapping like the pulse from Sanga's neck."
  },
  AvgDialog_15365_Content_8 = {
    Text = "An abandoned tomb"
  },
  AvgDialog_15365_Content_80 = {
    Text = "I don't know. Perhaps the depths of the ocean, or perhaps @1..."
  },
  AvgDialog_15365_Content_81 = {
    Text = "After that day, Miss Sanga disappeared."
  },
  AvgDialog_15365_Content_82 = {
    Text = [[
I went everywhere I could and asked everyone I could, but found nothing.

She left us like a gust of wind.
Even now, I still repeatedly recall that night by the sea.]]
  },
  AvgDialog_15365_Content_83 = {
    Text = [[
Back then, Ms. Sanga held me tight.
She might have said something later, or perhaps not; I don't know.

My memory has been hazy since that day.

<Red:White coral, shells, a mysterious underwater palace...>
Even now, these chaotic images torment my mind at night.]]
  },
  AvgDialog_15365_Content_84 = {
    Text = "<Yellow:\"Go to the salon exhibition for answers.\">\n\nMiss Sanga told me this. She also said—"
  },
  AvgDialog_15365_Content_85 = {
    Text = "Once you've witnessed those miracles, you'll understand me."
  },
  AvgDialog_15365_Content_86 = {
    Text = "Just follow my gaze..."
  },
  AvgDialog_15365_Content_87 = {
    Text = "I assure you."
  },
  AvgDialog_15365_Content_9 = {
    Text = "Miss Sanga."
  },
  AvgDialog_15367_Content_1 = {
    Text = "Get away, don't touch me...!!"
  },
  AvgDialog_15367_Content_10 = {
    Text = "I know you've recently set up a <Yellow:studio> on your own, but I think I need to remind you."
  },
  AvgDialog_15367_Content_11 = {
    Text = "Don't expect your <Yellow:blasphemous and abhorrent amateur creations> to win the favor of the government officials."
  },
  AvgDialog_15367_Content_12 = {
    Text = "I admit you're talented and have helped the studio a lot. But in a place like Cité, doing art requires more than just talent."
  },
  AvgDialog_15367_Content_13 = {
    Text = "If you anger me..."
  },
  AvgDialog_15367_Content_14 = {
    Text = "Mr. August, please mind your words."
  },
  AvgDialog_15367_Content_15 = {
    Text = "It's all right, Camille."
  },
  AvgDialog_15367_Content_16 = {
    Text = "Sanga gently held you from behind. Facing August's questioning, her expression remained calm."
  },
  AvgDialog_15367_Content_17 = {
    Text = "She crouched down, picked up the broken pieces of the sculpture's face, and threw them into the nearby trash pile."
  },
  AvgDialog_15367_Content_18 = {
    Text = "If you anger me, your work won't be exhibited or sold. As an artist, you'll never succeed, and in the end..."
  },
  AvgDialog_15367_Content_19 = {
    Text = "You'll either freeze to death on the streets or be sent to an asylum."
  },
  AvgDialog_15367_Content_2 = {
    Text = "With everyone's combined efforts, they finally managed to restrain the infuriated sculpture master."
  },
  AvgDialog_15367_Content_20 = {
    Text = "Of course, I know all of this, Teacher."
  },
  AvgDialog_15367_Content_3 = {
    Text = "Don't be rash, my dear teacher."
  },
  AvgDialog_15367_Content_4 = {
    Text = "Such a mediocre work ruins not only my mood but also your reputation."
  },
  AvgDialog_15367_Content_5 = {
    Text = "Heh... Don't be so clever. With less than half a year until the salon exhibition, can you magically create a better one?"
  },
  AvgDialog_15367_Content_6 = {Text = "One month."},
  AvgDialog_15367_Content_7 = {Text = "...What?"},
  AvgDialog_15367_Content_8 = {
    Text = "Give me a month, and I will give you an absolute <Yellow:surprise>."
  },
  AvgDialog_15367_Content_9 = {Text = "...Hmph."},
  AvgDialog_15368_Content_1 = {
    Text = "Upon reading this letter, it feels as if we are meeting in person."
  },
  AvgDialog_15368_Content_10 = {
    Text = "Your temples are throbbing. You try to move your body, but—"
  },
  AvgDialog_15368_Content_11 = {Text = "...!"},
  AvgDialog_15368_Content_12 = {
    Text = "<Shake:My legs... have gone numb...>"
  },
  AvgDialog_15368_Content_13 = {
    Text = "Hmm, was it just my imagination? For a moment when you opened your eyes, I seemed to see a brilliance I've never seen before."
  },
  AvgDialog_15368_Content_14 = {
    Text = "No, it's not an illusion. Your expression has changed as well..."
  },
  AvgDialog_15368_Content_15 = {
    Text = "A young sculptor apprentice's eyes sparkled with excitement as she suddenly leaned in toward you."
  },
  AvgDialog_15368_Content_16 = {
    Text = "Who are you?"
  },
  AvgDialog_15368_Content_17 = {Text = "Your Maid"},
  AvgDialog_15368_Content_18 = {
    Text = "<Shake:I-I'm your maid Camille@1, don't you remember? Haha...>"
  },
  AvgDialog_15368_Content_19 = {
    Text = "Remember your identity."
  },
  AvgDialog_15368_Content_2 = {
    Text = "Dear Mr. Claudel,\n\nI have arrived in Cité.\nUnlike the tranquility of Besançon, it is filled with noisy disturbances here.\nThe ringing of bells, the rumbling of carriages, and the clamor of crowds...\nThe thought that Miss Sanga lives in such an environment deeply unsettles me."
  },
  AvgDialog_15368_Content_20 = {
    Text = "This time, you are a maid who grew up with Sanga and have been sent by Master Paul to bring her home."
  },
  AvgDialog_15368_Content_21 = {
    Text = "\"Make sure to save her soul from that devil who only exploits and plagiarizes others.\""
  },
  AvgDialog_15368_Content_23 = {
    Text = "<Gray:No, that's not right...>"
  },
  AvgDialog_15368_Content_24 = {
    Text = "Remember your identity."
  },
  AvgDialog_15368_Content_25 = {
    Text = "This time, you are a maid who grew up with Sanga and have been sent by Young Master @1: Claudel to bring her home."
  },
  AvgDialog_15368_Content_26 = {
    Text = "\"Be sure to save her soul from that devil who only exploits and plagiarizes his subordinates.\""
  },
  AvgDialog_15368_Content_27 = {
    Text = "I, I'm your maid, Camille@1. Don't you remember? Haha..."
  },
  AvgDialog_15368_Content_28 = {
    Text = "<Shake:It's been so many years apart, we've both changed, haven't we?>"
  },
  AvgDialog_15368_Content_29 = {Text = "..."},
  AvgDialog_15368_Content_3 = {
    Text = "Rumors have spread. \nPeople say Miss Sanga spends all her time with a man over 20 years her senior, \"for art.\" \nIt's absurd. Tomorrow, I'll visit the studio to find out. \n\nThis time, I will fulfill your request—\n<Yellow:Bring your sister, our Miss Sanga, back to Besançon.>\n\nCamille@1\nA.F.2@1 Year 8"
  },
  AvgDialog_15368_Content_30 = {
    Text = [[
You're definitely different now, much more vivid than before.
It's as if... you've suddenly come alive.]]
  },
  AvgDialog_15368_Content_31 = {
    Text = "<Gray:Is this the artist's intuition? I'll need to be more careful from now on.>"
  },
  AvgDialog_15368_Content_32 = {
    Text = "<Shake:If you don't mind, could you help me out? I can't stand up right now...>"
  },
  AvgDialog_15368_Content_33 = {
    Text = "Sanga gently holds your hand, a hint of worry flashing in her tranquil eyes."
  },
  AvgDialog_15368_Content_34 = {
    Text = "Sorry, I was too absorbed in my creation earlier. You must be feeling uncomfortable now. Let me take a look."
  },
  AvgDialog_15368_Content_35 = {Text = "Whoa—!!"},
  AvgDialog_15368_Content_36 = {
    Text = "The studio door was pulled open with a jerk."
  },
  AvgDialog_15368_Content_37 = {
    Text = "A tall, brooding man walked in, followed by several unfamiliar faces."
  },
  AvgDialog_15368_Content_38 = {
    Text = "Without needing to access any of the original host's memories, you recognized the man by his distinctive beard—"
  },
  AvgDialog_15368_Content_39 = {
    Text = "The renowned sculptor <Blue:August>."
  },
  AvgDialog_15368_Content_4 = {
    Text = "Miss Sanga, come back with me. There's no place to warm up here—"
  },
  AvgDialog_15368_Content_40 = {
    Text = "Even now, his sculptures are still acclaimed as masterpieces and are highly sought after at the Londinium auctions."
  },
  AvgDialog_15368_Content_41 = {
    Text = "Seeing you and Sanga holding hands, August frowned. But soon, his attention was drawn to the sculpture before him."
  },
  AvgDialog_15368_Content_42 = {
    Text = "This is... <Big:A masterpiece, without a doubt!>"
  },
  AvgDialog_15368_Content_43 = {
    Text = "The others gathered around, curiously looking at the freshly made sculpture and exclaiming in admiration."
  },
  AvgDialog_15368_Content_44 = {
    Text = "Good, very good... Contact someone from the Ministry of Culture and tell them we have made progress on the exhibits for this year's Cité exhibition."
  },
  AvgDialog_15368_Content_45 = {
    Text = "I can't wait to see those critics' jaws drop... Hahaha!"
  },
  AvgDialog_15368_Content_46 = {
    Text = "August's hearty laugh echoes in the empty studio. He pushes you aside and grips Sanga's hand tightly."
  },
  AvgDialog_15368_Content_47 = {
    Text = "I knew you wouldn't disappoint me, Sanga."
  },
  AvgDialog_15368_Content_48 = {
    Text = "Sanga slowly pulled her hand out and walked to the sculpture."
  },
  AvgDialog_15368_Content_49 = {
    Text = "An undisputed... masterpiece?"
  },
  AvgDialog_15368_Content_5 = {
    Text = [[
Don't move, and don't speak. Just stay like this.
Yes, just like that...]]
  },
  AvgDialog_15368_Content_50 = {
    Text = "What do you think, Camille?"
  },
  AvgDialog_15368_Content_51 = {Text = "Uh, I...?"},
  AvgDialog_15368_Content_52 = {
    Text = "You gaze at the sculpture before you that looks almost exactly like \"you,\" lost in thought..."
  },
  AvgDialog_15368_Content_53 = {Text = "Normal"},
  AvgDialog_15368_Content_54 = {
    Text = "Well, stiff expressions, chaotic structure, and lack of tension..."
  },
  AvgDialog_15368_Content_55 = {
    Text = "You comment in an affected manner. In fact, you have always been disconnected from art; you only said this because you couldn't tolerate August's overbearing attitude."
  },
  AvgDialog_15368_Content_56 = {
    Text = "You don't like him."
  },
  AvgDialog_15368_Content_57 = {
    Text = "Sanga smiled at you, like a loving mother facing a babbling child."
  },
  AvgDialog_15368_Content_58 = {
    Text = "Hmm... Though our reasons may differ, we've arrived at the same conclusion."
  },
  AvgDialog_15368_Content_59 = {
    Text = "Masterpiece!"
  },
  AvgDialog_15368_Content_6 = {
    Text = "Be a good model for me and let me finish this piece... Then we can talk about going home."
  },
  AvgDialog_15368_Content_60 = {
    Text = "Truly unparalleled. I can't find any flaws in it."
  },
  AvgDialog_15368_Content_61 = {
    Text = "You, like everyone else, have had your full attention captured by this sculpture that appears free-flowing yet is meticulously crafted."
  },
  AvgDialog_15368_Content_62 = {
    Text = "Of course, this is also related to poor blood circulation caused by maintaining the same posture for a long time."
  },
  AvgDialog_15368_Content_63 = {
    Text = "A brain deprived of oxygen cannot perceive things clearly, but flattery is always welcome."
  },
  AvgDialog_15368_Content_64 = {
    Text = "You're absolutely right. Its biggest problem is that it has no flaws."
  },
  AvgDialog_15368_Content_65 = {
    Text = "Now... What should I do with you?"
  },
  AvgDialog_15368_Content_66 = {
    Text = "Sanga rested her chin on her hand, gazing at the sculpture before her. Then, she casually tapped the sculpture's forehead with her index finger—"
  },
  AvgDialog_15368_Content_67 = {
    Text = "Splash—!!"
  },
  AvgDialog_15368_Content_68 = {
    Text = "The sculpture traced a graceful arc, then crashed to the ground with a loud thud."
  },
  AvgDialog_15368_Content_69 = {
    Text = "Camille—or rather, your anxious face shatters into countless pieces."
  },
  AvgDialog_15368_Content_7 = {
    Text = "Is this...?"
  },
  AvgDialog_15368_Content_70 = {Text = "..."},
  AvgDialog_15368_Content_71 = {
    Text = "Miss Claudel, have you gone mad?!"
  },
  AvgDialog_15368_Content_72 = {
    Text = "August lunged at you in anger."
  },
  AvgDialog_15368_Content_73 = {
    Text = "<Big:This is the purest Petachi marble, straight from Palos—>"
  },
  AvgDialog_15368_Content_8 = {
    Text = "A messy house."
  },
  AvgDialog_15368_Content_9 = {
    Text = "Sculptures made of various types of clay, marble, and granite are casually placed, transforming this space into a simple carving workshop."
  },
  AvgDialog_15370_Content_1 = {
    Text = "Golden head"
  },
  AvgDialog_15370_Content_10 = {
    Text = [[
The rain grows heavier, and your throat becomes drier.
In such a storm, you must shout to hear your own voice.]]
  },
  AvgDialog_15370_Content_11 = {
    Text = "Here... I am here..."
  },
  AvgDialog_15370_Content_12 = {
    Text = "@1 Hehe, here, here @2 here, here, here..."
  },
  AvgDialog_15370_Content_13 = {
    Text = "Countless voices assault you from all directions. You can't hold on and finally collapse to your knees on the beach."
  },
  AvgDialog_15370_Content_14 = {
    Text = "Perhaps everything is your phantasm... Perhaps Miss Sanga has left forever."
  },
  AvgDialog_15370_Content_15 = {
    Text = "<Shake:Miss Sanga, come out... I know you're here...>"
  },
  AvgDialog_15370_Content_16 = {
    Text = "Unknowingly, the maid's consciousness has gradually devoured you. Her hopes and suffering have deeply stirred your heart."
  },
  AvgDialog_15370_Content_17 = {
    Text = "You press your forehead against the damp sand, a strange whimper escaping from your throat."
  },
  AvgDialog_15370_Content_18 = {
    Text = "<Shake:Miss Sanga...>"
  },
  AvgDialog_15370_Content_19 = {
    Text = "<Red:I'm here... I'm right here...>"
  },
  AvgDialog_15370_Content_2 = {
    Text = "Dear Mr. Claudel,\n\nThe \"Death of Ms. Coral\" has been a tremendous success in Cité, and everyone is talking about it.\nWhen I look at this sculpture, I can't help but think of you.\n\nIt is made from a dull white material, similar to the stones that cover you and leave you immobile.\nBut they won't let me touch the sculpture@1\nI will find a way."
  },
  AvgDialog_15370_Content_20 = {
    Text = "...What is this?"
  },
  AvgDialog_15370_Content_21 = {
    Text = "A cold sensation touches my fingertips."
  },
  AvgDialog_15370_Content_22 = {
    Text = "The white haze spreads from my fingertips once again, like living vines..."
  },
  AvgDialog_15370_Content_23 = {
    Text = "Slowly and steadily..."
  },
  AvgDialog_15370_Content_24 = {
    Text = "Finally... the moment has arrived."
  },
  AvgDialog_15370_Content_25 = {
    Text = [[
A delicate pair of women's shoes came to a stop before you.
Sanga held a chisel, her expression as calm and detached as ever.]]
  },
  AvgDialog_15370_Content_26 = {
    Text = "Miss Sanga... you are indeed still alive..."
  },
  AvgDialog_15370_Content_27 = {
    Text = "It depends on how you define \"being alive.\""
  },
  AvgDialog_15370_Content_28 = {
    Text = "The soft glow of distant lights gently envelops Sanga's body. She smiles quietly at you."
  },
  AvgDialog_15370_Content_29 = {
    Text = "I'm back, Camille. You must have been waiting for me for a long time, right?"
  },
  AvgDialog_15370_Content_3 = {
    Text = [[
Miss Sanga finally fulfilled her wish. She exchanged her life for immortal art.
But she also left us forever.
It has been nearly a month since the exhibition ended, and I still deeply miss her.

<Yellow:I will find her and bring her home.>

Camille@1
A.F.2@Year 8 Month]]
  },
  AvgDialog_15370_Content_30 = {
    Text = "Pain, shock, ecstasy..."
  },
  AvgDialog_15370_Content_31 = {
    Text = "Your chest is filled with countless emotions. You open your mouth, but find yourself unable to utter a single complete syllable."
  },
  AvgDialog_15370_Content_32 = {
    Text = "Sanga@1...not@2..."
  },
  AvgDialog_15370_Content_33 = {Text = "Shh..."},
  AvgDialog_15370_Content_34 = {
    Text = "Did you know? The human body is like a trembling, pulsating world."
  },
  AvgDialog_15370_Content_35 = {
    Text = "When the body and soul have undergone sufficient tempering, they will transform into the perfect sculpture at the peak of emotional outburst..."
  },
  AvgDialog_15370_Content_36 = {
    Text = "Cold fingers brush against your gradually stiffening face."
  },
  AvgDialog_15370_Content_37 = {
    Text = "Sanga looked at you with love, her gaze almost burning you up."
  },
  AvgDialog_15370_Content_38 = {
    Text = "Just like you are now..."
  },
  AvgDialog_15370_Content_39 = {
    Text = "Am I like this now...? Miss Sanga, is it the D-slime...?"
  },
  AvgDialog_15370_Content_4 = {
    Text = "You staggered to the seashore. There is no one here, only the dim, silent sea and the hazy horizon as your only companions."
  },
  AvgDialog_15370_Content_40 = {
    Text = "Shh... Quiet."
  },
  AvgDialog_15370_Content_41 = {
    Text = "To me, death has never been something to fear. What truly scares me is..."
  },
  AvgDialog_15370_Content_42 = {
    Text = "<Yellow:Losing beauty, or turning a blind eye to it.>"
  },
  AvgDialog_15370_Content_43 = {
    Text = "<Shake:Leave... me... alone...>"
  },
  AvgDialog_15370_Content_44 = {
    Text = "Don't say foolish things, Camille."
  },
  AvgDialog_15370_Content_45 = {
    Text = "<Red:You were already dead, remember?>"
  },
  AvgDialog_15370_Content_46 = {
    Text = "<Red:Dead...>"
  },
  AvgDialog_15370_Content_47 = {Text = "..."},
  AvgDialog_15370_Content_48 = {
    Text = "You plunge into the depths of the endless ocean once more."
  },
  AvgDialog_15370_Content_49 = {
    Text = "Those fragments sealed in memory are like white foam drifting around, constantly emerging and shattering..."
  },
  AvgDialog_15370_Content_5 = {
    Text = "You are all my eternal family."
  },
  AvgDialog_15370_Content_50 = {
    Text = "In the final moment before death, you must confront those brutal truths—"
  },
  AvgDialog_15370_Content_51 = {
    Text = "It's all my fault, Camille. It's all my fault... Let me hold you, so the wound won't hurt."
  },
  AvgDialog_15370_Content_52 = {
    Text = "My sister is a true genius. She will undoubtedly become a great artist immortalized in books!"
  },
  AvgDialog_15370_Content_53 = {
    Text = "Ahem... Stop fooling yourself, Camille..."
  },
  AvgDialog_15370_Content_54 = {
    Text = "Bring her back to me@2. I have something to ask her in person..."
  },
  AvgDialog_15370_Content_55 = {
    Text = "Extra, Extra!!"
  },
  AvgDialog_15370_Content_56 = {
    Text = "The world-shocking <Yellow:Sculpture Murder Case> has claimed yet another victim!"
  },
  AvgDialog_15370_Content_57 = {
    Text = "To date, there have been 54 cases of <Yellow:dizziness and hysteria> caused by attending \"Death of Ms. Coral\"..."
  },
  AvgDialog_15370_Content_58 = {
    Text = "<Red:Of these, 23 people have already committed suicide...>"
  },
  AvgDialog_15370_Content_59 = {Text = "..."},
  AvgDialog_15370_Content_6 = {
    Text = "Don't worry. Since I promised to go home with you, I won't break my word."
  },
  AvgDialog_15370_Content_60 = {
    Text = "So I... knew everything..."
  },
  AvgDialog_15370_Content_61 = {
    Text = "You see the white ocean palace once again. Plankton gather on the white calcium carbonate, lazily stretching their limbs."
  },
  AvgDialog_15370_Content_62 = {
    Text = "You also saw those white sculptures drifting aimlessly in the seawater."
  },
  AvgDialog_15370_Content_63 = {
    Text = "Some familiar faces are among them, like Mr. Auguste, still displaying the anger and despair from lunging at the sculpture."
  },
  AvgDialog_15370_Content_64 = {
    Text = "For example, Young Master Paul, with his sunken eye sockets filled with melancholy, seemed to have long foreseen his fate."
  },
  AvgDialog_15370_Content_65 = {
    Text = "The warm seawater envelops your body, its undulating rhythm like a flowing ballad."
  },
  AvgDialog_15370_Content_66 = {
    Text = [[
Before opening their eyes, the baby waves its tiny hands,
Holding clay, feeling a joy akin to maternal love.
The art of creation and control spreads through their fingers.

<Red:Open your eyes, and behold all born of beauty...>]]
  },
  AvgDialog_15370_Content_67 = {
    Text = "Cold hands gently embrace you. Sanga buries her soft cheek in your stiff shoulder."
  },
  AvgDialog_15370_Content_68 = {
    Text = "Can you hear them? Those songs keep echoing in my mind."
  },
  AvgDialog_15370_Content_69 = {
    Text = "It is the call of <Yellow:Them>, a fate I am destined to never escape..."
  },
  AvgDialog_15370_Content_7 = {
    Text = "She won't break her promise... She won't."
  },
  AvgDialog_15370_Content_70 = {
    Text = "I followed the songs and finally arrived here."
  },
  AvgDialog_15370_Content_71 = {
    Text = "Miracles and beauty from the ocean depths... I have nothing to offer Him but you."
  },
  AvgDialog_15370_Content_72 = {Text = "Me...?"},
  AvgDialog_15370_Content_73 = {
    Text = "Yeah, it's only you — %player%."
  },
  AvgDialog_15370_Content_74 = {
    Text = "She clearly and unmistakably spoke your original name."
  },
  AvgDialog_15370_Content_75 = {
    Text = "From the moment you opened your eyes, I knew."
  },
  AvgDialog_15370_Content_76 = {
    Text = "<Yellow:You are the true \"Death of Ms. Coral.\">"
  },
  AvgDialog_15370_Content_77 = {
    Text = "Consciousness gradually blurred, and white coral had already spread all over the body."
  },
  AvgDialog_15370_Content_78 = {
    Text = "You feel your blood and flesh growing heavy, but strangely, your bodies keep rising amidst the foam and coral."
  },
  AvgDialog_15370_Content_79 = {
    Text = "<Shake:No... home... go home...>"
  },
  AvgDialog_15370_Content_8 = {
    Text = "You lift your skirt and run along the long coastline without stopping."
  },
  AvgDialog_15370_Content_80 = {
    Text = "This is your home, %player%."
  },
  AvgDialog_15370_Content_81 = {Text = "No..."},
  AvgDialog_15370_Content_82 = {
    Text = "You gaze intently at Sanga's face until your pupils are covered by grayish-white coral."
  },
  AvgDialog_15370_Content_83 = {
    Text = "You fell into an endless Illusion."
  },
  AvgDialog_15370_Content_84 = {
    Text = "All oceans, corals, and sculptures fade away; only her voice remains."
  },
  AvgDialog_15370_Content_85 = {
    Text = "As always, a gentle yet indifferent voice."
  },
  AvgDialog_15370_Content_86 = {
    Text = "I promised you that I would take you home..."
  },
  AvgDialog_15370_Content_87 = {
    Text = "I promised you."
  },
  AvgDialog_15370_Content_9 = {
    Text = "Miss Sanga—Miss Sanga—"
  },
  AvgDialog_15605_Content_1 = {Text = "Start Test"},
  AvgDialog_15605_Content_10 = {
    Text = "Have you entered the Awakener's past again? You remember reading a document..."
  },
  AvgDialog_15605_Content_11 = {
    Text = "Why is there no response? Is the hearing module malfunctioning?"
  },
  AvgDialog_15605_Content_12 = {
    Text = "That depends. Did you secretly work on the module after I left yesterday?"
  },
  AvgDialog_15605_Content_13 = {
    Text = [[
No, no, really, not this time, I swear!
How about I try again? People of TikTok, can you hear me?]]
  },
  AvgDialog_15605_Content_14 = {Text = "Yes."},
  AvgDialog_15605_Content_15 = {
    Text = "Look, look! Its mouth is moving. I told you it's fine!"
  },
  AvgDialog_15605_Content_16 = {
    Text = [[
The world's first fully automatic mechanical doll that follows voice commands! The first! Fully automatic!
Dear Father, take me now, for I have no regrets in my life!]]
  },
  AvgDialog_15605_Content_17 = {
    Text = "I do have many regrets, like not completing the command response test, mobility test, operational time test..."
  },
  AvgDialog_15605_Content_18 = {
    Text = "Mei—Yi—you're really not interesting at all."
  },
  AvgDialog_15605_Content_19 = {
    Text = "...Overall Coordination Test, Balance Test, Load-Bearing Test..."
  },
  AvgDialog_15605_Content_2 = {
    Text = "Gear engagement: good; hydraulic system: no pressure leakage; motor MF311000: running normally, temperature high but within limits."
  },
  AvgDialog_15605_Content_20 = {
    Text = "Alright, I get it! <Small:You're more mechanical than a Tik-Tokian.>"
  },
  AvgDialog_15605_Content_21 = {
    Text = "What did you say?"
  },
  AvgDialog_15605_Content_22 = {
    Text = "Ah—next, we'll conduct a basic command reception and comprehension test!\nDida Man, blink."
  },
  AvgDialog_15605_Content_23 = {Text = "Blink"},
  AvgDialog_15605_Content_24 = {
    Text = [[
Watch my finger, very good.
Open your mouth? Very good, you are my good child.]]
  },
  AvgDialog_15605_Content_25 = {Text = "...Ugh."},
  AvgDialog_15605_Content_26 = {
    Text = "What! I created you bit by bit, so it's only reasonable to call me Mom."
  },
  AvgDialog_15605_Content_27 = {
    Text = "Yes, yes, Gear Freak Mama, bring your dear steel baby's left arm. It's time for the limb test."
  },
  AvgDialog_15605_Content_28 = {
    Text = "An arm composed of complex gears and incomprehensible mechanical structures briefly appears in your field of vision, then vanishes to your left, followed by your right."
  },
  AvgDialog_15605_Content_29 = {
    Text = "Limb installation went well. Following the instructions, you raise your arms and legs, and Erica's smile grows wider."
  },
  AvgDialog_15605_Content_3 = {
    Text = "Special Energy S, status stable."
  },
  AvgDialog_15605_Content_30 = {
    Text = "Alright, next—Ah!"
  },
  AvgDialog_15605_Content_31 = {
    Text = [[
Thick black smoke rises below your line of sight: something is burning.
You look down and see sparks and electricity flickering from your abdomen.]]
  },
  AvgDialog_15605_Content_32 = {
    Text = "Fire extinguisher, Mei, Mei!"
  },
  AvgDialog_15605_Content_33 = {
    Text = "Out of the way!"
  },
  AvgDialog_15605_Content_34 = {
    Text = [[
The extinguisher sprayed white foam, dispersing the burnt smell with the airflow.
Erica moved closer, ignoring the heat of the motor, and took it apart.]]
  },
  AvgDialog_15605_Content_35 = {Text = "Erica!"},
  AvgDialog_15605_Content_36 = {
    Text = "The charred motor lay on the workbench. Erica took a deep breath and belatedly blew on her foam-covered hand."
  },
  AvgDialog_15605_Content_37 = {
    Text = "It's scorching me, it's scorching me."
  },
  AvgDialog_15605_Content_38 = {
    Text = "Energy S, take a look at Energy S!"
  },
  AvgDialog_15605_Content_39 = {
    Text = "Erica leaned close to the motor, her slightly reddened fingers gently brushing over its metal casing."
  },
  AvgDialog_15605_Content_4 = {
    Text = "Whew—are you ready?\nAutomaton Tik-Tok, Test #13, commence."
  },
  AvgDialog_15605_Content_40 = {
    Text = "Looks like an external circuit shorted and caught fire, but the interior should remain unharmed."
  },
  AvgDialog_15605_Content_41 = {
    Text = "Don't worry, I'll check it in a moment."
  },
  AvgDialog_15605_Content_42 = {
    Text = "...Are you driving me away again?"
  },
  AvgDialog_15605_Content_43 = {Text = "Mei..."},
  AvgDialog_15605_Content_44 = {
    Text = "It was wrong of me to experiment with Energy S without permission, but you know our funding situation. Using S as a breakthrough can buy us more time and materials."
  },
  AvgDialog_15605_Content_45 = {
    Text = [[
Let me see it, just once. I swear I won't disclose any of its information.
Please.]]
  },
  AvgDialog_15605_Content_46 = {
    Text = "I told you, there's nothing inside."
  },
  AvgDialog_15605_Content_47 = {
    Text = [[
...You can't even be bothered to come up with an excuse. Do you really need to be so guarded against me?
Haven't I always been thinking about our future?]]
  },
  AvgDialog_15605_Content_48 = {Text = "..."},
  AvgDialog_15605_Content_49 = {
    Text = [[
Forget it.
I'll sit at Joey's diner for a while. Do whatever you want.]]
  },
  AvgDialog_15605_Content_5 = {
    Text = "Open your eyes"
  },
  AvgDialog_15605_Content_50 = {
    Text = "The door closed, the footsteps faded away, and Erica sighed."
  },
  AvgDialog_15605_Content_51 = {
    Text = [[
She's still... But that person warned me about Energy S...
I can't let Mei take the risk with me.]]
  },
  AvgDialog_15605_Content_52 = {
    Text = "She turned back to the motor, seemingly reinvigorated in spirit."
  },
  AvgDialog_15605_Content_53 = {
    Text = "I'll figure it out. Wait for me, Mei."
  },
  AvgDialog_15605_Content_54 = {
    Text = "She unscrewed the cap and pulled out a black cylinder."
  },
  AvgDialog_15605_Content_55 = {
    Text = "In that instant, your world was plunged into darkness."
  },
  AvgDialog_15605_Content_6 = {
    Text = "Tick-tock person, can you hear me?"
  },
  AvgDialog_15605_Content_7 = {Text = "...Erica?"},
  AvgDialog_15605_Content_8 = {
    Text = "A familiar face displays a natural expression completely different from what you remember. Compared to an automaton, she appears more like a living person."
  },
  AvgDialog_15605_Content_9 = {
    Text = "...What is happening here?"
  },
  AvgDialog_15606_Content_1 = {
    Text = "Thus spoke the voice"
  },
  AvgDialog_15606_Content_10 = {
    Text = "She muttered as she left, leaving you with the motor and parts on the workbench."
  },
  AvgDialog_15606_Content_11 = {
    Text = "You look at your hand."
  },
  AvgDialog_15606_Content_12 = {
    Text = "Slender, strong, and delicately crafted porcelain shell, carefully polished and maintained. Despite its coldness, it looks lifelike under dim light."
  },
  AvgDialog_15606_Content_13 = {
    Text = [[
This is Erica's hand, the hand of the <Blue:Automaton Erica> you know.
You seem to inhabit her later body, becoming the automaton she created.]]
  },
  AvgDialog_15606_Content_14 = {
    Text = [[
The person you saw just now was clearly human.
What kind of experience could have transformed her into what she has become?]]
  },
  AvgDialog_15606_Content_15 = {Text = "Erica?"},
  AvgDialog_15606_Content_16 = {
    Text = [[
You blink, and Mei has somehow entered.
Her gaze sweeps across the room and finally settles on the motor next to you.]]
  },
  AvgDialog_15606_Content_17 = {Text = "..."},
  AvgDialog_15606_Content_18 = {
    Text = "After scanning the room a second time, she shut the door and hurried toward the generator."
  },
  AvgDialog_15606_Content_19 = {
    Text = "Sorry, Erica."
  },
  AvgDialog_15606_Content_2 = {
    Text = "Tick-Tock, my dear, can you hear me?"
  },
  AvgDialog_15606_Content_20 = {
    Text = "The lid twisted open, and Mei pinched the item inside. This time, you saw it clearly: a metal cylinder no more than 5 cm in diameter, with the letter \"S\" engraved on its side."
  },
  AvgDialog_15606_Content_21 = {
    Text = "Once she fully withdraws the cylinder, you will lose consciousness again.\nSo before that, you must—"
  },
  AvgDialog_15606_Content_22 = {
    Text = "Grab her hand"
  },
  AvgDialog_15606_Content_23 = {Text = "Ah!"},
  AvgDialog_15606_Content_24 = {
    Text = "What's going on—"
  },
  AvgDialog_15606_Content_25 = {
    Text = "Erica rushed into the room, her concern freezing the moment she saw the cylinder in Mei's hand."
  },
  AvgDialog_15606_Content_26 = {
    Text = "Mei, what are you doing?"
  },
  AvgDialog_15606_Content_27 = {
    Text = "What are you doing!"
  },
  AvgDialog_15606_Content_28 = {
    Text = "I'm just trying... this energy... it really works..."
  },
  AvgDialog_15606_Content_29 = {
    Text = "Faced with the small cylinder that powered the entire motor and all connected equipment, Mei's eyes widened."
  },
  AvgDialog_15606_Content_3 = {
    Text = "Awakening from the eternal darkness, you find yourself still in the workshop. The charred motor remains on the workbench, connected to your Body by several cables of varying thickness."
  },
  AvgDialog_15606_Content_30 = {
    Text = "Do you know what this means, Erica?"
  },
  AvgDialog_15606_Content_31 = {
    Text = "This means it's dangerous, Mei. I told you not to mess around—"
  },
  AvgDialog_15606_Content_32 = {
    Text = "No, no, listen, Erica—this thing, this tiny thing, can provide energy with no loss, no emissions, for a long time. Don't you understand?"
  },
  AvgDialog_15606_Content_33 = {
    Text = "Coal and oil are nothing in comparison. If we can mass-produce it, we will rewrite the energy structure of humanity and make history!"
  },
  AvgDialog_15606_Content_34 = {
    Text = "You must tell me how you managed to do it, you must!"
  },
  AvgDialog_15606_Content_35 = {
    Text = "Erica, where are you going? What do you mean by saying you don't know what to do, Erica!"
  },
  AvgDialog_15606_Content_36 = {
    Text = "The investor said that as long as they see the sample, they are willing to provide us with substantial funding and even a dedicated studio."
  },
  AvgDialog_15606_Content_37 = {
    Text = "Why won't you listen—I don't know how to make this thing, I can't do it!"
  },
  AvgDialog_15606_Content_38 = {
    Text = "I've outgrown believing in fairy tales, Erica. What <Blue:Mysterious Shopkeeper>? If you want to brush me off, at least come up with a better excuse."
  },
  AvgDialog_15606_Content_39 = {
    Text = "If you can create such incredible things, why don't you have a more long-term vision?"
  },
  AvgDialog_15606_Content_4 = {
    Text = "Can be heard."
  },
  AvgDialog_15606_Content_40 = {
    Text = "Why confine yourself to this place, tinkering with these scraps?"
  },
  AvgDialog_15606_Content_41 = {
    Text = "Mei's voice hit Erica like a slap to the face. She stared at her partner and companion, unable to believe what she had just heard."
  },
  AvgDialog_15606_Content_42 = {
    Text = "...Junk, is that really what you think?"
  },
  AvgDialog_15606_Content_43 = {
    Text = "I thought we shared the same ideals."
  },
  AvgDialog_15606_Content_44 = {
    Text = "Mei bit her lip and tightened her grip on the cylinder."
  },
  AvgDialog_15606_Content_45 = {
    Text = "Face the facts, Erica. No one wants to spend money on automatons anymore. New energy is our future."
  },
  AvgDialog_15606_Content_46 = {
    Text = "...put down the special energy source."
  },
  AvgDialog_15606_Content_47 = {
    Text = "Think of all we could have: more funds, more resources.\nWith these, you can pursue your dreams. With these, you can—"
  },
  AvgDialog_15606_Content_48 = {
    Text = "I said, \"Drop it!\""
  },
  AvgDialog_15606_Content_49 = {
    Text = "Erica lunged forward to grab, but Mei failed to dodge in time and crashed into a nearby cabinet."
  },
  AvgDialog_15606_Content_5 = {
    Text = "Sorry, I promise to focus on tackling the voice module next! Please bear with it for now, okay?"
  },
  AvgDialog_15606_Content_50 = {Text = "!!"},
  AvgDialog_15606_Content_51 = {
    Text = "Bottles filled with various reagents and fuels topple over. You rush to shield the two people in front of you. The next second—"
  },
  AvgDialog_15606_Content_6 = {Text = "Nod."},
  AvgDialog_15606_Content_7 = {
    Text = "Thank the Father God, that's great. I was really worried a wire might have burned out."
  },
  AvgDialog_15606_Content_8 = {
    Text = "She let out a sigh of relief, then yawned widely as if only now feeling tired."
  },
  AvgDialog_15606_Content_9 = {
    Text = "I need to grab a coffee and have dinner..."
  },
  AvgDialog_15607_Content_1 = {
    Text = "The plasma cannon struck the giant hand, causing Silver to peel off the palm and fall silently to the ground."
  },
  AvgDialog_15607_Content_10 = {
    Text = "What... have I... done..."
  },
  AvgDialog_15607_Content_11 = {
    Text = [[
You still don't understand, but that's okay. You've already ignited the revolution of Life and Soul, this <Red:"Metamorphosis">.
Rest in peace. I will ensure everyone remembers your contribution.]]
  },
  AvgDialog_15607_Content_12 = {
    Text = "Erica closed her eyes."
  },
  AvgDialog_15607_Content_13 = {
    Text = "You're... right, you've always been right..."
  },
  AvgDialog_15607_Content_14 = {
    Text = "Black tears slid from the corners of her eyes as she wrinkled her nose and suddenly turned to look at you."
  },
  AvgDialog_15607_Content_15 = {
    Text = "I should have... listened to... you from the very beginning... I... shouldn't have taken this thing..."
  },
  AvgDialog_15607_Content_16 = {
    Text = "My sanity... my... help me... this one last time..."
  },
  AvgDialog_15607_Content_17 = {
    Text = "Is there really a third consciousness in this <Body>, or are you merely the embodiment of her guilt under the influence of <Dissolution>? You cannot tell."
  },
  AvgDialog_15607_Content_18 = {
    Text = "She extends her hand to you."
  },
  AvgDialog_15607_Content_19 = {
    Text = "Help... me... save..."
  },
  AvgDialog_15607_Content_2 = {
    Text = "After a moment of stillness, the giant hand disintegrated, and black slime poured down like heavy rain. It passed through you but stained Erica's phantom."
  },
  AvgDialog_15607_Content_20 = {
    Text = "You only know that you will help her and witness her fate as a \"human\"."
  },
  AvgDialog_15607_Content_21 = {
    Text = "Hold her hand"
  },
  AvgDialog_15607_Content_22 = {
    Text = "She looks at you in surprise, as if she never imagined she could actually touch her own \"sanity.\""
  },
  AvgDialog_15607_Content_23 = {Text = "Nod"},
  AvgDialog_15607_Content_24 = {
    Text = "She looks at you in surprise, as if she never expected her \"conscience\" to respond."
  },
  AvgDialog_15607_Content_25 = {
    Text = "Thank you..."
  },
  AvgDialog_15607_Content_26 = {
    Text = "The phantom burst like a bubble, leaving behind only a flickering orb that was still emitting its last light."
  },
  AvgDialog_15607_Content_27 = {
    Text = "You hold the shrunken light orb in your arms, gazing at the broken Silver not far away."
  },
  AvgDialog_15607_Content_28 = {
    Text = "You will succeed."
  },
  AvgDialog_15607_Content_3 = {
    Text = "It's... over..."
  },
  AvgDialog_15607_Content_4 = {
    Text = "Do you really think so?"
  },
  AvgDialog_15607_Content_5 = {Text = "!?"},
  AvgDialog_15607_Content_6 = {
    Text = "I told you, just enter this silver heart to attain true immortality."
  },
  AvgDialog_15607_Content_7 = {
    Text = "Struggle as you might, the black matter will eventually erase you, and then I will bring true <Red:\"Metamorphosis\"> to the world—immortality for all, eternal life for everyone."
  },
  AvgDialog_15607_Content_8 = {
    Text = "That is... death... not..."
  },
  AvgDialog_15607_Content_9 = {
    Text = "The color black increasingly consumed her body. Erica bent over in pain, her spirit on the verge of collapse."
  },
  AvgDialog_15608_Content_1 = {
    Text = "Is this... a spirit space?"
  },
  AvgDialog_15608_Content_2 = {
    Text = "Oh my god, what on earth is this..."
  },
  AvgDialog_15608_Content_3 = {
    Text = "Voice... Erica!"
  },
  AvgDialog_15609_Content_1 = {
    Text = "No, Erica, don't believe it!"
  },
  AvgDialog_15609_Content_10 = {
    Text = [[
The Caro body is merely a cage for the soul; only by freeing the soul can she join us.
Only metal bodies and minds grant us eternity.]]
  },
  AvgDialog_15609_Content_11 = {
    Text = "Fingers tightening, Mei's face contorted in pain."
  },
  AvgDialog_15609_Content_12 = {
    Text = "<Shake:You... insane...>"
  },
  AvgDialog_15609_Content_13 = {
    Text = "Another trembling hand appears on the screen. Erica grabs her own wrist, twists it, and detaches the uncontrollable hand, tossing it aside."
  },
  AvgDialog_15609_Content_14 = {
    Text = "The giant hand paused for a moment, as if somewhat puzzled."
  },
  AvgDialog_15609_Content_15 = {
    Text = "Why resist me? I'm granting her a new life."
  },
  AvgDialog_15609_Content_16 = {
    Text = "It's all phantasms, phantasms."
  },
  AvgDialog_15609_Content_17 = {
    Text = "Erica helped the unconscious May stand up slowly."
  },
  AvgDialog_15609_Content_18 = {
    Text = "I'm taking her to the hospital. I... must keep her alive."
  },
  AvgDialog_15609_Content_19 = {
    Text = "She hoisted Mei onto her shoulder and made her way through the studio, which was blown to pieces, heading toward the nearby door."
  },
  AvgDialog_15609_Content_2 = {
    Text = "Erica, Erica!"
  },
  AvgDialog_15609_Content_3 = {
    Text = "While you fight the enemy ahead, a slime creature sneaks behind and lunges at the light representing Erica's spirit."
  },
  AvgDialog_15609_Content_4 = {
    Text = [[
Like paint dissolving in water, darkness spreads inside the light orb, covering everything within.
The light orb begins to flicker.]]
  },
  AvgDialog_15609_Content_5 = {
    Text = "What's going on? My hand... it's moving on its own..."
  },
  AvgDialog_15609_Content_6 = {
    Text = "Was it you? Stop, <Big:Stop!>"
  },
  AvgDialog_15609_Content_7 = {
    Text = "Why? Don't you want to save her?"
  },
  AvgDialog_15609_Content_8 = {
    Text = "You're trying to choke her to death! Let go!"
  },
  AvgDialog_15609_Content_9 = {
    Text = "As darkness and light intertwine, you see a mechanical hand slowly extending toward Mei's neck."
  },
  AvgDialog_15610_Content_1 = {
    Text = "A single person's defence line is nearly non-existent, no matter how many monsters you smash. Bodies formed from slime quickly regroup, pass by you, and leap straight into the light sphere."
  },
  AvgDialog_15610_Content_10 = {
    Text = "Golden plasma crackled on the shadows, making Erica's form increasingly solid."
  },
  AvgDialog_15610_Content_11 = {
    Text = "She raises her hand and disperses the monster before you with plasma. The giant hand twitches slightly and lets out a sigh."
  },
  AvgDialog_15610_Content_12 = {
    Text = "I merely wished to repay you for bringing me back and granting me a new body. Why harm me?"
  },
  AvgDialog_15610_Content_13 = {
    Text = "Bring back? What do you mean, \"bring back\"? I never..."
  },
  AvgDialog_15610_Content_14 = {
    Text = "Can this power my doll?"
  },
  AvgDialog_15610_Content_15 = {
    Text = "Erica suspiciously held the black metal tube, examining it from all directions."
  },
  AvgDialog_15610_Content_16 = {
    Text = [[
If you're worried that it can't sustain the puppet's prolonged operation, don't be. 
This item is sufficient to power even more intricate and larger mechanisms.]]
  },
  AvgDialog_15610_Content_17 = {
    Text = "Are you saying that others are also using this energy?"
  },
  AvgDialog_15610_Content_18 = {
    Text = "Similar things exist, but identical? Absolutely impossible."
  },
  AvgDialog_15610_Content_19 = {
    Text = "What you're looking for is \"one-of-a-kind energy,\" and Daffodil's shop never lets its customers down."
  },
  AvgDialog_15610_Content_2 = {
    Text = "H-how annoying..."
  },
  AvgDialog_15610_Content_20 = {
    Text = "By the way, a friendly reminder—don't be curious about its structure and principles.\nOnce Pandora's Box is opened, you'll have to bear the consequences yourself."
  },
  AvgDialog_15610_Content_21 = {
    Text = "I don't want a genius like you to die young. Besides the projector, I have many other ideas I wish to realize."
  },
  AvgDialog_15610_Content_22 = {
    Text = "Looking forward to your next visit, Erica."
  },
  AvgDialog_15610_Content_23 = {
    Text = "No, impossible. There should only be — in Energy S."
  },
  AvgDialog_15610_Content_24 = {
    Text = [[
A tiny <Yellow:silver fragment>, right?
A magical thing that can drive machines and preserve the souls of living beings.]]
  },
  AvgDialog_15610_Content_25 = {
    Text = "Your spirit has merged with this body with the help of black matter. Enter the <Yellow:Silver Heart> before being corrupted, and you shall truly become immortal—you and I.\n\nAs my \"mother\" in this life, you are entitled to share it with me.\nIt's a pity that you are so stubborn."
  },
  AvgDialog_15610_Content_26 = {
    Text = "All I can do is let the <Yellow:black substance> devour you."
  },
  AvgDialog_15610_Content_27 = {
    Text = "The giant hand suddenly moved, spreading its fingers to reveal a cracked yet still shining Silver in its palm."
  },
  AvgDialog_15610_Content_28 = {
    Text = "Goodbye, my fleeting creator."
  },
  AvgDialog_15610_Content_3 = {
    Text = "The orb flickers again, and you see Erica's legs trembling uncontrollably."
  },
  AvgDialog_15610_Content_4 = {
    Text = "Gears interlock tightly, and a bright yellow electric arc flashes between the pipes and brackets."
  },
  AvgDialog_15610_Content_5 = {
    Text = "Stop resisting. Surrender control of your body to me."
  },
  AvgDialog_15610_Content_6 = {
    Text = "Don't you want to save her? Don't you wish for her to gain eternity together with you?"
  },
  AvgDialog_15610_Content_7 = {
    Text = "More flashes of lightning appear on the screen."
  },
  AvgDialog_15610_Content_8 = {
    Text = "Particles of light drifted out from the orb, gathering to form a humanoid silhouette."
  },
  AvgDialog_15610_Content_9 = {
    Text = "A-Are you Erica?!"
  },
  AvgDialog_15611_Content_1 = {
    Text = [[
Why save her?
She traded your dreams for her future. Don't you feel any resentment?]]
  },
  AvgDialog_15611_Content_10 = {
    Text = "But soon I realized: this is not a disaster, not a phantasm, but an opportunity for humanity."
  },
  AvgDialog_15611_Content_11 = {
    Text = [[
No pain or death in machines; in machines, we can create a true the Divine Realm, better than your false one.

We can transcend Caro life.]]
  },
  AvgDialog_15611_Content_12 = {
    Text = "Black slime drips again from the giant hand. Trembling and writhing, it crawls forward, merging with itself, excited by the eerie scene depicted by the sound."
  },
  AvgDialog_15611_Content_13 = {
    Text = "The voice grows louder, the giant hand shakes, flinging out more slime and more monsters."
  },
  AvgDialog_15611_Content_14 = {
    Text = "We can become gods ourselves."
  },
  AvgDialog_15611_Content_15 = {
    Text = "The slime suddenly accelerates and lunges at the light orb behind you once more."
  },
  AvgDialog_15611_Content_2 = {
    Text = [[
She just... made a wrong decision.
When she wakes up, we'll talk it through and everything will be resolved.]]
  },
  AvgDialog_15611_Content_3 = {
    Text = "The nearest phone booth is a kilometer away; she can't afford to wait."
  },
  AvgDialog_15611_Content_4 = {
    Text = "Sorry, I'd rather trust in humanity's survival instinct than your nonsense about \"liberating souls.\""
  },
  AvgDialog_15611_Content_5 = {
    Text = [[
If I am lying, how do you explain your current state?
Your Caro body has been shattered into pieces, yet your spirit remains, even controlling this body to continue living.

Doesn't this prove my point?]]
  },
  AvgDialog_15611_Content_6 = {
    Text = "<Big:You can't be sure this is why I turned out like this!>"
  },
  AvgDialog_15611_Content_7 = {
    Text = "Erica paused, seemingly wanting to inhale, but no longer had the organs to do so."
  },
  AvgDialog_15611_Content_8 = {
    Text = "What am I doing, arguing with a phantasm... Don't listen, don't think. He's a phantasm, born from toxic gas—"
  },
  AvgDialog_15611_Content_9 = {
    Text = [[
You're scared, so you try to run away.
I understand. Just like you, I was full of fear right after <Red:"Metamorphosis">.]]
  },
  AvgDialog_15612_Content_1 = {
    Text = "Invisible rhythms surround and envelop you, with faint glimmers of light appearing in the distance, fragile and out of reach."
  },
  AvgDialog_15612_Content_10 = {
    Text = "<Gray:No way... Could it be...>"
  },
  AvgDialog_15612_Content_11 = {
    Text = [[
Are you and Erica sharing the same body right now?
Is this why she has turned into a mechanical puppet?]]
  },
  AvgDialog_15612_Content_12 = {
    Text = "<Gray:But how could a regular explosion have this effect?>"
  },
  AvgDialog_15612_Content_13 = {
    Text = "Do you want to save her?"
  },
  AvgDialog_15612_Content_14 = {Text = "?!"},
  AvgDialog_15612_Content_15 = {
    Text = [[
A voice emerges from thin air, omnipresent yet elusive.
You look around, and a silhouette begins to take shape in the vast mental space]]
  },
  AvgDialog_15612_Content_16 = {
    Text = "Who, who's there?"
  },
  AvgDialog_15612_Content_17 = {
    Text = "I am the will that responds to you, the life granted a new body by you."
  },
  AvgDialog_15612_Content_18 = {
    Text = "I can be considered your Relic, and you, my \"mother\" in this life."
  },
  AvgDialog_15612_Content_19 = {
    Text = "A giant hand materializes behind the orb representing Erica's spirit, its fingers twitching and dripping with black goo."
  },
  AvgDialog_15612_Content_2 = {
    Text = "Mei, Mei! Wake up, Mei!"
  },
  AvgDialog_15612_Content_20 = {
    Text = "...Ticktockians...?"
  },
  AvgDialog_15612_Content_21 = {
    Text = [[
I like this name, yes, call me the Tick-Tock Man.
As a token of my rebirth, I can help you save her.
You just need to let go.]]
  },
  AvgDialog_15612_Content_22 = {
    Text = "Let go, and leave everything to me."
  },
  AvgDialog_15612_Content_23 = {
    Text = "The slime piled on the ground suddenly stirred, fusing together into twisted forms that wriggled toward the light."
  },
  AvgDialog_15612_Content_3 = {
    Text = "You quickly approach the source of the sound."
  },
  AvgDialog_15612_Content_4 = {
    Text = "It's a floating orb of light. Through it, you see a face covered in blood and sand — Mei's face."
  },
  AvgDialog_15612_Content_5 = {
    Text = "She seemed to be in a faint, unresponsive even to a gentle pat from a pale hand."
  },
  AvgDialog_15612_Content_6 = {
    Text = "<Gray:That hand...>"
  },
  AvgDialog_15612_Content_7 = {
    Text = [[
You lower your head, confirming your suspicion: the hand in the light sphere is identical to yours. 
It's the hand of an automaton, now moving under another's will.]]
  },
  AvgDialog_15612_Content_8 = {
    Text = "Damn it, Mei! We have to get out of here, Mei!"
  },
  AvgDialog_15612_Content_9 = {
    Text = "The mechanical hand moved to rest on Mei's shoulder, and the image within the light sphere shifted, revealing a studio still engulfed in flames, as if someone was looking around."
  },
  AvgDialog_15613_Content_1 = {
    Text = "Brilliant Conclusion"
  },
  AvgDialog_15613_Content_10 = {
    Text = "Right Foot."
  },
  AvgDialog_15613_Content_11 = {
    Text = "Erica fell to her knees. Frequent short circuits had rendered her left leg powerless, forcing her to support herself with her right arm, which lacked a hand."
  },
  AvgDialog_15613_Content_12 = {
    Text = [[
She carefully propped Mei up against the phone booth, then crawled inside using all four limbs. 
The electric current activated the phone box, and she pressed the emergency call button, stating the booth's location.]]
  },
  AvgDialog_15613_Content_13 = {
    Text = "This way... she... will be safe..."
  },
  AvgDialog_15613_Content_14 = {
    Text = "What's next...? What... could it be...?"
  },
  AvgDialog_15613_Content_15 = {
    Text = "You know what it is."
  },
  AvgDialog_15613_Content_16 = {
    Text = "You recall the contents of the file you read before entering here."
  },
  AvgDialog_15613_Content_17 = {
    Text = [[
On A.F. 297 @1@1 03:47, an unexplained explosion occurred southeast of The Aglo Republic @3 State @1@2@1 Town. The shockwave triggered a 3.8 magnitude earthquake in the area, with noticeable shaking reaching villages 5 kilometers away from @1@2@1 Town.

......

On A.F. 297 @1@1, 13 components were recovered from the woods southeast of The Aglo Republic @3 State @1@2@1 Town, numbered A101 to A114. Among them, components A108, A109, and A113 were severely damaged and have been handed over to Doll for design restoration.
A series of design blueprints matching the remnants of the explosion site were retrieved by the investigation team at @2 Road @1, suspected to be blueprints for explosive devices, which have also been submitted to Doll for analysis.]]
  },
  AvgDialog_15613_Content_18 = {
    Text = "You hear the wind rustling through the leaves."
  },
  AvgDialog_15613_Content_19 = {
    Text = "The light orb has dimmed, nearly blending into the surrounding darkness."
  },
  AvgDialog_15613_Content_2 = {Text = "Left Foot."},
  AvgDialog_15613_Content_20 = {
    Text = [[
Even if you save her Caro Body, what then? 
Death will eventually come; when it does, will she thank you, or will she resent you for taking away her chance at immortality? 

Let go, Erica, and let me take over this Body. 
I will make her <Red:"Transform">, allowing her to have a better future.]]
  },
  AvgDialog_15613_Content_21 = {
    Text = [[
I... always thought... I would die in an explosion...
Sorry... for... dragging you into this...]]
  },
  AvgDialog_15613_Content_22 = {
    Text = "...What are you planning to do?"
  },
  AvgDialog_15613_Content_23 = {
    Text = "Shut up... Demon... I'm not... talking to you..."
  },
  AvgDialog_15613_Content_24 = {
    Text = "The image in the orb shows a charred mechanical hand still leaking plasma."
  },
  AvgDialog_15613_Content_25 = {
    Text = "At some point, several strings were in their hands, covered in black goo."
  },
  AvgDialog_15613_Content_26 = {
    Text = "Sorry, Tik-Tok people... In the end... I have to destroy you myself..."
  },
  AvgDialog_15613_Content_27 = {
    Text = [[
Silence fell among you.
You still aren't sure of your role in this dream, and she doesn't seem to be waiting for a response.]]
  },
  AvgDialog_15613_Content_28 = {Text = "*sigh*..."},
  AvgDialog_15613_Content_29 = {
    Text = "What a... pity..."
  },
  AvgDialog_15613_Content_3 = {
    Text = "Right Foot."
  },
  AvgDialog_15613_Content_30 = {
    Text = "She pulled with great force."
  },
  AvgDialog_15613_Content_32 = {
    Text = "You suddenly sit up and find yourself back in your familiar room."
  },
  AvgDialog_15613_Content_33 = {
    Text = "Someone is knocking on your door."
  },
  AvgDialog_15613_Content_34 = {
    Text = "Please come in."
  },
  AvgDialog_15613_Content_35 = {
    Text = "Good afternoon, Keeper. You have a message from Doll. Would you like to receive it?"
  },
  AvgDialog_15613_Content_36 = {
    Text = "Doll has added another new feature for you... Receiving."
  },
  AvgDialog_15613_Content_37 = {
    Text = "Beep—Do you remember what day it is today, %player%? Two words: Testing."
  },
  AvgDialog_15613_Content_38 = {Text = "...Oh no."},
  AvgDialog_15613_Content_39 = {
    Text = "I suggest you show up in the classroom within five minutes, otherwise I can't guarantee what your training will be like for the next 30 days. Perhaps the physical training will be doubled?"
  },
  AvgDialog_15613_Content_4 = {
    Text = "Each step sends off sparks, and every movement echoes with the grating clash of machinery."
  },
  AvgDialog_15613_Content_40 = {
    Text = "Beep—End of message. Would you like to reply?"
  },
  AvgDialog_15613_Content_41 = {
    Text = "What are you replying for? Just get out already!!"
  },
  AvgDialog_15613_Content_42 = {
    Text = "The Keeper's figure disappeared at the end of the corridor. Erica turned around and looked at the scattered files on the table."
  },
  AvgDialog_15613_Content_43 = {
    Text = "Year 298@Jan@2, Mythag University Awakened Department, @3\nTorso restoration of Automaton E completed per T-38 blueprints, Serial EA301881.\nThis is our 10th attempt at restoration. I must express my admiration for the original designer and creator of this automaton—it is intricate and elegant, with hundreds of interlinked gears and bearings forming a symphony of mechanics. Even when stationary, it emanates a unique vitality.\nUnfortunately, we still lack the key machine blueprint—a cylinder with a diameter of 5cm and a length of 10cm. This should be the automaton's power core, yet I have never encountered anything so small capable of powering such a complex device...\nI hope Professor Doll has some ideas. I can't wait to see it fully operational."
  },
  AvgDialog_15613_Content_44 = {
    Text = "Year 298@Jan@2, Mythag University Awakened Department, @3\nElectrical machine restoration completed, Serial MF311028.\nDespite many hurdles (By the Father, we attempted 28 times, 28 times!), Professor Doll's final design proved correct—the power core is silver.\nAmong several Silvers tested, only unit E-1929 enabled normal machine operation. I can't help but think some lingering intent of the designer influenced this, though their current whereabouts remain unknown."
  },
  AvgDialog_15613_Content_45 = {
    Text = [[
Alluvial Year 300 @2 month @1 day, Mythag University, Awakening Department, Doll
Automatic Doll Erica awakened successfully.
The Awakener exhibits extreme aggression and destructive desires. Even with the investigator maintaining her spirit, she shows a clear inclination to attack and uncontrollably emits electrical currents, attacking surrounding objects indiscriminately.
Alistair determined that E-1929 contains two spirits: one is mad and strong, the other is weak but more rational. Attempts should be made to separate them or suppress the madness to a controllable level.
......
Alluvial Year 300 @2 month @2 day, Mythag University, Awakening Department, Doll
Unable to separate the spirits, actively considering the second option.
A spirit suppression device is a good idea.
......
Alluvial Year 303 @1 month @2 day, Mythag University, Awakening Department, Doll
Suppression device completed and installed successfully.
The Awakener's madness is restrained, overall state stabilizing, but there are still instances of brief suppression failure.
The Awakener's personality, preferences, etc., are completely lost, behaving more like a doll than a human.
At least she's not on the verge of exploding every moment anymore.
......]]
  },
  AvgDialog_15613_Content_46 = {
    Text = "Erica tilted her head, organized the files neatly, and left the room."
  },
  AvgDialog_15613_Content_5 = {
    Text = "Beneath a nearby streetlight, a public phone booth stands quietly."
  },
  AvgDialog_15613_Content_6 = {Text = "Left Foot."},
  AvgDialog_15613_Content_7 = {
    Text = "Right Foot."
  },
  AvgDialog_15613_Content_8 = {
    Text = "Noticing your resolve, the slime lying on the ground continues to attack Erica's mind, staining you completely black."
  },
  AvgDialog_15613_Content_9 = {Text = "Left Foot."},
  AvgDialog_18708_Content_1 = {Text = "!!!"},
  AvgDialog_18708_Content_10 = {
    Text = "Accompanied by painful groans, the Skull Hunter's features twisted to an unbelievable degree, with pus-filled cysts writhing beneath the skin, ready to burst out."
  },
  AvgDialog_18708_Content_11 = {
    Text = "Is this...?"
  },
  AvgDialog_18708_Content_13 = {
    Text = "Its head is mercilessly severed, black D-Slime gushing from the neck, almost splattering onto your face."
  },
  AvgDialog_18708_Content_14 = {
    Text = "Being overly curious isn't a good habit, Keeper."
  },
  AvgDialog_18708_Content_15 = {
    Text = "His skull was filled with accumulated D-Slime. I suggest you keep your distance."
  },
  AvgDialog_18708_Content_16 = {
    Text = "Lady Daffodil!"
  },
  AvgDialog_18708_Content_17 = {
    Text = "Good evening, my little rose."
  },
  AvgDialog_18708_Content_18 = {
    Text = "Why is it you again...?"
  },
  AvgDialog_18708_Content_19 = {
    Text = "I followed the Skull Hunter's trail here and took back my flower."
  },
  AvgDialog_18708_Content_2 = {
    Text = "The Skull Hunter collapses heavily to the ground, emitting a faint groan."
  },
  AvgDialog_18708_Content_20 = {
    Text = "Daffodil walked effortlessly on the floor stained with blood and D-Slime, picked a narcissus from the bedside, and lightly sniffed it."
  },
  AvgDialog_18708_Content_21 = {
    Text = "This is my Brown Cup Narcissus, which I've carefully cultivated for three years. It has a calming and soothing effect."
  },
  AvgDialog_18708_Content_22 = {
    Text = "Would you like to take a sniff?"
  },
  AvgDialog_18708_Content_23 = {
    Text = "<LightGray:No wonder I slept so soundly just now...>"
  },
  AvgDialog_18708_Content_24 = {
    Text = "You irritably brush aside the dewy, blooming narcissus in her hand."
  },
  AvgDialog_18708_Content_25 = {
    Text = "You seem to know a great deal about the Skull Hunter."
  },
  AvgDialog_18708_Content_26 = {
    Text = "How do you know his brain would ooze D-slime?"
  },
  AvgDialog_18708_Content_27 = {
    Text = "If you had lived as long as I have and seen enough Dissolution patients, you would naturally understand more."
  },
  AvgDialog_18708_Content_28 = {
    Text = "The Trail of the Skull Hunter?"
  },
  AvgDialog_18708_Content_29 = {
    Text = "\"Following the Trail of the Skull Hunter\"—Can you sense his location?"
  },
  AvgDialog_18708_Content_3 = {
    Text = "You hear \"thud, thud, thud\" coming from the stairs. The wooden door behind you is suddenly pulled open."
  },
  AvgDialog_18708_Content_30 = {
    Text = "I have my methods. However... to avoid frightening the children, I'd better not reveal them."
  },
  AvgDialog_18708_Content_31 = {Text = "..."},
  AvgDialog_18708_Content_32 = {
    Text = "Please leave for now, Lady Daffodil. Do not interfere with our investigation."
  },
  AvgDialog_18708_Content_33 = {
    Text = "Huh, you're not doubting me anymore?"
  },
  AvgDialog_18708_Content_34 = {
    Text = "I can't completely rule out your suspicion yet. But my intuition tells me..."
  },
  AvgDialog_18708_Content_35 = {
    Text = "If you were the \"Skull Hunter,\" you would handle it more cleanly and efficiently, leaving no such obvious traces behind."
  },
  AvgDialog_18708_Content_36 = {
    Text = [[
Oh my, is that a compliment for me?
To be precise, it's a fact, not just intuition.]]
  },
  AvgDialog_18708_Content_37 = {
    Text = "...Don't change the subject."
  },
  AvgDialog_18708_Content_38 = {
    Text = "Since you only arrived in town today, who was that person I saw last night?"
  },
  AvgDialog_18708_Content_39 = {
    Text = "Do you have a twin sister?"
  },
  AvgDialog_18708_Content_4 = {
    Text = "{Male=Mr.,Female=Miss} %player%, I just heard a sound, what happened?"
  },
  AvgDialog_18708_Content_40 = {Text = "..."},
  AvgDialog_18708_Content_41 = {
    Text = "Daffodil seemed troubled in thought, then suddenly reached out to you."
  },
  AvgDialog_18708_Content_42 = {
    Text = "Soft fingertips brush across your face for a moment, then glide to your neck, pausing to feel the pulse deep within your blood vessels."
  },
  AvgDialog_18708_Content_43 = {
    Text = "<Shake:...?>"
  },
  AvgDialog_18708_Content_44 = {
    Text = "I always thought humans were creatures skilled at disguise."
  },
  AvgDialog_18708_Content_45 = {
    Text = "You wrap yourselves in similar shells made of flesh, speaking similar words, with similar pulses and heartbeats..."
  },
  AvgDialog_18708_Content_46 = {
    Text = "For a long time, I couldn't distinguish between you, just as you couldn't distinguish me."
  },
  AvgDialog_18708_Content_47 = {
    Text = "So... you mean you're not twins, but share some kind of special relationship?"
  },
  AvgDialog_18708_Content_48 = {
    Text = "It's possible. Want to take a guess? You have three chances."
  },
  AvgDialog_18708_Content_49 = {
    Text = "...I refuse."
  },
  AvgDialog_18708_Content_5 = {
    Text = "Th-This is...?!"
  },
  AvgDialog_18708_Content_50 = {
    Text = "Even if I guess right, you still won't tell me the real answer. Am I correct?"
  },
  AvgDialog_18708_Content_51 = {
    Text = "Daffodil carelessly traced the veins on your neck with her fingertips, her eyes filled with an even deeper smile."
  },
  AvgDialog_18708_Content_52 = {
    Text = "You are truly getting to know me better, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_18708_Content_53 = {
    Text = "You take half a step back, moving out of Daffodil's reach, and give her a warning look."
  },
  AvgDialog_18708_Content_54 = {
    Text = "In your eyes, does looking exactly the same make them twins?"
  },
  AvgDialog_18708_Content_55 = {
    Text = "Generally speaking, this is probably the only possibility."
  },
  AvgDialog_18708_Content_56 = {
    Text = "But you and I both know that the world we live in is anything but \"ordinary.\""
  },
  AvgDialog_18708_Content_57 = {
    Text = "Sure. The most regrettable aspect of this world is its \"unconventionality.\""
  },
  AvgDialog_18708_Content_58 = {
    Text = "Being a pair of carefree twin sisters seems nice, too."
  },
  AvgDialog_18708_Content_6 = {
    Text = "You step forward and pull back the Skull Hunter's black hood, revealing the face beneath."
  },
  AvgDialog_18708_Content_7 = {
    Text = "High cheekbones, a hooked nose, and sunken cheeks—a completely unfamiliar face."
  },
  AvgDialog_18708_Content_8 = {
    Text = "You really know how to pick your targets, chasing me all the way here. Who exactly are you?"
  },
  AvgDialog_18708_Content_9 = {
    Text = "Ugh... Ah..."
  },
  AvgDialog_18709_Content_1 = {
    Text = "Bitter Rain"
  },
  AvgDialog_18709_Content_10 = {
    Text = "You prop yourself up against the bedhead, memories of recent events flashing before your eyes. Many issues remain to be resolved."
  },
  AvgDialog_18709_Content_11 = {
    Text = "Let's ask Miss Horla what she knows first."
  },
  AvgDialog_18709_Content_12 = {
    Text = "Ask Old Freeman"
  },
  AvgDialog_18709_Content_13 = {
    Text = "Old Freeman? So he's still alive..."
  },
  AvgDialog_18709_Content_14 = {
    Text = "I've heard the townsfolk say that he was an optimistic and cheerful person when he was young, and everyone liked him."
  },
  AvgDialog_18709_Content_15 = {
    Text = "After the <Yellow:plague>, he left Rainy Town and returned as a completely different person."
  },
  AvgDialog_18709_Content_16 = {Text = "Plague?"},
  AvgDialog_18709_Content_17 = {
    Text = "Three years ago, a Dissolution disaster occurred to the north of Rainy Town. Locals referred to it as a plague."
  },
  AvgDialog_18709_Content_18 = {
    Text = "It has now completely turned into a dead land."
  },
  AvgDialog_18709_Content_19 = {
    Text = "Ask Daffodil"
  },
  AvgDialog_18709_Content_2 = {Text = "..."},
  AvgDialog_18709_Content_20 = {
    Text = "Miss Horla, the tone you used when speaking of Daffodil just now... did you two know each other before?"
  },
  AvgDialog_18709_Content_21 = {
    Text = "Lady Daffodil..."
  },
  AvgDialog_18709_Content_22 = {
    Text = "Horla gazed at the book page in her hand, a faint smile playing on her face."
  },
  AvgDialog_18709_Content_23 = {
    Text = "Lady Daffodil, she... helped me."
  },
  AvgDialog_18709_Content_24 = {
    Text = "Year 15@1, San Pedro"
  },
  AvgDialog_18709_Content_25 = {
    Text = "This collection of Longsa's poems is one-of-a-kind. Be sure to treasure it."
  },
  AvgDialog_18709_Content_26 = {
    Text = "Many thanks, Lady Daffodil. I can't believe you actually found it..."
  },
  AvgDialog_18709_Content_27 = {
    Text = "\"May you forever retain the radiant beauty of a rose.\""
  },
  AvgDialog_18709_Content_28 = {
    Text = "Beautiful poetry. You have excellent taste."
  },
  AvgDialog_18709_Content_29 = {
    Text = "Yes, but I prefer \"I honor this moment with milk and flowers...\""
  },
  AvgDialog_18709_Content_3 = {
    Text = "You finally woke up, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_18709_Content_30 = {
    Text = "Ah... Sorry, I got sidetracked again."
  },
  AvgDialog_18709_Content_31 = {
    Text = "I know the rules of the \"Exchange Shop.\" So, what do you want from me?"
  },
  AvgDialog_18709_Content_32 = {
    Text = "Hmm... I'll have to observe you closely, my little rose."
  },
  AvgDialog_18709_Content_33 = {
    Text = "The gaze swept over Horla's entire body without emotion. The girl involuntarily straightened her back."
  },
  AvgDialog_18709_Content_34 = {
    Text = [[
Can you share a memory with me?  
Painful, sad... any unhappy memory will do.]]
  },
  AvgDialog_18709_Content_35 = {
    Text = "Unhappy memories? Th-That's not a good thing. What do you plan to do with them...?"
  },
  AvgDialog_18709_Content_36 = {
    Text = "I plan to use it for a small experiment. You'll know then."
  },
  AvgDialog_18709_Content_37 = {
    Text = "Days of relentless exhaustion eroded your nerves; you drift into sleep to Horla's soft words."
  },
  AvgDialog_18709_Content_38 = {Text = "..."},
  AvgDialog_18709_Content_39 = {
    Text = "After an unknown amount of time, a light drizzle began outside the window."
  },
  AvgDialog_18709_Content_4 = {
    Text = "I remember I seemed to faint, and then..."
  },
  AvgDialog_18709_Content_40 = {
    Text = "Someone is trudging slowly and endlessly through the muddy road in the rain."
  },
  AvgDialog_18709_Content_41 = {
    Text = "They only appear on rainy nights, their footsteps concealed by the rain, quietly creeping up behind you..."
  },
  AvgDialog_18709_Content_42 = {
    Text = "The Skull Hunters are neither one person nor two. The Skull Hunters are an organization."
  },
  AvgDialog_18709_Content_43 = {
    Text = "A rainy night, alone... <Red:Isn't this your current situation?>"
  },
  AvgDialog_18709_Content_44 = {
    Text = "<Red:Zzz... Krr...>"
  },
  AvgDialog_18709_Content_45 = {
    Text = "<RedBig:Snap!>"
  },
  AvgDialog_18709_Content_46 = {Text = "?!"},
  AvgDialog_18709_Content_47 = {
    Text = "A pale bolt of lightning pierces the stillness of the night. You abruptly open your eyes in the darkness."
  },
  AvgDialog_18709_Content_48 = {
    Text = "Someone is standing by your bed."
  },
  AvgDialog_18709_Content_49 = {
    Text = "The heavy gaze feels like a cold, damp sickle tracing your limbs, back, and..."
  },
  AvgDialog_18709_Content_5 = {
    Text = "Yes, it was the Lady Daffodil who brought you back and instructed me to take good care of you."
  },
  AvgDialog_18709_Content_50 = {
    Text = "An unprotected neck."
  },
  AvgDialog_18709_Content_51 = {
    Text = "Head@1 Skull@4"
  },
  AvgDialog_18709_Content_54 = {Text = "Hmm...!!"},
  AvgDialog_18709_Content_55 = {
    Text = "You suddenly fall off the bed and instinctively cover your neck."
  },
  AvgDialog_18709_Content_56 = {
    Text = "A shadowy figure holding a scythe stands by the bed, almost blending into the dark night behind."
  },
  AvgDialog_18709_Content_57 = {
    Text = "The air is filled with the scent of rain and rust. Dark red blood drips from the cold, white blade, pooling on the floor."
  },
  AvgDialog_18709_Content_58 = {
    Text = "—It's the Skull Hunter."
  },
  AvgDialog_18709_Content_6 = {
    Text = "Daffodil...?"
  },
  AvgDialog_18709_Content_7 = {
    Text = "You catch a familiar scent."
  },
  AvgDialog_18709_Content_8 = {
    Text = "A slender-necked vase has appeared on the bedside table, with white narcissus flowers stretching their petals towards the sunlight."
  },
  AvgDialog_18709_Content_9 = {
    Text = "It's her scent..."
  },
  AvgDialog_18710_Content_1 = {
    Text = "Beast Kingdom"
  },
  AvgDialog_18710_Content_10 = {
    Text = "It was a clear summer night, and I was diligently carrying my \"spoils\" as usual."
  },
  AvgDialog_18710_Content_11 = {
    Text = "<Shake:Heads... more heads...>"
  },
  AvgDialog_18710_Content_12 = {
    Text = "Tap. Tap. Tap."
  },
  AvgDialog_18710_Content_13 = {
    Text = "The sound of light footsteps approached quietly, and a gentle voice came from above."
  },
  AvgDialog_18710_Content_14 = {
    Text = "Heh... Look what I've found? A stray little beast."
  },
  AvgDialog_18710_Content_15 = {
    Text = "That night, a woman came to me."
  },
  AvgDialog_18710_Content_16 = {
    Text = [[
When she approached me, I caught a pleasant fragrance.
It was the scent of flowers and mist.]]
  },
  AvgDialog_18710_Content_17 = {
    Text = "This is the scent of another world, as different from my kingdom as day is from night, never meant to intersect."
  },
  AvgDialog_18710_Content_18 = {
    Text = "But she still trudged through the foul-smelling sludge, walked through the city's shadows, and reached out to me."
  },
  AvgDialog_18710_Content_19 = {
    Text = "She said..."
  },
  AvgDialog_18710_Content_2 = {
    Text = [[
I am a beast... I am a patient.

I am beyond redemption.]]
  },
  AvgDialog_18710_Content_20 = {
    Text = "Would you like to come with me, little beast?"
  },
  AvgDialog_18710_Content_21 = {
    Text = "5:00, North of Rainy Town"
  },
  AvgDialog_18710_Content_22 = {
    Text = "This place is... truly desolate."
  },
  AvgDialog_18710_Content_23 = {
    Text = "Three years ago, an <Yellow:S-Class D-Rift> appeared here. Water, vegetation... the entire ecosystem suffered severe damage."
  },
  AvgDialog_18710_Content_24 = {
    Text = "Fortunately, there were few casualties, and the residents were evacuated under the Committee's arrangement."
  },
  AvgDialog_18710_Content_25 = {
    Text = "You gaze at the desolate walls and the pale, withered trees ahead."
  },
  AvgDialog_18710_Content_26 = {
    Text = "If not for the Dissolution, this would be a green field in full bloom with lilacs. When the wind blows, the grass ripples like waves, resembling a green ocean."
  },
  AvgDialog_18710_Content_27 = {
    Text = "Are you sure the Skull Hunter is here, Lady Daffodil?"
  },
  AvgDialog_18710_Content_28 = {
    Text = "The only response is the hoarse cawing of crows."
  },
  AvgDialog_18710_Content_29 = {
    Text = "Oh, Lady Daffodil is missing?"
  },
  AvgDialog_18710_Content_3 = {
    Text = "During the day, I hide in the city's shadows, lying on my back with my belly up, sleeping soundly."
  },
  AvgDialog_18710_Content_30 = {
    Text = "Well, the consequences of trusting others."
  },
  AvgDialog_18710_Content_31 = {
    Text = "Ahem. She is always so unpredictable in her movements; I've long since gotten used to it."
  },
  AvgDialog_18710_Content_32 = {
    Text = "No worries, I can investigate myself. I'll definitely find something here..."
  },
  AvgDialog_18710_Content_33 = {
    Text = "<Big:Boom—!!>"
  },
  AvgDialog_18710_Content_34 = {
    Text = "Thunder rumbles in the low-hanging clouds, and dry leaves rustle in the autumn wind."
  },
  AvgDialog_18710_Content_35 = {
    Text = "This is a sign of rain."
  },
  AvgDialog_18710_Content_36 = {
    Text = "Why does it only appear on rainy days?"
  },
  AvgDialog_18710_Content_37 = {
    Text = "Because when it rains, blood and rain mix and flow into the sewers."
  },
  AvgDialog_18710_Content_38 = {
    Text = "Yes, it flows into the sewers, coffins, and the small gutters around you..."
  },
  AvgDialog_18710_Content_39 = {
    Text = "<Red:Zzz... Krr...>"
  },
  AvgDialog_18710_Content_4 = {
    Text = "At night, I wander the streets like a phantom, searching for one head after another."
  },
  AvgDialog_18710_Content_40 = {
    Text = "A rainy, dark night... No, I'm daydreaming again."
  },
  AvgDialog_18710_Content_41 = {
    Text = "You shook your head vigorously, trying to clear the chaos from your mind."
  },
  AvgDialog_18710_Content_42 = {
    Text = "Time is running out. You must act quickly."
  },
  AvgDialog_18710_Content_5 = {
    Text = "<Red:Heads. Heads. Heads.>"
  },
  AvgDialog_18710_Content_6 = {
    Text = [[
<RedBig:Heads.
        Heads.
                Heads.
                        Heads.
                                Heads.
                                        Heads...>]]
  },
  AvgDialog_18710_Content_7 = {
    Text = [[
My mind can no longer contemplate survival, love, and dignity.

It has long been filled to the brim with those insatiable fantasies.]]
  },
  AvgDialog_18710_Content_8 = {
    Text = "I am beyond redemption."
  },
  AvgDialog_18710_Content_9 = {
    Text = "Year 15@1, San Pedro City"
  },
  AvgDialog_18711_Content_1 = {Text = "Ahhhh—!!"},
  AvgDialog_18711_Content_10 = {
    Text = "She ignored the filthy slime and blood on the ground, squatted down, and stared at the struggling creature before her."
  },
  AvgDialog_18711_Content_11 = {
    Text = "Stop searching. They're gone and will never come back."
  },
  AvgDialog_18711_Content_12 = {
    Text = "What you need is not these things."
  },
  AvgDialog_18711_Content_13 = {
    Text = "No need...? No, Head@1, give it to me..."
  },
  AvgDialog_18711_Content_14 = {Text = "..."},
  AvgDialog_18711_Content_15 = {
    Text = [[
Did you know? Actually... we're the same.
I understand your pain.]]
  },
  AvgDialog_18711_Content_16 = {
    Text = "Year 15@1, San Pedro City"
  },
  AvgDialog_18711_Content_17 = {
    Text = "Will you come with me, little beast? You need help."
  },
  AvgDialog_18711_Content_18 = {
    Text = "Year 15@1 In the summer of the first year, a woman extended her hand to me."
  },
  AvgDialog_18711_Content_19 = {
    Text = "Perhaps it's her pleasant scent, or perhaps she just appears gentle."
  },
  AvgDialog_18711_Content_2 = {
    Text = "A mass of flesh collapses, pouring out D-Slime and gray mucus, revealing Harriet's frail body."
  },
  AvgDialog_18711_Content_20 = {
    Text = "In short, I didn't turn her down."
  },
  AvgDialog_18711_Content_21 = {
    Text = "I naively grasped her hand, and with it, my future fate."
  },
  AvgDialog_18711_Content_22 = {
    Text = "Cough... Cough..."
  },
  AvgDialog_18711_Content_23 = {
    Text = "You're dying, Daffodil."
  },
  AvgDialog_18711_Content_24 = {
    Text = "Silly child... After all these years, you still haven't learned to speak properly."
  },
  AvgDialog_18711_Content_25 = {
    Text = "Don't cry... *cough*..."
  },
  AvgDialog_18711_Content_26 = {
    Text = "<Shake:I... I didn't...>"
  },
  AvgDialog_18711_Content_27 = {
    Text = "Take my head. I entrust you with my identity, appearance, and this small shop."
  },
  AvgDialog_18711_Content_28 = {Text = "?!"},
  AvgDialog_18711_Content_29 = {
    Text = "I know, cough cough... you've always yearned to walk the world like an ordinary human."
  },
  AvgDialog_18711_Content_3 = {
    Text = "Grayish-white skulls surged forth, only to vanish in the blink of an eye."
  },
  AvgDialog_18711_Content_30 = {
    Text = "You hide in the corner, observing how I talk and walk. When I'm away, you secretly wear my clothes and even pretend to be me to make friends..."
  },
  AvgDialog_18711_Content_31 = {
    Text = "I always knew."
  },
  AvgDialog_18711_Content_32 = {
    Text = "Sorry, Daffodil, I didn't mean to..."
  },
  AvgDialog_18711_Content_33 = {
    Text = "Now, I will grant your wish, ahem... but you must promise me..."
  },
  AvgDialog_18711_Content_34 = {
    Text = "In the future, do not casually sever the heads of the innocent. If you encounter someone like yourself, you must help them."
  },
  AvgDialog_18711_Content_35 = {
    Text = "Just like I'm helping you now."
  },
  AvgDialog_18711_Content_36 = {
    Text = "<Shake:Save me, save me...>"
  },
  AvgDialog_18711_Content_37 = {
    Text = "Harriet lets out a beast-like wail and tremblingly reaches out to Lady Daffodil."
  },
  AvgDialog_18711_Content_38 = {Text = "..."},
  AvgDialog_18711_Content_39 = {
    Text = "Back then... when you saw your husband in the graveyard, you must have felt utterly hopeless, right?"
  },
  AvgDialog_18711_Content_4 = {
    Text = "Head@1... No..."
  },
  AvgDialog_18711_Content_40 = {
    Text = "Freeman... Huh.@2..."
  },
  AvgDialog_18711_Content_41 = {
    Text = "We bear the same curse, but I am much luckier than you."
  },
  AvgDialog_18711_Content_42 = {
    Text = "When I didn't yet know the difference between good and evil, it was that lady who reached out to me."
  },
  AvgDialog_18711_Content_43 = {
    Text = "Daffodil knelt before Mrs. Harriet, gently holding her scarred and D-Slime-covered hand."
  },
  AvgDialog_18711_Content_44 = {
    Text = "I learned to talk and walk like her, shaping myself into her image."
  },
  AvgDialog_18711_Content_45 = {
    Text = "Watch out, Lady Daffodil! Harriet's hands are covered in D-Slime—"
  },
  AvgDialog_18711_Content_46 = {
    Text = "Shh... I still have something to say to her."
  },
  AvgDialog_18711_Content_47 = {
    Text = "Daffodil continued to gaze at Harriet. A secret connection flowed between them, isolating them from all distractions."
  },
  AvgDialog_18711_Content_48 = {
    Text = "Now I can finally reach out to others, just as she did... But it's too late."
  },
  AvgDialog_18711_Content_49 = {
    Text = "Pale purple smoke gradually rises, slowly drifting in the dim room."
  },
  AvgDialog_18711_Content_5 = {
    Text = "Harriet, headless and uneasy, writhed as the veins in her neck pulsed rapidly, emitting a faint hum."
  },
  AvgDialog_18711_Content_50 = {
    Text = "You catch that familiar floral scent again, mingled with the dampness of midnight mist, diluting the room's heavy blood odor."
  },
  AvgDialog_18711_Content_51 = {
    Text = "Daffodil gently placed her hand beside Mrs. Harriet."
  },
  AvgDialog_18711_Content_52 = {
    Text = "Rest assured, Lady Harriet. You won't feel any pain."
  },
  AvgDialog_18711_Content_53 = {
    Text = "A rift swiftly tears open from her palm, slowly engulfing Harriet..."
  },
  AvgDialog_18711_Content_54 = {
    Text = "<Shake:...>"
  },
  AvgDialog_18711_Content_55 = {
    Text = "Tell my husband@2 to stop drinking."
  },
  AvgDialog_18711_Content_56 = {
    Text = "There's more..."
  },
  AvgDialog_18711_Content_57 = {
    Text = "Harriet's exposed throat trembled slightly, but finally fell silent like a wilted leaf."
  },
  AvgDialog_18711_Content_58 = {
    Text = "She released Daffodil's hand and silently plummeted into a fathomless dimensional rift."
  },
  AvgDialog_18711_Content_59 = {
    Text = "<Change>Farewell, farewell..."
  },
  AvgDialog_18711_Content_6 = {
    Text = "Give me the @2, give me the head..."
  },
  AvgDialog_18711_Content_60 = {
    Text = "Finally... Is it over? Where did you take her, Lady Daffodil?"
  },
  AvgDialog_18711_Content_61 = {
    Text = "The Primal Ocean. She will have a long time to remember... or forget everything that happened."
  },
  AvgDialog_18711_Content_62 = {
    Text = "Lady Harriet..."
  },
  AvgDialog_18711_Content_63 = {
    Text = "Before you can gather your scattered thoughts, faint footsteps echo outside the house."
  },
  AvgDialog_18711_Content_64 = {
    Text = "Who's there? Let's follow and take a look."
  },
  AvgDialog_18711_Content_65 = {
    Text = "Yes, it's me... hic."
  },
  AvgDialog_18711_Content_66 = {
    Text = "Long time no see, little detective! Do you remember me, the gravekeeper Old Freeman?"
  },
  AvgDialog_18711_Content_67 = {
    Text = "Old Freeman, holding a bottle of brandy, kept burping with an awkward smile on his face."
  },
  AvgDialog_18711_Content_68 = {
    Text = "Old Freeman?! What are you doing here... Did you hear everything?"
  },
  AvgDialog_18711_Content_69 = {Text = "I..."},
  AvgDialog_18711_Content_7 = {
    Text = "She crawled anxiously on the ground, her bony arms flailing. Like a cornered beast, she let out desperate moans from her throat."
  },
  AvgDialog_18711_Content_70 = {
    Text = "I don't know what happened either. I slept like a log after drinking."
  },
  AvgDialog_18711_Content_71 = {
    Text = "I can't recall what happened in the middle, but somehow I ended up here in a daze."
  },
  AvgDialog_18711_Content_72 = {
    Text = "Then I heard some noise inside... Don't worry, I didn't take a single peek!"
  },
  AvgDialog_18711_Content_73 = {
    Text = [[
Old Freeman suddenly leaned in and gave you a mysterious wink.
You didn't dodge in time and caught a strong whiff of the pungent smell of smoke and alcohol.]]
  },
  AvgDialog_18711_Content_74 = {
    Text = "You killed that Skull Hunter, right?"
  },
  AvgDialog_18711_Content_75 = {
    Text = "Not great, but close enough. No one will disturb your sleep from now on."
  },
  AvgDialog_18711_Content_76 = {
    Text = "You pinch your nose, take three steps back, and nod perfunctorily."
  },
  AvgDialog_18711_Content_77 = {Text = "Oh..."},
  AvgDialog_18711_Content_78 = {
    Text = "Old Freeman rubbed his messy hair, a hint of confusion flashing in his eyes."
  },
  AvgDialog_18711_Content_79 = {
    Text = "Pretty good, pretty good..."
  },
  AvgDialog_18711_Content_8 = {Text = "..."},
  AvgDialog_18711_Content_80 = {
    Text = "Mr. Freeman. From now on... no more drinking."
  },
  AvgDialog_18711_Content_81 = {
    Text = "Quit drinking? No, no, no... I'd rather die."
  },
  AvgDialog_18711_Content_82 = {
    Text = "This is a request from a friend. She has gone far, far away... but she still cares about you."
  },
  AvgDialog_18711_Content_83 = {
    Text = "Friends? Heh, don't kid yourself. Old Freeman doesn't have any friends..."
  },
  AvgDialog_18711_Content_84 = {
    Text = "He waved you off dismissively, muttering as he staggered away."
  },
  AvgDialog_18711_Content_85 = {
    Text = [[
He looks so down. What a pity...
He will never know why he feels this way.]]
  },
  AvgDialog_18711_Content_86 = {
    Text = "It's almost as if he doesn't understand why he's here."
  },
  AvgDialog_18711_Content_87 = {
    Text = "This must be what Mrs. Harriet had hoped for."
  },
  AvgDialog_18711_Content_88 = {
    Text = "Don't tell him anything... He can continue drinking, singing, and drifting through life like this."
  },
  AvgDialog_18711_Content_89 = {
    Text = "In a way, this is also a kind of luck. A human's life is very short..."
  },
  AvgDialog_18711_Content_9 = {
    Text = "Daffodil let out a soft sigh, her eyes shimmering with unspoken sorrow."
  },
  AvgDialog_18711_Content_90 = {
    Text = "You watch Old Freeman depart."
  },
  AvgDialog_18711_Content_91 = {
    Text = "A hunched figure trembles in the bleak wind, growing smaller and smaller, farther and farther away..."
  },
  AvgDialog_18711_Content_92 = {
    Text = "Until completely swallowed by the distant horizon."
  },
  AvgDialog_18711_Content_93 = {
    Text = "Then you see a faint ray of dawn piercing through the mist, gradually illuminating the sky."
  },
  AvgDialog_18711_Content_94 = {
    Text = "The rain has stopped... Daffodil."
  },
  AvgDialog_18712_Content_1 = {
    Text = "Shadow Hymn"
  },
  AvgDialog_18712_Content_10 = {
    Text = "Give it to me... <Big:Return it to me>!"
  },
  AvgDialog_18712_Content_11 = {
    Text = "Black tendrils continuously extend from its neck, greedily absorbing the fallen heads into its body."
  },
  AvgDialog_18712_Content_12 = {
    Text = "With each skull it devours, its size increases further."
  },
  AvgDialog_18712_Content_13 = {
    Text = "The last thing standing before you is a massive pile of stacked flesh."
  },
  AvgDialog_18712_Content_14 = {
    Text = "<Bold:—!!!>"
  },
  AvgDialog_18712_Content_15 = {
    Text = "These heads... I've seen them before."
  },
  AvgDialog_18712_Content_16 = {
    Text = "You've seen some of them in the files the police gave you, in those cold, lined-up victim photos."
  },
  AvgDialog_18712_Content_17 = {
    Text = "You've seen them."
  },
  AvgDialog_18712_Content_18 = {
    Text = "Now you understand, there was never any Skull Hunters organization."
  },
  AvgDialog_18712_Content_19 = {
    Text = "<Yellow:From start to finish, the Skull Hunter has always been alone.>"
  },
  AvgDialog_18712_Content_2 = {
    Text = "Lady Daffodil...?!"
  },
  AvgDialog_18712_Content_20 = {
    Text = "<RedShake:Not enough...>"
  },
  AvgDialog_18712_Content_21 = {
    Text = "<RedShake:Not enough... not enough...>"
  },
  AvgDialog_18712_Content_22 = {
    Text = "A swollen body embedded with countless heads expressing pain and wailing, rising and falling with the soft fat..."
  },
  AvgDialog_18712_Content_23 = {
    Text = "Such familiar spirit waves... Could it be the Thousand-Mirages?!"
  },
  AvgDialog_18712_Content_24 = {
    Text = "It is a power that originates from the same source as the Thousand-Mirages, which is why I can sense her location."
  },
  AvgDialog_18712_Content_25 = {
    Text = [[
Now it's completely out of control and continues to grow.
We must act quickly.]]
  },
  AvgDialog_18712_Content_26 = {Text = "So..."},
  AvgDialog_18712_Content_27 = {
    Text = "Daffodil suddenly leaned in, grasping the Silver Key on your chest."
  },
  AvgDialog_18712_Content_28 = {
    Text = "Would you like to team up with me, %player%?"
  },
  AvgDialog_18712_Content_29 = {
    Text = "Oh, you want to Link with me?"
  },
  AvgDialog_18712_Content_3 = {
    Text = "Sorry... I deliberately left you here to lure it out. You must be blaming me in your heart, right?"
  },
  AvgDialog_18712_Content_30 = {
    Text = "After all this time working together, I thought we would have some understanding by now."
  },
  AvgDialog_18712_Content_31 = {
    Text = "Or... are you not confident that you can handle me?"
  },
  AvgDialog_18712_Content_32 = {
    Text = "Heh... Shall we give it a shot?"
  },
  AvgDialog_18712_Content_33 = {
    Text = "You close your eyes and focus, urging the Silver Key on your chest."
  },
  AvgDialog_18712_Content_34 = {
    Text = "Soon, the Silver Key begins to emit a continuous, weak vibration, and the cold white glimmer rapidly engulfs the entire darkroom."
  },
  AvgDialog_18712_Content_35 = {
    Text = "You feel as if you are in an immense sea of time."
  },
  AvgDialog_18712_Content_36 = {
    Text = "Strange energy surges in your chest, a torrent crossing dimensions."
  },
  AvgDialog_18712_Content_37 = {
    Text = [[
Across the vast sea of time, Daffodil quietly gazes at you.
At this moment, a subtle and unfamiliar expression appears on her face.]]
  },
  AvgDialog_18712_Content_38 = {
    Text = "That is an absolute, unquestionable confidence honed over hundreds of years through countless confrontations and battles."
  },
  AvgDialog_18712_Content_39 = {
    Text = "Let's set off, %player%. I'm all prepared."
  },
  AvgDialog_18712_Content_4 = {Text = "..."},
  AvgDialog_18712_Content_5 = {
    Text = "We'll settle this once we get out."
  },
  AvgDialog_18712_Content_6 = {
    Text = "<Shake:My head... Give it back...>"
  },
  AvgDialog_18712_Content_7 = {
    Text = "\"Harriet\" staggered forward two steps, reaching futilely above her neck."
  },
  AvgDialog_18712_Content_8 = {
    Text = "One hit, two hits..."
  },
  AvgDialog_18712_Content_9 = {
    Text = "Realizing her head was already gone, she let out a series of piercing screams."
  },
  AvgDialog_18713_Content_1 = {
    Text = "It's raining."
  },
  AvgDialog_18713_Content_10 = {
    Text = "You hastily wipe the rain off your face and blink, only to realize that someone is actually talking to you."
  },
  AvgDialog_18713_Content_11 = {
    Text = "I thought no one lived here anymore."
  },
  AvgDialog_18713_Content_12 = {
    Text = "Most people have moved away."
  },
  AvgDialog_18713_Content_13 = {
    Text = "Those who were sick or elderly chose to stay, while some went outside and then came back..."
  },
  AvgDialog_18713_Content_14 = {
    Text = "Not everyone can adapt to life outside."
  },
  AvgDialog_18713_Content_15 = {
    Text = "I see. But I didn't see anyone just now."
  },
  AvgDialog_18713_Content_16 = {
    Text = "...They hate dealing with outsiders."
  },
  AvgDialog_18713_Content_17 = {
    Text = "You look around at the sparse, dilapidated houses."
  },
  AvgDialog_18713_Content_18 = {
    Text = "Through the pitch-black windows, silent gazes can be faintly seen, brimming with caution and hostility."
  },
  AvgDialog_18713_Content_19 = {
    Text = "Hello, ma'am. May I ask you—"
  },
  AvgDialog_18713_Content_2 = {
    Text = "You walk alone in the rain, cold and wet water soaking your clothes and clinging to your skin."
  },
  AvgDialog_18713_Content_20 = {
    Text = "Have you seen anything strange?"
  },
  AvgDialog_18713_Content_21 = {
    Text = "Strange things...?"
  },
  AvgDialog_18713_Content_22 = {
    Text = "Uh... whether it's a person or a beast, it moves extremely fast."
  },
  AvgDialog_18713_Content_23 = {
    Text = "The woman shook her head."
  },
  AvgDialog_18713_Content_24 = {
    Text = "It has been a long time since anyone came here; even the vultures refuse to come close."
  },
  AvgDialog_18713_Content_25 = {
    Text = "Have you seen Daffodil?"
  },
  AvgDialog_18713_Content_26 = {
    Text = "Have you seen a beautiful lady in a purple long dress?"
  },
  AvgDialog_18713_Content_27 = {
    Text = "The woman shook her head."
  },
  AvgDialog_18713_Content_28 = {
    Text = "It has been a long time since anyone came here; even the vultures refuse to come close."
  },
  AvgDialog_18713_Content_29 = {
    Text = "<Big:Boom—>"
  },
  AvgDialog_18713_Content_3 = {
    Text = "You walk through one abandoned house after another, passing by one grave after another."
  },
  AvgDialog_18713_Content_30 = {
    Text = "The rain is falling harder, turning everything gray."
  },
  AvgDialog_18713_Content_31 = {
    Text = "The woman's figure begins to blur and lose focus, and even her voice grows increasingly faint..."
  },
  AvgDialog_18713_Content_32 = {
    Text = "Come in, {Male=sir,Female=miss}. You'll catch a cold in this heavy rain..."
  },
  AvgDialog_18713_Content_33 = {Text = "..."},
  AvgDialog_18713_Content_34 = {
    Text = "With pleasure."
  },
  AvgDialog_18713_Content_4 = {
    Text = "Wherever they go, there are only scars and desolation."
  },
  AvgDialog_18713_Content_5 = {
    Text = "Only rain. Unending, cold rain accompanies you all the way."
  },
  AvgDialog_18713_Content_6 = {Text = "Keeper..."},
  AvgDialog_18713_Content_7 = {
    Text = "An elderly woman stands in front of the cabin, waving to you."
  },
  AvgDialog_18713_Content_8 = {
    Text = "She wore a dull dress, her face concealed in the gray rain, blending seamlessly with the dilapidated house behind her."
  },
  AvgDialog_18713_Content_9 = {
    Text = "{Male=Sir,Female=Miss}, you look very cold... Would you like to come in and take a seat?"
  },
  AvgDialog_18714_Content_1 = {
    Text = "Stormbreach"
  },
  AvgDialog_18714_Content_10 = {
    Text = "A single person?!"
  },
  AvgDialog_18714_Content_11 = {
    Text = "Oh dear, you look terrible. Need some help?"
  },
  AvgDialog_18714_Content_12 = {
    Text = "You step back. I have something to ask you."
  },
  AvgDialog_18714_Content_13 = {
    Text = "That's really hurtful. What, am I giving off some kind of unpleasant smell?"
  },
  AvgDialog_18714_Content_14 = {
    Text = "I don't know... Perhaps the scent of the dead?"
  },
  AvgDialog_18714_Content_15 = {
    Text = "Beren Stock, Dwight Williams... Do these names sound familiar?"
  },
  AvgDialog_18714_Content_16 = {Text = "..."},
  AvgDialog_18714_Content_17 = {
    Text = "I see, you suspect I'm the Skull Hunter."
  },
  AvgDialog_18714_Content_18 = {
    Text = "And you clearly know the names of the victims of the Skull Hunter."
  },
  AvgDialog_18714_Content_19 = {Text = "..."},
  AvgDialog_18714_Content_2 = {
    Text = "Daffodil strolls towards you with an air of casual elegance, as if she were here on vacation."
  },
  AvgDialog_18714_Content_20 = {
    Text = "I thought we've built a bit of mutual trust after Rye."
  },
  AvgDialog_18714_Content_21 = {
    Text = "The Skull Hunter took a <Yellow:precious skull> from me, so I'm just conducting a small investigation. It's as simple as that."
  },
  AvgDialog_18714_Content_22 = {
    Text = "Whose precious head... could this be?"
  },
  AvgDialog_18714_Content_23 = {Text = "..."},
  AvgDialog_18714_Content_24 = {
    Text = "Daffodil smiles at you. She always puts on this smile when she doesn't want to answer others' questions."
  },
  AvgDialog_18714_Content_25 = {
    Text = "If I remember correctly, you've always had a habit of collecting heads. Rainy Town is less than 15 miles away from Rye in a straight line, making the round trip quite convenient."
  },
  AvgDialog_18714_Content_26 = {
    Text = "Sorry, I only collect heads, not produce them."
  },
  AvgDialog_18714_Content_27 = {
    Text = "There is a subtle difference between the two... I believe you can understand, our smart Keeper?"
  },
  AvgDialog_18714_Content_28 = {
    Text = [[
Sure, I understand.
So, where were you and what were you doing at 8:15 last night?]]
  },
  AvgDialog_18714_Content_29 = {
    Text = "Let me think... The shop received a new batch of bath salts, so I tried them in the bathtub."
  },
  AvgDialog_18714_Content_3 = {
    Text = "It's you...?"
  },
  AvgDialog_18714_Content_30 = {
    Text = "Well, want to hear the details of my trial?"
  },
  AvgDialog_18714_Content_31 = {
    Text = "Is that so? But when I saw you last night, you were standing alone under the streetlight, holding a human head."
  },
  AvgDialog_18714_Content_32 = {
    Text = "It doesn't look like bath salts at all."
  },
  AvgDialog_18714_Content_33 = {Text = "..."},
  AvgDialog_18714_Content_34 = {
    Text = "Are you saying... you saw someone who looks exactly like me last night?"
  },
  AvgDialog_18714_Content_35 = {
    Text = "You recall seeing Daffodil last night."
  },
  AvgDialog_18714_Content_36 = {
    Text = "No doubt, their appearances are almost identical, but their demeanor and aura are vastly different."
  },
  AvgDialog_18714_Content_37 = {
    Text = "Or rather, I saw <Yellow:you>, not someone who looks exactly like you."
  },
  AvgDialog_18714_Content_38 = {
    Text = "All the unfavorable evidence now points to you, and I have every reason to suspect you."
  },
  AvgDialog_18714_Content_39 = {
    Text = "Hmm, your suspicion is indeed well-founded."
  },
  AvgDialog_18714_Content_4 = {
    Text = "Oh dear, someone seems unwilling to see me?"
  },
  AvgDialog_18714_Content_40 = {Text = "..."},
  AvgDialog_18714_Content_41 = {
    Text = "Don't you have anything to explain?"
  },
  AvgDialog_18714_Content_42 = {
    Text = "Daffodil looked at you in surprise, as if you had asked a ridiculous question."
  },
  AvgDialog_18714_Content_43 = {
    Text = "Explain? Sorry, I don't need to explain anything to anyone."
  },
  AvgDialog_18714_Content_44 = {
    Text = "She walks gracefully towards you."
  },
  AvgDialog_18714_Content_45 = {
    Text = "The wide skirt rustles the dead leaves, while purple smoke coils like tendrils around."
  },
  AvgDialog_18714_Content_46 = {
    Text = "The next second, she vanishes into thin air before your eyes."
  },
  AvgDialog_18714_Content_47 = {
    Text = "The low-hanging clouds completely block the sunlight, making you feel as if you're in a gray dream, with Daffodil's whispers lingering in your ears—"
  },
  AvgDialog_18714_Content_48 = {
    Text = "Since you think I'm the \"Skull Hunter\"... what's next? What do you plan to do to me?"
  },
  AvgDialog_18714_Content_49 = {
    Text = "Or rather... what can you do to me?"
  },
  AvgDialog_18714_Content_5 = {
    Text = "The desolate autumn wind blows from behind you. You turn around, but there's nothing in front of you; Old Freeman has long since vanished."
  },
  AvgDialog_18714_Content_6 = {
    Text = "Thinking back on everything that just happened, it was like a nightmare."
  },
  AvgDialog_18714_Content_7 = {
    Text = "Mr. Freeman...?"
  },
  AvgDialog_18714_Content_8 = {
    Text = "Hmm, you brought a companion? Is it that girl who always looks so serious?"
  },
  AvgDialog_18714_Content_9 = {
    Text = "Just now, you were standing here alone, completely still, as if possessed."
  },
  AvgDialog_18715_Content_1 = {
    Text = "I concede, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_18715_Content_10 = {
    Text = "You plunge into a sea of gray primordial essence."
  },
  AvgDialog_18715_Content_11 = {
    Text = "The daylight stings your eyes, revealing an endless expanse of gray ocean."
  },
  AvgDialog_18715_Content_12 = {
    Text = "The surging gray waves shimmer with a glittering light, dotted with countless black specks."
  },
  AvgDialog_18715_Content_13 = {
    Text = "As your vision gradually adjusts, you realize it's not a black spot, but just a skull."
  },
  AvgDialog_18715_Content_14 = {
    Text = "Countless heads are submerged in the gray sea, rising and falling with the waves. They cry out and wail, drowning in immense sorrow and fear."
  },
  AvgDialog_18715_Content_15 = {
    Text = "<Change>Crystals, crystals..."
  },
  AvgDialog_18715_Content_16 = {
    Text = "<Shake:Don't touch that booklet, don't touch it...>"
  },
  AvgDialog_18715_Content_17 = {
    Text = "<Shake:San Pedro, let me return, let me return...>"
  },
  AvgDialog_18715_Content_18 = {
    Text = "Countless voices shriek in your ears, forcing you to cover them, as if thousands of needles were piercing your mind."
  },
  AvgDialog_18715_Content_19 = {
    Text = "Hmm... <Big:AAAAAHHH...!!>"
  },
  AvgDialog_18715_Content_2 = {
    Text = "Since I can't bear to see you get hurt, continuing this fight would just be a waste of everyone's time."
  },
  AvgDialog_18715_Content_20 = {
    Text = "Warm blood flows from your ears and nostrils, creating massive waves the moment it hits the water."
  },
  AvgDialog_18715_Content_21 = {
    Text = "The tide surges with anger and fear, carrying countless heads bobbing on its waves, rushing toward you."
  },
  AvgDialog_18715_Content_22 = {
    Text = "<Change>No, no..."
  },
  AvgDialog_18715_Content_23 = {
    Text = "<Shake:Intruders... Intruders!!>"
  },
  AvgDialog_18715_Content_24 = {
    Text = "You have no way out. Just close your eyes."
  },
  AvgDialog_18715_Content_25 = {Text = "Hmm...!"},
  AvgDialog_18715_Content_26 = {
    Text = "Cough... Cough..."
  },
  AvgDialog_18715_Content_27 = {
    Text = "Daffodil held her forehead and frowned at you."
  },
  AvgDialog_18715_Content_28 = {
    Text = "Out so soon...? I thought I could keep you trapped for at least a whole day."
  },
  AvgDialog_18715_Content_29 = {
    Text = "Looks like we're destined to be bound together, aren't we?"
  },
  AvgDialog_18715_Content_3 = {
    Text = "Given the irreconcilable differences between us, I suggest you stop bothering me."
  },
  AvgDialog_18715_Content_30 = {
    Text = "Head... it hurts..."
  },
  AvgDialog_18715_Content_31 = {
    Text = "What was that just now...? What kind of thing was it...?"
  },
  AvgDialog_18715_Content_32 = {
    Text = [[
This is my ultra-dimensional space. I've named it <Yellow:Thousand Mirage>.
What do you think? Isn't it fascinating?]]
  },
  AvgDialog_18715_Content_33 = {Text = "..."},
  AvgDialog_18715_Content_34 = {
    Text = "%player%, you're having a nosebleed. Wait, even your ears are bleeding..."
  },
  AvgDialog_18715_Content_35 = {
    Text = "<Shake:I'm alright... Stay away...>"
  },
  AvgDialog_18715_Content_36 = {
    Text = "It's not wise to act tough now; you can barely stand."
  },
  AvgDialog_18715_Content_37 = {
    Text = "*Cough cough*... don't come any closer..."
  },
  AvgDialog_18715_Content_38 = {
    Text = "Your vision goes black, and you collapse heavily to the ground."
  },
  AvgDialog_18715_Content_39 = {
    Text = "In the darkness, you seem to hear a familiar voice."
  },
  AvgDialog_18715_Content_4 = {
    Text = "Daffodil, with a cold expression, quickly drew a series of glowing purple runes in the air."
  },
  AvgDialog_18715_Content_40 = {
    Text = "Gentle, indifferent, wrapped in a slightly harsh electric buzz, appearing distant and vague."
  },
  AvgDialog_18715_Content_41 = {
    Text = "%player%, can you hear me now...<Red:Incorrect investigation direction>..."
  },
  AvgDialog_18715_Content_42 = {
    Text = [[
The Skull Hunter strikes again...
Three victims, all with their heads taken...]]
  },
  AvgDialog_18715_Content_43 = {
    Text = "Just a moment ago..."
  },
  AvgDialog_18715_Content_5 = {
    Text = "<Change>Thousand Mirage, activate."
  },
  AvgDialog_18715_Content_6 = {
    Text = "The world before your eyes suddenly transforms into fragmented reflections in water, gently flickering in front of you."
  },
  AvgDialog_18715_Content_7 = {
    Text = "You instinctively reach out, but are pulled into a deep vortex the moment you touch the reflections."
  },
  AvgDialog_18715_Content_8 = {Text = "AAAHHH—!"},
  AvgDialog_18715_Content_9 = {Text = "This is..."},
  AvgDialog_18716_Content_1 = {Text = "Aaahh—!!"},
  AvgDialog_18716_Content_10 = {
    Text = "The threads suddenly contracted, shattering the bedroom door as countless heads rolled out."
  },
  AvgDialog_18716_Content_11 = {
    Text = "When you come to your senses, a somewhat familiar head is already attached to Harriet's empty neck."
  },
  AvgDialog_18716_Content_12 = {
    Text = "This head... This face..."
  },
  AvgDialog_18716_Content_13 = {
    Text = "Beren Stock, the previous victim... What's going on?!"
  },
  AvgDialog_18716_Content_14 = {
    Text = "The pallid skull emits a stiff creaking sound and finally opens its unfocused eyes."
  },
  AvgDialog_18716_Content_15 = {
    Text = "The reborn \"Harriet\" grins and charges at you with an incredible speed."
  },
  AvgDialog_18716_Content_16 = {
    Text = "Aaaahhh—!!"
  },
  AvgDialog_18716_Content_18 = {
    Text = "The cold blade mercilessly slashes through the darkness."
  },
  AvgDialog_18716_Content_19 = {
    Text = "The next second, \"Harriet's\" head flew off gracefully and rolled beside her wide skirt."
  },
  AvgDialog_18716_Content_2 = {
    Text = "Harriet collapsed to the ground, emitting a piercing wail from deep within her throat."
  },
  AvgDialog_18716_Content_20 = {
    Text = "Whew... It seems I'm not too late."
  },
  AvgDialog_18716_Content_21 = {
    Text = "You're looking spirited, %player%."
  },
  AvgDialog_18716_Content_3 = {
    Text = "You step forward and grab her by the collar."
  },
  AvgDialog_18716_Content_4 = {
    Text = "Speak, who are your accomplices and where are they? Is Old Freeman one of them?"
  },
  AvgDialog_18716_Content_5 = {
    Text = "Freeman...? Heh... Hehehe..."
  },
  AvgDialog_18716_Content_6 = {
    Text = "Her face contorted violently, with countless pustules swelling beneath her thin skin, on the verge of bursting forth."
  },
  AvgDialog_18716_Content_7 = {
    Text = "Zzzzap—!!"
  },
  AvgDialog_18716_Content_8 = {
    Text = "Harriet's head was blown into a warm pulp."
  },
  AvgDialog_18716_Content_9 = {
    Text = "Her neck writhed continuously, with D-Slime mixed with blood forming thin threads that extended to the ceiling, walls, and floor..."
  },
  AvgDialog_18717_Content_1 = {Text = "Felin Muse"},
  AvgDialog_18717_Content_10 = {
    Text = "That was quite an interesting experience."
  },
  AvgDialog_18717_Content_11 = {
    Text = "The originally sorrowful memories, reinterpreted through imagery, unexpectedly acquired a comedic charm."
  },
  AvgDialog_18717_Content_12 = {
    Text = "I heard you later formed a film club called <Yellow:\"Felin Poetry Society\">?"
  },
  AvgDialog_18717_Content_13 = {
    Text = "Yes... Sometimes I help write scripts, though I've always been a terrible playwright."
  },
  AvgDialog_18717_Content_14 = {
    Text = "It was Lady Daffodil who helped me move on from the past, regardless of her true intentions."
  },
  AvgDialog_18717_Content_15 = {
    Text = "I've always been grateful to Lady Daffodil."
  },
  AvgDialog_18717_Content_16 = {
    Text = "I see, so that's what she told you."
  },
  AvgDialog_18717_Content_17 = {
    Text = "I am also deeply grateful to Miss Horla. It was a beautiful encounter."
  },
  AvgDialog_18717_Content_18 = {
    Text = "So, for Miss Horla's sake, I'll trust you this one time."
  },
  AvgDialog_18717_Content_19 = {
    Text = "<LightGray:Besides, the people sent by the school are already on their way.>"
  },
  AvgDialog_18717_Content_2 = {
    Text = "2:15, Kenting Street"
  },
  AvgDialog_18717_Content_20 = {
    Text = "<LightGray:If I'm gone for too long, they won't just sit idly by...>"
  },
  AvgDialog_18717_Content_21 = {
    Text = "Then let's set off, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_18717_Content_22 = {
    Text = "Daffodil nodded happily, extending her hand to you."
  },
  AvgDialog_18717_Content_23 = {Text = "..."},
  AvgDialog_18717_Content_24 = {
    Text = "You gently hold Daffodil's hand. Contrary to expectations, her hand is soft and warm."
  },
  AvgDialog_18717_Content_25 = {
    Text = "Hold tight, Keeper."
  },
  AvgDialog_18717_Content_26 = {
    Text = "Your footing falters, and you are pulled into a deep dimension."
  },
  AvgDialog_18717_Content_27 = {
    Text = "Welcome back to my \"Thousand-Mirage.\""
  },
  AvgDialog_18717_Content_28 = {
    Text = "Here is that familiar Sea of Primordial Essence again, with heads still bobbing along with the waves."
  },
  AvgDialog_18717_Content_29 = {
    Text = "Unlike last time, the heads seem much quieter now. Their hollow eye sockets all turn toward you, yet they continue to whisper among themselves."
  },
  AvgDialog_18717_Content_3 = {
    Text = "I didn't expect you to agree to come with me so readily. Aren't you worried that I might take you somewhere strange?"
  },
  AvgDialog_18717_Content_30 = {
    Text = "Daffodil waved her hand lightly, and two heads trembled as they floated to her eye level."
  },
  AvgDialog_18717_Content_31 = {
    Text = "<Change>My master..."
  },
  AvgDialog_18717_Content_32 = {
    Text = "<Change>Long time no see..."
  },
  AvgDialog_18717_Content_33 = {
    Text = "<Change>Help me find someone..."
  },
  AvgDialog_18717_Content_34 = {
    Text = "Daffodil and the skull are whispering in a language you can't understand. Whatever they discussed, it made her laugh happily."
  },
  AvgDialog_18717_Content_35 = {
    Text = "You've never seen her smile like that; it feels out of place."
  },
  AvgDialog_18717_Content_36 = {
    Text = "Instead, it traversed hundreds of years and landed in a corner of a story unknown to you."
  },
  AvgDialog_18717_Content_37 = {Text = "..."},
  AvgDialog_18717_Content_38 = {
    Text = "What's wrong? Is there something on my face?"
  },
  AvgDialog_18717_Content_39 = {
    Text = "You look delighted."
  },
  AvgDialog_18717_Content_4 = {
    Text = "So, will you... take me to strange places?"
  },
  AvgDialog_18717_Content_40 = {
    Text = "These are all my cherished collections."
  },
  AvgDialog_18717_Content_41 = {
    Text = "It has been a long time since I last returned. I miss them dearly."
  },
  AvgDialog_18717_Content_42 = {
    Text = "What are you talking about?"
  },
  AvgDialog_18717_Content_43 = {
    Text = "Past, present, and future."
  },
  AvgDialog_18717_Content_44 = {
    Text = "Each of these heads is a <Yellow:projection from reality>. Their vision and memory transcend the dimensions of time and space, helping me uncover many unexpected things."
  },
  AvgDialog_18717_Content_45 = {
    Text = "So that's why your shop has so many strange and unusual items...?"
  },
  AvgDialog_18717_Content_46 = {
    Text = "Daffodil blinked, tacitly agreeing with your guess."
  },
  AvgDialog_18717_Content_47 = {
    Text = "Where did all these heads come from?"
  },
  AvgDialog_18717_Content_48 = {
    Text = [[
Trading, gifting, and a bit of luck.
Of course, I also took some of it myself.]]
  },
  AvgDialog_18717_Content_49 = {
    Text = "It's said that you've hunted down as many as @1 heads—this is only the officially recorded number."
  },
  AvgDialog_18717_Content_5 = {Text = "Of course."},
  AvgDialog_18717_Content_50 = {
    Text = "Daffodil leisurely took a deep drag from her long pipe, then exhaled a wisp of white smoke."
  },
  AvgDialog_18717_Content_51 = {
    Text = "Sorry to disappoint you, {Male=Mr.,Female=Miss} Keeper, but moral rebukes don't affect me."
  },
  AvgDialog_18717_Content_52 = {
    Text = "The rules created by humans do not apply to us. What you see now is me, with eyes and a nose like yours..."
  },
  AvgDialog_18717_Content_53 = {
    Text = "Daffodil picked up the Silver Key on your chest, lightly tracing its intricate patterns."
  },
  AvgDialog_18717_Content_54 = {
    Text = "Chaotic buzzing and vibrations fill her chest, clashing fiercely like a silent war."
  },
  AvgDialog_18717_Content_55 = {
    Text = "Feel it? We're not human. We are \"beasts,\" or as some would call us..."
  },
  AvgDialog_18717_Content_56 = {
    Text = "We are <Yellow:higher beings>."
  },
  AvgDialog_18717_Content_57 = {
    Text = "We tolerate ignorant humans, we follow ever-changing rules, we obey fragile Links, all out of fear..."
  },
  AvgDialog_18717_Content_58 = {
    Text = "She gently strokes your face."
  },
  AvgDialog_18717_Content_59 = {
    Text = "And a promise."
  },
  AvgDialog_18717_Content_6 = {Text = "..."},
  AvgDialog_18717_Content_60 = {Text = "..."},
  AvgDialog_18717_Content_61 = {
    Text = "So you became one of the few registered Awakeners without any Links."
  },
  AvgDialog_18717_Content_62 = {
    Text = "No one is born to enjoy being controlled; most creatures inherently yearn for freedom."
  },
  AvgDialog_18717_Content_63 = {
    Text = "Personally, I don't dislike the so-called \"Link\"... As long as it's mutually beneficial, why bother with appearances?"
  },
  AvgDialog_18717_Content_64 = {
    Text = [[
The problem might not be with me.
No one links with me because they aren't qualified. Got it?]]
  },
  AvgDialog_18717_Content_65 = {Text = "Uh..."},
  AvgDialog_18717_Content_66 = {
    Text = "What about me? Am I also one of those \"unqualified\"...?"
  },
  AvgDialog_18717_Content_67 = {
    Text = "Daffodil burst into laughter, but choked on smoke and couldn't help coughing several times."
  },
  AvgDialog_18717_Content_68 = {
    Text = "Don't worry, kid... You'll know the answer soon."
  },
  AvgDialog_18717_Content_69 = {
    Text = "<LightGray:Another ambiguous answer...>"
  },
  AvgDialog_18717_Content_7 = {
    Text = "Actually... Miss Horla talked to me about your first meeting this afternoon. She said—"
  },
  AvgDialog_18717_Content_70 = {
    Text = "Oops, I might have said a bit too much."
  },
  AvgDialog_18717_Content_71 = {
    Text = "Daffodil raised her hand and tapped each forehead, causing them to obediently float away."
  },
  AvgDialog_18717_Content_72 = {
    Text = "<Change>Thank you all."
  },
  AvgDialog_18717_Content_73 = {
    Text = "Alright. Let's go, Keeper."
  },
  AvgDialog_18717_Content_74 = {
    Text = "I already know the location of the Skull Hunter."
  },
  AvgDialog_18717_Content_8 = {
    Text = "I later found out that she had turned that memory into something called a \"movie.\""
  },
  AvgDialog_18717_Content_9 = {
    Text = "I sat in the audience and watched the first movie of my life."
  },
  AvgDialog_18718_Content_1 = {
    Text = "A Solitary Reunion"
  },
  AvgDialog_18718_Content_10 = {
    Text = [[
This is my home.
I have no other place to go besides here.]]
  },
  AvgDialog_18718_Content_11 = {
    Text = "For people like us from the countryside, it's all the same no matter where we go."
  },
  AvgDialog_18718_Content_12 = {
    Text = "Lady Harriet..."
  },
  AvgDialog_18718_Content_13 = {
    Text = "The atmosphere inside the house grew somewhat heavy."
  },
  AvgDialog_18718_Content_14 = {
    Text = "The rain is still softly falling as you and she gaze out at the endless curtain of rain."
  },
  AvgDialog_18718_Content_15 = {
    Text = "The outside is shrouded in a gray mist, with water vapor enveloping you tightly, making it seem as if you are the only life left between heaven and earth."
  },
  AvgDialog_18718_Content_16 = {
    Text = "<LightGray:Where is Lady Daffodil now...>"
  },
  AvgDialog_18718_Content_17 = {
    Text = "Please wait a moment, {Male=sir,Female=miss}. I'll brew some hot tea in the kitchen."
  },
  AvgDialog_18718_Content_18 = {
    Text = "Although it's humble here, I can still offer you a cup of tea."
  },
  AvgDialog_18718_Content_19 = {
    Text = "Mrs. Harriet dragged her slow steps towards the kitchen."
  },
  AvgDialog_18718_Content_2 = {
    Text = [[
You follow the woman into the wooden cabin.
The interior is very simple, and you catch a whiff of damp wood.]]
  },
  AvgDialog_18718_Content_20 = {
    Text = "Until her silhouette was swallowed by the corridor's deep shadows, you finally came back to your senses."
  },
  AvgDialog_18718_Content_21 = {
    Text = "Looks like it will be a while before the rain stops. Let's take a look around."
  },
  AvgDialog_18718_Content_3 = {
    Text = "The woman slowly bent down, picked up a few sticks of firewood from the corner, and tossed them into the dark little stove."
  },
  AvgDialog_18718_Content_4 = {
    Text = "Put your hands over here, warm them up a bit longer, and you won't feel cold."
  },
  AvgDialog_18718_Content_5 = {
    Text = "Thank you very much..."
  },
  AvgDialog_18718_Content_6 = {
    Text = "My name is Harriet: @1, {Male=sir,Female=miss}. You can call me Harriet."
  },
  AvgDialog_18718_Content_7 = {
    Text = "Sure, Mrs. Harriet. To be honest, I'm curious—why are you staying here?"
  },
  AvgDialog_18718_Content_8 = {
    Text = "This area doesn't seem very habitable."
  },
  AvgDialog_18718_Content_9 = {
    Text = "Mrs. Harriet crouched, fiddling with the firewood. The flickering flames danced on her gaunt and weary face."
  },
  AvgDialog_18719_Content_1 = {
    Text = "Skullhunt Gathering"
  },
  AvgDialog_18719_Content_10 = {
    Text = "Last night, you failed to catch up with Daffodil and could only follow the address provided by Ramona to Horla's residence."
  },
  AvgDialog_18719_Content_11 = {
    Text = "G-Good morning, Miss Horla."
  },
  AvgDialog_18719_Content_12 = {
    Text = "Good morning, {Male=Mr.,Female=Miss} %player%."
  },
  AvgDialog_18719_Content_13 = {Text = "..."},
  AvgDialog_18719_Content_14 = {Text = "..."},
  AvgDialog_18719_Content_15 = {
    Text = "An awkward silence fills the air. You realize this Awakener doesn't seem very good at socializing."
  },
  AvgDialog_18719_Content_16 = {
    Text = [[
Miss Horla, I'm here regarding the Skull Hunter incident.
Since you've lived here for a long time, do you have any leads or information?]]
  },
  AvgDialog_18719_Content_17 = {
    Text = "\"Skull Hunter\"... Please wait a moment."
  },
  AvgDialog_18719_Content_18 = {
    Text = "Horla turned and started searching through the tall bookshelf."
  },
  AvgDialog_18719_Content_19 = {
    Text = "Found it! *Cough, cough...*"
  },
  AvgDialog_18719_Content_2 = {Text = "Daffodil!"},
  AvgDialog_18719_Content_20 = {
    Text = "Horla brushed away the dust floating around and placed the yellowed notebook in your hand."
  },
  AvgDialog_18719_Content_21 = {
    Text = "A month ago, Miss Doll requested my assistance."
  },
  AvgDialog_18719_Content_22 = {
    Text = "I don't have any particular skills, but I've documented all the recent cases. Hopefully, this will be of help."
  },
  AvgDialog_18719_Content_23 = {
    Text = "You open the notebook, and in elegant handwriting, it records the discovery time and location of each case, even including sketches of the bodies and crime scenes."
  },
  AvgDialog_18719_Content_24 = {
    Text = "<Shake:I apologize, my drawing skills are quite poor. You can simply ignore it...>"
  },
  AvgDialog_18719_Content_25 = {
    Text = [[
No, it's very impressive.
Thank you, Miss Horla. This note is crucial to us.]]
  },
  AvgDialog_18719_Content_26 = {
    Text = "No matter what, I'm glad to help. Those poor people..."
  },
  AvgDialog_18719_Content_27 = {
    Text = "Horla let out a soft sigh and turned to gaze at the gloomy sky outside."
  },
  AvgDialog_18719_Content_28 = {
    Text = "Rainy Town is a place where it rains all year round. However, after the rain, what it often faces is not a bountiful harvest but endless floods and plagues."
  },
  AvgDialog_18719_Content_29 = {
    Text = "Young people work in big cities like Londinium, leaving only the elderly and children behind."
  },
  AvgDialog_18719_Content_3 = {
    Text = "Huh... Where is this place?"
  },
  AvgDialog_18719_Content_30 = {
    Text = "Now, even the elders are starting to leave one by one..."
  },
  AvgDialog_18719_Content_31 = {
    Text = "I have attended a few local funerals. Whenever a loved one passes away, the townsfolk sing an ancient song..."
  },
  AvgDialog_18719_Content_32 = {
    Text = "Horla began to hum softly, and the melancholic melody soon coalesced into words as dark as ink."
  },
  AvgDialog_18719_Content_33 = {
    Text = [[
<RedItalic:We write with blood as our pen and mud as our paper.>
<RedItalic:We inscribe sorrow and fear with rain-soaked bodies...>]]
  },
  AvgDialog_18719_Content_34 = {
    Text = "These words flowed slowly around Horla, then formed a yellowed letter that enveloped her."
  },
  AvgDialog_18719_Content_35 = {
    Text = "She let out a soft sigh, tears glistening in her eyes."
  },
  AvgDialog_18719_Content_36 = {
    Text = "Isn't everything happening now the sorrow that the residents of Rainy Town wrote with their rain-soaked bodies..."
  },
  AvgDialog_18719_Content_37 = {
    Text = "The air is filled with a silent, thick sense of depression, almost suffocating you."
  },
  AvgDialog_18719_Content_38 = {
    Text = "<Shake:Cough, Miss Horla...>"
  },
  AvgDialog_18719_Content_39 = {Text = "..."},
  AvgDialog_18719_Content_4 = {
    Text = "The cheerful chirping of birds pulls you back to reality from your dreams."
  },
  AvgDialog_18719_Content_40 = {
    Text = "Ah! Sorry, I did it again..."
  },
  AvgDialog_18719_Content_41 = {
    Text = "Horla came to her senses and took two deep breaths."
  },
  AvgDialog_18719_Content_42 = {
    Text = "The oppressive emotions finally dissipated, and the heavy weight on your chest lifted significantly."
  },
  AvgDialog_18719_Content_43 = {Text = "..."},
  AvgDialog_18719_Content_44 = {Text = "..."},
  AvgDialog_18719_Content_45 = {
    Text = "Ah, right, right."
  },
  AvgDialog_18719_Content_46 = {
    Text = "I brewed a pot of rose tea using freshly picked petals. Would you like to join me for a taste?"
  },
  AvgDialog_18719_Content_47 = {
    Text = "In half an hour"
  },
  AvgDialog_18719_Content_48 = {
    Text = "In one hand, you hold a bone china cup filled with rose tea, while with the other, you flip through Horla's notes, searching for a possible breakthrough."
  },
  AvgDialog_18719_Content_49 = {
    Text = "Where are the people from the police station?"
  },
  AvgDialog_18719_Content_5 = {
    Text = "You gaze at the clean, simple room in confusion, then lift the blanket and take a sniff."
  },
  AvgDialog_18719_Content_50 = {
    Text = "On Norwich Street, the place you passed by last night."
  },
  AvgDialog_18719_Content_51 = {Text = "..."},
  AvgDialog_18719_Content_52 = {
    Text = [[
Rain. Blood. Daffodil.
Recalling last night's encounter, you can't tell whether it was a dream or reality.]]
  },
  AvgDialog_18719_Content_53 = {
    Text = "You sound weak... Did you not rest well last night?"
  },
  AvgDialog_18719_Content_54 = {
    Text = "No, it's just..."
  },
  AvgDialog_18719_Content_55 = {
    Text = "You shook your head, trying to clear the jumbled thoughts from your mind."
  },
  AvgDialog_18719_Content_56 = {Text = "..."},
  AvgDialog_18719_Content_57 = {
    Text = "The investigation in Rye Town just concluded two days ago, and your wounds haven't fully healed yet."
  },
  AvgDialog_18719_Content_58 = {
    Text = "Sigh, it can't be helped that the other Investigators are also caught up, can it?"
  },
  AvgDialog_18719_Content_59 = {
    Text = "At this point, let's wrap up this case quickly. I want to take a vacation."
  },
  AvgDialog_18719_Content_6 = {
    Text = "Good. Dry and soft, with no smell of rain or blood."
  },
  AvgDialog_18719_Content_60 = {
    Text = "Huh, this is..."
  },
  AvgDialog_18719_Content_61 = {
    Text = "The sound of flipping pages came to an abrupt stop."
  },
  AvgDialog_18719_Content_62 = {
    Text = "You focus on the frozen page, starting to formulate your next investigation plan"
  },
  AvgDialog_18719_Content_63 = {
    Text = "Ramona... Before meeting up with the detective, I want to go somewhere first."
  },
  AvgDialog_18719_Content_7 = {
    Text = "Good morning, {Male=Mr.,Female=Miss} %player%. Welcome to my humble abode..."
  },
  AvgDialog_18719_Content_8 = {
    Text = "Miss Horla?!"
  },
  AvgDialog_18719_Content_9 = {
    Text = "Memory begins to gradually recover."
  },
  AvgDialog_18720_Content_1 = {
    Text = "11:00, Highgate Cemetery"
  },
  AvgDialog_18720_Content_10 = {
    Text = "Don't expect too much from the expertise of detectives in remote areas."
  },
  AvgDialog_18720_Content_11 = {
    Text = "...Makes sense."
  },
  AvgDialog_18720_Content_12 = {
    Text = "You take out your magnifying glass and continue observing the skeleton."
  },
  AvgDialog_18720_Content_13 = {
    Text = "There is a <Red:jagged cut> on the neckbone..."
  },
  AvgDialog_18720_Content_14 = {
    Text = "However, it's quite messy with numerous overlapping cuts, completely different from what we saw in the photos earlier."
  },
  AvgDialog_18720_Content_15 = {
    Text = "Still quite inexperienced, first time committing a crime?"
  },
  AvgDialog_18720_Content_16 = {
    Text = [[
Begin the investigation centered around the Burial Ground.
Inexperienced novices typically do not wander far from home during their first crime.]]
  },
  AvgDialog_18720_Content_17 = {
    Text = "Understood. I'm confident this time; the culprit will be caught soon!"
  },
  AvgDialog_18720_Content_18 = {
    Text = "Murderer? How dare you assume, *hic*, that there's only one murderer?"
  },
  AvgDialog_18720_Content_19 = {
    Text = "From the depths of the dense forest emerged an old man, reeking of alcohol and with flushed cheeks."
  },
  AvgDialog_18720_Content_2 = {
    Text = "You walk alone through the desolate burial mounds."
  },
  AvgDialog_18720_Content_20 = {
    Text = "Sorry, I didn't mean to eavesdrop on your monologue."
  },
  AvgDialog_18720_Content_21 = {
    Text = "I am the caretaker of this graveyard. You can call me... uh, <Blue:Old Freeman>."
  },
  AvgDialog_18720_Content_22 = {
    Text = [[
Good afternoon, Mr. Freeman.
Did you just imply that there is more than one killer?]]
  },
  AvgDialog_18720_Content_23 = {
    Text = "Old Freeman grabbed the bottle and chugged down the liquor, his fat Adam's apple bobbing up and down."
  },
  AvgDialog_18720_Content_24 = {
    Text = "Burp! This wretched forest never sees a soul all day long. Since you're here, let me tell you a story..."
  },
  AvgDialog_18720_Content_25 = {
    Text = "That was probably earlier this year...? I can't quite recall."
  },
  AvgDialog_18720_Content_26 = {
    Text = "As usual, I drank and dozed off in a shady spot."
  },
  AvgDialog_18720_Content_27 = {
    Text = "And then I heard some strange noises, almost like..."
  },
  AvgDialog_18720_Content_28 = {
    Text = "<RedItalic:Zzz... Crack...>"
  },
  AvgDialog_18720_Content_29 = {
    Text = "Strange sound. What's next?"
  },
  AvgDialog_18720_Content_3 = {
    Text = "Crows glide across the gloomy sky as the desolate autumn wind howls."
  },
  AvgDialog_18720_Content_30 = {
    Text = [[
Don't worry, little detective.
I opened my eyes... hic, guess what I saw?]]
  },
  AvgDialog_18720_Content_31 = {
    Text = "No way, it's just the Skull Hunter, isn't it?"
  },
  AvgDialog_18720_Content_32 = {
    Text = "Sure, it's a Skull Hunter! Or, you could say it's a woman..."
  },
  AvgDialog_18720_Content_33 = {
    Text = "A woman is cutting off Pinocchio's head!"
  },
  AvgDialog_18720_Content_34 = {
    Text = "Then she saw me—hic—as if she'd seen a ghost, and ran faster than anyone else!"
  },
  AvgDialog_18720_Content_35 = {
    Text = "My poor Pinoko, her neck is barely hanging on by a thread!"
  },
  AvgDialog_18720_Content_36 = {
    Text = "Haha, <Big:Hahahaha...>"
  },
  AvgDialog_18720_Content_37 = {
    Text = "Old Freeman burst into a series of loud laughs, even shedding tears of joy."
  },
  AvgDialog_18720_Content_38 = {
    Text = "<SmallShake:Patience, patience...>"
  },
  AvgDialog_18720_Content_39 = {
    Text = "Hic, hic! It's been about a month, and I heard that voice again..."
  },
  AvgDialog_18720_Content_4 = {Text = "Found it."},
  AvgDialog_18720_Content_40 = {
    Text = "<RedItalic:Zzz... Crack... Crack...>"
  },
  AvgDialog_18720_Content_41 = {
    Text = "This time, it's not the woman who returned, but a very thin man."
  },
  AvgDialog_18720_Content_42 = {
    Text = "That's a skilled worker! With a single slash..."
  },
  AvgDialog_18720_Content_43 = {
    Text = "<RedBig:Whoosh!> Pinoko's head is gone!"
  },
  AvgDialog_18720_Content_44 = {
    Text = "It sounds like there were two Skull Hunters. What happened next?"
  },
  AvgDialog_18720_Content_45 = {
    Text = "Later? There is no later. That's the entire story of Old Freeman and the Headcrabs, hic."
  },
  AvgDialog_18720_Content_46 = {
    Text = "Old Freeman let out a satisfied belch, squinted his murky yellow eyes, and looked you up and down."
  },
  AvgDialog_18720_Content_47 = {
    Text = "You seem completely clueless, poor little detective. Have you ever heard of <Red:The Legend of the Skull Hunter>?"
  },
  AvgDialog_18720_Content_48 = {
    Text = "The Legend of the Skull Hunter? Do tell."
  },
  AvgDialog_18720_Content_49 = {
    Text = "Old Freeman leisurely leaned against the tombstone, took a few gulps to finish the remaining liquor in the bottle, and casually tossed it onto the ground."
  },
  AvgDialog_18720_Content_5 = {
    Text = "You stop in front of a solitary grave, the decayed coffin lid already pried open below."
  },
  AvgDialog_18720_Content_50 = {
    Text = "Liquid oozed from the broken bottle, leaving a winding trail on the ground. Like tears, or perhaps blood."
  },
  AvgDialog_18720_Content_51 = {
    Text = "Some say the Skull Hunter is a monster born from the <Yellow:Epidemic>."
  },
  AvgDialog_18720_Content_52 = {
    Text = "Some say that the Skull Hunter is neither one person nor two people."
  },
  AvgDialog_18720_Content_53 = {
    Text = "<Red:The Skull Hunters is an organization.>"
  },
  AvgDialog_18720_Content_54 = {
    Text = "Organization?"
  },
  AvgDialog_18720_Content_55 = {
    Text = "Yes, an organization."
  },
  AvgDialog_18720_Content_56 = {
    Text = "They only appear on rainy nights, their footsteps concealed by the rain, silently creeping up behind you..."
  },
  AvgDialog_18720_Content_57 = {
    Text = "<RedBig:Snap!>"
  },
  AvgDialog_18720_Content_58 = {Text = "!!"},
  AvgDialog_18720_Content_59 = {
    Text = "Hahaha! What's this? Already scared, my little detective?"
  },
  AvgDialog_18720_Content_6 = {
    Text = "A headless skeleton lies in the coffin, now a paradise for moss and insects."
  },
  AvgDialog_18720_Content_60 = {
    Text = "He sways closer, his murky yellow eyes rolling, almost burning into you."
  },
  AvgDialog_18720_Content_61 = {
    Text = "This person seems off. Leave this place quickly."
  },
  AvgDialog_18720_Content_62 = {
    Text = "Sorry, Mr. Freeman. It's getting late. I think I have to leave..."
  },
  AvgDialog_18720_Content_63 = {
    Text = "You took a light breath and walked away without looking back."
  },
  AvgDialog_18720_Content_64 = {
    Text = "Mocking laughter comes from behind, but you can't afford to care about that now. All you want is to leave."
  },
  AvgDialog_18720_Content_65 = {
    Text = "The sky gradually darkened, with low-hanging dark clouds blocking the pale sunlight. The wind stirred the leaves, causing them to undulate like waves."
  },
  AvgDialog_18720_Content_66 = {
    Text = "At the end of the graveyard, you see a figure that is both familiar and strange."
  },
  AvgDialog_18720_Content_67 = {
    Text = "It's Daffodil. Most of her face is hidden under the brim of her lowered hat, with gray-white hair gently swaying in the wind."
  },
  AvgDialog_18720_Content_68 = {
    Text = "Seeing you in such a disheveled state, Daffodil laughed happily."
  },
  AvgDialog_18720_Content_69 = {
    Text = "Long time no see, {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_18720_Content_7 = {
    Text = "The note records the discovery time as half a year ago; the time of death must be even earlier..."
  },
  AvgDialog_18720_Content_8 = {
    Text = "In other words, this is likely the earliest known victim of the \"Skull Hunter.\" However, the police records never mentioned it..."
  },
  AvgDialog_18720_Content_9 = {
    Text = "There's no proper hospital or funeral home here, and no one pays much attention to the dead."
  },
  AvgDialog_18721_Content_1 = {
    Text = "Maybe try using Mind Trace to find the Skull Hunter?"
  },
  AvgDialog_18721_Content_2 = {
    Text = "This method has little effect on Ultra Realm creatures."
  },
  AvgDialog_18721_Content_3 = {
    Text = "Spiritual retrospection isn't omnipotent either."
  },
  AvgDialog_18722_Content_1 = {
    Text = "Until We Meet Again"
  },
  AvgDialog_18722_Content_10 = {
    Text = "<LightGray:A precious skull? Whose could it be...>"
  },
  AvgDialog_18722_Content_11 = {Text = "..."},
  AvgDialog_18722_Content_12 = {
    Text = "You look troubled, %player%. It seems you really want to know the answer?"
  },
  AvgDialog_18722_Content_13 = {
    Text = "Yeah, I guess."
  },
  AvgDialog_18722_Content_14 = {
    Text = "Ahem, I'm not the type to casually pry into others' privacy."
  },
  AvgDialog_18722_Content_15 = {
    Text = "Is that so? But your expression has already betrayed you."
  },
  AvgDialog_18722_Content_16 = {
    Text = "Sure, I want to know."
  },
  AvgDialog_18722_Content_17 = {
    Text = "I just want to know more about you, Lady Daffodil."
  },
  AvgDialog_18722_Content_18 = {
    Text = "Oh? Someone seems to be growing greedier."
  },
  AvgDialog_18722_Content_19 = {
    Text = "Here's a hint: <Yellow:It's something you've seen before.>"
  },
  AvgDialog_18722_Content_2 = {
    Text = "Support troops and the Committee are on their way. Stay here and secure the area."
  },
  AvgDialog_18722_Content_20 = {
    Text = "Seen this before...?"
  },
  AvgDialog_18722_Content_21 = {
    Text = "You ponder deeply, the story of the past two days and the people you've met flash before your eyes like a revolving lantern."
  },
  AvgDialog_18722_Content_22 = {Text = "..."},
  AvgDialog_18722_Content_23 = {Text = "!!"},
  AvgDialog_18722_Content_24 = {
    Text = "Could it be the one on Norwich Street who looks exactly like you...?"
  },
  AvgDialog_18722_Content_25 = {
    Text = "Very smart."
  },
  AvgDialog_18722_Content_26 = {
    Text = "But why... I don't understand."
  },
  AvgDialog_18722_Content_27 = {
    Text = "Daffodil gazed at the hazy dawn on the distant horizon, the chilly wind lifting her long hair."
  },
  AvgDialog_18722_Content_28 = {
    Text = "That is a \"specimen.\" It belonged to my former master."
  },
  AvgDialog_18722_Content_29 = {
    Text = "Here's a secret: My current face is modeled after it."
  },
  AvgDialog_18722_Content_3 = {
    Text = "Don't worry, this time I'll be good and wait here. I won't run around everywhere."
  },
  AvgDialog_18722_Content_30 = {Text = "?!"},
  AvgDialog_18722_Content_31 = {
    Text = "<LightGray:So this isn't your true appearance...>"
  },
  AvgDialog_18722_Content_32 = {
    Text = [[
You did me a great help this time.
I still can't forgive myself for using such an inexperienced Keeper as bait.]]
  },
  AvgDialog_18722_Content_33 = {
    Text = "...It doesn't matter. As long as the investigation is completed, I don't mind being used once."
  },
  AvgDialog_18722_Content_34 = {
    Text = "Is that so? But I really feel bad about it. So..."
  },
  AvgDialog_18722_Content_35 = {
    Text = "As an apology, I can grant you one request."
  },
  AvgDialog_18722_Content_36 = {Text = "It's free~"},
  AvgDialog_18722_Content_37 = {Text = "!!"},
  AvgDialog_18722_Content_38 = {
    Text = "The person before you is a shrewd and ruthless merchant, holding intelligence, taboo knowledge, and precious collectibles that many covet."
  },
  AvgDialog_18722_Content_39 = {
    Text = "And now, she can grant you one request free of charge."
  },
  AvgDialog_18722_Content_4 = {
    Text = [[
Never expected the investigation to be completed so quickly.
Great job, %player%.]]
  },
  AvgDialog_18722_Content_40 = {
    Text = "<LightGray:No... Miss Doll would be upset if she found out I was making deals with others outside.>"
  },
  AvgDialog_18722_Content_41 = {
    Text = "A flood of possibilities flashes through your mind—lost Golden Relics, the most delicious cakes, a massive amount of money..."
  },
  AvgDialog_18722_Content_42 = {
    Text = "Conflicting thoughts intertwine and clash, but eventually recede like the tide — you decide to follow your instincts."
  },
  AvgDialog_18722_Content_43 = {
    Text = "Have you decided on your request? Don't be too greedy."
  },
  AvgDialog_18722_Content_44 = {
    Text = "I've made up my mind. My requirements are simple."
  },
  AvgDialog_18722_Content_45 = {
    Text = "Let me see your true form."
  },
  AvgDialog_18722_Content_46 = {Text = "..."},
  AvgDialog_18722_Content_47 = {
    Text = "Is it really that simple? Think it through. I can give you many things, any one of which is worth more than this."
  },
  AvgDialog_18722_Content_48 = {
    Text = "The value is determined by my judgment. That is my only demand."
  },
  AvgDialog_18722_Content_49 = {
    Text = "As expected of a {Male=Mr.,Female=Miss} Keeper, you always surprise me. So..."
  },
  AvgDialog_18722_Content_5 = {
    Text = "Ahem, it's all thanks to Lady Daffodil."
  },
  AvgDialog_18722_Content_50 = {
    Text = "Daffodil walked towards you. The wind lifted her long hair, making it flutter like gray waves."
  },
  AvgDialog_18722_Content_51 = {
    Text = "You are so close that you can almost see your reflection in her eyes."
  },
  AvgDialog_18722_Content_52 = {
    Text = "Remember to keep it a secret, %player%."
  },
  AvgDialog_18722_Content_53 = {
    Text = "No sooner had she spoken than her features began to blur and dissolve, like oil paints in water..."
  },
  AvgDialog_18722_Content_54 = {
    Text = "Finally, you finally saw her face clearly."
  },
  AvgDialog_18722_Content_55 = {
    Text = "It was a @2 face, reminding you of many things."
  },
  AvgDialog_18722_Content_56 = {
    Text = "Like the damp mist after the rain, the narcissus quietly blooming in the corner, or the small animal curled up in the dark..."
  },
  AvgDialog_18722_Content_57 = {
    Text = "Before you could take a closer look, the face vanished like a drop of water merging into the water."
  },
  AvgDialog_18722_Content_58 = {
    Text = "So... this is your true form."
  },
  AvgDialog_18722_Content_59 = {
    Text = "How is it? Is it ugly, right?"
  },
  AvgDialog_18722_Content_6 = {
    Text = "It's just a small effort, and I've also recovered what was lost."
  },
  AvgDialog_18722_Content_60 = {
    Text = "You shook your head."
  },
  AvgDialog_18722_Content_61 = {
    Text = "It was unexpected... but it fit you well."
  },
  AvgDialog_18722_Content_62 = {
    Text = "The morning sunlight swept away the dampness of the rain, enveloping her in a soft halo."
  },
  AvgDialog_18722_Content_63 = {
    Text = "To be honest... I was a bit scared just now, and then I was surprised at my own fear."
  },
  AvgDialog_18722_Content_64 = {
    Text = "Ten years, fifty years? I can't even remember the last time I felt fear."
  },
  AvgDialog_18722_Content_65 = {
    Text = "Afraid...? Were you worried I might think you're unattractive?"
  },
  AvgDialog_18722_Content_66 = {
    Text = "Daffodil didn't respond, just gently ruffled your hair."
  },
  AvgDialog_18722_Content_67 = {
    Text = "%player%, you are now the only person in the world who has seen the real \"me\"."
  },
  AvgDialog_18722_Content_68 = {
    Text = "Heh, I've got a bit of leverage over you now."
  },
  AvgDialog_18722_Content_69 = {
    Text = "Before I lose my memory, I need to quickly draw your face on paper."
  },
  AvgDialog_18722_Content_7 = {
    Text = "From the merchant's perspective, this was a perfect \"deal.\""
  },
  AvgDialog_18722_Content_70 = {
    Text = "Daffodil smiled, her eyes curving into a beautiful arc."
  },
  AvgDialog_18722_Content_71 = {
    Text = "What a silly child."
  },
  AvgDialog_18722_Content_72 = {
    Text = "Well, your Committee and police friends should be on their way now, right?"
  },
  AvgDialog_18722_Content_73 = {
    Text = "<Shake:So you knew all along...>"
  },
  AvgDialog_18722_Content_74 = {
    Text = [[
I don't have the patience for those tedious interrogations.
Next time, let's find a quiet place and have a cup of coffee.]]
  },
  AvgDialog_18722_Content_75 = {
    Text = "Farewell, my {Male=Mr.,Female=Miss} Keeper."
  },
  AvgDialog_18722_Content_76 = {
    Text = "Huh? Oh... Farewell, Lady Daffodil."
  },
  AvgDialog_18722_Content_77 = {
    Text = "Daffodil waved at you and walked away."
  },
  AvgDialog_18722_Content_78 = {
    Text = "Gazing at her relaxed figure in the distance, you feel your mood lighten."
  },
  AvgDialog_18722_Content_79 = {
    Text = "The lingering haze has completely dissipated, and the sky has finally cleared. Sunlight filters through the lazy clouds, warming your entire body."
  },
  AvgDialog_18722_Content_8 = {
    Text = "You lost something..."
  },
  AvgDialog_18722_Content_80 = {
    Text = "For some reason, you have a premonition—"
  },
  AvgDialog_18722_Content_81 = {
    Text = "You will keep encountering each other across different times and dimensions."
  },
  AvgDialog_18722_Content_9 = {
    Text = "The Skull Hunter took a <Yellow:precious skull> from me, so I'm here to do a little investigation. It's that simple."
  },
  AvgDialog_18723_Content_1 = {
    Text = "Cough, cough, Awakeners from the Ultra Realm are really hard to chase..."
  },
  AvgDialog_18723_Content_10 = {Text = "Answer...?"},
  AvgDialog_18723_Content_11 = {
    Text = "It ran off while you were temporarily away, and Ms. Horla and I were chatting."
  },
  AvgDialog_18723_Content_12 = {
    Text = "But there's no need to worry. If you follow me, you'll see it soon."
  },
  AvgDialog_18723_Content_13 = {
    Text = "Is it in the <Blue:wasteland to the north of Rainy Town>?"
  },
  AvgDialog_18723_Content_14 = {
    Text = "Oh? It seems our little detective is quite sharp. How did you manage to figure it out?"
  },
  AvgDialog_18723_Content_15 = {
    Text = "That guy exhibits the D-Phenomenon, which is likely related to the plague that occurred in the north three years ago."
  },
  AvgDialog_18723_Content_16 = {
    Text = "Now that it's seriously injured and facing attacks from both us and the police, there aren't many places left for it to go."
  },
  AvgDialog_18723_Content_17 = {
    Text = "No matter if it's hiding in the wasteland, it's a breakthrough worth investigating."
  },
  AvgDialog_18723_Content_18 = {
    Text = "Not bad, quite clever. But do you know how vast that wasteland is?"
  },
  AvgDialog_18723_Content_19 = {
    Text = [[
Approximately 50 square miles.
You wouldn't want to waste your precious vacation on geological exploration and population census work, would you?]]
  },
  AvgDialog_18723_Content_2 = {
    Text = "You stagger to a crossroads."
  },
  AvgDialog_18723_Content_20 = {
    Text = [[
And I happen to know its exact hiding place.
Would you like to come along?]]
  },
  AvgDialog_18723_Content_21 = {
    Text = "Don't agree. She's extremely dangerous; don't be deceived by her."
  },
  AvgDialog_18723_Content_22 = {
    Text = "I'll count to three. Three, two..."
  },
  AvgDialog_18723_Content_23 = {Text = "..."},
  AvgDialog_18723_Content_24 = {
    Text = "I'll go with you."
  },
  AvgDialog_18723_Content_25 = {Text = "..."},
  AvgDialog_18723_Content_26 = {
    Text = "Hmm, what an obedient child."
  },
  AvgDialog_18723_Content_27 = {
    Text = "Lady Daffodil, may I accompany you?"
  },
  AvgDialog_18723_Content_28 = {
    Text = "A frail girl steps out from the shadows of the trees behind you, her eyes filled with worry."
  },
  AvgDialog_18723_Content_29 = {
    Text = "I know you're worried about %player%."
  },
  AvgDialog_18723_Content_3 = {
    Text = "No more hunters here, only Daffodil and her elongated shadow."
  },
  AvgDialog_18723_Content_30 = {
    Text = "But I'm sorry, my little rose. This time I can only take one person."
  },
  AvgDialog_18723_Content_31 = {
    Text = "The cold wind howls through the night streets. Horla wraps herself tightly in the windproof and warming letter, her pale little face lifted as she looks at Daffodil with a serious expression."
  },
  AvgDialog_18723_Content_32 = {
    Text = "Why? I may not be good at fighting, but an extra hand is always helpful, isn't it?"
  },
  AvgDialog_18723_Content_33 = {
    Text = "I can only take one. Sorry, Little Rose, I have my reasons."
  },
  AvgDialog_18723_Content_34 = {Text = "..."},
  AvgDialog_18723_Content_35 = {
    Text = "Lady Daffodil, you will surely escort {Male=Mr.,Female=Miss} %player% safely back, right?"
  },
  AvgDialog_18723_Content_36 = {
    Text = "Daffodil watched the moths fluttering under the streetlight and leisurely blew a round smoke ring from her mouth."
  },
  AvgDialog_18723_Content_37 = {
    Text = "Of course, rest assured."
  },
  AvgDialog_18723_Content_4 = {
    Text = "For some reason, you feel that she has been standing there for a very long time."
  },
  AvgDialog_18723_Content_5 = {
    Text = "It seems that since ancient times, she has been standing here alone, silently gazing into the distance without uttering a word."
  },
  AvgDialog_18723_Content_6 = {
    Text = "You're here."
  },
  AvgDialog_18723_Content_7 = {
    Text = "Daffodil turned around, her expression still faint."
  },
  AvgDialog_18723_Content_8 = {
    Text = "Where is the Skull Hunter? Have you lost track?"
  },
  AvgDialog_18723_Content_9 = {
    Text = "Yes, we lost track. But... I think I already know the answer."
  },
  AvgDialog_18724_Content_1 = {Text = "From Afar"},
  AvgDialog_18724_Content_10 = {
    Text = "Based on the condition of the bodies and witness statements, the two died within half an hour of each other."
  },
  AvgDialog_18724_Content_11 = {
    Text = "Is the place of death nearby?"
  },
  AvgDialog_18724_Content_12 = {
    Text = "Ramona shook her head."
  },
  AvgDialog_18724_Content_13 = {
    Text = "Even by car, it takes over an hour, not to mention that very few people in the town own cars."
  },
  AvgDialog_18724_Content_14 = {
    Text = "... Perhaps Old Freeman was right."
  },
  AvgDialog_18724_Content_15 = {
    Text = "The Skull Hunters are an organization. But what is their true purpose?"
  },
  AvgDialog_18724_Content_16 = {
    Text = "Heads@2... More heads..."
  },
  AvgDialog_18724_Content_17 = {
    Text = "A sudden cold wind blew from behind."
  },
  AvgDialog_18724_Content_18 = {
    Text = "You turn around, only to see the headless corpse rushing at you with incredible speed."
  },
  AvgDialog_18724_Content_19 = {Text = "?!"},
  AvgDialog_18724_Content_2 = {
    Text = "00:15, Horla's Cabin"
  },
  AvgDialog_18724_Content_20 = {
    Text = "Give me the head@3... give@1 more heads @4..."
  },
  AvgDialog_18724_Content_21 = {
    Text = "You swiftly shift your body aside. The corpse smashes through the glass ahead, vanishing into the vast night."
  },
  AvgDialog_18724_Content_22 = {
    Text = "Such incredible speed... Could it be an Awakener from the Ultra Realm?"
  },
  AvgDialog_18724_Content_23 = {
    Text = "Just as you are puzzled, a strong scent of narcissus envelops you completely."
  },
  AvgDialog_18724_Content_24 = {
    Text = "A purple skirt swiftly sweeps past you, then vanishes before your eyes."
  },
  AvgDialog_18724_Content_25 = {
    Text = "Lady Daffodil...?"
  },
  AvgDialog_18724_Content_26 = {
    Text = "Quick, catch up! Don't let the important clue slip away."
  },
  AvgDialog_18724_Content_3 = {
    Text = "You found a quiet corner and explained what had just happened to Ramona."
  },
  AvgDialog_18724_Content_4 = {
    Text = "Sure, just skip the part where you almost had your throat slit."
  },
  AvgDialog_18724_Content_5 = {Text = "..."},
  AvgDialog_18724_Content_6 = {
    Text = "I've called you <Red:35> times since this afternoon, but there's been no response."
  },
  AvgDialog_18724_Content_7 = {
    Text = "Sorry, it happened so suddenly..."
  },
  AvgDialog_18724_Content_8 = {
    Text = "...This won't happen again."
  },
  AvgDialog_18724_Content_9 = {
    Text = [[
The identities of the victims found during the day have been confirmed.
Carpenter Damon Mendes, 35; Unemployed youth Thomas Quillen, 23.]]
  },
  AvgDialog_18725_Content_1 = {
    Text = "An upside-down picture frame catches your attention."
  },
  AvgDialog_18725_Content_10 = {
    Text = "<RedItalic:He drank ten bottles of alcohol on Sunday, lost his job, and lost his wife.>"
  },
  AvgDialog_18725_Content_11 = {
    Text = "Someone is softly humming a nursery rhyme without rhythm."
  },
  AvgDialog_18725_Content_12 = {
    Text = "The dry melody feels like a damp, invisible hand gently stroking the already raised hairs on the back of your neck."
  },
  AvgDialog_18725_Content_13 = {
    Text = "<RedItalic:Old Freeman wailed and drank eleven bottles of liquor again on Monday...>"
  },
  AvgDialog_18725_Content_14 = {
    Text = "Accompanied by the creaking of the wooden boards, Harriet stood silently before the dimly lit corridor."
  },
  AvgDialog_18725_Content_15 = {
    Text = "That's right, Old Freeman is my husband."
  },
  AvgDialog_18725_Content_16 = {Text = "What?!"},
  AvgDialog_18725_Content_17 = {
    Text = "At that time, everyone thought I was dead, including my husband."
  },
  AvgDialog_18725_Content_18 = {
    Text = "Later, after an unknown amount of time, I came back to life... but something about me had changed."
  },
  AvgDialog_18725_Content_19 = {
    Text = "You remain silent, already guessing the rest of the story."
  },
  AvgDialog_18725_Content_2 = {
    Text = "From the kitchen came the gurgling sound of boiling water; Mrs. Harriet was still busy inside."
  },
  AvgDialog_18725_Content_20 = {
    Text = "Humans infected by Dissolution suffer irreversible mental damage, leading to various complications."
  },
  AvgDialog_18725_Content_21 = {
    Text = "It's no surprise that Lady Harriet ended up this way."
  },
  AvgDialog_18725_Content_22 = {
    Text = "I began to crave heads, many heads... So I sneaked into a burial ground."
  },
  AvgDialog_18725_Content_23 = {
    Text = [[
I leaned over old Pinoco's body, using a rusty sickle to try to cut off his head.
But I was too weak at that time, and I couldn't even hold the sickle steady...]]
  },
  AvgDialog_18725_Content_24 = {
    Text = "And guess who I met?"
  },
  AvgDialog_18725_Content_25 = {Text = "..."},
  AvgDialog_18725_Content_26 = {
    Text = "I met my husband."
  },
  AvgDialog_18725_Content_27 = {
    Text = "He's become fatter, older, and turned into a drunkard."
  },
  AvgDialog_18725_Content_28 = {
    Text = "Heh... This world always finds new ways to torment us poor souls."
  },
  AvgDialog_18725_Content_29 = {
    Text = "He held his drink and looked at me like a stray dog."
  },
  AvgDialog_18725_Content_3 = {
    Text = "You gently flip the picture frame over."
  },
  AvgDialog_18725_Content_30 = {
    Text = "He's been laughing the whole time. Yes, I know I must have looked both pitiful and ridiculous back then."
  },
  AvgDialog_18725_Content_31 = {
    Text = "But he... doesn't recognize me at all."
  },
  AvgDialog_18725_Content_32 = {
    Text = "...So, you're the skull hunter he mentioned."
  },
  AvgDialog_18725_Content_33 = {
    Text = "Harriet mechanically tilted her head to the right, producing a \"crackling\" sound from her neck."
  },
  AvgDialog_18725_Content_34 = {
    Text = "Yeah. Even though I know he doesn't remember me, I still sneak a peek at him."
  },
  AvgDialog_18725_Content_35 = {
    Text = "So you overheard our conversation, learned that I was conducting an investigation into the murders, and decided to follow and ambush me?"
  },
  AvgDialog_18725_Content_36 = {Text = "..."},
  AvgDialog_18725_Content_37 = {
    Text = "You truly are different from them. I've said so much, yet you remain composed."
  },
  AvgDialog_18725_Content_38 = {
    Text = "You let out a soft sigh, glancing down at the locked door next to you."
  },
  AvgDialog_18725_Content_39 = {
    Text = "Dark red blood oozes like thick syrup from the crack of the door, slowly creeping toward your feet."
  },
  AvgDialog_18725_Content_4 = {
    Text = "This is an old family photo. The faces of the wife and child have long been blurred, leaving only the husband standing on the far left."
  },
  AvgDialog_18725_Content_40 = {
    Text = "Did you know..."
  },
  AvgDialog_18725_Content_41 = {
    Text = "The ground, ceiling, cabinets... all reek of blood and the stench of death."
  },
  AvgDialog_18725_Content_42 = {
    Text = "From the moment I entered, I knew everything."
  },
  AvgDialog_18725_Content_5 = {
    Text = "He stands tall and relaxed in front of his newly built house, flashing a radiant smile at the camera."
  },
  AvgDialog_18725_Content_6 = {
    Text = "You gaze at his somewhat familiar brow and eyes, and a ridiculous thought suddenly flashes through your mind."
  },
  AvgDialog_18725_Content_7 = {
    Text = "Old Freeman...?!"
  },
  AvgDialog_18725_Content_8 = {
    Text = "Could he be Mrs. Harriet's husband?"
  },
  AvgDialog_18725_Content_9 = {
    Text = "<RedItalic:Old Freeman, Old Freeman, the poor and mad drunkard Old Freeman...>"
  },
  AvgDialog_18726_Content_1 = {
    Text = "You walk deeper into the alley, your coat already soaked by the rain."
  },
  AvgDialog_18726_Content_10 = {
    Text = "Tap, tap, tap."
  },
  AvgDialog_18726_Content_11 = {
    Text = "The sound of unhurried footsteps echoed from the street outside the alley, and a blurry figure appeared under the streetlamp."
  },
  AvgDialog_18726_Content_12 = {
    Text = "It's dangerous here, leave immediately—"
  },
  AvgDialog_18726_Content_13 = {
    Text = "That is a woman."
  },
  AvgDialog_18726_Content_14 = {
    Text = "She stands alone under the streetlamp, holding a plump head that fits perfectly with the neck of the headless body behind you."
  },
  AvgDialog_18726_Content_15 = {
    Text = "Blood drips from the neck, slowly flowing along the cracks in the floor tiles."
  },
  AvgDialog_18726_Content_16 = {
    Text = [[
Stay right there.
Who are you?]]
  },
  AvgDialog_18726_Content_17 = {
    Text = "The dim streetlights flicker, emitting an irritating electrical hum."
  },
  AvgDialog_18726_Content_18 = {
    Text = "The woman raises her head, and you finally make out her features."
  },
  AvgDialog_18726_Content_19 = {Text = "..."},
  AvgDialog_18726_Content_2 = {
    Text = "Dark red blood flows from the shadow, extending menacing tentacles, silently inviting you."
  },
  AvgDialog_18726_Content_20 = {
    Text = "<Gray:L-Lady Daffodil?>"
  },
  AvgDialog_18726_Content_3 = {
    Text = "It's quiet here; you can only hear the sound of rain, footsteps, and breathing."
  },
  AvgDialog_18726_Content_4 = {
    Text = "They sound like a chaotic drumbeat, growing faster and louder, until you reach the end of the alley."
  },
  AvgDialog_18726_Content_5 = {
    Text = "The bloated corpse lies limp in the trash heap, carelessly discarded."
  },
  AvgDialog_18726_Content_6 = {
    Text = "The incision on the neck is blurred, with dark red blood gushing out from the vessels."
  },
  AvgDialog_18726_Content_7 = {
    Text = "You don't need to touch it to know the blood is warm."
  },
  AvgDialog_18726_Content_8 = {
    Text = "Head missing, jagged wounds on the neck..."
  },
  AvgDialog_18726_Content_9 = {
    Text = "It's the \"Skull Hunter.\""
  },
  AvgDialog_18727_Content_1 = {
    Text = "Serendipity"
  },
  AvgDialog_18727_Content_10 = {
    Text = "If she didn't lie or misjudge, then yes."
  },
  AvgDialog_18727_Content_11 = {
    Text = "<Blue:Vanguard> arrived in Rainy Town a week ago and detected signs of an active Silver at the site of death."
  },
  AvgDialog_18727_Content_12 = {
    Text = "Including the last three, this is the eighth <Blue:Skull Hunter Event> in Rainy Town."
  },
  AvgDialog_18727_Content_13 = {
    Text = "Skull Hunter? Is that what people here call the murderer?"
  },
  AvgDialog_18727_Content_14 = {
    Text = "Very vivid, isn't it? Thanks to him, no one dares to go out after dark here anymore."
  },
  AvgDialog_18727_Content_15 = {
    Text = "You gaze at the desolate street before you."
  },
  AvgDialog_18727_Content_16 = {
    Text = "By 8 PM, all nearby doors and windows are tightly locked. Fear seeps from the pitch-black windows, silently enveloping the surroundings."
  },
  AvgDialog_18727_Content_17 = {
    Text = "Other than a few drawn-out dog barks, it is eerily silent here."
  },
  AvgDialog_18727_Content_18 = {
    Text = "Pitter-patter..."
  },
  AvgDialog_18727_Content_19 = {
    Text = "Hmm, is it raining?"
  },
  AvgDialog_18727_Content_2 = {
    Text = [[
Belen Stock, 46, died at home in the kitchen on September 12.
<Red:Head missing>, body intact except for a jagged cut on the neck.]]
  },
  AvgDialog_18727_Content_20 = {
    Text = "A fine, cool rain drips from the night sky, casting a white veil before you."
  },
  AvgDialog_18727_Content_21 = {
    Text = "I hear rain on your side. Do you have an umbrella?"
  },
  AvgDialog_18727_Content_22 = {
    Text = "<Shake:Oh no. You're always the one who brings an umbrella, so...>"
  },
  AvgDialog_18727_Content_23 = {
    Text = "Looks like I still need to get used to life without you."
  },
  AvgDialog_18727_Content_24 = {Text = "..."},
  AvgDialog_18727_Content_25 = {
    Text = "Sorry, I couldn't go with you this time."
  },
  AvgDialog_18727_Content_26 = {
    Text = "Miss Doll insists that I stay to conduct some supposedly \"important\" Dissolution research with her..."
  },
  AvgDialog_18727_Content_27 = {
    Text = "<Small:Ramona, could you hand me the Silver sample on the third shelf of the fifth row, code SI-3007...>"
  },
  AvgDialog_18727_Content_28 = {Text = "..."},
  AvgDialog_18727_Content_29 = {
    Text = "Take care of yourself, %player%. As for accommodation... <Blue:Miss Horla> will arrange everything."
  },
  AvgDialog_18727_Content_3 = {
    Text = [[
Dwight Williams, 56, died at the Deman Street intersection on September 13.
<Red:Head Missing>, body intact with a jagged cut on the neck.]]
  },
  AvgDialog_18727_Content_30 = {
    Text = "Miss Horla? No wonder we rarely see her at school; she lives outside?"
  },
  AvgDialog_18727_Content_31 = {
    Text = "Mythag is not some one-way camp."
  },
  AvgDialog_18727_Content_32 = {
    Text = [[
Low-risk Awakeners can go on vacation, stay overnight, or visit family.
The condition is simple: apply in advance and avoid causing trouble.]]
  },
  AvgDialog_18727_Content_33 = {
    Text = "Uh... So Miss Horla will also participate in the investigation?"
  },
  AvgDialog_18727_Content_34 = {
    Text = "Not all Awakeners are interested in field missions. If you think it's necessary, ask her for her opinion."
  },
  AvgDialog_18727_Content_35 = {
    Text = "The current situation is stable and manageable, no need to—"
  },
  AvgDialog_18727_Content_36 = {Text = "Whoosh—"},
  AvgDialog_18727_Content_37 = {
    Text = "Suddenly, the sound of flesh splattering came from the alley ahead, followed by chaotic footsteps, abruptly breaking the night's silence."
  },
  AvgDialog_18727_Content_38 = {Text = "?!"},
  AvgDialog_18727_Content_39 = {
    Text = "At this time, this noise... Could it be...?"
  },
  AvgDialog_18727_Content_4 = {
    Text = "Deceased No. 012, identity and age unknown, died by Lake Knerl in the north on the early morning of September 16..."
  },
  AvgDialog_18727_Content_40 = {
    Text = "Let's follow and take a look. Remember to stay in touch."
  },
  AvgDialog_18727_Content_41 = {
    Text = "May the Silver Key light our path."
  },
  AvgDialog_18727_Content_5 = {
    Text = [[
20:00, Norwich Street
Rainy Town]]
  },
  AvgDialog_18727_Content_6 = {
    Text = "Missing head, jagged scars..."
  },
  AvgDialog_18727_Content_7 = {
    Text = "And all died either while going out alone or at home."
  },
  AvgDialog_18727_Content_8 = {
    Text = "Additionally, a week after Dwight Williams' death, his wife claimed to have seen him running hurriedly in the wilderness."
  },
  AvgDialog_18727_Content_9 = {
    Text = "...Resurrected?"
  },
  AvgDialog_18764_Content_1 = {
    Text = "No, don't..."
  },
  AvgDialog_18764_Content_10 = {
    Text = "Cough, cough... You, how could you cheat!"
  },
  AvgDialog_18764_Content_11 = {
    Text = "<SmallShake:It's just a guessing game, what's worrying you so much...>"
  },
  AvgDialog_18764_Content_12 = {
    Text = "Where is the exit of the maze?"
  },
  AvgDialog_18764_Content_13 = {
    Text = "Hehe, curious? Then get on your knees, apologize to me properly, and then..."
  },
  AvgDialog_18764_Content_14 = {
    Text = "You slowly raise your hand."
  },
  AvgDialog_18764_Content_15 = {
    Text = "<Shake:Wait, wait! I mean...>"
  },
  AvgDialog_18764_Content_16 = {
    Text = "The girl opened her mouth and lowered her head in frustration."
  },
  AvgDialog_18764_Content_17 = {
    Text = "Actually... I don't know either. I've been imprisoned here for nearly a thousand years..."
  },
  AvgDialog_18764_Content_18 = {
    Text = "Apart from sleeping and daydreaming, managing my offspring is driving me crazy with boredom!"
  },
  AvgDialog_18764_Content_19 = {Text = "..."},
  AvgDialog_18764_Content_20 = {
    Text = "Aren't you the master of the maze? How could you not know where the exit is?"
  },
  AvgDialog_18764_Content_21 = {
    Text = "<SmallShake:You should ask the person who threw me in here. How would I know what they're thinking...>"
  },
  AvgDialog_18764_Content_22 = {
    Text = "How could this happen...?"
  },
  AvgDialog_18764_Content_23 = {
    Text = "So, let's say, hypothetically speaking—"
  },
  AvgDialog_18764_Content_24 = {
    Text = "Those who enter the maze are not physical entities but exist in some form of ideology."
  },
  AvgDialog_18764_Content_25 = {
    Text = "Could he, uh, like... ignore the rules of this maze?"
  },
  AvgDialog_18764_Content_26 = {
    Text = "Agrippa gave you a strange look."
  },
  AvgDialog_18764_Content_27 = {
    Text = "Of course not."
  },
  AvgDialog_18764_Content_28 = {
    Text = "Wanna guess why you see so many familiar people and places in the maze?"
  },
  AvgDialog_18764_Content_29 = {
    Text = "Phantasm? No, it's memory..."
  },
  AvgDialog_18764_Content_3 = {
    Text = "You've finally cleaned up the last \"Charlotte.\""
  },
  AvgDialog_18764_Content_30 = {
    Text = "Agrippa shook his head."
  },
  AvgDialog_18764_Content_31 = {
    Text = "Neither. To be precise, it's <Yellow:awareness>."
  },
  AvgDialog_18764_Content_32 = {
    Text = "<Yellow:Only your consciousness is trapped in the maze.>"
  },
  AvgDialog_18764_Content_4 = {
    Text = "The Key Tomb gradually fades away, and you find yourself back where you started."
  },
  AvgDialog_18764_Content_5 = {
    Text = "Come out, I know where you are."
  },
  AvgDialog_18764_Content_6 = {
    Text = "A trembling hum resonates from deep underground, followed by the ground gradually cracking open."
  },
  AvgDialog_18764_Content_7 = {Text = "Boom!!"},
  AvgDialog_18764_Content_8 = {
    Text = "Pfft... bleh bleh bleh!!"
  },
  AvgDialog_18764_Content_9 = {
    Text = "Agrippa suddenly bursts out from the ground, covered in dust."
  },
  AvgDialog_18765_Content_1 = {Text = "Hive-mind"},
  AvgDialog_18765_Content_10 = {
    Text = "Did you do this week's assignments? The \"Intro to Dissolution\" exam is coming up. How's your revision?"
  },
  AvgDialog_18765_Content_11 = {
    Text = "Ramona?! No, I didn't... wait..."
  },
  AvgDialog_18765_Content_12 = {
    Text = "%player%, you were 5 minutes late for class today. Your total lateness this month has reached 30 minutes and 15 seconds."
  },
  AvgDialog_18765_Content_13 = {
    Text = "Come to my office after class."
  },
  AvgDialog_18765_Content_14 = {Text = "—!!"},
  AvgDialog_18765_Content_15 = {
    Text = "Pfft. <Big:Hahahahaha!>"
  },
  AvgDialog_18765_Content_16 = {
    Text = "Scared, huh? You really should look in the mirror and see what you look like now."
  },
  AvgDialog_18765_Content_17 = {Text = "..."},
  AvgDialog_18765_Content_18 = {
    Text = "Where did you learn these... tricks of transformation?"
  },
  AvgDialog_18765_Content_19 = {
    Text = "You've seen Agrippa's file in the Awakener Archives; it mentioned nothing about \"transformation.\""
  },
  AvgDialog_18765_Content_20 = {
    Text = "Study? I am the master of this maze. In my domain, I can do as I please."
  },
  AvgDialog_18765_Content_21 = {
    Text = "Don't just transform one... I can show you ten, even a hundred."
  },
  AvgDialog_18765_Content_22 = {
    Text = "After speaking, Agrippa disappeared again."
  },
  AvgDialog_18765_Content_23 = {
    Text = "In no time, one, two... more Charlottes appear before you."
  },
  AvgDialog_18765_Content_24 = {
    Text = "Guess which one is the real me, hehe..."
  },
  AvgDialog_18765_Content_25 = {
    Text = "Boohoo... Which Charlotte is Agrippa?"
  },
  AvgDialog_18765_Content_26 = {
    Text = "Only once, just one chance..."
  },
  AvgDialog_18765_Content_27 = {
    Text = "Countless piercing voices intertwine into a chaotic melody, lingering in your mind."
  },
  AvgDialog_18765_Content_28 = {
    Text = "Get... Get away...!!"
  },
  AvgDialog_18765_Content_29 = {
    Text = "You take a deep breath and finally steady your mind."
  },
  AvgDialog_18765_Content_3 = {
    Text = "Charlotte, how did you end up like this?"
  },
  AvgDialog_18765_Content_30 = {
    Text = "Sorry. You all look the same; I can't tell."
  },
  AvgDialog_18765_Content_31 = {
    Text = "Huh? Giving up already? How boring."
  },
  AvgDialog_18765_Content_33 = {
    Text = "In the next second, \"Charlotte\" was knocked to the ground.\nYou rubbed your temples and calmly said—"
  },
  AvgDialog_18765_Content_34 = {
    Text = "But it's alright."
  },
  AvgDialog_18765_Content_35 = {
    Text = "I can knock all of you down and question each of you one by one."
  },
  AvgDialog_18765_Content_4 = {
    Text = "\"Charlotte\" twists her head, emitting a spine-chilling hum from deep within her throat."
  },
  AvgDialog_18765_Content_5 = {
    Text = "<Shake:Hehe, surprised? Your so-called friend has long become my descendant!>"
  },
  AvgDialog_18765_Content_6 = {
    Text = "That voice... Are you Agrippa?"
  },
  AvgDialog_18765_Content_7 = {
    Text = [[
It's touching that you still remember my voice.
Wait, let me show you something incredible!]]
  },
  AvgDialog_18765_Content_8 = {
    Text = "A muffled chuckle emerged from Charlotte's throat, then she twisted her neck, instantly changing her appearance."
  },
  AvgDialog_18765_Content_9 = {
    Text = "%player%, you're sneaking cupcakes again!"
  },
  AvgDialog_18766_Content_1 = {Text = "Gate"},
  AvgDialog_18766_Content_10 = {
    Text = "Are you ready, @1? Let's push it together."
  },
  AvgDialog_18766_Content_11 = {
    Text = "Creak—Yaa—"
  },
  AvgDialog_18766_Content_12 = {Text = "<Big:!!!>"},
  AvgDialog_18766_Content_13 = {
    Text = "Where... is this place...?"
  },
  AvgDialog_18766_Content_14 = {
    Text = "This is where you'll obediently stay for the rest of your life."
  },
  AvgDialog_18766_Content_15 = {
    Text = "The girl sits on the hollow platform, her hands cupping her cheeks, her right leg swinging idly as she smiles."
  },
  AvgDialog_18766_Content_16 = {
    Text = "Welcome to my maze."
  },
  AvgDialog_18766_Content_17 = {
    Text = "You slept so soundly; I was about to feed you some bugs to refresh your spirit."
  },
  AvgDialog_18766_Content_18 = {
    Text = "<LightGray:Agrippa...?>"
  },
  AvgDialog_18766_Content_19 = {
    Text = "You glance down at your unfamiliar attire and realize you've entered a dream once more."
  },
  AvgDialog_18766_Content_2 = {
    Text = "People say that in \"His\" maze, what gets lost is not just the direction."
  },
  AvgDialog_18766_Content_20 = {
    Text = [[
This time, you've almost lost all memories of the original host.
Who is she? Where is she from?]]
  },
  AvgDialog_18766_Content_21 = {
    Text = "You know nothing."
  },
  AvgDialog_18766_Content_22 = {
    Text = "<Shake:What's going on... The original owner? No, who am I...>"
  },
  AvgDialog_18766_Content_23 = {
    Text = "Alright, stop thinking. You won't remember a thing."
  },
  AvgDialog_18766_Content_24 = {
    Text = "Even after 1 day, 100 days, or 1000 days, your mind will remain as pure as that of a newborn baby."
  },
  AvgDialog_18766_Content_25 = {
    Text = "Now, I will give you two choices."
  },
  AvgDialog_18766_Content_26 = {
    Text = "<Red:One: Make a contract with me and become my child.>"
  },
  AvgDialog_18766_Content_27 = {
    Text = "<Red:Two: Starve to death in the maze and then become my offspring.>"
  },
  AvgDialog_18766_Content_28 = {
    Text = "Agrippa skillfully clarifies the situation for you and presents options, as if this process has been repeated countless times."
  },
  AvgDialog_18766_Content_29 = {
    Text = "Offspring? What is that?"
  },
  AvgDialog_18766_Content_3 = {
    Text = "Name, hometown, lover... Everything important and unimportant will all be left behind."
  },
  AvgDialog_18766_Content_30 = {
    Text = "Rest assured, it's non-toxic, painless, and harmless. As for side effects? You won't even notice their presence."
  },
  AvgDialog_18766_Content_31 = {
    Text = "How about it? Compared to those evil gods who demand life sacrifices and force you to slay your loved ones, aren't I much gentler?"
  },
  AvgDialog_18766_Content_32 = {Text = "..."},
  AvgDialog_18766_Content_33 = {
    Text = "Now, I'll give you three seconds to choose. Sign the contract or starve?"
  },
  AvgDialog_18766_Content_34 = {Text = "Three —"},
  AvgDialog_18766_Content_35 = {Text = "Two—"},
  AvgDialog_18766_Content_36 = {
    Text = "Alright, I've made my decision."
  },
  AvgDialog_18766_Content_37 = {Text = "Uh...?"},
  AvgDialog_18766_Content_38 = {
    Text = "You're decisive... not bad. So, tell me your choice."
  },
  AvgDialog_18766_Content_39 = {
    Text = "You nod and quietly shift your right foot back a little."
  },
  AvgDialog_18766_Content_4 = {
    Text = "From now on, you have only one identity: <Red:His Offspring>."
  },
  AvgDialog_18766_Content_40 = {
    Text = "My choice is—"
  },
  AvgDialog_18766_Content_41 = {
    Text = "You decisively turned around and dashed out at the fastest speed."
  },
  AvgDialog_18766_Content_42 = {
    Text = "<BigShake:Run!!>"
  },
  AvgDialog_18766_Content_43 = {
    Text = "A very, very long time later..."
  },
  AvgDialog_18766_Content_44 = {
    Text = "Huff... huff..."
  },
  AvgDialog_18766_Content_45 = {
    Text = "You run down the long corridor until a door blocks your way."
  },
  AvgDialog_18766_Content_46 = {
    Text = "Wax Museum? Not again..."
  },
  AvgDialog_18766_Content_47 = {
    Text = "If I remember correctly, this is the 23rd time I've seen it."
  },
  AvgDialog_18766_Content_48 = {
    Text = "Yes, there are countless doors leading to countless spaces."
  },
  AvgDialog_18766_Content_49 = {
    Text = "They repeatedly appear before you with such frequency that it could drive even the calmest Investigator mad."
  },
  AvgDialog_18766_Content_5 = {
    Text = "<Shake:Child, heir?>"
  },
  AvgDialog_18766_Content_50 = {
    Text = "You push the door open and continue down the corridor."
  },
  AvgDialog_18766_Content_51 = {
    Text = "This hallway again... 15 times."
  },
  AvgDialog_18766_Content_52 = {
    Text = "You instinctively touched the silver cufflinks embedded in your sleeve."
  },
  AvgDialog_18766_Content_53 = {
    Text = "Mythag's early school emblem... It seems I've become a predecessor from the past this time?"
  },
  AvgDialog_18766_Content_54 = {
    Text = "But how did she enter the maze?"
  },
  AvgDialog_18766_Content_55 = {
    Text = "As you contemplate, another door blocks your way."
  },
  AvgDialog_18766_Content_56 = {
    Text = "You are now standing in front of this door, @1. Open it."
  },
  AvgDialog_18766_Content_57 = {
    Text = "Who's speaking?!"
  },
  AvgDialog_18766_Content_58 = {
    Text = "My head... it hurts. Are these the memories of that upperclassman girl?"
  },
  AvgDialog_18766_Content_59 = {
    Text = "Take a deep breath, %player%. Clear your mind..."
  },
  AvgDialog_18766_Content_6 = {
    Text = "Yes. The offspring swarm into the maze like a pale tide, flooding in from all directions."
  },
  AvgDialog_18766_Content_60 = {
    Text = "You force yourself to calm down, twist the brass handle, and gently pull the door open."
  },
  AvgDialog_18766_Content_61 = {
    Text = "...Key Tomb?"
  },
  AvgDialog_18766_Content_62 = {
    Text = "Amidst the mist, you notice a figure that is both familiar and strange."
  },
  AvgDialog_18766_Content_63 = {
    Text = "Charlotte... <Big:Charlotte!>"
  },
  AvgDialog_18766_Content_64 = {
    Text = "You remember the girl named Charlotte. She was the friend who led \"you\" into the maze."
  },
  AvgDialog_18766_Content_65 = {
    Text = "<Big:Wait for me, Charlotte!>"
  },
  AvgDialog_18766_Content_66 = {
    Text = "You rush forward and grab Charlotte's wrist."
  },
  AvgDialog_18766_Content_67 = {
    Text = "The instant our skin made contact, countless chaotic fragments flashed through my mind."
  },
  AvgDialog_18766_Content_68 = {
    Text = "Open the door, @1."
  },
  AvgDialog_18766_Content_69 = {
    Text = "<Shake:No, I-I just remembered I haven't finished my homework. I want to—>"
  },
  AvgDialog_18766_Content_7 = {
    Text = "Entrances to the maze are everywhere: inside walls, in the sewers, and even where we are now..."
  },
  AvgDialog_18766_Content_70 = {
    Text = "<Big:Ahhh!!>"
  },
  AvgDialog_18766_Content_71 = {
    Text = "<Shake:Charlotte, your face...>"
  },
  AvgDialog_18766_Content_72 = {
    Text = "Door... Door..."
  },
  AvgDialog_18766_Content_73 = {
    Text = "@1 Door @2 Open @4"
  },
  AvgDialog_18766_Content_74 = {
    Text = "<RedBig:Open the door...>"
  },
  AvgDialog_18766_Content_75 = {
    Text = "I see. So it was you who tricked \"me\" into the maze..."
  },
  AvgDialog_18766_Content_76 = {
    Text = "You instinctively released Charlotte's wrist and stepped back a few paces."
  },
  AvgDialog_18766_Content_77 = {
    Text = "The mist gradually dissipates. With some effort, Charlotte turns around and looks at you sorrowfully."
  },
  AvgDialog_18766_Content_78 = {
    Text = "...@4 Gate@4@1"
  },
  AvgDialog_18766_Content_79 = {
    Text = "—With her pitch-black eye sockets."
  },
  AvgDialog_18766_Content_8 = {
    Text = "<Blue:City Library> behind the hidden door underground."
  },
  AvgDialog_18766_Content_9 = {
    Text = "<Shake:I can't believe such a place actually exists... The legends are true...>"
  },
  AvgDialog_18767_Content_1 = {
    Text = "Labyrinth's end"
  },
  AvgDialog_18767_Content_10 = {
    Text = "Shh... Close your eyes, clear your mind, and think of nothing."
  },
  AvgDialog_18767_Content_11 = {
    Text = "Don't do anything..."
  },
  AvgDialog_18767_Content_12 = {Text = "Hmm!!"},
  AvgDialog_18767_Content_13 = {
    Text = "My head is about to split... I'd better not use this method too often..."
  },
  AvgDialog_18767_Content_14 = {
    Text = "<Shake:Out of my way, all of you!>"
  },
  AvgDialog_18767_Content_15 = {
    Text = "Whoever dares to harm my family, I'll be the first to kill that swine!!"
  },
  AvgDialog_18767_Content_16 = {
    Text = "A trembling blade instantly presses against your throat."
  },
  AvgDialog_18767_Content_17 = {Text = "...?"},
  AvgDialog_18767_Content_18 = {
    Text = "Entered the dream successfully—though not in the way you imagined."
  },
  AvgDialog_18767_Content_19 = {
    Text = "Ahead stands a dense crowd of bare-chested slaves. Their usual docility is long gone, replaced by a burning hatred in their eyes."
  },
  AvgDialog_18767_Content_2 = {
    Text = "You mean you can infiltrate my mind and change the past?"
  },
  AvgDialog_18767_Content_20 = {
    Text = "Faced with Agrippa's threat, they first fell silent, then burst into laughter."
  },
  AvgDialog_18767_Content_21 = {
    Text = "Pfft. Hahahaha!"
  },
  AvgDialog_18767_Content_22 = {
    Text = "How about that, our little princess sure has courage!"
  },
  AvgDialog_18767_Content_23 = {
    Text = "Heh. You don't believe me, do you...?"
  },
  AvgDialog_18767_Content_24 = {
    Text = "A swift slash of the blade, and your neck is instantly wracked with pain."
  },
  AvgDialog_18767_Content_25 = {
    Text = "Hmm! You're serious!!"
  },
  AvgDialog_18767_Content_26 = {
    Text = "<Big:Shut up!> You and they are clearly in cahoots. You're the one who stole my house key and the indenture!"
  },
  AvgDialog_18767_Content_27 = {Text = "...?"},
  AvgDialog_18767_Content_28 = {
    Text = "And you all! If anyone laughs again, I'll cut another line on {Male=his,Female=her} neck!"
  },
  AvgDialog_18767_Content_29 = {
    Text = "Put down the knife, Agrippa... <Big:Run!>"
  },
  AvgDialog_18767_Content_3 = {
    Text = "If you're really that powerful, how did I manage to trap you?"
  },
  AvgDialog_18767_Content_31 = {
    Text = "The whip struck the woman fiercely, knocking her unconscious before she could utter a sound."
  },
  AvgDialog_18767_Content_32 = {
    Text = "<Big:Mother!!>"
  },
  AvgDialog_18767_Content_33 = {
    Text = "Put away your laughable antics; we are no longer your slaves."
  },
  AvgDialog_18767_Content_34 = {
    Text = "How did you not think about today when you were showing off in the training ground back then?"
  },
  AvgDialog_18767_Content_35 = {
    Text = "Open your eyes and take a good look, \"Little Princess.\" Watch how we humiliate you..."
  },
  AvgDialog_18767_Content_36 = {
    Text = "<Shake:Cowards, a bunch of cowards! How dare you...>"
  },
  AvgDialog_18767_Content_37 = {
    Text = "<Shake:It was me who bullied you, not them... No, I was too foolish. I shouldn't have treated you that way...>"
  },
  AvgDialog_18767_Content_38 = {
    Text = "<Shake:Come at me, do whatever you want! Just let my mother go...>"
  },
  AvgDialog_18767_Content_39 = {
    Text = "The girl was already so flustered that she couldn't speak coherently, her dagger trembling violently and almost slipping from her grasp."
  },
  AvgDialog_18767_Content_4 = {
    Text = "Ahem... To be precise, it's influence, not change."
  },
  AvgDialog_18767_Content_40 = {
    Text = "You let out a soft sigh and gently take the dagger from her hand."
  },
  AvgDialog_18767_Content_41 = {
    Text = "Don't be afraid, Agrippa. I'll help you."
  },
  AvgDialog_18767_Content_42 = {
    Text = "Help me? Aren't you..."
  },
  AvgDialog_18767_Content_43 = {
    Text = "You stand before Agrippa, looking directly at the slaves in front of you."
  },
  AvgDialog_18767_Content_44 = {
    Text = [[
Alright, game time is over.
You've gotten what you wanted, so you can leave now.]]
  },
  AvgDialog_18767_Content_45 = {
    Text = "Yo, someone's acting like the boss and giving us a lecture."
  },
  AvgDialog_18767_Content_46 = {
    Text = "Cress, aren't you supposed to be on our side?"
  },
  AvgDialog_18767_Content_47 = {
    Text = "You shook your head."
  },
  AvgDialog_18767_Content_48 = {
    Text = "I have always respected your cause of resistance, but no one has the right to kill the innocent."
  },
  AvgDialog_18767_Content_49 = {
    Text = "\"Innocent\"...?"
  },
  AvgDialog_18767_Content_5 = {
    Text = "Don't underestimate yourself; your maze is much more complex than I thought..."
  },
  AvgDialog_18767_Content_50 = {
    Text = "Hehe, this guy has completely betrayed us. No need to waste any more words."
  },
  AvgDialog_18767_Content_51 = {
    Text = "<Big:Kill him!>"
  },
  AvgDialog_18767_Content_6 = {
    Text = "Agrippa looks at you with suspicion."
  },
  AvgDialog_18767_Content_7 = {
    Text = [[
Alright, there's no other way anyway.
What do you need me to do?]]
  },
  AvgDialog_18767_Content_8 = {
    Text = "You try to recall your state every time you enter a dream, gently holding Agrippa's hand."
  },
  AvgDialog_18767_Content_9 = {
    Text = "Hey, you! Are you trying to take advantage of me?"
  },
  AvgDialog_18768_Content_1 = {
    Text = "Cough... Cough..."
  },
  AvgDialog_18768_Content_10 = {
    Text = "The distant sound of a low horn reaches you; the rebels are still in pursuit."
  },
  AvgDialog_18768_Content_11 = {
    Text = "You and Agrippa run hand in hand beneath the pitch-black sky."
  },
  AvgDialog_18768_Content_12 = {
    Text = "Her family is not far from you. Driven by fear and hope, they are running toward a horizon with no end in sight."
  },
  AvgDialog_18768_Content_13 = {
    Text = "Who are you? Why did you save me?"
  },
  AvgDialog_18768_Content_14 = {
    Text = "Hmm... to be precise, it's to save myself."
  },
  AvgDialog_18768_Content_15 = {
    Text = "Oh... whatever the reason, you... did great."
  },
  AvgDialog_18768_Content_16 = {
    Text = "When we are rescued, I will give you all the money and jewels I have stashed away over the years."
  },
  AvgDialog_18768_Content_17 = {
    Text = "You couldn't help but laugh."
  },
  AvgDialog_18768_Content_18 = {
    Text = "I don't need your money. However... if you wish to repay me, I do have one request."
  },
  AvgDialog_18768_Content_19 = {
    Text = "Tell me, I'm sure I can do it."
  },
  AvgDialog_18768_Content_2 = {
    Text = "Out of respect for old times, the brothers refrained from using lethal force."
  },
  AvgDialog_18768_Content_20 = {
    Text = "A shooting star streaks across the night sky—it's the perfect moment to make a wish."
  },
  AvgDialog_18768_Content_21 = {
    Text = "My request is simple. Keep smiling and remember how you feel right now."
  },
  AvgDialog_18768_Content_22 = {
    Text = "Current feelings? Hmm... Happy, relieved, worried? Which one do you mean!"
  },
  AvgDialog_18768_Content_23 = {
    Text = "Suit yourself. I'm curious which Agrippa they will lead me to."
  },
  AvgDialog_18768_Content_24 = {Text = "?"},
  AvgDialog_18768_Content_25 = {
    Text = "<SmallShake:This guy is a good person, but he talks a bit strangely...>"
  },
  AvgDialog_18768_Content_26 = {
    Text = "The sound of horns finally faded, and the tranquility of the night returned."
  },
  AvgDialog_18768_Content_27 = {
    Text = "Finally... it's over."
  },
  AvgDialog_18768_Content_28 = {
    Text = "The girl ran up to the top of the dune in a few quick steps, clenched her fists, and shouted towards where the horn had disappeared."
  },
  AvgDialog_18768_Content_29 = {
    Text = "Never expected this, you @2, I made it to the very end!"
  },
  AvgDialog_18768_Content_3 = {
    Text = "Since you insist on helping them, don't blame us for being impolite—"
  },
  AvgDialog_18768_Content_30 = {
    Text = "Hahaha, @2!"
  },
  AvgDialog_18768_Content_31 = {
    Text = "<Shake:Agrippa! Lady, lady...!>"
  },
  AvgDialog_18768_Content_32 = {
    Text = "Can't hear!!!"
  },
  AvgDialog_18768_Content_33 = {
    Text = "To hell with being a lady and etiquette, I'm finally free!!"
  },
  AvgDialog_18768_Content_34 = {
    Text = "With a powerful declaration, the girl spread her arms wide, lifting the vast starry sky above her head as if holding it in her hands."
  },
  AvgDialog_18768_Content_35 = {
    Text = "<Big:Freedom—!!>"
  },
  AvgDialog_18768_Content_36 = {
    Text = "Splash—!!"
  },
  AvgDialog_18768_Content_37 = {Text = "...Huh?"},
  AvgDialog_18768_Content_38 = {
    Text = "The sky disappeared, and the maze vanished."
  },
  AvgDialog_18768_Content_39 = {
    Text = "The Cambrian Valley comes directly into view."
  },
  AvgDialog_18768_Content_4 = {Text = "Boom!"},
  AvgDialog_18768_Content_40 = {
    Text = "The deep, mirror-like lake flows quietly, with the wind blowing across the water and creating ripples of light."
  },
  AvgDialog_18768_Content_41 = {
    Text = "Agrippa sat dazed on the grass, staring blankly at everything before him."
  },
  AvgDialog_18768_Content_42 = {
    Text = "%player%, are we... out of here?"
  },
  AvgDialog_18768_Content_43 = {
    Text = "Welcome back to the real world, Agrippa."
  },
  AvgDialog_18768_Content_44 = {Text = "...Oh."},
  AvgDialog_18768_Content_45 = {
    Text = "So this is the River Valley. It's a hundred times more beautiful than people say, no, a thousand times more beautiful."
  },
  AvgDialog_18768_Content_46 = {
    Text = "The faint morning light pierces the mist, shining on your body."
  },
  AvgDialog_18768_Content_47 = {
    Text = "Agrippa closed his eyes, greedily savoring those long-lost scents."
  },
  AvgDialog_18768_Content_48 = {
    Text = "I smell so many things. Soil, grass, freesia, and sunshine..."
  },
  AvgDialog_18768_Content_49 = {
    Text = "Does sunlight have a taste?"
  },
  AvgDialog_18768_Content_5 = {
    Text = "You take advantage of the chaos to push down the pillar in front, causing the entire building to start swaying precariously."
  },
  AvgDialog_18768_Content_50 = {
    Text = "Hmm. The scent makes one feel drowsy."
  },
  AvgDialog_18768_Content_51 = {
    Text = "Thank you, %player%."
  },
  AvgDialog_18768_Content_52 = {
    Text = "She stretched and softly hummed an ancient Roman melody."
  },
  AvgDialog_18768_Content_53 = {
    Text = "A light melody swirled in the air, spreading the owner's cheerful mood to every corner of the valley."
  },
  AvgDialog_18768_Content_54 = {
    Text = "After more than a thousand years, she finally saw the sunlight once again."
  },
  AvgDialog_18768_Content_55 = {
    Text = "And finally, saw the river valley for the first time."
  },
  AvgDialog_18768_Content_6 = {
    Text = "Now, follow me quickly!"
  },
  AvgDialog_18768_Content_7 = {
    Text = "You grab Agrippa's hand and hurriedly leave with her family."
  },
  AvgDialog_18768_Content_8 = {
    Text = "This once incredibly magnificent courtyard collapsed like a silent, giant beast."
  },
  AvgDialog_18768_Content_9 = {
    Text = "16 years before the Flood @1, outskirts of Kapua"
  },
  AvgDialog_18769_Content_1 = {
    Text = "Memory barrier"
  },
  AvgDialog_18769_Content_10 = {
    Text = "You@1, what are you saying—"
  },
  AvgDialog_18769_Content_11 = {
    Text = "Forget it, don't get involved with that guy. He's just a madman..."
  },
  AvgDialog_18769_Content_12 = {
    Text = "The slaves jostled each other as they left, and the dark cell finally fell silent."
  },
  AvgDialog_18769_Content_13 = {
    Text = "The girl walked out from the shadows in the corner of her cell, her head hanging down."
  },
  AvgDialog_18769_Content_14 = {
    Text = "Why not leave with them? Tonight is your chance to regain freedom."
  },
  AvgDialog_18769_Content_15 = {
    Text = "I like it here. Why leave?"
  },
  AvgDialog_18769_Content_16 = {
    Text = "Like it...? Haha, impressive. Do you prefer being scolded, or do you like the feel of my whip?"
  },
  AvgDialog_18769_Content_17 = {
    Text = "The gladiator yawned and stretched comfortably."
  },
  AvgDialog_18769_Content_18 = {
    Text = "I love blood, and I love killing even more. For me, killing is freedom."
  },
  AvgDialog_18769_Content_19 = {
    Text = "As for the title of a slave, I don't care how many you give me. Why leave?"
  },
  AvgDialog_18769_Content_2 = {
    Text = "16 years before the Great Flood, Year 1, Capua"
  },
  AvgDialog_18769_Content_20 = {Text = "..."},
  AvgDialog_18769_Content_21 = {
    Text = "Heh... Now I see you in a different light. You're a genuine madman."
  },
  AvgDialog_18769_Content_22 = {
    Text = "Agrippa looked up at the dungeon's exit, his expression extremely calm."
  },
  AvgDialog_18769_Content_23 = {
    Text = "A crimson wave of fire surged towards the sky, accompanied by laughter, cries, and screams... a symphony of diverse sounds from Hell."
  },
  AvgDialog_18769_Content_24 = {
    Text = "Soon, they'll find me, @1 me, and cut off my head, just like they did to my parents."
  },
  AvgDialog_18769_Content_25 = {
    Text = "I don't want these lowly creatures near me. But you..."
  },
  AvgDialog_18769_Content_26 = {
    Text = [[
You are different from them.
I know we've had some "issues" before, but this time, you definitely won't refuse my request.]]
  },
  AvgDialog_18769_Content_27 = {
    Text = "Oh? Do tell."
  },
  AvgDialog_18769_Content_28 = {Text = "..."},
  AvgDialog_18769_Content_29 = {Text = "Kill me."},
  AvgDialog_18769_Content_3 = {
    Text = "Damn it, the woman has disappeared."
  },
  AvgDialog_18769_Content_30 = {
    Text = "<RedBig:Kill me...>"
  },
  AvgDialog_18769_Content_31 = {
    Text = "Agrippa...?"
  },
  AvgDialog_18769_Content_32 = {
    Text = "<RedBig:Kill me... kill me... kill me...>"
  },
  AvgDialog_18769_Content_33 = {Text = "Agrippa!"},
  AvgDialog_18769_Content_34 = {Text = "!!"},
  AvgDialog_18769_Content_35 = {
    Text = "<Shake:Hmm...>"
  },
  AvgDialog_18769_Content_36 = {
    Text = "I had such a long, long dream..."
  },
  AvgDialog_18769_Content_37 = {
    Text = "Listen, it seems we overlooked some issues just now."
  },
  AvgDialog_18769_Content_38 = {
    Text = "Nonsense! I am the mighty Lord of the Maze, and everything is under my control—"
  },
  AvgDialog_18769_Content_39 = {
    Text = "First, why can your offspring freely enter and exit the maze, but you and I cannot?"
  },
  AvgDialog_18769_Content_4 = {
    Text = "Heh, so now you're hiding, are you? Once we find her, we'll cut off her legs first..."
  },
  AvgDialog_18769_Content_40 = {
    Text = "Can't you share your consciousness?"
  },
  AvgDialog_18769_Content_41 = {
    Text = "What do you know? As the master of the maze, I must always remain mysterious."
  },
  AvgDialog_18769_Content_42 = {
    Text = "Besides, as long as I wish, they all have to return obediently. Is this what you call \"free access\"?"
  },
  AvgDialog_18769_Content_43 = {
    Text = "You nod and take out your notebook once again."
  },
  AvgDialog_18769_Content_44 = {
    Text = "One more question."
  },
  AvgDialog_18769_Content_45 = {
    Text = "I recorded all the places I encountered in the maze: the school, the wax museum, and the streets of Londinium..."
  },
  AvgDialog_18769_Content_46 = {
    Text = "None of the places you haven't experienced. Not a single one."
  },
  AvgDialog_18769_Content_47 = {
    Text = "Why, aren't you trapped here as well?"
  },
  AvgDialog_18769_Content_48 = {
    Text = "Why so many \"why\"s? Because this great king doesn't want to recall! Why bother thinking about unpleasant things?"
  },
  AvgDialog_18769_Content_49 = {
    Text = "Yes, <Yellow:you don't want to remember>."
  },
  AvgDialog_18769_Content_5 = {
    Text = "Hey, Uvhash, have you seen Agrippa?"
  },
  AvgDialog_18769_Content_50 = {
    Text = "Is there a possibility that..."
  },
  AvgDialog_18769_Content_51 = {
    Text = "It is precisely because of your resistance—the Maze Master's rejection of the shared consciousness—that this maze, formed from the minds of the trapped, remains forever incomplete."
  },
  AvgDialog_18769_Content_52 = {
    Text = "So we can never get out."
  },
  AvgDialog_18769_Content_53 = {Text = "..."},
  AvgDialog_18769_Content_54 = {
    Text = "I've thought about these issues before. This is my maze."
  },
  AvgDialog_18769_Content_55 = {
    Text = "Just thinking about the past drives me crazy..."
  },
  AvgDialog_18769_Content_56 = {
    Text = "Agrippa clutched his head, muttering rapidly as if in a dream."
  },
  AvgDialog_18769_Content_57 = {
    Text = "Those despicable wretches... How dare they treat me this way..."
  },
  AvgDialog_18769_Content_58 = {
    Text = "Just a bunch of slaves, not even worthy of being called human, destined to be trampled underfoot by us for eternity."
  },
  AvgDialog_18769_Content_59 = {
    Text = "Rebellion? What a fantasy."
  },
  AvgDialog_18769_Content_6 = {
    Text = "The gladiator in the shadows slowly opened his eyes."
  },
  AvgDialog_18769_Content_60 = {
    Text = "But they didn't just stop there. They hung my parents' heads on the city wall, grabbed me by the hair, and forced me to look closely at every detail without missing a single one."
  },
  AvgDialog_18769_Content_61 = {
    Text = "And my sister, Yulia. When I found her, she was covered in @3, and she was so small..."
  },
  AvgDialog_18769_Content_62 = {
    Text = "How ridiculous... Did you really think I would cry?"
  },
  AvgDialog_18769_Content_63 = {
    Text = "No, impossible. I'd rather die than shed a single tear in front of them."
  },
  AvgDialog_18769_Content_64 = {
    Text = "We are descendants of grey wolves. We will die with dignity, like true wolves—something those curs will never understand."
  },
  AvgDialog_18769_Content_65 = {Text = "Hahaha..."},
  AvgDialog_18769_Content_66 = {
    Text = "Agrippa clutched his stomach, laughing until tears flowed."
  },
  AvgDialog_18769_Content_67 = {
    Text = "They must have been so disappointed when they saw my corpse... Haha..."
  },
  AvgDialog_18769_Content_68 = {
    Text = "Agrippa...? Agrippa!"
  },
  AvgDialog_18769_Content_69 = {
    Text = "You grip Agrippa's shoulder tightly, trying to pull her back from the nightmares of the past."
  },
  AvgDialog_18769_Content_7 = {
    Text = "... Get lost."
  },
  AvgDialog_18769_Content_70 = {
    Text = "It's all in the past. No need to mention it."
  },
  AvgDialog_18769_Content_71 = {Text = "..."},
  AvgDialog_18769_Content_72 = {
    Text = "Sorry, Agrippa. I didn't know before... Let's just leave those unpleasant things behind."
  },
  AvgDialog_18769_Content_73 = {
    Text = "You're the lord of the maze; nothing can truly harm you"
  },
  AvgDialog_18769_Content_74 = {Text = "...Hmm."},
  AvgDialog_18769_Content_75 = {
    Text = "Agrippa uncharacteristically fell silent; it seems she has not yet emerged from the shadows of the past."
  },
  AvgDialog_18769_Content_76 = {
    Text = "<LightGray:If only we could change the past... Then we could help her and escape this predicament.>"
  },
  AvgDialog_18769_Content_77 = {
    Text = "<LightGray:No, don't lose heart. Try to think of another way...>"
  },
  AvgDialog_18769_Content_78 = {
    Text = "You desperately search for useful information in your fragmented memories."
  },
  AvgDialog_18769_Content_79 = {
    Text = "Dreaming cannot change the past, but it can influence the future. Therefore, Keepers must learn to exercise restraint while dreaming."
  },
  AvgDialog_18769_Content_8 = {
    Text = "Heh, while everyone else is striving for a noble cause, you're the only one willing to stay and play the loyal dog."
  },
  AvgDialog_18769_Content_80 = {
    Text = "Affecting the future?"
  },
  AvgDialog_18769_Content_81 = {
    Text = "For instance, human memory is like a tranquil lake."
  },
  AvgDialog_18769_Content_82 = {
    Text = "Entering a dream is like throwing a stone into the water; the ripples soon vanish."
  },
  AvgDialog_18769_Content_83 = {
    Text = "But the stone is still there."
  },
  AvgDialog_18769_Content_84 = {
    Text = "That's right. Even if the person who entered the dream remembers nothing after waking up..."
  },
  AvgDialog_18769_Content_85 = {
    Text = "The stone will forever sink into his subconscious, affecting his present."
  },
  AvgDialog_18769_Content_86 = {Text = "!!!"},
  AvgDialog_18769_Content_87 = {
    Text = "Agrippa, I know the way out."
  },
  AvgDialog_18769_Content_9 = {
    Text = "I said, \"Scram.\" Don't you understand?"
  },
  AvgDialog_18770_Content_1 = {
    Text = "Her kingdom"
  },
  AvgDialog_18770_Content_10 = {
    Text = "Useless, useless! Even mathematicians, those clever individuals, were trapped in the maze back then!"
  },
  AvgDialog_18770_Content_11 = {
    Text = "Don't waste your effort on the puzzles that no one can solve."
  },
  AvgDialog_18770_Content_12 = {
    Text = "If you ask me, since neither of us can kill the other, we might as well get along."
  },
  AvgDialog_18770_Content_13 = {
    Text = "Let's chat! Or play cards. What card games do you know?"
  },
  AvgDialog_18770_Content_14 = {
    Text = "Don't be fooled by my time underground; I've mastered card games like no one else!"
  },
  AvgDialog_18770_Content_15 = {
    Text = "Gotta admit, her words hurt you a little."
  },
  AvgDialog_18770_Content_16 = {
    Text = "If no one has solved this maze for so many years, what makes you think you can?"
  },
  AvgDialog_18770_Content_17 = {
    Text = "You don't have the sharp mind that Ramona does."
  },
  AvgDialog_18770_Content_18 = {
    Text = "Thinking this, you collapse onto the soft pillow."
  },
  AvgDialog_18770_Content_19 = {
    Text = [[
I'm not very good at cards. How about we chat instead?
How did you end up trapped in this maze?]]
  },
  AvgDialog_18770_Content_2 = {
    Text = "39, 40, 41..."
  },
  AvgDialog_18770_Content_20 = {Text = "Uh..."},
  AvgDialog_18770_Content_21 = {
    Text = "As if not expecting your question, the multifaceted eyes in the girl's eye sockets collectively paused for a moment."
  },
  AvgDialog_18770_Content_22 = {
    Text = "As you said, we need to get along well. Thus, being honest is the first step."
  },
  AvgDialog_18770_Content_23 = {
    Text = "I say, I say...! It's just a clichéd story."
  },
  AvgDialog_18770_Content_24 = {
    Text = "Back in the day, my family was the wealthiest in Kapua, with a line of servants trailing behind me as far as the eye could see..."
  },
  AvgDialog_18770_Content_25 = {
    Text = "Later, these fools started a revolution, talking about \"liberation\" and \"freedom\"—things I don't understand anyway."
  },
  AvgDialog_18770_Content_26 = {
    Text = "I refuse to die at their hands; let a gladiator be the one to kill me."
  },
  AvgDialog_18770_Content_27 = {
    Text = "Agrippa spoke, spreading his hands toward you."
  },
  AvgDialog_18770_Content_28 = {
    Text = "...When I woke up, I found myself here."
  },
  AvgDialog_18770_Content_29 = {
    Text = "I've heard about this revolution in history class. They say —"
  },
  AvgDialog_18770_Content_3 = {
    Text = "You quickly jot down the notes in the senior's notebook: <Blue:Student Dormitory: 41>"
  },
  AvgDialog_18770_Content_30 = {
    Text = "Not interested. This topic is really boring! Change it, change it."
  },
  AvgDialog_18770_Content_31 = {
    Text = "One hour later..."
  },
  AvgDialog_18770_Content_32 = {
    Text = "The pointless conversation continued until Agrippa finally steered the topic back to himself."
  },
  AvgDialog_18770_Content_33 = {
    Text = "Did you know? I now have over a thousand descendants under my command..."
  },
  AvgDialog_18770_Content_34 = {
    Text = "They can freely enter and exit the maze, gather stories from the outside world for me, and bring back unlucky souls suitable to become offspring"
  },
  AvgDialog_18770_Content_35 = {
    Text = "If it weren't for them, I would have died of boredom."
  },
  AvgDialog_18770_Content_36 = {
    Text = "You listen to her incessant complaints, and for some reason, a scene comes to mind—"
  },
  AvgDialog_18770_Content_37 = {
    Text = "The aging king leans on his cane, sinking deep into the decayed and heavy throne."
  },
  AvgDialog_18770_Content_38 = {
    Text = "His domain is boundless, and his authority is beyond question."
  },
  AvgDialog_18770_Content_39 = {
    Text = "He sent out many envoys to bring back tales from afar: emerald cat's eyes, missing elephants, and rainbows after the rain..."
  },
  AvgDialog_18770_Content_4 = {
    Text = "Stop wasting time and come play with me!"
  },
  AvgDialog_18770_Content_40 = {
    Text = "When the envoy reaches an exciting part, he joyfully waves his arms. The king, however, remains silent, like a moss-covered sculpture."
  },
  AvgDialog_18770_Content_41 = {
    Text = "He can do nothing, for he can no longer leave the throne even for a single step."
  },
  AvgDialog_18770_Content_42 = {
    Text = "Agrippa, you've heard so many stories from the outside... Is there somewhere you want to go?"
  },
  AvgDialog_18770_Content_43 = {
    Text = "The place I want to go..."
  },
  AvgDialog_18770_Content_44 = {
    Text = "<Blue:Cambrian Valley> counts as one."
  },
  AvgDialog_18770_Content_45 = {
    Text = "Agrippa responded almost without thinking."
  },
  AvgDialog_18770_Content_46 = {
    Text = "My offspring told me that the center of this maze seems to be beneath a valley called Cambrian."
  },
  AvgDialog_18770_Content_47 = {
    Text = "I've heard it's a beautiful place with lakes as clear as mirrors."
  },
  AvgDialog_18770_Content_48 = {
    Text = "Every spring, a flower called freesia blooms everywhere..."
  },
  AvgDialog_18770_Content_49 = {
    Text = "Agrippa rests his chin on his hand, gazing into the distance."
  },
  AvgDialog_18770_Content_5 = {Text = "..."},
  AvgDialog_18770_Content_50 = {
    Text = "There is also a beautiful lake in my hometown, but I have never seen it."
  },
  AvgDialog_18770_Content_51 = {
    Text = "Why not take a look?"
  },
  AvgDialog_18770_Content_52 = {
    Text = "Agrippa glanced at you arrogantly, lifting her sharp little chin."
  },
  AvgDialog_18770_Content_53 = {
    Text = "I am a Roman lady of noble birth, and a lady should not wander about freely."
  },
  AvgDialog_18770_Content_54 = {
    Text = "So you can command many slaves, yet you are not entirely free yourself."
  },
  AvgDialog_18770_Content_55 = {
    Text = "Your words pierce through reality, and the girl's face instantly falls, like a frostbitten eggplant."
  },
  AvgDialog_18770_Content_56 = {
    Text = "Back then, I was worse off than those slaves. Not to mention now..."
  },
  AvgDialog_18770_Content_6 = {
    Text = "Sorry, could you change your face before talking to me?"
  },
  AvgDialog_18770_Content_7 = {
    Text = "Tsk, so stingy!"
  },
  AvgDialog_18770_Content_8 = {
    Text = "\"William\" rolled his eyes and then disappeared into thin air with a \"bang.\""
  },
  AvgDialog_18770_Content_9 = {
    Text = "You keep your head down, poring over the dense records, trying to find a way to crack the maze."
  },
  AvgDialog_18779_Content_1 = {
    Text = "Is this... is this the embryo?"
  },
  AvgDialog_18779_Content_10 = {
    Text = [[
Is it draining energy from Miryam?!
Is it going to happen again?]]
  },
  AvgDialog_18779_Content_11 = {
    Text = [[
Useless.
It is protected by the "placenta", and the power supplied by Miryam can still repair the placenta at least three more times.]]
  },
  AvgDialog_18779_Content_12 = {
    Text = "To completely defeat it, you must directly attack its true core."
  },
  AvgDialog_18779_Content_13 = {Text = "Core?"},
  AvgDialog_18779_Content_14 = {
    Text = "A pale heart is embedded in a transparent cocoon, illuminated by the moonlight. Within the immense cocoon, \"His\" shadow is faintly visible."
  },
  AvgDialog_18779_Content_15 = {
    Text = "Is it the \"counterfeit\" itself?"
  },
  AvgDialog_18779_Content_16 = {
    Text = "Yes, but not really."
  },
  AvgDialog_18779_Content_17 = {
    Text = "Is... Murphy?"
  },
  AvgDialog_18779_Content_18 = {
    Text = "That's correct."
  },
  AvgDialog_18779_Content_19 = {
    Text = "Miryam forcibly advanced the ritual, but \"He\" was born out of lies and desires; until the stars reach Align, His existence will not be recognized by reality."
  },
  AvgDialog_18779_Content_2 = {
    Text = "It seems to be motionless."
  },
  AvgDialog_18779_Content_20 = {
    Text = "Before her birth, the core was still her."
  },
  AvgDialog_18779_Content_3 = {
    Text = "It's not over yet."
  },
  AvgDialog_18779_Content_4 = {
    Text = "The \"heart\" has stopped beating, but the low wailing carried by the sea breeze cannot be ignored."
  },
  AvgDialog_18779_Content_5 = {
    Text = "Did you hear the crying?"
  },
  AvgDialog_18779_Content_6 = {
    Text = "The waves surged as the giant cocoon, supported by Miryam, rose abruptly above the sea."
  },
  AvgDialog_18779_Content_7 = {
    Text = "Sure, just like this..."
  },
  AvgDialog_18779_Content_8 = {
    Text = "It is your right to take whatever you desire, for your birth and to punish these faithless ones..."
  },
  AvgDialog_18779_Content_9 = {
    Text = "Miryam's voice grows fainter, but the presence within the slumbering cocoon becomes more substantial."
  },
  AvgDialog_18784_Content_10 = {
    Text = "What a pity, merely losing the Silver Link has reduced you to such a state."
  },
  AvgDialog_18784_Content_11 = {
    Text = "The pus monster ignores Lotan's taunts, roaring as it charges at the enemy."
  },
  AvgDialog_18784_Content_12 = {
    Text = "<Change>Give her... to... me..."
  },
  AvgDialog_18784_Content_13 = {
    Text = "As long as I can catch that girl... As long as I can become the Twin Holy Maidens with her..."
  },
  AvgDialog_18784_Content_14 = {
    Text = "She won't be abandoned, lament her origins, or become a pawn at others' beck and call."
  },
  AvgDialog_18784_Content_17 = {
    Text = "<Change>Hand her... over... to me!"
  },
  AvgDialog_18784_Content_18 = {
    Text = "Have you lost the ability to communicate as well?"
  },
  AvgDialog_18784_Content_19 = {
    Text = [[
Since that's the case, channel your words and emotions into your sword.
Let me hear your anger!]]
  },
  AvgDialog_18784_Content_2 = {
    Text = "<BigShake:Roar—>"
  },
  AvgDialog_18784_Content_3 = {
    Text = "You haven't walked far in the dark when a sticky creature emerges from the bridge tunnel. Its massive body, dragging countless gooey blobs, suddenly drops in front of you."
  },
  AvgDialog_18784_Content_4 = {
    Text = "The monster raises its barely human upper body, looks around at you all, and fixes its gaze on Lily, madness gradually growing in its expression."
  },
  AvgDialog_18784_Content_6 = {
    Text = "Leave her... to me!"
  },
  AvgDialog_18784_Content_7 = {
    Text = "Lotan stood in front of you, proudly meeting the monster's gaze."
  },
  AvgDialog_18784_Content_8 = {
    Text = "Shackles shattered, limbs distorted and swollen; only the tangled, dirty face beneath the matted hair still reveals the identity of the body's owner."
  },
  AvgDialog_18784_Content_9 = {
    Text = "You are... Helot..."
  },
  AvgDialog_18785_Content_1 = {
    Text = "Warped reality"
  },
  AvgDialog_18785_Content_10 = {
    Text = "By the light, she saw countless black wounds of varying sizes scattered across the smooth surface of \"Mother\"."
  },
  AvgDialog_18785_Content_11 = {
    Text = "\"I'm sorry...\""
  },
  AvgDialog_18785_Content_12 = {
    Text = "Black slime surged, shattering the tranquility at the bottom of the pool."
  },
  AvgDialog_18785_Content_13 = {
    Text = "\"The 'Mother' let out a sharp wail, her tentacles thrashing about, sending something into the chick's chest.\""
  },
  AvgDialog_18785_Content_14 = {
    Text = "Slippery and cold, the soft limbs entwine her. The black pool water no longer blocks her mouth and nose but instead lifts her life like amniotic fluid."
  },
  AvgDialog_18785_Content_15 = {
    Text = [[
<Change>"I'm sorry..."
"I still... don't want to die..."]]
  },
  AvgDialog_18785_Content_16 = {
    Text = "The surface remains calm for ages; even the howling polar winds cannot ripple the viscous pool."
  },
  AvgDialog_18785_Content_17 = {
    Text = "Lady Miryam, could it be that the saintess has already...?"
  },
  AvgDialog_18785_Content_18 = {
    Text = "She was born at the last Stellar Align, a child who can \"see.\""
  },
  AvgDialog_18785_Content_19 = {
    Text = "No one in the world deserves the recognition of the divine bloodline more than her."
  },
  AvgDialog_18785_Content_2 = {
    Text = "The fledgling with broken wings fell into the black pond."
  },
  AvgDialog_18785_Content_20 = {
    Text = [[
The gaunt woman stood surrounded, at the highest point overlooking everyone.
The thin veil obscured her face; even her closest attendants couldn't discern her thoughts.]]
  },
  AvgDialog_18785_Content_21 = {Text = "Murphy..."},
  AvgDialog_18785_Content_3 = {
    Text = "The high priest's murmured prayers, both ethereal and firm, pierced through the black ooze, transforming into blades that split the fledgling's chest."
  },
  AvgDialog_18785_Content_4 = {
    Text = "Crimson liquid rises from the chest, blooming eerily on the still, black water—"
  },
  AvgDialog_18785_Content_5 = {
    Text = "She keeps sinking, with blood-stained roots, into the deepest depths, into a soft and chilling embrace."
  },
  AvgDialog_18785_Content_6 = {Text = "..."},
  AvgDialog_18785_Content_7 = {Text = "..."},
  AvgDialog_18785_Content_8 = {
    Text = [[
She saw it.
She looked up. "Mother" lowered three pairs of eye stalks to meet her gaze.]]
  },
  AvgDialog_18785_Content_9 = {
    Text = "It was a colossal crimson beast, with blood-stained areas turning transparent white. \"Mother\"emitted a faint glow, temporarily illuminating a small world."
  },
  AvgDialog_18786_Content_1 = {
    Text = "Fade-in video"
  },
  AvgDialog_18786_Content_2 = {
    Text = "Video Loop 1"
  },
  AvgDialog_18786_Content_3 = {
    Text = "Video Loop 2"
  },
  AvgDialog_18786_Content_4 = {
    Text = "Video Fade Out"
  },
  AvgDialog_18786_Content_5 = {
    Text = "That's all."
  },
  AvgDialog_18787_Content_1 = {
    Text = "But now there's something more urgent than that."
  },
  AvgDialog_18787_Content_10 = {
    Text = "This is the girl Herbert is tracking. She might have clues relevant to your investigation."
  },
  AvgDialog_18787_Content_11 = {
    Text = [[
Let's go, what are you waiting for?
Do you really enjoy spending the whole night howling with wolves in the wilderness?]]
  },
  AvgDialog_18787_Content_12 = {
    Text = "If you want to rough it out, I'm always ready to join you. But I'm afraid a delicate girl like you might not be able to handle it."
  },
  AvgDialog_18787_Content_13 = {
    Text = "Lotan patted Ramona on the back. Ramona made an expression as if she had eaten a fly, but said nothing."
  },
  AvgDialog_18787_Content_14 = {
    Text = "Lady Daffodil... Sounds like a wealthy person with a kind heart, right?"
  },
  AvgDialog_18787_Content_2 = {Text = "?"},
  AvgDialog_18787_Content_3 = {
    Text = "If you aren't planning to use the snow as a blanket, you should seriously consider where we'll stay tonight, Keeper."
  },
  AvgDialog_18787_Content_4 = {
    Text = "<Italic:Big Brother, Big Sister, have you come from a very distant place?>"
  },
  AvgDialog_18787_Content_5 = {
    Text = "A youthful voice interrupted your conversation."
  },
  AvgDialog_18787_Content_6 = {
    Text = "Who is there?"
  },
  AvgDialog_18787_Content_7 = {
    Text = "The snow on the wall reflects the bright moonlight, and in the center stands a maiden even whiter than the moonlight."
  },
  AvgDialog_18787_Content_8 = {
    Text = [[
If you can't find a place to stay, you can temporarily stay in <Blue:Lady Daffodil>'s room.
It's just around the corner.]]
  },
  AvgDialog_18787_Content_9 = {
    Text = "You give Ramona a knowing wink, and she responds with an affirmative nod."
  },
  AvgDialog_18790_Content_1 = {
    Text = "You fought your way to the bow, but before you could look out to sea, an upward surge caused the ship to tilt even further."
  },
  AvgDialog_18790_Content_2 = {
    Text = "The cargo ship rises and falls with the surging waves, and something emerges from the water—"
  },
  AvgDialog_18790_Content_3 = {Text = "Murphy!"},
  AvgDialog_18790_Content_4 = {
    Text = "The snake's head tightly clutched the girl's body, and Miryam could only pray in a hoarse and indistinct voice."
  },
  AvgDialog_18790_Content_5 = {
    Text = "Ph'nglui mglw'nafh @3..."
  },
  AvgDialog_18790_Content_6 = {
    Text = "She raised Murphy into the moonlight. Tiny, delicate black hands poured out from the girl's chest, writhing and weaving, wrapping her body in layers to form a giant black cocoon."
  },
  AvgDialog_18790_Content_7 = {
    Text = "With a muffled growl, hands and black threads use Miryam as a frame, tightly entwining the cocoon around the massive serpent's body."
  },
  AvgDialog_18790_Content_8 = {
    Text = "The cocoon's shell turns transparent from swelling, countless hands intertwine to form a throne, lifting up a pale heart."
  },
  AvgDialog_18790_Content_9 = {
    Text = "Ph'nglui mglw'nafh @1'@2 wgah'nagl fhtagn!"
  },
  AvgDialog_18792_Content_1 = {
    Text = "She's just a kid from the slums, knows nothing, and won't pose any threat to you..."
  },
  AvgDialog_18792_Content_10 = {
    Text = "So annoying, my hands are sore. Are you planning to die here today, 24?"
  },
  AvgDialog_18792_Content_11 = {
    Text = "Losing a slave as obedient as you would make me cry~"
  },
  AvgDialog_18792_Content_12 = {
    Text = "Sorry... I won't take a single step away from here."
  },
  AvgDialog_18792_Content_14 = {Text = "Snap—!"},
  AvgDialog_18792_Content_15 = {
    Text = "Soon, 24 was covered in Caro. But she didn't move, muttering the same words over and over."
  },
  AvgDialog_18792_Content_16 = {
    Text = "<Shake:Let her go...>"
  },
  AvgDialog_18792_Content_17 = {
    Text = "<Shake:Let her go...>"
  },
  AvgDialog_18792_Content_18 = {
    Text = "Come at me if you dare, you bunch of losers! Don't..."
  },
  AvgDialog_18792_Content_19 = {
    Text = "<Bold:Don't hurt my sister...>"
  },
  AvgDialog_18792_Content_2 = {Text = "Snap—!"},
  AvgDialog_18792_Content_20 = {
    Text = "Miss 24! Stop... Ugh..."
  },
  AvgDialog_18792_Content_21 = {
    Text = "<Small:Can't... move at all. Need to find a way to get the Silver Key...>"
  },
  AvgDialog_18792_Content_22 = {
    Text = "You're so foolish, so very foolish! Don't blame me for being ruthless~"
  },
  AvgDialog_18792_Content_23 = {
    Text = "Leigh, it's your turn to shine."
  },
  AvgDialog_18792_Content_3 = {
    Text = "The whip mercilessly lashed down, leaving a fierce red mark on 24's face."
  },
  AvgDialog_18792_Content_4 = {Text = "Hmm—!"},
  AvgDialog_18792_Content_5 = {
    Text = "24 stood in front of Jenkin, their thin shoulder blades trembling like butterfly wings."
  },
  AvgDialog_18792_Content_6 = {
    Text = "She managed a faint smile, but it looked more painful than crying."
  },
  AvgDialog_18792_Content_7 = {
    Text = "My lord, please have mercy... Let her go, and I will do anything..."
  },
  AvgDialog_18792_Content_8 = {Text = "Snap—!"},
  AvgDialog_18792_Content_9 = {
    Text = "Countless lashes fall like raindrops."
  },
  AvgDialog_18795_Content_1 = {
    Text = "The tip of the rapier penetrates the serpent-scale energy, piercing the giant serpent's vital point."
  },
  AvgDialog_18795_Content_10 = {
    Text = "King... My Lord... Murphy... Murphy..."
  },
  AvgDialog_18795_Content_12 = {
    Text = [[
Now... there is still room for redemption.
Return to the Order, and you will remain the revered "Divine Mother".]]
  },
  AvgDialog_18795_Content_13 = {
    Text = "Your funeral will be the grandest ceremony in the history of the Divine Realm, admired by tens of thousands... Your name will also be inscribed in the annals of history, passed down through the ages."
  },
  AvgDialog_18795_Content_14 = {
    Text = "Return to me, together we shall... execute this <Blue:blasphemer>."
  },
  AvgDialog_18795_Content_15 = {
    Text = "Execution... This vile person, disguised as my lord!"
  },
  AvgDialog_18795_Content_16 = {
    Text = "The giant snake dissipated and reformed, as Miryam's power distorted and transformed the space."
  },
  AvgDialog_18795_Content_17 = {
    Text = "Miryam! I command you to stop!"
  },
  AvgDialog_18795_Content_18 = {
    Text = "False god, counterfeit, deceiver, blasphemer... No @1@2... Not allowed to use the form of @3@4!"
  },
  AvgDialog_18795_Content_19 = {
    Text = [[
At a certain moment, the phantom above the power room solidified.
An indescribable, twisted structure rose from the ground.]]
  },
  AvgDialog_18795_Content_2 = {
    Text = "Hey, hey! Someone is about to fall!"
  },
  AvgDialog_18795_Content_20 = {
    Text = "<Change>Irreverent ones... Irreverent ones... Unrestrained and uncontrollable▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_18795_Content_21 = {
    Text = "Miryam emitted harsh, incoherent noises and clutched her neck with both hands as her body warped and elongated."
  },
  AvgDialog_18795_Content_22 = {
    Text = "Be careful! She's losing control!"
  },
  AvgDialog_18795_Content_3 = {
    Text = "You also fall amidst the roar of the giant serpent."
  },
  AvgDialog_18795_Content_4 = {
    Text = "—and then fell into a trembling, warm embrace."
  },
  AvgDialog_18795_Content_5 = {
    Text = "...%player%."
  },
  AvgDialog_18795_Content_6 = {
    Text = "Am I in heaven?"
  },
  AvgDialog_18795_Content_7 = {
    Text = "Sorry, we're still on the Sonanil. And the crisis is imminent..."
  },
  AvgDialog_18795_Content_8 = {
    Text = "<Small:Unforgivable...>"
  },
  AvgDialog_18795_Content_9 = {
    Text = "Be careful! Miryam is acting strange!"
  },
  AvgDialog_18796_Content_1 = {
    Text = "Ahem, ahem, hello everyone! Today, we'll test the transition effects of the Z1~"
  },
  AvgDialog_18796_Content_10 = {
    Text = "Suitable for quickly switching to darker scenes."
  },
  AvgDialog_18796_Content_11 = {
    Text = "Phew... I'm exhausted. There's no need to spell it out, right? After Stage 4, it's obviously time for Stage 5!"
  },
  AvgDialog_18796_Content_12 = {
    Text = "Hmm... In summary, No.5 is a highly versatile transition that works well in many situations."
  },
  AvgDialog_18796_Content_13 = {
    Text = "Alright, now for the final transition—let's welcome No. 6!"
  },
  AvgDialog_18796_Content_14 = {
    Text = "This is the longest transition ever~"
  },
  AvgDialog_18796_Content_15 = {
    Text = "That's all the transition effects. Does everyone understand?"
  },
  AvgDialog_18796_Content_16 = {
    Text = "See you next time♡"
  },
  AvgDialog_18796_Content_2 = {
    Text = "Here comes Transition 1 — Left and Right Transition~!!"
  },
  AvgDialog_18796_Content_3 = {
    Text = "Ta-da! What do you think? Isn't it magnificent!"
  },
  AvgDialog_18796_Content_4 = {
    Text = "This transition is typically used for switching between the same scenes, you know."
  },
  AvgDialog_18796_Content_5 = {
    Text = "Next is Transition #2 —"
  },
  AvgDialog_18796_Content_6 = {
    Text = "This transition is typically used to switch to a brighter scene."
  },
  AvgDialog_18796_Content_7 = {
    Text = "Then... Transition No. 3!"
  },
  AvgDialog_18796_Content_8 = {
    Text = "Transition #3 is also suitable for switching to bright scenes, but the pace will be slightly slower, hehe."
  },
  AvgDialog_18796_Content_9 = {
    Text = "Next up is—Scene 4!"
  },
  AvgDialog_18797_Content_1 = {
    Text = "Hmm... @1... Ugh..."
  },
  AvgDialog_18797_Content_10 = {
    Text = "Aren't you the \"Godking\"!"
  },
  AvgDialog_18797_Content_11 = {
    Text = "After all, as the one served by Miryam, didn't you decree the prophecy of God's resurrection?"
  },
  AvgDialog_18797_Content_12 = {Text = "You..."},
  AvgDialog_18797_Content_13 = {
    Text = "I just saw... through the link, I saw your memories"
  },
  AvgDialog_18797_Content_14 = {Text = "...Yes."},
  AvgDialog_18797_Content_15 = {
    Text = "This is the prophecy I have bestowed, but the so-called \"divine oracle\" does not exist."
  },
  AvgDialog_18797_Content_16 = {Text = "What?"},
  AvgDialog_18797_Content_17 = {
    Text = [[
Long before the flood arrived, I lost the ability to glimpse the future from the God's Dream.
I don't know where He went; He might have awakened, or He might have left.]]
  },
  AvgDialog_18797_Content_18 = {
    Text = "Then your prophecy..."
  },
  AvgDialog_18797_Content_19 = {
    Text = "Miryam is a devout believer, born for the Divine Realm and driven by My will."
  },
  AvgDialog_18797_Content_2 = {
    Text = "Murphy let out a pained groan, his mutterings fragmented."
  },
  AvgDialog_18797_Content_20 = {
    Text = "I only hoped my words would comfort her in her final moments, never expecting she would take them as gospel and seek to rebuild the Divine Realm."
  },
  AvgDialog_18797_Content_21 = {
    Text = "All of this is..."
  },
  AvgDialog_18797_Content_22 = {
    Text = "Yes, it is entirely my fault."
  },
  AvgDialog_18797_Content_23 = {
    Text = "Countdown: 60 minutes"
  },
  AvgDialog_18797_Content_3 = {
    Text = "What is this?!"
  },
  AvgDialog_18797_Content_4 = {
    Text = "Terrifying dark green marks appeared on Murphy's face, embedding deeply under her skin like plant roots."
  },
  AvgDialog_18797_Content_5 = {
    Text = "It starts blocking the host's blood flow."
  },
  AvgDialog_18797_Content_6 = {
    Text = "Isn't it said that staying away from celestial bodies would suffice?"
  },
  AvgDialog_18797_Content_7 = {
    Text = "What I mean is, she might feel less miserable."
  },
  AvgDialog_18797_Content_8 = {
    Text = "Celestial orbit achieved; there's no turning back."
  },
  AvgDialog_18797_Content_9 = {
    Text = "Is there really no solution?"
  },
  AvgDialog_18798_Content_1 = {
    Text = "Huff... Huff... Nothing above, nothing below either..."
  },
  AvgDialog_18798_Content_10 = {
    Text = "Murphy instantly lost her strength, sliding down against the ship's rail onto the deck, no longer caring about maintaining a ladylike posture."
  },
  AvgDialog_18798_Content_11 = {
    Text = "She wanted to find something to steady herself. After some fumbling, she leaned on your shoulder."
  },
  AvgDialog_18798_Content_12 = {
    Text = "Just a moment..."
  },
  AvgDialog_18798_Content_13 = {
    Text = [[
In just a few seconds, rapid yet rhythmic breathing reached his ears.
Murphy lost consciousness once again.]]
  },
  AvgDialog_18798_Content_14 = {
    Text = "She is growing weaker..."
  },
  AvgDialog_18798_Content_15 = {
    Text = "The gods I commune with hail from myriad stars. Even a mere replica is beyond human resistance."
  },
  AvgDialog_18798_Content_16 = {
    Text = "Is there no way to alleviate it?"
  },
  AvgDialog_18798_Content_17 = {
    Text = "...Take her down."
  },
  AvgDialog_18798_Content_18 = {
    Text = "Stay away from celestial bodies, and she might feel better."
  },
  AvgDialog_18798_Content_2 = {
    Text = "Where... huff... are they?"
  },
  AvgDialog_18798_Content_3 = {
    Text = "<Small:Ugh... Why is this ship so huge...>"
  },
  AvgDialog_18798_Content_4 = {
    Text = "Are you alright?"
  },
  AvgDialog_18798_Content_5 = {
    Text = "I'm perfectly fine! Cough, cough..."
  },
  AvgDialog_18798_Content_6 = {
    Text = "Murphy raised his voice to answer you but accidentally choked and began coughing violently."
  },
  AvgDialog_18798_Content_7 = {
    Text = "But I'm really tired, and my head hurts a little."
  },
  AvgDialog_18798_Content_8 = {
    Text = "While speaking, you have already sat down on the spot."
  },
  AvgDialog_18798_Content_9 = {
    Text = "Well... let's take a break, just for a moment..."
  },
  AvgDialog_18802_Content_1 = {
    Text = [[
If only I were a little stronger, if I could always resist him...
But I can't, I just can't.]]
  },
  AvgDialog_18802_Content_10 = {
    Text = "I'm sorry... I'm sorry... It's all my... It's all my fault..."
  },
  AvgDialog_18802_Content_11 = {
    Text = "I'm a useless monster. I've caused the deaths of so many people, yet I couldn't save Jenkin's sister."
  },
  AvgDialog_18802_Content_12 = {
    Text = [[
She was taken away, taken away... but I don't even know where she went...
I don't even know who is controlling us...]]
  },
  AvgDialog_18802_Content_13 = {
    Text = "Ramona knelt before Aigis, gently embracing the girl in her arms."
  },
  AvgDialog_18802_Content_14 = {
    Text = "You've done your best, Aigis. It's not your fault."
  },
  AvgDialog_18802_Content_15 = {
    Text = [[
That was the real Ripper, the one controlling you and committing these crimes. 
It was never your fault.]]
  },
  AvgDialog_18802_Content_16 = {
    Text = "The girl threw herself into Ramona's arms, sobbing uncontrollably, but never forgot to cover her eyes with her right hand."
  },
  AvgDialog_18802_Content_17 = {
    Text = "We'll find that person."
  },
  AvgDialog_18802_Content_18 = {
    Text = [[
We will find him and make him pay.
I swear to you.]]
  },
  AvgDialog_18802_Content_19 = {
    Text = "Thank you, thank you all... Thank you."
  },
  AvgDialog_18802_Content_2 = {
    Text = "Last time I tried to resist him, but... but... I just couldn't do it. Sobbing..."
  },
  AvgDialog_18802_Content_20 = {
    Text = "The golden rays of the setting sun penetrate the clock tower's massive transparent clock face, casting a glow on the girl."
  },
  AvgDialog_18802_Content_21 = {
    Text = "Aigis turned sideways, placing one hand on the glass, squinting into the warm sunlight."
  },
  AvgDialog_18802_Content_22 = {
    Text = "Today, I can see the sun..."
  },
  AvgDialog_18802_Content_24 = {
    Text = "As if invigorated by the rare sunny day, she propped herself up and wobbled over to a relatively clean piece of glass."
  },
  AvgDialog_18802_Content_25 = {
    Text = "Her blurry vision finally cleared. She gazed at the streets, some familiar, some unfamiliar. In a daze, it seemed as if someone was whispering in her ear."
  },
  AvgDialog_18802_Content_26 = {
    Text = "Look, that voice said, \"Tonight, we will definitely see a brilliant starry sky.\""
  },
  AvgDialog_18802_Content_28 = {
    Text = "The girl lowered her head, revealing a wistful smile."
  },
  AvgDialog_18802_Content_29 = {
    Text = "In the past, whenever the sun was visible, Tyog would secretly bring me up here at night."
  },
  AvgDialog_18802_Content_3 = {
    Text = "Stop it. Stop forcing me to do this."
  },
  AvgDialog_18802_Content_30 = {
    Text = "Miss Sarah never allowed us to come here; she said it was too dangerous, and we could get hurt easily. But Tyug didn't care about any of that."
  },
  AvgDialog_18802_Content_31 = {
    Text = "His eyes are excellent; he can clearly see the path, no matter how dark the place is."
  },
  AvgDialog_18802_Content_32 = {
    Text = "He, like Jenkin, is clever and brave, always knowing hidden paths and mechanisms that others don't."
  },
  AvgDialog_18802_Content_33 = {
    Text = "As long as he is with us, Miss Sarah will not find us."
  },
  AvgDialog_18802_Content_34 = {
    Text = "As long as he carries it with him, this place will always be our secret base."
  },
  AvgDialog_18802_Content_35 = {
    Text = [[
He told me that I need to connect with the stars to strengthen my magic. 
Although we can't see a single star here.]]
  },
  AvgDialog_18802_Content_36 = {
    Text = [[
At that time, he was the only one who believed in me.
He believed I could see those dark things and told me it was a witch's gift.]]
  },
  AvgDialog_18802_Content_37 = {
    Text = "Later... after that, the doctors began taking patients away, no longer treating them at the almshouse. I couldn't gather evidence or avenge Tiyoug."
  },
  AvgDialog_18802_Content_38 = {
    Text = "If I were as smart as him and as brave as Jenkin, I would have probably uncovered the truth by now."
  },
  AvgDialog_18802_Content_39 = {
    Text = "But I'm not a witch."
  },
  AvgDialog_18802_Content_4 = {
    Text = "I don't want to hurt anyone, and I don't want to kill."
  },
  AvgDialog_18802_Content_40 = {
    Text = "I'm just a coward."
  },
  AvgDialog_18802_Content_41 = {Text = "A monster."},
  AvgDialog_18802_Content_42 = {
    Text = "A... murderer."
  },
  AvgDialog_18802_Content_43 = {
    Text = [[
Do you know how many times I've been manipulated?
Do you know how much blood stains my hands?]]
  },
  AvgDialog_18802_Content_44 = {
    Text = "I'm terrified of what I'm about to become."
  },
  AvgDialog_18802_Content_46 = {
    Text = "I used to have pain in my eyes and body. But now, I feel nothing, as if I were made of stone."
  },
  AvgDialog_18802_Content_48 = {
    Text = "Damn it, where on earth did everyone go..."
  },
  AvgDialog_18802_Content_49 = {Text = "That's..."},
  AvgDialog_18802_Content_5 = {
    Text = [[
<Shake:<AvgNormalFont:No! No!
Don't let little Mike do this. He's so small. How can he... <Shake:Please...>>>]]
  },
  AvgDialog_18802_Content_50 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18802_Content_51 = {
    Text = "Suddenly, Jenkin's voice came from below the clock tower. She had somehow appeared in the courtyard."
  },
  AvgDialog_18802_Content_52 = {
    Text = "She anxiously shouted Aigis's name, stretching her arms towards the sky."
  },
  AvgDialog_18802_Content_53 = {
    Text = "The girl's small body falls away, vanishing forever from the night sky."
  },
  AvgDialog_18802_Content_54 = {
    Text = "A bird flies across the night sky, vanishing into the thick fog without a trace."
  },
  AvgDialog_18802_Content_55 = {
    Text = "Jenkin's outstretched arms merely held Aigis's empty dress, scattering square pieces of paper like snowflakes."
  },
  AvgDialog_18802_Content_56 = {
    Text = [[
Ai... Aigis...?
How... how could this happen...?]]
  },
  AvgDialog_18802_Content_57 = {
    Text = "A golden butterfly is drawn on the paper, with the creased edges carefully flattened and folded. As it falls, it carries a sweet candy-like scent."
  },
  AvgDialog_18802_Content_58 = {
    Text = "Ugh... Aigis..."
  },
  AvgDialog_18802_Content_59 = {
    Text = "A bloodstained ribbon, along with a candy wrapper, fell into the girl's hand. It swayed with the wind, gently brushing against her fingertips, much like a tender comfort offered by someone."
  },
  AvgDialog_18802_Content_6 = {
    Text = "I can't hear, I can't hear, I can't hear, I can't hear, I can't hear—"
  },
  AvgDialog_18802_Content_60 = {
    Text = "The girl blinked, and tears blurred her vision, silently caught by that vivid red."
  },
  AvgDialog_18802_Content_61 = {
    Text = "This familiar color, this familiar texture—just one silver buckle away from perfectly matching what she remembers."
  },
  AvgDialog_18802_Content_62 = {
    Text = "...Sister...?"
  },
  AvgDialog_18802_Content_7 = {
    Text = [[
Success? Did it work?
Hurry, run, but please don't tell anyone.]]
  },
  AvgDialog_18802_Content_8 = {
    Text = [[
<Shake:<AvgNormalFont:Wait, what's this?! My head, my head...
Ah... ah...!<Shake:Ahhh!!>>>]]
  },
  AvgDialog_18802_Content_9 = {
    Text = "I'm sorry... I'm so sorry..."
  },
  AvgDialog_18804_Content_1 = {
    Text = "As a dignified Keeper, you've been completely outwitted by a few ordinary kids. A year's worth of training has gone to waste. Even public school freshmen are smarter than you."
  },
  AvgDialog_18804_Content_2 = {
    Text = "You're lucky the thief was at the mission site. Otherwise, tough luck. I won't allow you to waste mission time on personal matters."
  },
  AvgDialog_18804_Content_3 = {
    Text = "It's not that bad, Doll. Give %player% a bit of confidence."
  },
  AvgDialog_18804_Content_4 = {
    Text = "Please do not interfere with the Keeper's investigation."
  },
  AvgDialog_18805_Content_1 = {
    Text = "As a dignified Keeper, you've been completely outwitted by a few ordinary kids. A year's worth of training has gone to waste. Even public school freshmen are smarter than you."
  },
  AvgDialog_18805_Content_2 = {
    Text = "You're lucky the thief was at the mission site. Otherwise, tough luck. I won't allow you to waste mission time on personal matters."
  },
  AvgDialog_18805_Content_3 = {
    Text = "It's not that bad, Doll. Give %player% a bit of confidence."
  },
  AvgDialog_18805_Content_4 = {
    Text = "Please do not interfere with the Keeper's investigation."
  },
  AvgDialog_18808_Content_1 = {
    Text = "This is a background-free dialogue test 1"
  },
  AvgDialog_18808_Content_2 = {
    Text = "This is a background-free dialogue test 2"
  },
  AvgDialog_18809_Content_1 = {
    Text = [[

Murphy didn't hesitate much; she pulled Ramona to the side and began unfastening her clothes.
As the last button on the front came undone, Ramona saw the "god" within the girl.]]
  },
  AvgDialog_18809_Content_2 = {
    Text = "A patch of transparent skin is clearly visible on the chest, pulling at the surrounding skin and muscles, causing the entire chest and abdomen to take on a grayish, decaying white hue."
  },
  AvgDialog_18809_Content_3 = {
    Text = "Such an anomaly exposed the organs in her chest; Ramona saw a young heart of pale crimson and a milky \"egg\"."
  },
  AvgDialog_18809_Content_4 = {
    Text = "Countless fine threads emerge from the \"Egg\", tightly entwining with Murphy's veins, mutually dependent."
  },
  AvgDialog_18809_Content_5 = {
    Text = "If it weren't for its presence already squeezing Murphy's heart, it would seem to blend seamlessly with the transparent chest cavity, not appearing as a foreign object."
  },
  AvgDialog_18809_Content_6 = {
    Text = "It embodies Chaos and silence, with an inverted triangular black Orison, like a bizarre artwork."
  },
  AvgDialog_18809_Content_7 = {
    Text = "Dissolution... This thing has already undergone dissolution."
  },
  AvgDialog_18809_Content_8 = {
    Text = "Have you seen enough?"
  },
  AvgDialog_18809_Content_9 = {
    Text = "Sorry, my mistake. Please put your clothes back on."
  },
  AvgDialog_18810_Content_1 = {
    Text = "Countdown: 20 minutes"
  },
  AvgDialog_18810_Content_10 = {
    Text = "Caution! Don't fall into the sea!"
  },
  AvgDialog_18810_Content_11 = {
    Text = [[
A massive serpent erupted from the sea, nearly capsizing the entire ship.
Multiple snake heads writhed and twisted, casting large, ominous shadows on the deck.]]
  },
  AvgDialog_18810_Content_12 = {
    Text = "Usurper... Impudent... Fool!"
  },
  AvgDialog_18810_Content_13 = {
    Text = "Goddess... Goddess... @3!"
  },
  AvgDialog_18810_Content_14 = {
    Text = "Oh no, it's Miryam!"
  },
  AvgDialog_18810_Content_15 = {
    Text = "Take Murphy down quickly!"
  },
  AvgDialog_18810_Content_16 = {Text = "Ah!!"},
  AvgDialog_18810_Content_17 = {
    Text = "You look back at the deck; Murphy is no longer there. A giant snake head has grabbed the girl and dragged her into the sea."
  },
  AvgDialog_18810_Content_2 = {
    Text = "Link? Does it mean she will depend on you to survive in the future?"
  },
  AvgDialog_18810_Content_3 = {
    Text = "It's only a temporary measure. We have no intention of taking Miss Celeste away from you."
  },
  AvgDialog_18810_Content_4 = {
    Text = "This is not something I can decide."
  },
  AvgDialog_18810_Content_5 = {
    Text = "Celeste, are you willing?"
  },
  AvgDialog_18810_Content_6 = {
    Text = "As if triggered by a keyword, Celeste looked up but turned her gaze to the sea behind her, and the voyage came to a halt."
  },
  AvgDialog_18810_Content_7 = {
    Text = "The ship can't move."
  },
  AvgDialog_18810_Content_8 = {
    Text = "Something has got me."
  },
  AvgDialog_18810_Content_9 = {
    Text = "Before the words were finished, the ground shook violently like never before, and the ship tilted to an inconceivable angle."
  },
  AvgDialog_18812_Content_1 = {
    Text = "Even you people... A bunch of self-centered adults."
  },
  AvgDialog_18812_Content_10 = {
    Text = "The dazzling light stung my eyes, causing uncontrollable tears."
  },
  AvgDialog_18812_Content_11 = {
    Text = "This, this is!?"
  },
  AvgDialog_18812_Content_12 = {
    Text = "The murky liquid drained away, and his eyes finally refocused on the girl."
  },
  AvgDialog_18812_Content_13 = {
    Text = "The blade sank deep into her chest, and the moonlit girl opened her eyes."
  },
  AvgDialog_18812_Content_14 = {
    Text = "The full moon, a symbol of death, looms close, yet there isn't a trace of fear on the youthful face."
  },
  AvgDialog_18812_Content_15 = {
    Text = "I... pierced it... It won't be born..."
  },
  AvgDialog_18812_Content_16 = {
    Text = "In this way..."
  },
  AvgDialog_18812_Content_17 = {
    Text = "The hand gripping the knife falls weakly, as crimson, viscous, and dark liquid flows from the blade, dripping through the fingers into the sea."
  },
  AvgDialog_18812_Content_18 = {
    Text = "Blood quickly drains from the body, leaving the skin deathly pale, yet an unusual vitality emanates from within."
  },
  AvgDialog_18812_Content_19 = {
    Text = "No... No, no, no, no, aahh—"
  },
  AvgDialog_18812_Content_2 = {
    Text = "No one has ever asked for my opinion... Hmph."
  },
  AvgDialog_18812_Content_20 = {
    Text = "Almighty God, forgive me, forgive this child, forgive Your devout believer..."
  },
  AvgDialog_18812_Content_21 = {
    Text = "Align, the time of Align is near, near..."
  },
  AvgDialog_18812_Content_22 = {
    Text = "\"The placenta\" shattered, and the \"heart\" also collapsed—countless hands burst forth from the body, crushing the girl's chest cavity."
  },
  AvgDialog_18812_Content_23 = {
    Text = "The deformed hand gripped the unrecognizable remains, overlapping, swelling, overlapping, swelling—"
  },
  AvgDialog_18812_Content_24 = {
    Text = "Ah... You heard me... You responded to me..."
  },
  AvgDialog_18812_Content_25 = {
    Text = "They pushed a deformed entity into the moonlight."
  },
  AvgDialog_18812_Content_26 = {
    Text = "My great God...!"
  },
  AvgDialog_18812_Content_3 = {
    Text = "A life bought with sacrifice... Who would want it?"
  },
  AvgDialog_18812_Content_4 = {
    Text = [[

No, the placenta is too murky.
Can I see through it with "Spirit Tracing"?]]
  },
  AvgDialog_18812_Content_5 = {
    Text = "You gripped the trembling Silver Key and sank back into the space of consciousness."
  },
  AvgDialog_18812_Content_6 = {
    Text = "In the space covered by D-slime, the spark symbolizing life and intelligence shines even more brilliantly."
  },
  AvgDialog_18812_Content_7 = {
    Text = "—That is a sacrificial blade reflecting the cold, eerie moonlight."
  },
  AvgDialog_18812_Content_8 = {Text = "—Ugh!!"},
  AvgDialog_18812_Content_9 = {
    Text = "A burst of light suddenly erupts, forcefully throwing you out of the spirit world."
  },
  AvgDialog_18813_Content_1 = {
    Text = "Next, we will test the transition effect: Slow Time Lapse"
  },
  AvgDialog_18813_Content_10 = {
    Text = "Sandstorm 2"
  },
  AvgDialog_18813_Content_11 = {
    Text = "Test Complete"
  },
  AvgDialog_18813_Content_12 = {
    Text = "Next, we'll conduct a screen effect continuous shake test"
  },
  AvgDialog_18813_Content_13 = {
    Text = "Test begins"
  },
  AvgDialog_18813_Content_16 = {
    Text = "Test Complete"
  },
  AvgDialog_18813_Content_17 = {
    Text = "Next is [Screen Effect] Silver Key Activation video test"
  },
  AvgDialog_18813_Content_18 = {
    Text = "Test begins"
  },
  AvgDialog_18813_Content_19 = {
    Text = "Test complete, but I'll start [Screen Effect] Silver Key activation effect Test"
  },
  AvgDialog_18813_Content_2 = {
    Text = "Test begins"
  },
  AvgDialog_18813_Content_20 = {
    Text = "Test begins"
  },
  AvgDialog_18813_Content_21 = {
    Text = "In Progress"
  },
  AvgDialog_18813_Content_22 = {
    Text = "Test Complete"
  },
  AvgDialog_18813_Content_23 = {
    Text = "Next, we will perform the FadeDarkRole effect test."
  },
  AvgDialog_18813_Content_26 = {Text = "End"},
  AvgDialog_18813_Content_3 = {
    Text = "Test Complete"
  },
  AvgDialog_18813_Content_4 = {
    Text = "Next up is the background transition fast time-lapse test."
  },
  AvgDialog_18813_Content_5 = {
    Text = "Test begins"
  },
  AvgDialog_18813_Content_6 = {
    Text = "Test Complete"
  },
